export type ViewType = 'dashboard' | 'pos' | 'orders' | 'logistics' | 'production' | 'sync' | 'whatsapp' | 'customers' | 'employees' | 'reports' | 'settings' | 'quality' | 'scanner' | 'inventory' | 'tickets';

export interface Product {
  id: string;
  name: string;
  price: number;
  stock: number;
  category?: 'Agua' | 'Insumos' | 'Accesorios';
}

export type GarrafonType = 'Aqua' | 'Bonafont' | 'Ciel' | 'E-Pura' | 'Generico';

export interface Customer {
  id: string;
  name: string;
  alias: string;
  phone?: string;
  specialPrice?: number;
  lat?: number;
  lng?: number;
  garrafonType?: GarrafonType;
  balance: number;
}

export interface TicketConfig {
  businessName: string;
  rfc: string;
  address: string;
  phone: string;
  footerMessage: string;
  logoUrl?: string;
  website?: string;
  socialMedia?: string;
  extraNote?: string;
  slogan?: string;
  email?: string;
}

export interface CloudConfig {
  url: string;
  apiKey: string;
  autoSync: boolean;
  lastSync?: number;
}

export interface Order {
  id: string;
  customerId: string;
  customerAlias: string;
  items: CartItem[];
  total: number;
  status: 'pendiente' | 'asignado' | 'entregado' | 'cancelado';
  vehicleId?: string;
  timestamp: number;
  priority: number;
}

export interface CartItem extends Product {
  quantity: number;
}

export type PaymentMethod = 'Efectivo' | 'Transferencia' | 'Crédito' | 'Multimodal';

export interface PaymentSplit {
  method: 'Efectivo' | 'Transferencia';
  amount: number;
}

export interface Sale {
  id: string;
  timestamp: number;
  customerId: string;
  customerAlias: string;
  items: CartItem[];
  total: number;
  paidAmount: number;
  change: number;
  paymentSplits: PaymentSplit[];
  emptyGarrafonsReturned: number;
  synced: boolean;
}

export interface QualityRecord {
  id: string;
  timestamp: number;
  type: 'Cruda' | 'Producto';
  ph: number;
  cloro: number;
  tds: number;
  dureza: number;
  color: string;
  sabor: string;
  turbiedad: string;
  employeeId: string;
}

export interface Task {
  id: string;
  employeeId: string;
  title: string;
  description?: string;
  status: 'pendiente' | 'completada';
  timestamp: number;
  date: string;
}

export interface Attendance {
  id: string;
  employeeId: string;
  timestamp: number;
  date: string;
  status: 'presente' | 'falta' | 'retardo';
}

export interface Employee {
  id: string;
  name: string;
  role: 'Repartidor' | 'Planta' | 'Administrador';
  phone: string;
  pin: string;
  permissions: ViewType[];
}

export interface Vehicle {
  id: string;
  plate: string;
  description: string;
  loadCapacity: number;
  currentLoad: number;
}

import { useState, useEffect, useCallback } from 'react';
import { Product, Customer, Sale, CartItem, Order, Employee, Vehicle, PaymentSplit, ViewType, QualityRecord, Task, Attendance, TicketConfig, CloudConfig } from '../types';
import { INITIAL_PRODUCTS, INITIAL_CUSTOMERS } from '../constants';

const DEFAULT_PERMISSIONS: ViewType[] = ['dashboard', 'pos', 'orders', 'customers', 'logistics', 'inventory', 'whatsapp', 'production', 'sync', 'reports', 'settings', 'employees', 'quality', 'scanner', 'tickets'];

const INITIAL_TICKET_CONFIG: TicketConfig = {
  businessName: 'AQUA+ FUNDADORES',
  rfc: 'AQUA900101-XXX',
  address: 'Calle del Agua #123, Col. Manantiales',
  phone: '33-1234-5678',
  footerMessage: '¡Gracias por tu preferencia! Frescura que hidrata tu vida.',
  website: 'www.aquafun.mx',
  socialMedia: '@aquafun_pro',
  extraNote: 'No hay cambios después de 24 horas.',
  logoUrl: 'data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 100 100%22><rect width=%22100%22 height=%22100%22 rx=%2225%22 fill=%22%230284c7%22/><path d=%22M50 20C50 20 30 45 30 60C30 71.0457 38.9543 80 50 80C61.0457 80 70 71.0457 70 60C70 45 50 20 50 20Z%22 fill=%22white%22/></svg>'
};

const INITIAL_CLOUD_CONFIG: CloudConfig = {
  url: '',
  apiKey: '',
  autoSync: false
};

export const useERPData = () => {
  const [products, setProducts] = useState<Product[]>(() => {
    const saved = localStorage.getItem('aqua_products');
    return saved ? JSON.parse(saved) : INITIAL_PRODUCTS;
  });

  const [customers, setCustomers] = useState<Customer[]>(() => {
    const saved = localStorage.getItem('aqua_customers');
    return saved ? JSON.parse(saved).map((c: any) => ({ ...c, balance: c.balance || 0 })) : INITIAL_CUSTOMERS;
  });

  const [ticketConfig, setTicketConfig] = useState<TicketConfig>(() => {
    const saved = localStorage.getItem('aqua_ticket_config');
    return saved ? JSON.parse(saved) : INITIAL_TICKET_CONFIG;
  });

  const [cloudConfig, setCloudConfig] = useState<CloudConfig>(() => {
    const saved = localStorage.getItem('aqua_cloud_config');
    return saved ? JSON.parse(saved) : INITIAL_CLOUD_CONFIG;
  });

  const [sales, setSales] = useState<Sale[]>(() => {
    const saved = localStorage.getItem('aqua_sales');
    return saved ? JSON.parse(saved) : [];
  });

  const [orders, setOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('aqua_orders');
    return saved ? JSON.parse(saved) : [];
  });

  const [employees, setEmployees] = useState<Employee[]>(() => {
    const saved = localStorage.getItem('aqua_employees');
    const initial = saved ? JSON.parse(saved) : [
      { id: 'admin', name: 'Gerente General', role: 'Administrador', phone: '3312345678', pin: '1234', permissions: [...DEFAULT_PERMISSIONS] }
    ];
    return initial;
  });

  // Force update admin permissions to include all new modules
  useEffect(() => {
    setEmployees(prev => prev.map(e => 
      e.role === 'Administrador' 
        ? { ...e, permissions: [...DEFAULT_PERMISSIONS] } 
        : e
    ));
  }, []);

  const [vehicles, setVehicles] = useState<Vehicle[]>(() => {
    const saved = localStorage.getItem('aqua_vehicles');
    return saved ? JSON.parse(saved) : [{ id: 'v1', plate: 'ABC-123', description: 'Nissan NP300', loadCapacity: 60, currentLoad: 0 }];
  });

  const [qualityRecords, setQualityRecords] = useState<QualityRecord[]>(() => {
    const saved = localStorage.getItem('aqua_quality');
    return saved ? JSON.parse(saved) : [];
  });

  const [tasks, setTasks] = useState<Task[]>(() => {
    const saved = localStorage.getItem('aqua_tasks');
    return saved ? JSON.parse(saved) : [];
  });

  const [attendance, setAttendance] = useState<Attendance[]>(() => {
    const saved = localStorage.getItem('aqua_attendance');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => {
    localStorage.setItem('aqua_products', JSON.stringify(products));
    localStorage.setItem('aqua_customers', JSON.stringify(customers));
    localStorage.setItem('aqua_sales', JSON.stringify(sales));
    localStorage.setItem('aqua_orders', JSON.stringify(orders));
    localStorage.setItem('aqua_employees', JSON.stringify(employees));
    localStorage.setItem('aqua_vehicles', JSON.stringify(vehicles));
    localStorage.setItem('aqua_ticket_config', JSON.stringify(ticketConfig));
    localStorage.setItem('aqua_quality', JSON.stringify(qualityRecords));
    localStorage.setItem('aqua_tasks', JSON.stringify(tasks));
    localStorage.setItem('aqua_attendance', JSON.stringify(attendance));
    localStorage.setItem('aqua_cloud_config', JSON.stringify(cloudConfig));
  }, [products, customers, sales, orders, employees, vehicles, ticketConfig, qualityRecords, tasks, attendance, cloudConfig]);

  const addSale = (
    customerId: string, 
    items: CartItem[], 
    total: number, 
    paidAmount: number, 
    splits: PaymentSplit[], 
    returnedVacios: number, 
    manualTimestamp?: number
  ) => {
    const debtAmount = Math.max(0, total - paidAmount);
    const newSale: Sale = {
      id: `TKT-${Date.now().toString().slice(-6)}`,
      timestamp: manualTimestamp || Date.now(),
      customerId,
      customerAlias: customers.find(c => c.id === customerId)?.alias || 'Anonimo',
      items,
      total,
      paidAmount,
      change: Math.max(0, paidAmount - total),
      paymentSplits: splits,
      emptyGarrafonsReturned: returnedVacios,
      synced: false
    };

    setSales(prev => [newSale, ...prev]);
    setCustomers(prev => prev.map(c => c.id === customerId ? { ...c, balance: (c.balance || 0) + debtAmount } : c));
    setProducts(prev => prev.map(p => {
      const cartItem = items.find(item => item.id === p.id);
      return cartItem ? { ...p, stock: p.stock - cartItem.quantity } : p;
    }));

    return newSale;
  };

  const syncData = useCallback((externalData: { sales: Sale[], customers: Customer[] }) => {
    if (!externalData || !externalData.sales) return false;
    let changesMade = false;

    setSales(prev => {
      const existingIds = new Set(prev.map(s => s.id));
      const newSales = externalData.sales.filter(s => !existingIds.has(s.id));
      if (newSales.length > 0) changesMade = true;
      return [...newSales, ...prev].sort((a, b) => b.timestamp - a.timestamp);
    });

    if (externalData.customers) {
      setCustomers(prev => {
        // Merge strategy: Update existing by ID if cloud version is newer? 
        // For simplicity in this P2P/Cloud model, we assume cloud serves as source of truth for new additions
        // or we merge arrays ensuring no duplicates by ID
        const existingMap = new Map(prev.map(c => [c.id, c]));
        externalData.customers.forEach(c => {
          if (!existingMap.has(c.id)) {
            existingMap.set(c.id, c);
            changesMade = true;
          } else {
             // Optional: Conflict resolution logic (e.g. higher balance wins)
          }
        });
        return Array.from(existingMap.values());
      });
    }

    return changesMade;
  }, []);

  const importCustomers = useCallback((newCustomers: Customer[]) => {
    setCustomers(prev => {
      const existingIds = new Set(prev.map(c => c.id));
      const filteredNew = newCustomers.filter(c => !existingIds.has(c.id));
      return [...prev, ...filteredNew];
    });
  }, []);

  return { 
    products, 
    saveProduct: (p: Product) => setProducts(prev => prev.find(x => x.id === p.id) ? prev.map(x => x.id === p.id ? p : x) : [...prev, p]),
    deleteProduct: (id: string) => setProducts(prev => prev.filter(p => p.id !== id)),
    customers, 
    saveCustomer: (c: Customer) => setCustomers(prev => prev.find(x => x.id === c.id) ? prev.map(x => x.id === c.id ? c : x) : [...prev, c]),
    deleteCustomer: (id: string) => setCustomers(prev => prev.filter(c => c.id !== id)),
    importCustomers,
    sales, addSale,
    orders, 
    setOrders,
    addOrder: (o: Partial<Order>) => {
      const newOrder: Order = {
        id: `ORD-${Date.now().toString().slice(-6)}`,
        timestamp: Date.now(),
        status: 'pendiente',
        priority: 1,
        items: [],
        total: 0,
        customerId: '',
        customerAlias: '',
        ...o
      } as Order;
      setOrders(prev => [newOrder, ...prev]);
    },
    updateOrder: (o: Order) => setOrders(prev => prev.map(item => item.id === o.id ? o : item)),
    employees, 
    saveEmployee: (e: Employee) => setEmployees(prev => prev.find(x => x.id === e.id) ? prev.map(x => x.id === e.id ? e : x) : [...prev, e]),
    vehicles, 
    setVehicles,
    loadVehicle: (id: string, delta: number) => setVehicles(prev => prev.map(v => v.id === id ? { ...v, currentLoad: Math.max(0, Math.min(v.loadCapacity, v.currentLoad + delta)) } : v)),
    tasks,
    addTask: (t: Partial<Task>) => {
      const newTask: Task = {
        id: `TSK-${Date.now().toString().slice(-4)}`,
        timestamp: Date.now(),
        status: 'pendiente',
        ...t
      } as Task;
      setTasks(prev => [newTask, ...prev]);
    },
    updateTaskStatus: (id: string, status: Task['status']) => setTasks(prev => prev.map(t => t.id === id ? { ...t, status } : t)),
    attendance,
    recordAttendance: (employeeId: string, status: Attendance['status']) => {
      const date = new Date().toISOString().split('T')[0];
      setAttendance(prev => {
        const filtered = prev.filter(a => !(a.employeeId === employeeId && a.date === date));
        return [{ id: `ATT-${Date.now()}`, employeeId, status, date, timestamp: Date.now() }, ...filtered];
      });
    },
    qualityRecords,
    addQualityRecord: (r: Partial<QualityRecord>) => {
      const newRecord: QualityRecord = {
        id: `QUAL-${Date.now().toString().slice(-4)}`,
        timestamp: Date.now(),
        employeeId: 'admin',
        ...r
      } as QualityRecord;
      setQualityRecords(prev => [newRecord, ...prev]);
    },
    ticketConfig, setTicketConfig,
    cloudConfig, setCloudConfig,
    syncData
  };
};

import React, { useState, useEffect } from 'react';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';

interface SyncModuleProps {
  onBack: () => void;
  onScanRequest: () => void;
  scannedId?: string;
}

type SyncStatus = 'idle' | 'syncing' | 'success' | 'error';

export const SyncModule: React.FC<SyncModuleProps> = ({ onBack, scannedId }) => {
  const { sales, customers, syncData, cloudConfig, setCloudConfig } = useERPData();
  const [status, setStatus] = useState<SyncStatus>('idle');
  const [logs, setLogs] = useState<string[]>([]);
  const [editingConfig, setEditingConfig] = useState(false);
  const [tempConfig, setTempConfig] = useState(cloudConfig);

  const addLog = (msg: string) => {
    setLogs(prev => [`[${new Date().toLocaleTimeString()}] ${msg}`, ...prev.slice(0, 4)]);
  };

  const handleSaveConfig = () => {
    // Validaciones básicas de URL de Firebase
    let url = tempConfig.url.trim();
    if (url && !url.endsWith('/')) url += '/';

    setCloudConfig({ ...tempConfig, url });
    setEditingConfig(false);
    addLog("Configuración guardada.");
  };

  const performSync = async () => {
    if (!cloudConfig.url) {
      alert("Configura primero la URL de tu base de datos (Firebase).");
      setEditingConfig(true);
      return;
    }

    setStatus('syncing');
    addLog("Iniciando conexión segura SSL...");

    try {
      // 1. PUSH: Subir datos locales
      // Usamos PUT para reemplazar nodo específico de este dispositivo o PATCH para mezclar
      // Para simplificar esta demo, asumimos una estructura plana "erp_data"
      // En producción, se usaría una estructura /sales/{id} y /customers/{id} con PATCH

      const endpoint = `${cloudConfig.url}aqua_data.json${cloudConfig.apiKey ? `?auth=${cloudConfig.apiKey}` : ''}`;

      addLog("Subiendo datos locales...");
      const uploadPayload = {
        sales: sales,
        customers: customers,
        lastUpdated: Date.now(),
        deviceUser: 'AquaPro Mobile'
      };

      // Primero obtenemos lo que hay para no sobrescribir ciegamente (Merge manual simple)
      const getResponse = await fetch(endpoint);
      if (!getResponse.ok) throw new Error(`Error conexión: ${getResponse.statusText}`);

      const cloudData = await getResponse.json();

      let mergedSales = [...sales];
      let mergedCustomers = [...customers];

      if (cloudData) {
        addLog("Descargando cambios remotos...");

        // Merge Lógica: Nube + Local
        if (cloudData.sales) {
          const localIds = new Set(sales.map(s => s.id));
          const newCloudSales = (cloudData.sales as any[]).filter((s: any) => !localIds.has(s.id));
          mergedSales = [...mergedSales, ...newCloudSales];
        }

        if (cloudData.customers) {
          // Asumimos que la nube tiene la verdad para clientes existentes o fusionamos
          const localCustMap = new Map(customers.map(c => [c.id, c]));
          (cloudData.customers as any[]).forEach((c: any) => {
             localCustMap.set(c.id, c); // Cloud gana en conflicto simple
          });
          mergedCustomers = Array.from(localCustMap.values());
        }

        // Aplicar a estado local
        syncData({ sales: mergedSales, customers: mergedCustomers });
      }

      // Subir la versión fusionada (Snapshot total para consistencia en este modelo simple)
      // Nota: En producción real usaríamos updates atómicos.
      const putResponse = await fetch(endpoint, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          sales: mergedSales,
          customers: mergedCustomers,
          lastUpdated: Date.now()
        })
      });

      if (!putResponse.ok) throw new Error("Error al escribir en nube");

      setCloudConfig(prev => ({ ...prev, lastSync: Date.now() }));
      setStatus('success');
      addLog("¡Sincronización Completada!");

    } catch (error: any) {
      console.error(error);
      setStatus('error');
      addLog(`Error: ${error.message}`);
    } finally {
      setTimeout(() => setStatus(prev => prev === 'syncing' ? 'idle' : prev), 2000);
    }
  };

  // Auto-sync effect
  useEffect(() => {
    if (cloudConfig.autoSync && cloudConfig.url && status === 'idle') {
      const timer = setInterval(() => {
        // Sync cada 5 minutos si está en auto
        const minsSince = cloudConfig.lastSync ? (Date.now() - cloudConfig.lastSync) / 60000 : 999;
        if (minsSince > 5) {
          performSync();
        }
      }, 60000);
      return () => clearInterval(timer);
    }
  }, [cloudConfig, status]);

  if (editingConfig) {
    return (
      <div className="h-full bg-slate-50 animate-fadeIn pb-24 overflow-y-auto">
        <ModuleHeader title="Configurar Nube" onBack={() => setEditingConfig(false)} />
        <div className="px-6 space-y-6">
          <div className="bg-white p-6 rounded-[2rem] shadow-lg border border-indigo-100">
             <div className="flex items-center gap-3 mb-4">
                <i className="fas fa-fire text-amber-500 text-2xl"></i>
                <h3 className="font-black text-sky-900">Firebase Realtime DB</h3>
             </div>
             <p className="text-xs text-slate-500 mb-6 leading-relaxed">
               Conecta tu ERP a una base de datos Firebase para sincronización en tiempo real a través de internet (sin necesidad de estar en la misma red Wi-Fi).
             </p>

             <div className="space-y-4">
               <div>
                 <label className="text-[10px] font-black uppercase text-sky-400 ml-2">URL de la Base de Datos</label>
                 <input 
                   type="url" 
                   placeholder="https://mi-proyecto.firebaseio.com/" 
                   className="w-full bg-slate-50 p-4 rounded-2xl outline-none font-bold text-sky-900 focus:ring-2 ring-indigo-300 transition-all text-xs"
                   value={tempConfig.url}
                   onChange={e => setTempConfig({...tempConfig, url: e.target.value})}
                 />
                 <p className="text-[9px] text-slate-400 mt-1 ml-2">Copia esto desde la consola de Firebase {'>'} Realtime Database.</p>
               </div>

               <div>
                 <label className="text-[10px] font-black uppercase text-sky-400 ml-2">Secreto de Base de Datos (Auth)</label>
                 <input 
                   type="password" 
                   placeholder="Token de secreto..." 
                   className="w-full bg-slate-50 p-4 rounded-2xl outline-none font-bold text-sky-900 focus:ring-2 ring-indigo-300 transition-all text-xs"
                   value={tempConfig.apiKey}
                   onChange={e => setTempConfig({...tempConfig, apiKey: e.target.value})}
                 />
                 <p className="text-[9px] text-slate-400 mt-1 ml-2">Configuración del Proyecto {'>'} Cuentas de servicio {'>'} Secretos.</p>
               </div>

               <div className="flex items-center gap-3 bg-indigo-50 p-4 rounded-2xl">
                 <div 
                   onClick={() => setTempConfig({...tempConfig, autoSync: !tempConfig.autoSync})}
                   className={`w-12 h-7 rounded-full p-1 transition-colors cursor-pointer ${tempConfig.autoSync ? 'bg-indigo-500' : 'bg-slate-300'}`}
                 >
                   <div className={`w-5 h-5 bg-white rounded-full shadow-sm transition-transform ${tempConfig.autoSync ? 'translate-x-5' : ''}`}></div>
                 </div>
                 <span className="text-xs font-bold text-indigo-900">Sincronización Automática (5 min)</span>
               </div>
             </div>
          </div>
          <ActionButton onClick={handleSaveConfig}>Guardar Conexión</ActionButton>
        </div>
      </div>
    );
  }

  return (
    <div className="h-full bg-slate-900 text-white flex flex-col animate-fadeIn overflow-hidden pb-24">
      <div className="px-6 pt-8 pb-4 flex items-center justify-between">
        <div className="flex items-center gap-4">
          <button onClick={onBack} className="w-12 h-12 bg-white/10 rounded-2xl flex items-center justify-center active:scale-90 transition-transform">
            <i className="fas fa-arrow-left"></i>
          </button>
          <div>
            <h2 className="text-xl font-black tracking-tight">Aqua Cloud</h2>
            <div className="flex items-center gap-2">
               <div className={`w-2 h-2 rounded-full ${cloudConfig.url ? 'bg-emerald-400' : 'bg-red-500'}`}></div>
               <span className="text-[10px] font-bold uppercase opacity-70">{cloudConfig.url ? 'Configurado' : 'Sin Conexión'}</span>
            </div>
          </div>
        </div>
        <button onClick={() => setEditingConfig(true)} className="w-10 h-10 bg-white/10 rounded-xl flex items-center justify-center text-sm active:bg-white/20">
          <i className="fas fa-gear"></i>
        </button>
      </div>

      <div className="flex-1 overflow-y-auto px-6 space-y-8 no-scrollbar pb-10 flex flex-col justify-center">

        <div className="relative">
           {/* Status Ring */}
           <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-64 h-64 rounded-full border-4 border-indigo-500/20"></div>
           <div className={`absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-64 h-64 rounded-full border-t-4 border-indigo-500 transition-all duration-1000 ${status === 'syncing' ? 'animate-spin' : ''}`}></div>

           <div className="flex flex-col items-center justify-center relative z-10">
              <div className={`w-32 h-32 rounded-full flex items-center justify-center text-5xl shadow-[0_0_50px_rgba(99,102,241,0.3)] transition-all ${status === 'syncing' ? 'bg-indigo-600 scale-110' : status === 'success' ? 'bg-emerald-500' : status === 'error' ? 'bg-red-500' : 'bg-slate-800 border border-slate-700'}`}>
                 <i className={`fas ${status === 'syncing' ? 'fa-rotate animate-spin' : status === 'success' ? 'fa-check' : status === 'error' ? 'fa-triangle-exclamation' : 'fa-cloud'}`}></i>
              </div>

              <h3 className="text-2xl font-black mt-6 mb-1">
                {status === 'syncing' ? 'Sincronizando...' : status === 'success' ? 'Todo al día' : 'Nube Aqua+'}
              </h3>

              {cloudConfig.lastSync ? (
                <p className="text-xs font-mono opacity-50 bg-black/20 px-3 py-1 rounded-full">
                  Última vez: {new Date(cloudConfig.lastSync).toLocaleTimeString()}
                </p>
              ) : (
                <p className="text-xs font-bold opacity-50">Nunca sincronizado</p>
              )}
           </div>
        </div>

        <div className="space-y-4">
           <button 
             onClick={performSync}
             disabled={status === 'syncing'}
             className="w-full bg-white text-indigo-900 py-6 rounded-[2.5rem] font-black uppercase text-sm tracking-widest shadow-2xl shadow-indigo-500/20 active:scale-95 transition-all disabled:opacity-50 flex items-center justify-center gap-3"
           >
             {status === 'syncing' ? 'Procesando...' : 'Sincronizar Ahora'}
             {!status.includes('sync') && <i className="fas fa-arrow-right-arrow-left"></i>}
           </button>

           <div className="grid grid-cols-2 gap-4 text-center">
              <div className="bg-white/5 p-4 rounded-3xl border border-white/5">
                 <p className="text-[10px] font-black uppercase opacity-40 mb-1">Ventas Locales</p>
                 <p className="text-xl font-black">{sales.length}</p>
              </div>
