        content = content.replace('ext {', "ext {\n    capacitorVersion = '6.0.0'");
        fs.writeFileSync(variablesPath, content);
        success("variables.gradle reparado (capacitorVersion inyectado).");
      } else {
        // Si el archivo existe pero no tiene ext block, lo sobrescribimos con uno default seguro
        const defaultContent = `ext {
    minSdkVersion = 22
    compileSdkVersion = 34
    targetSdkVersion = 34
    androidxAppCompatVersion = '1.6.1'
    androidxCoreVersion = '1.10.1'
    androidxMaterialVersion = '1.9.0'
    junitVersion = '4.13.2'
    androidxJunitVersion = '1.1.5'
    androidxEspressoCoreVersion = '3.5.1'
    cordovaAndroidVersion = '10.1.1'
    capacitorVersion = '6.0.0'
}`;
        fs.writeFileSync(variablesPath, defaultContent);
        success("variables.gradle regenerado por formato inválido.");
      }
    } else {
      success("variables.gradle parece correcto.");
    }
  } else {
    log("variables.gradle no encontrado. Generando uno nuevo...");
    const defaultContent = `ext {
    minSdkVersion = 22
    compileSdkVersion = 34
    targetSdkVersion = 34
    androidxAppCompatVersion = '1.6.1'
    androidxCoreVersion = '1.10.1'
    androidxMaterialVersion = '1.9.0'
    junitVersion = '4.13.2'
    androidxJunitVersion = '1.1.5'
    androidxEspressoCoreVersion = '3.5.1'
    cordovaAndroidVersion = '10.1.1'
    capacitorVersion = '6.0.0'
}`;
    fs.writeFileSync(variablesPath, defaultContent);
    success("variables.gradle creado exitosamente.");
  }
} catch (e) {
  error("Error procesando variables.gradle: " + e.message);
}

// 1. Modificar android/build.gradle (Nivel Proyecto)
const projectGradlePath = path.join(androidDir, 'build.gradle');
