      const regex = /(buildscript\s*\{[\s\S]*?dependencies\s*\{)/;
      if (regex.test(content)) {
        content = content.replace(regex, '$1\n        classpath "com.google.gms:google-services:4.4.1"');
        fs.writeFileSync(projectGradlePath, content);
        success("Classpath añadido correctamente.");
      } else {
        log("No se pudo inyectar classpath automáticamente. Estructura no reconocida.");
      }
    } else {
