import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const rootDir = process.cwd();
const androidDir = path.join(rootDir, 'android');
const appDir = path.join(androidDir, 'app');

function log(msg) { console.log(`\x1b[36m[Android Setup]\x1b[0m ${msg}`); }
function error(msg) { console.error(`\x1b[31m[Error]\x1b[0m ${msg}`); }
function success(msg) { console.log(`\x1b[32m[Success]\x1b[0m ${msg}`); }

log("Iniciando reparación del entorno Android...");

if (!fs.existsSync(androidDir)) {
  error("No se encontró la carpeta 'android'. Ejecuta 'npx cap add android' primero.");
  process.exit(1);
}

// --- PASO 1: REPARAR variables.gradle (La causa del error capacitorVersion=null) ---
const variablesPath = path.join(androidDir, 'variables.gradle');
const correctVariablesContent = `ext {
    minSdkVersion = 22
    compileSdkVersion = 34
    targetSdkVersion = 34
    androidxAppCompatVersion = '1.6.1'
    androidxCoreVersion = '1.10.1'
    androidxMaterialVersion = '1.10.0'
    junitVersion = '4.13.2'
    androidxJunitVersion = '1.1.5'
    androidxEspressoCoreVersion = '3.5.1'
    cordovaAndroidVersion = '10.1.1'
    capacitorVersion = '6.0.0'
}`;

try {
  let needsRewrite = false;

  if (!fs.existsSync(variablesPath)) {
    log("variables.gradle no existe. Creándolo...");
    needsRewrite = true;
  } else {
    const currentContent = fs.readFileSync(variablesPath, 'utf8');
    // Verificamos si falta la variable crítica o si el archivo está malformado
    if (!currentContent.includes('capacitorVersion') || !currentContent.includes('compileSdkVersion')) {
      log("variables.gradle está incompleto o dañado. Regenerando...");
      needsRewrite = true;
    }
  }

  if (needsRewrite) {
    fs.writeFileSync(variablesPath, correctVariablesContent);
    success("variables.gradle ha sido restaurado correctamente.");
  } else {
    success("variables.gradle ya está correcto.");
  }
} catch (e) {
  error("Error manipulando variables.gradle: " + e.message);
}

// --- PASO 2: VINCULAR variables.gradle EN EL PROYECTO ---
const projectGradlePath = path.join(androidDir, 'build.gradle');
try {
  if (fs.existsSync(projectGradlePath)) {
    let content = fs.readFileSync(projectGradlePath, 'utf8');
    let modified = false;

    // 1. Asegurar que se aplica variables.gradle
    if (!content.includes("apply from: 'variables.gradle'") && !content.includes('apply from: "variables.gradle"')) {
        log("Vinculando variables.gradle en build.gradle...");
        // Lo insertamos al inicio
        content = "apply from: 'variables.gradle'\n" + content;
        modified = true;
    }

    // 2. Asegurar classpath de Google Services (Firebase)
    if (!content.includes('com.google.gms:google-services')) {
      log("Añadiendo classpath de Google Services...");
      const regex = /(dependencies\s*\{)/; // Busca el bloque dependencies dentro de buildscript
      if (regex.test(content)) {
        // Simple inyección si no existe ya
        content = content.replace(regex, '$1\n        classpath "com.google.gms:google-services:4.4.1"');
        modified = true;
      }
    }

    if (modified) {
      fs.writeFileSync(projectGradlePath, content);
      success("android/build.gradle actualizado.");
    } else {
      success("android/build.gradle ya está configurado correctamente.");
    }
  }
} catch (e) {
  error("Error en android/build.gradle: " + e.message);
}

// --- PASO 3: CONFIGURAR NIVEL DE APP (android/app/build.gradle) ---
const appGradlePath = path.join(appDir, 'build.gradle');
try {
  if (fs.existsSync(appGradlePath)) {
    let content = fs.readFileSync(appGradlePath, 'utf8');
    let modified = false;

    // 1. Plugin de Google Services
    if (!content.includes('com.google.gms.google-services')) {
      log("Activando plugin de Firebase en app...");
      if (content.includes("apply plugin: 'com.android.application'")) {
        content = content.replace(
          "apply plugin: 'com.android.application'", 
          "apply plugin: 'com.android.application'\napply plugin: 'com.google.gms.google-services'"
        );
        modified = true;
      }
    }

    // 2. Dependencias de Firebase
    if (!content.includes('firebase-bom')) {
      log("Añadiendo dependencias de Firebase BOM...");
      const depRegex = /(dependencies\s*\{)/;
      if (depRegex.test(content)) {
        content = content.replace(depRegex, '$1\n    implementation platform("com.google.firebase:firebase-bom:32.8.0")\n    implementation "com.google.firebase:firebase-analytics"');
        modified = true;
      }
    }

    if (modified) {
      fs.writeFileSync(appGradlePath, content);
      success("android/app/build.gradle actualizado.");
    } else {
      success("android/app/build.gradle ya tiene Firebase.");
    }
  }
} catch (e) {
  error("Error en android/app/build.gradle: " + e.message);
}

// --- PASO 4: VERIFICAR JSON ---
const jsonPath = path.join(appDir, 'google-services.json');
if (!fs.existsSync(jsonPath)) {
  console.log("\n\x1b[33m⚠️  ALERTA:\x1b[0m Falta 'android/app/google-services.json'.");
  console.log("   La app compilará, pero Firebase fallará en tiempo de ejecución.");
} else {
  success("google-services.json presente.");
}

// --- PASO 5: SINCRONIZAR JDK (SOLUCIÓN MULTIPLE DAEMONS) ---
log("Sincronizando configuración de JDK...");
const gradlePropertiesPath = path.join(androidDir, 'gradle.properties');
const javaHome = process.env.JAVA_HOME;

// Configuración base recomendada para mejorar rendimiento
const baseJvmArgs = "-Xmx4096m -XX:MaxMetaspaceSize=1024m -Dfile.encoding=UTF-8";

try {
  let propContent = "";
  if (fs.existsSync(gradlePropertiesPath)) {
    propContent = fs.readFileSync(gradlePropertiesPath, 'utf8');
  } else {
    log("Creando gradle.properties...");
  }

  let updated = false;

  // 1. Asegurar JVM Args
  if (!propContent.includes("org.gradle.jvmargs")) {
    propContent += `\norg.gradle.jvmargs=${baseJvmArgs}\n`;
    updated = true;
  }

  // 2. Forzar JAVA_HOME si existe en el entorno
  if (javaHome) {
    // Normalizar ruta para Gradle (barras normales, sin espacios conflictivos si es posible)
    const normalizedJavaHome = javaHome.replace(/\\/g, '/');

    if (propContent.includes("org.gradle.java.home")) {
      const currentVal = propContent.match(/org\.gradle\.java\.home=(.*)/)?.[1];
      if (currentVal !== normalizedJavaHome) {
        propContent = propContent.replace(/org\.gradle\.java\.home=.*/g, `org.gradle.java.home=${normalizedJavaHome}`);
        updated = true;
        log(`Actualizando Gradle JDK a: ${normalizedJavaHome}`);
      }
    } else {
      propContent += `\norg.gradle.java.home=${normalizedJavaHome}\n`;
      updated = true;
      log(`Fijando Gradle JDK a: ${normalizedJavaHome}`);
    }
  } else {
    log("\x1b[33m[Warn]\x1b[0m JAVA_HOME no definido. Se usará el JDK por defecto de Android Studio.");
  }

  if (updated) {
    fs.writeFileSync(gradlePropertiesPath, propContent);
    success("gradle.properties optimizado para coincidir con el sistema.");
  } else {
    success("gradle.properties ya está sincronizado.");
  }

} catch (e) {
  error("Error configurando gradle.properties: " + e.message);
}

console.log("\n\x1b[32m✅ REPARACIÓN COMPLETADA.\x1b[0m");
console.log("👉 Vuelve a intentar compilar con 'npm run build' o 'npx cap run android'.");

