               )}
            </div>

            <div className="space-y-3">
              <label className="text-[10px] font-black uppercase text-sky-400 ml-3 block">Tipo de Garrafón Preferido</label>
              <div className="grid grid-cols-2 gap-3">
                {GARRAFON_TYPES.map(g => (
                  <button 
                    key={g.type}
