import React, { useState } from 'react';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';
import { Product, CartItem, PaymentSplit, Sale } from '../types';

export const TicketModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const { customers, products, addSale, sales, ticketConfig } = useERPData();
  const [activeTab, setActiveTab] = useState<'create' | 'history'>('create');

  // State for Create
  const [manualDate, setManualDate] = useState<string>(() => {
    // Default to current time but in local ISO format for input
    const d = new Date();
    const offset = d.getTimezoneOffset() * 60000;
    return new Date(d.getTime() - offset).toISOString().slice(0, 16);
  });
  const [selectedCustomerId, setSelectedCustomerId] = useState<string>('');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [searchCustomer, setSearchCustomer] = useState('');

  // Modal de éxito
  const [showSuccessModal, setShowSuccessModal] = useState<Sale | null>(null);

  const customer = customers.find(c => c.id === selectedCustomerId);
  const total = cart.reduce((sum, item) => {
    const price = (customer?.specialPrice && item.id === '1') ? customer.specialPrice : item.price;
    return sum + (price * item.quantity);
  }, 0);

  // --- FUNCIONES DE TICKET Y WHATSAPP (Reutilizadas de POS) ---
  const generateTicketPDF = (sale: Sale) => {
    const qrData = btoa(`AQUA-PRO-SECURE|${JSON.stringify({ id: sale.id, total: sale.total })}`);
    const ticketHtml = `
      <div style="font-family: 'Courier New', Courier, monospace; padding: 20px; text-align: center; width: 300px; margin: auto; color: #000; background: #fff; line-height: 1.4;">
        ${ticketConfig.logoUrl ? `<img src="${ticketConfig.logoUrl}" style="width: 100px; height: 100px; object-fit: contain; margin-bottom: 15px;"/>` : ''}

        <h2 style="margin: 0; font-size: 18px; text-transform: uppercase; font-weight: 900;">${ticketConfig.businessName}</h2>
        ${ticketConfig.slogan ? `<p style="font-size: 10px; font-style: italic; margin: 4px 0 0 0; color: #444;">"${ticketConfig.slogan}"</p>` : ''}

        <div style="margin: 10px 0; font-size: 10px; border-bottom: 2px solid #000; padding-bottom: 10px;">
          <p style="margin: 2px 0;">RFC: ${ticketConfig.rfc}</p>
          <p style="margin: 2px 0;">${ticketConfig.address}</p>
          <p style="margin: 2px 0;">TEL: ${ticketConfig.phone}</p>
          ${ticketConfig.email ? `<p style="margin: 2px 0;">${ticketConfig.email}</p>` : ''}
          ${ticketConfig.website ? `<p style="margin: 2px 0;">${ticketConfig.website}</p>` : ''}
        </div>

        <div style="text-align: left; font-size: 11px; margin-bottom: 10px;">
          <p style="margin: 2px 0;">FOLIO: <b>${sale.id}</b></p>
          <p style="margin: 2px 0;">FECHA: ${new Date(sale.timestamp).toLocaleString()}</p>
          <p style="margin: 2px 0;">CLIENTE: ${sale.customerAlias.toUpperCase()}</p>
        </div>

        <table style="width: 100%; font-size: 11px; border-collapse: collapse; margin-bottom: 10px;">
          <thead>
            <tr style="border-bottom: 1px dashed #000;">
              <th style="text-align: left; padding: 4px 0;">CANT</th>
              <th style="text-align: left; padding: 4px 0;">CONCEPTO</th>
              <th style="text-align: right; padding: 4px 0;">IMP</th>
            </tr>
          </thead>
          <tbody>
            ${sale.items.map(i => `
              <tr>
                <td style="text-align: left; vertical-align: top; padding: 4px 0;">${i.quantity}</td>
                <td style="text-align: left; vertical-align: top; padding: 4px 0;">${i.name.slice(0, 20)}</td>
                <td style="text-align: right; vertical-align: top; padding: 4px 0;">$${(i.quantity * i.price).toFixed(2)}</td>
              </tr>
            `).join('')}
          </tbody>
        </table>

        <div style="border-top: 2px solid #000; padding-top: 10px; text-align: right; font-size: 13px; font-weight: 900;">
          <p style="margin: 4px 0;">TOTAL: $${sale.total.toFixed(2)}</p>
        </div>

        <div style="margin: 20px 0; border-top: 1px dashed #000; padding-top: 10px;">
          <p style="font-size: 11px; font-weight: bold; margin: 0 0 5px 0;">${ticketConfig.footerMessage}</p>
          ${ticketConfig.extraNote ? `<p style="font-size: 9px; font-style: italic; margin: 0;">* ${ticketConfig.extraNote}</p>` : ''}
        </div>

        <div style="margin-top: 15px;">
          <img src="https://api.qrserver.com/v1/create-qr-code/?size=120x120&data=${encodeURIComponent(qrData)}" style="width: 120px; height: 120px;"/>
          <p style="font-size: 8px; margin-top: 8px; color: #555; text-transform: uppercase; letter-spacing: 1px;">Escanea para validar autenticidad</p>
        </div>
      </div>
    `;
    const win = window.open('', '_blank');
    if (win) {
      win.document.write(ticketHtml);
      win.document.close();
      win.print();
    }
  };

  const handleSendWhatsApp = (sale: Sale) => {
    // Buscar el cliente actual en la base de datos para obtener su teléfono, 
    // ya que 'sale' podría tener datos históricos si el cliente cambió.
    const currentCustomer = customers.find(c => c.id === sale.customerId);
    const phone = currentCustomer?.phone?.replace(/\D/g, '');

    if (!phone) return alert("El cliente no tiene teléfono registrado.");

    const itemsText = sale.items.map(i => `• ${i.quantity}x ${i.name}`).join('%0A');
    const msg = `¡Hola ${sale.customerAlias}!%0A%0A*${ticketConfig.businessName}*%0AGracias por tu compra.%0A%0A*Detalles de tu pedido:*%0A${itemsText}%0A%0A*Total:* $${sale.total.toFixed(2)}%0A*Ticket:* ${sale.id}%0A%0A_Este es un comprobante digital._`;
    window.open(`https://wa.me/52${phone}?text=${msg}`, '_blank');
  };

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === product.id);
      if (existing) return prev.map(i => i.id === product.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.filter(i => i.id !== id));
  };

  const handleCreateTicket = () => {
    if (!customer || cart.length === 0 || !manualDate) {
      alert("Faltan datos (Cliente, Productos o Fecha).");
      return;
    }

    const timestamp = new Date(manualDate).getTime();
    if (isNaN(timestamp)) {
      alert("Fecha inválida.");
      return;
    }

    // Default payment to cash for admin back-entry
    const splits: PaymentSplit[] = [{ method: 'Efectivo', amount: total }];

    const newSale = addSale(
      customer.id, 
      cart, 
      total, 
      total, // Fully paid by default for history logs
      splits, 
      0, // No returns tracked here
      timestamp // CRITICAL: The manual timestamp
    );

    // Mostrar modal en lugar de solo alertar
    setShowSuccessModal(newSale);

    // Limpiar formulario
    setCart([]);
    setSelectedCustomerId('');
    setSearchCustomer('');
  };

  return (
    <div className="h-full bg-slate-50 flex flex-col animate-fadeIn overflow-hidden pb-24 relative">
      <ModuleHeader title="Gestión de Tickets" onBack={onBack} />

      <div className="px-6 flex gap-2 mb-4 shrink-0">
        <button onClick={() => setActiveTab('create')} className={`flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'create' ? 'bg-slate-700 text-white shadow-lg' : 'bg-white text-slate-400'}`}>Emitir Retroactivo</button>
        <button onClick={() => setActiveTab('history')} className={`flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'history' ? 'bg-slate-700 text-white shadow-lg' : 'bg-white text-slate-400'}`}>Últimos Emitidos</button>
      </div>

      <div className="flex-1 overflow-y-auto px-6 space-y-6 no-scrollbar pb-10">

        {activeTab === 'create' && (
          <div className="space-y-6">
            <RoundedCard className="bg-slate-800 text-white border-none">
              <div className="flex items-center gap-3 mb-4">
                 <i className="fas fa-clock text-rose-400 text-xl"></i>
                 <h3 className="font-black uppercase text-sm">Fecha de Emisión</h3>
              </div>
              <p className="text-[10px] text-slate-400 mb-2">Selecciona la fecha y hora exacta que aparecerá en el ticket.</p>
              <input 
                type="datetime-local" 
                value={manualDate}
                onChange={(e) => setManualDate(e.target.value)}
                className="w-full bg-slate-700 text-white p-4 rounded-2xl outline-none font-bold text-lg border border-slate-600 focus:border-rose-400 transition-colors"
              />
            </RoundedCard>

            <section>
              <h4 className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2 px-2">Cliente</h4>
              <div className="relative">
                <input 
                  type="text" 
                  placeholder="Buscar cliente..." 
                  value={searchCustomer}
                  onChange={e => setSearchCustomer(e.target.value)}
                  className="w-full bg-white p-4 rounded-[1.5rem] shadow-sm font-bold text-slate-800 outline-none"
                />
                {searchCustomer && !selectedCustomerId && (
                  <div className="absolute top-full left-0 right-0 bg-white z-20 shadow-xl rounded-xl mt-2 max-h-40 overflow-y-auto border border-slate-100">
                    {customers.filter(c => c.alias.toLowerCase().includes(searchCustomer.toLowerCase())).map(c => (
                      <button 
                        key={c.id} 
                        onClick={() => { setSelectedCustomerId(c.id); setSearchCustomer(c.alias); }}
                        className="w-full text-left p-3 border-b border-slate-50 font-bold text-xs text-slate-600 hover:bg-slate-50"
                      >
                        {c.alias}
                      </button>
                    ))}
                  </div>
                )}
                {customer && (
                   <div className="mt-2 bg-emerald-50 text-emerald-600 px-4 py-2 rounded-xl text-xs font-black uppercase flex justify-between items-center border border-emerald-100">
                     <span>{customer.alias}</span>
                     <button onClick={() => { setSelectedCustomerId(''); setSearchCustomer(''); }}><i className="fas fa-times"></i></button>
                   </div>
                )}
              </div>
            </section>

            <section>
               <h4 className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2 px-2">Productos</h4>
               <div className="grid grid-cols-2 gap-2">
                 {products.map(p => (
                   <button 
                    key={p.id} 
                    onClick={() => addToCart(p)}
                    className="bg-white p-3 rounded-xl shadow-sm text-left active:scale-95 transition-transform border border-slate-50"
                   >
                     <p className="text-[9px] font-black uppercase text-slate-800">{p.name}</p>
                     <p className="text-xs font-bold text-slate-500">${p.price}</p>
                   </button>
                 ))}
               </div>
            </section>

            {cart.length > 0 && (
              <div className="bg-white p-5 rounded-[2rem] shadow-lg border border-slate-100">
                 <h4 className="text-xs font-black uppercase text-slate-800 mb-3 border-b pb-2">Resumen</h4>
                 {cart.map(i => (
                   <div key={i.id} className="flex justify-between items-center mb-2 text-xs">
                      <span className="font-bold text-slate-600">{i.quantity}x {i.name}</span>
                      <div className="flex items-center gap-3">
                         <span className="font-black text-slate-900">${(i.quantity * i.price)}</span>
                         <button onClick={() => removeFromCart(i.id)} className="text-rose-400"><i className="fas fa-trash"></i></button>
                      </div>
                   </div>
                 ))}
                 <div className="mt-4 pt-2 border-t flex justify-between items-center">
                    <span className="font-black text-slate-800 text-lg">TOTAL</span>
                    <span className="font-black text-slate-900 text-2xl">${total.toFixed(2)}</span>
                 </div>
                 <div className="mt-6">
                   <ActionButton onClick={handleCreateTicket} variant="primary">Guardar Ticket</ActionButton>
                 </div>
              </div>
            )}
          </div>
        )}

        {activeTab === 'history' && (
          <div className="space-y-4">
             {sales.length === 0 ? (
               <p className="text-center text-slate-400 text-xs py-10">No hay tickets registrados.</p>
             ) : (
               sales.slice(0, 20).map(s => (
                 <div key={s.id} className="bg-white p-5 rounded-[1.5rem] shadow-sm border border-slate-100">
                    <div className="flex justify-between items-center mb-4">
                      <div>
                         <div className="flex items-center gap-2">
                            <span className="bg-slate-100 text-slate-600 text-[8px] font-black px-2 py-0.5 rounded-full">{s.id}</span>
                            <span className="text-xs font-black text-slate-800">{s.customerAlias}</span>
                         </div>
                         <p className="text-[10px] text-slate-400 font-bold mt-1">
                           {new Date(s.timestamp).toLocaleDateString()} {new Date(s.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                         </p>
                      </div>
                      <span className="text-xl font-black text-slate-700">${s.total}</span>
                    </div>

                    <div className="flex gap-2">
                      <button 
                        onClick={() => generateTicketPDF(s)} 
                        className="flex-1 bg-slate-50 text-slate-600 py-2 rounded-xl text-[9px] font-black uppercase flex items-center justify-center gap-2 active:bg-slate-200 transition-colors"
                      >
                        <i className="fas fa-print"></i> Ticket
                      </button>
                      <button 
                        onClick={() => handleSendWhatsApp(s)} 
                        className="flex-1 bg-emerald-50 text-emerald-600 py-2 rounded-xl text-[9px] font-black uppercase flex items-center justify-center gap-2 active:bg-emerald-100 transition-colors"
                      >
                        <i className="fab fa-whatsapp"></i> Enviar
                      </button>
                    </div>
                 </div>
               ))
             )}
          </div>
        )}
      </div>

      {/* Modal de Éxito al Crear */}
      {showSuccessModal && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[100] flex items-center justify-center p-8 animate-fadeIn">
          <div className="bg-white w-full max-w-sm rounded-[3rem] p-8 text-center shadow-2xl">
            <div className="w-20 h-20 bg-emerald-100 text-emerald-500 rounded-full flex items-center justify-center mx-auto mb-6">
              <i className="fas fa-check-circle text-4xl"></i>
            </div>
            <h3 className="text-2xl font-black text-slate-900 mb-2">Ticket Generado</h3>
            <p className="text-slate-400 text-xs font-bold mb-8 uppercase">El ticket retroactivo se ha guardado correctamente.</p>

            <div className="space-y-3">
              <button 
                onClick={() => generateTicketPDF(showSuccessModal)}
                className="w-full bg-slate-800 text-white py-5 rounded-[2rem] font-black uppercase text-[10px] tracking-widest flex items-center justify-center gap-3 active:scale-95 transition-all"
              >
                <i className="fas fa-print"></i> Imprimir / PDF
              </button>
              <button 
                onClick={() => handleSendWhatsApp(showSuccessModal)}
                className="w-full bg-emerald-500 text-white py-5 rounded-[2rem] font-black uppercase text-[10px] tracking-widest flex items-center justify-center gap-3 active:scale-95 transition-all shadow-lg shadow-emerald-200"
              >
                <i className="fab fa-whatsapp"></i> Enviar a Cliente
              </button>
              <button 
                onClick={() => setShowSuccessModal(null)}
                className="w-full bg-slate-50 text-slate-400 py-4 rounded-[2rem] font-black uppercase text-[10px] mt-2"
              >
                Cerrar
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Product, Customer, CartItem, PaymentSplit, Sale, Employee } from '../types';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';

export const POSModule: React.FC<{ onBack: () => void; user: Employee }> = ({ onBack, user }) => {
  const { products, customers, sales, addSale, ticketConfig } = useERPData();
  const [activeTab, setActiveTab] = useState<'sell' | 'history'>('sell');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [customer, setCustomer] = useState<Customer | null>(null);
  const [search, setSearch] = useState('');
  const [vacios, setVacios] = useState(0);

  // Lógica de Tiempo para Admin
  const getLocalISO = (d: Date = new Date()) => {
    const offset = d.getTimezoneOffset() * 60000;
    return new Date(d.getTime() - offset).toISOString().slice(0, 16);
  };

  const [manualDate, setManualDate] = useState<string>(getLocalISO());
  const [autoTime, setAutoTime] = useState(true);
  const [nowDisplay, setNowDisplay] = useState(new Date());

  const [showSuccessModal, setShowSuccessModal] = useState<Sale | null>(null);

  const [paidCash, setPaidCash] = useState<string>('');
  const [paidTransfer, setPaidTransfer] = useState<string>('');

  // Efecto del Reloj
  useEffect(() => {
    let interval: any;
    if (autoTime) {
      interval = setInterval(() => {
        const d = new Date();
        setNowDisplay(d);
        setManualDate(getLocalISO(d));
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [autoTime]);

  const handleDateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setAutoTime(false);
    setManualDate(e.target.value);
  };

  const total = cart.reduce((sum, item) => {
    const price = (customer?.specialPrice && item.id === '1') ? customer.specialPrice : item.price;
    return sum + (price * item.quantity);
  }, 0);

  const totalPaid = (parseFloat(paidCash) || 0) + (parseFloat(paidTransfer) || 0);

  // Lógica de Deuda vs Cambio
  const remainingBalance = total - totalPaid;
  const isCreditSale = remainingBalance > 0.01; // Pequeño margen por decimales
  const change = Math.max(0, totalPaid - total);

  // Auto-calcular vacíos basado en garrafones vendidos (sugerencia)
  useEffect(() => {
    const garrafonesInCart = cart.filter(i => i.name.toLowerCase().includes('garraf') || i.category === 'Agua').reduce((acc, i) => acc + i.quantity, 0);
    if (cart.length > 0 && vacios === 0) {
      setVacios(garrafonesInCart);
    } else if (cart.length === 0) {
      setVacios(0);
    }
  }, [cart]);

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === product.id);
      if (existing) return prev.map(i => i.id === product.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const generateTicketPDF = (sale: Sale) => {
    const qrData = btoa(`AQUA-PRO-SECURE|${JSON.stringify({ id: sale.id, total: sale.total })}`);
    const ticketHtml = `
      <div style="font-family: 'Courier New', Courier, monospace; padding: 20px; text-align: center; width: 300px; margin: auto; color: #000; background: #fff; line-height: 1.4;">
        ${ticketConfig.logoUrl ? `<img src="${ticketConfig.logoUrl}" style="width: 100px; height: 100px; object-fit: contain; margin-bottom: 15px;"/>` : ''}

        <h2 style="margin: 0; font-size: 18px; text-transform: uppercase; font-weight: 900;">${ticketConfig.businessName}</h2>
        ${ticketConfig.slogan ? `<p style="font-size: 10px; font-style: italic; margin: 4px 0 0 0; color: #444;">"${ticketConfig.slogan}"</p>` : ''}

        <div style="margin: 10px 0; font-size: 10px; border-bottom: 2px solid #000; padding-bottom: 10px;">
          <p style="margin: 2px 0;">RFC: ${ticketConfig.rfc}</p>
          <p style="margin: 2px 0;">${ticketConfig.address}</p>
          <p style="margin: 2px 0;">TEL: ${ticketConfig.phone}</p>
          ${ticketConfig.email ? `<p style="margin: 2px 0;">${ticketConfig.email}</p>` : ''}
          ${ticketConfig.website ? `<p style="margin: 2px 0;">${ticketConfig.website}</p>` : ''}
          ${ticketConfig.socialMedia ? `<p style="margin: 2px 0;">${ticketConfig.socialMedia}</p>` : ''}
        </div>

        <div style="text-align: left; font-size: 11px; margin-bottom: 10px;">
          <p style="margin: 2px 0;">FOLIO: <b>${sale.id}</b></p>
          <p style="margin: 2px 0;">FECHA: ${new Date(sale.timestamp).toLocaleString()}</p>
          <p style="margin: 2px 0;">CLIENTE: ${sale.customerAlias.toUpperCase()}</p>
        </div>

        <table style="width: 100%; font-size: 11px; border-collapse: collapse; margin-bottom: 10px;">
          <thead>
            <tr style="border-bottom: 1px dashed #000;">
              <th style="text-align: left; padding: 4px 0;">CANT</th>
              <th style="text-align: left; padding: 4px 0;">CONCEPTO</th>
              <th style="text-align: right; padding: 4px 0;">IMP</th>
            </tr>
          </thead>
          <tbody>
            ${sale.items.map(i => `
              <tr>
                <td style="text-align: left; vertical-align: top; padding: 4px 0;">${i.quantity}</td>
                <td style="text-align: left; vertical-align: top; padding: 4px 0;">${i.name.slice(0, 20)}</td>
                <td style="text-align: right; vertical-align: top; padding: 4px 0;">$${(i.quantity * i.price).toFixed(2)}</td>
              </tr>
            `).join('')}
          </tbody>
        </table>

        <div style="border-top: 2px solid #000; padding-top: 10px; text-align: right; font-size: 13px; font-weight: 900;">
          <p style="margin: 4px 0;">TOTAL: $${sale.total.toFixed(2)}</p>
        </div>
        <div style="text-align: right; font-size: 11px;">
          <p style="margin: 2px 0;">EFECTIVO: $${(sale.paymentSplits.find(p => p.method === 'Efectivo')?.amount || 0).toFixed(2)}</p>
          <p style="margin: 2px 0;">TRANSF: $${(sale.paymentSplits.find(p => p.method === 'Transferencia')?.amount || 0).toFixed(2)}</p>
          <p style="margin: 2px 0;">RECIBIDO: $${sale.paidAmount.toFixed(2)}</p>
          ${sale.paidAmount < sale.total 
            ? `<p style="margin: 4px 0; font-weight: bold; color: #000;">SALDO PENDIENTE (CRÉDITO): $${(sale.total - sale.paidAmount).toFixed(2)}</p>` 
            : `<p style="margin: 4px 0; font-weight: bold; border-top: 1px dotted #888; display: inline-block; padding-top: 2px;">CAMBIO: $${sale.change.toFixed(2)}</p>`
          }
        </div>

        ${sale.emptyGarrafonsReturned > 0 ? `
          <div style="margin: 10px 0; text-align: center; border: 1px solid #000; padding: 5px;">
             <p style="font-weight: bold; font-size: 12px; margin:0;">ENVASES RECIBIDOS: ${sale.emptyGarrafonsReturned}</p>
          </div>
        ` : ''}

        <div style="margin: 20px 0; border-top: 1px dashed #000; padding-top: 10px;">
          <p style="font-size: 11px; font-weight: bold; margin: 0 0 5px 0;">${ticketConfig.footerMessage}</p>
          ${ticketConfig.extraNote ? `<p style="font-size: 9px; font-style: italic; margin: 0;">* ${ticketConfig.extraNote}</p>` : ''}
        </div>

        <div style="margin-top: 15px;">
          <img src="https://api.qrserver.com/v1/create-qr-code/?size=120x120&data=${encodeURIComponent(qrData)}" style="width: 120px; height: 120px;"/>
          <p style="font-size: 8px; margin-top: 8px; color: #555; text-transform: uppercase; letter-spacing: 1px;">Escanea para validar autenticidad</p>
          <p style="font-size: 8px; font-weight: bold;">AQUA+ FUNDADORES SECURITY</p>
        </div>
      </div>
    `;
    const win = window.open('', '_blank');
    if (win) {
      win.document.write(ticketHtml);
      win.document.close();
      win.print();
    }
  };

  const handleSendWhatsApp = (sale: Sale) => {
    const phone = customer?.phone?.replace(/\D/g, '');
    if (!phone) return alert("El cliente no tiene teléfono registrado.");

    const itemsText = sale.items.map(i => `• ${i.quantity}x ${i.name}`).join('%0A');
    const debtMsg = sale.paidAmount < sale.total ? `%0A%0A⚠️ *Saldo Pendiente:* $${(sale.total - sale.paidAmount).toFixed(2)}` : '';

    const msg = `¡Hola ${sale.customerAlias}!%0A%0A*${ticketConfig.businessName}*%0AGracias por tu compra.%0A%0A*Detalles de tu pedido:*%0A${itemsText}%0A%0A*Envases Recibidos:* ${sale.emptyGarrafonsReturned}%0A*Total:* $${sale.total.toFixed(2)}${debtMsg}%0A*Ticket:* ${sale.id}%0A%0A_Validación de seguridad QR disponible en planta._`;
    window.open(`https://wa.me/52${phone}?text=${msg}`, '_blank');
  };

  const handleCheckout = () => {
    if (!customer) return alert("Selecciona un cliente.");
    if (cart.length === 0) return alert("El carrito está vacío.");

    const splits: PaymentSplit[] = [];
    if (parseFloat(paidCash) > 0) splits.push({ method: 'Efectivo', amount: parseFloat(paidCash) });
    if (parseFloat(paidTransfer) > 0) splits.push({ method: 'Transferencia', amount: parseFloat(paidTransfer) });

    const sale = addSale(
      customer.id, cart, total, totalPaid, splits, vacios, 
      user.role === 'Administrador' ? new Date(manualDate).getTime() : undefined
    );

    setShowSuccessModal(sale);
    setCart([]);
    setCustomer(null);
    setSearch('');
    setPaidCash('');
    setPaidTransfer('');
    setVacios(0);
    if (user.role === 'Administrador') setAutoTime(true); 
  };

  return (
    <div className="h-full flex flex-col animate-fadeIn bg-sky-50 pb-24 overflow-hidden relative">
      <ModuleHeader title="Punto de Venta" onBack={onBack} />

      <div className="px-6 flex gap-2 mb-4">
        <button onClick={() => setActiveTab('sell')} className={`flex-1 py-3 rounded-2xl text-xs font-bold ${activeTab === 'sell' ? 'bg-sky-600 text-white shadow-lg' : 'bg-white text-sky-400'}`}>Nueva Venta</button>
        <button onClick={() => setActiveTab('history')} className={`flex-1 py-3 rounded-2xl text-xs font-bold ${activeTab === 'history' ? 'bg-sky-600 text-white shadow-lg' : 'bg-white text-sky-400'}`}>Historial</button>
      </div>

      {activeTab === 'sell' ? (
        <div className="flex-1 overflow-y-auto px-6 space-y-6 pb-32 no-scrollbar">
          {/* Admin Date Control */}
          {user.role === 'Administrador' && (
            <div className={`p-4 rounded-[2.2rem] border transition-all duration-500 ${autoTime ? 'bg-white border-sky-100' : 'bg-amber-50 border-amber-200 shadow-inner'}`}>
              <div className="flex justify-between items-center mb-3">
                <div className="flex items-center gap-2">
                  <div className={`w-2.5 h-2.5 rounded-full ${autoTime ? 'bg-emerald-500 animate-pulse' : 'bg-amber-500'}`}></div>
                  <label className="text-[10px] font-black uppercase tracking-widest text-sky-900">
                    {autoTime ? 'TIEMPO REAL (INTERNET)' : 'MODO MANUAL (EDITANDO)'}
                  </label>
                </div>
                {!autoTime && (
                  <button onClick={() => setAutoTime(true)} className="flex items-center gap-1 text-[9px] font-black text-sky-500 uppercase bg-sky-50 px-3 py-1.5 rounded-full active:scale-95 transition-transform">
                    <i className="fas fa-rotate"></i> Sincronizar
                  </button>
                )}
              </div>

              <div className="flex gap-3 items-center">
                <div className="flex-1 relative">
                  <input 
                    type="datetime-local" 
                    className={`w-full border-none rounded-2xl p-4 text-xs font-black shadow-sm outline-none transition-all ${
                      autoTime 
                        ? 'bg-sky-50 text-sky-400 pointer-events-none opacity-80' 
                        : 'bg-white text-amber-600 ring-2 ring-amber-200'
                    }`}
                    value={manualDate}
                    onChange={handleDateChange}
                  />
                  {autoTime && (
                    <div className="absolute right-4 top-1/2 -translate-y-1/2 text-emerald-500 text-lg font-black tracking-tighter tabular-nums">
                      {nowDisplay.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit', second:'2-digit'})}
                    </div>
                  )}
                </div>
              </div>
            </div>
          )}

          <section>
            <div className="relative">
              <input type="text" placeholder="Buscar Cliente..." className="w-full bg-white border-none rounded-[2rem] py-5 px-8 shadow-sm outline-none" value={search} onChange={e => setSearch(e.target.value)} />
              {search && !customer && (
                <div className="absolute top-full left-0 right-0 bg-white shadow-2xl rounded-3xl mt-2 z-50 overflow-hidden border border-sky-50">
                  {customers.filter(c => c.alias.toLowerCase().includes(search.toLowerCase())).map(c => (
                    <button key={c.id} onClick={() => { setCustomer(c); setSearch(c.alias); }} className="w-full text-left p-4 hover:bg-sky-50 font-bold border-b border-sky-50 flex justify-between items-center">
                      <span className="text-sky-900">{c.alias}</span>
                      <span className="text-[10px] bg-sky-50 text-sky-400 px-3 py-1 rounded-full font-black">${c.balance}</span>
                    </button>
                  ))}
                </div>
              )}
            </div>
            {customer && (
              <div className="mt-4 flex items-center justify-between bg-sky-600 text-white p-4 rounded-[1.8rem] shadow-lg animate-fadeIn">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-white/20 rounded-2xl flex items-center justify-center"><i className="fas fa-user"></i></div>
                  <div>
                    <span className="text-[8px] font-black uppercase opacity-60 block">Cliente Activo</span>
                    <span className="font-black text-sm">{customer.alias}</span>
                    {customer.balance > 0 && (
                      <span className="text-[9px] bg-red-500/30 px-2 py-0.5 rounded ml-2 font-bold">Adeudo: ${customer.balance}</span>
                    )}
                  </div>
                </div>
                <button onClick={() => {setCustomer(null); setSearch('');}} className="w-10 h-10 bg-white/10 rounded-full flex items-center justify-center active:scale-90 transition-all"><i className="fas fa-times"></i></button>
              </div>
            )}
          </section>

          <div className="grid grid-cols-2 gap-3">
            {products.map(p => (
              <button key={p.id} onClick={() => addToCart(p)} className="bg-white p-5 rounded-[2.2rem] shadow-sm active:bg-sky-50 text-left relative overflow-hidden group border border-transparent hover:border-sky-100">
                <div className="text-xs font-black text-sky-900 uppercase tracking-tight mb-1">{p.name}</div>
                <div className="text-sky-600 font-black text-lg">${p.price}</div>
                <div className="absolute -bottom-2 -right-2 w-12 h-12 bg-sky-50 text-sky-100 flex items-center justify-center rounded-tl-3xl group-active:text-sky-200 transition-colors">
                  <i className="fas fa-plus"></i>
                </div>
              </button>
            ))}
          </div>

          {cart.length > 0 && (
            <RoundedCard className="shadow-2xl border-2 border-white">
              <div className="flex justify-between items-start mb-6">
                <div>
                  <span className="text-[10px] text-sky-400 font-black uppercase mb-1 block">Monto a Liquidar</span>
                  <span className="text-4xl font-black text-sky-900 tracking-tighter">${total.toFixed(2)}</span>
                </div>
                <button onClick={() => setCart([])} className="text-rose-400 text-xs font-bold uppercase underline">Vaciar</button>
              </div>

              <div className="space-y-3 mb-6">
                {cart.map(i => (
                  <div key={i.id} className="flex justify-between items-center bg-sky-50/30 p-2 rounded-xl">
                    <span className="text-xs font-bold text-sky-800">{i.quantity}x {i.name}</span>
                    <span className="text-xs font-black text-sky-600">${(i.quantity * i.price).toFixed(2)}</span>
                  </div>
                ))}
              </div>

              {/* Control de Garrafones Vacíos */}
              <div className="mb-6 bg-white p-4 rounded-3xl border border-sky-100 flex justify-between items-center">
                 <span className="text-[10px] font-black text-sky-400 uppercase tracking-tight ml-2">Garrafones Vacíos Recibidos</span>
                 <div className="flex items-center gap-3 bg-sky-50 rounded-2xl p-1">
                    <button onClick={() => setVacios(Math.max(0, vacios - 1))} className="w-8 h-8 flex items-center justify-center bg-white text-sky-600 rounded-xl font-black shadow-sm">-</button>
                    <span className="text-lg font-black text-sky-900 w-6 text-center">{vacios}</span>
                    <button onClick={() => setVacios(vacios + 1)} className="w-8 h-8 flex items-center justify-center bg-sky-600 text-white rounded-xl font-black shadow-lg">+</button>
                 </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[9px] font-black text-sky-400 uppercase ml-2">Efectivo</label>
                  <input type="number" value={paidCash} onChange={e => setPaidCash(e.target.value)} className="w-full bg-sky-50 p-4 rounded-2xl font-black text-lg focus:ring-2 ring-sky-200 outline-none" placeholder="$ 0.00" />
                </div>
                <div className="space-y-1">
                  <label className="text-[9px] font-black text-sky-400 uppercase ml-2">Transf.</label>
                  <input type="number" value={paidTransfer} onChange={e => setPaidTransfer(e.target.value)} className="w-full bg-sky-50 p-4 rounded-2xl font-black text-lg focus:ring-2 ring-sky-200 outline-none" placeholder="$ 0.00" />
                </div>
              </div>

              <div className={`mt-4 p-5 rounded-[1.8rem] flex justify-between items-center border transition-colors ${isCreditSale ? 'bg-amber-50 border-amber-100' : 'bg-emerald-50 border-emerald-100'}`}>
                <div>
                  <span className={`text-[10px] font-black uppercase tracking-widest block ${isCreditSale ? 'text-amber-700' : 'text-emerald-700'}`}>
                    {isCreditSale ? 'Saldo Pendiente (Crédito)' : 'Cambio Sugerido'}
                  </span>
                  <span className={`text-2xl font-black tracking-tighter ${isCreditSale ? 'text-amber-600' : 'text-emerald-600'}`}>
                    ${isCreditSale ? remainingBalance.toFixed(2) : change.toFixed(2)}
                  </span>
                </div>
                <div className={`w-12 h-12 bg-white rounded-2xl flex items-center justify-center shadow-sm ${isCreditSale ? 'text-amber-500 shadow-amber-100' : 'text-emerald-500 shadow-emerald-100'}`}>
                  <i className={`fas ${isCreditSale ? 'fa-file-invoice-dollar' : 'fa-hand-holding-dollar'} text-xl`}></i>
                </div>
              </div>
            </RoundedCard>
          )}
        </div>
      ) : (
        <div className="flex-1 overflow-y-auto px-6 space-y-3 pb-10 no-scrollbar">
          {sales.length === 0 ? (
            <div className="text-center py-20 opacity-30">
               <i className="fas fa-receipt text-6xl mb-4"></i>
               <p className="text-xs font-black uppercase">Sin historial reciente</p>
            </div>
          ) : (
            sales.map(s => (
              <RoundedCard key={s.id} className="py-5 border-none shadow-sm group">
                <div className="flex justify-between items-start">
                  <div className="flex gap-4">
                    <div className="w-12 h-12 bg-sky-50 text-sky-600 rounded-2xl flex items-center justify-center text-xl">
                      <i className="fas fa-receipt"></i>
                    </div>
                    <div>
                      <h4 className="font-black text-sky-900 text-sm leading-tight">{s.customerAlias}</h4>
                      <p className="text-[9px] text-sky-400 font-bold uppercase mt-1">{new Date(s.timestamp).toLocaleString()}</p>
                      {s.paidAmount < s.total && (
                        <span className="text-[9px] text-amber-500 font-black uppercase bg-amber-50 px-2 py-0.5 rounded mt-1 inline-block">Crédito</span>
                      )}
                    </div>
                  </div>
                  <div className="text-right">
                    <span className="font-black text-sky-600 text-xl tracking-tighter">${s.total}</span>
                    <p className="text-[8px] font-black text-sky-300 uppercase">{s.id}</p>
                  </div>
                </div>
                <div className="flex gap-2 mt-5">
                   <button onClick={() => generateTicketPDF(s)} className="flex-1 text-[9px] font-black uppercase bg-sky-100 text-sky-600 px-3 py-3 rounded-xl flex items-center justify-center gap-2 active:bg-sky-200 transition-colors">
                    <i className="fas fa-print"></i> Ticket
                   </button>
                   <button onClick={() => handleSendWhatsApp(s)} className="flex-1 text-[9px] font-black uppercase bg-emerald-100 text-emerald-600 px-3 py-3 rounded-xl flex items-center justify-center gap-2 active:bg-emerald-200 transition-colors">
                    <i className="fab fa-whatsapp"></i> Enviar WA
                   </button>
                </div>
              </RoundedCard>
            ))
          )}
        </div>
      )}

      {activeTab === 'sell' && (
        <div className="fixed bottom-0 left-0 right-0 p-6 bg-white/95 border-t border-sky-100 shadow-2xl z-50">
          <ActionButton onClick={handleCheckout} disabled={!customer || cart.length === 0}>
             {isCreditSale ? 'Registrar Venta a Crédito' : 'Completar Venta'}
          </ActionButton>
        </div>
      )}

      {/* Modal de Éxito Moderno */}
      {showSuccessModal && (
        <div className="fixed inset-0 bg-sky-900/80 backdrop-blur-md z-[100] flex items-center justify-center p-8 animate-fadeIn">
          <div className="bg-white w-full max-w-sm rounded-[3rem] p-10 text-center shadow-2xl border-t-8 border-emerald-500">
            <div className="w-24 h-24 bg-emerald-100 text-emerald-500 rounded-full flex items-center justify-center mx-auto mb-8 shadow-xl shadow-emerald-100">
              <i className="fas fa-check-circle text-5xl"></i>
            </div>
            <h3 className="text-3xl font-black text-sky-900 mb-2 tracking-tighter">¡Listo!</h3>
            <p className="text-sky-400 text-xs font-bold mb-10 uppercase tracking-widest leading-relaxed">
               {showSuccessModal.paidAmount < showSuccessModal.total 
                 ? "Venta registrada. Saldo pendiente agregado a cuenta del cliente." 
                 : "Venta registrada correctamente."}
            </p>

            <div className="space-y-3">
              <button 
                onClick={() => { generateTicketPDF(showSuccessModal); setShowSuccessModal(null); }}
                className="w-full bg-sky-600 text-white py-6 rounded-[2rem] font-black uppercase text-xs tracking-[0.2em] flex items-center justify-center gap-4 active:scale-95 transition-all shadow-xl shadow-sky-100"
              >
                <i className="fas fa-print text-sm"></i> Imprimir Físico
              </button>
              <button 
                onClick={() => { handleSendWhatsApp(showSuccessModal); setShowSuccessModal(null); }}
                className="w-full bg-emerald-500 text-white py-6 rounded-[2rem] font-black uppercase text-xs tracking-[0.2em] flex items-center justify-center gap-4 active:scale-95 transition-all shadow-xl shadow-emerald-100"
              >
                <i className="fab fa-whatsapp text-sm"></i> Enviar a Cliente
              </button>
              <button 
                onClick={() => setShowSuccessModal(null)}
                className="w-full bg-sky-50 text-sky-400 py-5 rounded-[2rem] font-black uppercase text-[10px] mt-4"
              >
                Continuar Vendiendo
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export type ViewType = 'dashboard' | 'pos' | 'orders' | 'logistics' | 'production' | 'sync' | 'whatsapp' | 'customers' | 'employees' | 'reports' | 'settings' | 'quality' | 'scanner' | 'inventory' | 'tickets';

export interface Product {
  id: string;
  name: string;
  price: number;
  stock: number;
  category?: 'Agua' | 'Insumos' | 'Accesorios';
}

export type GarrafonType = 'Aqua' | 'Bonafont' | 'Ciel' | 'E-Pura' | 'Generico';

export interface Customer {
  id: string;
  name: string;
  alias: string;
  address?: string; // New field
  phone?: string;
  specialPrice?: number;
  lat?: number;
  lng?: number;
  garrafonType?: GarrafonType;
  balance: number;
}

export interface TicketConfig {
  businessName: string;
  rfc: string;
  address: string;
  phone: string;
  footerMessage: string;
  logoUrl?: string;
  website?: string;
  socialMedia?: string;
  extraNote?: string;
  slogan?: string;
  email?: string;
}

export interface CloudConfig {
  url: string;
  apiKey: string;
  autoSync: boolean;
  lastSync?: number;
}

export interface Order {
  id: string;
  customerId: string;
  customerAlias: string;
  items: CartItem[];
  total: number;
  status: 'pendiente' | 'asignado' | 'entregado' | 'cancelado';
  vehicleId?: string;
  timestamp: number;
  priority: number;
}

export interface CartItem extends Product {
  quantity: number;
}

export type PaymentMethod = 'Efectivo' | 'Transferencia' | 'Crédito' | 'Multimodal';

export interface PaymentSplit {
  method: 'Efectivo' | 'Transferencia';
  amount: number;
}

export interface Sale {
  id: string;
  timestamp: number;
  customerId: string;
  customerAlias: string;
  items: CartItem[];
  total: number;
  paidAmount: number;
  change: number;
  paymentSplits: PaymentSplit[];
  emptyGarrafonsReturned: number;
  synced: boolean;
}

export interface QualityRecord {
  id: string;
  timestamp: number;
  type: 'Cruda' | 'Producto';
  ph: number;
  cloro: number;
  tds: number;
  dureza: number;
  color: string;
  sabor: string;
  turbiedad: string;
  employeeId: string;
}

export interface Task {
  id: string;
  employeeId: string;
  title: string;
  description?: string;
  status: 'pendiente' | 'completada';
  timestamp: number;
  date: string;
}

export interface Attendance {
  id: string;
  employeeId: string;
  timestamp: number;
  date: string;
  status: 'presente' | 'falta' | 'retardo';
}

export interface Employee {
  id: string;
  name: string;
  role: 'Repartidor' | 'Planta' | 'Administrador';
  phone: string;
  pin: string;
  permissions: ViewType[];
}

export interface Vehicle {
  id: string;
  plate: string;
  description: string;
  loadCapacity: number;
  currentLoad: number;
}

import React, { useState, useRef } from 'react';
import { Customer, GarrafonType } from '../types';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';

const GARRAFON_TYPES: { type: GarrafonType, color: string }[] = [
  { type: 'Aqua', color: 'bg-blue-500' },
  { type: 'Bonafont', color: 'bg-orange-500' },
  { type: 'Ciel', color: 'bg-sky-400' },
  { type: 'E-Pura', color: 'bg-red-500' },
  { type: 'Generico', color: 'bg-slate-400' }
];

export const CustomersModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const { customers, saveCustomer, deleteCustomer, sales, importCustomers } = useERPData();
  const [search, setSearch] = useState('');
  const [editingCustomer, setEditingCustomer] = useState<Partial<Customer> | null>(null);
  const [viewingHistory, setViewingHistory] = useState<Customer | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const filteredCustomers = customers.filter(c => 
    c.name.toLowerCase().includes(search.toLowerCase()) || 
    c.alias.toLowerCase().includes(search.toLowerCase())
  );

  const handleSave = () => {
    if (!editingCustomer?.name || !editingCustomer?.alias) {
      alert("Nombre y Alias son obligatorios.");
      return;
    }
    const customerToSave: Customer = {
      id: editingCustomer.id || Math.random().toString(36).substr(2, 9),
      name: editingCustomer.name,
      alias: editingCustomer.alias,
      phone: editingCustomer.phone || '',
      address: editingCustomer.address || '',
      specialPrice: editingCustomer.specialPrice || undefined,
      garrafonType: editingCustomer.garrafonType || 'Generico',
      balance: editingCustomer.balance || 0,
      lat: editingCustomer.lat,
      lng: editingCustomer.lng,
    };
    saveCustomer(customerToSave);
    setEditingCustomer(null);
  };

  const handleDelete = () => {
    if (!editingCustomer?.id) return;
    const confirmDelete = window.confirm(
      `¿Estás seguro de eliminar a "${editingCustomer.alias}"?\n\nEsta acción eliminará el registro del cliente permanentemente. Su historial de ventas se mantendrá como anónimo.`
    );
    if (confirmDelete) {
      deleteCustomer(editingCustomer.id);
      setEditingCustomer(null);
    }
  };

  const handleGetLocation = () => {
    if (!navigator.geolocation) {
      alert("Tu dispositivo no soporta geolocalización.");
      return;
    }

    const btn = document.getElementById('gps-btn');
    if(btn) {
       btn.innerHTML = '<i class="fas fa-circle-notch animate-spin"></i> Obteniendo...';
       btn.classList.add('opacity-50', 'pointer-events-none');
    }

    navigator.geolocation.getCurrentPosition(
      (position) => {
        setEditingCustomer(prev => prev ? ({
          ...prev,
          lat: position.coords.latitude,
          lng: position.coords.longitude
        }) : null);

        if(btn) {
          btn.innerHTML = '<i class="fas fa-check"></i> Ubicación Capturada';
          btn.classList.remove('opacity-50', 'pointer-events-none', 'bg-emerald-50', 'text-emerald-600');
          btn.classList.add('bg-emerald-50', 'text-white');
          setTimeout(() => {
             btn.innerHTML = '<i class="fas fa-location-crosshairs"></i> Actualizar GPS';
             btn.classList.remove('bg-emerald-500', 'text-white');
             btn.classList.add('bg-emerald-50', 'text-emerald-600');
          }, 3000);
        }
      },
      (error) => {
        console.error(error);
        alert("Error al obtener ubicación. Asegúrate de dar permisos de ubicación a la app.");
        if(btn) {
          btn.innerHTML = '<i class="fas fa-triangle-exclamation"></i> Error';
          btn.classList.remove('opacity-50', 'pointer-events-none');
        }
      },
      { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 }
    );
  };

  const openGoogleMaps = (lat?: number, lng?: number) => {
    if (lat && lng) {
      window.open(`https://www.google.com/maps/search/?api=1&query=${lat},${lng}`, '_blank');
    } else {
      alert("Este cliente no tiene ubicación registrada.");
    }
  };

  // --- LOGICA DE EXPORTACIÓN E IMPORTACIÓN ---

  const downloadFile = (content: string, filename: string, type: string) => {
    const blob = new Blob([content], { type });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleExportCSV = () => {
    const headers = ["ID", "Nombre", "Alias", "Telefono", "Direccion", "Saldo", "Precio Especial", "Tipo Garrafon", "Lat", "Lng"];
    const rows = customers.map(c => [
      c.id,
      `"${c.name}"`,
      `"${c.alias}"`,
      c.phone || '',
      `"${c.address || ''}"`,
      c.balance,
      c.specialPrice || '',
      c.garrafonType || 'Generico',
      c.lat || '',
      c.lng || ''
    ]);
    const csvContent = [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
    downloadFile(csvContent, `Clientes_Aqua_${new Date().toISOString().split('T')[0]}.csv`, 'text/csv');
  };

  const handleExportVCard = () => {
    let vCardContent = '';
    customers.forEach(c => {
      vCardContent += 'BEGIN:VCARD\nVERSION:3.0\n';
      vCardContent += `FN:Aqua - ${c.alias}\n`;
      vCardContent += `N:Aqua;${c.alias};;;\n`;
      if (c.phone) vCardContent += `TEL;TYPE=CELL:${c.phone}\n`;
      if (c.address) vCardContent += `ADR;TYPE=HOME:;;${c.address};;;;\n`;
      vCardContent += `NOTE:Cliente Aqua+. Saldo: $${c.balance}. Tipo: ${c.garrafonType}\n`;
      vCardContent += 'END:VCARD\n';
    });
    downloadFile(vCardContent, `Contactos_Aqua_${new Date().toISOString().split('T')[0]}.vcf`, 'text/vcard');
  };

  const handleImportFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      if (!text) return;

      try {
        let importedCount = 0;
        const newCustomers: Customer[] = [];

        if (file.name.toLowerCase().endsWith('.csv')) {
          // Importar CSV - Flexible con Headers
          const lines = text.replace(/\r\n/g, '\n').replace(/\r/g, '\n').split('\n');

          if (lines.length > 0) {
            // Analizar cabeceras (primera línea) para encontrar índices
            const headerLine = lines[0].toLowerCase();
            const headers = headerLine.split(',').map(h => h.trim().replace(/^"|"$/g, ''));

            // Mapas de índices
            const idxNombre = headers.findIndex(h => h.includes('nombre'));
            const idxAlias = headers.findIndex(h => h.includes('alias') || h.includes('comercial'));
            const idxTelefono = headers.findIndex(h => h.includes('telefono') || h.includes('celular') || h.includes('whatsapp'));
            const idxDireccion = headers.findIndex(h => h.includes('direccion') || h.includes('domicilio') || h.includes('calle'));
            const idxSaldo = headers.findIndex(h => h.includes('saldo') || h.includes('balance'));
            const idxPrecio = headers.findIndex(h => h.includes('precio'));

            lines.slice(1).forEach(line => {
              if (!line.trim()) return;
              // Regex simple para split respetando comillas básicas
              const cols = line.split(',').map(c => c.replace(/^"|"$/g, '').trim());

              // Extracción flexible de datos
              const nameRaw = idxNombre !== -1 ? cols[idxNombre] : '';
              const aliasRaw = idxAlias !== -1 ? cols[idxAlias] : '';

              // Lógica de fallback: Si falta nombre o alias, usar el otro
              const finalName = nameRaw || aliasRaw || 'Cliente Importado';
              const finalAlias = aliasRaw || nameRaw || 'Sin Alias';

              if (finalAlias) {
                newCustomers.push({
                  id: Math.random().toString(36).substr(2, 9),
                  name: finalName,
                  alias: finalAlias,
                  phone: idxTelefono !== -1 ? cols[idxTelefono] : '',
                  address: idxDireccion !== -1 ? cols[idxDireccion] : '',
                  balance: idxSaldo !== -1 ? (parseFloat(cols[idxSaldo]) || 0) : 0,
                  specialPrice: idxPrecio !== -1 ? (parseFloat(cols[idxPrecio]) || undefined) : undefined,
                  garrafonType: 'Generico',
                });
                importedCount++;
              }
            });
          }
        } else if (file.name.toLowerCase().endsWith('.vcf') || file.name.toLowerCase().endsWith('.vcard')) {
          // Importar vCard (Básico)
          const vcards = text.split('BEGIN:VCARD');
          vcards.forEach(vc => {
            const fnMatch = vc.match(/FN:(.*)/);
            const telMatch = vc.match(/TEL.*:(.*)/);
            const adrMatch = vc.match(/ADR.*:;;(.*?);/);

            if (fnMatch) {
              const name = fnMatch[1].trim();
              if (name) { 
                  const phone = telMatch ? telMatch[1].trim().replace(/[^0-9+]/g, '') : undefined;
                  const address = adrMatch ? adrMatch[1].trim() : undefined;
                  newCustomers.push({
                    id: Math.random().toString(36).substr(2, 9),
                    name: name,
                    alias: name.replace('Aqua - ', ''), 
                    phone: phone,
                    address: address,
                    balance: 0,
                    garrafonType: 'Generico'
                  });
                  importedCount++;
              }
            }
          });
        }

        if (importedCount > 0) {
          importCustomers(newCustomers);
          alert(`¡Éxito! Se importaron ${importedCount} clientes correctamente.`);
        } else {
          alert("No se encontraron datos válidos. Revisa que el CSV tenga cabeceras como 'Nombre', 'Alias', 'Telefono', 'Direccion'.");
        }
      } catch (err) {
        alert("Error crítico al procesar el archivo.");
        console.error(err);
      }
      if (fileInputRef.current) fileInputRef.current.value = '';
    };
    reader.readAsText(file);
  };

  // --- FIN LÓGICA IMPORT/EXPORT ---

  if (viewingHistory) {
    const customerSales = sales.filter(s => s.customerId === viewingHistory.id);
    const hasDebt = viewingHistory.balance > 0;
    const hasCredit = viewingHistory.balance < 0;

    return (
      <div className="h-full bg-sky-50 overflow-y-auto no-scrollbar pb-24">
        <ModuleHeader title={`Perfil: ${viewingHistory.alias}`} onBack={() => setViewingHistory(null)} />
        <div className="px-6 space-y-4">
          <RoundedCard className={`${hasDebt ? 'bg-red-500' : hasCredit ? 'bg-emerald-500' : 'bg-sky-600'} text-white shadow-lg border-none transition-colors duration-500`}>
             <div className="flex justify-between items-center">
                <div>
                   <span className="text-[10px] font-black uppercase opacity-70">
                     {hasDebt ? 'Estado: Adeudo' : hasCredit ? 'Estado: Saldo a Favor' : 'Estado: Al Corriente'}
                   </span>
                   <p className="text-3xl font-black">
                     ${Math.abs(viewingHistory.balance).toLocaleString()}
                   </p>
                </div>
                <div className="bg-white/20 p-4 rounded-2xl">
                   <i className={`fas ${hasDebt ? 'fa-hand-holding-dollar' : 'fa-piggy-bank'} text-2xl`}></i>
                </div>
             </div>
          </RoundedCard>

          <div className="grid grid-cols-2 gap-3">
             <div className="bg-white p-4 rounded-3xl shadow-sm border border-sky-50">
                <span className="text-[9px] font-black text-sky-400 uppercase block mb-1">WhatsApp</span>
                <p className="text-xs font-bold text-sky-900">{viewingHistory.phone || 'No registrado'}</p>
             </div>
             <div className="bg-white p-4 rounded-3xl shadow-sm border border-sky-50">
                <span className="text-[9px] font-black text-sky-400 uppercase block mb-1">Precio Esp.</span>
                <p className="text-xs font-bold text-sky-900">{viewingHistory.specialPrice ? `$${viewingHistory.specialPrice}` : 'Precio Base'}</p>
             </div>
          </div>

          {viewingHistory.address && (
            <div className="bg-white p-5 rounded-3xl shadow-sm border border-sky-50">
              <span className="text-[9px] font-black text-sky-400 uppercase block mb-1">Dirección</span>
              <p className="text-sm font-bold text-sky-900 leading-tight">{viewingHistory.address}</p>
            </div>
          )}

          {viewingHistory.lat && viewingHistory.lng && (
             <button 
               onClick={() => openGoogleMaps(viewingHistory.lat, viewingHistory.lng)}
               className="w-full py-4 bg-white border border-sky-100 rounded-[2rem] flex items-center justify-center gap-2 shadow-sm text-sky-600 font-black uppercase text-[10px] active:scale-95 transition-all"
             >
               <i className="fas fa-map-location-dot text-lg text-red-500"></i>
               Ver Ubicación en Mapa
             </button>
          )}

          <h4 className="text-[10px] font-black uppercase text-sky-400 tracking-widest px-2 mt-4">Transacciones Recientes</h4>
          {customerSales.length === 0 ? (
            <div className="text-center py-20 text-sky-300 italic animate-fadeIn">Sin compras registradas aún.</div>
          ) : (
            customerSales.map(s => (
              <RoundedCard key={s.id} className="py-5 border-none shadow-sm animate-fadeIn">
                <div className="flex justify-between items-start mb-3">
                  <div>
                    <span className="text-sky-900 font-black">{s.id}</span>
                    <p className="text-[10px] text-sky-400 font-bold uppercase">{new Date(s.timestamp).toLocaleDateString()}</p>
                  </div>
                  <span className="font-black text-sky-600 text-xl">${s.total}</span>
                </div>
                <div className="flex flex-wrap gap-2">
                  {s.items.map(i => <span key={i.id} className="bg-sky-50 text-sky-600 text-[8px] px-3 py-1 rounded-full font-black uppercase">{i.quantity}x {i.name}</span>)}
                </div>
              </RoundedCard>
            ))
          )}
        </div>
      </div>
    );
  }

  if (editingCustomer) {
    return (
      <div className="h-full bg-sky-50 overflow-y-auto no-scrollbar pb-32">
        <ModuleHeader title={editingCustomer.id ? "Editar Perfil" : "Nuevo Cliente"} onBack={() => setEditingCustomer(null)} />
        <div className="px-6 space-y-5">
          <div className="space-y-4">
            <div>
               <label className="text-[10px] font-black text-sky-400 uppercase ml-3 mb-1 block">Nombre Comercial / Alias</label>
               <input className="w-full bg-white p-5 rounded-[2rem] outline-none shadow-sm font-bold text-sky-900 focus:ring-2 ring-sky-300 transition-all" placeholder="Ej: Doña Mary" value={editingCustomer.alias || ''} onChange={e => setEditingCustomer({...editingCustomer, alias: e.target.value})}/>
            </div>
            <div>
               <label className="text-[10px] font-black text-sky-400 uppercase ml-3 mb-1 block">Nombre Legal</label>
               <input className="w-full bg-white p-5 rounded-[2rem] outline-none shadow-sm text-sky-900 focus:ring-2 ring-sky-300 transition-all" placeholder="Ej: María de los Angeles" value={editingCustomer.name || ''} onChange={e => setEditingCustomer({...editingCustomer, name: e.target.value})}/>
            </div>
            <div>
               <label className="text-[10px] font-black text-sky-400 uppercase ml-3 mb-1 block">WhatsApp</label>
               <input className="w-full bg-white p-5 rounded-[2rem] outline-none shadow-sm text-sky-900 focus:ring-2 ring-sky-300 transition-all" placeholder="33..." value={editingCustomer.phone || ''} onChange={e => setEditingCustomer({...editingCustomer, phone: e.target.value})}/>
            </div>
            <div>
               <label className="text-[10px] font-black text-sky-400 uppercase ml-3 mb-1 block">Dirección / Domicilio</label>
               <input className="w-full bg-white p-5 rounded-[2rem] outline-none shadow-sm text-sky-900 focus:ring-2 ring-sky-300 transition-all" placeholder="Calle, Número, Colonia..." value={editingCustomer.address || ''} onChange={e => setEditingCustomer({...editingCustomer, address: e.target.value})}/>
            </div>

            {/* Sección de Geolocalización */}
            <div>
               <label className="text-[10px] font-black text-sky-400 uppercase ml-3 mb-1 block">Ubicación de Entrega (Pin Google Maps)</label>
               <div className="flex gap-2">
                 <button 
                   id="gps-btn"
                   onClick={handleGetLocation} 
                   className="flex-1 bg-emerald-50 text-emerald-600 p-4 rounded-[2rem] font-bold text-[10px] uppercase flex items-center justify-center gap-2 border border-emerald-100 shadow-sm active:scale-95 transition-all"
                 >
                   <i className="fas fa-location-crosshairs"></i> Capturar GPS Actual
                 </button>
                 {editingCustomer?.lat && (
                   <button 
                     onClick={() => openGoogleMaps(editingCustomer.lat, editingCustomer.lng)} 
                     className="w-14 bg-sky-50 text-sky-500 rounded-[1.5rem] flex items-center justify-center text-lg active:scale-90 transition-transform shadow-sm"
                   >
                     <i className="fas fa-map-location-dot text-red-500"></i>
                   </button>
                 )}
               </div>
               {editingCustomer.lat !== undefined && editingCustomer.lng !== undefined && (
                 <div className="mt-2 px-4 flex gap-4 text-[9px] font-mono font-bold text-sky-400 bg-white/50 py-2 rounded-xl border border-white">
                   <span>Lat: {editingCustomer.lat.toFixed(6)}</span>
                   <span>Lng: {editingCustomer.lng.toFixed(6)}</span>
                 </div>
               )}
            </div>

            <div className="space-y-3">
              <label className="text-[10px] font-black uppercase text-sky-400 ml-3 block">Tipo de Garrafón Preferido</label>
              <div className="grid grid-cols-2 gap-3">
                {GARRAFON_TYPES.map(g => (
                  <button 
                    key={g.type}
                    onClick={() => setEditingCustomer({...editingCustomer, garrafonType: g.type})}
                    className={`py-4 rounded-[1.5rem] text-[10px] font-black uppercase tracking-widest transition-all flex items-center justify-center gap-2 ${editingCustomer.garrafonType === g.type ? `${g.color} text-white shadow-lg scale-[1.02]` : 'bg-white text-sky-400 shadow-sm border border-sky-50'}`}
                  >
                    <div className={`w-2 h-2 rounded-full ${editingCustomer.garrafonType === g.type ? 'bg-white' : g.color}`}></div>
                    {g.type}
                  </button>
                ))}
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                 <label className="text-[10px] font-black text-sky-400 uppercase ml-3 mb-1 block">Precio Especial</label>
                 <input type="number" className="w-full bg-white p-5 rounded-[2rem] outline-none shadow-sm font-black text-sky-600 text-xl focus:ring-2 ring-sky-300" placeholder="0.00" value={editingCustomer.specialPrice || ''} onChange={e => setEditingCustomer({...editingCustomer, specialPrice: Number(e.target.value)})}/>
              </div>
              <div>
                 <label className="text-[10px] font-black text-sky-400 uppercase ml-3 mb-1 block">Saldo (Pos=Adeudo)</label>
                 <input type="number" className="w-full bg-white p-5 rounded-[2rem] outline-none shadow-sm font-black text-sky-900 text-xl focus:ring-2 ring-sky-300" placeholder="0.00" value={editingCustomer.balance || ''} onChange={e => setEditingCustomer({...editingCustomer, balance: Number(e.target.value)})}/>
              </div>
            </div>
          </div>

          <div className="pt-4 space-y-3">
             <ActionButton onClick={handleSave}>Guardar Cliente</ActionButton>

             {editingCustomer.id && (
               <button 
                 onClick={handleDelete}
                 className="w-full py-4 text-rose-500 font-black uppercase text-[10px] tracking-widest bg-rose-50 rounded-[2rem] active:scale-95 transition-all border border-rose-100 shadow-sm hover:bg-rose-100"
               >
                 <i className="fas fa-trash-can mr-2"></i> Eliminar Cliente
               </button>
             )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="h-full bg-sky-50 overflow-y-auto no-scrollbar pb-24">
      <ModuleHeader title="Directorio" onBack={onBack} />
      <div className="px-6 space-y-4">

        {/* PANEL DE HERRAMIENTAS DE DATOS */}
        <div className="bg-indigo-600 rounded-[2.5rem] p-6 text-white shadow-lg shadow-indigo-200">
          <div className="flex justify-between items-center mb-4">
            <h4 className="text-sm font-black uppercase tracking-tight">Herramientas de Datos</h4>
            <i className="fas fa-database opacity-50"></i>
          </div>
          <div className="grid grid-cols-3 gap-2">
            <button onClick={handleExportCSV} className="bg-white/10 hover:bg-white/20 p-3 rounded-2xl flex flex-col items-center gap-2 transition-colors">
               <i className="fas fa-file-csv text-xl"></i>
               <span className="text-[8px] font-bold uppercase text-center">CSV / Excel</span>
            </button>
            <button onClick={handleExportVCard} className="bg-white/10 hover:bg-white/20 p-3 rounded-2xl flex flex-col items-center gap-2 transition-colors">
               <i className="fas fa-address-book text-xl"></i>
               <span className="text-[8px] font-bold uppercase text-center">Contactos</span>
            </button>
            <label className="bg-white/10 hover:bg-white/20 p-3 rounded-2xl flex flex-col items-center gap-2 transition-colors cursor-pointer relative">
               <i className="fas fa-cloud-arrow-up text-xl"></i>
               <span className="text-[8px] font-bold uppercase text-center">Importar CSV</span>
               <input 
                 type="file" 
                 ref={fileInputRef}
                 accept=".csv, .vcf, .vcard" 
                 className="absolute inset-0 opacity-0 cursor-pointer"
                 onChange={handleImportFile}
               />
            </label>
          </div>
        </div>

        <div className="relative">
          <input type="text" placeholder="Buscar por alias o teléfono..." className="w-full bg-white p-5 rounded-[2rem] outline-none shadow-sm focus:ring-2 ring-sky-300 font-medium" value={search} onChange={e => setSearch(e.target.value)}/>
          <i className="fas fa-search absolute right-6 top-1/2 -translate-y-1/2 text-sky-200"></i>
        </div>

        <div className="space-y-3">
          {filteredCustomers.map(c => (
            <RoundedCard key={c.id} className="py-5 border-none shadow-sm group hover:shadow-md transition-all active:scale-[0.98]">
              <div className="flex justify-between items-center">
                <div className="flex gap-4 items-center flex-1" onClick={() => setViewingHistory(c)}>
                  <div className={`w-14 h-14 rounded-3xl flex items-center justify-center text-white font-black text-xl shadow-lg transition-transform group-active:scale-90 ${GARRAFON_TYPES.find(g => g.type === c.garrafonType)?.color || 'bg-slate-400'}`}>
                    {c.alias ? c.alias.charAt(0).toUpperCase() : '?'}
                  </div>
                  <div>
                    <h4 className="font-black text-sky-900 leading-tight">{c.alias}</h4>
                    <div className="flex gap-2 mt-1 flex-wrap">
                      <span className="bg-sky-100 text-sky-600 text-[8px] font-black px-2 py-0.5 rounded-full uppercase">{c.garrafonType || 'Aqua'}</span>
                      {c.address && (
                         <span className="bg-violet-100 text-violet-600 text-[8px] font-black px-2 py-0.5 rounded-full uppercase flex items-center gap-1">
                           <i className="fas fa-map-pin text-[8px]"></i> {c.address.slice(0, 10)}...
                         </span>
                      )}
                      {c.balance > 0 && (
                        <span className="bg-red-100 text-red-600 text-[8px] font-black px-2 py-0.5 rounded-full uppercase border border-red-200">
                          Adeudo
                        </span>
                      )}
                    </div>
                  </div>
                </div>
                <div className="flex gap-1">
                  <button onClick={() => setViewingHistory(c)} className="w-10 h-10 bg-sky-50 text-sky-500 rounded-xl flex items-center justify-center text-sm active:bg-sky-200 transition-colors"><i className="fas fa-eye"></i></button>
                  <button onClick={() => setEditingCustomer(c)} className="w-10 h-10 bg-sky-50 text-sky-500 rounded-xl flex items-center justify-center text-sm active:bg-sky-200 transition-colors"><i className="fas fa-pen"></i></button>
                  <a href={`https://wa.me/52${c.phone}`} className="w-10 h-10 bg-emerald-50 text-emerald-500 rounded-xl flex items-center justify-center text-sm active:bg-emerald-200 transition-colors"><i className="fab fa-whatsapp"></i></a>
                </div>
              </div>
            </RoundedCard>
          ))}
        </div>
        <button onClick={() => setEditingCustomer({})} className="w-full py-6 border-2 border-dashed border-sky-200 rounded-[2.5rem] text-sky-400 font-black text-sm uppercase hover:bg-white hover:text-sky-600 transition-all">+ Añadir Nuevo Cliente</button>
      </div>
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { Customer, GarrafonType } from '../types';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';

const GARRAFON_TYPES: { type: GarrafonType, color: string }[] = [
  { type: 'Aqua', color: 'bg-blue-500' },
  { type: 'Bonafont', color: 'bg-orange-500' },
  { type: 'Ciel', color: 'bg-sky-400' },
  { type: 'E-Pura', color: 'bg-red-500' },
  { type: 'Generico', color: 'bg-slate-400' }
];

export const CustomersModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const { customers, saveCustomer, deleteCustomer, sales, importCustomers } = useERPData();
  const [search, setSearch] = useState('');
  const [editingCustomer, setEditingCustomer] = useState<Partial<Customer> | null>(null);
  const [viewingHistory, setViewingHistory] = useState<Customer | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const filteredCustomers = customers.filter(c => 
    c.name.toLowerCase().includes(search.toLowerCase()) || 
    c.alias.toLowerCase().includes(search.toLowerCase())
  );

  // --- LÓGICA DE NAVEGACIÓN INTELIGENTE ---
  const handleBackNavigation = () => {
    if (editingCustomer || viewingHistory) {
      setEditingCustomer(null);
      setViewingHistory(null);
    } else {
      onBack();
    }
  };

  const handleSave = () => {
    if (!editingCustomer?.name || !editingCustomer?.alias) {
      alert("Nombre y Alias son obligatorios.");
      return;
    }
    const customerToSave: Customer = {
      id: editingCustomer.id || Math.random().toString(36).substr(2, 9),
      name: editingCustomer.name,
      alias: editingCustomer.alias,
      phone: editingCustomer.phone || '',
      address: editingCustomer.address || '',
      specialPrice: editingCustomer.specialPrice || undefined,
      garrafonType: editingCustomer.garrafonType || 'Generico',
      balance: editingCustomer.balance || 0,
      lat: editingCustomer.lat,
      lng: editingCustomer.lng,
    };
    saveCustomer(customerToSave);
    setEditingCustomer(null);
  };

  const handleDelete = () => {
    if (!editingCustomer?.id) return;
    const confirmDelete = window.confirm(
      `¿Estás seguro de eliminar a "${editingCustomer.alias}"?\n\nEsta acción eliminará el registro del cliente permanentemente. Su historial de ventas se mantendrá como anónimo.`
    );
    if (confirmDelete) {
      deleteCustomer(editingCustomer.id);
      setEditingCustomer(null);
    }
  };

  const handleGetLocation = () => {
    if (!navigator.geolocation) {
      alert("Tu dispositivo no soporta geolocalización.");
      return;
    }

    const btn = document.getElementById('gps-btn');
    if(btn) {
       btn.innerHTML = '<i class="fas fa-circle-notch animate-spin"></i> Obteniendo...';
       btn.classList.add('opacity-50', 'pointer-events-none');
    }

    navigator.geolocation.getCurrentPosition(
      (position) => {
        setEditingCustomer(prev => prev ? ({
          ...prev,
          lat: position.coords.latitude,
          lng: position.coords.longitude
        }) : null);

        if(btn) {
          btn.innerHTML = '<i class="fas fa-check"></i> Ubicación Capturada';
          btn.classList.remove('opacity-50', 'pointer-events-none', 'bg-emerald-50', 'text-emerald-600');
          btn.classList.add('bg-emerald-50', 'text-white');
          setTimeout(() => {
             btn.innerHTML = '<i class="fas fa-location-crosshairs"></i> Actualizar GPS';
             btn.classList.remove('bg-emerald-500', 'text-white');
             btn.classList.add('bg-emerald-50', 'text-emerald-600');
          }, 3000);
        }
      },
      (error) => {
        console.error(error);
        alert("Error al obtener ubicación. Asegúrate de dar permisos de ubicación a la app.");
        if(btn) {
          btn.innerHTML = '<i class="fas fa-triangle-exclamation"></i> Error';
          btn.classList.remove('opacity-50', 'pointer-events-none');
        }
      },
      { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 }
    );
  };

  const openGoogleMaps = (lat?: number, lng?: number) => {
    if (lat && lng) {
      window.open(`https://www.google.com/maps/search/?api=1&query=${lat},${lng}`, '_blank');
    } else {
      alert("Este cliente no tiene ubicación registrada.");
    }
  };

  // --- LOGICA DE EXPORTACIÓN E IMPORTACIÓN ---

  const downloadFile = (content: string, filename: string, type: string) => {
    const blob = new Blob([content], { type });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleExportCSV = () => {
    const headers = ["ID", "Nombre", "Alias", "Telefono", "Direccion", "Saldo", "Precio Especial", "Tipo Garrafon", "Lat", "Lng"];
    const rows = customers.map(c => [
      c.id,
      `"${c.name}"`,
      `"${c.alias}"`,
      c.phone || '',
      `"${c.address || ''}"`,
      c.balance,
      c.specialPrice || '',
      c.garrafonType || 'Generico',
      c.lat || '',
      c.lng || ''
    ]);
    const csvContent = [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
    downloadFile(csvContent, `Clientes_Aqua_${new Date().toISOString().split('T')[0]}.csv`, 'text/csv');
  };

  // --- NUEVA FUNCIÓN: IMPORTAR CONTACTOS DEL TELÉFONO ---
  const handleImportContacts = async () => {
    // Verificar soporte de la API de Contactos (Android Chrome / Capacitor)
    const nav = navigator as any;

    if ('contacts' in nav && 'ContactsManager' in window) {
      try {
        const props = ['name', 'tel', 'address'];
        const opts = { multiple: true };

        const contacts = await nav.contacts.select(props, opts);

        if (contacts.length > 0) {
           const newCustomers: Customer[] = contacts.map((c: any) => ({
             id: Math.random().toString(36).substr(2, 9),
             name: c.name[0] || 'Desconocido',
             alias: c.name[0] || 'Desconocido',
             phone: c.tel ? c.tel[0] : '',
             address: c.address ? c.address[0]?.addressLine : '',
             balance: 0,
             garrafonType: 'Generico'
           }));

           importCustomers(newCustomers);
           alert(`Se importaron ${newCustomers.length} contactos exitosamente.`);
        }
      } catch (ex) {
        // El usuario canceló o hubo error
        console.log(ex);
      }
    } else {
      // Fallback: Explicar que use CSV o manual
      alert("La importación directa de contactos no está soportada en este navegador/dispositivo. Por favor usa la opción de 'Importar CSV' o agrega manualmente.");
    }
  };

  const handleImportFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      if (!text) return;

      try {
        let importedCount = 0;
        const newCustomers: Customer[] = [];

        if (file.name.toLowerCase().endsWith('.csv')) {
          const lines = text.replace(/\r\n/g, '\n').replace(/\r/g, '\n').split('\n');
          if (lines.length > 0) {
            const headerLine = lines[0].toLowerCase();
            const headers = headerLine.split(',').map(h => h.trim().replace(/^"|"$/g, ''));

            const idxNombre = headers.findIndex(h => h.includes('nombre'));
            const idxAlias = headers.findIndex(h => h.includes('alias') || h.includes('comercial'));
            const idxTelefono = headers.findIndex(h => h.includes('telefono') || h.includes('celular') || h.includes('whatsapp'));
            const idxDireccion = headers.findIndex(h => h.includes('direccion') || h.includes('domicilio'));
            const idxSaldo = headers.findIndex(h => h.includes('saldo'));
            const idxPrecio = headers.findIndex(h => h.includes('precio'));

            lines.slice(1).forEach(line => {
              if (!line.trim()) return;
              const cols = line.split(',').map(c => c.replace(/^"|"$/g, '').trim());
              const finalName = (idxNombre !== -1 ? cols[idxNombre] : '') || (idxAlias !== -1 ? cols[idxAlias] : '') || 'Importado';
              const finalAlias = (idxAlias !== -1 ? cols[idxAlias] : '') || finalName;

              if (finalAlias) {
                newCustomers.push({
                  id: Math.random().toString(36).substr(2, 9),
                  name: finalName,
                  alias: finalAlias,
                  phone: idxTelefono !== -1 ? cols[idxTelefono] : '',
                  address: idxDireccion !== -1 ? cols[idxDireccion] : '',
                  balance: idxSaldo !== -1 ? (parseFloat(cols[idxSaldo]) || 0) : 0,
                  specialPrice: idxPrecio !== -1 ? (parseFloat(cols[idxPrecio]) || undefined) : undefined,
                  garrafonType: 'Generico',
                });
                importedCount++;
              }
            });
          }
        }

        if (importedCount > 0) {
          importCustomers(newCustomers);
          alert(`¡Éxito! Se importaron ${importedCount} clientes.`);
        } else {
          alert("No se encontraron datos válidos en el CSV.");
        }
      } catch (err) {
        alert("Error al procesar el archivo.");
      }
      if (fileInputRef.current) fileInputRef.current.value = '';
    };
    reader.readAsText(file);
  };

  // --- UI RENDER ---

  if (viewingHistory) {
    const customerSales = sales.filter(s => s.customerId === viewingHistory.id);
    const hasDebt = viewingHistory.balance > 0;
    const hasCredit = viewingHistory.balance < 0;

    return (
      <div className="h-full bg-sky-50 overflow-y-auto no-scrollbar pb-24">
        <ModuleHeader title={`Perfil: ${viewingHistory.alias}`} onBack={handleBackNavigation} />
        <div className="px-6 space-y-4">
          <RoundedCard className={`${hasDebt ? 'bg-red-500' : hasCredit ? 'bg-emerald-500' : 'bg-sky-600'} text-white shadow-lg border-none transition-colors duration-500`}>
             <div className="flex justify-between items-center">
                <div>
                   <span className="text-[10px] font-black uppercase opacity-70">
                     {hasDebt ? 'Estado: Adeudo' : hasCredit ? 'Estado: Saldo a Favor' : 'Estado: Al Corriente'}
                   </span>
                   <p className="text-3xl font-black">
                     ${Math.abs(viewingHistory.balance).toLocaleString()}
                   </p>
                </div>
                <div className="bg-white/20 p-4 rounded-2xl">
                   <i className={`fas ${hasDebt ? 'fa-hand-holding-dollar' : 'fa-piggy-bank'} text-2xl`}></i>
                </div>
             </div>
          </RoundedCard>

          {viewingHistory.address && (
            <div className="bg-white p-5 rounded-3xl shadow-sm border border-sky-50 flex items-start gap-3">
              <i className="fas fa-map-location-dot text-sky-300 mt-1"></i>
              <div>
                 <span className="text-[9px] font-black text-sky-400 uppercase block mb-1">Dirección Registrada</span>
                 <p className="text-sm font-bold text-sky-900 leading-tight">{viewingHistory.address}</p>
              </div>
            </div>
          )}

          <div className="grid grid-cols-2 gap-3">
             <div className="bg-white p-4 rounded-3xl shadow-sm border border-sky-50">
                <span className="text-[9px] font-black text-sky-400 uppercase block mb-1">WhatsApp</span>
                <p className="text-xs font-bold text-sky-900">{viewingHistory.phone || 'No registrado'}</p>
             </div>
             <div className="bg-white p-4 rounded-3xl shadow-sm border border-sky-50">
                <span className="text-[9px] font-black text-sky-400 uppercase block mb-1">Precio Esp.</span>
                <p className="text-xs font-bold text-sky-900">{viewingHistory.specialPrice ? `$${viewingHistory.specialPrice}` : 'Precio Base'}</p>
             </div>
          </div>

          <h4 className="text-[10px] font-black uppercase text-sky-400 tracking-widest px-2 mt-4">Transacciones Recientes</h4>
          {customerSales.length === 0 ? (
            <div className="text-center py-20 text-sky-300 italic animate-fadeIn">Sin compras registradas aún.</div>
          ) : (
            customerSales.map(s => (
              <RoundedCard key={s.id} className="py-5 border-none shadow-sm animate-fadeIn">
                <div className="flex justify-between items-start mb-3">
                  <div>
                    <span className="text-sky-900 font-black">{s.id}</span>
                    <p className="text-[10px] text-sky-400 font-bold uppercase">{new Date(s.timestamp).toLocaleDateString()}</p>
                  </div>
                  <span className="font-black text-sky-600 text-xl">${s.total}</span>
                </div>
                <div className="flex flex-wrap gap-2">
