          </div>
        )}
      </div>

      {selectedCustomerIds.size > 0 && selectedTemplate && !campaignMode && (
        <div className="fixed bottom-0 left-0 right-0 p-6 bg-white/95 border-t border-sky-100 shadow-2xl z-50 animate-fadeIn">
