                  </div>
                </div>
              ))
            )}
          </div>
        </section>

        {/* Top Customers */}
        <section className="space-y-4">
           <h4 className="text-[10px] font-black uppercase text-sky-400 tracking-widest px-2">Top Clientes Histórico</h4>
           <div className="bg-white p-2 rounded-[2rem] shadow-sm border border-white">
              {topCustomers.map((c, idx) => (
                 <div key={idx} className="flex items-center justify-between p-4 border-b border-sky-50 last:border-none">
                    <div className="flex items-center gap-3">
                       <div className={`w-8 h-8 rounded-full flex items-center justify-center font-black text-white text-[10px] ${idx === 0 ? 'bg-amber-400' : 'bg-sky-200'}`}>
                          {idx + 1}
                       </div>
                       <span className="text-xs font-bold text-sky-900">{c.alias}</span>
                    </div>
                    <span className="text-xs font-black text-sky-600">${c.total.toLocaleString()}</span>
                 </div>
              ))}
           </div>
        </section>

        {/* Assets & Inventory */}
        <section className="space-y-4">
          <h4 className="text-[10px] font-black uppercase text-sky-400 tracking-widest px-2">Inventario y Activos</h4>
