import React, { useState, useEffect } from 'react';
import { Product, Customer, CartItem, PaymentSplit, Sale, Employee, TicketConfig } from '../types';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';

export const POSModule: React.FC<{ onBack: () => void; user: Employee }> = ({ onBack, user }) => {
  const { products, customers, sales, addSale, ticketConfig } = useERPData();
  const [activeTab, setActiveTab] = useState<'sell' | 'history'>('sell');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [customer, setCustomer] = useState<Customer | null>(null);
  const [search, setSearch] = useState('');
  const [vacios, setVacios] = useState(0);

  // Lógica de Tiempo para Admin
  const getLocalISO = (d: Date = new Date()) => {
    const offset = d.getTimezoneOffset() * 60000;
    return new Date(d.getTime() - offset).toISOString().slice(0, 16);
  };

  const [manualDate, setManualDate] = useState<string>(getLocalISO());
  const [autoTime, setAutoTime] = useState(true);
  const [nowDisplay, setNowDisplay] = useState(new Date());

  // Ticket Modal State (Internal Viewer)
  const [viewingTicket, setViewingTicket] = useState<Sale | null>(null);

  const [paidCash, setPaidCash] = useState<string>('');
  const [paidTransfer, setPaidTransfer] = useState<string>('');

  // Efecto del Reloj
  useEffect(() => {
    let interval: any;
    if (autoTime) {
      interval = setInterval(() => {
        const d = new Date();
        setNowDisplay(d);
        setManualDate(getLocalISO(d));
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [autoTime]);

  const handleDateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setAutoTime(false);
    setManualDate(e.target.value);
  };

  const total = cart.reduce((sum, item) => {
    const price = (customer?.specialPrice && item.id === '1') ? customer.specialPrice : item.price;
    return sum + (price * item.quantity);
  }, 0);

  const totalPaid = (parseFloat(paidCash) || 0) + (parseFloat(paidTransfer) || 0);

  // Lógica de Deuda vs Cambio
  const remainingBalance = total - totalPaid;
  const isCreditSale = remainingBalance > 0.01; // Pequeño margen por decimales
  const change = Math.max(0, totalPaid - total);

  // Auto-calcular vacíos basado en garrafones vendidos (sugerencia)
  useEffect(() => {
    const garrafonesInCart = cart.filter(i => i.name.toLowerCase().includes('garraf') || i.category === 'Agua').reduce((acc, i) => acc + i.quantity, 0);
    if (cart.length > 0 && vacios === 0) {
      setVacios(garrafonesInCart);
    } else if (cart.length === 0) {
      setVacios(0);
    }
  }, [cart]);

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === product.id);
      if (existing) return prev.map(i => i.id === product.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const handleSendWhatsApp = (sale: Sale) => {
    // Buscar el cliente para asegurar datos actualizados
    const currentCustomer = customers.find(c => c.id === sale.customerId);
    const phone = currentCustomer?.phone?.replace(/\D/g, '') || '';

    if (!phone) return alert("El cliente no tiene teléfono registrado.");

    const itemsText = sale.items.map(i => `• ${i.quantity}x ${i.name}`).join('%0A');
    const debtMsg = sale.paidAmount < sale.total ? `%0A%0A⚠️ *Saldo Pendiente:* $${(sale.total - sale.paidAmount).toFixed(2)}` : '';

    const msg = `¡Hola ${sale.customerAlias}!%0A%0A*${ticketConfig.businessName}*%0AGracias por tu compra.%0A%0A*Detalles de tu pedido:*%0A${itemsText}%0A%0A*Envases Recibidos:* ${sale.emptyGarrafonsReturned}%0A*Total:* $${sale.total.toFixed(2)}${debtMsg}%0A*Ticket:* ${sale.id}%0A%0A_Validación de seguridad QR disponible en planta._`;
    window.open(`https://wa.me/52${phone}?text=${msg}`, '_blank');
  };

  const handleCheckout = () => {
    if (!customer) return alert("Selecciona un cliente.");
    if (cart.length === 0) return alert("El carrito está vacío.");

    const splits: PaymentSplit[] = [];
    if (parseFloat(paidCash) > 0) splits.push({ method: 'Efectivo', amount: parseFloat(paidCash) });
    if (parseFloat(paidTransfer) > 0) splits.push({ method: 'Transferencia', amount: parseFloat(paidTransfer) });

    const sale = addSale(
      customer.id, cart, total, totalPaid, splits, vacios, 
      user.role === 'Administrador' ? new Date(manualDate).getTime() : undefined
    );

    // Abrir visor de ticket interno
    setViewingTicket(sale);

    // Resetear formulario
    setCart([]);
    setCustomer(null);
    setSearch('');
    setPaidCash('');
    setPaidTransfer('');
    setVacios(0);
    if (user.role === 'Administrador') setAutoTime(true); 
  };

  // --- INTERNAL TICKET RENDERER ---
  const TicketModal = ({ sale, config, onClose }: { sale: Sale, config: TicketConfig, onClose: () => void }) => {
    const qrData = btoa(`AQUA-PRO-SECURE|${JSON.stringify({ id: sale.id, total: sale.total })}`);
    const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(qrData)}`;

    const handlePrint = () => {
      window.print();
    };

    return (
      <div className="fixed inset-0 z-[100] bg-slate-900/90 backdrop-blur-sm flex flex-col items-center justify-center p-4 overflow-y-auto">
        <div className="bg-white w-full max-w-sm shadow-2xl overflow-hidden print:w-full print:shadow-none print:max-w-none">
          {/* Action Bar (Hidden when printing) */}
          <div className="bg-slate-100 p-4 flex justify-between items-center print:hidden border-b border-slate-200">
             <span className="text-xs font-black uppercase text-slate-500">Vista Previa</span>
             <button onClick={onClose} className="w-8 h-8 flex items-center justify-center bg-slate-200 rounded-full text-slate-600"><i className="fas fa-times"></i></button>
          </div>

          {/* Ticket Content (Printable Area) */}
          <div className="p-8 text-center font-mono text-black leading-tight" id="printable-ticket">
             {config.logoUrl && <img src={config.logoUrl} alt="Logo" className="w-24 h-24 object-contain mx-auto mb-4 grayscale" />}

             <h2 className="text-xl font-black uppercase mb-1">{config.businessName}</h2>
             {config.slogan && <p className="text-[10px] italic mb-4">"{config.slogan}"</p>}

             <div className="text-[10px] border-b border-black pb-4 mb-4 space-y-1">
                <p>RFC: {config.rfc}</p>
                <p>{config.address}</p>
                <p>Tel: {config.phone}</p>
             </div>

             <div className="text-left text-xs mb-4 space-y-1">
                <p>FOLIO: <span className="font-bold">{sale.id}</span></p>
                <p>FECHA: {new Date(sale.timestamp).toLocaleString()}</p>
                <p>CLIENTE: {sale.customerAlias.toUpperCase()}</p>
             </div>

             <table className="w-full text-xs mb-4 border-collapse">
               <thead>
                 <tr className="border-b border-black border-dashed">
                   <th className="text-left py-1">CANT</th>
                   <th className="text-left py-1">DESC</th>
                   <th className="text-right py-1">IMP</th>
                 </tr>
               </thead>
               <tbody>
                 {sale.items.map((item, i) => (
                   <tr key={i}>
                     <td className="text-left py-1 align-top">{item.quantity}</td>
                     <td className="text-left py-1 align-top">{item.name.slice(0, 20)}</td>
                     <td className="text-right py-1 align-top">${(item.quantity * item.price).toFixed(2)}</td>
                   </tr>
                 ))}
               </tbody>
             </table>

             <div className="border-t-2 border-black pt-2 mb-2 text-right">
                <p className="text-lg font-black">TOTAL: ${sale.total.toFixed(2)}</p>
             </div>

             <div className="text-right text-[10px] mb-4 space-y-1">
                <p>RECIBIDO: ${sale.paidAmount.toFixed(2)}</p>
                {sale.paidAmount < sale.total ? (
                   <p className="font-bold">SALDO PENDIENTE: ${(sale.total - sale.paidAmount).toFixed(2)}</p>
                ) : (
                   <p>CAMBIO: ${sale.change.toFixed(2)}</p>
                )}
             </div>

             {sale.emptyGarrafonsReturned > 0 && (
                <div className="border border-black p-2 mb-4 text-xs font-bold">
                   ENVASES RECIBIDOS: {sale.emptyGarrafonsReturned}
                </div>
             )}

             <div className="border-t border-dashed border-black pt-4 mb-4">
                <p className="text-xs font-bold mb-1">{config.footerMessage}</p>
                <p className="text-[9px] italic">{config.extraNote}</p>
             </div>

             <div className="flex flex-col items-center">
                <img src={qrUrl} alt="QR" className="w-24 h-24 mb-2" />
                <p className="text-[8px] uppercase tracking-widest">Escanea para validar</p>
             </div>
          </div>

          {/* Footer Actions (Hidden when printing) */}
          <div className="p-4 bg-slate-50 border-t border-slate-200 space-y-3 print:hidden">
             <button onClick={handlePrint} className="w-full bg-slate-800 text-white py-4 rounded-xl font-black uppercase text-xs flex items-center justify-center gap-2 shadow-lg">
                <i className="fas fa-print"></i> Imprimir / Guardar PDF
             </button>
             <button onClick={() => handleSendWhatsApp(sale)} className="w-full bg-emerald-500 text-white py-4 rounded-xl font-black uppercase text-xs flex items-center justify-center gap-2 shadow-lg">
                <i className="fab fa-whatsapp"></i> Enviar WhatsApp
             </button>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="h-full flex flex-col animate-fadeIn bg-sky-50 pb-24 overflow-hidden relative">
      <ModuleHeader title="Punto de Venta" onBack={onBack} />

      <div className="px-6 flex gap-2 mb-4">
        <button onClick={() => setActiveTab('sell')} className={`flex-1 py-3 rounded-2xl text-xs font-bold ${activeTab === 'sell' ? 'bg-sky-600 text-white shadow-lg' : 'bg-white text-sky-400'}`}>Nueva Venta</button>
        <button onClick={() => setActiveTab('history')} className={`flex-1 py-3 rounded-2xl text-xs font-bold ${activeTab === 'history' ? 'bg-sky-600 text-white shadow-lg' : 'bg-white text-sky-400'}`}>Historial</button>
      </div>

      {activeTab === 'sell' ? (
        <div className="flex-1 overflow-y-auto px-6 space-y-6 pb-32 no-scrollbar">
          {/* Admin Date Control */}
          {user.role === 'Administrador' && (
            <div className={`p-4 rounded-[2.2rem] border transition-all duration-500 ${autoTime ? 'bg-white border-sky-100' : 'bg-amber-50 border-amber-200 shadow-inner'}`}>
              <div className="flex justify-between items-center mb-3">
                <div className="flex items-center gap-2">
                  <div className={`w-2.5 h-2.5 rounded-full ${autoTime ? 'bg-emerald-500 animate-pulse' : 'bg-amber-500'}`}></div>
