                         </div>
                         <span className="text-xs font-bold text-sky-900">{c.alias}</span>
                      </div>
                      <span className="text-xs font-black text-sky-600">${c.total.toLocaleString()}</span>
                   </div>
                ))
              )}
           </div>
        </section>

        {/* Assets & Inventory */}
        <section className="space-y-4">
          <h4 className="text-[10px] font-black uppercase text-sky-400 tracking-widest px-2">Inventario y Activos (Actual)</h4>
          <div className="grid grid-cols-2 gap-4">
            <div className="bg-white p-6 rounded-[2rem] shadow-sm border border-white">
              <p className="text-[9px] font-black uppercase text-sky-400 tracking-widest mb-1">Valor Stock</p>
              <p className="text-xl font-black text-sky-900">${totalInventoryValue.toLocaleString()}</p>
