                <button 
                  onClick={() => setShowExitConfirm(false)}
                  className="flex-1 py-4 bg-sky-50 text-sky-600 rounded-2xl font-black uppercase text-[10px] tracking-widest active:scale-95 transition-all"
                >
                  Continuar
