             <button onClick={() => setLoadingVehicleId(null)} className="px-8 py-3 bg-emerald-500 text-white rounded-2xl font-black text-xs uppercase shadow-lg shadow-emerald-200">
               Listo
             </button>
          </div>
        </div>
      </div>
    );
  };

