  const [customer, setCustomer] = useState<Customer | null>(null);
  const [search, setSearch] = useState('');
  const [vacios, setVacios] = useState(0);

  // Lógica de Tiempo para Admin
  const getLocalISO = (d: Date = new Date()) => {
    const offset = d.getTimezoneOffset() * 60000;
    return new Date(d.getTime() - offset).toISOString().slice(0, 16);
  };

  const [manualDate, setManualDate] = useState<string>(getLocalISO());
  const [autoTime, setAutoTime] = useState(true);
  const [nowDisplay, setNowDisplay] = useState(new Date());

  // Ticket Modal State (Internal Viewer)
  const [viewingTicket, setViewingTicket] = useState<Sale | null>(null);

  const [paidCash, setPaidCash] = useState<string>('');
  const [paidTransfer, setPaidTransfer] = useState<string>('');

  // Efecto del Reloj
  useEffect(() => {
    let interval: any;
    if (autoTime) {
      interval = setInterval(() => {
        const d = new Date();
        setNowDisplay(d);
        setManualDate(getLocalISO(d));
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [autoTime]);

  const handleDateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setAutoTime(false);
    setManualDate(e.target.value);
  };

  const total = cart.reduce((sum, item) => {
    const price = (customer?.specialPrice && item.id === '1') ? customer.specialPrice : item.price;
    return sum + (price * item.quantity);
  }, 0);

  const totalPaid = (parseFloat(paidCash) || 0) + (parseFloat(paidTransfer) || 0);

  // Lógica de Deuda vs Cambio
  const remainingBalance = total - totalPaid;
  const isCreditSale = remainingBalance > 0.01; // Pequeño margen por decimales
  const change = Math.max(0, totalPaid - total);

  // Auto-calcular vacíos basado en garrafones vendidos (sugerencia)
  useEffect(() => {
    const garrafonesInCart = cart.filter(i => i.name.toLowerCase().includes('garraf') || i.category === 'Agua').reduce((acc, i) => acc + i.quantity, 0);
    if (cart.length > 0 && vacios === 0) {
      setVacios(garrafonesInCart);
    } else if (cart.length === 0) {
      setVacios(0);
    }
  }, [cart]);

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === product.id);
      if (existing) return prev.map(i => i.id === product.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  // NEW: Decrease quantity functionality
  const decreaseQuantity = (productId: string) => {
    setCart(prev => prev.map(item => {
      if (item.id === productId) {
        return { ...item, quantity: Math.max(0, item.quantity - 1) };
      }
      return item;
    }).filter(item => item.quantity > 0));
  };

  // NEW: Remove item completely
  const removeFromCart = (productId: string) => {
    setCart(prev => prev.filter(item => item.id !== productId));
  };

  const handleSendWhatsApp = (sale: Sale) => {
    // Buscar el cliente para asegurar datos actualizados
    const currentCustomer = customers.find(c => c.id === sale.customerId);
    const phone = currentCustomer?.phone?.replace(/\D/g, '') || '';

    if (!phone) return alert("El cliente no tiene teléfono registrado.");

    const itemsText = sale.items.map(i => `• ${i.quantity}x ${i.name}`).join('%0A');
    const debtMsg = sale.paidAmount < sale.total ? `%0A%0A⚠️ *Saldo Pendiente:* $${(sale.total - sale.paidAmount).toFixed(2)}` : '';

    const msg = `¡Hola ${sale.customerAlias}!%0A%0A*${ticketConfig.businessName}*%0AGracias por tu compra.%0A%0A*Detalles de tu pedido:*%0A${itemsText}%0A%0A*Envases Recibidos:* ${sale.emptyGarrafonsReturned}%0A*Total:* $${sale.total.toFixed(2)}${debtMsg}%0A*Ticket:* ${sale.id}%0A%0A_Validación de seguridad QR disponible en planta._`;
    window.open(`https://wa.me/52${phone}?text=${msg}`, '_blank');
  };

  const handleCheckout = () => {
    if (!customer) return alert("Selecciona un cliente.");
    if (cart.length === 0) return alert("El carrito está vacío.");

    const splits: PaymentSplit[] = [];
    if (parseFloat(paidCash) > 0) splits.push({ method: 'Efectivo', amount: parseFloat(paidCash) });
    if (parseFloat(paidTransfer) > 0) splits.push({ method: 'Transferencia', amount: parseFloat(paidTransfer) });

    const sale = addSale(
      customer.id, cart, total, totalPaid, splits, vacios, 
      user.role === 'Administrador' ? new Date(manualDate).getTime() : undefined
    );

    // Abrir visor de ticket interno
    setViewingTicket(sale);

    // Resetear formulario para que al cerrar el ticket ya esté listo
    setCart([]);
    setCustomer(null);
    setSearch('');
    setPaidCash('');
    setPaidTransfer('');
    setVacios(0);
    if (user.role === 'Administrador') setAutoTime(true); 
  };

  // --- INTERNAL TICKET RENDERER ---
  const TicketModal = ({ sale, config, onClose }: { sale: Sale, config: TicketConfig, onClose: () => void }) => {
    const qrData = btoa(`AQUA-PRO-SECURE|${JSON.stringify({ id: sale.id, total: sale.total })}`);
    const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(qrData)}`;

    const handlePrint = () => {
      window.print();
    };

    return (
      <div className="fixed inset-0 z-[100] bg-slate-900/90 backdrop-blur-sm flex flex-col items-center justify-center p-4 overflow-y-auto animate-fadeIn">
        <div className="bg-white w-full max-w-sm shadow-2xl overflow-hidden print:w-full print:shadow-none print:max-w-none rounded-[2rem]">
          {/* Action Bar (Hidden when printing) */}
          <div className="bg-slate-100 p-4 flex justify-between items-center print:hidden border-b border-slate-200">
             <span className="text-xs font-black uppercase text-slate-500">Ticket Generado</span>
             <button onClick={onClose} className="w-8 h-8 flex items-center justify-center bg-slate-200 rounded-full text-slate-600 active:scale-90 transition-transform"><i className="fas fa-times"></i></button>
          </div>

          {/* Ticket Content (Printable Area) */}
          <div className="p-8 text-center font-mono text-black leading-tight" id="printable-ticket">
             {config.logoUrl && <img src={config.logoUrl} alt="Logo" className="w-24 h-24 object-contain mx-auto mb-4 grayscale" />}

             <h2 className="text-xl font-black uppercase mb-1">{config.businessName}</h2>
             {config.slogan && <p className="text-[10px] italic mb-4">"{config.slogan}"</p>}

             <div className="text-[10px] border-b border-black pb-4 mb-4 space-y-1">
                <p>RFC: {config.rfc}</p>
                <p>{config.address}</p>
                <p>Tel: {config.phone}</p>
             </div>

             <div className="text-left text-xs mb-4 space-y-1">
                <p>FOLIO: <span className="font-bold">{sale.id}</span></p>
                <p>FECHA: {new Date(sale.timestamp).toLocaleString()}</p>
                <p>CLIENTE: {sale.customerAlias.toUpperCase()}</p>
             </div>

             <table className="w-full text-xs mb-4 border-collapse">
               <thead>
                 <tr className="border-b border-black border-dashed">
                   <th className="text-left py-1">CANT</th>
                   <th className="text-left py-1">DESC</th>
                   <th className="text-right py-1">IMP</th>
                 </tr>
               </thead>
               <tbody>
                 {sale.items.map((item, i) => (
                   <tr key={i}>
                     <td className="text-left py-1 align-top">{item.quantity}</td>
                     <td className="text-left py-1 align-top">{item.name.slice(0, 20)}</td>
                     <td className="text-right py-1 align-top">${(item.quantity * item.price).toFixed(2)}</td>
                   </tr>
                 ))}
               </tbody>
             </table>

             <div className="border-t-2 border-black pt-2 mb-2 text-right">
                <p className="text-lg font-black">TOTAL: ${sale.total.toFixed(2)}</p>
             </div>

             <div className="text-right text-[10px] mb-4 space-y-1">
                <p>RECIBIDO: ${sale.paidAmount.toFixed(2)}</p>
                {sale.paidAmount < sale.total ? (
                   <p className="font-bold">SALDO PENDIENTE: ${(sale.total - sale.paidAmount).toFixed(2)}</p>
                ) : (
                   <p>CAMBIO: ${sale.change.toFixed(2)}</p>
                )}
             </div>

             {sale.emptyGarrafonsReturned > 0 && (
                <div className="border border-black p-2 mb-4 text-xs font-bold">
                   ENVASES RECIBIDOS: {sale.emptyGarrafonsReturned}
                </div>
             )}

             <div className="border-t border-dashed border-black pt-4 mb-4">
                <p className="text-xs font-bold mb-1">{config.footerMessage}</p>
                <p className="text-[9px] italic">{config.extraNote}</p>
             </div>

             <div className="flex flex-col items-center">
                <img src={qrUrl} alt="QR" className="w-24 h-24 mb-2" />
                <p className="text-[8px] uppercase tracking-widest">Escanea para validar</p>
             </div>
          </div>

          {/* Footer Actions (Hidden when printing) */}
          <div className="p-4 bg-slate-50 border-t border-slate-200 space-y-3 print:hidden">
             <div className="flex gap-2">
               <button onClick={handlePrint} className="flex-1 bg-slate-800 text-white py-4 rounded-xl font-black uppercase text-[10px] flex items-center justify-center gap-2 shadow-lg active:scale-95 transition-transform">
                  <i className="fas fa-print"></i> Imprimir
               </button>
               <button onClick={() => handleSendWhatsApp(sale)} className="flex-1 bg-emerald-500 text-white py-4 rounded-xl font-black uppercase text-[10px] flex items-center justify-center gap-2 shadow-lg active:scale-95 transition-transform">
                  <i className="fab fa-whatsapp"></i> WhatsApp
               </button>
             </div>
             <button onClick={onClose} className="w-full bg-white text-sky-600 border-2 border-sky-100 py-4 rounded-xl font-black uppercase text-[10px] flex items-center justify-center gap-2 shadow-sm active:scale-95 transition-transform">
                <i className="fas fa-check"></i> Finalizar Venta
             </button>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="h-full flex flex-col animate-fadeIn bg-sky-50 pb-24 overflow-hidden relative">
      <ModuleHeader title="Punto de Venta" onBack={onBack} />

      <div className="px-6 flex gap-2 mb-4">
        <button onClick={() => setActiveTab('sell')} className={`flex-1 py-3 rounded-2xl text-xs font-bold ${activeTab === 'sell' ? 'bg-sky-600 text-white shadow-lg' : 'bg-white text-sky-400'}`}>Nueva Venta</button>
        <button onClick={() => setActiveTab('history')} className={`flex-1 py-3 rounded-2xl text-xs font-bold ${activeTab === 'history' ? 'bg-sky-600 text-white shadow-lg' : 'bg-white text-sky-400'}`}>Historial</button>
      </div>

      {activeTab === 'sell' ? (
        <div className="flex-1 overflow-y-auto px-6 space-y-6 pb-32 no-scrollbar">
          {/* Admin Date Control */}
          {user.role === 'Administrador' && (
            <div className={`p-4 rounded-[2.2rem] border transition-all duration-500 ${autoTime ? 'bg-white border-sky-100' : 'bg-amber-50 border-amber-200 shadow-inner'}`}>
              <div className="flex justify-between items-center mb-3">
                <div className="flex items-center gap-2">
                  <div className={`w-2.5 h-2.5 rounded-full ${autoTime ? 'bg-emerald-500 animate-pulse' : 'bg-amber-500'}`}></div>
                  <label className="text-[10px] font-black uppercase tracking-widest text-sky-900">
                    {autoTime ? 'TIEMPO REAL (INTERNET)' : 'MODO MANUAL (EDITANDO)'}
                  </label>
                </div>
                {!autoTime && (
                  <button onClick={() => setAutoTime(true)} className="flex items-center gap-1 text-[9px] font-black text-sky-500 uppercase bg-sky-50 px-3 py-1.5 rounded-full active:scale-95 transition-transform">
                    <i className="fas fa-rotate"></i> Sincronizar
                  </button>
                )}
              </div>

              <div className="flex gap-3 items-center">
                <div className="flex-1 relative">
                  <input 
                    type="datetime-local" 
                    className={`w-full border-none rounded-2xl p-4 text-xs font-black shadow-sm outline-none transition-all ${
                      autoTime 
                        ? 'bg-sky-50 text-sky-400 pointer-events-none opacity-80' 
                        : 'bg-white text-amber-600 ring-2 ring-amber-200'
                    }`}
                    value={manualDate}
                    onChange={handleDateChange}
                  />
                  {autoTime && (
                    <div className="absolute right-4 top-1/2 -translate-y-1/2 text-emerald-500 text-lg font-black tracking-tighter tabular-nums">
                      {nowDisplay.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit', second:'2-digit'})}
                    </div>
                  )}
                </div>
              </div>
            </div>
          )}

          <section>
            <div className="relative">
              <input type="text" placeholder="Buscar Cliente..." className="w-full bg-white border-none rounded-[2rem] py-5 px-8 shadow-sm outline-none" value={search} onChange={e => setSearch(e.target.value)} />
              {search && !customer && (
                <div className="absolute top-full left-0 right-0 bg-white shadow-2xl rounded-3xl mt-2 z-50 overflow-hidden border border-sky-50">
                  {customers.filter(c => c.alias.toLowerCase().includes(search.toLowerCase())).map(c => (
                    <button key={c.id} onClick={() => { setCustomer(c); setSearch(c.alias); }} className="w-full text-left p-4 hover:bg-sky-50 font-bold border-b border-sky-50 flex justify-between items-center">
                      <span className="text-sky-900">{c.alias}</span>
                      <span className="text-[10px] bg-sky-50 text-sky-400 px-3 py-1 rounded-full font-black">${c.balance}</span>
                    </button>
                  ))}
                </div>
              )}
            </div>
            {customer && (
              <div className="mt-4 flex items-center justify-between bg-sky-600 text-white p-4 rounded-[1.8rem] shadow-lg animate-fadeIn">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-white/20 rounded-2xl flex items-center justify-center"><i className="fas fa-user"></i></div>
                  <div>
                    <span className="text-[8px] font-black uppercase opacity-60 block">Cliente Activo</span>
                    <span className="font-black text-sm">{customer.alias}</span>
                    {customer.balance > 0 && (
                      <span className="text-[9px] bg-red-500/30 px-2 py-0.5 rounded ml-2 font-bold">Adeudo: ${customer.balance}</span>
                    )}
                  </div>
                </div>
                <button onClick={() => {setCustomer(null); setSearch('');}} className="w-10 h-10 bg-white/10 rounded-full flex items-center justify-center active:scale-90 transition-all"><i className="fas fa-times"></i></button>
              </div>
            )}
          </section>

          <div className="grid grid-cols-2 gap-3">
            {products.map(p => (
              <button key={p.id} onClick={() => addToCart(p)} className="bg-white p-5 rounded-[2.2rem] shadow-sm active:bg-sky-50 text-left relative overflow-hidden group border border-transparent hover:border-sky-100">
                <div className="text-xs font-black text-sky-900 uppercase tracking-tight mb-1">{p.name}</div>
                <div className="text-sky-600 font-black text-lg">${p.price}</div>
                <div className="absolute -bottom-2 -right-2 w-12 h-12 bg-sky-50 text-sky-100 flex items-center justify-center rounded-tl-3xl group-active:text-sky-200 transition-colors">
                  <i className="fas fa-plus"></i>
                </div>
              </button>
            ))}
          </div>

          {cart.length > 0 && (
            <RoundedCard className="shadow-2xl border-2 border-white">
              <div className="flex justify-between items-start mb-6">
                <div>
                  <span className="text-[10px] text-sky-400 font-black uppercase mb-1 block">Monto a Liquidar</span>
                  <span className="text-4xl font-black text-sky-900 tracking-tighter">${total.toFixed(2)}</span>
                </div>
                <button onClick={() => setCart([])} className="text-rose-400 text-xs font-bold uppercase underline">Vaciar</button>
              </div>

              <div className="space-y-3 mb-6">
                {cart.map(i => (
                  <div key={i.id} className="flex justify-between items-center bg-sky-50/50 p-2 rounded-2xl border border-sky-100">
                    <div className="flex flex-col">
                       <span className="text-[10px] font-black text-sky-900 uppercase">{i.name}</span>
                       <span className="text-xs font-bold text-sky-600">${(i.quantity * i.price).toFixed(2)}</span>
                    </div>

                    <div className="flex items-center gap-2 bg-white rounded-xl shadow-sm p-1">
                       <button onClick={() => decreaseQuantity(i.id)} className="w-8 h-8 flex items-center justify-center bg-sky-50 text-sky-600 rounded-lg active:bg-sky-200 transition-colors font-bold">-</button>
                       <span className="text-sm font-black text-sky-900 w-6 text-center">{i.quantity}</span>
                       <button onClick={() => addToCart(i)} className="w-8 h-8 flex items-center justify-center bg-sky-600 text-white rounded-lg active:scale-95 transition-transform font-bold">+</button>
                    </div>

                    <button onClick={() => removeFromCart(i.id)} className="w-8 h-8 flex items-center justify-center text-rose-400 hover:text-rose-600">
                       <i className="fas fa-trash"></i>
                    </button>
                  </div>
                ))}
              </div>

              {/* Control de Garrafones Vacíos */}
              <div className="mb-6 bg-white p-4 rounded-3xl border border-sky-100 flex justify-between items-center">
                 <span className="text-[10px] font-black text-sky-400 uppercase tracking-tight ml-2">Garrafones Vacíos Recibidos</span>
                 <div className="flex items-center gap-3 bg-sky-50 rounded-2xl p-1">
                    <button onClick={() => setVacios(Math.max(0, vacios - 1))} className="w-8 h-8 flex items-center justify-center bg-white text-sky-600 rounded-xl font-black shadow-sm">-</button>
                    <span className="text-lg font-black text-sky-900 w-6 text-center">{vacios}</span>
                    <button onClick={() => setVacios(vacios + 1)} className="w-8 h-8 flex items-center justify-center bg-sky-600 text-white rounded-xl font-black shadow-lg">+</button>
                 </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[9px] font-black text-sky-400 uppercase ml-2">Efectivo</label>
                  <input type="number" value={paidCash} onChange={e => setPaidCash(e.target.value)} className="w-full bg-sky-50 p-4 rounded-2xl font-black text-lg focus:ring-2 ring-sky-200 outline-none" placeholder="$ 0.00" />
                </div>
                <div className="space-y-1">
                  <label className="text-[9px] font-black text-sky-400 uppercase ml-2">Transf.</label>
                  <input type="number" value={paidTransfer} onChange={e => setPaidTransfer(e.target.value)} className="w-full bg-sky-50 p-4 rounded-2xl font-black text-lg focus:ring-2 ring-sky-200 outline-none" placeholder="$ 0.00" />
                </div>
              </div>

              <div className={`mt-4 p-5 rounded-[1.8rem] flex justify-between items-center border transition-colors ${isCreditSale ? 'bg-amber-50 border-amber-100' : 'bg-emerald-50 border-emerald-100'}`}>
                <div>
                  <span className={`text-[10px] font-black uppercase tracking-widest block ${isCreditSale ? 'text-amber-700' : 'text-emerald-700'}`}>
                    {isCreditSale ? 'Saldo Pendiente (Crédito)' : 'Cambio Sugerido'}
                  </span>
                  <span className={`text-2xl font-black tracking-tighter ${isCreditSale ? 'text-amber-600' : 'text-emerald-600'}`}>
                    ${isCreditSale ? remainingBalance.toFixed(2) : change.toFixed(2)}
                  </span>
                </div>
                <div className={`w-12 h-12 bg-white rounded-2xl flex items-center justify-center shadow-sm ${isCreditSale ? 'text-amber-500 shadow-amber-100' : 'text-emerald-500 shadow-emerald-100'}`}>
                  <i className={`fas ${isCreditSale ? 'fa-file-invoice-dollar' : 'fa-hand-holding-dollar'} text-xl`}></i>
                </div>
              </div>
            </RoundedCard>
          )}
        </div>
      ) : (
        <div className="flex-1 overflow-y-auto px-6 space-y-3 pb-10 no-scrollbar">
          {sales.length === 0 ? (
            <div className="text-center py-20 opacity-30">
               <i className="fas fa-receipt text-6xl mb-4"></i>
               <p className="text-xs font-black uppercase">Sin historial reciente</p>
            </div>
          ) : (
            sales.map(s => (
              <RoundedCard key={s.id} className="py-5 border-none shadow-sm group">
                <div className="flex justify-between items-start">
                  <div className="flex gap-4">
                    <div className="w-12 h-12 bg-sky-50 text-sky-600 rounded-2xl flex items-center justify-center text-xl">
                      <i className="fas fa-receipt"></i>
                    </div>
                    <div>
                      <h4 className="font-black text-sky-900 text-sm leading-tight">{s.customerAlias}</h4>
                      <p className="text-[9px] text-sky-400 font-bold uppercase mt-1">{new Date(s.timestamp).toLocaleString()}</p>
                      {s.paidAmount < s.total && (
                        <span className="text-[9px] text-amber-500 font-black uppercase bg-amber-50 px-2 py-0.5 rounded mt-1 inline-block">Crédito</span>
                      )}
                    </div>
                  </div>
                  <div className="text-right">
                    <span className="font-black text-sky-600 text-xl tracking-tighter">${s.total}</span>
                    <p className="text-[8px] font-black text-sky-300 uppercase">{s.id}</p>
                  </div>
                </div>
                <div className="flex gap-2 mt-5">
                   <button onClick={() => setViewingTicket(s)} className="flex-1 text-[9px] font-black uppercase bg-sky-100 text-sky-600 px-3 py-3 rounded-xl flex items-center justify-center gap-2 active:bg-sky-200 transition-colors">
                    <i className="fas fa-eye"></i> Ver Ticket
                   </button>
                   <button onClick={() => handleSendWhatsApp(s)} className="flex-1 text-[9px] font-black uppercase bg-emerald-100 text-emerald-600 px-3 py-3 rounded-xl flex items-center justify-center gap-2 active:bg-emerald-200 transition-colors">
                    <i className="fab fa-whatsapp"></i> WA
                   </button>
                </div>
              </RoundedCard>
            ))
          )}
        </div>
      )}

      {activeTab === 'sell' && (
        <div className="fixed bottom-0 left-0 right-0 p-6 bg-white/95 border-t border-sky-100 shadow-2xl z-50">
          <ActionButton onClick={handleCheckout} disabled={!customer || cart.length === 0}>
             {isCreditSale ? 'Registrar Venta a Crédito' : 'Completar Venta'}
          </ActionButton>
        </div>
      )}

      {/* Internal Ticket Viewer Modal */}
      {viewingTicket && (
        <TicketModal 
          sale={viewingTicket} 
          config={ticketConfig} 
          onClose={() => setViewingTicket(null)} 
        />
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Product, Customer, CartItem, PaymentSplit, Sale, Employee, TicketConfig } from '../types';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';

// --- COMPONENTE TICKET MODAL (EXTRAÍDO) ---
