  const qrData = btoa(`AQUA-PRO-SECURE|${JSON.stringify({ id: sale.id, total: sale.total })}`);
  const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(qrData)}`;

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="fixed inset-0 z-[100] bg-slate-900/90 backdrop-blur-sm flex flex-col items-center justify-center p-4 overflow-y-auto animate-fadeIn">
      <div className="bg-white w-full max-w-sm shadow-2xl overflow-hidden print:w-full print:shadow-none print:max-w-none rounded-[2rem]">
        {/* Action Bar (Hidden when printing) */}
        <div className="bg-slate-100 p-4 flex justify-between items-center print:hidden border-b border-slate-200">
            <span className="text-xs font-black uppercase text-slate-500">Ticket Generado</span>
            <button onClick={onClose} className="w-8 h-8 flex items-center justify-center bg-slate-200 rounded-full text-slate-600 active:scale-90 transition-transform"><i className="fas fa-times"></i></button>
        </div>

        {/* Ticket Content (Printable Area) */}
        <div className="p-8 text-center font-mono text-black leading-tight" id="printable-ticket">
            {config.logoUrl && <img src={config.logoUrl} alt="Logo" className="w-24 h-24 object-contain mx-auto mb-4 grayscale" />}

            <h2 className="text-xl font-black uppercase mb-1">{config.businessName}</h2>
            {config.slogan && <p className="text-[10px] italic mb-4">"{config.slogan}"</p>}

            <div className="text-[10px] border-b border-black pb-4 mb-4 space-y-1">
              <p>RFC: {config.rfc}</p>
              <p>{config.address}</p>
              <p>Tel: {config.phone}</p>
            </div>

            <div className="text-left text-xs mb-4 space-y-1">
              <p>FOLIO: <span className="font-bold">{sale.id}</span></p>
              <p>FECHA: {new Date(sale.timestamp).toLocaleString()}</p>
              <p>CLIENTE: {sale.customerAlias.toUpperCase()}</p>
            </div>

            <table className="w-full text-xs mb-4 border-collapse">
              <thead>
                <tr className="border-b border-black border-dashed">
                  <th className="text-left py-1">CANT</th>
                  <th className="text-left py-1">DESC</th>
                  <th className="text-right py-1">IMP</th>
                </tr>
              </thead>
              <tbody>
                {sale.items.map((item, i) => (
                  <tr key={i}>
                    <td className="text-left py-1 align-top">{item.quantity}</td>
                    <td className="text-left py-1 align-top">{item.name.slice(0, 20)}</td>
                    <td className="text-right py-1 align-top">${(item.quantity * item.price).toFixed(2)}</td>
                  </tr>
                ))}
              </tbody>
            </table>

            <div className="border-t-2 border-black pt-2 mb-2 text-right">
              <p className="text-lg font-black">TOTAL: ${sale.total.toFixed(2)}</p>
            </div>

            <div className="text-right text-[10px] mb-4 space-y-1">
              <p>RECIBIDO: ${sale.paidAmount.toFixed(2)}</p>
              {sale.paidAmount < sale.total ? (
                  <p className="font-bold">SALDO PENDIENTE: ${(sale.total - sale.paidAmount).toFixed(2)}</p>
              ) : (
                  <p>CAMBIO: ${sale.change.toFixed(2)}</p>
              )}
            </div>

            {sale.emptyGarrafonsReturned > 0 && (
              <div className="border border-black p-2 mb-4 text-xs font-bold">
                  ENVASES RECIBIDOS: {sale.emptyGarrafonsReturned}
              </div>
            )}

            <div className="border-t border-dashed border-black pt-4 mb-4">
              <p className="text-xs font-bold mb-1">{config.footerMessage}</p>
              <p className="text-[9px] italic">{config.extraNote}</p>
            </div>

            <div className="flex flex-col items-center">
              <img src={qrUrl} alt="QR" className="w-24 h-24 mb-2" />
              <p className="text-[8px] uppercase tracking-widest">Escanea para validar</p>
            </div>
        </div>

        {/* Footer Actions (Hidden when printing) */}
        <div className="p-4 bg-slate-50 border-t border-slate-200 space-y-3 print:hidden">
            <div className="flex gap-2">
              <button onClick={handlePrint} className="flex-1 bg-slate-800 text-white py-4 rounded-xl font-black uppercase text-[10px] flex items-center justify-center gap-2 shadow-lg active:scale-95 transition-transform">
                  <i className="fas fa-print"></i> Imprimir
              </button>
              <button onClick={onWhatsApp} className="flex-1 bg-emerald-500 text-white py-4 rounded-xl font-black uppercase text-[10px] flex items-center justify-center gap-2 shadow-lg active:scale-95 transition-transform">
                  <i className="fab fa-whatsapp"></i> WhatsApp
              </button>
            </div>
            <button onClick={onClose} className="w-full bg-white text-sky-600 border-2 border-sky-100 py-4 rounded-xl font-black uppercase text-[10px] flex items-center justify-center gap-2 shadow-sm active:scale-95 transition-transform">
              <i className="fas fa-check"></i> Finalizar Venta
            </button>
        </div>
      </div>
    </div>
  );
};

export const POSModule: React.FC<{ onBack: () => void; user: Employee }> = ({ onBack, user }) => {
  const { products, customers, sales, addSale, ticketConfig } = useERPData();
  const [activeTab, setActiveTab] = useState<'sell' | 'history'>('sell');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [customer, setCustomer] = useState<Customer | null>(null);
  const [search, setSearch] = useState('');
  const [vacios, setVacios] = useState(0);

  // Lógica de Tiempo para Admin
  const getLocalISO = (d: Date = new Date()) => {
    const offset = d.getTimezoneOffset() * 60000;
    return new Date(d.getTime() - offset).toISOString().slice(0, 16);
  };

  const [manualDate, setManualDate] = useState<string>(getLocalISO());
  const [autoTime, setAutoTime] = useState(true);
  const [nowDisplay, setNowDisplay] = useState(new Date());

  // Ticket Modal State (Internal Viewer)
  const [viewingTicket, setViewingTicket] = useState<Sale | null>(null);

  const [paidCash, setPaidCash] = useState<string>('');
  const [paidTransfer, setPaidTransfer] = useState<string>('');

  // Efecto del Reloj
  useEffect(() => {
    let interval: any;
    if (autoTime) {
      interval = setInterval(() => {
        const d = new Date();
        setNowDisplay(d);
        setManualDate(getLocalISO(d));
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [autoTime]);

  const handleDateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setAutoTime(false);
    setManualDate(e.target.value);
  };

  const total = cart.reduce((sum, item) => {
    const price = (customer?.specialPrice && item.id === '1') ? customer.specialPrice : item.price;
    return sum + (price * item.quantity);
  }, 0);

  const totalPaid = (parseFloat(paidCash) || 0) + (parseFloat(paidTransfer) || 0);

  // Lógica de Deuda vs Cambio
  const remainingBalance = total - totalPaid;
  const isCreditSale = remainingBalance > 0.01; // Pequeño margen por decimales
  const change = Math.max(0, totalPaid - total);

  // Auto-calcular vacíos basado en garrafones vendidos (sugerencia)
  useEffect(() => {
    const garrafonesInCart = cart.filter(i => i.name.toLowerCase().includes('garraf') || i.category === 'Agua').reduce((acc, i) => acc + i.quantity, 0);
    if (cart.length > 0 && vacios === 0) {
      setVacios(garrafonesInCart);
    } else if (cart.length === 0) {
      setVacios(0);
    }
  }, [cart]);

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === product.id);
      if (existing) return prev.map(i => i.id === product.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  // NEW: Decrease quantity functionality
  const decreaseQuantity = (productId: string) => {
    setCart(prev => prev.map(item => {
      if (item.id === productId) {
        return { ...item, quantity: Math.max(0, item.quantity - 1) };
      }
      return item;
    }).filter(item => item.quantity > 0));
  };

  // NEW: Remove item completely
  const removeFromCart = (productId: string) => {
    setCart(prev => prev.filter(item => item.id !== productId));
  };

  const handleSendWhatsApp = (sale: Sale) => {
    // Buscar el cliente para asegurar datos actualizados
    const currentCustomer = customers.find(c => c.id === sale.customerId);
    const phone = currentCustomer?.phone?.replace(/\D/g, '') || '';

    if (!phone) {
      alert("El cliente no tiene teléfono registrado.");
      return;
    }

    const itemsText = sale.items.map(i => `• ${i.quantity}x ${i.name}`).join('%0A');
    const debtMsg = sale.paidAmount < sale.total ? `%0A%0A⚠️ *Saldo Pendiente:* $${(sale.total - sale.paidAmount).toFixed(2)}` : '';

    const fullPhone = phone.length === 10 ? `52${phone}` : phone;

    const msg = `¡Hola ${sale.customerAlias}!%0A%0A*${ticketConfig.businessName}*%0AGracias por tu compra.%0A%0A*Detalles de tu pedido:*%0A${itemsText}%0A%0A*Envases Recibidos:* ${sale.emptyGarrafonsReturned}%0A*Total:* $${sale.total.toFixed(2)}${debtMsg}%0A*Ticket:* ${sale.id}%0A%0A_Validación de seguridad QR disponible en planta._`;
    window.open(`https://wa.me/${fullPhone}?text=${msg}`, '_blank');
  };

  const handleCheckout = () => {
    if (!customer) return alert("Selecciona un cliente.");
    if (cart.length === 0) return alert("El carrito está vacío.");

    const splits: PaymentSplit[] = [];
    if (parseFloat(paidCash) > 0) splits.push({ method: 'Efectivo', amount: parseFloat(paidCash) });
    if (parseFloat(paidTransfer) > 0) splits.push({ method: 'Transferencia', amount: parseFloat(paidTransfer) });

    const sale = addSale(
      customer.id, cart, total, totalPaid, splits, vacios, 
      user.role === 'Administrador' ? new Date(manualDate).getTime() : undefined
    );

    // Abrir visor de ticket interno
    setViewingTicket(sale);

    // Resetear formulario para que al cerrar el ticket ya esté listo
    setCart([]);
    setCustomer(null);
    setSearch('');
    setPaidCash('');
    setPaidTransfer('');
    setVacios(0);
    if (user.role === 'Administrador') setAutoTime(true); 
  };

  return (
    <div className="h-full flex flex-col animate-fadeIn bg-sky-50 pb-24 overflow-hidden relative">
      <ModuleHeader title="Punto de Venta" onBack={onBack} />

      <div className="px-6 flex gap-2 mb-4">
        <button onClick={() => setActiveTab('sell')} className={`flex-1 py-3 rounded-2xl text-xs font-bold ${activeTab === 'sell' ? 'bg-sky-600 text-white shadow-lg' : 'bg-white text-sky-400'}`}>Nueva Venta</button>
        <button onClick={() => setActiveTab('history')} className={`flex-1 py-3 rounded-2xl text-xs font-bold ${activeTab === 'history' ? 'bg-sky-600 text-white shadow-lg' : 'bg-white text-sky-400'}`}>Historial</button>
      </div>

      {activeTab === 'sell' ? (
        <div className="flex-1 overflow-y-auto px-6 space-y-6 pb-32 no-scrollbar">
          {/* Admin Date Control */}
          {user.role === 'Administrador' && (
            <div className={`p-4 rounded-[2.2rem] border transition-all duration-500 ${autoTime ? 'bg-white border-sky-100' : 'bg-amber-50 border-amber-200 shadow-inner'}`}>
              <div className="flex justify-between items-center mb-3">
                <div className="flex items-center gap-2">
                  <div className={`w-2.5 h-2.5 rounded-full ${autoTime ? 'bg-emerald-500 animate-pulse' : 'bg-amber-500'}`}></div>
                  <label className="text-[10px] font-black uppercase tracking-widest text-sky-900">
                    {autoTime ? 'TIEMPO REAL (INTERNET)' : 'MODO MANUAL (EDITANDO)'}
                  </label>
                </div>
                {!autoTime && (
                  <button onClick={() => setAutoTime(true)} className="flex items-center gap-1 text-[9px] font-black text-sky-500 uppercase bg-sky-50 px-3 py-1.5 rounded-full active:scale-95 transition-transform">
                    <i className="fas fa-rotate"></i> Sincronizar
                  </button>
                )}
              </div>

              <div className="flex gap-3 items-center">
                <div className="flex-1 relative">
                  <input 
                    type="datetime-local" 
                    className={`w-full border-none rounded-2xl p-4 text-xs font-black shadow-sm outline-none transition-all ${
                      autoTime 
                        ? 'bg-sky-50 text-sky-400 pointer-events-none opacity-80' 
                        : 'bg-white text-amber-600 ring-2 ring-amber-200'
                    }`}
                    value={manualDate}
                    onChange={handleDateChange}
                  />
                  {autoTime && (
                    <div className="absolute right-4 top-1/2 -translate-y-1/2 text-emerald-500 text-lg font-black tracking-tighter tabular-nums">
                      {nowDisplay.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit', second:'2-digit'})}
                    </div>
                  )}
                </div>
              </div>
            </div>
          )}

          <section>
            <div className="relative">
              <input type="text" placeholder="Buscar Cliente..." className="w-full bg-white border-none rounded-[2rem] py-5 px-8 shadow-sm outline-none" value={search} onChange={e => setSearch(e.target.value)} />
              {search && !customer && (
                <div className="absolute top-full left-0 right-0 bg-white shadow-2xl rounded-3xl mt-2 z-50 overflow-hidden border border-sky-50">
                  {customers.filter(c => c.alias.toLowerCase().includes(search.toLowerCase())).map(c => (
                    <button key={c.id} onClick={() => { setCustomer(c); setSearch(c.alias); }} className="w-full text-left p-4 hover:bg-sky-50 font-bold border-b border-sky-50 flex justify-between items-center">
                      <span className="text-sky-900">{c.alias}</span>
                      <span className="text-[10px] bg-sky-50 text-sky-400 px-3 py-1 rounded-full font-black">${c.balance}</span>
                    </button>
                  ))}
                </div>
              )}
            </div>
            {customer && (
              <div className="mt-4 flex items-center justify-between bg-sky-600 text-white p-4 rounded-[1.8rem] shadow-lg animate-fadeIn">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-white/20 rounded-2xl flex items-center justify-center"><i className="fas fa-user"></i></div>
                  <div>
                    <span className="text-[8px] font-black uppercase opacity-60 block">Cliente Activo</span>
                    <span className="font-black text-sm">{customer.alias}</span>
                    {customer.balance > 0 && (
                      <span className="text-[9px] bg-red-500/30 px-2 py-0.5 rounded ml-2 font-bold">Adeudo: ${customer.balance}</span>
                    )}
                  </div>
                </div>
                <button onClick={() => {setCustomer(null); setSearch('');}} className="w-10 h-10 bg-white/10 rounded-full flex items-center justify-center active:scale-90 transition-all"><i className="fas fa-times"></i></button>
              </div>
            )}
          </section>

          <div className="grid grid-cols-2 gap-3">
            {products.map(p => (
              <button key={p.id} onClick={() => addToCart(p)} className="bg-white p-5 rounded-[2.2rem] shadow-sm active:bg-sky-50 text-left relative overflow-hidden group border border-transparent hover:border-sky-100">
                <div className="text-xs font-black text-sky-900 uppercase tracking-tight mb-1">{p.name}</div>
                <div className="text-sky-600 font-black text-lg">${p.price}</div>
                <div className="absolute -bottom-2 -right-2 w-12 h-12 bg-sky-50 text-sky-100 flex items-center justify-center rounded-tl-3xl group-active:text-sky-200 transition-colors">
                  <i className="fas fa-plus"></i>
                </div>
              </button>
            ))}
          </div>

          {cart.length > 0 && (
            <RoundedCard className="shadow-2xl border-2 border-white">
              <div className="flex justify-between items-start mb-6">
                <div>
                  <span className="text-[10px] text-sky-400 font-black uppercase mb-1 block">Monto a Liquidar</span>
                  <span className="text-4xl font-black text-sky-900 tracking-tighter">${total.toFixed(2)}</span>
                </div>
                <button onClick={() => setCart([])} className="text-rose-400 text-xs font-bold uppercase underline">Vaciar</button>
              </div>

              <div className="space-y-3 mb-6">
                {cart.map(i => (
                  <div key={i.id} className="flex justify-between items-center bg-sky-50/50 p-2 rounded-2xl border border-sky-100">
                    <div className="flex flex-col">
                       <span className="text-[10px] font-black text-sky-900 uppercase">{i.name}</span>
                       <span className="text-xs font-bold text-sky-600">${(i.quantity * i.price).toFixed(2)}</span>
                    </div>

                    <div className="flex items-center gap-2 bg-white rounded-xl shadow-sm p-1">
                       <button onClick={() => decreaseQuantity(i.id)} className="w-8 h-8 flex items-center justify-center bg-sky-50 text-sky-600 rounded-lg active:bg-sky-200 transition-colors font-bold">-</button>
                       <span className="text-sm font-black text-sky-900 w-6 text-center">{i.quantity}</span>
                       <button onClick={() => addToCart(i)} className="w-8 h-8 flex items-center justify-center bg-sky-600 text-white rounded-lg active:scale-95 transition-transform font-bold">+</button>
                    </div>

                    <button onClick={() => removeFromCart(i.id)} className="w-8 h-8 flex items-center justify-center text-rose-400 hover:text-rose-600">
                       <i className="fas fa-trash"></i>
                    </button>
                  </div>
                ))}
              </div>

              {/* Control de Garrafones Vacíos */}
              <div className="mb-6 bg-white p-4 rounded-3xl border border-sky-100 flex justify-between items-center">
                 <span className="text-[10px] font-black text-sky-400 uppercase tracking-tight ml-2">Garrafones Vacíos Recibidos</span>
                 <div className="flex items-center gap-3 bg-sky-50 rounded-2xl p-1">
                    <button onClick={() => setVacios(Math.max(0, vacios - 1))} className="w-8 h-8 flex items-center justify-center bg-white text-sky-600 rounded-xl font-black shadow-sm">-</button>
                    <span className="text-lg font-black text-sky-900 w-6 text-center">{vacios}</span>
                    <button onClick={() => setVacios(vacios + 1)} className="w-8 h-8 flex items-center justify-center bg-sky-600 text-white rounded-xl font-black shadow-lg">+</button>
                 </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[9px] font-black text-sky-400 uppercase ml-2">Efectivo</label>
                  <input type="number" value={paidCash} onChange={e => setPaidCash(e.target.value)} className="w-full bg-sky-50 p-4 rounded-2xl font-black text-lg focus:ring-2 ring-sky-200 outline-none" placeholder="$ 0.00" />
                </div>
                <div className="space-y-1">
                  <label className="text-[9px] font-black text-sky-400 uppercase ml-2">Transf.</label>
                  <input type="number" value={paidTransfer} onChange={e => setPaidTransfer(e.target.value)} className="w-full bg-sky-50 p-4 rounded-2xl font-black text-lg focus:ring-2 ring-sky-200 outline-none" placeholder="$ 0.00" />
                </div>
              </div>

              <div className={`mt-4 p-5 rounded-[1.8rem] flex justify-between items-center border transition-colors ${isCreditSale ? 'bg-amber-50 border-amber-100' : 'bg-emerald-50 border-emerald-100'}`}>
                <div>
                  <span className={`text-[10px] font-black uppercase tracking-widest block ${isCreditSale ? 'text-amber-700' : 'text-emerald-700'}`}>
                    {isCreditSale ? 'Saldo Pendiente (Crédito)' : 'Cambio Sugerido'}
                  </span>
                  <span className={`text-2xl font-black tracking-tighter ${isCreditSale ? 'text-amber-600' : 'text-emerald-600'}`}>
                    ${isCreditSale ? remainingBalance.toFixed(2) : change.toFixed(2)}
                  </span>
                </div>
                <div className={`w-12 h-12 bg-white rounded-2xl flex items-center justify-center shadow-sm ${isCreditSale ? 'text-amber-500 shadow-amber-100' : 'text-emerald-500 shadow-emerald-100'}`}>
                  <i className={`fas ${isCreditSale ? 'fa-file-invoice-dollar' : 'fa-hand-holding-dollar'} text-xl`}></i>
                </div>
              </div>
            </RoundedCard>
          )}
        </div>
      ) : (
        <div className="flex-1 overflow-y-auto px-6 space-y-3 pb-10 no-scrollbar">
          {sales.length === 0 ? (
            <div className="text-center py-20 opacity-30">
               <i className="fas fa-receipt text-6xl mb-4"></i>
               <p className="text-xs font-black uppercase">Sin historial reciente</p>
            </div>
          ) : (
            sales.map(s => (
              <RoundedCard key={s.id} className="py-5 border-none shadow-sm group">
                <div className="flex justify-between items-start">
                  <div className="flex gap-4">
                    <div className="w-12 h-12 bg-sky-50 text-sky-600 rounded-2xl flex items-center justify-center text-xl">
                      <i className="fas fa-receipt"></i>
                    </div>
                    <div>
                      <h4 className="font-black text-sky-900 text-sm leading-tight">{s.customerAlias}</h4>
                      <p className="text-[9px] text-sky-400 font-bold uppercase mt-1">{new Date(s.timestamp).toLocaleString()}</p>
                      {s.paidAmount < s.total && (
                        <span className="text-[9px] text-amber-500 font-black uppercase bg-amber-50 px-2 py-0.5 rounded mt-1 inline-block">Crédito</span>
                      )}
                    </div>
                  </div>
                  <div className="text-right">
                    <span className="font-black text-sky-600 text-xl tracking-tighter">${s.total}</span>
                    <p className="text-[8px] font-black text-sky-300 uppercase">{s.id}</p>
                  </div>
                </div>
                <div className="flex gap-2 mt-5">
                   <button onClick={() => setViewingTicket(s)} className="flex-1 text-[9px] font-black uppercase bg-sky-100 text-sky-600 px-3 py-3 rounded-xl flex items-center justify-center gap-2 active:bg-sky-200 transition-colors">
                    <i className="fas fa-eye"></i> Ver Ticket
                   </button>
                   <button onClick={() => handleSendWhatsApp(s)} className="flex-1 text-[9px] font-black uppercase bg-emerald-100 text-emerald-600 px-3 py-3 rounded-xl flex items-center justify-center gap-2 active:bg-emerald-200 transition-colors">
                    <i className="fab fa-whatsapp"></i> WA
                   </button>
                </div>
              </RoundedCard>
            ))
          )}
        </div>
      )}

      {activeTab === 'sell' && (
        <div className="fixed bottom-0 left-0 right-0 p-6 bg-white/95 border-t border-sky-100 shadow-2xl z-50">
          <ActionButton onClick={handleCheckout} disabled={!customer || cart.length === 0}>
             {isCreditSale ? 'Registrar Venta a Crédito' : 'Completar Venta'}
          </ActionButton>
        </div>
      )}

      {/* Internal Ticket Viewer Modal */}
      {viewingTicket && (
        <TicketModal 
          sale={viewingTicket} 
          config={ticketConfig} 
          onClose={() => setViewingTicket(null)} 
          onWhatsApp={() => handleSendWhatsApp(viewingTicket)}
        />
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Product, Customer, CartItem, PaymentSplit, Sale, Employee, TicketConfig } from '../types';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';

// --- COMPONENTE TICKET MODAL (EXTRAÍDO) ---
interface TicketModalProps {
  sale: Sale;
  config: TicketConfig;
  onClose: () => void;
  onWhatsApp: () => void;
  onNewSale: () => void;
  onFinish: () => void;
}

const TicketModal = ({ sale, config, onClose, onWhatsApp, onNewSale, onFinish }: TicketModalProps) => {
  const qrData = btoa(`AQUA-PRO-SECURE|${JSON.stringify({ id: sale.id, total: sale.total })}`);
  const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(qrData)}`;

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="fixed inset-0 z-[100] bg-slate-900/90 backdrop-blur-sm flex flex-col items-center justify-center p-4 overflow-y-auto animate-fadeIn">
      <div className="bg-white w-full max-w-sm shadow-2xl overflow-hidden print:w-full print:shadow-none print:max-w-none rounded-[2rem]">
        {/* Action Bar (Hidden when printing) */}
        <div className="bg-slate-100 p-4 flex justify-between items-center print:hidden border-b border-slate-200">
            <span className="text-xs font-black uppercase text-slate-500">Ticket Generado</span>
            <button onClick={onClose} className="w-8 h-8 flex items-center justify-center bg-slate-200 rounded-full text-slate-600 active:scale-90 transition-transform"><i className="fas fa-times"></i></button>
        </div>

        {/* Ticket Content (Printable Area) */}
        <div className="p-8 text-center font-mono text-black leading-tight" id="printable-ticket">
            {config.logoUrl && <img src={config.logoUrl} alt="Logo" className="w-24 h-24 object-contain mx-auto mb-4 grayscale" />}

            <h2 className="text-xl font-black uppercase mb-1">{config.businessName}</h2>
            {config.slogan && <p className="text-[10px] italic mb-4">"{config.slogan}"</p>}

            <div className="text-[10px] border-b border-black pb-4 mb-4 space-y-1">
              <p>RFC: {config.rfc}</p>
              <p>{config.address}</p>
              <p>Tel: {config.phone}</p>
            </div>

            <div className="text-left text-xs mb-4 space-y-1">
              <p>FOLIO: <span className="font-bold">{sale.id}</span></p>
              <p>FECHA: {new Date(sale.timestamp).toLocaleString()}</p>
              <p>CLIENTE: {sale.customerAlias.toUpperCase()}</p>
            </div>

            <table className="w-full text-xs mb-4 border-collapse">
              <thead>
                <tr className="border-b border-black border-dashed">
                  <th className="text-left py-1">CANT</th>
                  <th className="text-left py-1">DESC</th>
                  <th className="text-right py-1">IMP</th>
                </tr>
              </thead>
              <tbody>
                {sale.items.map((item, i) => (
                  <tr key={i}>
                    <td className="text-left py-1 align-top">{item.quantity}</td>
                    <td className="text-left py-1 align-top">{item.name.slice(0, 20)}</td>
                    <td className="text-right py-1 align-top">${(item.quantity * item.price).toFixed(2)}</td>
                  </tr>
                ))}
              </tbody>
            </table>

            <div className="border-t-2 border-black pt-2 mb-2 text-right">
              <p className="text-lg font-black">TOTAL: ${sale.total.toFixed(2)}</p>
            </div>

            <div className="text-right text-[10px] mb-4 space-y-1">
              <p>RECIBIDO: ${sale.paidAmount.toFixed(2)}</p>
              {sale.paidAmount < sale.total ? (
                  <p className="font-bold">SALDO PENDIENTE: ${(sale.total - sale.paidAmount).toFixed(2)}</p>
              ) : (
                  <p>CAMBIO: ${sale.change.toFixed(2)}</p>
              )}
            </div>

            {sale.emptyGarrafonsReturned > 0 && (
              <div className="border border-black p-2 mb-4 text-xs font-bold">
                  ENVASES RECIBIDOS: {sale.emptyGarrafonsReturned}
              </div>
            )}

            <div className="border-t border-dashed border-black pt-4 mb-4">
              <p className="text-xs font-bold mb-1">{config.footerMessage}</p>
              <p className="text-[9px] italic">{config.extraNote}</p>
            </div>

            <div className="flex flex-col items-center">
              <img src={qrUrl} alt="QR" className="w-24 h-24 mb-2" />
              <p className="text-[8px] uppercase tracking-widest">Escanea para validar</p>
            </div>
        </div>

        {/* Footer Actions (Hidden when printing) */}
        <div className="p-5 bg-slate-50 border-t border-slate-200 flex flex-col gap-3 print:hidden">
            {/* Fila 1: Acciones de Ticket */}
            <div className="flex gap-3">
              <button onClick={handlePrint} className="flex-1 bg-slate-200 text-slate-700 py-3 rounded-2xl font-black uppercase text-[10px] flex items-center justify-center gap-2 active:scale-95 transition-transform">
                  <i className="fas fa-print text-lg"></i> Imprimir
              </button>
              <button onClick={onWhatsApp} className="flex-1 bg-emerald-500 text-white py-3 rounded-2xl font-black uppercase text-[10px] flex items-center justify-center gap-2 active:scale-95 transition-transform shadow-lg shadow-emerald-100">
                  <i className="fab fa-whatsapp text-lg"></i> Enviar
              </button>
            </div>

            {/* Fila 2: Acciones de Flujo */}
            <div className="flex gap-3 pt-2">
              <button onClick={onFinish} className="flex-1 bg-white border-2 border-slate-200 text-slate-500 py-4 rounded-2xl font-black uppercase text-[10px] flex items-center justify-center gap-2 active:scale-95 transition-transform">
                <i className="fas fa-flag-checkered"></i> Terminar
              </button>
              <button onClick={onNewSale} className="flex-[1.5] bg-sky-600 text-white py-4 rounded-2xl font-black uppercase text-[10px] flex items-center justify-center gap-2 active:scale-95 transition-transform shadow-xl shadow-sky-200">
                <i className="fas fa-cart-plus"></i> Nueva Venta
              </button>
            </div>
        </div>
      </div>
    </div>
  );
};

export const POSModule: React.FC<{ onBack: () => void; user: Employee }> = ({ onBack, user }) => {
  const { products, customers, sales, addSale, ticketConfig } = useERPData();
  const [activeTab, setActiveTab] = useState<'sell' | 'history'>('sell');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [customer, setCustomer] = useState<Customer | null>(null);
  const [search, setSearch] = useState('');
  const [vacios, setVacios] = useState(0);

  // Lógica de Tiempo para Admin
  const getLocalISO = (d: Date = new Date()) => {
    const offset = d.getTimezoneOffset() * 60000;
    return new Date(d.getTime() - offset).toISOString().slice(0, 16);
  };

  const [manualDate, setManualDate] = useState<string>(getLocalISO());
  const [autoTime, setAutoTime] = useState(true);
  const [nowDisplay, setNowDisplay] = useState(new Date());

  // Ticket Modal State (Internal Viewer)
  const [viewingTicket, setViewingTicket] = useState<Sale | null>(null);

  const [paidCash, setPaidCash] = useState<string>('');
  const [paidTransfer, setPaidTransfer] = useState<string>('');

  // Efecto del Reloj
  useEffect(() => {
    let interval: any;
    if (autoTime) {
      interval = setInterval(() => {
        const d = new Date();
        setNowDisplay(d);
        setManualDate(getLocalISO(d));
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [autoTime]);

  const handleDateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setAutoTime(false);
    setManualDate(e.target.value);
  };

  const total = cart.reduce((sum, item) => {
    const price = (customer?.specialPrice && item.id === '1') ? customer.specialPrice : item.price;
    return sum + (price * item.quantity);
  }, 0);

  const totalPaid = (parseFloat(paidCash) || 0) + (parseFloat(paidTransfer) || 0);

  // Lógica de Deuda vs Cambio
  const remainingBalance = total - totalPaid;
  const isCreditSale = remainingBalance > 0.01; // Pequeño margen por decimales
  const change = Math.max(0, totalPaid - total);

  // Auto-calcular vacíos basado en garrafones vendidos (sugerencia)
  useEffect(() => {
    const garrafonesInCart = cart.filter(i => i.name.toLowerCase().includes('garraf') || i.category === 'Agua').reduce((acc, i) => acc + i.quantity, 0);
    if (cart.length > 0 && vacios === 0) {
      setVacios(garrafonesInCart);
    } else if (cart.length === 0) {
      setVacios(0);
    }
  }, [cart]);

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === product.id);
      if (existing) return prev.map(i => i.id === product.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  // NEW: Decrease quantity functionality
  const decreaseQuantity = (productId: string) => {
    setCart(prev => prev.map(item => {
      if (item.id === productId) {
        return { ...item, quantity: Math.max(0, item.quantity - 1) };
      }
      return item;
    }).filter(item => item.quantity > 0));
  };

  // NEW: Remove item completely
  const removeFromCart = (productId: string) => {
    setCart(prev => prev.filter(item => item.id !== productId));
  };

  const handleSendWhatsApp = (sale: Sale) => {
    // Buscar el cliente para asegurar datos actualizados
    const currentCustomer = customers.find(c => c.id === sale.customerId);
    const phone = currentCustomer?.phone?.replace(/\D/g, '') || '';

    if (!phone) {
      alert("El cliente no tiene teléfono registrado.");
      return;
    }

    const itemsText = sale.items.map(i => `• ${i.quantity}x ${i.name}`).join('%0A');
    const debtMsg = sale.paidAmount < sale.total ? `%0A%0A⚠️ *Saldo Pendiente:* $${(sale.total - sale.paidAmount).toFixed(2)}` : '';

    const fullPhone = phone.length === 10 ? `52${phone}` : phone;

    const msg = `¡Hola ${sale.customerAlias}!%0A%0A*${ticketConfig.businessName}*%0AGracias por tu compra.%0A%0A*Detalles de tu pedido:*%0A${itemsText}%0A%0A*Envases Recibidos:* ${sale.emptyGarrafonsReturned}%0A*Total:* $${sale.total.toFixed(2)}${debtMsg}%0A*Ticket:* ${sale.id}%0A%0A_Validación de seguridad QR disponible en planta._`;
    window.open(`https://wa.me/${fullPhone}?text=${msg}`, '_blank');
  };

  const handleCheckout = () => {
    if (!customer) return alert("Selecciona un cliente.");
    if (cart.length === 0) return alert("El carrito está vacío.");

    const splits: PaymentSplit[] = [];
    if (parseFloat(paidCash) > 0) splits.push({ method: 'Efectivo', amount: parseFloat(paidCash) });
    if (parseFloat(paidTransfer) > 0) splits.push({ method: 'Transferencia', amount: parseFloat(paidTransfer) });

    const sale = addSale(
      customer.id, cart, total, totalPaid, splits, vacios, 
      user.role === 'Administrador' ? new Date(manualDate).getTime() : undefined
    );

    // Abrir visor de ticket interno
    setViewingTicket(sale);

    // Resetear formulario para que al cerrar el ticket ya esté listo
    setCart([]);
    setCustomer(null);
    setSearch('');
    setPaidCash('');
    setPaidTransfer('');
    setVacios(0);
    if (user.role === 'Administrador') setAutoTime(true); 
  };

  return (
    <div className="h-full flex flex-col animate-fadeIn bg-sky-50 pb-24 overflow-hidden relative">
      <ModuleHeader title="Punto de Venta" onBack={onBack} />

      <div className="px-6 flex gap-2 mb-4">
        <button onClick={() => setActiveTab('sell')} className={`flex-1 py-3 rounded-2xl text-xs font-bold ${activeTab === 'sell' ? 'bg-sky-600 text-white shadow-lg' : 'bg-white text-sky-400'}`}>Nueva Venta</button>
        <button onClick={() => setActiveTab('history')} className={`flex-1 py-3 rounded-2xl text-xs font-bold ${activeTab === 'history' ? 'bg-sky-600 text-white shadow-lg' : 'bg-white text-sky-400'}`}>Historial</button>
      </div>

      {activeTab === 'sell' ? (
        <div className="flex-1 overflow-y-auto px-6 space-y-6 pb-32 no-scrollbar">
          {/* Admin Date Control */}
          {user.role === 'Administrador' && (
            <div className={`p-4 rounded-[2.2rem] border transition-all duration-500 ${autoTime ? 'bg-white border-sky-100' : 'bg-amber-50 border-amber-200 shadow-inner'}`}>
              <div className="flex justify-between items-center mb-3">
                <div className="flex items-center gap-2">
                  <div className={`w-2.5 h-2.5 rounded-full ${autoTime ? 'bg-emerald-500 animate-pulse' : 'bg-amber-500'}`}></div>
                  <label className="text-[10px] font-black uppercase tracking-widest text-sky-900">
                    {autoTime ? 'TIEMPO REAL (INTERNET)' : 'MODO MANUAL (EDITANDO)'}
                  </label>
                </div>
                {!autoTime && (
                  <button onClick={() => setAutoTime(true)} className="flex items-center gap-1 text-[9px] font-black text-sky-500 uppercase bg-sky-50 px-3 py-1.5 rounded-full active:scale-95 transition-transform">
                    <i className="fas fa-rotate"></i> Sincronizar
                  </button>
                )}
              </div>

              <div className="flex gap-3 items-center">
                <div className="flex-1 relative">
                  <input 
                    type="datetime-local" 
                    className={`w-full border-none rounded-2xl p-4 text-xs font-black shadow-sm outline-none transition-all ${
                      autoTime 
                        ? 'bg-sky-50 text-sky-400 pointer-events-none opacity-80' 
                        : 'bg-white text-amber-600 ring-2 ring-amber-200'
                    }`}
                    value={manualDate}
                    onChange={handleDateChange}
                  />
                  {autoTime && (
                    <div className="absolute right-4 top-1/2 -translate-y-1/2 text-emerald-500 text-lg font-black tracking-tighter tabular-nums">
                      {nowDisplay.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit', second:'2-digit'})}
                    </div>
                  )}
                </div>
              </div>
            </div>
          )}

          <section>
            <div className="relative">
              <input type="text" placeholder="Buscar Cliente..." className="w-full bg-white border-none rounded-[2rem] py-5 px-8 shadow-sm outline-none" value={search} onChange={e => setSearch(e.target.value)} />
              {search && !customer && (
                <div className="absolute top-full left-0 right-0 bg-white shadow-2xl rounded-3xl mt-2 z-50 overflow-hidden border border-sky-50">
                  {customers.filter(c => c.alias.toLowerCase().includes(search.toLowerCase())).map(c => (
                    <button key={c.id} onClick={() => { setCustomer(c); setSearch(c.alias); }} className="w-full text-left p-4 hover:bg-sky-50 font-bold border-b border-sky-50 flex justify-between items-center">
                      <span className="text-sky-900">{c.alias}</span>
                      <span className="text-[10px] bg-sky-50 text-sky-400 px-3 py-1 rounded-full font-black">${c.balance}</span>
                    </button>
                  ))}
                </div>
              )}
            </div>
            {customer && (
              <div className="mt-4 flex items-center justify-between bg-sky-600 text-white p-4 rounded-[1.8rem] shadow-lg animate-fadeIn">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-white/20 rounded-2xl flex items-center justify-center"><i className="fas fa-user"></i></div>
                  <div>
                    <span className="text-[8px] font-black uppercase opacity-60 block">Cliente Activo</span>
                    <span className="font-black text-sm">{customer.alias}</span>
                    {customer.balance > 0 && (
                      <span className="text-[9px] bg-red-500/30 px-2 py-0.5 rounded ml-2 font-bold">Adeudo: ${customer.balance}</span>
                    )}
                  </div>
                </div>
                <button onClick={() => {setCustomer(null); setSearch('');}} className="w-10 h-10 bg-white/10 rounded-full flex items-center justify-center active:scale-90 transition-all"><i className="fas fa-times"></i></button>
              </div>
            )}
          </section>

          <div className="grid grid-cols-2 gap-3">
            {products.map(p => (
              <button key={p.id} onClick={() => addToCart(p)} className="bg-white p-5 rounded-[2.2rem] shadow-sm active:bg-sky-50 text-left relative overflow-hidden group border border-transparent hover:border-sky-100">
                <div className="text-xs font-black text-sky-900 uppercase tracking-tight mb-1">{p.name}</div>
                <div className="text-sky-600 font-black text-lg">${p.price}</div>
                <div className="absolute -bottom-2 -right-2 w-12 h-12 bg-sky-50 text-sky-100 flex items-center justify-center rounded-tl-3xl group-active:text-sky-200 transition-colors">
                  <i className="fas fa-plus"></i>
                </div>
              </button>
            ))}
          </div>

          {cart.length > 0 && (
            <RoundedCard className="shadow-2xl border-2 border-white">
              <div className="flex justify-between items-start mb-6">
                <div>
                  <span className="text-[10px] text-sky-400 font-black uppercase mb-1 block">Monto a Liquidar</span>
                  <span className="text-4xl font-black text-sky-900 tracking-tighter">${total.toFixed(2)}</span>
                </div>
                <button onClick={() => setCart([])} className="text-rose-400 text-xs font-bold uppercase underline">Vaciar</button>
              </div>

              <div className="space-y-3 mb-6">
                {cart.map(i => (
                  <div key={i.id} className="flex justify-between items-center bg-sky-50/50 p-2 rounded-2xl border border-sky-100">
                    <div className="flex flex-col">
                       <span className="text-[10px] font-black text-sky-900 uppercase">{i.name}</span>
                       <span className="text-xs font-bold text-sky-600">${(i.quantity * i.price).toFixed(2)}</span>
                    </div>

                    <div className="flex items-center gap-2 bg-white rounded-xl shadow-sm p-1">
                       <button onClick={() => decreaseQuantity(i.id)} className="w-8 h-8 flex items-center justify-center bg-sky-50 text-sky-600 rounded-lg active:bg-sky-200 transition-colors font-bold">-</button>
                       <span className="text-sm font-black text-sky-900 w-6 text-center">{i.quantity}</span>
                       <button onClick={() => addToCart(i)} className="w-8 h-8 flex items-center justify-center bg-sky-600 text-white rounded-lg active:scale-95 transition-transform font-bold">+</button>
                    </div>

                    <button onClick={() => removeFromCart(i.id)} className="w-8 h-8 flex items-center justify-center text-rose-400 hover:text-rose-600">
                       <i className="fas fa-trash"></i>
                    </button>
                  </div>
                ))}
              </div>

              {/* Control de Garrafones Vacíos */}
              <div className="mb-6 bg-white p-4 rounded-3xl border border-sky-100 flex justify-between items-center">
                 <span className="text-[10px] font-black text-sky-400 uppercase tracking-tight ml-2">Garrafones Vacíos Recibidos</span>
                 <div className="flex items-center gap-3 bg-sky-50 rounded-2xl p-1">
                    <button onClick={() => setVacios(Math.max(0, vacios - 1))} className="w-8 h-8 flex items-center justify-center bg-white text-sky-600 rounded-xl font-black shadow-sm">-</button>
                    <span className="text-lg font-black text-sky-900 w-6 text-center">{vacios}</span>
                    <button onClick={() => setVacios(vacios + 1)} className="w-8 h-8 flex items-center justify-center bg-sky-600 text-white rounded-xl font-black shadow-lg">+</button>
                 </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[9px] font-black text-sky-400 uppercase ml-2">Efectivo</label>
                  <input type="number" value={paidCash} onChange={e => setPaidCash(e.target.value)} className="w-full bg-sky-50 p-4 rounded-2xl font-black text-lg focus:ring-2 ring-sky-200 outline-none" placeholder="$ 0.00" />
                </div>
                <div className="space-y-1">
                  <label className="text-[9px] font-black text-sky-400 uppercase ml-2">Transf.</label>
                  <input type="number" value={paidTransfer} onChange={e => setPaidTransfer(e.target.value)} className="w-full bg-sky-50 p-4 rounded-2xl font-black text-lg focus:ring-2 ring-sky-200 outline-none" placeholder="$ 0.00" />
                </div>
              </div>

              <div className={`mt-4 p-5 rounded-[1.8rem] flex justify-between items-center border transition-colors ${isCreditSale ? 'bg-amber-50 border-amber-100' : 'bg-emerald-50 border-emerald-100'}`}>
                <div>
                  <span className={`text-[10px] font-black uppercase tracking-widest block ${isCreditSale ? 'text-amber-700' : 'text-emerald-700'}`}>
                    {isCreditSale ? 'Saldo Pendiente (Crédito)' : 'Cambio Sugerido'}
                  </span>
                  <span className={`text-2xl font-black tracking-tighter ${isCreditSale ? 'text-amber-600' : 'text-emerald-600'}`}>
                    ${isCreditSale ? remainingBalance.toFixed(2) : change.toFixed(2)}
                  </span>
                </div>
                <div className={`w-12 h-12 bg-white rounded-2xl flex items-center justify-center shadow-sm ${isCreditSale ? 'text-amber-500 shadow-amber-100' : 'text-emerald-500 shadow-emerald-100'}`}>
                  <i className={`fas ${isCreditSale ? 'fa-file-invoice-dollar' : 'fa-hand-holding-dollar'} text-xl`}></i>
                </div>
              </div>
            </RoundedCard>
          )}
        </div>
      ) : (
        <div className="flex-1 overflow-y-auto px-6 space-y-3 pb-10 no-scrollbar">
          {sales.length === 0 ? (
            <div className="text-center py-20 opacity-30">
               <i className="fas fa-receipt text-6xl mb-4"></i>
               <p className="text-xs font-black uppercase">Sin historial reciente</p>
            </div>
          ) : (
            sales.map(s => (
              <RoundedCard key={s.id} className="py-5 border-none shadow-sm group">
                <div className="flex justify-between items-start">
                  <div className="flex gap-4">
                    <div className="w-12 h-12 bg-sky-50 text-sky-600 rounded-2xl flex items-center justify-center text-xl">
                      <i className="fas fa-receipt"></i>
                    </div>
                    <div>
                      <h4 className="font-black text-sky-900 text-sm leading-tight">{s.customerAlias}</h4>
                      <p className="text-[9px] text-sky-400 font-bold uppercase mt-1">{new Date(s.timestamp).toLocaleString()}</p>
                      {s.paidAmount < s.total && (
                        <span className="text-[9px] text-amber-500 font-black uppercase bg-amber-50 px-2 py-0.5 rounded mt-1 inline-block">Crédito</span>
                      )}
                    </div>
                  </div>
                  <div className="text-right">
                    <span className="font-black text-sky-600 text-xl tracking-tighter">${s.total}</span>
                    <p className="text-[8px] font-black text-sky-300 uppercase">{s.id}</p>
                  </div>
                </div>
                <div className="flex gap-2 mt-5">
                   <button onClick={() => setViewingTicket(s)} className="flex-1 text-[9px] font-black uppercase bg-sky-100 text-sky-600 px-3 py-3 rounded-xl flex items-center justify-center gap-2 active:bg-sky-200 transition-colors">
                    <i className="fas fa-eye"></i> Ver Ticket
                   </button>
                   <button onClick={() => handleSendWhatsApp(s)} className="flex-1 text-[9px] font-black uppercase bg-emerald-100 text-emerald-600 px-3 py-3 rounded-xl flex items-center justify-center gap-2 active:bg-emerald-200 transition-colors">
                    <i className="fab fa-whatsapp"></i> WA
                   </button>
                </div>
              </RoundedCard>
            ))
          )}
        </div>
      )}

      {activeTab === 'sell' && (
        <div className="fixed bottom-0 left-0 right-0 p-6 bg-white/95 border-t border-sky-100 shadow-2xl z-50">
          <ActionButton onClick={handleCheckout} disabled={!customer || cart.length === 0}>
             {isCreditSale ? 'Registrar Venta a Crédito' : 'Completar Venta'}
          </ActionButton>
        </div>
      )}

      {/* Internal Ticket Viewer Modal */}
      {viewingTicket && (
        <TicketModal 
          sale={viewingTicket} 
          config={ticketConfig} 
          onClose={() => setViewingTicket(null)} 
          onWhatsApp={() => handleSendWhatsApp(viewingTicket)}
          onNewSale={() => {
            setViewingTicket(null);
            // El estado ya se limpió en handleCheckout, estamos listos
          }}
          onFinish={() => {
            setViewingTicket(null);
            setActiveTab('history');
          }}
        />
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Product, Customer, CartItem, PaymentSplit, Sale, Employee, TicketConfig } from '../types';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';

// --- COMPONENTE TICKET MODAL (EXTRAÍDO) ---
interface TicketModalProps {
  sale: Sale;
  config: TicketConfig;
  onClose: () => void;
  onWhatsApp: () => void;
  onNewSale: () => void;
  onFinish: () => void;
}

const TicketModal = ({ sale, config, onClose, onWhatsApp, onNewSale, onFinish }: TicketModalProps) => {
  const qrData = btoa(`AQUA-PRO-SECURE|${JSON.stringify({ id: sale.id, total: sale.total })}`);
  const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(qrData)}`;

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="fixed inset-0 z-[100] bg-slate-900/90 backdrop-blur-sm flex flex-col items-center justify-center p-4 overflow-y-auto animate-fadeIn">
      <div className="bg-white w-full max-w-sm shadow-2xl overflow-hidden print:w-full print:shadow-none print:max-w-none rounded-[2rem]">
        {/* Action Bar (Hidden when printing) */}
        <div className="bg-slate-100 p-4 flex justify-between items-center print:hidden border-b border-slate-200">
            <span className="text-xs font-black uppercase text-slate-500">Ticket Generado</span>
            <button onClick={onClose} className="w-8 h-8 flex items-center justify-center bg-slate-200 rounded-full text-slate-600 active:scale-90 transition-transform"><i className="fas fa-times"></i></button>
        </div>

        {/* Ticket Content (Printable Area) */}
        <div className="p-8 text-center font-mono text-black leading-tight" id="printable-ticket">
            {config.logoUrl && <img src={config.logoUrl} alt="Logo" className="w-24 h-24 object-contain mx-auto mb-4 grayscale" />}

            <h2 className="text-xl font-black uppercase mb-1">{config.businessName}</h2>
            {config.slogan && <p className="text-[10px] italic mb-4">"{config.slogan}"</p>}

            <div className="text-[10px] border-b border-black pb-4 mb-4 space-y-1">
              <p>RFC: {config.rfc}</p>
              <p>{config.address}</p>
              <p>Tel: {config.phone}</p>
            </div>

            <div className="text-left text-xs mb-4 space-y-1">
              <p>FOLIO: <span className="font-bold">{sale.id}</span></p>
              <p>FECHA: {new Date(sale.timestamp).toLocaleString()}</p>
              <p>CLIENTE: {sale.customerAlias.toUpperCase()}</p>
            </div>

            <table className="w-full text-xs mb-4 border-collapse">
              <thead>
                <tr className="border-b border-black border-dashed">
                  <th className="text-left py-1">CANT</th>
                  <th className="text-left py-1">DESC</th>
                  <th className="text-right py-1">IMP</th>
                </tr>
              </thead>
              <tbody>
                {sale.items.map((item, i) => (
                  <tr key={i}>
                    <td className="text-left py-1 align-top">{item.quantity}</td>
                    <td className="text-left py-1 align-top">{item.name.slice(0, 20)}</td>
                    <td className="text-right py-1 align-top">${(item.quantity * item.price).toFixed(2)}</td>
                  </tr>
                ))}
              </tbody>
            </table>

            <div className="border-t-2 border-black pt-2 mb-2 text-right">
              <p className="text-lg font-black">TOTAL: ${sale.total.toFixed(2)}</p>
            </div>

            <div className="text-right text-[10px] mb-4 space-y-1">
              <p>RECIBIDO: ${sale.paidAmount.toFixed(2)}</p>
              {sale.paidAmount < sale.total ? (
                  <p className="font-bold">SALDO PENDIENTE: ${(sale.total - sale.paidAmount).toFixed(2)}</p>
              ) : (
                  <p>CAMBIO: ${sale.change.toFixed(2)}</p>
              )}
            </div>

            {sale.emptyGarrafonsReturned > 0 && (
              <div className="border border-black p-2 mb-4 text-xs font-bold">
                  ENVASES RECIBIDOS: {sale.emptyGarrafonsReturned}
              </div>
            )}

            <div className="border-t border-dashed border-black pt-4 mb-4">
              <p className="text-xs font-bold mb-1">{config.footerMessage}</p>
              <p className="text-[9px] italic">{config.extraNote}</p>
            </div>

            <div className="flex flex-col items-center">
              <img src={qrUrl} alt="QR" className="w-24 h-24 mb-2" />
              <p className="text-[8px] uppercase tracking-widest">Escanea para validar</p>
            </div>
        </div>

        {/* Footer Actions (Hidden when printing) */}
        <div className="p-5 bg-slate-50 border-t border-slate-200 flex flex-col gap-4 print:hidden">
            {/* Grupo 1: Gestión del Documento */}
            <div className="grid grid-cols-2 gap-3">
              <button 
                onClick={handlePrint} 
                className="bg-slate-200 text-slate-700 py-3.5 rounded-2xl font-black uppercase text-[10px] flex items-center justify-center gap-2 active:scale-95 transition-transform"
              >
                  <i className="fas fa-print text-lg"></i> 
                  <span>Imprimir / PDF</span>
              </button>
              <button 
                onClick={onWhatsApp} 
                className="bg-emerald-500 text-white py-3.5 rounded-2xl font-black uppercase text-[10px] flex items-center justify-center gap-2 active:scale-95 transition-transform shadow-lg shadow-emerald-100"
              >
                  <i className="fab fa-whatsapp text-lg"></i> 
                  <span>Enviar Ticket</span>
              </button>
            </div>

            {/* Separador Visual */}
            <div className="h-px bg-slate-200 w-full"></div>

            {/* Grupo 2: Flujo de Venta */}
            <div className="grid grid-cols-2 gap-3">
              <button 
                onClick={onFinish} 
                className="border-2 border-slate-200 text-slate-500 py-3.5 rounded-2xl font-black uppercase text-[10px] flex items-center justify-center gap-2 active:scale-95 transition-transform hover:bg-slate-100"
              >
                <i className="fas fa-flag-checkered"></i> 
                <span>Terminar</span>
              </button>
              <button 
                onClick={onNewSale} 
                className="bg-sky-600 text-white py-3.5 rounded-2xl font-black uppercase text-[10px] flex items-center justify-center gap-2 active:scale-95 transition-transform shadow-xl shadow-sky-200"
              >
                <i className="fas fa-cart-plus"></i> 
                <span>Nueva Venta</span>
              </button>
            </div>
        </div>
      </div>
    </div>
  );
};

export const POSModule: React.FC<{ onBack: () => void; user: Employee }> = ({ onBack, user }) => {
  const { products, customers, sales, addSale, ticketConfig } = useERPData();
  const [activeTab, setActiveTab] = useState<'sell' | 'history'>('sell');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [customer, setCustomer] = useState<Customer | null>(null);
  const [search, setSearch] = useState('');
  const [vacios, setVacios] = useState(0);

  // Lógica de Tiempo para Admin
  const getLocalISO = (d: Date = new Date()) => {
    const offset = d.getTimezoneOffset() * 60000;
    return new Date(d.getTime() - offset).toISOString().slice(0, 16);
  };

  const [manualDate, setManualDate] = useState<string>(getLocalISO());
  const [autoTime, setAutoTime] = useState(true);
  const [nowDisplay, setNowDisplay] = useState(new Date());

  // Ticket Modal State (Internal Viewer)
  const [viewingTicket, setViewingTicket] = useState<Sale | null>(null);

  const [paidCash, setPaidCash] = useState<string>('');
  const [paidTransfer, setPaidTransfer] = useState<string>('');

  // Efecto del Reloj
  useEffect(() => {
    let interval: any;
    if (autoTime) {
      interval = setInterval(() => {
        const d = new Date();
        setNowDisplay(d);
        setManualDate(getLocalISO(d));
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [autoTime]);

  const handleDateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setAutoTime(false);
    setManualDate(e.target.value);
  };

  const total = cart.reduce((sum, item) => {
    const price = (customer?.specialPrice && item.id === '1') ? customer.specialPrice : item.price;
    return sum + (price * item.quantity);
  }, 0);

  const totalPaid = (parseFloat(paidCash) || 0) + (parseFloat(paidTransfer) || 0);

  // Lógica de Deuda vs Cambio
  const remainingBalance = total - totalPaid;
  const isCreditSale = remainingBalance > 0.01; // Pequeño margen por decimales
  const change = Math.max(0, totalPaid - total);

  // Auto-calcular vacíos basado en garrafones vendidos (sugerencia)
  useEffect(() => {
    const garrafonesInCart = cart.filter(i => i.name.toLowerCase().includes('garraf') || i.category === 'Agua').reduce((acc, i) => acc + i.quantity, 0);
    if (cart.length > 0 && vacios === 0) {
      setVacios(garrafonesInCart);
    } else if (cart.length === 0) {
      setVacios(0);
    }
  }, [cart]);

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === product.id);
      if (existing) return prev.map(i => i.id === product.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  // NEW: Decrease quantity functionality
  const decreaseQuantity = (productId: string) => {
    setCart(prev => prev.map(item => {
      if (item.id === productId) {
        return { ...item, quantity: Math.max(0, item.quantity - 1) };
      }
      return item;
    }).filter(item => item.quantity > 0));
  };

  // NEW: Remove item completely
  const removeFromCart = (productId: string) => {
    setCart(prev => prev.filter(item => item.id !== productId));
  };

  const handleSendWhatsApp = (sale: Sale) => {
    // Buscar el cliente para asegurar datos actualizados
    const currentCustomer = customers.find(c => c.id === sale.customerId);
    const phone = currentCustomer?.phone?.replace(/\D/g, '') || '';

    if (!phone) {
      alert("El cliente no tiene teléfono registrado.");
      return;
    }

    const itemsText = sale.items.map(i => `• ${i.quantity}x ${i.name}`).join('%0A');
    const debtMsg = sale.paidAmount < sale.total ? `%0A%0A⚠️ *Saldo Pendiente:* $${(sale.total - sale.paidAmount).toFixed(2)}` : '';

    const fullPhone = phone.length === 10 ? `52${phone}` : phone;

    const msg = `¡Hola ${sale.customerAlias}!%0A%0A*${ticketConfig.businessName}*%0AGracias por tu compra.%0A%0A*Detalles de tu pedido:*%0A${itemsText}%0A%0A*Envases Recibidos:* ${sale.emptyGarrafonsReturned}%0A*Total:* $${sale.total.toFixed(2)}${debtMsg}%0A*Ticket:* ${sale.id}%0A%0A_Validación de seguridad QR disponible en planta._`;
    window.open(`https://wa.me/${fullPhone}?text=${msg}`, '_blank');
  };

  const handleCheckout = () => {
    if (!customer) return alert("Selecciona un cliente.");
    if (cart.length === 0) return alert("El carrito está vacío.");

    const splits: PaymentSplit[] = [];
    if (parseFloat(paidCash) > 0) splits.push({ method: 'Efectivo', amount: parseFloat(paidCash) });
    if (parseFloat(paidTransfer) > 0) splits.push({ method: 'Transferencia', amount: parseFloat(paidTransfer) });

    const sale = addSale(
      customer.id, cart, total, totalPaid, splits, vacios, 
      user.role === 'Administrador' ? new Date(manualDate).getTime() : undefined
    );

    // Abrir visor de ticket interno
    setViewingTicket(sale);

    // Resetear formulario para que al cerrar el ticket ya esté listo
    setCart([]);
    setCustomer(null);
    setSearch('');
    setPaidCash('');
    setPaidTransfer('');
    setVacios(0);
    if (user.role === 'Administrador') setAutoTime(true); 
  };

  return (
    <div className="h-full flex flex-col animate-fadeIn bg-sky-50 pb-24 overflow-hidden relative">
      <ModuleHeader title="Punto de Venta" onBack={onBack} />

      <div className="px-6 flex gap-2 mb-4">
        <button onClick={() => setActiveTab('sell')} className={`flex-1 py-3 rounded-2xl text-xs font-bold ${activeTab === 'sell' ? 'bg-sky-600 text-white shadow-lg' : 'bg-white text-sky-400'}`}>Nueva Venta</button>
        <button onClick={() => setActiveTab('history')} className={`flex-1 py-3 rounded-2xl text-xs font-bold ${activeTab === 'history' ? 'bg-sky-600 text-white shadow-lg' : 'bg-white text-sky-400'}`}>Historial</button>
      </div>

      {activeTab === 'sell' ? (
        <div className="flex-1 overflow-y-auto px-6 space-y-6 pb-32 no-scrollbar">
          {/* Admin Date Control */}
          {user.role === 'Administrador' && (
            <div className={`p-4 rounded-[2.2rem] border transition-all duration-500 ${autoTime ? 'bg-white border-sky-100' : 'bg-amber-50 border-amber-200 shadow-inner'}`}>
              <div className="flex justify-between items-center mb-3">
                <div className="flex items-center gap-2">
                  <div className={`w-2.5 h-2.5 rounded-full ${autoTime ? 'bg-emerald-500 animate-pulse' : 'bg-amber-500'}`}></div>
                  <label className="text-[10px] font-black uppercase tracking-widest text-sky-900">
                    {autoTime ? 'TIEMPO REAL (INTERNET)' : 'MODO MANUAL (EDITANDO)'}
                  </label>
                </div>
                {!autoTime && (
                  <button onClick={() => setAutoTime(true)} className="flex items-center gap-1 text-[9px] font-black text-sky-500 uppercase bg-sky-50 px-3 py-1.5 rounded-full active:scale-95 transition-transform">
                    <i className="fas fa-rotate"></i> Sincronizar
                  </button>
                )}
              </div>

              <div className="flex gap-3 items-center">
                <div className="flex-1 relative">
                  <input 
                    type="datetime-local" 
                    className={`w-full border-none rounded-2xl p-4 text-xs font-black shadow-sm outline-none transition-all ${
                      autoTime 
                        ? 'bg-sky-50 text-sky-400 pointer-events-none opacity-80' 
                        : 'bg-white text-amber-600 ring-2 ring-amber-200'
                    }`}
                    value={manualDate}
                    onChange={handleDateChange}
                  />
                  {autoTime && (
                    <div className="absolute right-4 top-1/2 -translate-y-1/2 text-emerald-500 text-lg font-black tracking-tighter tabular-nums">
                      {nowDisplay.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit', second:'2-digit'})}
                    </div>
                  )}
                </div>
              </div>
            </div>
          )}

          <section>
            <div className="relative">
              <input type="text" placeholder="Buscar Cliente..." className="w-full bg-white border-none rounded-[2rem] py-5 px-8 shadow-sm outline-none" value={search} onChange={e => setSearch(e.target.value)} />
              {search && !customer && (
                <div className="absolute top-full left-0 right-0 bg-white shadow-2xl rounded-3xl mt-2 z-50 overflow-hidden border border-sky-50">
                  {customers.filter(c => c.alias.toLowerCase().includes(search.toLowerCase())).map(c => (
                    <button key={c.id} onClick={() => { setCustomer(c); setSearch(c.alias); }} className="w-full text-left p-4 hover:bg-sky-50 font-bold border-b border-sky-50 flex justify-between items-center">
                      <span className="text-sky-900">{c.alias}</span>
                      <span className="text-[10px] bg-sky-50 text-sky-400 px-3 py-1 rounded-full font-black">${c.balance}</span>
                    </button>
                  ))}
                </div>
              )}
            </div>
            {customer && (
              <div className="mt-4 flex items-center justify-between bg-sky-600 text-white p-4 rounded-[1.8rem] shadow-lg animate-fadeIn">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-white/20 rounded-2xl flex items-center justify-center"><i className="fas fa-user"></i></div>
                  <div>
                    <span className="text-[8px] font-black uppercase opacity-60 block">Cliente Activo</span>
                    <span className="font-black text-sm">{customer.alias}</span>
                    {customer.balance > 0 && (
                      <span className="text-[9px] bg-red-500/30 px-2 py-0.5 rounded ml-2 font-bold">Adeudo: ${customer.balance}</span>
                    )}
                  </div>
                </div>
                <button onClick={() => {setCustomer(null); setSearch('');}} className="w-10 h-10 bg-white/10 rounded-full flex items-center justify-center active:scale-90 transition-all"><i className="fas fa-times"></i></button>
              </div>
            )}
          </section>

          <div className="grid grid-cols-2 gap-3">
            {products.map(p => (
              <button key={p.id} onClick={() => addToCart(p)} className="bg-white p-5 rounded-[2.2rem] shadow-sm active:bg-sky-50 text-left relative overflow-hidden group border border-transparent hover:border-sky-100">
                <div className="text-xs font-black text-sky-900 uppercase tracking-tight mb-1">{p.name}</div>
                <div className="text-sky-600 font-black text-lg">${p.price}</div>
                <div className="absolute -bottom-2 -right-2 w-12 h-12 bg-sky-50 text-sky-100 flex items-center justify-center rounded-tl-3xl group-active:text-sky-200 transition-colors">
                  <i className="fas fa-plus"></i>
                </div>
              </button>
            ))}
          </div>

          {cart.length > 0 && (
            <RoundedCard className="shadow-2xl border-2 border-white">
              <div className="flex justify-between items-start mb-6">
                <div>
                  <span className="text-[10px] text-sky-400 font-black uppercase mb-1 block">Monto a Liquidar</span>
                  <span className="text-4xl font-black text-sky-900 tracking-tighter">${total.toFixed(2)}</span>
                </div>
                <button onClick={() => setCart([])} className="text-rose-400 text-xs font-bold uppercase underline">Vaciar</button>
              </div>

              <div className="space-y-3 mb-6">
                {cart.map(i => (
                  <div key={i.id} className="flex justify-between items-center bg-sky-50/50 p-2 rounded-2xl border border-sky-100">
                    <div className="flex flex-col">
                       <span className="text-[10px] font-black text-sky-900 uppercase">{i.name}</span>
                       <span className="text-xs font-bold text-sky-600">${(i.quantity * i.price).toFixed(2)}</span>
                    </div>

                    <div className="flex items-center gap-2 bg-white rounded-xl shadow-sm p-1">
                       <button onClick={() => decreaseQuantity(i.id)} className="w-8 h-8 flex items-center justify-center bg-sky-50 text-sky-600 rounded-lg active:bg-sky-200 transition-colors font-bold">-</button>
                       <span className="text-sm font-black text-sky-900 w-6 text-center">{i.quantity}</span>
                       <button onClick={() => addToCart(i)} className="w-8 h-8 flex items-center justify-center bg-sky-600 text-white rounded-lg active:scale-95 transition-transform font-bold">+</button>
                    </div>

                    <button onClick={() => removeFromCart(i.id)} className="w-8 h-8 flex items-center justify-center text-rose-400 hover:text-rose-600">
                       <i className="fas fa-trash"></i>
                    </button>
                  </div>
                ))}
              </div>

              {/* Control de Garrafones Vacíos */}
              <div className="mb-6 bg-white p-4 rounded-3xl border border-sky-100 flex justify-between items-center">
                 <span className="text-[10px] font-black text-sky-400 uppercase tracking-tight ml-2">Garrafones Vacíos Recibidos</span>
                 <div className="flex items-center gap-3 bg-sky-50 rounded-2xl p-1">
                    <button onClick={() => setVacios(Math.max(0, vacios - 1))} className="w-8 h-8 flex items-center justify-center bg-white text-sky-600 rounded-xl font-black shadow-sm">-</button>
                    <span className="text-lg font-black text-sky-900 w-6 text-center">{vacios}</span>
                    <button onClick={() => setVacios(vacios + 1)} className="w-8 h-8 flex items-center justify-center bg-sky-600 text-white rounded-xl font-black shadow-lg">+</button>
                 </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[9px] font-black text-sky-400 uppercase ml-2">Efectivo</label>
                  <input type="number" value={paidCash} onChange={e => setPaidCash(e.target.value)} className="w-full bg-sky-50 p-4 rounded-2xl font-black text-lg focus:ring-2 ring-sky-200 outline-none" placeholder="$ 0.00" />
                </div>
                <div className="space-y-1">
                  <label className="text-[9px] font-black text-sky-400 uppercase ml-2">Transf.</label>
                  <input type="number" value={paidTransfer} onChange={e => setPaidTransfer(e.target.value)} className="w-full bg-sky-50 p-4 rounded-2xl font-black text-lg focus:ring-2 ring-sky-200 outline-none" placeholder="$ 0.00" />
                </div>
              </div>

              <div className={`mt-4 p-5 rounded-[1.8rem] flex justify-between items-center border transition-colors ${isCreditSale ? 'bg-amber-50 border-amber-100' : 'bg-emerald-50 border-emerald-100'}`}>
                <div>
                  <span className={`text-[10px] font-black uppercase tracking-widest block ${isCreditSale ? 'text-amber-700' : 'text-emerald-700'}`}>
                    {isCreditSale ? 'Saldo Pendiente (Crédito)' : 'Cambio Sugerido'}
                  </span>
                  <span className={`text-2xl font-black tracking-tighter ${isCreditSale ? 'text-amber-600' : 'text-emerald-600'}`}>
                    ${isCreditSale ? remainingBalance.toFixed(2) : change.toFixed(2)}
                  </span>
                </div>
                <div className={`w-12 h-12 bg-white rounded-2xl flex items-center justify-center shadow-sm ${isCreditSale ? 'text-amber-500 shadow-amber-100' : 'text-emerald-500 shadow-emerald-100'}`}>
                  <i className={`fas ${isCreditSale ? 'fa-file-invoice-dollar' : 'fa-hand-holding-dollar'} text-xl`}></i>
                </div>
              </div>
            </RoundedCard>
          )}
        </div>
      ) : (
        <div className="flex-1 overflow-y-auto px-6 space-y-3 pb-10 no-scrollbar">
          {sales.length === 0 ? (
            <div className="text-center py-20 opacity-30">
               <i className="fas fa-receipt text-6xl mb-4"></i>
               <p className="text-xs font-black uppercase">Sin historial reciente</p>
            </div>
          ) : (
            sales.map(s => (
              <RoundedCard key={s.id} className="py-5 border-none shadow-sm group">
                <div className="flex justify-between items-start">
                  <div className="flex gap-4">
                    <div className="w-12 h-12 bg-sky-50 text-sky-600 rounded-2xl flex items-center justify-center text-xl">
                      <i className="fas fa-receipt"></i>
                    </div>
                    <div>
                      <h4 className="font-black text-sky-900 text-sm leading-tight">{s.customerAlias}</h4>
                      <p className="text-[9px] text-sky-400 font-bold uppercase mt-1">{new Date(s.timestamp).toLocaleString()}</p>
                      {s.paidAmount < s.total && (
                        <span className="text-[9px] text-amber-500 font-black uppercase bg-amber-50 px-2 py-0.5 rounded mt-1 inline-block">Crédito</span>
                      )}
                    </div>
                  </div>
                  <div className="text-right">
                    <span className="font-black text-sky-600 text-xl tracking-tighter">${s.total}</span>
                    <p className="text-[8px] font-black text-sky-300 uppercase">{s.id}</p>
                  </div>
                </div>
                <div className="flex gap-2 mt-5">
                   <button onClick={() => setViewingTicket(s)} className="flex-1 text-[9px] font-black uppercase bg-sky-100 text-sky-600 px-3 py-3 rounded-xl flex items-center justify-center gap-2 active:bg-sky-200 transition-colors">
                    <i className="fas fa-eye"></i> Ver Ticket
                   </button>
                   <button onClick={() => handleSendWhatsApp(s)} className="flex-1 text-[9px] font-black uppercase bg-emerald-100 text-emerald-600 px-3 py-3 rounded-xl flex items-center justify-center gap-2 active:bg-emerald-200 transition-colors">
                    <i className="fab fa-whatsapp"></i> WA
                   </button>
                </div>
              </RoundedCard>
            ))
          )}
        </div>
      )}

      {activeTab === 'sell' && (
        <div className="fixed bottom-0 left-0 right-0 p-6 bg-white/95 border-t border-sky-100 shadow-2xl z-50">
          <ActionButton onClick={handleCheckout} disabled={!customer || cart.length === 0}>
             {isCreditSale ? 'Registrar Venta a Crédito' : 'Completar Venta'}
          </ActionButton>
        </div>
      )}

      {/* Internal Ticket Viewer Modal */}
      {viewingTicket && (
        <TicketModal 
          sale={viewingTicket} 
          config={ticketConfig} 
          onClose={() => setViewingTicket(null)} 
          onWhatsApp={() => handleSendWhatsApp(viewingTicket)}
          onNewSale={() => {
            setViewingTicket(null);
            // El estado ya se limpió en handleCheckout, estamos listos
          }}
          onFinish={() => {
            setViewingTicket(null);
            setActiveTab('history');
          }}
        />
      )}
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard } from './ui/Cards';

type TimeRange = 'day' | 'week' | 'month';

export const ReportsModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const { sales, customers, products } = useERPData();
  const [timeRange, setTimeRange] = useState<TimeRange>('day');

  // Lógica de filtrado por fecha
  const filteredSales = useMemo(() => {
    const now = new Date();
    let startTime = 0;

    if (timeRange === 'day') {
      startTime = new Date(now.setHours(0,0,0,0)).getTime();
    } else if (timeRange === 'week') {
      const day = now.getDay(); // 0 is Sunday
      const diff = now.getDate() - day + (day === 0 ? -6 : 1); // Adjust when day is sunday
      const monday = new Date(now.setDate(diff));
      startTime = new Date(monday.setHours(0,0,0,0)).getTime();
    } else if (timeRange === 'month') {
      startTime = new Date(now.getFullYear(), now.getMonth(), 1).getTime();
    }

    return sales.filter(s => s.timestamp >= startTime);
  }, [sales, timeRange]);

  const totalGross = filteredSales.reduce((acc, s) => acc + (s.total || 0), 0);
  const totalPaid = filteredSales.reduce((acc, s) => acc + (s.paidAmount || 0), 0);
  const totalCredit = totalGross - totalPaid;

  // Payment Method Breakdown
  const paymentsByMethod = { cash: 0, transfer: 0 };
  filteredSales.forEach(s => {
    if (s.paymentSplits && Array.isArray(s.paymentSplits)) {
      s.paymentSplits.forEach(p => {
          if(p.method === 'Efectivo') paymentsByMethod.cash += (p.amount || 0);
          if(p.method === 'Transferencia') paymentsByMethod.transfer += (p.amount || 0);
      });
    } else {
      // Fallback for legacy data: assume paidAmount is Cash if not specified
      if (s.paidAmount > 0) {
        paymentsByMethod.cash += s.paidAmount;
      }
    }
  });
  const totalReceived = paymentsByMethod.cash + paymentsByMethod.transfer;

  const totalDebtBalance = customers.reduce((acc, c) => acc + (c.balance > 0 ? c.balance : 0), 0);
  const totalInventoryValue = products.reduce((acc, p) => acc + (p.stock * p.price), 0);

  // Top Customers Logic (Based on filtered period)
  const customerSpending: Record<string, { alias: string, total: number }> = {};
  filteredSales.forEach(s => {
      const cid = s.customerId || 'unknown';
      if(!customerSpending[cid]) customerSpending[cid] = { alias: s.customerAlias || 'Cliente', total: 0 };
      customerSpending[cid].total += (s.total || 0);
  });
  const topCustomers = Object.values(customerSpending).sort((a, b) => b.total - a.total).slice(0, 5);

  // Categorize sales by product
  const productStats: Record<string, { qty: number, total: number }> = {};
  filteredSales.forEach(s => {
    if (s.items && Array.isArray(s.items)) {
      s.items.forEach(item => {
        const name = item.name || 'Producto';
        if (!productStats[name]) productStats[name] = { qty: 0, total: 0 };
        productStats[name].qty += (item.quantity || 0);
        productStats[name].total += (item.quantity || 0) * (item.price || 0);
      });
    }
  });

  const maxQty = Math.max(...Object.values(productStats).map(s => s.qty), 1);
  const averageTicket = filteredSales.length > 0 ? totalGross / filteredSales.length : 0;

  return (
    <div className="h-full bg-sky-50 overflow-y-auto pb-32 no-scrollbar">
      <ModuleHeader title="Análisis de Negocio" onBack={onBack} />
      <div className="px-6 space-y-6 animate-fadeIn">

        {/* Selector de Rango */}
        <div className="flex bg-white p-1.5 rounded-[2rem] shadow-sm">
           <button onClick={() => setTimeRange('day')} className={`flex-1 py-3 rounded-[1.5rem] text-[10px] font-black uppercase tracking-widest transition-all ${timeRange === 'day' ? 'bg-sky-600 text-white shadow-md' : 'text-sky-400'}`}>Día</button>
           <button onClick={() => setTimeRange('week')} className={`flex-1 py-3 rounded-[1.5rem] text-[10px] font-black uppercase tracking-widest transition-all ${timeRange === 'week' ? 'bg-sky-600 text-white shadow-md' : 'text-sky-400'}`}>Semana</button>
           <button onClick={() => setTimeRange('month')} className={`flex-1 py-3 rounded-[1.5rem] text-[10px] font-black uppercase tracking-widest transition-all ${timeRange === 'month' ? 'bg-sky-600 text-white shadow-md' : 'text-sky-400'}`}>Mes</button>
        </div>

        {/* Financial Scorecard */}
        <section className="space-y-3">
          <h4 className="text-[10px] font-black uppercase text-sky-400 tracking-widest px-2">
            Resultados: {timeRange === 'day' ? 'Hoy' : timeRange === 'week' ? 'Esta Semana' : 'Este Mes'}
          </h4>
          <div className="grid grid-cols-2 gap-4">
            <div className="bg-white p-6 rounded-[2rem] shadow-sm border border-white">
              <div className="flex items-center gap-2 mb-2">
                <i className="fas fa-arrow-trend-up text-emerald-500 text-[10px]"></i>
                <p className="text-[9px] font-black uppercase text-sky-400 tracking-widest leading-none">Ventas Brutas</p>
              </div>
              <p className="text-2xl font-black text-sky-900 tracking-tighter">${totalGross.toLocaleString()}</p>
              <div className="mt-1 flex items-center gap-1">
                 <span className="text-[8px] font-bold text-sky-300">{filteredSales.length} Tickets</span>
              </div>
            </div>

            <div className="bg-white p-6 rounded-[2rem] shadow-sm border border-white">
              <div className="flex items-center gap-2 mb-2">
                <i className="fas fa-ticket text-sky-500 text-[10px]"></i>
                <p className="text-[9px] font-black uppercase text-sky-400 tracking-widest leading-none">Ticket Promedio</p>
              </div>
              <p className="text-2xl font-black text-sky-900 tracking-tighter">${averageTicket.toFixed(0)}</p>
              <div className="mt-1 flex items-center gap-1">
                 <span className="text-[8px] font-bold text-sky-300">Por venta</span>
              </div>
            </div>
          </div>

          {/* Payment Methods Chart */}
          {totalReceived > 0 ? (
             <RoundedCard className="bg-white border-none shadow-sm p-5">
                <p className="text-[10px] font-black uppercase text-sky-400 tracking-widest mb-3">Métodos de Pago (Recaudado)</p>
                <div className="flex h-4 rounded-full overflow-hidden mb-2">
                   <div style={{ width: `${(paymentsByMethod.cash/totalReceived)*100}%` }} className="bg-emerald-400 h-full"></div>
                   <div style={{ width: `${(paymentsByMethod.transfer/totalReceived)*100}%` }} className="bg-indigo-500 h-full"></div>
                </div>
                <div className="flex justify-between text-xs font-bold">
                   <div className="flex items-center gap-1">
                      <div className="w-2 h-2 rounded-full bg-emerald-400"></div>
                      <span className="text-sky-900">Efec: ${paymentsByMethod.cash.toLocaleString()}</span>
                   </div>
                   <div className="flex items-center gap-1">
                      <div className="w-2 h-2 rounded-full bg-indigo-500"></div>
                      <span className="text-sky-900">Transf: ${paymentsByMethod.transfer.toLocaleString()}</span>
                   </div>
                </div>
             </RoundedCard>
          ) : (
            <div className="bg-white p-4 rounded-3xl text-center">
              <p className="text-[10px] font-bold text-sky-300">Sin ingresos registrados en este periodo.</p>
            </div>
          )}

          <RoundedCard className="bg-sky-900 text-white border-none shadow-xl flex items-center justify-between p-7">
            <div>
              <p className="text-[9px] font-black text-sky-300 uppercase tracking-[0.2em] mb-1">Cuentas por Cobrar (Global)</p>
              <p className="text-3xl font-black tracking-tighter">${totalDebtBalance.toLocaleString()}</p>
            </div>
            <div className="w-14 h-14 bg-white/10 rounded-3xl flex items-center justify-center text-2xl text-sky-300">
              <i className="fas fa-sack-dollar"></i>
            </div>
          </RoundedCard>
        </section>

        {/* Product Performance Visualization */}
        <section className="space-y-4">
          <div className="flex justify-between items-center px-2">
            <h4 className="text-[10px] font-black uppercase text-sky-400 tracking-widest">Desempeño por Producto</h4>
          </div>
          <div className="bg-white p-7 rounded-[2.5rem] shadow-sm border border-white space-y-6">
            {Object.keys(productStats).length === 0 ? (
              <p className="text-center text-sky-300 text-xs italic py-4">Sin datos de ventas.</p>
            ) : (
              Object.entries(productStats).map(([name, stats]) => (
                <div key={name} className="space-y-2">
                  <div className="flex justify-between items-end">
                    <div>
                      <h5 className="text-[11px] font-black text-sky-900 uppercase leading-none">{name}</h5>
                      <span className="text-[9px] font-bold text-sky-400">{stats.qty} unidades vendidas</span>
                    </div>
                    <span className="text-sm font-black text-sky-600">${stats.total.toLocaleString()}</span>
                  </div>
                  <div className="w-full bg-sky-50 h-2.5 rounded-full overflow-hidden">
                    <div 
                      className="h-full bg-gradient-to-r from-sky-400 to-sky-600 transition-all duration-1000 ease-out rounded-full" 
                      style={{ width: `${(stats.qty / maxQty) * 100}%` }}
                    ></div>
                  </div>
                </div>
              ))
            )}
          </div>
        </section>

        {/* Top Customers */}
        <section className="space-y-4">
           <h4 className="text-[10px] font-black uppercase text-sky-400 tracking-widest px-2">Top Clientes ({timeRange === 'day' ? 'Hoy' : timeRange === 'week' ? 'Semana' : 'Mes'})</h4>
           <div className="bg-white p-2 rounded-[2rem] shadow-sm border border-white">
              {topCustomers.length === 0 ? (
                 <p className="text-center text-sky-300 text-xs italic py-4">Sin clientes activos.</p>
              ) : (
                topCustomers.map((c, idx) => (
                   <div key={idx} className="flex items-center justify-between p-4 border-b border-sky-50 last:border-none">
                      <div className="flex items-center gap-3">
                         <div className={`w-8 h-8 rounded-full flex items-center justify-center font-black text-white text-[10px] ${idx === 0 ? 'bg-amber-400' : 'bg-sky-200'}`}>
                            {idx + 1}
                         </div>
                         <span className="text-xs font-bold text-sky-900">{c.alias}</span>
                      </div>
                      <span className="text-xs font-black text-sky-600">${c.total.toLocaleString()}</span>
                   </div>
                ))
              )}
           </div>
        </section>

        {/* Assets & Inventory */}
        <section className="space-y-4">
          <h4 className="text-[10px] font-black uppercase text-sky-400 tracking-widest px-2">Inventario y Activos (Actual)</h4>
          <div className="grid grid-cols-2 gap-4">
            <div className="bg-white p-6 rounded-[2rem] shadow-sm border border-white">
              <p className="text-[9px] font-black uppercase text-sky-400 tracking-widest mb-1">Valor Stock</p>
              <p className="text-xl font-black text-sky-900">${totalInventoryValue.toLocaleString()}</p>
              <p className="text-[8px] font-bold text-sky-300 mt-1 uppercase">Estimado en piso</p>
            </div>
            <div className="bg-white p-6 rounded-[2rem] shadow-sm border border-white">
              <p className="text-[9px] font-black uppercase text-sky-400 tracking-widest mb-1">Items Bajos</p>
              <p className="text-xl font-black text-rose-500">{products.filter(p => p.stock < 15).length}</p>
              <p className="text-[8px] font-bold text-rose-300 mt-1 uppercase">Reabastecimiento</p>
            </div>
          </div>

          <div className="space-y-2">
            {products.filter(p => p.stock < 15).map(p => (
              <div key={p.id} className="bg-rose-50 border border-rose-100 p-4 rounded-3xl flex justify-between items-center animate-fadeIn">
                <div className="flex items-center gap-3">
                  <div className="w-8 h-8 bg-white rounded-xl flex items-center justify-center text-rose-500 shadow-sm">
                    <i className="fas fa-triangle-exclamation text-xs"></i>
                  </div>
                  <span className="text-[10px] font-black text-rose-900 uppercase">{p.name}</span>
                </div>
                <span className="text-xs font-black text-rose-600">{p.stock} Uds.</span>
              </div>
            ))}
          </div>
        </section>
      </div>
    </div>
  );
};

export type ViewType = 'dashboard' | 'pos' | 'orders' | 'logistics' | 'production' | 'sync' | 'whatsapp' | 'customers' | 'employees' | 'reports' | 'settings' | 'quality' | 'scanner' | 'inventory' | 'tickets';

export interface Product {
  id: string;
  name: string;
  price: number;
  stock: number;
  category?: 'Agua' | 'Insumos' | 'Accesorios';
}

export type GarrafonType = 'Aqua' | 'Bonafont' | 'Ciel' | 'E-Pura' | 'Generico';

export interface Customer {
  id: string;
  name: string;
  alias: string;
  address?: string; // New field
  phone?: string;
  specialPrice?: number;
  lat?: number;
  lng?: number;
  garrafonType?: GarrafonType;
  balance: number;
}

export interface TicketConfig {
  businessName: string;
  rfc: string;
  address: string;
  phone: string;
  footerMessage: string;
  logoUrl?: string;
  website?: string;
  socialMedia?: string;
  extraNote?: string;
  slogan?: string;
  email?: string;
}

export interface CloudConfig {
  url: string;
  apiKey: string;
  autoSync: boolean;
  lastSync?: number;
}

export interface Order {
  id: string;
  customerId: string;
  customerAlias: string;
  items: CartItem[];
  total: number;
  status: 'pendiente' | 'asignado' | 'entregado' | 'cancelado';
  vehicleId?: string;
  timestamp: number;
  priority: number;
}

export interface CartItem extends Product {
  quantity: number;
}

export type PaymentMethod = 'Efectivo' | 'Transferencia' | 'Crédito' | 'Multimodal';

export interface PaymentSplit {
  method: 'Efectivo' | 'Transferencia';
  amount: number;
}

export interface Sale {
  id: string;
  timestamp: number;
  customerId: string;
  customerAlias: string;
  items: CartItem[];
  total: number;
  paidAmount: number;
  change: number;
  paymentSplits: PaymentSplit[];
  emptyGarrafonsReturned: number;
  synced: boolean;
}

export interface QualityRecord {
  id: string;
  timestamp: number;
  type: 'Cruda' | 'Producto';
  ph: number;
  cloro: number;
  tds: number;
  dureza: number;
  color: string;
  sabor: string;
  turbiedad: string;
  employeeId: string;
}

export interface Task {
  id: string;
  employeeId: string;
  title: string;
  description?: string;
  status: 'pendiente' | 'completada';
  timestamp: number;
  date: string;
}

export interface Attendance {
  id: string;
  employeeId: string;
  timestamp: number;
  date: string;
  status: 'presente' | 'falta' | 'retardo';
}

export interface Employee {
  id: string;
  name: string;
  role: 'Repartidor' | 'Planta' | 'Administrador';
  phone: string;
  pin: string;
  permissions: ViewType[];
}

export interface Vehicle {
  id: string;
  plate: string;
  description: string;
  loadCapacity: number;
  currentLoad: number;
  inventory: CartItem[]; // Detalle de productos en la unidad
}

export interface SavedReport {
  id: string;
  timestamp: number;
  rangeType: 'day' | 'week' | 'month';
  dateLabel: string; // "12 Oct 2023" or "Semana 42"
  totalGross: number;
  totalTransactions: number;
  averageTicket: number;
  payments: { cash: number, transfer: number };
  topProducts: { name: string, qty: number, total: number }[];
  notes?: string;
}

import { useState, useEffect, useCallback } from 'react';
import { Product, Customer, Sale, CartItem, Order, Employee, Vehicle, PaymentSplit, ViewType, QualityRecord, Task, Attendance, TicketConfig, CloudConfig, SavedReport } from '../types';
import { INITIAL_PRODUCTS, INITIAL_CUSTOMERS } from '../constants';

const DEFAULT_PERMISSIONS: ViewType[] = ['dashboard', 'pos', 'orders', 'customers', 'logistics', 'inventory', 'whatsapp', 'production', 'sync', 'reports', 'settings', 'employees', 'quality', 'scanner', 'tickets'];

