  const [customers, setCustomers] = useState<Customer[]>(() => {
    const saved = localStorage.getItem('aqua_customers');
    return saved ? JSON.parse(saved).map((c: any) => ({ ...c, balance: c.balance || 0 })) : INITIAL_CUSTOMERS;
  });

  const [ticketConfig, setTicketConfig] = useState<TicketConfig>(() => {
    const saved = localStorage.getItem('aqua_ticket_config');
    return saved ? JSON.parse(saved) : INITIAL_TICKET_CONFIG;
  });

  const [cloudConfig, setCloudConfig] = useState<CloudConfig>(() => {
    const saved = localStorage.getItem('aqua_cloud_config');
    if (saved) {
      const parsed = JSON.parse(saved);
      if (!parsed.url || parsed.url === '') {
        return INITIAL_CLOUD_CONFIG;
      }
      return parsed;
    }
    return INITIAL_CLOUD_CONFIG;
  });

  const [sales, setSales] = useState<Sale[]>(() => {
    const saved = localStorage.getItem('aqua_sales');
    return saved ? JSON.parse(saved) : [];
  });

  const [orders, setOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('aqua_orders');
    return saved ? JSON.parse(saved) : [];
  });

  const [employees, setEmployees] = useState<Employee[]>(() => {
    const saved = localStorage.getItem('aqua_employees');
    const initial = saved ? JSON.parse(saved) : [
      { id: 'admin', name: 'Gerente General', role: 'Administrador', phone: '3312345678', pin: '1234', permissions: [...DEFAULT_PERMISSIONS] }
    ];
    return initial;
  });

  useEffect(() => {
    setEmployees(prev => prev.map(e => 
      e.role === 'Administrador' 
        ? { ...e, permissions: [...DEFAULT_PERMISSIONS] } 
        : e
    ));
  }, []);

  const [vehicles, setVehicles] = useState<Vehicle[]>(() => {
    const saved = localStorage.getItem('aqua_vehicles');
    // Migration: ensure inventory and fuelHistory arrays exist
    const parsed = saved ? JSON.parse(saved) : [{ id: 'v1', plate: 'ABC-123', description: 'Nissan NP300', loadCapacity: 60, currentLoad: 0, inventory: [], fuelHistory: [] }];
    return parsed.map((v: any) => ({
        ...v,
        inventory: v.inventory || [],
        fuelHistory: v.fuelHistory || []
    }));
  });

  const [qualityRecords, setQualityRecords] = useState<QualityRecord[]>(() => {
    const saved = localStorage.getItem('aqua_quality');
    return saved ? JSON.parse(saved) : [];
  });

  const [tasks, setTasks] = useState<Task[]>(() => {
    const saved = localStorage.getItem('aqua_tasks');
    return saved ? JSON.parse(saved) : [];
  });

  const [attendance, setAttendance] = useState<Attendance[]>(() => {
    const saved = localStorage.getItem('aqua_attendance');
    return saved ? JSON.parse(saved) : [];
  });

  const [savedReports, setSavedReports] = useState<SavedReport[]>(() => {
    const saved = localStorage.getItem('aqua_saved_reports');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => {
    localStorage.setItem('aqua_products', JSON.stringify(products));
    localStorage.setItem('aqua_customers', JSON.stringify(customers));
    localStorage.setItem('aqua_sales', JSON.stringify(sales));
    localStorage.setItem('aqua_orders', JSON.stringify(orders));
    localStorage.setItem('aqua_employees', JSON.stringify(employees));
    localStorage.setItem('aqua_vehicles', JSON.stringify(vehicles));
    localStorage.setItem('aqua_ticket_config', JSON.stringify(ticketConfig));
    localStorage.setItem('aqua_quality', JSON.stringify(qualityRecords));
    localStorage.setItem('aqua_tasks', JSON.stringify(tasks));
    localStorage.setItem('aqua_attendance', JSON.stringify(attendance));
    localStorage.setItem('aqua_cloud_config', JSON.stringify(cloudConfig));
    localStorage.setItem('aqua_saved_reports', JSON.stringify(savedReports));
  }, [products, customers, sales, orders, employees, vehicles, ticketConfig, qualityRecords, tasks, attendance, cloudConfig, savedReports]);

  const addSale = (
    customerId: string, 
    items: CartItem[], 
    total: number, 
    paidAmount: number, 
    splits: PaymentSplit[], 
    returnedVacios: number, 
    manualTimestamp?: number
  ) => {
    const debtAmount = Math.max(0, total - paidAmount);
    const newSale: Sale = {
      id: `TKT-${Date.now().toString().slice(-6)}`,
      timestamp: manualTimestamp || Date.now(),
      customerId,
      customerAlias: customers.find(c => c.id === customerId)?.alias || 'Anonimo',
      items,
      total,
      paidAmount,
      change: Math.max(0, paidAmount - total),
      paymentSplits: splits,
      emptyGarrafonsReturned: returnedVacios,
      synced: false
    };

    setSales(prev => [newSale, ...prev]);
    setCustomers(prev => prev.map(c => c.id === customerId ? { ...c, balance: (c.balance || 0) + debtAmount } : c));
    setProducts(prev => prev.map(p => {
      const cartItem = items.find(item => item.id === p.id);
      return cartItem ? { ...p, stock: p.stock - cartItem.quantity } : p;
    }));

    return newSale;
  };

  const syncData = useCallback((externalData: { sales: Sale[], customers: Customer[] }) => {
    if (!externalData || !externalData.sales) return false;
    let changesMade = false;

    setSales(prev => {
      const existingIds = new Set(prev.map(s => s.id));
      const newSales = externalData.sales.filter(s => !existingIds.has(s.id));
      if (newSales.length > 0) changesMade = true;
      return [...newSales, ...prev].sort((a, b) => b.timestamp - a.timestamp);
    });

    if (externalData.customers) {
      setCustomers(prev => {
        const existingMap = new Map(prev.map(c => [c.id, c]));
        externalData.customers.forEach(c => {
          if (!existingMap.has(c.id)) {
            existingMap.set(c.id, c);
            changesMade = true;
          }
        });
        return Array.from(existingMap.values());
      });
    }

    return changesMade;
  }, []);

  const importCustomers = useCallback((newCustomers: Customer[]) => {
    setCustomers(prev => {
      const existingIds = new Set(prev.map(c => c.id));
      const filteredNew = newCustomers.filter(c => !existingIds.has(c.id));
      return [...prev, ...filteredNew];
    });
  }, []);

  const loadVehicle = (vehicleId: string, product: Product, delta: number) => {
    // 1. Validar Stock Principal
    const currentProduct = products.find(p => p.id === product.id);
    if (!currentProduct) return;

    if (delta > 0 && currentProduct.stock < delta) {
        alert("Stock insuficiente en planta.");
        return;
    }

    // 2. Actualizar Vehículo
    setVehicles(prev => prev.map(v => {
        if (v.id !== vehicleId) return v;

        // Copiar inventario actual
        const newInventory = [...(v.inventory || [])];
        const existingItemIndex = newInventory.findIndex(i => i.id === product.id);

        if (existingItemIndex > -1) {
            const newQty = newInventory[existingItemIndex].quantity + delta;
            if (newQty <= 0) {
                newInventory.splice(existingItemIndex, 1);
            } else {
                newInventory[existingItemIndex] = { ...newInventory[existingItemIndex], quantity: newQty };
            }
        } else if (delta > 0) {
            newInventory.push({ ...product, quantity: delta });
        }

        // Recalcular carga total (unidades)
        const newLoad = newInventory.reduce((acc, item) => acc + item.quantity, 0);

        return { ...v, inventory: newInventory, currentLoad: newLoad };
    }));

    // 3. Actualizar Inventario Principal (Inverso al movimiento del vehículo)
    setProducts(prev => prev.map(p => {
        if (p.id === product.id) {
            return { ...p, stock: p.stock - delta };
        }
        return p;
    }));
  };

  const addFuelRecord = (vehicleId: string, record: FuelRecord) => {
    setVehicles(prev => prev.map(v => {
      if (v.id !== vehicleId) return v;
      return { 
        ...v, 
        fuelHistory: [record, ...(v.fuelHistory || [])] 
      };
    }));
  };

  return { 
    products, 
    saveProduct: (p: Product) => setProducts(prev => prev.find(x => x.id === p.id) ? prev.map(x => x.id === p.id ? p : x) : [...prev, p]),
    deleteProduct: (id: string) => setProducts(prev => prev.filter(p => p.id !== id)),
    customers, 
    saveCustomer: (c: Customer) => setCustomers(prev => prev.find(x => x.id === c.id) ? prev.map(x => x.id === c.id ? c : x) : [...prev, c]),
    deleteCustomer: (id: string) => setCustomers(prev => prev.filter(c => c.id !== id)),
    importCustomers,
    sales, addSale,
    orders, 
    setOrders,
    addOrder: (o: Partial<Order>) => {
      const newOrder: Order = {
        id: `ORD-${Date.now().toString().slice(-6)}`,
        timestamp: Date.now(),
        status: 'pendiente',
        priority: 1,
        items: [],
        total: 0,
        customerId: '',
        customerAlias: '',
        ...o
      } as Order;
      setOrders(prev => [newOrder, ...prev]);
    },
    updateOrder: (o: Order) => setOrders(prev => prev.map(item => item.id === o.id ? o : item)),
    employees, 
    saveEmployee: (e: Employee) => setEmployees(prev => prev.find(x => x.id === e.id) ? prev.map(x => x.id === e.id ? e : x) : [...prev, e]),
    vehicles, 
    setVehicles,
    loadVehicle,
    deleteVehicle: (id: string) => setVehicles(prev => prev.filter(v => v.id !== id)),
    addFuelRecord,
    tasks,
    addTask: (t: Partial<Task>) => {
      const newTask: Task = {
        id: `TSK-${Date.now().toString().slice(-4)}`,
        timestamp: Date.now(),
        status: 'pendiente',
        ...t
      } as Task;
      setTasks(prev => [newTask, ...prev]);
    },
    updateTaskStatus: (id: string, status: Task['status']) => setTasks(prev => prev.map(t => t.id === id ? { ...t, status } : t)),
    attendance,
    recordAttendance: (employeeId: string, status: Attendance['status']) => {
      const date = new Date().toISOString().split('T')[0];
      setAttendance(prev => {
        const filtered = prev.filter(a => !(a.employeeId === employeeId && a.date === date));
        return [{ id: `ATT-${Date.now()}`, employeeId, status, date, timestamp: Date.now() }, ...filtered];
      });
    },
    qualityRecords,
    addQualityRecord: (r: Partial<QualityRecord>) => {
      const newRecord: QualityRecord = {
        id: `QUAL-${Date.now().toString().slice(-4)}`,
        timestamp: Date.now(),
        employeeId: 'admin',
        ...r
      } as QualityRecord;
      setQualityRecords(prev => [newRecord, ...prev]);
    },
    ticketConfig, setTicketConfig,
    cloudConfig, setCloudConfig,
    syncData,
    savedReports,
    addSavedReport: (r: SavedReport) => setSavedReports(prev => [r, ...prev]),
    deleteSavedReport: (id: string) => setSavedReports(prev => prev.filter(r => r.id !== id))
  };
};

import React, { useState } from 'react';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';
import { Vehicle, Product, FuelRecord } from '../types';

export const LogisticsModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const { vehicles, setVehicles, loadVehicle, deleteVehicle, products, addFuelRecord } = useERPData();
  const [editingVehicle, setEditingVehicle] = useState<Partial<Vehicle> | null>(null);
  const [loadingVehicleId, setLoadingVehicleId] = useState<string | null>(null);

  // Fuel Management State
  const [fuelVehicleId, setFuelVehicleId] = useState<string | null>(null);
  const [fuelForm, setFuelForm] = useState<Partial<FuelRecord>>({
    mileage: undefined,
    liters: undefined,
    cost: undefined,
    notes: ''
  });

  const saveVehicle = () => {
    if (!editingVehicle?.plate || !editingVehicle?.description) return alert("Completa los datos.");
    setVehicles(prev => {
      const exists = prev.find(v => v.id === editingVehicle.id);
      if (exists) return prev.map(v => v.id === editingVehicle.id ? { ...v, ...editingVehicle } as Vehicle : v);
      return [...prev, { ...editingVehicle, id: editingVehicle.id || Date.now().toString(), currentLoad: 0, inventory: [], fuelHistory: [] } as Vehicle];
    });
    setEditingVehicle(null);
  };

  const handleDelete = () => {
    if (!editingVehicle?.id) return;
    if (confirm("¿Estás seguro de eliminar esta unidad de la flota?")) {
        deleteVehicle(editingVehicle.id);
        setEditingVehicle(null);
    }
  };

  const handleAddFuel = () => {
    if (!fuelVehicleId) return;
    if (!fuelForm.mileage || !fuelForm.liters || !fuelForm.cost) {
      alert("Por favor completa los campos de kilometraje, litros y costo.");
      return;
    }

    const newRecord: FuelRecord = {
      id: Date.now().toString(),
      date: Date.now(),
      mileage: fuelForm.mileage,
      liters: fuelForm.liters,
      cost: fuelForm.cost,
      notes: fuelForm.notes
    };

    addFuelRecord(fuelVehicleId, newRecord);
    setFuelForm({ mileage: undefined, liters: undefined, cost: undefined, notes: '' });
    // Keep modal open to show history update
  };

  // --- MODAL DE CARGA DE VEHÍCULO ---
  const LoadingModal = () => {
    const vehicle = vehicles.find(v => v.id === loadingVehicleId);
    if (!vehicle) return null;

    return (
      <div className="fixed inset-0 bg-sky-900/80 backdrop-blur-sm z-[100] flex items-center justify-center p-4 animate-fadeIn">
        <div className="bg-white w-full max-w-md rounded-[3rem] p-6 shadow-2xl max-h-[85vh] overflow-y-auto no-scrollbar">
          <div className="flex justify-between items-center mb-6">
            <div>
              <h3 className="text-xl font-black text-sky-900">Cargar Unidad</h3>
              <p className="text-[10px] text-sky-400 font-bold uppercase">{vehicle.description}</p>
            </div>
            <button onClick={() => setLoadingVehicleId(null)} className="w-10 h-10 bg-sky-50 rounded-full flex items-center justify-center text-sky-400"><i className="fas fa-times"></i></button>
          </div>

          <div className="space-y-4">
            {products.map(p => {
              const inVehicle = vehicle.inventory?.find(i => i.id === p.id)?.quantity || 0;
              return (
                <div key={p.id} className="bg-sky-50 p-4 rounded-2xl flex justify-between items-center border border-white shadow-sm">
                  <div>
                    <p className="text-[10px] font-black text-sky-900 uppercase mb-1">{p.name}</p>
                    <div className="flex gap-2">
                      <span className="text-[8px] bg-white px-2 py-0.5 rounded text-sky-400 font-bold">Planta: {p.stock}</span>
                      <span className="text-[8px] bg-sky-600 text-white px-2 py-0.5 rounded font-bold">Camión: {inVehicle}</span>
                    </div>
                  </div>
                  <div className="flex items-center gap-3">
                    <button 
                      onClick={() => loadVehicle(vehicle.id, p, -1)}
                      className="w-8 h-8 bg-white rounded-xl text-sky-600 font-black shadow-sm active:scale-90 transition-transform"
                    >
                      -
                    </button>
                    <span className="w-4 text-center font-black text-sky-900">{inVehicle}</span>
                    <button 
                      onClick={() => loadVehicle(vehicle.id, p, 1)}
                      className="w-8 h-8 bg-sky-600 rounded-xl text-white font-black shadow-lg shadow-sky-200 active:scale-90 transition-transform"
                    >
                      +
                    </button>
                  </div>
                </div>
              );
            })}
          </div>

          <div className="mt-6 pt-4 border-t border-sky-100 flex justify-between items-center">
             <div>
               <p className="text-[9px] font-black text-sky-400 uppercase">Capacidad Total</p>
               <p className="text-xl font-black text-sky-900">{vehicle.currentLoad} / {vehicle.loadCapacity}</p>
             </div>
             <button onClick={() => setLoadingVehicleId(null)} className="px-8 py-3 bg-emerald-500 text-white rounded-2xl font-black text-xs uppercase shadow-lg shadow-emerald-200">
               Listo
             </button>
          </div>
        </div>
      </div>
    );
  };

  // --- MODAL DE COMBUSTIBLE ---
  const FuelModal = () => {
    const vehicle = vehicles.find(v => v.id === fuelVehicleId);
    if (!vehicle) return null;

    const history = vehicle.fuelHistory || [];
    const costPerLiter = (fuelForm.cost && fuelForm.liters) ? (fuelForm.cost / fuelForm.liters) : 0;

    return (
      <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-sm z-[100] flex items-center justify-center p-4 animate-fadeIn">
        <div className="bg-white w-full max-w-md rounded-[2.5rem] p-6 shadow-2xl max-h-[90vh] overflow-y-auto no-scrollbar">
          <div className="flex justify-between items-center mb-6">
            <div className="flex items-center gap-3">
              <div className="w-12 h-12 bg-amber-500 text-white rounded-2xl flex items-center justify-center text-xl shadow-lg shadow-amber-200">
                <i className="fas fa-gas-pump"></i>
              </div>
              <div>
                <h3 className="text-lg font-black text-sky-900">Combustible</h3>
                <p className="text-[10px] text-sky-400 font-bold uppercase">{vehicle.plate}</p>
              </div>
            </div>
            <button onClick={() => setFuelVehicleId(null)} className="w-10 h-10 bg-slate-100 rounded-full flex items-center justify-center text-slate-400 hover:bg-slate-200 transition-colors"><i className="fas fa-times"></i></button>
          </div>

          {/* Formulario de Registro */}
          <div className="bg-slate-50 p-5 rounded-[2rem] border border-slate-100 mb-6">
             <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Registrar Carga</h4>

             <div className="grid grid-cols-2 gap-3 mb-3">
               <div>
                 <label className="text-[9px] font-black text-slate-400 uppercase ml-2 block mb-1">Kilometraje</label>
                 <div className="relative">
                   <i className="fas fa-gauge absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 text-xs"></i>
                   <input 
                     type="number" 
                     className="w-full bg-white p-3 pl-9 rounded-xl outline-none text-sm font-bold text-slate-700 shadow-sm"
                     placeholder="KM"
                     value={fuelForm.mileage || ''}
                     onChange={e => setFuelForm({...fuelForm, mileage: Number(e.target.value)})}
                   />
                 </div>
               </div>
               <div>
                 <label className="text-[9px] font-black text-slate-400 uppercase ml-2 block mb-1">Litros</label>
                 <div className="relative">
                   <i className="fas fa-droplet absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 text-xs"></i>
                   <input 
                     type="number" 
                     className="w-full bg-white p-3 pl-9 rounded-xl outline-none text-sm font-bold text-slate-700 shadow-sm"
                     placeholder="L"
                     value={fuelForm.liters || ''}
                     onChange={e => setFuelForm({...fuelForm, liters: Number(e.target.value)})}
                   />
                 </div>
               </div>
             </div>

             <div className="mb-3">
               <label className="text-[9px] font-black text-slate-400 uppercase ml-2 block mb-1">Costo Total ($)</label>
               <div className="relative">
                 <i className="fas fa-dollar-sign absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 text-xs"></i>
                 <input 
                   type="number" 
                   className="w-full bg-white p-3 pl-9 rounded-xl outline-none text-lg font-black text-emerald-600 shadow-sm"
                   placeholder="0.00"
                   value={fuelForm.cost || ''}
                   onChange={e => setFuelForm({...fuelForm, cost: Number(e.target.value)})}
                 />
                 {costPerLiter > 0 && (
                   <span className="absolute right-4 top-1/2 -translate-y-1/2 text-[9px] font-bold text-slate-400 bg-slate-100 px-2 py-0.5 rounded">
                     ${costPerLiter.toFixed(2)} / L
                   </span>
                 )}
               </div>
             </div>

             <button 
               onClick={handleAddFuel}
               className="w-full py-3 bg-amber-500 text-white rounded-xl font-black uppercase text-[10px] tracking-widest shadow-lg shadow-amber-200 active:scale-95 transition-all"
             >
               Guardar Registro
             </button>
          </div>

          {/* Historial */}
          <div>
            <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 ml-2">Historial Reciente</h4>
            <div className="space-y-2 max-h-60 overflow-y-auto no-scrollbar">
               {history.length === 0 ? (
                 <div className="text-center py-8 opacity-40">
                   <i className="fas fa-gas-pump text-4xl text-slate-300 mb-2"></i>
                   <p className="text-[10px] font-bold text-slate-400">Sin registros</p>
                 </div>
               ) : (
                 history.map(r => (
                   <div key={r.id} className="bg-white p-3 rounded-2xl shadow-sm border border-slate-50 flex justify-between items-center">
                      <div>
                         <p className="text-[10px] font-black text-slate-400 uppercase">{new Date(r.date).toLocaleDateString()}</p>
                         <p className="text-xs font-bold text-slate-700">{r.mileage.toLocaleString()} km</p>
                      </div>
                      <div className="text-right">
                         <p className="text-sm font-black text-emerald-600">${r.cost.toLocaleString()}</p>
                         <p className="text-[9px] font-bold text-amber-500">{r.liters} L</p>
                      </div>
                   </div>
                 ))
               )}
            </div>
          </div>

        </div>
      </div>
    );
  };

  if (editingVehicle) {
    return (
      <div className="h-full bg-sky-50 animate-fadeIn">
        <ModuleHeader title={editingVehicle.id ? "Editar Vehículo" : "Nueva Unidad"} onBack={() => setEditingVehicle(null)} />
        <div className="px-6 space-y-5">
           <input className="w-full bg-white p-5 rounded-[2rem] shadow-sm outline-none font-bold text-sky-900" placeholder="Placa" value={editingVehicle.plate || ''} onChange={e => setEditingVehicle({...editingVehicle, plate: e.target.value})}/>
           <input className="w-full bg-white p-5 rounded-[2rem] shadow-sm outline-none font-bold text-sky-900" placeholder="Descripción (Ej: Nissan Blanca)" value={editingVehicle.description || ''} onChange={e => setEditingVehicle({...editingVehicle, description: e.target.value})}/>
           <div className="space-y-1">
              <label className="text-[10px] font-black text-sky-400 uppercase ml-4">Capacidad Total (Unidades)</label>
              <input type="number" className="w-full bg-white p-5 rounded-[2rem] shadow-sm outline-none font-black text-sky-600 text-xl" value={editingVehicle.loadCapacity || ''} onChange={e => setEditingVehicle({...editingVehicle, loadCapacity: Number(e.target.value)})}/>
           </div>

           <ActionButton onClick={saveVehicle}>Guardar Unidad</ActionButton>

           {editingVehicle.id && (
             <button 
                onClick={handleDelete}
                className="w-full py-4 text-rose-500 font-black uppercase text-[10px] tracking-widest bg-rose-50 rounded-[2rem] border border-rose-100 shadow-sm active:scale-95 transition-all"
             >
                <i className="fas fa-trash-can mr-2"></i> Eliminar Unidad
             </button>
           )}
        </div>
      </div>
    );
  }

  return (
    <div className="h-full bg-sky-50 overflow-y-auto no-scrollbar pb-24">
      <ModuleHeader title="Gestión de Flota" onBack={onBack} />
      <div className="px-6 space-y-6">
        <RoundedCard className="bg-sky-100/50 border-sky-200">
           <div className="flex items-start gap-4">
              <i className="fas fa-info-circle text-sky-500 mt-1"></i>
              <p className="text-[10px] font-bold text-sky-700 leading-tight">
                Nota: Al cargar una unidad, el stock se descuenta del inventario principal. Al descargar, regresa a planta.
              </p>
           </div>
        </RoundedCard>

        {vehicles.map(v => (
          <RoundedCard key={v.id} className="relative overflow-hidden border-none shadow-xl bg-white group active:scale-[0.99] transition-all p-0">
             <div className="p-6 pb-4">
               <div className="flex justify-between items-start mb-6">
                 <div className="flex gap-4">
                   <div className="w-14 h-14 bg-sky-900 text-white rounded-[1.5rem] flex items-center justify-center text-xl shadow-lg shadow-sky-100">
