// --- COMPONENTE MODAL DE COBRO ---
interface PaymentModalProps {
  total: number;
  onConfirm: (cash: number, transfer: number) => void;
  onCancel: () => void;
}

const PaymentModal = ({ total, onConfirm, onCancel }: PaymentModalProps) => {
  const [cash, setCash] = useState('');
  const [transfer, setTransfer] = useState('');

  const numCash = parseFloat(cash) || 0;
  const numTransfer = parseFloat(transfer) || 0;
  const totalPaid = numCash + numTransfer;
  const change = totalPaid - total;
  const remaining = total - totalPaid;
  const isComplete = totalPaid >= total;
  const isCredit = !isComplete && totalPaid > 0; // Partial payment implies credit intent

  return (
    <div className="fixed inset-0 z-[150] bg-slate-900/80 backdrop-blur-sm flex items-end justify-center sm:items-center p-0 sm:p-4 animate-fadeIn">
      <div className="bg-white w-full max-w-md rounded-t-[2.5rem] sm:rounded-[2.5rem] p-6 shadow-2xl">
         <div className="flex justify-between items-center mb-6">
            <h3 className="text-xl font-black text-sky-900">Cobrar Venta</h3>
            <button onClick={onCancel} className="w-10 h-10 bg-slate-100 rounded-full text-slate-400 flex items-center justify-center"><i className="fas fa-times"></i></button>
         </div>

         <div className="text-center mb-8">
            <p className="text-xs font-black uppercase text-slate-400 tracking-widest mb-1">Total a Pagar</p>
            <p className="text-5xl font-black text-slate-900 tracking-tighter">${total.toFixed(2)}</p>
         </div>

         <div className="space-y-4 mb-8">
            <div className="bg-sky-50 p-4 rounded-2xl flex items-center gap-4 border border-sky-100 focus-within:ring-2 ring-sky-300 transition-all">
               <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center text-sky-600 shadow-sm"><i className="fas fa-money-bill"></i></div>
               <div className="flex-1">
                  <label className="text-[9px] font-black uppercase text-sky-400 block">Efectivo</label>
                  <input 
                    type="number" 
                    placeholder="0.00" 
                    className="w-full bg-transparent font-black text-xl text-sky-900 outline-none"
                    value={cash}
                    onChange={e => setCash(e.target.value)}
                    autoFocus
                  />
               </div>
            </div>

            <div className="bg-sky-50 p-4 rounded-2xl flex items-center gap-4 border border-sky-100 focus-within:ring-2 ring-sky-300 transition-all">
               <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center text-indigo-500 shadow-sm"><i className="fas fa-building-columns"></i></div>
               <div className="flex-1">
                  <label className="text-[9px] font-black uppercase text-indigo-400 block">Transferencia</label>
                  <input 
                    type="number" 
                    placeholder="0.00" 
                    className="w-full bg-transparent font-black text-xl text-indigo-900 outline-none"
                    value={transfer}
                    onChange={e => setTransfer(e.target.value)}
                  />
               </div>
            </div>
         </div>

         <div className={`p-5 rounded-2xl mb-6 transition-colors flex justify-between items-center ${
            isComplete ? 'bg-emerald-100 text-emerald-700' : remaining > 0.1 ? 'bg-amber-100 text-amber-700' : 'bg-slate-100'
         }`}>
            <span className="text-xs font-black uppercase">
               {isComplete ? 'Cambio a entregar:' : 'Saldo Pendiente (Crédito):'}
            </span>
            <span className="text-2xl font-black">
               ${isComplete ? change.toFixed(2) : remaining.toFixed(2)}
            </span>
         </div>

         <ActionButton 
            onClick={() => onConfirm(numCash, numTransfer)} 
            disabled={totalPaid === 0 && !isCredit}
            variant={isComplete ? 'primary' : 'secondary'}
         >
            {isComplete ? 'Cobrar y Emitir Ticket' : 'Registrar Venta a Crédito'}
         </ActionButton>
      </div>
    </div>
  );
};

export const POSModule: React.FC<{ onBack: () => void; user: Employee }> = ({ onBack, user }) => {
  const { products, customers, sales, addSale, ticketConfig } = useERPData();
  const [activeTab, setActiveTab] = useState<'sell' | 'history'>('sell');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [customer, setCustomer] = useState<Customer | null>(null);
  const [search, setSearch] = useState('');
  const [vacios, setVacios] = useState(0);

  // States para modales
  const [showPaymentModal, setShowPaymentModal] = useState(false);
  const [viewingTicket, setViewingTicket] = useState<Sale | null>(null);

  // Admin Time Control
  const getLocalISO = (d: Date = new Date()) => {
    const offset = d.getTimezoneOffset() * 60000;
    return new Date(d.getTime() - offset).toISOString().slice(0, 16);
  };
  const [manualDate, setManualDate] = useState<string>(getLocalISO());
  const [autoTime, setAutoTime] = useState(true);
  const [nowDisplay, setNowDisplay] = useState(new Date());

  useEffect(() => {
    let interval: any;
    if (autoTime) {
      interval = setInterval(() => {
        const d = new Date();
        setNowDisplay(d);
        setManualDate(getLocalISO(d));
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [autoTime]);

  const handleDateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setAutoTime(false);
    setManualDate(e.target.value);
  };

  const total = cart.reduce((sum, item) => {
    const price = (customer?.specialPrice && item.id === '1') ? customer.specialPrice : item.price;
    return sum + (price * item.quantity);
  }, 0);

  // Auto-calc vacios
  useEffect(() => {
    const garrafonesInCart = cart.filter(i => i.name.toLowerCase().includes('garraf') || i.category === 'Agua').reduce((acc, i) => acc + i.quantity, 0);
    if (cart.length > 0 && vacios === 0) setVacios(garrafonesInCart);
    else if (cart.length === 0) setVacios(0);
  }, [cart]);

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === product.id);
      if (existing) return prev.map(i => i.id === product.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const decreaseQuantity = (productId: string) => {
    setCart(prev => prev.map(item => {
      if (item.id === productId) {
        return { ...item, quantity: Math.max(0, item.quantity - 1) };
      }
      return item;
    }).filter(item => item.quantity > 0));
  };

  const removeFromCart = (productId: string) => {
    setCart(prev => prev.filter(item => item.id !== productId));
  };

  const handleSendWhatsApp = (sale: Sale) => {
    const currentCustomer = customers.find(c => c.id === sale.customerId);
    const phone = currentCustomer?.phone?.replace(/\D/g, '') || '';
    if (!phone) { alert("El cliente no tiene teléfono registrado."); return; }
    const itemsText = sale.items.map(i => `• ${i.quantity}x ${i.name}`).join('%0A');
    const debtMsg = sale.paidAmount < sale.total ? `%0A%0A⚠️ *Saldo Pendiente:* $${(sale.total - sale.paidAmount).toFixed(2)}` : '';
    const fullPhone = phone.length === 10 ? `52${phone}` : phone;
    const msg = `¡Hola ${sale.customerAlias}!%0A%0A*${ticketConfig.businessName}*%0AGracias por tu compra.%0A%0A*Pedido:*%0A${itemsText}%0A%0A*Total:* $${sale.total.toFixed(2)}${debtMsg}%0A*Folio:* ${sale.id}%0A%0A_Excelente día._`;
    window.open(`https://wa.me/${fullPhone}?text=${msg}`, '_blank');
  };

  const handlePreCheckout = () => {
    if (!customer) return alert("Selecciona un cliente.");
    if (cart.length === 0) return alert("El carrito está vacío.");
    setShowPaymentModal(true);
  };

  const handleConfirmPayment = (cash: number, transfer: number) => {
    if(!customer) return;

    const totalPaid = cash + transfer;
    const splits: PaymentSplit[] = [];
    if (cash > 0) splits.push({ method: 'Efectivo', amount: cash });
    if (transfer > 0) splits.push({ method: 'Transferencia', amount: transfer });

    const sale = addSale(
      customer.id, cart, total, totalPaid, splits, vacios, 
      user.role === 'Administrador' ? new Date(manualDate).getTime() : undefined
    );

    setShowPaymentModal(false);
    setViewingTicket(sale); // Mostrar ticket
  };

  const resetPOS = () => {
    setViewingTicket(null);
    setCart([]);
    setCustomer(null);
    setSearch('');
    setVacios(0);
    if (user.role === 'Administrador') setAutoTime(true); 
  };

  return (
    <div className="h-full flex flex-col animate-fadeIn bg-sky-50 pb-24 overflow-hidden relative">
      <ModuleHeader title="Punto de Venta" onBack={onBack} />

      <div className="px-6 flex gap-2 mb-4">
        <button onClick={() => setActiveTab('sell')} className={`flex-1 py-3 rounded-2xl text-xs font-bold ${activeTab === 'sell' ? 'bg-sky-600 text-white shadow-lg' : 'bg-white text-sky-400'}`}>Nueva Venta</button>
        <button onClick={() => setActiveTab('history')} className={`flex-1 py-3 rounded-2xl text-xs font-bold ${activeTab === 'history' ? 'bg-sky-600 text-white shadow-lg' : 'bg-white text-sky-400'}`}>Historial</button>
      </div>

      {activeTab === 'sell' ? (
        <div className="flex-1 overflow-y-auto px-6 space-y-6 pb-32 no-scrollbar">
          {/* Admin Date Control */}
          {user.role === 'Administrador' && (
            <div className={`p-4 rounded-[2.2rem] border transition-all duration-500 ${autoTime ? 'bg-white border-sky-100' : 'bg-amber-50 border-amber-200 shadow-inner'}`}>
              <div className="flex justify-between items-center mb-3">
                <div className="flex items-center gap-2">
                  <div className={`w-2.5 h-2.5 rounded-full ${autoTime ? 'bg-emerald-500 animate-pulse' : 'bg-amber-500'}`}></div>
                  <label className="text-[10px] font-black uppercase tracking-widest text-sky-900">
                    {autoTime ? 'TIEMPO REAL' : 'MODO MANUAL'}
                  </label>
                </div>
                {!autoTime && (
                  <button onClick={() => setAutoTime(true)} className="flex items-center gap-1 text-[9px] font-black text-sky-500 uppercase bg-sky-50 px-3 py-1.5 rounded-full active:scale-95 transition-transform">
                    <i className="fas fa-rotate"></i> Sincronizar
                  </button>
                )}
              </div>

              <div className="flex gap-3 items-center">
                <div className="flex-1 relative">
                  <input 
                    type="datetime-local" 
                    className={`w-full border-none rounded-2xl p-4 text-xs font-black shadow-sm outline-none transition-all ${
                      autoTime 
                        ? 'bg-sky-50 text-sky-400 pointer-events-none opacity-80' 
                        : 'bg-white text-amber-600 ring-2 ring-amber-200'
                    }`}
                    value={manualDate}
                    onChange={handleDateChange}
                  />
                </div>
              </div>
            </div>
          )}

          <section>
            <div className="relative">
              <input type="text" placeholder="Buscar Cliente..." className="w-full bg-white border-none rounded-[2rem] py-5 px-8 shadow-sm outline-none" value={search} onChange={e => setSearch(e.target.value)} />
              {search && !customer && (
                <div className="absolute top-full left-0 right-0 bg-white shadow-2xl rounded-3xl mt-2 z-50 overflow-hidden border border-sky-50 max-h-60 overflow-y-auto">
                  {customers.filter(c => c.alias.toLowerCase().includes(search.toLowerCase())).map(c => (
                    <button key={c.id} onClick={() => { setCustomer(c); setSearch(c.alias); }} className="w-full text-left p-4 hover:bg-sky-50 font-bold border-b border-sky-50 flex justify-between items-center">
                      <span className="text-sky-900">{c.alias}</span>
                      <span className="text-[10px] bg-sky-50 text-sky-400 px-3 py-1 rounded-full font-black">${c.balance}</span>
                    </button>
                  ))}
                </div>
              )}
            </div>
            {customer && (
              <div className="mt-4 flex items-center justify-between bg-sky-600 text-white p-4 rounded-[1.8rem] shadow-lg animate-fadeIn">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-white/20 rounded-2xl flex items-center justify-center"><i className="fas fa-user"></i></div>
                  <div>
                    <span className="text-[8px] font-black uppercase opacity-60 block">Cliente Activo</span>
                    <span className="font-black text-sm">{customer.alias}</span>
                    {customer.balance > 0 && (
                      <span className="text-[9px] bg-red-500/30 px-2 py-0.5 rounded ml-2 font-bold">Adeudo: ${customer.balance}</span>
                    )}
                  </div>
                </div>
                <button onClick={() => {setCustomer(null); setSearch('');}} className="w-10 h-10 bg-white/10 rounded-full flex items-center justify-center active:scale-90 transition-all"><i className="fas fa-times"></i></button>
              </div>
            )}
          </section>

          <div className="grid grid-cols-2 gap-3">
            {products.map(p => (
              <button key={p.id} onClick={() => addToCart(p)} className="bg-white p-5 rounded-[2.2rem] shadow-sm active:bg-sky-50 text-left relative overflow-hidden group border border-transparent hover:border-sky-100 transition-all">
                <div className="text-xs font-black text-sky-900 uppercase tracking-tight mb-1">{p.name}</div>
                <div className="text-sky-600 font-black text-lg">${p.price}</div>
                <div className="absolute -bottom-2 -right-2 w-12 h-12 bg-sky-50 text-sky-100 flex items-center justify-center rounded-tl-3xl group-active:text-sky-200 transition-colors">
                  <i className="fas fa-plus"></i>
                </div>
              </button>
            ))}
          </div>

          {cart.length > 0 && (
            <RoundedCard className="shadow-2xl border-2 border-white mb-20">
              <div className="flex justify-between items-start mb-6">
                <div>
                  <span className="text-[10px] text-sky-400 font-black uppercase mb-1 block">Total Carrito</span>
                  <span className="text-4xl font-black text-sky-900 tracking-tighter">${total.toFixed(2)}</span>
                </div>
                <button onClick={() => setCart([])} className="text-rose-400 text-xs font-bold uppercase underline">Vaciar</button>
              </div>

              <div className="space-y-3 mb-6">
                {cart.map(i => (
                  <div key={i.id} className="flex justify-between items-center bg-sky-50/50 p-2 rounded-2xl border border-sky-100">
                    <div className="flex flex-col">
                       <span className="text-[10px] font-black text-sky-900 uppercase max-w-[120px] truncate">{i.name}</span>
                       <span className="text-xs font-bold text-sky-600">${(i.quantity * i.price).toFixed(2)}</span>
                    </div>

                    <div className="flex items-center gap-2 bg-white rounded-xl shadow-sm p-1">
                       <button onClick={() => decreaseQuantity(i.id)} className="w-8 h-8 flex items-center justify-center bg-sky-50 text-sky-600 rounded-lg active:bg-sky-200 transition-colors font-bold">-</button>
                       <span className="text-sm font-black text-sky-900 w-6 text-center">{i.quantity}</span>
                       <button onClick={() => addToCart(i)} className="w-8 h-8 flex items-center justify-center bg-sky-600 text-white rounded-lg active:scale-95 transition-transform font-bold">+</button>
                    </div>
                  </div>
                ))}
              </div>

              {/* Control de Garrafones Vacíos */}
              <div className="mb-2 bg-white p-4 rounded-3xl border border-sky-100 flex justify-between items-center">
                 <span className="text-[10px] font-black text-sky-400 uppercase tracking-tight ml-2">Envases Vacíos</span>
                 <div className="flex items-center gap-3 bg-sky-50 rounded-2xl p-1">
                    <button onClick={() => setVacios(Math.max(0, vacios - 1))} className="w-8 h-8 flex items-center justify-center bg-white text-sky-600 rounded-xl font-black shadow-sm">-</button>
                    <span className="text-lg font-black text-sky-900 w-6 text-center">{vacios}</span>
                    <button onClick={() => setVacios(vacios + 1)} className="w-8 h-8 flex items-center justify-center bg-sky-600 text-white rounded-xl font-black shadow-lg">+</button>
                 </div>
              </div>
            </RoundedCard>
          )}
        </div>
      ) : (
        <div className="flex-1 overflow-y-auto px-6 space-y-3 pb-10 no-scrollbar">
          {sales.length === 0 ? (
            <div className="text-center py-20 opacity-30">
               <i className="fas fa-receipt text-6xl mb-4"></i>
               <p className="text-xs font-black uppercase">Sin historial reciente</p>
            </div>
          ) : (
            sales.map(s => (
              <RoundedCard key={s.id} className="py-5 border-none shadow-sm group">
                <div className="flex justify-between items-start">
                  <div className="flex gap-4">
                    <div className="w-12 h-12 bg-sky-50 text-sky-600 rounded-2xl flex items-center justify-center text-xl">
                      <i className="fas fa-receipt"></i>
                    </div>
                    <div>
                      <h4 className="font-black text-sky-900 text-sm leading-tight">{s.customerAlias}</h4>
                      <p className="text-[9px] text-sky-400 font-bold uppercase mt-1">{new Date(s.timestamp).toLocaleString()}</p>
                      {s.paidAmount < s.total && (
                        <span className="text-[9px] text-amber-500 font-black uppercase bg-amber-50 px-2 py-0.5 rounded mt-1 inline-block">Crédito</span>
                      )}
                    </div>
                  </div>
                  <div className="text-right">
                    <span className="font-black text-sky-600 text-xl tracking-tighter">${s.total}</span>
                    <p className="text-[8px] font-black text-sky-300 uppercase">{s.id}</p>
                  </div>
                </div>
                <div className="flex gap-2 mt-5">
                   <button onClick={() => setViewingTicket(s)} className="flex-1 text-[9px] font-black uppercase bg-sky-100 text-sky-600 px-3 py-3 rounded-xl flex items-center justify-center gap-2 active:bg-sky-200 transition-colors">
                    <i className="fas fa-eye"></i> Ver Ticket
                   </button>
                   <button onClick={() => handleSendWhatsApp(s)} className="flex-1 text-[9px] font-black uppercase bg-emerald-100 text-emerald-600 px-3 py-3 rounded-xl flex items-center justify-center gap-2 active:bg-emerald-200 transition-colors">
                    <i className="fab fa-whatsapp"></i> WA
                   </button>
                </div>
              </RoundedCard>
            ))
          )}
        </div>
      )}

      {activeTab === 'sell' && (
        <div className="fixed bottom-0 left-0 right-0 p-6 bg-white/95 border-t border-sky-100 shadow-[0_-10px_40px_rgba(0,0,0,0.1)] z-50">
          <ActionButton onClick={handlePreCheckout} disabled={!customer || cart.length === 0}>
             Ir a Pagar ${total.toFixed(2)}
          </ActionButton>
        </div>
      )}

      {/* Modales */}
      {showPaymentModal && (
        <PaymentModal 
          total={total}
          onConfirm={handleConfirmPayment}
          onCancel={() => setShowPaymentModal(false)}
        />
      )}

      {viewingTicket && (
        <TicketModal 
          sale={viewingTicket} 
          config={ticketConfig} 
          onClose={() => setViewingTicket(null)} 
          onWhatsApp={() => handleSendWhatsApp(viewingTicket)}
          onNewSale={resetPOS}
          onFinish={() => {
            setViewingTicket(null);
            setActiveTab('history');
          }}
        />
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';
import { Vehicle, Product, FuelRecord } from '../types';

export const LogisticsModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const { vehicles, setVehicles, loadVehicle, deleteVehicle, products, addFuelRecord } = useERPData();
  const [editingVehicle, setEditingVehicle] = useState<Partial<Vehicle> | null>(null);
  const [loadingVehicleId, setLoadingVehicleId] = useState<string | null>(null);

  // Fuel Management State
  const [fuelVehicleId, setFuelVehicleId] = useState<string | null>(null);
  const [fuelForm, setFuelForm] = useState<Partial<FuelRecord>>({
    mileage: undefined,
    liters: undefined,
    cost: undefined,
    notes: ''
  });

  const saveVehicle = () => {
    if (!editingVehicle?.plate || !editingVehicle?.description) return alert("Completa los datos.");
    setVehicles(prev => {
      const exists = prev.find(v => v.id === editingVehicle.id);
      if (exists) return prev.map(v => v.id === editingVehicle.id ? { ...v, ...editingVehicle } as Vehicle : v);
      return [...prev, { ...editingVehicle, id: editingVehicle.id || Date.now().toString(), currentLoad: 0, inventory: [], fuelHistory: [] } as Vehicle];
    });
    setEditingVehicle(null);
  };

  const handleDelete = () => {
    if (!editingVehicle?.id) return;
    if (confirm("¿Estás seguro de eliminar esta unidad de la flota?")) {
        deleteVehicle(editingVehicle.id);
        setEditingVehicle(null);
    }
  };

  const handleAddFuel = () => {
    if (!fuelVehicleId) return;
    if (!fuelForm.mileage || !fuelForm.liters || !fuelForm.cost) {
      alert("Por favor completa los campos de kilometraje, litros y costo.");
      return;
    }

    const newRecord: FuelRecord = {
      id: Date.now().toString(),
      date: Date.now(),
      mileage: fuelForm.mileage,
      liters: fuelForm.liters,
      cost: fuelForm.cost,
      notes: fuelForm.notes
    };

    addFuelRecord(fuelVehicleId, newRecord);
    setFuelForm({ mileage: undefined, liters: undefined, cost: undefined, notes: '' });
  };

  // --- MODAL DE CARGA DE VEHÍCULO (FIXED Z-INDEX) ---
  const LoadingModal = () => {
    const vehicle = vehicles.find(v => v.id === loadingVehicleId);
    if (!vehicle) return null;

    return (
      <div className="fixed inset-0 bg-sky-900/90 backdrop-blur-md z-[200] flex items-center justify-center p-4 animate-fadeIn">
        <div className="bg-white w-full max-w-md rounded-[2.5rem] p-6 shadow-2xl max-h-[90vh] flex flex-col">
          <div className="flex justify-between items-center mb-6 shrink-0">
            <div>
              <h3 className="text-xl font-black text-sky-900">Cargar Unidad</h3>
              <p className="text-[10px] text-sky-400 font-bold uppercase">{vehicle.description}</p>
            </div>
            <button onClick={() => setLoadingVehicleId(null)} className="w-10 h-10 bg-sky-50 rounded-full flex items-center justify-center text-sky-400"><i className="fas fa-times"></i></button>
          </div>

          <div className="flex-1 overflow-y-auto no-scrollbar space-y-3">
            {products.map(p => {
              const inVehicle = vehicle.inventory?.find(i => i.id === p.id)?.quantity || 0;
              return (
                <div key={p.id} className="bg-sky-50 p-3 rounded-2xl flex flex-col gap-2 border border-sky-100">
                  <div className="flex justify-between items-center">
                    <p className="text-[10px] font-black text-sky-900 uppercase">{p.name}</p>
                    <span className="text-[8px] bg-white px-2 py-0.5 rounded text-sky-400 font-bold border border-sky-100">Planta: {p.stock}</span>
                  </div>

                  <div className="flex items-center justify-between bg-white rounded-xl p-1 shadow-sm">
                    <button 
                      onClick={() => loadVehicle(vehicle.id, p, -1)}
                      className="w-10 h-10 bg-sky-50 rounded-lg text-sky-600 font-black active:scale-90 transition-transform text-lg"
                    >
                      -
                    </button>
                    <div className="flex flex-col items-center">
                       <span className="font-black text-sky-900 text-lg leading-none">{inVehicle}</span>
                       <span className="text-[8px] text-sky-300 font-bold uppercase">Cargados</span>
                    </div>
                    <button 
                      onClick={() => loadVehicle(vehicle.id, p, 1)}
                      className="w-10 h-10 bg-sky-600 rounded-lg text-white font-black active:scale-90 transition-transform text-lg shadow-lg shadow-sky-200"
                    >
                      +
                    </button>
                  </div>
                </div>
              );
            })}
          </div>

          <div className="mt-6 pt-4 border-t border-sky-100 flex justify-between items-center shrink-0">
             <div>
               <p className="text-[9px] font-black text-sky-400 uppercase">Capacidad Utilizada</p>
               <p className="text-2xl font-black text-sky-900">{vehicle.currentLoad} / {vehicle.loadCapacity}</p>
             </div>
             <button onClick={() => setLoadingVehicleId(null)} className="px-8 py-4 bg-emerald-500 text-white rounded-[1.5rem] font-black text-xs uppercase shadow-lg shadow-emerald-200 active:scale-95 transition-all">
               Confirmar Carga
             </button>
          </div>
        </div>
      </div>
    );
  };

  // --- MODAL DE COMBUSTIBLE (FIXED Z-INDEX) ---
  const FuelModal = () => {
    const vehicle = vehicles.find(v => v.id === fuelVehicleId);
    if (!vehicle) return null;

    const history = vehicle.fuelHistory || [];
    const costPerLiter = (fuelForm.cost && fuelForm.liters) ? (fuelForm.cost / fuelForm.liters) : 0;

    return (
      <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-md z-[200] flex items-center justify-center p-4 animate-fadeIn">
        <div className="bg-white w-full max-w-md rounded-[2.5rem] p-6 shadow-2xl max-h-[90vh] overflow-y-auto no-scrollbar">
          <div className="flex justify-between items-center mb-6">
            <div className="flex items-center gap-3">
              <div className="w-12 h-12 bg-amber-500 text-white rounded-2xl flex items-center justify-center text-xl shadow-lg shadow-amber-200">
                <i className="fas fa-gas-pump"></i>
              </div>
              <div>
                <h3 className="text-lg font-black text-sky-900">Combustible</h3>
                <p className="text-[10px] text-sky-400 font-bold uppercase">{vehicle.plate}</p>
              </div>
            </div>
            <button onClick={() => setFuelVehicleId(null)} className="w-10 h-10 bg-slate-100 rounded-full flex items-center justify-center text-slate-400 hover:bg-slate-200 transition-colors"><i className="fas fa-times"></i></button>
          </div>

          <div className="bg-slate-50 p-5 rounded-[2rem] border border-slate-100 mb-6">
             <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Registrar Carga</h4>

             <div className="grid grid-cols-2 gap-3 mb-3">
               <div>
                 <label className="text-[9px] font-black text-slate-400 uppercase ml-2 block mb-1">Kilometraje</label>
                 <div className="relative">
                   <i className="fas fa-gauge absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 text-xs"></i>
                   <input 
                     type="number" 
                     className="w-full bg-white p-3 pl-9 rounded-xl outline-none text-sm font-bold text-slate-700 shadow-sm"
                     placeholder="KM"
                     value={fuelForm.mileage || ''}
                     onChange={e => setFuelForm({...fuelForm, mileage: Number(e.target.value)})}
                   />
                 </div>
               </div>
               <div>
                 <label className="text-[9px] font-black text-slate-400 uppercase ml-2 block mb-1">Litros</label>
                 <div className="relative">
                   <i className="fas fa-droplet absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 text-xs"></i>
                   <input 
                     type="number" 
                     className="w-full bg-white p-3 pl-9 rounded-xl outline-none text-sm font-bold text-slate-700 shadow-sm"
                     placeholder="L"
                     value={fuelForm.liters || ''}
                     onChange={e => setFuelForm({...fuelForm, liters: Number(e.target.value)})}
                   />
                 </div>
               </div>
             </div>

             <div className="mb-3">
               <label className="text-[9px] font-black text-slate-400 uppercase ml-2 block mb-1">Costo Total ($)</label>
               <div className="relative">
                 <i className="fas fa-dollar-sign absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 text-xs"></i>
                 <input 
                   type="number" 
                   className="w-full bg-white p-3 pl-9 rounded-xl outline-none text-lg font-black text-emerald-600 shadow-sm"
                   placeholder="0.00"
                   value={fuelForm.cost || ''}
                   onChange={e => setFuelForm({...fuelForm, cost: Number(e.target.value)})}
                 />
                 {costPerLiter > 0 && (
                   <span className="absolute right-4 top-1/2 -translate-y-1/2 text-[9px] font-bold text-slate-400 bg-slate-100 px-2 py-0.5 rounded">
                     ${costPerLiter.toFixed(2)} / L
                   </span>
                 )}
               </div>
             </div>

             <button 
               onClick={handleAddFuel}
               className="w-full py-3 bg-amber-500 text-white rounded-xl font-black uppercase text-[10px] tracking-widest shadow-lg shadow-amber-200 active:scale-95 transition-all"
             >
               Guardar Registro
             </button>
          </div>

          <div>
            <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 ml-2">Historial Reciente</h4>
            <div className="space-y-2 max-h-60 overflow-y-auto no-scrollbar">
               {history.length === 0 ? (
                 <div className="text-center py-8 opacity-40">
                   <i className="fas fa-gas-pump text-4xl text-slate-300 mb-2"></i>
                   <p className="text-[10px] font-bold text-slate-400">Sin registros</p>
                 </div>
               ) : (
                 history.map(r => (
                   <div key={r.id} className="bg-white p-3 rounded-2xl shadow-sm border border-slate-50 flex justify-between items-center">
                      <div>
                         <p className="text-[10px] font-black text-slate-400 uppercase">{new Date(r.date).toLocaleDateString()}</p>
                         <p className="text-xs font-bold text-slate-700">{r.mileage.toLocaleString()} km</p>
                      </div>
                      <div className="text-right">
                         <p className="text-sm font-black text-emerald-600">${r.cost.toLocaleString()}</p>
                         <p className="text-[9px] font-bold text-amber-500">{r.liters} L</p>
                      </div>
                   </div>
                 ))
               )}
            </div>
          </div>

        </div>
      </div>
    );
  };

  if (editingVehicle) {
    return (
      <div className="h-full bg-sky-50 animate-fadeIn">
        <ModuleHeader title={editingVehicle.id ? "Editar Vehículo" : "Nueva Unidad"} onBack={() => setEditingVehicle(null)} />
        <div className="px-6 space-y-5">
           <input className="w-full bg-white p-5 rounded-[2rem] shadow-sm outline-none font-bold text-sky-900" placeholder="Placa" value={editingVehicle.plate || ''} onChange={e => setEditingVehicle({...editingVehicle, plate: e.target.value})}/>
           <input className="w-full bg-white p-5 rounded-[2rem] shadow-sm outline-none font-bold text-sky-900" placeholder="Descripción (Ej: Nissan Blanca)" value={editingVehicle.description || ''} onChange={e => setEditingVehicle({...editingVehicle, description: e.target.value})}/>
           <div className="space-y-1">
              <label className="text-[10px] font-black text-sky-400 uppercase ml-4">Capacidad Total (Unidades)</label>
              <input type="number" className="w-full bg-white p-5 rounded-[2rem] shadow-sm outline-none font-black text-sky-600 text-xl" value={editingVehicle.loadCapacity || ''} onChange={e => setEditingVehicle({...editingVehicle, loadCapacity: Number(e.target.value)})}/>
           </div>

           <ActionButton onClick={saveVehicle}>Guardar Unidad</ActionButton>

           {editingVehicle.id && (
             <button 
                onClick={handleDelete}
                className="w-full py-4 text-rose-500 font-black uppercase text-[10px] tracking-widest bg-rose-50 rounded-[2rem] border border-rose-100 shadow-sm active:scale-95 transition-all"
             >
                <i className="fas fa-trash-can mr-2"></i> Eliminar Unidad
             </button>
           )}
        </div>
      </div>
    );
  }

  return (
    <div className="h-full bg-sky-50 overflow-y-auto no-scrollbar pb-24 relative">
      <ModuleHeader title="Gestión de Flota" onBack={onBack} />
      <div className="px-6 space-y-6">
        <RoundedCard className="bg-sky-100/50 border-sky-200">
           <div className="flex items-start gap-4">
              <i className="fas fa-info-circle text-sky-500 mt-1"></i>
              <p className="text-[10px] font-bold text-sky-700 leading-tight">
                Nota: Al cargar una unidad, el stock se descuenta del inventario principal. Al descargar, regresa a planta.
              </p>
           </div>
        </RoundedCard>

        {vehicles.map(v => (
          <RoundedCard key={v.id} className="relative overflow-hidden border-none shadow-xl bg-white group active:scale-[0.99] transition-all p-0">
             <div className="p-6 pb-4">
               <div className="flex justify-between items-start mb-6">
                 <div className="flex gap-4">
                   <div className="w-14 h-14 bg-sky-900 text-white rounded-[1.5rem] flex items-center justify-center text-xl shadow-lg shadow-sky-100">
                      <i className="fas fa-truck-pickup"></i>
                   </div>
                   <div>
                     <span className="text-[10px] font-black text-sky-400 uppercase tracking-widest leading-none block mb-1">{v.plate}</span>
                     <h3 className="text-xl font-black text-sky-900 leading-tight">{v.description}</h3>
                   </div>
                 </div>
                 <div className="flex gap-2">
                   <button onClick={() => setFuelVehicleId(v.id)} className="w-10 h-10 bg-amber-50 text-amber-500 rounded-full flex items-center justify-center hover:bg-amber-100 transition-colors shadow-sm"><i className="fas fa-gas-pump"></i></button>
                   <button onClick={() => setEditingVehicle(v)} className="w-10 h-10 bg-sky-50 text-sky-400 rounded-full flex items-center justify-center hover:bg-sky-100 transition-colors"><i className="fas fa-edit"></i></button>
                 </div>
               </div>

               <div className="flex items-end justify-between mb-4">
                 <div>
                   <p className="text-[10px] font-black text-sky-400 uppercase tracking-tighter mb-1">Carga Actual</p>
                   <p className="text-4xl font-black text-sky-600 tracking-tighter">{v.currentLoad} <span className="text-xs font-bold text-sky-300 ml-1">ITEMS</span></p>
                 </div>

                 <button 
                   onClick={() => setLoadingVehicleId(v.id)}
                   className="px-5 py-3 bg-sky-600 text-white rounded-2xl font-black text-[10px] uppercase shadow-lg shadow-sky-200 active:scale-95 transition-all flex items-center gap-2"
                 >
                   <i className="fas fa-boxes-packing"></i> Gestionar Carga
                 </button>
               </div>

               {/* Inventory Summary Preview */}
               <div className="flex flex-wrap gap-2 mb-4">
                 {(!v.inventory || v.inventory.length === 0) ? (
                   <span className="text-[9px] font-bold text-sky-300 italic">Unidad vacía</span>
                 ) : (
                   v.inventory.map(item => (
                     <span key={item.id} className="bg-sky-50 text-sky-700 text-[9px] font-bold px-2 py-1 rounded-lg border border-sky-100">
                       {item.quantity}x {item.name.split(' ')[0]}
                     </span>
                   ))
                 )}
               </div>

               <div className="w-full bg-sky-50 h-3 rounded-full overflow-hidden border border-sky-100">
                 <div className="h-full bg-gradient-to-r from-sky-400 to-sky-600 transition-all duration-700 ease-out" style={{ width: `${Math.min((v.currentLoad/v.loadCapacity)*100, 100)}%` }}></div>
               </div>
               <div className="flex justify-between mt-2">
                  <span className="text-[9px] font-black text-sky-300 uppercase">Límite: {v.loadCapacity}</span>
                  <span className="text-[9px] font-black text-sky-500 uppercase">{Math.round((v.currentLoad/v.loadCapacity)*100)}% Capacidad</span>
               </div>
             </div>
          </RoundedCard>
        ))}

        <button 
          onClick={() => setEditingVehicle({})}
          className="w-full py-7 border-2 border-dashed border-sky-200 rounded-[2.5rem] text-sky-400 font-black text-sm uppercase hover:bg-white hover:text-sky-600 transition-all group"
        >
          <i className="fas fa-plus mr-2 group-hover:scale-125 transition-transform"></i> Registrar Nueva Unidad
        </button>
      </div>

      {loadingVehicleId && <LoadingModal />}
      {fuelVehicleId && <FuelModal />}
    </div>
  );
};

import React, { useState } from 'react';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';
import { Product, CartItem, PaymentSplit, Sale } from '../types';

export const TicketModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const { customers, products, addSale, sales, ticketConfig } = useERPData();
  const [activeTab, setActiveTab] = useState<'create' | 'history'>('create');

  // State for Create
  const [manualDate, setManualDate] = useState<string>(() => {
    // Default to current time but in local ISO format for input
    const d = new Date();
    const offset = d.getTimezoneOffset() * 60000;
    return new Date(d.getTime() - offset).toISOString().slice(0, 16);
  });
  const [selectedCustomerId, setSelectedCustomerId] = useState<string>('');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [searchCustomer, setSearchCustomer] = useState('');

  // Modal de éxito
  const [showSuccessModal, setShowSuccessModal] = useState<Sale | null>(null);

  const customer = customers.find(c => c.id === selectedCustomerId);
  const total = cart.reduce((sum, item) => {
    const price = (customer?.specialPrice && item.id === '1') ? customer.specialPrice : item.price;
    return sum + (price * item.quantity);
  }, 0);

  // --- FUNCIONES DE TICKET Y WHATSAPP ---
  const generateTicketPDF = (sale: Sale) => {
    const qrData = btoa(`AQUA-PRO-SECURE|${JSON.stringify({ id: sale.id, total: sale.total })}`);
    const ticketHtml = `
