  const [customer, setCustomer] = useState<Customer | null>(null);
  const [search, setSearch] = useState('');
  const [vacios, setVacios] = useState(0);

  // States para modales
  const [showPaymentModal, setShowPaymentModal] = useState(false);
  const [viewingTicket, setViewingTicket] = useState<Sale | null>(null);

  // Admin Time Control
  const getLocalISO = (d: Date = new Date()) => {
    const offset = d.getTimezoneOffset() * 60000;
    return new Date(d.getTime() - offset).toISOString().slice(0, 16);
  };
  const [manualDate, setManualDate] = useState<string>(getLocalISO());
  const [autoTime, setAutoTime] = useState(true);
  const [nowDisplay, setNowDisplay] = useState(new Date());

  useEffect(() => {
    let interval: any;
    if (autoTime) {
      interval = setInterval(() => {
        const d = new Date();
        setNowDisplay(d);
        setManualDate(getLocalISO(d));
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [autoTime]);

  const handleDateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setAutoTime(false);
    setManualDate(e.target.value);
  };

  const total = cart.reduce((sum, item) => {
    const price = (customer?.specialPrice && item.id === '1') ? customer.specialPrice : item.price;
    return sum + (price * item.quantity);
  }, 0);

  // Auto-calc vacios
  useEffect(() => {
    const garrafonesInCart = cart.filter(i => i.name.toLowerCase().includes('garraf') || i.category === 'Agua').reduce((acc, i) => acc + i.quantity, 0);
    if (cart.length > 0 && vacios === 0) setVacios(garrafonesInCart);
    else if (cart.length === 0) setVacios(0);
  }, [cart]);

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === product.id);
      if (existing) return prev.map(i => i.id === product.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const decreaseQuantity = (productId: string) => {
    setCart(prev => prev.map(item => {
      if (item.id === productId) {
        return { ...item, quantity: Math.max(0, item.quantity - 1) };
      }
      return item;
    }).filter(item => item.quantity > 0));
  };

  const removeFromCart = (productId: string) => {
    setCart(prev => prev.filter(item => item.id !== productId));
  };

  const handleSendWhatsApp = (sale: Sale) => {
    const currentCustomer = customers.find(c => c.id === sale.customerId);
    const phone = currentCustomer?.phone?.replace(/\D/g, '') || '';
    if (!phone) { alert("El cliente no tiene teléfono registrado."); return; }
    const itemsText = sale.items.map(i => `• ${i.quantity}x ${i.name}`).join('%0A');
    const debtMsg = sale.paidAmount < sale.total ? `%0A%0A⚠️ *Saldo Pendiente:* $${(sale.total - sale.paidAmount).toFixed(2)}` : '';
    const fullPhone = phone.length === 10 ? `52${phone}` : phone;
    const msg = `¡Hola ${sale.customerAlias}!%0A%0A*${ticketConfig.businessName}*%0AGracias por tu compra.%0A%0A*Pedido:*%0A${itemsText}%0A%0A*Total:* $${sale.total.toFixed(2)}${debtMsg}%0A*Folio:* ${sale.id}%0A%0A_Excelente día._`;
    window.open(`https://wa.me/${fullPhone}?text=${msg}`, '_blank');
  };

  const handlePreCheckout = () => {
    if (!customer) return alert("Selecciona un cliente.");
    if (cart.length === 0) return alert("El carrito está vacío.");
    setShowPaymentModal(true);
  };

  const handleConfirmPayment = (cash: number, transfer: number) => {
    if(!customer) return;

    const totalPaid = cash + transfer;
    const splits: PaymentSplit[] = [];
    if (cash > 0) splits.push({ method: 'Efectivo', amount: cash });
    if (transfer > 0) splits.push({ method: 'Transferencia', amount: transfer });

    const sale = addSale(
      customer.id, cart, total, totalPaid, splits, vacios, 
      user.role === 'Administrador' ? new Date(manualDate).getTime() : undefined
    );

    setShowPaymentModal(false);
    setViewingTicket(sale); // Mostrar ticket
  };

  const resetPOS = () => {
    setViewingTicket(null);
    setCart([]);
    setCustomer(null);
    setSearch('');
    setVacios(0);
    setActiveTab('sell'); // Forzar regreso a la pestaña de venta
    if (user.role === 'Administrador') setAutoTime(true); 
  };

  return (
    <div className="h-full flex flex-col animate-fadeIn bg-sky-50 pb-24 overflow-hidden relative">
      <ModuleHeader title="Punto de Venta" onBack={onBack} />

      <div className="px-6 flex gap-2 mb-4">
        <button onClick={() => setActiveTab('sell')} className={`flex-1 py-3 rounded-2xl text-xs font-bold ${activeTab === 'sell' ? 'bg-sky-600 text-white shadow-lg' : 'bg-white text-sky-400'}`}>Nueva Venta</button>
        <button onClick={() => setActiveTab('history')} className={`flex-1 py-3 rounded-2xl text-xs font-bold ${activeTab === 'history' ? 'bg-sky-600 text-white shadow-lg' : 'bg-white text-sky-400'}`}>Historial</button>
      </div>

      {activeTab === 'sell' ? (
        <div className="flex-1 overflow-y-auto px-6 space-y-6 pb-32 no-scrollbar">
          {/* Admin Date Control */}
          {user.role === 'Administrador' && (
            <div className={`p-4 rounded-[2.2rem] border transition-all duration-500 ${autoTime ? 'bg-white border-sky-100' : 'bg-amber-50 border-amber-200 shadow-inner'}`}>
              <div className="flex justify-between items-center mb-3">
                <div className="flex items-center gap-2">
                  <div className={`w-2.5 h-2.5 rounded-full ${autoTime ? 'bg-emerald-500 animate-pulse' : 'bg-amber-500'}`}></div>
                  <label className="text-[10px] font-black uppercase tracking-widest text-sky-900">
                    {autoTime ? 'TIEMPO REAL' : 'MODO MANUAL'}
                  </label>
                </div>
                {!autoTime && (
                  <button onClick={() => setAutoTime(true)} className="flex items-center gap-1 text-[9px] font-black text-sky-500 uppercase bg-sky-50 px-3 py-1.5 rounded-full active:scale-95 transition-transform">
                    <i className="fas fa-rotate"></i> Sincronizar
                  </button>
                )}
              </div>

              <div className="flex gap-3 items-center">
                <div className="flex-1 relative">
                  <input 
                    type="datetime-local" 
                    className={`w-full border-none rounded-2xl p-4 text-xs font-black shadow-sm outline-none transition-all ${
                      autoTime 
                        ? 'bg-sky-50 text-sky-400 pointer-events-none opacity-80' 
                        : 'bg-white text-amber-600 ring-2 ring-amber-200'
                    }`}
                    value={manualDate}
                    onChange={handleDateChange}
                  />
                </div>
              </div>
            </div>
          )}

          <section>
            <div className="relative">
              <input type="text" placeholder="Buscar Cliente..." className="w-full bg-white border-none rounded-[2rem] py-5 px-8 shadow-sm outline-none" value={search} onChange={e => setSearch(e.target.value)} />
              {search && !customer && (
                <div className="absolute top-full left-0 right-0 bg-white shadow-2xl rounded-3xl mt-2 z-50 overflow-hidden border border-sky-50 max-h-60 overflow-y-auto">
                  {customers.filter(c => c.alias.toLowerCase().includes(search.toLowerCase())).map(c => (
                    <button key={c.id} onClick={() => { setCustomer(c); setSearch(c.alias); }} className="w-full text-left p-4 hover:bg-sky-50 font-bold border-b border-sky-50 flex justify-between items-center">
                      <span className="text-sky-900">{c.alias}</span>
                      <span className="text-[10px] bg-sky-50 text-sky-400 px-3 py-1 rounded-full font-black">${c.balance}</span>
                    </button>
                  ))}
                </div>
              )}
            </div>
            {customer && (
              <div className="mt-4 flex items-center justify-between bg-sky-600 text-white p-4 rounded-[1.8rem] shadow-lg animate-fadeIn">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-white/20 rounded-2xl flex items-center justify-center"><i className="fas fa-user"></i></div>
                  <div>
                    <span className="text-[8px] font-black uppercase opacity-60 block">Cliente Activo</span>
                    <span className="font-black text-sm">{customer.alias}</span>
                    {customer.balance > 0 && (
                      <span className="text-[9px] bg-red-500/30 px-2 py-0.5 rounded ml-2 font-bold">Adeudo: ${customer.balance}</span>
                    )}
                  </div>
                </div>
                <button onClick={() => {setCustomer(null); setSearch('');}} className="w-10 h-10 bg-white/10 rounded-full flex items-center justify-center active:scale-90 transition-all"><i className="fas fa-times"></i></button>
              </div>
            )}
          </section>

          <div className="grid grid-cols-2 gap-3">
            {products.map(p => (
              <button key={p.id} onClick={() => addToCart(p)} className="bg-white p-5 rounded-[2.2rem] shadow-sm active:bg-sky-50 text-left relative overflow-hidden group border border-transparent hover:border-sky-100 transition-all">
                <div className="text-xs font-black text-sky-900 uppercase tracking-tight mb-1">{p.name}</div>
                <div className="text-sky-600 font-black text-lg">${p.price}</div>
                <div className="absolute -bottom-2 -right-2 w-12 h-12 bg-sky-50 text-sky-100 flex items-center justify-center rounded-tl-3xl group-active:text-sky-200 transition-colors">
                  <i className="fas fa-plus"></i>
                </div>
              </button>
            ))}
          </div>

          {cart.length > 0 && (
            <RoundedCard className="shadow-2xl border-2 border-white mb-20">
              <div className="flex justify-between items-start mb-6">
                <div>
                  <span className="text-[10px] text-sky-400 font-black uppercase mb-1 block">Total Carrito</span>
                  <span className="text-4xl font-black text-sky-900 tracking-tighter">${total.toFixed(2)}</span>
                </div>
                <button onClick={() => setCart([])} className="text-rose-400 text-xs font-bold uppercase underline">Vaciar</button>
              </div>

              <div className="space-y-3 mb-6">
                {cart.map(i => (
                  <div key={i.id} className="flex justify-between items-center bg-sky-50/50 p-2 rounded-2xl border border-sky-100">
                    <div className="flex flex-col">
                       <span className="text-[10px] font-black text-sky-900 uppercase max-w-[120px] truncate">{i.name}</span>
                       <span className="text-xs font-bold text-sky-600">${(i.quantity * i.price).toFixed(2)}</span>
                    </div>

                    <div className="flex items-center gap-2 bg-white rounded-xl shadow-sm p-1">
                       <button onClick={() => decreaseQuantity(i.id)} className="w-8 h-8 flex items-center justify-center bg-sky-50 text-sky-600 rounded-lg active:bg-sky-200 transition-colors font-bold">-</button>
                       <span className="text-sm font-black text-sky-900 w-6 text-center">{i.quantity}</span>
                       <button onClick={() => addToCart(i)} className="w-8 h-8 flex items-center justify-center bg-sky-600 text-white rounded-lg active:scale-95 transition-transform font-bold">+</button>
                    </div>
                  </div>
                ))}
              </div>

              {/* Control de Garrafones Vacíos */}
              <div className="mb-2 bg-white p-4 rounded-3xl border border-sky-100 flex justify-between items-center">
                 <span className="text-[10px] font-black text-sky-400 uppercase tracking-tight ml-2">Envases Vacíos</span>
                 <div className="flex items-center gap-3 bg-sky-50 rounded-2xl p-1">
                    <button onClick={() => setVacios(Math.max(0, vacios - 1))} className="w-8 h-8 flex items-center justify-center bg-white text-sky-600 rounded-xl font-black shadow-sm">-</button>
                    <span className="text-lg font-black text-sky-900 w-6 text-center">{vacios}</span>
                    <button onClick={() => setVacios(vacios + 1)} className="w-8 h-8 flex items-center justify-center bg-sky-600 text-white rounded-xl font-black shadow-lg">+</button>
                 </div>
              </div>
            </RoundedCard>
          )}
        </div>
      ) : (
        <div className="flex-1 overflow-y-auto px-6 space-y-3 pb-10 no-scrollbar">
          {sales.length === 0 ? (
            <div className="text-center py-20 opacity-30">
               <i className="fas fa-receipt text-6xl mb-4"></i>
               <p className="text-xs font-black uppercase">Sin historial reciente</p>
            </div>
          ) : (
            sales.map(s => (
              <RoundedCard key={s.id} className="py-5 border-none shadow-sm group">
                <div className="flex justify-between items-start">
                  <div className="flex gap-4">
                    <div className="w-12 h-12 bg-sky-50 text-sky-600 rounded-2xl flex items-center justify-center text-xl">
                      <i className="fas fa-receipt"></i>
                    </div>
                    <div>
                      <h4 className="font-black text-sky-900 text-sm leading-tight">{s.customerAlias}</h4>
                      <p className="text-[9px] text-sky-400 font-bold uppercase mt-1">{new Date(s.timestamp).toLocaleString()}</p>
                      {s.paidAmount < s.total && (
                        <span className="text-[9px] text-amber-500 font-black uppercase bg-amber-50 px-2 py-0.5 rounded mt-1 inline-block">Crédito</span>
                      )}
                    </div>
                  </div>
                  <div className="text-right">
                    <span className="font-black text-sky-600 text-xl tracking-tighter">${s.total}</span>
                    <p className="text-[8px] font-black text-sky-300 uppercase">{s.id}</p>
                  </div>
                </div>
                <div className="flex gap-2 mt-5">
                   <button onClick={() => setViewingTicket(s)} className="flex-1 text-[9px] font-black uppercase bg-sky-100 text-sky-600 px-3 py-3 rounded-xl flex items-center justify-center gap-2 active:bg-sky-200 transition-colors">
                    <i className="fas fa-eye"></i> Ver Ticket
                   </button>
                   <button onClick={() => handleSendWhatsApp(s)} className="flex-1 text-[9px] font-black uppercase bg-emerald-100 text-emerald-600 px-3 py-3 rounded-xl flex items-center justify-center gap-2 active:bg-emerald-200 transition-colors">
                    <i className="fab fa-whatsapp"></i> WA
                   </button>
                </div>
              </RoundedCard>
            ))
          )}
        </div>
      )}

      {activeTab === 'sell' && (
        <div className="fixed bottom-0 left-0 right-0 p-6 bg-white/95 border-t border-sky-100 shadow-[0_-10px_40px_rgba(0,0,0,0.1)] z-50">
          <ActionButton onClick={handlePreCheckout} disabled={!customer || cart.length === 0}>
             Ir a Pagar ${total.toFixed(2)}
          </ActionButton>
        </div>
      )}

      {/* Modales */}
      {showPaymentModal && (
        <PaymentModal 
          total={total}
          onConfirm={handleConfirmPayment}
          onCancel={() => setShowPaymentModal(false)}
        />
      )}

      {viewingTicket && (
        <TicketModal 
          sale={viewingTicket} 
          config={ticketConfig} 
          onClose={() => setViewingTicket(null)} 
          onWhatsApp={() => handleSendWhatsApp(viewingTicket)}
          onNewSale={resetPOS}
          onFinish={() => {
            setViewingTicket(null);
            setActiveTab('history');
          }}
        />
      )}
    </div>
  );
};

import { useState, useEffect, useCallback } from 'react';
import { Product, Customer, Sale, CartItem, Order, Employee, Vehicle, PaymentSplit, ViewType, QualityRecord, Task, Attendance, TicketConfig, CloudConfig, SavedReport, FuelRecord } from '../types';
import { INITIAL_PRODUCTS, INITIAL_CUSTOMERS } from '../constants';

const DEFAULT_PERMISSIONS: ViewType[] = ['dashboard', 'pos', 'orders', 'customers', 'logistics', 'inventory', 'whatsapp', 'production', 'sync', 'reports', 'settings', 'employees', 'quality', 'scanner', 'tickets'];

const INITIAL_TICKET_CONFIG: TicketConfig = {
  businessName: 'AQUA+ FUNDADORES',
  rfc: 'AQUA900101-XXX',
  address: 'Calle del Agua #123, Col. Manantiales',
  phone: '33-1234-5678',
  footerMessage: '¡Gracias por tu preferencia! Frescura que hidrata tu vida.',
  website: 'www.aquafun.mx',
  socialMedia: '@aquafun_pro',
  extraNote: 'No hay cambios después de 24 horas.',
  logoUrl: 'data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 100 100%22><rect width=%22100%22 height=%22100%22 rx=%2225%22 fill=%22%230284c7%22/><path d=%22M50 20C50 20 30 45 30 60C30 71.0457 38.9543 80 50 80C61.0457 80 70 71.0457 70 60C70 45 50 20 50 20Z%22 fill=%22white%22/></svg>'
};

const INITIAL_CLOUD_CONFIG: CloudConfig = {
  url: 'https://aquamasfundadores-default-rtdb.firebaseio.com/',
  apiKey: 't8rzxkeWbMIKGufdW7RV1j1bKS0TKf2gPkgmZ36A',
  autoSync: true
};

export const useERPData = () => {
  const [products, setProducts] = useState<Product[]>(() => {
    const saved = localStorage.getItem('aqua_products');
    return saved ? JSON.parse(saved) : INITIAL_PRODUCTS;
  });

  const [customers, setCustomers] = useState<Customer[]>(() => {
    const saved = localStorage.getItem('aqua_customers');
    return saved ? JSON.parse(saved).map((c: any) => ({ ...c, balance: c.balance || 0 })) : INITIAL_CUSTOMERS;
  });

  const [ticketConfig, setTicketConfig] = useState<TicketConfig>(() => {
    const saved = localStorage.getItem('aqua_ticket_config');
    return saved ? JSON.parse(saved) : INITIAL_TICKET_CONFIG;
  });

  const [cloudConfig, setCloudConfig] = useState<CloudConfig>(() => {
    const saved = localStorage.getItem('aqua_cloud_config');
    if (saved) {
      const parsed = JSON.parse(saved);
      if (!parsed.url || parsed.url === '') {
        return INITIAL_CLOUD_CONFIG;
      }
      return parsed;
    }
    return INITIAL_CLOUD_CONFIG;
  });

  const [sales, setSales] = useState<Sale[]>(() => {
    const saved = localStorage.getItem('aqua_sales');
    return saved ? JSON.parse(saved) : [];
  });

  const [orders, setOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('aqua_orders');
    return saved ? JSON.parse(saved) : [];
  });

  const [employees, setEmployees] = useState<Employee[]>(() => {
    const saved = localStorage.getItem('aqua_employees');
    const initial = saved ? JSON.parse(saved) : [
      { id: 'admin', name: 'Gerente General', role: 'Administrador', phone: '3312345678', pin: '1234', permissions: [...DEFAULT_PERMISSIONS] }
    ];
    return initial;
  });

  useEffect(() => {
    setEmployees(prev => prev.map(e => 
      e.role === 'Administrador' 
        ? { ...e, permissions: [...DEFAULT_PERMISSIONS] } 
        : e
    ));
  }, []);

  const [vehicles, setVehicles] = useState<Vehicle[]>(() => {
    const saved = localStorage.getItem('aqua_vehicles');
    // Migration: ensure inventory and fuelHistory arrays exist
    const parsed = saved ? JSON.parse(saved) : [{ id: 'v1', plate: 'ABC-123', description: 'Nissan NP300', loadCapacity: 60, currentLoad: 0, inventory: [], fuelHistory: [] }];
    return parsed.map((v: any) => ({
        ...v,
        inventory: v.inventory || [],
        fuelHistory: v.fuelHistory || []
    }));
  });

  const [qualityRecords, setQualityRecords] = useState<QualityRecord[]>(() => {
    const saved = localStorage.getItem('aqua_quality');
    return saved ? JSON.parse(saved) : [];
  });

  const [tasks, setTasks] = useState<Task[]>(() => {
    const saved = localStorage.getItem('aqua_tasks');
    return saved ? JSON.parse(saved) : [];
  });

  const [attendance, setAttendance] = useState<Attendance[]>(() => {
    const saved = localStorage.getItem('aqua_attendance');
    return saved ? JSON.parse(saved) : [];
  });

  const [savedReports, setSavedReports] = useState<SavedReport[]>(() => {
    const saved = localStorage.getItem('aqua_saved_reports');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => {
    localStorage.setItem('aqua_products', JSON.stringify(products));
    localStorage.setItem('aqua_customers', JSON.stringify(customers));
    localStorage.setItem('aqua_sales', JSON.stringify(sales));
    localStorage.setItem('aqua_orders', JSON.stringify(orders));
    localStorage.setItem('aqua_employees', JSON.stringify(employees));
    localStorage.setItem('aqua_vehicles', JSON.stringify(vehicles));
    localStorage.setItem('aqua_ticket_config', JSON.stringify(ticketConfig));
    localStorage.setItem('aqua_quality', JSON.stringify(qualityRecords));
    localStorage.setItem('aqua_tasks', JSON.stringify(tasks));
    localStorage.setItem('aqua_attendance', JSON.stringify(attendance));
    localStorage.setItem('aqua_cloud_config', JSON.stringify(cloudConfig));
    localStorage.setItem('aqua_saved_reports', JSON.stringify(savedReports));
  }, [products, customers, sales, orders, employees, vehicles, ticketConfig, qualityRecords, tasks, attendance, cloudConfig, savedReports]);

  const addSale = (
    customerId: string, 
    items: CartItem[], 
    total: number, 
    paidAmount: number, 
    splits: PaymentSplit[], 
    returnedVacios: number, 
    manualTimestamp?: number
  ) => {
    const debtAmount = Math.max(0, total - paidAmount);
    const newSale: Sale = {
      id: `TKT-${Date.now().toString().slice(-6)}`,
      timestamp: manualTimestamp || Date.now(),
      customerId,
      customerAlias: customers.find(c => c.id === customerId)?.alias || 'Anonimo',
      items,
      total,
      paidAmount,
      change: Math.max(0, paidAmount - total),
      paymentSplits: splits,
      emptyGarrafonsReturned: returnedVacios,
      synced: false
    };

    setSales(prev => [newSale, ...prev]);
    setCustomers(prev => prev.map(c => c.id === customerId ? { ...c, balance: (c.balance || 0) + debtAmount } : c));
    setProducts(prev => prev.map(p => {
      const cartItem = items.find(item => item.id === p.id);
      return cartItem ? { ...p, stock: p.stock - cartItem.quantity } : p;
    }));

    return newSale;
  };

  const syncData = useCallback((externalData: any) => {
    if (!externalData) return false;
    let changesMade = false;

    // 1. Sales Sync
    if (externalData.sales) {
      setSales(prev => {
        const existingIds = new Set(prev.map(s => s.id));
        const newSales = (externalData.sales as Sale[]).filter(s => !existingIds.has(s.id));
        if (newSales.length > 0) changesMade = true;
        return [...newSales, ...prev].sort((a, b) => b.timestamp - a.timestamp);
      });
    }

    // 2. Customers Sync (Merge by ID)
    if (externalData.customers) {
      setCustomers(prev => {
        const existingMap = new Map(prev.map(c => [c.id, c]));
        (externalData.customers as Customer[]).forEach(c => {
          // Cloud data overwrites local if conflict, assuming cloud is latest for master data
          if (JSON.stringify(existingMap.get(c.id)) !== JSON.stringify(c)) {
             existingMap.set(c.id, c);
             changesMade = true;
          }
        });
        return Array.from(existingMap.values());
      });
    }

    // 3. Products Sync (Inventory)
    if (externalData.products) {
      setProducts(prev => {
        const existingMap = new Map(prev.map(p => [p.id, p]));
        (externalData.products as Product[]).forEach(p => {
           if (JSON.stringify(existingMap.get(p.id)) !== JSON.stringify(p)) {
             existingMap.set(p.id, p);
             changesMade = true;
           }
        });
        return Array.from(existingMap.values());
      });
    }

    // 4. Orders Sync
    if (externalData.orders) {
      setOrders(prev => {
        const existingMap = new Map(prev.map(o => [o.id, o]));
        (externalData.orders as Order[]).forEach(o => {
           if (JSON.stringify(existingMap.get(o.id)) !== JSON.stringify(o)) {
             existingMap.set(o.id, o);
             changesMade = true;
           }
        });
        // Filter out very old orders? Keeping all for now.
        return Array.from(existingMap.values()).sort((a, b) => b.timestamp - a.timestamp);
      });
    }

    // 5. Fleet/Vehicles Sync
    if (externalData.vehicles) {
      setVehicles(prev => {
        const existingMap = new Map(prev.map(v => [v.id, v]));
        (externalData.vehicles as Vehicle[]).forEach(v => {
           if (JSON.stringify(existingMap.get(v.id)) !== JSON.stringify(v)) {
             existingMap.set(v.id, v);
             changesMade = true;
           }
        });
        return Array.from(existingMap.values());
      });
    }

    // 6. Employees Sync
    if (externalData.employees) {
      setEmployees(prev => {
        const existingMap = new Map(prev.map(e => [e.id, e]));
        (externalData.employees as Employee[]).forEach(e => {
           if (JSON.stringify(existingMap.get(e.id)) !== JSON.stringify(e)) {
             existingMap.set(e.id, e);
             changesMade = true;
           }
        });
        return Array.from(existingMap.values());
      });
    }

    // 7. Quality Records Sync
    if (externalData.qualityRecords) {
      setQualityRecords(prev => {
        const existingIds = new Set(prev.map(r => r.id));
        const newRecs = (externalData.qualityRecords as QualityRecord[]).filter(r => !existingIds.has(r.id));
        if (newRecs.length > 0) changesMade = true;
        return [...newRecs, ...prev].sort((a, b) => b.timestamp - a.timestamp);
      });
    }

    // 8. Tasks Sync
    if (externalData.tasks) {
      setTasks(prev => {
        const existingMap = new Map(prev.map(t => [t.id, t]));
        (externalData.tasks as Task[]).forEach(t => {
           if (JSON.stringify(existingMap.get(t.id)) !== JSON.stringify(t)) {
             existingMap.set(t.id, t);
             changesMade = true;
           }
        });
        return Array.from(existingMap.values());
      });
    }

    // 9. Attendance Sync
    if (externalData.attendance) {
      setAttendance(prev => {
        const existingIds = new Set(prev.map(a => a.id));
        const newAtt = (externalData.attendance as Attendance[]).filter(a => !existingIds.has(a.id));
        if (newAtt.length > 0) changesMade = true;
        return [...newAtt, ...prev].sort((a, b) => b.timestamp - a.timestamp);
      });
    }

    return changesMade;
  }, []);

  const importCustomers = useCallback((newCustomers: Customer[]) => {
    setCustomers(prev => {
      const existingIds = new Set(prev.map(c => c.id));
      const filteredNew = newCustomers.filter(c => !existingIds.has(c.id));
      return [...prev, ...filteredNew];
    });
  }, []);

  const loadVehicle = (vehicleId: string, product: Product, delta: number) => {
    // 1. Validar Stock Principal
    const currentProduct = products.find(p => p.id === product.id);
    if (!currentProduct) return;

    if (delta > 0 && currentProduct.stock < delta) {
        alert("Stock insuficiente en planta.");
        return;
    }

    // 2. Actualizar Vehículo
    setVehicles(prev => prev.map(v => {
        if (v.id !== vehicleId) return v;

        // Copiar inventario actual
        const newInventory = [...(v.inventory || [])];
        const existingItemIndex = newInventory.findIndex(i => i.id === product.id);

        if (existingItemIndex > -1) {
            const newQty = newInventory[existingItemIndex].quantity + delta;
            if (newQty <= 0) {
                newInventory.splice(existingItemIndex, 1);
            } else {
                newInventory[existingItemIndex] = { ...newInventory[existingItemIndex], quantity: newQty };
            }
        } else if (delta > 0) {
            newInventory.push({ ...product, quantity: delta });
        }

        // Recalcular carga total (unidades)
        const newLoad = newInventory.reduce((acc, item) => acc + item.quantity, 0);

        return { ...v, inventory: newInventory, currentLoad: newLoad };
    }));

    // 3. Actualizar Inventario Principal (Inverso al movimiento del vehículo)
    setProducts(prev => prev.map(p => {
        if (p.id === product.id) {
            return { ...p, stock: p.stock - delta };
        }
        return p;
    }));
  };

  const addFuelRecord = (vehicleId: string, record: FuelRecord) => {
    setVehicles(prev => prev.map(v => {
      if (v.id !== vehicleId) return v;
      return { 
        ...v, 
        fuelHistory: [record, ...(v.fuelHistory || [])] 
      };
    }));
  };

  return { 
    products, 
    saveProduct: (p: Product) => setProducts(prev => prev.find(x => x.id === p.id) ? prev.map(x => x.id === p.id ? p : x) : [...prev, p]),
    deleteProduct: (id: string) => setProducts(prev => prev.filter(p => p.id !== id)),
    customers, 
    saveCustomer: (c: Customer) => setCustomers(prev => prev.find(x => x.id === c.id) ? prev.map(x => x.id === c.id ? c : x) : [...prev, c]),
    deleteCustomer: (id: string) => setCustomers(prev => prev.filter(c => c.id !== id)),
    importCustomers,
    sales, addSale,
    orders, 
    setOrders,
    addOrder: (o: Partial<Order>) => {
      const newOrder: Order = {
        id: `ORD-${Date.now().toString().slice(-6)}`,
        timestamp: Date.now(),
        status: 'pendiente',
        priority: 1,
        items: [],
        total: 0,
        customerId: '',
        customerAlias: '',
        ...o
      } as Order;
      setOrders(prev => [newOrder, ...prev]);
    },
    updateOrder: (o: Order) => setOrders(prev => prev.map(item => item.id === o.id ? o : item)),
    employees, 
    saveEmployee: (e: Employee) => setEmployees(prev => prev.find(x => x.id === e.id) ? prev.map(x => x.id === e.id ? e : x) : [...prev, e]),
    vehicles, 
    setVehicles,
    loadVehicle,
    deleteVehicle: (id: string) => setVehicles(prev => prev.filter(v => v.id !== id)),
    addFuelRecord,
    tasks,
    addTask: (t: Partial<Task>) => {
      const newTask: Task = {
        id: `TSK-${Date.now().toString().slice(-4)}`,
        timestamp: Date.now(),
        status: 'pendiente',
        ...t
      } as Task;
      setTasks(prev => [newTask, ...prev]);
    },
    updateTaskStatus: (id: string, status: Task['status']) => setTasks(prev => prev.map(t => t.id === id ? { ...t, status } : t)),
    attendance,
    recordAttendance: (employeeId: string, status: Attendance['status']) => {
      const date = new Date().toISOString().split('T')[0];
      setAttendance(prev => {
        const filtered = prev.filter(a => !(a.employeeId === employeeId && a.date === date));
        return [{ id: `ATT-${Date.now()}`, employeeId, status, date, timestamp: Date.now() }, ...filtered];
      });
    },
    qualityRecords,
    addQualityRecord: (r: Partial<QualityRecord>) => {
      const newRecord: QualityRecord = {
        id: `QUAL-${Date.now().toString().slice(-4)}`,
        timestamp: Date.now(),
        employeeId: 'admin',
        ...r
      } as QualityRecord;
      setQualityRecords(prev => [newRecord, ...prev]);
    },
    ticketConfig, setTicketConfig,
    cloudConfig, setCloudConfig,
    syncData,
    savedReports,
    addSavedReport: (r: SavedReport) => setSavedReports(prev => [r, ...prev]),
    deleteSavedReport: (id: string) => setSavedReports(prev => prev.filter(r => r.id !== id))
  };
};

import React, { useState, useEffect } from 'react';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';

interface SyncModuleProps {
  onBack: () => void;
  onScanRequest: () => void;
  scannedId?: string;
}

type SyncStatus = 'idle' | 'syncing' | 'success' | 'error';

export const SyncModule: React.FC<SyncModuleProps> = ({ onBack, scannedId }) => {
  const { 
    sales, customers, products, orders, employees, vehicles, qualityRecords, tasks, attendance,
    syncData, cloudConfig, setCloudConfig 
  } = useERPData();

  const [status, setStatus] = useState<SyncStatus>('idle');
  const [logs, setLogs] = useState<string[]>([]);
  const [editingConfig, setEditingConfig] = useState(false);
  const [tempConfig, setTempConfig] = useState(cloudConfig);

  const addLog = (msg: string) => {
    setLogs(prev => [`[${new Date().toLocaleTimeString()}] ${msg}`, ...prev.slice(0, 4)]);
  };

  const handleSaveConfig = () => {
    // Validaciones básicas de URL de Firebase
    let url = tempConfig.url.trim();
    if (url && !url.endsWith('/')) url += '/';

    setCloudConfig({ ...tempConfig, url });
    setEditingConfig(false);
    addLog("Configuración guardada.");
  };

  const performSync = async () => {
    if (!cloudConfig.url) {
      alert("Configura primero la URL de tu base de datos (Firebase).");
      setEditingConfig(true);
      return;
    }

    setStatus('syncing');
    addLog("Iniciando conexión segura SSL...");

    try {
      const endpoint = `${cloudConfig.url}aqua_data.json${cloudConfig.apiKey ? `?auth=${cloudConfig.apiKey}` : ''}`;

      // 1. GET: Descargar estado actual de la nube para fusionar
      addLog("Verificando estado remoto...");
      const getResponse = await fetch(endpoint);
      if (!getResponse.ok) throw new Error(`Error conexión: ${getResponse.statusText}`);

      const cloudData = await getResponse.json();

      // Construir Payload de Subida (snapshot local)
      const uploadPayload = {
        sales, 
        customers, 
        products, 
        orders, 
        employees, 
        vehicles, 
        qualityRecords, 
        tasks, 
        attendance,
        lastUpdated: Date.now(),
        deviceUser: 'AquaPro Mobile'
      };

      // Si hay datos en la nube, los aplicamos localmente (La lógica de merge detallada está en useERPData)
      if (cloudData) {
        addLog("Descargando cambios remotos...");
        syncData(cloudData);

        // Fusión básica para re-subir: 
        // Nota: En un entorno de producción real, esto debería ser más granular (PATCH)
        // Aquí re-subimos el estado local YA fusionado (o el local si es más reciente/autoritativo para este dispositivo)
        // Para simplificar, asumimos que el estado local (tras syncData) es el 'master' temporal antes de subir.
        // Pero `syncData` es asíncrono en React State, así que usamos las variables locales fusionadas manualmente
        // solo para el payload de subida si quisiéramos ser perfectos. 
        // Dado que `syncData` actualiza el estado y eso dispara re-renders, 
        // la subida inmediata puede usar los datos "viejos" del render actual.
        // Solución robusta simple: Fusionar los arrays aquí para el payload de subida también.

        // Ejemplo de fusión para subida (Sales):
        if (cloudData.sales) {
           const localIds = new Set(sales.map(s => s.id));
           const newCloudSales = (cloudData.sales as any[]).filter((s: any) => !localIds.has(s.id));
           uploadPayload.sales = [...sales, ...newCloudSales];
        }
        // (Similar logic applies implicitly if we trust specific device authority, 
        // but for safety we usually rely on the next sync cycle or specialized backend logic.
        // For this implementation, we will upload the LOCAL state, assuming this device has "work done" 
        // that needs to go up. The next device downloads it.)
      }

      addLog("Subiendo datos locales...");
      const putResponse = await fetch(endpoint, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(uploadPayload)
      });

      if (!putResponse.ok) throw new Error("Error al escribir en nube");

      setCloudConfig(prev => ({ ...prev, lastSync: Date.now() }));
      setStatus('success');
      addLog("¡Sincronización Total Completada!");

    } catch (error: any) {
      console.error(error);
      setStatus('error');
      addLog(`Error: ${error.message}`);
    } finally {
      setTimeout(() => setStatus(prev => prev === 'syncing' ? 'idle' : prev), 2000);
    }
  };

  // Auto-sync effect
  useEffect(() => {
    if (cloudConfig.autoSync && cloudConfig.url && status === 'idle') {
      const timer = setInterval(() => {
        // Sync cada 5 minutos si está en auto
        const minsSince = cloudConfig.lastSync ? (Date.now() - cloudConfig.lastSync) / 60000 : 999;
        if (minsSince > 5) {
          performSync();
        }
      }, 60000);
      return () => clearInterval(timer);
    }
  }, [cloudConfig, status]);

  if (editingConfig) {
    return (
      <div className="h-full bg-slate-50 animate-fadeIn pb-24 overflow-y-auto">
        <ModuleHeader title="Configurar Nube" onBack={() => setEditingConfig(false)} />
        <div className="px-6 space-y-6">
          <div className="bg-white p-6 rounded-[2rem] shadow-lg border border-indigo-100">
             <div className="flex items-center gap-3 mb-4">
                <i className="fas fa-fire text-amber-500 text-2xl"></i>
                <h3 className="font-black text-sky-900">Firebase Realtime DB</h3>
             </div>
             <p className="text-xs text-slate-500 mb-6 leading-relaxed">
               Conecta tu ERP a una base de datos Firebase para sincronización en tiempo real a través de internet (sin necesidad de estar en la misma red Wi-Fi).
             </p>

             <div className="space-y-4">
               <div>
                 <label className="text-[10px] font-black uppercase text-sky-400 ml-2">URL de la Base de Datos</label>
                 <input 
                   type="url" 
                   placeholder="https://mi-proyecto.firebaseio.com/" 
                   className="w-full bg-slate-50 p-4 rounded-2xl outline-none font-bold text-sky-900 focus:ring-2 ring-indigo-300 transition-all text-xs"
                   value={tempConfig.url}
                   onChange={e => setTempConfig({...tempConfig, url: e.target.value})}
                 />
                 <p className="text-[9px] text-slate-400 mt-1 ml-2">Copia esto desde la consola de Firebase {'>'} Realtime Database.</p>
               </div>

               <div>
                 <label className="text-[10px] font-black uppercase text-sky-400 ml-2">Secreto de Base de Datos (Auth)</label>
                 <input 
                   type="password" 
                   placeholder="Token de secreto..." 
                   className="w-full bg-slate-50 p-4 rounded-2xl outline-none font-bold text-sky-900 focus:ring-2 ring-indigo-300 transition-all text-xs"
                   value={tempConfig.apiKey}
                   onChange={e => setTempConfig({...tempConfig, apiKey: e.target.value})}
                 />
                 <p className="text-[9px] text-slate-400 mt-1 ml-2">Configuración del Proyecto {'>'} Cuentas de servicio {'>'} Secretos.</p>
               </div>

               <div className="flex items-center gap-3 bg-indigo-50 p-4 rounded-2xl">
                 <div 
                   onClick={() => setTempConfig({...tempConfig, autoSync: !tempConfig.autoSync})}
                   className={`w-12 h-7 rounded-full p-1 transition-colors cursor-pointer ${tempConfig.autoSync ? 'bg-indigo-500' : 'bg-slate-300'}`}
                 >
                   <div className={`w-5 h-5 bg-white rounded-full shadow-sm transition-transform ${tempConfig.autoSync ? 'translate-x-5' : ''}`}></div>
                 </div>
                 <span className="text-xs font-bold text-indigo-900">Sincronización Automática (5 min)</span>
               </div>
             </div>
          </div>
          <ActionButton onClick={handleSaveConfig}>Guardar Conexión</ActionButton>
        </div>
      </div>
    );
  }

  return (
    <div className="h-full bg-slate-900 text-white flex flex-col animate-fadeIn overflow-hidden pb-24">
      <div className="px-6 pt-8 pb-4 flex items-center justify-between">
        <div className="flex items-center gap-4">
          <button onClick={onBack} className="w-12 h-12 bg-white/10 rounded-2xl flex items-center justify-center active:scale-90 transition-transform">
            <i className="fas fa-arrow-left"></i>
          </button>
          <div>
            <h2 className="text-xl font-black tracking-tight">Aqua Cloud</h2>
            <div className="flex items-center gap-2">
               <div className={`w-2 h-2 rounded-full ${cloudConfig.url ? 'bg-emerald-400' : 'bg-red-500'}`}></div>
               <span className="text-[10px] font-bold uppercase opacity-70">{cloudConfig.url ? 'Conectado' : 'Desconectado'}</span>
            </div>
          </div>
        </div>
        <button onClick={() => setEditingConfig(true)} className="w-10 h-10 bg-white/10 rounded-xl flex items-center justify-center text-sm active:bg-white/20">
          <i className="fas fa-gear"></i>
        </button>
      </div>

      <div className="flex-1 overflow-y-auto px-6 space-y-8 no-scrollbar pb-10 flex flex-col justify-center">

        <div className="relative">
           {/* Status Ring */}
           <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-64 h-64 rounded-full border-4 border-indigo-500/20"></div>
           <div className={`absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-64 h-64 rounded-full border-t-4 border-indigo-500 transition-all duration-1000 ${status === 'syncing' ? 'animate-spin' : ''}`}></div>

           <div className="flex flex-col items-center justify-center relative z-10">
              <div className={`w-32 h-32 rounded-full flex items-center justify-center text-5xl shadow-[0_0_50px_rgba(99,102,241,0.3)] transition-all ${status === 'syncing' ? 'bg-indigo-600 scale-110' : status === 'success' ? 'bg-emerald-500' : status === 'error' ? 'bg-red-500' : 'bg-slate-800 border border-slate-700'}`}>
                 <i className={`fas ${status === 'syncing' ? 'fa-rotate animate-spin' : status === 'success' ? 'fa-check' : status === 'error' ? 'fa-triangle-exclamation' : 'fa-cloud'}`}></i>
              </div>

              <h3 className="text-2xl font-black mt-6 mb-1">
                {status === 'syncing' ? 'Sincronizando...' : status === 'success' ? 'Todo al día' : 'Nube Aqua+'}
              </h3>

              {cloudConfig.lastSync ? (
                <p className="text-xs font-mono opacity-50 bg-black/20 px-3 py-1 rounded-full">
                  Última vez: {new Date(cloudConfig.lastSync).toLocaleTimeString()}
                </p>
              ) : (
                <p className="text-xs font-bold opacity-50">Nunca sincronizado</p>
              )}
           </div>
        </div>

        <div className="space-y-4">
           <button 
             onClick={performSync}
             disabled={status === 'syncing'}
             className="w-full bg-white text-indigo-900 py-6 rounded-[2.5rem] font-black uppercase text-sm tracking-widest shadow-2xl shadow-indigo-500/20 active:scale-95 transition-all disabled:opacity-50 flex items-center justify-center gap-3"
           >
             {status === 'syncing' ? 'Procesando...' : 'Sincronizar Todo'}
             {!status.includes('sync') && <i className="fas fa-arrow-right-arrow-left"></i>}
           </button>

           <div className="grid grid-cols-2 gap-4 text-center">
              <div className="bg-white/5 p-4 rounded-3xl border border-white/5">
                 <p className="text-[10px] font-black uppercase opacity-40 mb-1">Ventas</p>
                 <p className="text-xl font-black">{sales.length}</p>
              </div>
              <div className="bg-white/5 p-4 rounded-3xl border border-white/5">
                 <p className="text-[10px] font-black uppercase opacity-40 mb-1">Inventario</p>
                 <p className="text-xl font-black">{products.reduce((a,b) => a + b.stock, 0)}</p>
              </div>
              <div className="bg-white/5 p-4 rounded-3xl border border-white/5">
                 <p className="text-[10px] font-black uppercase opacity-40 mb-1">Pedidos</p>
                 <p className="text-xl font-black">{orders.length}</p>
              </div>
              <div className="bg-white/5 p-4 rounded-3xl border border-white/5">
                 <p className="text-[10px] font-black uppercase opacity-40 mb-1">Clientes</p>
                 <p className="text-xl font-black">{customers.length}</p>
              </div>
           </div>
        </div>

        {/* Console Log */}
        <div className="bg-black/40 rounded-2xl p-4 font-mono text-[9px] h-32 overflow-hidden border border-white/5 relative">
          <div className="flex justify-between items-center mb-2 opacity-50 sticky top-0">
            <span>ACTIVITY LOG</span>
            <i className="fas fa-terminal"></i>
          </div>
          <div className="space-y-1">
            {logs.length === 0 && <span className="opacity-30">Esperando acción...</span>}
            {logs.map((log, i) => (
              <div key={i} className="opacity-80 border-l-2 border-indigo-500 pl-2">{log}</div>
            ))}
          </div>
        </div>

      </div>
    </div>
  );
};

