      )}

      {/* Modales */}
      {showPaymentModal && (
        <PaymentModal 
          total={total}
          onConfirm={handleConfirmPayment}
          onCancel={() => setShowPaymentModal(false)}
        />
      )}

      {viewingTicket && (
        <TicketModal 
          sale={viewingTicket} 
          config={ticketConfig} 
