import { ScannerModule } from './components/ScannerModule';
import { TicketModule } from './components/TicketModule';
import { VoiceAI } from './components/VoiceAI';

// Auth & UI Components
import { PermissionShield } from './components/auth/PermissionShield';
import { LoginScreen } from './components/auth/LoginScreen';
import { SplashScreen } from './components/ui/SplashScreen';

const App: React.FC = () => {
  const { currentView, navigateTo, goBack } = useNavigation();
  const [showSplash, setShowSplash] = useState(true);
  const [needsPermissions, setNeedsPermissions] = useState(() => !localStorage.getItem('aqua_permissions_granted'));
  const [user, setUser] = useState<Employee | null>(null);

  if (needsPermissions) return <PermissionShield onGranted={() => setNeedsPermissions(false)} />;
  if (showSplash) return <SplashScreen onComplete={() => setShowSplash(false)} />;
  if (!user) return <LoginScreen onLogin={setUser} />;

  return (
    <div className="max-w-md mx-auto min-h-screen bg-sky-50 relative overflow-x-hidden shadow-2xl">
      <main className="min-h-screen">
        {currentView === 'dashboard' && <Dashboard setView={navigateTo} user={user} onLogout={() => setUser(null)} />}
        {currentView === 'pos' && <POSModule user={user} onBack={goBack} />}
        {currentView === 'settings' && <SettingsModule currentUser={user} onBack={goBack} />}
        {currentView === 'whatsapp' && <WhatsAppModule onBack={goBack} />}
        {currentView === 'customers' && <CustomersModule onBack={goBack} />}
        {currentView === 'logistics' && <LogisticsModule onBack={goBack} />}
        {currentView === 'production' && <ProductionModule onBack={goBack} />}
        {currentView === 'sync' && <SyncModule onBack={goBack} onScanRequest={() => navigateTo('scanner')} />}
        {currentView === 'inventory' && <InventoryModule onBack={goBack} />}
        {currentView === 'supplies' && <SuppliesModule onBack={goBack} />}
        {currentView === 'employees' && <EmployeesModule onBack={goBack} currentUser={user} />}
        {currentView === 'reports' && <ReportsModule onBack={goBack} />}
        {currentView === 'quality' && <QualityModule onBack={goBack} />}
        {currentView === 'scanner' && <ScannerModule onBack={goBack} />}
        {currentView === 'orders' && <OrdersModule onBack={goBack} />}
        {currentView === 'tickets' && <TicketModule onBack={goBack} />}
      </main>
      {currentView === 'dashboard' && <VoiceAI onAction={(res) => res.action === 'SALE' && navigateTo('pos')} />}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { ModuleHeader, RoundedCard } from './ui/Cards';
import jsQR from 'jsqr';

interface ScannerModuleProps {
  onBack: () => void;
  onScanSuccess?: (data: string, type: 'TICKET' | 'SYNC') => void;
  mode?: 'TICKET' | 'P2P';
}

export const ScannerModule: React.FC<ScannerModuleProps> = ({ onBack, onScanSuccess, mode = 'TICKET' }) => {
  const [scanning, setScanning] = useState(true);
  const [result, setResult] = useState<any>(null);
  const [cameraError, setCameraError] = useState<string | null>(null);
  const [debugInfo, setDebugInfo] = useState<string>('');

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationRef = useRef<number>(0);
  const streamRef = useRef<MediaStream | null>(null);

  // Limpieza agresiva de streams previos
  const cleanupMedia = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => {
        track.stop();
        track.enabled = false;
      });
      streamRef.current = null;
    }
    if (videoRef.current) {
      videoRef.current.srcObject = null;
      videoRef.current.load();
    }
    if (animationRef.current) cancelAnimationFrame(animationRef.current);
  };

  // Iniciar Cámara
  useEffect(() => {
    if (!scanning) {
      cleanupMedia();
      return;
    }

    const startCamera = async () => {
      cleanupMedia();
      setCameraError(null);
      setDebugInfo('Iniciando cámara...');

      try {
        // Verificar soporte
        if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
          throw new Error("API de cámara no soportada en este dispositivo.");
        }

        // Estrategia 1: Buscar ID de cámara trasera explícitamente (Más robusto en Android)
        let backCameraId = null;
        try {
          const devices = await navigator.mediaDevices.enumerateDevices();
          const videoDevices = devices.filter(d => d.kind === 'videoinput');
          const backDevice = videoDevices.find(d => 
            d.label.toLowerCase().includes('back') || 
            d.label.toLowerCase().includes('trasera') || 
            d.label.toLowerCase().includes('environment')
          );
          if (backDevice) backCameraId = backDevice.deviceId;
          // Si solo hay una cámara, usarla
          if (!backCameraId && videoDevices.length === 1) backCameraId = videoDevices[0].deviceId;
        } catch (e) {
          console.warn("Error enumerando dispositivos:", e);
        }

        const tryStream = async (constraints: MediaStreamConstraints) => {
          try {
            return await navigator.mediaDevices.getUserMedia(constraints);
          } catch (err: any) {
            console.warn(`Intento fallido: ${JSON.stringify(constraints)}`, err);
            return null;
          }
        };

        let stream: MediaStream | null = null;

        // Intento 1: ID Específico (si se encontró)
        if (backCameraId) {
          stream = await tryStream({ 
            video: { 
              deviceId: { exact: backCameraId },
              width: { ideal: 1280 },
              height: { ideal: 720 }
            } 
          });
        }

        // Intento 2: Facing Mode Environment (Estándar Web)
        if (!stream) {
          stream = await tryStream({ 
            video: { facingMode: "environment", width: { ideal: 640 } } 
          });
        }

        // Intento 3: Cualquier video (Fallback extremo)
        if (!stream) {
          stream = await tryStream({ video: true });
        }

        if (stream) {
          streamRef.current = stream;
          if (videoRef.current) {
            videoRef.current.srcObject = stream;
            videoRef.current.setAttribute("playsinline", "true");

            // Promesa de play segura
            const playPromise = videoRef.current.play();
            if (playPromise !== undefined) {
              playPromise.catch(error => {
                console.error("Error al reproducir video:", error);
                setCameraError("generic");
                setDebugInfo(`Play error: ${error.message}`);
              });
            }

            requestAnimationFrame(tick);
            setDebugInfo('');
          }
        } else {
          throw new Error("No se pudo obtener ningún stream de video.");
        }

      } catch (err: any) {
        console.error("Camera Fatal Error:", err);
        if (err.name === 'NotAllowedError' || err.name === 'PermissionDeniedError') {
          setCameraError("permiso");
        } else if (err.name === 'NotFoundError') {
          setCameraError("no_device");
        } else if (err.name === 'NotReadableError') {
          setCameraError("generic");
          setDebugInfo("Hardware ocupado. Reinicia la app.");
        } else {
          setCameraError("generic");
          setDebugInfo(`${err.name}: ${err.message}`);
        }
      }
    };

    // Pequeño delay para asegurar que el DOM esté listo y streams anteriores cerrados
    const timer = setTimeout(startCamera, 500);
    return () => {
      clearTimeout(timer);
      cleanupMedia();
    };
  }, [scanning]);

  const tick = () => {
    if (!videoRef.current || !canvasRef.current || !scanning) return;

    if (videoRef.current.readyState === videoRef.current.HAVE_ENOUGH_DATA) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      const ctx = canvas.getContext('2d');

      if (ctx) {
        canvas.height = video.videoHeight;
        canvas.width = video.videoWidth;
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);

        try {
          const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
          const code = jsQR(imageData.data, imageData.width, imageData.height, {
            inversionAttempts: "dontInvert",
          });

          if (code && code.data) {
            handleScan(code.data);
            return; 
          }
        } catch (e) {
          // Ignorar errores de decodificación frame a frame
        }
      }
    }
    animationRef.current = requestAnimationFrame(tick);
  };

  const decryptData = (encrypted: string) => {
    try {
      const decoded = atob(encrypted);
      if (decoded.startsWith('AQUA-PRO-SECURE|')) {
        return { type: 'TICKET', data: JSON.parse(decoded.split('|')[1]) };
      }
      return null;
    } catch {
      if (mode === 'P2P' && (encrypted.length > 5 || encrypted.startsWith('AQUA-'))) {
         return { type: 'SYNC', data: encrypted };
      }
      return null;
    }
  };

  const handleScan = (code: string) => {
    if (!scanning) return;

    if (navigator.vibrate) navigator.vibrate(200);

    if (mode === 'P2P') {
      cleanupMedia();
      if (onScanSuccess) onScanSuccess(code, 'SYNC');
      return;
    }

    const decoded = decryptData(code);
    if (decoded?.type === 'TICKET') {
      cleanupMedia();
      if (onScanSuccess && mode === 'TICKET') {
        onScanSuccess(code, 'TICKET');
      } else {
        setResult(decoded.data);
        setScanning(false);
      }
    }
  };

  const handleManualEntry = (code: string) => {
    handleScan(code);
  };

  return (
    <div className={`h-full flex flex-col animate-fadeIn overflow-hidden ${mode === 'P2P' ? 'bg-slate-800' : 'bg-sky-900'}`}>
      <div className="px-6 pt-8 pb-4 flex items-center gap-4 relative z-20">
        <button onClick={onBack} className="w-12 h-12 bg-white/10 text-white rounded-2xl flex items-center justify-center active:scale-90 transition-transform">
          <i className="fas fa-arrow-left"></i>
        </button>
        <h2 className="text-2xl font-black tracking-tight text-white">
          {mode === 'P2P' ? 'Conectar' : 'Validar Ticket'}
        </h2>
      </div>

      <div className="flex-1 flex flex-col items-center justify-center px-6 relative">
        {scanning ? (
          <div className="w-full h-full flex flex-col items-center justify-center">

            {cameraError ? (
               <div className="bg-white p-8 rounded-[2rem] max-w-sm text-center shadow-2xl animate-fadeIn z-30">
                  <div className="w-20 h-20 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4 text-red-500 text-3xl">
                     <i className="fas fa-video-slash"></i>
                  </div>
                  <h3 className="text-xl font-black text-sky-900 mb-2">Error de Cámara</h3>

                  {cameraError === 'permiso' ? (
                    <div className="text-sm text-sky-600 mb-6 text-left bg-sky-50 p-4 rounded-xl">
                       <p className="font-bold mb-2">Permisos Requeridos:</p>
                       <p className="text-xs">Ve a Ajustes {'>'} Apps {'>'} Aqua+ Pro {'>'} Permisos y activa la Cámara.</p>
                    </div>
                  ) : (
                    <div className="mb-6">
                      <p className="text-sm text-sky-500 mb-2 font-bold">No se pudo iniciar el video.</p>
                      <p className="text-[10px] bg-slate-100 p-2 rounded text-slate-500 font-mono break-all">{debugInfo}</p>
                    </div>
                  )}

                  <button onClick={() => { setCameraError(null); setScanning(true); window.location.reload(); }} className="w-full bg-sky-600 text-white py-4 rounded-xl font-black uppercase text-xs shadow-lg">Reiniciar App</button>
               </div>
            ) : (
               <div className="relative w-full max-w-xs aspect-square rounded-[2rem] overflow-hidden shadow-2xl bg-black border border-white/10">
                  <video ref={videoRef} className="absolute inset-0 w-full h-full object-cover opacity-90" muted playsInline></video>
                  <canvas ref={canvasRef} className="hidden"></canvas>

                  {/* Viewfinder Corners */}
                  <div className="absolute top-6 left-6 w-10 h-10 border-t-4 border-l-4 border-white/40 rounded-tl-2xl z-20 pointer-events-none"></div>
                  <div className="absolute top-6 right-6 w-10 h-10 border-t-4 border-r-4 border-white/40 rounded-tr-2xl z-20 pointer-events-none"></div>
                  <div className="absolute bottom-6 left-6 w-10 h-10 border-b-4 border-l-4 border-white/40 rounded-bl-2xl z-20 pointer-events-none"></div>
                  <div className="absolute bottom-6 right-6 w-10 h-10 border-b-4 border-r-4 border-white/40 rounded-br-2xl z-20 pointer-events-none"></div>

                  {/* Enhanced Scanner Animation */}
                  <div className="absolute inset-0 z-20 overflow-hidden pointer-events-none">
                    <div className={`w-full h-1/2 bg-gradient-to-b from-transparent ${mode === 'P2P' ? 'to-emerald-500/20' : 'to-sky-500/20'} absolute top-[-50%] left-0 animate-scan-trail`}></div>
                    <div className={`w-full h-0.5 ${mode === 'P2P' ? 'bg-emerald-400 shadow-[0_0_20px_rgba(52,211,153,0.8)]' : 'bg-sky-400 shadow-[0_0_20px_rgba(56,189,248,0.8)]'} absolute top-0 left-0 animate-scan-line`}></div>
                  </div>

                  <div className="absolute inset-0 flex items-center justify-center z-10 pointer-events-none">
                     <i className="fas fa-expand text-white/5 text-8xl"></i>
                  </div>

                  <div className="absolute bottom-8 left-0 right-0 text-center z-30 pointer-events-none">
                     <p className="text-white/90 text-[10px] font-bold uppercase tracking-[0.2em] bg-black/40 inline-block px-4 py-1.5 rounded-full backdrop-blur-md border border-white/10">
                        {mode === 'P2P' ? 'Sincronizando...' : 'Escaneando...'}
                     </p>
                  </div>

                  {/* Debug info */}
                  {debugInfo && <div className="absolute top-2 left-2 text-[8px] text-white/50 font-mono z-30">{debugInfo}</div>}
               </div>
            )}

            {!cameraError && (
              <div className="w-full max-w-xs mt-8">
                <input 
                  type="text" 
                  placeholder="Código Manual..." 
                  className="w-full border border-white/20 bg-white/10 text-white rounded-2xl p-5 text-sm outline-none focus:ring-2 ring-white/30 transition-all placeholder-white/40 font-bold text-center backdrop-blur-md"
                  onKeyDown={e => e.key === 'Enter' && handleManualEntry(e.currentTarget.value)}
                />
              </div>
            )}
          </div>
        ) : (
          <RoundedCard className="w-full bg-white animate-fadeIn p-8">
            <div className="flex flex-col items-center text-center">
              <div className="w-20 h-20 bg-emerald-100 text-emerald-500 rounded-full flex items-center justify-center mb-6">
                <i className="fas fa-check-circle text-4xl"></i>
              </div>
              <h3 className="text-2xl font-black text-sky-900 mb-2">Código Detectado</h3>
              <div className="w-full bg-sky-50 rounded-3xl p-6 mb-8 space-y-4">
                <div className="flex justify-between">
                  <span className="text-[10px] font-black text-sky-400 uppercase">ID</span>
                  <span className="text-xs font-black text-sky-900">{result?.id || 'N/A'}</span>
                </div>
                {result?.total && (
                  <div className="flex justify-between border-t border-sky-100 pt-3">
                    <span className="text-[10px] font-black text-sky-400 uppercase">Monto</span>
                    <span className="text-xl font-black text-sky-900">${result.total}</span>
                  </div>
                )}
              </div>
              <button 
                onClick={() => { setResult(null); setScanning(true); }} 
                className="w-full bg-sky-600 text-white py-5 rounded-[2rem] font-black uppercase text-xs tracking-widest shadow-xl shadow-sky-100"
              >
                Escanear Otro
              </button>
            </div>
          </RoundedCard>
        )}
      </div>

      <style>{`
        @keyframes scan-line {
          0% { top: 0%; opacity: 0; }
          10% { opacity: 1; }
          90% { opacity: 1; }
          100% { top: 100%; opacity: 0; }
        }
        @keyframes scan-trail {
          0% { top: -50%; opacity: 0; }
          10% { opacity: 1; }
          90% { opacity: 1; }
          100% { top: 50%; opacity: 0; }
        }
        .animate-scan-line { animation: scan-line 2s cubic-bezier(0.4, 0, 0.2, 1) infinite; }
        .animate-scan-trail { animation: scan-trail 2s cubic-bezier(0.4, 0, 0.2, 1) infinite; }
      `}</style>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Product, Customer, CartItem, PaymentSplit, Sale, Employee, TicketConfig } from '../types';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';
import html2canvas from 'html2canvas';

// --- COMPONENTE TICKET MODAL (ESTILO TÉRMICO) ---
interface TicketModalProps {
  sale: Sale;
  config: TicketConfig;
  onClose: () => void;
  onWhatsApp: () => void;
  onNewSale: () => void;
  onFinish: () => void;
}

const TicketModal = ({ sale, config, onClose, onWhatsApp, onNewSale, onFinish }: TicketModalProps) => {
  const [sharing, setSharing] = useState(false);
  const qrData = btoa(`AQUA-PRO-SECURE|${JSON.stringify({ id: sale.id, total: sale.total })}`);
  const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(qrData)}`;

  const handlePrint = () => {
    window.print();
  };

  const handleNativeShare = async () => {
    setSharing(true);
    try {
      const element = document.getElementById('printable-ticket');
      if (!element) return;

      // Generar imagen del ticket
      const canvas = await html2canvas(element, { 
        scale: 2, 
        backgroundColor: '#ffffff',
        logging: false 
      });

      canvas.toBlob(async (blob: Blob | null) => {
        if (!blob) {
          alert("Error al generar imagen");
          setSharing(false);
          return;
        }

        const file = new File([blob], `Ticket_${sale.id}.png`, { type: "image/png" });

        // Intentar usar Web Share API Nivel 2 (Archivos) para compartir sin descarga manual
        if (navigator.canShare && navigator.canShare({ files: [file] })) {
          try {
            await navigator.share({
              files: [file],
              title: `Ticket ${sale.id}`,
              text: `Gracias por tu compra en ${config.businessName}.`
            });
          } catch (error) {
            // Usuario canceló o error
            console.log("Compartir cancelado o no soportado");
          }
        } else {
          // Fallback: Descargar imagen si no soporta compartir nativo
          const link = document.createElement('a');
          link.href = URL.createObjectURL(blob);
          link.download = `Ticket_${sale.id}.png`;
          link.click();
          alert("Tu dispositivo no soporta compartir imágenes directo. La imagen se ha descargado; adjúntala en WhatsApp.");
        }
        setSharing(false);
      }, 'image/png');

    } catch (e) {
      console.error(e);
      alert("No se pudo generar la imagen para compartir.");
      setSharing(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[300] bg-slate-900/80 backdrop-blur-sm flex flex-col items-center justify-center p-4 animate-fadeIn">
      {/* Contenedor Visual del Ticket (Simula Papel) - Adaptado */}
      <div className="bg-white w-full max-w-[340px] max-h-[85vh] shadow-2xl rounded-3xl overflow-hidden flex flex-col relative print:w-full print:shadow-none print:max-w-none print:max-h-none print:absolute print:top-0 print:left-0 print:rounded-none">

        {/* Efecto de papel cortado */}
        <div className="absolute top-0 left-0 right-0 h-1 bg-[url('data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHdpZHRoPSIxMCIgaGVpZ2h0PSIxMCIgdmlld0JveD0iMCAwIDEwIDEwIj48cGF0aCBkPSJNTAgMTBMNSAwTDEwIDEwWiIgZmlsbD0iI2YzZjRZjYiLz48L3N2Zz4=')] opacity-50 z-10 pointer-events-none print:hidden"></div>

        <div className="overflow-y-auto flex-1 p-6 pb-2 text-center font-mono text-slate-900 leading-tight text-xs relative custom-scrollbar" id="printable-ticket">
            {config.logoUrl && <img src={config.logoUrl} alt="Logo" className="w-20 h-20 object-contain mx-auto mb-3 grayscale mix-blend-multiply" />}

            <h2 className="text-lg font-black uppercase mb-1 tracking-tighter">{config.businessName}</h2>
            {config.slogan && <p className="text-[9px] italic mb-3 opacity-70">"{config.slogan}"</p>}

            <div className="border-b-2 border-dashed border-slate-300 pb-3 mb-3 space-y-0.5">
              <p>RFC: {config.rfc}</p>
              <p>{config.address}</p>
              <p>Tel: {config.phone}</p>
              <p>{new Date(sale.timestamp).toLocaleString()}</p>
            </div>

            <div className="text-left mb-3 space-y-1">
              <p>FOLIO: <span className="font-bold">{sale.id}</span></p>
              <p>CLIENTE: {sale.customerAlias.toUpperCase()}</p>
            </div>

            <table className="w-full mb-3 border-collapse">
              <thead>
                <tr className="border-b border-slate-900">
                  <th className="text-left py-1 w-8">CANT</th>
                  <th className="text-left py-1">DESC</th>
                  <th className="text-right py-1">IMP</th>
                </tr>
              </thead>
              <tbody>
                {sale.items.map((item, i) => (
                  <tr key={i}>
                    <td className="text-left py-1 align-top font-bold">{item.quantity}</td>
                    <td className="text-left py-1 align-top">{item.name.slice(0, 18)}</td>
                    <td className="text-right py-1 align-top">${(item.quantity * item.price).toFixed(2)}</td>
                  </tr>
                ))}
              </tbody>
            </table>

            <div className="border-t-2 border-slate-900 pt-2 mb-2 text-right">
              <p className="text-xl font-black">TOTAL: ${sale.total.toFixed(2)}</p>
            </div>

            <div className="text-right mb-4 space-y-0.5 text-[10px]">
              <p>SU PAGO: ${sale.paidAmount.toFixed(2)}</p>
              {sale.paidAmount < sale.total ? (
                  <p className="font-bold bg-slate-900 text-white inline-block px-1">PENDIENTE: ${(sale.total - sale.paidAmount).toFixed(2)}</p>
              ) : (
                  <p>CAMBIO: ${sale.change.toFixed(2)}</p>
              )}
            </div>

            {sale.emptyGarrafonsReturned > 0 && (
              <div className="border-2 border-slate-900 p-2 mb-4 text-xs font-bold uppercase text-center">
                  ★ {sale.emptyGarrafonsReturned} Envases Recibidos ★
              </div>
            )}

            <div className="pt-2 mb-4 text-center opacity-80">
              <p className="font-bold mb-1">{config.footerMessage}</p>
              <p className="text-[8px] italic">{config.extraNote}</p>
            </div>

            <div className="flex flex-col items-center pb-2">
              <img src={qrUrl} alt="QR" className="w-20 h-20 mb-1 mix-blend-multiply" />
            </div>
        </div>

        {/* Action Bar (Hidden Print) */}
        <div className="bg-slate-100 p-4 border-t border-slate-200 shrink-0 print:hidden space-y-3 z-20 relative">
             {/* Acciones del Ticket */}
             <div className="grid grid-cols-2 gap-3">
                <button 
                    onClick={handleNativeShare} 
                    disabled={sharing}
                    className="bg-emerald-500 text-white py-3 rounded-xl font-black uppercase text-[10px] flex items-center justify-center gap-2 active:scale-95 transition-transform shadow-lg shadow-emerald-100"
                >
                    {sharing ? <i className="fas fa-spinner animate-spin"></i> : <i className="fas fa-share-nodes"></i>}
                    {sharing ? 'Generando...' : 'Compartir (Imagen)'}
                </button>
                <button 
                    onClick={onWhatsApp} 
                    className="bg-white border border-emerald-500 text-emerald-600 py-3 rounded-xl font-black uppercase text-[10px] flex items-center justify-center gap-2 active:scale-95 transition-transform shadow-sm"
                >
                    <i className="fab fa-whatsapp"></i> WA (Texto)
                </button>
             </div>

             {/* Navegación Final */}
             <div className="grid grid-cols-2 gap-3 pt-2 border-t border-slate-200">
                <button 
                    onClick={handlePrint} 
                    className="bg-slate-800 text-white py-3 rounded-xl font-black uppercase text-[10px] flex items-center justify-center gap-2 active:scale-95 transition-transform shadow-lg"
                >
                    <i className="fas fa-print"></i> PDF / Print
                </button>
                <button 
                    onClick={onNewSale} 
                    className="bg-sky-600 text-white py-3 rounded-xl font-black uppercase text-[10px] flex items-center justify-center gap-2 active:scale-95 transition-transform shadow-xl shadow-sky-200"
                >
                    <i className="fas fa-plus"></i> Nueva Venta
                </button>
             </div>
             <button 
                onClick={onFinish} 
                className="w-full text-slate-400 text-[10px] font-bold uppercase underline"
             >
                Cerrar Ventana
             </button>
        </div>
      </div>
    </div>
  );
};

// --- COMPONENTE MODAL DE COBRO ---
interface PaymentModalProps {
  total: number;
  onConfirm: (cash: number, transfer: number) => void;
  onCancel: () => void;
}

const PaymentModal = ({ total, onConfirm, onCancel }: PaymentModalProps) => {
  const [cash, setCash] = useState('');
  const [transfer, setTransfer] = useState('');

  const numCash = parseFloat(cash) || 0;
  const numTransfer = parseFloat(transfer) || 0;
  const totalPaid = numCash + numTransfer;
  const change = totalPaid - total;
  const remaining = total - totalPaid;
  const isComplete = totalPaid >= total;
  const isCredit = !isComplete && totalPaid > 0; 

  return (
    <div className="fixed inset-0 z-[150] bg-slate-900/80 backdrop-blur-sm flex items-end justify-center sm:items-center p-0 sm:p-4 animate-fadeIn">
      <div className="bg-white w-full max-w-md rounded-t-[2.5rem] sm:rounded-[2.5rem] p-6 shadow-2xl">
         <div className="flex justify-between items-center mb-6">
            <h3 className="text-xl font-black text-sky-900">Cobrar Venta</h3>
            <button onClick={onCancel} className="w-10 h-10 bg-slate-100 rounded-full text-slate-400 flex items-center justify-center"><i className="fas fa-times"></i></button>
         </div>

         <div className="text-center mb-8">
            <p className="text-xs font-black uppercase text-slate-400 tracking-widest mb-1">Total a Pagar</p>
            <p className="text-5xl font-black text-slate-900 tracking-tighter">${total.toFixed(2)}</p>
         </div>

         <div className="space-y-4 mb-8">
            <div className="bg-sky-50 p-4 rounded-2xl flex items-center gap-4 border border-sky-100 focus-within:ring-2 ring-sky-300 transition-all">
               <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center text-sky-600 shadow-sm"><i className="fas fa-money-bill"></i></div>
               <div className="flex-1">
                  <label className="text-[9px] font-black uppercase text-sky-400 block">Efectivo</label>
                  <input 
                    type="number" 
                    placeholder="0.00" 
                    className="w-full bg-transparent font-black text-xl text-sky-900 outline-none"
                    value={cash}
                    onChange={e => setCash(e.target.value)}
                    autoFocus
                  />
               </div>
            </div>

            <div className="bg-sky-50 p-4 rounded-2xl flex items-center gap-4 border border-sky-100 focus-within:ring-2 ring-sky-300 transition-all">
               <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center text-indigo-500 shadow-sm"><i className="fas fa-building-columns"></i></div>
               <div className="flex-1">
                  <label className="text-[9px] font-black uppercase text-indigo-400 block">Transferencia</label>
                  <input 
                    type="number" 
                    placeholder="0.00" 
                    className="w-full bg-transparent font-black text-xl text-indigo-900 outline-none"
                    value={transfer}
                    onChange={e => setTransfer(e.target.value)}
                  />
               </div>
            </div>
         </div>

         <div className={`p-5 rounded-2xl mb-6 transition-colors flex justify-between items-center ${
            isComplete ? 'bg-emerald-100 text-emerald-700' : remaining > 0.1 ? 'bg-amber-100 text-amber-700' : 'bg-slate-100'
         }`}>
            <span className="text-xs font-black uppercase">
               {isComplete ? 'Cambio a entregar:' : 'Saldo Pendiente (Crédito):'}
            </span>
            <span className="text-2xl font-black">
               ${isComplete ? change.toFixed(2) : remaining.toFixed(2)}
            </span>
         </div>

         <ActionButton 
            onClick={() => onConfirm(numCash, numTransfer)} 
            disabled={totalPaid === 0 && !isCredit}
            variant={isComplete ? 'primary' : 'secondary'}
         >
            {isComplete ? 'Cobrar y Emitir Ticket' : 'Registrar Venta a Crédito'}
         </ActionButton>
      </div>
    </div>
  );
};

export const POSModule: React.FC<{ onBack: () => void; user: Employee }> = ({ onBack, user }) => {
  const { products, customers, sales, addSale, ticketConfig } = useERPData();
  const [activeTab, setActiveTab] = useState<'sell' | 'history'>('sell');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [customer, setCustomer] = useState<Customer | null>(null);
  const [search, setSearch] = useState('');
  const [vacios, setVacios] = useState(0);

  // States para modales
  const [showPaymentModal, setShowPaymentModal] = useState(false);
  const [viewingTicket, setViewingTicket] = useState<Sale | null>(null);

  // Admin Time Control
  const getLocalISO = (d: Date = new Date()) => {
    const offset = d.getTimezoneOffset() * 60000;
    return new Date(d.getTime() - offset).toISOString().slice(0, 16);
  };
  const [manualDate, setManualDate] = useState<string>(getLocalISO());
  const [autoTime, setAutoTime] = useState(true);
  const [nowDisplay, setNowDisplay] = useState(new Date());

  useEffect(() => {
    let interval: any;
    if (autoTime) {
      interval = setInterval(() => {
        const d = new Date();
        setNowDisplay(d);
        setManualDate(getLocalISO(d));
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [autoTime]);

  const handleDateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setAutoTime(false);
    setManualDate(e.target.value);
  };

  const total = cart.reduce((sum, item) => {
    const price = (customer?.specialPrice && item.id === '1') ? customer.specialPrice : item.price;
    return sum + (price * item.quantity);
  }, 0);

  // Auto-calc vacios
  useEffect(() => {
    const garrafonesInCart = cart.filter(i => i.name.toLowerCase().includes('garraf') || i.category === 'Agua').reduce((acc, i) => acc + i.quantity, 0);
    if (cart.length > 0 && vacios === 0) setVacios(garrafonesInCart);
    else if (cart.length === 0) setVacios(0);
  }, [cart]);

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === product.id);
      if (existing) return prev.map(i => i.id === product.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const decreaseQuantity = (productId: string) => {
    setCart(prev => prev.map(item => {
      if (item.id === productId) {
        return { ...item, quantity: Math.max(0, item.quantity - 1) };
      }
      return item;
    }).filter(item => item.quantity > 0));
  };

  const removeFromCart = (productId: string) => {
    setCart(prev => prev.filter(item => item.id !== productId));
  };

  const handleSendWhatsApp = (sale: Sale) => {
    const currentCustomer = customers.find(c => c.id === sale.customerId);
    const phone = currentCustomer?.phone?.replace(/\D/g, '') || '';
    if (!phone) { alert("El cliente no tiene teléfono registrado."); return; }
    const itemsText = sale.items.map(i => `• ${i.quantity}x ${i.name}`).join('%0A');
    const debtMsg = sale.paidAmount < sale.total ? `%0A%0A⚠️ *Saldo Pendiente:* $${(sale.total - sale.paidAmount).toFixed(2)}` : '';
    const fullPhone = phone.length === 10 ? `52${phone}` : phone;
    const msg = `¡Hola ${sale.customerAlias}!%0A%0A*${ticketConfig.businessName}*%0AGracias por tu compra.%0A%0A*Pedido:*%0A${itemsText}%0A%0A*Total:* $${sale.total.toFixed(2)}${debtMsg}%0A*Folio:* ${sale.id}%0A%0A_Excelente día._`;
    window.open(`https://wa.me/${fullPhone}?text=${msg}`, '_blank');
  };

  const handlePreCheckout = () => {
    if (!customer) return alert("Selecciona un cliente.");
    if (cart.length === 0) return alert("El carrito está vacío.");
    setShowPaymentModal(true);
  };

  const handleConfirmPayment = (cash: number, transfer: number) => {
    if(!customer) return;

    const totalPaid = cash + transfer;
    const splits: PaymentSplit[] = [];
    if (cash > 0) splits.push({ method: 'Efectivo', amount: cash });
    if (transfer > 0) splits.push({ method: 'Transferencia', amount: transfer });

    const sale = addSale(
      customer.id, cart, total, totalPaid, splits, vacios, 
      user.role === 'Administrador' ? new Date(manualDate).getTime() : undefined
    );

    setShowPaymentModal(false);
    setViewingTicket(sale); // Mostrar ticket
  };

  const resetPOS = () => {
    setViewingTicket(null);
    setCart([]);
    setCustomer(null);
    setSearch('');
    setVacios(0);
    setActiveTab('sell'); // Forzar regreso a la pestaña de venta
    if (user.role === 'Administrador') setAutoTime(true); 
  };

  return (
    <div className="h-full flex flex-col animate-fadeIn bg-sky-50 pb-24 overflow-hidden relative">
      <ModuleHeader title="Punto de Venta" onBack={onBack} />

      <div className="px-6 flex gap-2 mb-4">
        <button onClick={() => setActiveTab('sell')} className={`flex-1 py-3 rounded-2xl text-xs font-bold ${activeTab === 'sell' ? 'bg-sky-600 text-white shadow-lg' : 'bg-white text-sky-400'}`}>Nueva Venta</button>
        <button onClick={() => setActiveTab('history')} className={`flex-1 py-3 rounded-2xl text-xs font-bold ${activeTab === 'history' ? 'bg-sky-600 text-white shadow-lg' : 'bg-white text-sky-400'}`}>Historial</button>
      </div>

      {activeTab === 'sell' ? (
        <div className="flex-1 overflow-y-auto px-6 space-y-6 pb-32 no-scrollbar">
          {/* Admin Date Control */}
          {user.role === 'Administrador' && (
            <div className={`p-4 rounded-[2.2rem] border transition-all duration-500 ${autoTime ? 'bg-white border-sky-100' : 'bg-amber-50 border-amber-200 shadow-inner'}`}>
              <div className="flex justify-between items-center mb-3">
                <div className="flex items-center gap-2">
                  <div className={`w-2.5 h-2.5 rounded-full ${autoTime ? 'bg-emerald-500 animate-pulse' : 'bg-amber-500'}`}></div>
                  <label className="text-[10px] font-black uppercase tracking-widest text-sky-900">
                    {autoTime ? 'TIEMPO REAL' : 'MODO MANUAL'}
                  </label>
                </div>
                {!autoTime && (
                  <button onClick={() => setAutoTime(true)} className="flex items-center gap-1 text-[9px] font-black text-sky-500 uppercase bg-sky-50 px-3 py-1.5 rounded-full active:scale-95 transition-transform">
                    <i className="fas fa-rotate"></i> Sincronizar
                  </button>
                )}
              </div>

              <div className="flex gap-3 items-center">
                <div className="flex-1 relative">
                  <input 
                    type="datetime-local" 
                    className={`w-full border-none rounded-2xl p-4 text-xs font-black shadow-sm outline-none transition-all ${
                      autoTime 
                        ? 'bg-sky-50 text-sky-400 pointer-events-none opacity-80' 
                        : 'bg-white text-amber-600 ring-2 ring-amber-200'
                    }`}
                    value={manualDate}
                    onChange={handleDateChange}
                  />
                </div>
              </div>
            </div>
          )}

          <section>
            <div className="relative">
              <input type="text" placeholder="Buscar Cliente..." className="w-full bg-white border-none rounded-[2rem] py-5 px-8 shadow-sm outline-none" value={search} onChange={e => setSearch(e.target.value)} />
              {search && !customer && (
                <div className="absolute top-full left-0 right-0 bg-white shadow-2xl rounded-3xl mt-2 z-50 overflow-hidden border border-sky-50 max-h-60 overflow-y-auto">
                  {customers.filter(c => c.alias.toLowerCase().includes(search.toLowerCase())).map(c => (
                    <button key={c.id} onClick={() => { setCustomer(c); setSearch(c.alias); }} className="w-full text-left p-4 hover:bg-sky-50 font-bold border-b border-sky-50 flex justify-between items-center">
                      <span className="text-sky-900">{c.alias}</span>
                      <span className="text-[10px] bg-sky-50 text-sky-400 px-3 py-1 rounded-full font-black">${c.balance}</span>
                    </button>
                  ))}
                </div>
              )}
            </div>
            {customer && (
              <div className="mt-4 flex items-center justify-between bg-sky-600 text-white p-4 rounded-[1.8rem] shadow-lg animate-fadeIn">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-white/20 rounded-2xl flex items-center justify-center"><i className="fas fa-user"></i></div>
                  <div>
                    <span className="text-[8px] font-black uppercase opacity-60 block">Cliente Activo</span>
                    <span className="font-black text-sm">{customer.alias}</span>
                    {customer.balance > 0 && (
                      <span className="text-[9px] bg-red-500/30 px-2 py-0.5 rounded ml-2 font-bold">Adeudo: ${customer.balance}</span>
                    )}
                  </div>
                </div>
                <button onClick={() => {setCustomer(null); setSearch('');}} className="w-10 h-10 bg-white/10 rounded-full flex items-center justify-center active:scale-90 transition-all"><i className="fas fa-times"></i></button>
              </div>
            )}
          </section>

          <div className="grid grid-cols-2 gap-3">
            {products.map(p => (
              <button key={p.id} onClick={() => addToCart(p)} className="bg-white p-5 rounded-[2.2rem] shadow-sm active:bg-sky-50 text-left relative overflow-hidden group border border-transparent hover:border-sky-100 transition-all">
                <div className="text-xs font-black text-sky-900 uppercase tracking-tight mb-1">{p.name}</div>
                <div className="text-sky-600 font-black text-lg">${p.price}</div>
                <div className="absolute -bottom-2 -right-2 w-12 h-12 bg-sky-50 text-sky-100 flex items-center justify-center rounded-tl-3xl group-active:text-sky-200 transition-colors">
                  <i className="fas fa-plus"></i>
                </div>
              </button>
            ))}
          </div>

          {cart.length > 0 && (
            <RoundedCard className="shadow-2xl border-2 border-white mb-20">
              <div className="flex justify-between items-start mb-6">
                <div>
                  <span className="text-[10px] text-sky-400 font-black uppercase mb-1 block">Total Carrito</span>
                  <span className="text-4xl font-black text-sky-900 tracking-tighter">${total.toFixed(2)}</span>
                </div>
                <button onClick={() => setCart([])} className="text-rose-400 text-xs font-bold uppercase underline">Vaciar</button>
              </div>

              <div className="space-y-3 mb-6">
                {cart.map(i => (
                  <div key={i.id} className="flex justify-between items-center bg-sky-50/50 p-2 rounded-2xl border border-sky-100">
                    <div className="flex flex-col">
                       <span className="text-[10px] font-black text-sky-900 uppercase max-w-[120px] truncate">{i.name}</span>
                       <span className="text-xs font-bold text-sky-600">${(i.quantity * i.price).toFixed(2)}</span>
                    </div>

                    <div className="flex items-center gap-2 bg-white rounded-xl shadow-sm p-1">
                       <button onClick={() => decreaseQuantity(i.id)} className="w-8 h-8 flex items-center justify-center bg-sky-50 text-sky-600 rounded-lg active:bg-sky-200 transition-colors font-bold">-</button>
                       <span className="text-sm font-black text-sky-900 w-6 text-center">{i.quantity}</span>
                       <button onClick={() => addToCart(i)} className="w-8 h-8 flex items-center justify-center bg-sky-600 text-white rounded-lg active:scale-95 transition-transform font-bold">+</button>
                    </div>
                  </div>
                ))}
              </div>

              {/* Control de Garrafones Vacíos */}
              <div className="mb-2 bg-white p-4 rounded-3xl border border-sky-100 flex justify-between items-center">
                 <span className="text-[10px] font-black text-sky-400 uppercase tracking-tight ml-2">Envases Vacíos</span>
                 <div className="flex items-center gap-3 bg-sky-50 rounded-2xl p-1">
                    <button onClick={() => setVacios(Math.max(0, vacios - 1))} className="w-8 h-8 flex items-center justify-center bg-white text-sky-600 rounded-xl font-black shadow-sm">-</button>
                    <span className="text-lg font-black text-sky-900 w-6 text-center">{vacios}</span>
                    <button onClick={() => setVacios(vacios + 1)} className="w-8 h-8 flex items-center justify-center bg-sky-600 text-white rounded-xl font-black shadow-lg">+</button>
                 </div>
              </div>
            </RoundedCard>
          )}
        </div>
      ) : (
        <div className="flex-1 overflow-y-auto px-6 space-y-3 pb-10 no-scrollbar">
          {sales.length === 0 ? (
            <div className="text-center py-20 opacity-30">
               <i className="fas fa-receipt text-6xl mb-4"></i>
               <p className="text-xs font-black uppercase">Sin historial reciente</p>
            </div>
          ) : (
            sales.map(s => (
              <RoundedCard key={s.id} className="py-5 border-none shadow-sm group">
                <div className="flex justify-between items-start">
                  <div className="flex gap-4">
                    <div className="w-12 h-12 bg-sky-50 text-sky-600 rounded-2xl flex items-center justify-center text-xl">
                      <i className="fas fa-receipt"></i>
                    </div>
                    <div>
                      <h4 className="font-black text-sky-900 text-sm leading-tight">{s.customerAlias}</h4>
                      <p className="text-[9px] text-sky-400 font-bold uppercase mt-1">{new Date(s.timestamp).toLocaleString()}</p>
                      {s.paidAmount < s.total && (
                        <span className="text-[9px] text-amber-500 font-black uppercase bg-amber-50 px-2 py-0.5 rounded mt-1 inline-block">Crédito</span>
                      )}
                    </div>
                  </div>
                  <div className="text-right">
                    <span className="font-black text-sky-600 text-xl tracking-tighter">${s.total}</span>
                    <p className="text-[8px] font-black text-sky-300 uppercase">{s.id}</p>
                  </div>
                </div>
                <div className="flex gap-2 mt-5">
                   <button onClick={() => setViewingTicket(s)} className="flex-1 text-[9px] font-black uppercase bg-sky-100 text-sky-600 px-3 py-3 rounded-xl flex items-center justify-center gap-2 active:bg-sky-200 transition-colors">
                    <i className="fas fa-eye"></i> Ver Ticket
                   </button>
                   <button onClick={() => handleSendWhatsApp(s)} className="flex-1 text-[9px] font-black uppercase bg-emerald-100 text-emerald-600 px-3 py-3 rounded-xl flex items-center justify-center gap-2 active:bg-emerald-200 transition-colors">
                    <i className="fab fa-whatsapp"></i> WA (Txt)
                   </button>
                </div>
              </RoundedCard>
            ))
          )}
        </div>
      )}

      {activeTab === 'sell' && (
        <div className="fixed bottom-0 left-0 right-0 p-6 bg-white/95 border-t border-sky-100 shadow-[0_-10px_40px_rgba(0,0,0,0.1)] z-50">
          <ActionButton onClick={handlePreCheckout} disabled={!customer || cart.length === 0}>
             Ir a Pagar ${total.toFixed(2)}
          </ActionButton>
        </div>
      )}

      {/* Modales */}
      {showPaymentModal && (
        <PaymentModal 
          total={total}
          onConfirm={handleConfirmPayment}
          onCancel={() => setShowPaymentModal(false)}
        />
      )}

      {viewingTicket && (
        <TicketModal 
          sale={viewingTicket} 
          config={ticketConfig} 
          onClose={() => setViewingTicket(null)} 
          onWhatsApp={() => handleSendWhatsApp(viewingTicket)}
          onNewSale={resetPOS}
          onFinish={() => {
            setViewingTicket(null);
            setActiveTab('history');
          }}
        />
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';
import { Product, CartItem, PaymentSplit, Sale, TicketConfig } from '../types';
import html2canvas from 'html2canvas';

// Componente Interno del Visualizador de Ticket
const TicketViewerModal = ({ sale, config, onClose }: { sale: Sale, config: TicketConfig, onClose: () => void }) => {
  const [sharing, setSharing] = useState(false);
  const qrData = btoa(`AQUA-PRO-SECURE|${JSON.stringify({ id: sale.id, total: sale.total })}`);
  const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(qrData)}`;

  const handlePrint = () => {
    window.print();
  };

  const handleNativeShare = async () => {
    setSharing(true);
    try {
      const element = document.getElementById('printable-area');
      if (!element) return;

      const canvas = await html2canvas(element, { 
        scale: 2, 
        backgroundColor: '#ffffff',
        logging: false 
      });

      canvas.toBlob(async (blob: Blob | null) => {
        if (!blob) {
          alert("Error al generar imagen");
          setSharing(false);
          return;
        }

        const file = new File([blob], `Ticket_${sale.id}.png`, { type: "image/png" });

        // Compartir nativamente (Mobile)
        if (navigator.canShare && navigator.canShare({ files: [file] })) {
          try {
            await navigator.share({
              files: [file],
              title: `Ticket ${sale.id}`,
              text: `Hola ${sale.customerAlias}, aquí tienes tu ticket.`
            });
          } catch (error) {
            console.log("Compartir cancelado");
          }
        } else {
          // Fallback descarga manual (Desktop)
          const link = document.createElement('a');
          link.href = URL.createObjectURL(blob);
          link.download = `Ticket_${sale.id}.png`;
          link.click();
          alert("Imagen descargada. Compártela manualmente desde tu galería.");
        }
        setSharing(false);
      }, 'image/png');

    } catch (e) {
      console.error(e);
      alert("Error al compartir.");
      setSharing(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[300] bg-slate-900/80 backdrop-blur-sm flex flex-col items-center justify-center p-4 animate-fadeIn">
      {/* Botón de Cierre Flotante */}
      <button 
        onClick={onClose} 
        className="absolute top-6 right-6 w-12 h-12 bg-white/10 text-white rounded-full flex items-center justify-center hover:bg-white/20 active:scale-90 transition-all z-50 backdrop-blur-sm"
      >
        <i className="fas fa-times text-xl"></i>
      </button>

      {/* Contenedor Visual del Ticket (Simula Papel) - Adaptado */}
      <div className="bg-white w-full max-w-[340px] max-h-[85vh] shadow-2xl rounded-3xl overflow-hidden flex flex-col relative print:w-full print:shadow-none print:max-w-none print:max-h-none print:absolute print:top-0 print:left-0 print:rounded-none">

        {/* Efecto de papel cortado (Solo decorativo en pantalla) */}
        <div className="absolute top-0 left-0 right-0 h-1 bg-[url('data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHdpZHRoPSIxMCIgaGVpZ2h0PSIxMCIgdmlld0JveD0iMCAwIDEwIDEwIj48cGF0aCBkPSJNTAgMTBMNSAwTDEwIDEwWiIgZmlsbD0iI2YzZjRZjYiLz48L3N2Zz4=')] opacity-50 z-10 pointer-events-none print:hidden"></div>

        {/* Scrollable Content Area */}
        <div className="overflow-y-auto flex-1 p-6 pb-2 text-center font-mono text-slate-900 leading-tight text-xs relative custom-scrollbar" id="printable-area">
            {config.logoUrl && <img src={config.logoUrl} alt="Logo" className="w-20 h-20 object-contain mx-auto mb-3 grayscale mix-blend-multiply" />}

