// WhatsAppPDFSender.jsx
import React, { useState } from 'react';
import { PDFDocument } from 'pdf-lib';
import axios from 'axios';

export const WhatsAppPDFSender = () => {
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState({
    phone: '',
    name: '',
    message: 'Hola, te envío tu documento PDF adjunto.'
  });

  // Configuración de WhatsApp Business API
  const WHATSAPP_CONFIG = {
    PHONE_NUMBER_ID: process.env.REACT_APP_WHATSAPP_PHONE_ID,
    ACCESS_TOKEN: process.env.REACT_APP_WHATSAPP_TOKEN,
    API_VERSION: 'v18.0'
  };

  const generarPDF = async () => {
    const pdfDoc = await PDFDocument.create();
    const page = pdfDoc.addPage([595, 842]);

    // Diseño del PDF
    page.drawText('📄 DOCUMENTO IMPORTANTE', {
      x: 150,
      y: 750,
      size: 22,
    });

    page.drawText(`Para: ${formData.name}`, {
      x: 50,
      y: 700,
      size: 14,
    });

    page.drawText(`Fecha: ${new Date().toLocaleDateString('es-ES')}`, {
      x: 50,
      y: 670,
      size: 12,
    });

    page.drawText('Contenido del documento:', {
      x: 50,
      y: 630,
      size: 16,
    });

    page.drawText('• Certificado de compra', {
      x: 70,
      y: 600,
      size: 12,
    });

    page.drawText('• Información de garantía', {
      x: 70,
      y: 580,
      size: 12,
    });

    page.drawText('• Datos de contacto', {
      x: 70,
      y: 560,
      size: 12,
    });

    // QR Code para verificación (opcional)
    page.drawText('🔒 Documento verificado', {
      x: 200,
      y: 450,
      size: 14,
      color: { r: 0, g: 0.5, b: 0 },
    });

    return await pdfDoc.save();
  };

  const enviarPorWhatsApp = async () => {
    if (!formData.phone) {
      alert('Por favor ingresa un número de WhatsApp');
      return;
    }

    setLoading(true);

    try {
      // 1. Generar PDF
      const pdfBytes = await generarPDF();

      // 2. Convertir a Base64
      const base64PDF = btoa(
        new Uint8Array(pdfBytes).reduce(
          (data, byte) => data + String.fromCharCode(byte),
          ''
        )
      );

      // 3. Subir a servidor temporal (necesario para WhatsApp)
      const fileName = `documento_${Date.now()}.pdf`;

      // Opción A: Subir a Cloudinary (recomendado para producción)
      const cloudinaryUpload = await subirACloudinary(base64PDF, fileName);

      // Opción B: Usar servidor propio
      // const serverUpload = await subirAServidorPropio(pdfBytes, fileName);

      // 4. Enviar mensaje por WhatsApp
      await enviarMensajeWhatsApp(
        formData.phone,
        formData.message,
        cloudinaryUpload.secure_url
      );

      alert(`✅ PDF enviado al WhatsApp de ${formData.name}`);

    } catch (error) {
      console.error('Error:', error);
      alert('❌ Error al enviar por WhatsApp');
    } finally {
      setLoading(false);
    }
  };

  const subirACloudinary = async (base64File, fileName) => {
    const cloudName = process.env.REACT_APP_CLOUDINARY_CLOUD_NAME;
    const uploadPreset = process.env.REACT_APP_CLOUDINARY_UPLOAD_PRESET;

    const formData = new FormData();
    formData.append('file', `data:application/pdf;base64,${base64File}`);
    formData.append('upload_preset', uploadPreset);
    formData.append('public_id', fileName);

    const response = await fetch(
      `https://api.cloudinary.com/v1_1/${cloudName}/upload`,
      {
        method: 'POST',
        body: formData,
      }
    );

    return await response.json();
  };

  const enviarMensajeWhatsApp = async (phoneNumber, message, pdfUrl) => {
    const url = `https://graph.facebook.com/${WHATSAPP_CONFIG.API_VERSION}/${WHATSAPP_CONFIG.PHONE_NUMBER_ID}/messages`;

    const payload = {
      messaging_product: 'whatsapp',
      to: phoneNumber,
      type: 'document',
      document: {
        link: pdfUrl,
        filename: `documento_${Date.now()}.pdf`,
        caption: message
      }
    };

    const response = await axios.post(url, payload, {
      headers: {
        'Authorization': `Bearer ${WHATSAPP_CONFIG.ACCESS_TOKEN}`,
        'Content-Type': 'application/json',
      },
    });

    return response.data;
  };

  return (
    <div className="max-w-md mx-auto p-6 bg-white rounded-2xl shadow-xl">
      <div className="text-center mb-6">
        <div className="inline-flex items-center justify-center w-16 h-16 bg-green-100 rounded-full mb-4">
          <span className="text-3xl">📱</span>
        </div>
        <h2 className="text-2xl font-bold text-gray-800">
          Enviar PDF por WhatsApp
        </h2>
        <p className="text-gray-600 mt-2">
          Genera y envía documentos directamente a WhatsApp
        </p>
      </div>

      <div className="space-y-4">
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">
