import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import { TicketConfig, Sale } from '../types';

// Interface for the data expected by the report generator
interface ReportData {
  label: string;
  rangeType: string;
  totalGross: number;
  totalTransactions: number;
  averageTicket: number;
  payments: { cash: number; transfer: number };
  topProducts: { name: string; qty: number; total: number }[];
}

export const generateFinancialPDF = (data: ReportData, config: TicketConfig): string => {
  const doc = new jsPDF();
  const pageWidth = doc.internal.pageSize.width;

  // --- HEADER ---
  doc.setFillColor(2, 132, 199); // Sky-600
  doc.rect(0, 0, pageWidth, 40, 'F');

  doc.setTextColor(255, 255, 255);
  doc.setFontSize(22);
  doc.setFont('helvetica', 'bold');
  doc.text(config.businessName, 15, 15);

  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');
  doc.text('REPORTE FINANCIERO', 15, 22);
  doc.text(`Generado: ${new Date().toLocaleString()}`, 15, 27);

  // Right side header info
  doc.setFontSize(10);
  doc.text(`Periodo: ${data.label}`, pageWidth - 15, 15, { align: 'right' });
  doc.text(`Tipo: ${data.rangeType.toUpperCase()}`, pageWidth - 15, 20, { align: 'right' });

  // --- KPI CARDS (Simulated) ---
  let yPos = 55;

  // Title
  doc.setTextColor(15, 23, 42); // Slate-900
  doc.setFontSize(14);
  doc.setFont('helvetica', 'bold');
  doc.text('Resumen General', 15, yPos);

  yPos += 10;

  // Draw Boxes for KPIs
  const boxWidth = (pageWidth - 40) / 3;
  const boxHeight = 25;

  // Box 1: Ventas
  doc.setDrawColor(226, 232, 240);
  doc.setFillColor(248, 250, 252);
  doc.roundedRect(15, yPos, boxWidth, boxHeight, 3, 3, 'FD');
  doc.setFontSize(8);
  doc.setTextColor(100, 116, 139);
  doc.text('VENTAS BRUTAS', 20, yPos + 8);
  doc.setFontSize(12);
  doc.setTextColor(15, 23, 42);
  doc.setFont('helvetica', 'bold');
  doc.text(`$${data.totalGross.toLocaleString()}`, 20, yPos + 18);

  // Box 2: Ops
  doc.roundedRect(15 + boxWidth + 5, yPos, boxWidth, boxHeight, 3, 3, 'FD');
  doc.setFontSize(8);
  doc.setTextColor(100, 116, 139);
  doc.setFont('helvetica', 'normal');
  doc.text('TRANSACCIONES', 20 + boxWidth + 5, yPos + 8);
  doc.setFontSize(12);
  doc.setTextColor(15, 23, 42);
  doc.setFont('helvetica', 'bold');
  doc.text(`${data.totalTransactions}`, 20 + boxWidth + 5, yPos + 18);

  // Box 3: Ticket Prom
  doc.roundedRect(15 + (boxWidth * 2) + 10, yPos, boxWidth, boxHeight, 3, 3, 'FD');
  doc.setFontSize(8);
  doc.setTextColor(100, 116, 139);
  doc.setFont('helvetica', 'normal');
  doc.text('TICKET PROMEDIO', 20 + (boxWidth * 2) + 10, yPos + 8);
  doc.setFontSize(12);
  doc.setTextColor(15, 23, 42);
  doc.setFont('helvetica', 'bold');
  doc.text(`$${data.averageTicket.toFixed(2)}`, 20 + (boxWidth * 2) + 10, yPos + 18);

  yPos += 40;

  // --- PAYMENTS SECTION ---
  doc.setFontSize(12);
  doc.setTextColor(15, 23, 42);
  doc.text('Desglose de Ingresos', 15, yPos);

  yPos += 5;

  (doc as any).autoTable({
    startY: yPos,
    head: [['Método de Pago', 'Monto Recaudado']],
    body: [
      ['Efectivo', `$${data.payments.cash.toLocaleString()}`],
      ['Transferencia', `$${data.payments.transfer.toLocaleString()}`],
      ['TOTAL', `$${(data.payments.cash + data.payments.transfer).toLocaleString()}`]
    ],
    theme: 'striped',
    headStyles: { fillColor: [2, 132, 199] },
    styles: { fontSize: 10 },
    columnStyles: { 1: { halign: 'right', fontStyle: 'bold' } },
    foot: [['Balance', `$${(data.payments.cash + data.payments.transfer).toLocaleString()}`]],
    footStyles: { fillColor: [241, 245, 249], textColor: [15, 23, 42] }
  });

  yPos = (doc as any).lastAutoTable.finalY + 20;

  // --- PRODUCTS SECTION ---
  doc.text('Top Productos Vendidos', 15, yPos);
  yPos += 5;

  const productRows = data.topProducts.map(p => [
    p.name,
    p.qty.toString(),
    `$${p.total.toLocaleString()}`
  ]);

  (doc as any).autoTable({
    startY: yPos,
    head: [['Producto', 'Cantidad', 'Venta Total']],
    body: productRows,
    theme: 'grid',
    headStyles: { fillColor: [71, 85, 105] },
    columnStyles: { 
      1: { halign: 'center' },
      2: { halign: 'right' }
    }
  });

  // --- FOOTER ---
  const pageCount = (doc as any).internal.getNumberOfPages();
  for(let i = 1; i <= pageCount; i++) {
    doc.setPage(i);
    doc.setFontSize(8);
    doc.setTextColor(150);
    doc.text(`Aqua+ ERP - Documento Confidencial - Página ${i} de ${pageCount}`, pageWidth / 2, doc.internal.pageSize.height - 10, { align: 'center' });
  }

  // Return the Data URL string to be used in an iframe
  return doc.output('datauristring');
};

/**
 * Generates a Ticket PDF similar to the Python/HTML template provided.
 * Replicates styles:
 * - Header Color: #2c3e50
 * - Table Header: #3498db (Blue)
 * - Total: #e74c3c (Red)
 */
export const generateTicketPDF = (sale: Sale, config: TicketConfig): string => {
  const doc = new jsPDF();
  const pageWidth = doc.internal.pageSize.width;

  // --- HEADER (Matches Python .header style) ---
  // Color: #2c3e50 (Dark Slate)
  doc.setTextColor(44, 62, 80);
  doc.setFontSize(18);
  doc.setFont('helvetica', 'bold');
  doc.text('Reporte Generado', pageWidth / 2, 20, { align: 'center' });

  // Business Subtitle
  doc.setFontSize(12);
  doc.setFont('helvetica', 'normal');
  doc.text(config.businessName, pageWidth / 2, 28, { align: 'center' });

  // --- INFO ---
  let yPos = 40;
  doc.setFontSize(10);
  doc.setTextColor(0, 0, 0);

  // HTML: <p><strong>Cliente:</strong> ...</p>
  doc.setFont('helvetica', 'bold');
  doc.text('Cliente:', 15, yPos);
  doc.setFont('helvetica', 'normal');
  doc.text(sale.customerAlias, 40, yPos);

  yPos += 7;
  doc.setFont('helvetica', 'bold');
  doc.text('Fecha:', 15, yPos);
  doc.setFont('helvetica', 'normal');
  doc.text(new Date(sale.timestamp).toLocaleString(), 40, yPos);

  yPos += 7;
  doc.setFont('helvetica', 'bold');
  doc.text('Folio:', 15, yPos);
  doc.setFont('helvetica', 'normal');
  doc.text(sale.id, 40, yPos);

  // --- TABLE (Matches Python .table style) ---
  // HTML CSS: th { background-color: #3498db; color: white; }
  // HTML CSS: total { color: #e74c3c; }

  yPos += 10;

  const tableBody = sale.items.map(item => [
    item.name,
    item.quantity.toString(),
    `$${item.price.toFixed(2)}`,
    `$${(item.quantity * item.price).toFixed(2)}`
  ]);

  (doc as any).autoTable({
    startY: yPos,
    head: [['Producto', 'Cantidad', 'Precio Unitario', 'Subtotal']],
    body: tableBody,
    theme: 'plain', // Use plain to control borders manually if desired, or 'grid' for standard lines
    headStyles: { 
      fillColor: [52, 152, 219], // #3498db
      textColor: 255, 
      fontStyle: 'bold',
      halign: 'center' 
    },
    styles: { 
      cellPadding: 3,
      fontSize: 10,
      valign: 'middle',
      lineColor: [221, 221, 221], // #ddd
      lineWidth: 0.1, // border-bottom: 1px solid #ddd simulated by grid
    },
    columnStyles: {
      0: { halign: 'left' },
      1: { halign: 'center' },
      2: { halign: 'right' },
      3: { halign: 'right' }
    },
    // Adding the border bottom effect simulated
    didDrawCell: (data: any) => {
       // AutoTable handles borders via styles
    }
  });

  yPos = (doc as any).lastAutoTable.finalY + 15;

  // --- TOTAL (Matches Python .total style) ---
  // CSS: .total { font-weight: bold; color: #e74c3c; }

  const totalStr = `Total: $${sale.total.toFixed(2)}`;
  doc.setFontSize(16);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(231, 76, 60); // #e74c3c

  // Align right
  doc.text(totalStr, pageWidth - 15, yPos, { align: 'right' });

  // Optional Footer
  doc.setTextColor(150);
  doc.setFontSize(8);
  doc.setFont('helvetica', 'normal');
  doc.text(config.footerMessage, pageWidth / 2, doc.internal.pageSize.height - 15, { align: 'center' });

  return doc.output('datauristring');
};

