import React, { useState, useEffect } from 'react';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';
import { Product, CartItem, PaymentSplit, Sale, TicketConfig, Customer } from '../types';
import html2canvas from 'html2canvas';
import { Filesystem, Directory } from '@capacitor/filesystem';
import { generateTicketPDF } from '../services/pdfGenerator';

// Componente Interno del Visualizador de Ticket
const TicketViewerModal = ({ sale, config, onClose }: { sale: Sale, config: TicketConfig, onClose: () => void }) => {
  const { integrationConfig, customers } = useERPData();
  const [sharing, setSharing] = useState(false);
  const [apiSending, setApiSending] = useState(false);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved' | 'error'>('idle');
  const qrData = btoa(`AQUA-PRO-SECURE|${JSON.stringify({ id: sale.id, total: sale.total })}`);
  const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(qrData)}`;

  // Auto-save effect (Imagen PNG)
  useEffect(() => {
    const timer = setTimeout(() => {
      handleAutoSaveImage();
    }, 800); // Wait for render
    return () => clearTimeout(timer);
  }, []);

  const handleAutoSaveImage = async () => {
    try {
      setSaveStatus('saving');
      const element = document.getElementById('printable-area');
      if (!element) return;

      const canvas = await html2canvas(element, { 
        scale: 2, 
        backgroundColor: '#ffffff',
        logging: false 
      });

      const base64Data = canvas.toDataURL('image/png');
      const base64Content = base64Data.split(',')[1];
      const fileName = `Ticket_${sale.id}_${Date.now()}.png`;

      try {
        await Filesystem.writeFile({
          path: fileName,
          data: base64Content,
          directory: Directory.Documents
        });
        setSaveStatus('saved');
      } catch (fsError) {
        console.warn("Filesystem save failed (likely web browser), skipping auto-save to disk", fsError);
        setSaveStatus('error');
      }

    } catch (e) {
      console.error("Error generating image", e);
      setSaveStatus('error');
    }
  };

  const handleSavePDF = async () => {
    try {
      setSaveStatus('saving');
      const pdfDataUri = generateTicketPDF(sale, config);
      const base64Content = pdfDataUri.split(',')[1];
      const fileName = `Reporte_${sale.id}.pdf`;

      await Filesystem.writeFile({
        path: fileName,
        data: base64Content,
        directory: Directory.Documents
      });

      setSaveStatus('saved');
      alert(`PDF Guardado en Documentos como: ${fileName}`);

      if (!(window as any).Capacitor?.isNative) {
         const link = document.createElement('a');
         link.href = pdfDataUri;
         link.download = fileName;
         link.click();
      }

    } catch (e) {
      console.error("Error saving PDF", e);
      setSaveStatus('error');
      alert("Error al generar el PDF.");
    } finally {
      setTimeout(() => setSaveStatus('idle'), 2000);
    }
  };

  const handleCloudWhatsApp = async () => {
    if (!integrationConfig.whatsappToken || !integrationConfig.cloudinaryCloudName) {
      alert("Configura las claves de API en Ajustes > Integraciones.");
      return;
    }

    const currentCustomer = customers.find(c => c.id === sale.customerId);
    const phone = currentCustomer?.phone?.replace(/\D/g, '');

    if (!phone) {
      alert("El cliente no tiene teléfono.");
      return;
    }

    setApiSending(true);

    try {
      // 1. Generar PDF
      const pdfDataUri = generateTicketPDF(sale, config);
      const base64PDF = pdfDataUri.split(',')[1];

      // 2. Subir a Cloudinary
      const formData = new FormData();
      formData.append('file', `data:application/pdf;base64,${base64PDF}`);
      formData.append('upload_preset', integrationConfig.cloudinaryPreset);
      formData.append('public_id', `ticket_${sale.id}_${Date.now()}`);

      const uploadRes = await fetch(
        `https://api.cloudinary.com/v1_1/${integrationConfig.cloudinaryCloudName}/upload`,
        { method: 'POST', body: formData }
      );

      const uploadData = await uploadRes.json();
      if (!uploadData.secure_url) throw new Error("Fallo subida a nube");

      // 3. Enviar mensaje por WhatsApp API
      const waUrl = `https://graph.facebook.com/v18.0/${integrationConfig.whatsappPhoneId}/messages`;
      const fullPhone = phone.length === 10 ? `52${phone}` : phone;

      const payload = {
        messaging_product: 'whatsapp',
        to: fullPhone,
        type: 'document',
        document: {
          link: uploadData.secure_url,
          filename: `Ticket_${sale.id}.pdf`,
          caption: `Hola ${sale.customerAlias}, aquí tienes tu ticket de compra.`
        }
      };

      const waRes = await fetch(waUrl, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${integrationConfig.whatsappToken}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(payload)
      });

      if (!waRes.ok) throw new Error("Error WhatsApp API");

      alert("¡PDF enviado correctamente por WhatsApp!");

    } catch (e: any) {
      console.error(e);
      alert(`Error: ${e.message}`);
    } finally {
      setApiSending(false);
    }
  };

  const handleNativeShare = async () => {
    setSharing(true);
    try {
      const element = document.getElementById('printable-area');
      if (!element) return;

      const canvas = await html2canvas(element, { 
        scale: 2, 
        backgroundColor: '#ffffff',
        logging: false 
      });

      canvas.toBlob(async (blob: Blob | null) => {
        if (!blob) {
          alert("Error al generar imagen");
          setSharing(false);
          return;
        }

        const file = new File([blob], `Ticket_${sale.id}.png`, { type: "image/png" });

        if (navigator.canShare && navigator.canShare({ files: [file] })) {
          try {
            await navigator.share({
              files: [file],
              title: `Ticket ${sale.id}`,
              text: `Hola ${sale.customerAlias}, aquí tienes tu ticket.`
            });
          } catch (error) {
            console.log("Compartir cancelado");
          }
        } else {
          const link = document.createElement('a');
          link.href = URL.createObjectURL(blob);
          link.download = `Ticket_${sale.id}.png`;
          link.click();
          alert("Imagen descargada.");
        }
        setSharing(false);
      }, 'image/png');

    } catch (e) {
      console.error(e);
      alert("Error al compartir.");
      setSharing(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[300] bg-slate-900/80 backdrop-blur-sm flex flex-col items-center justify-center p-4 animate-fadeIn">
      <button onClick={onClose} className="absolute top-6 right-6 w-12 h-12 bg-white/10 text-white rounded-full flex items-center justify-center hover:bg-white/20 active:scale-90 transition-all z-50 backdrop-blur-sm">
        <i className="fas fa-times text-xl"></i>
