export const TicketModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const { customers, products, addSale, sales, ticketConfig } = useERPData();
  const [activeTab, setActiveTab] = useState<'create' | 'history'>('create');

  // State for Create
  const [manualDate, setManualDate] = useState<string>(() => {
    // Default to current time but in local ISO format for input
    const d = new Date();
    const offset = d.getTimezoneOffset() * 60000;
    return new Date(d.getTime() - offset).toISOString().slice(0, 16);
  });
  const [selectedCustomerId, setSelectedCustomerId] = useState<string>('');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [searchCustomer, setSearchCustomer] = useState('');

  // Modales
  const [showSuccessModal, setShowSuccessModal] = useState<Sale | null>(null);
  const [viewingTicket, setViewingTicket] = useState<Sale | null>(null);

  const customer = customers.find(c => c.id === selectedCustomerId);
  const total = cart.reduce((sum, item) => {
    const price = (customer?.specialPrice && item.id === '1') ? customer.specialPrice : item.price;
    return sum + (price * item.quantity);
  }, 0);

  const handleSendWhatsApp = (sale: Sale) => {
    const currentCustomer = customers.find(c => c.id === sale.customerId);
    const phone = currentCustomer?.phone?.replace(/\D/g, '');

    if (!phone) return alert("El cliente no tiene teléfono registrado.");

    const itemsText = sale.items.map(i => `• ${i.quantity}x ${i.name}`).join('%0A');
    const msg = `¡Hola ${sale.customerAlias}!%0A%0A*${ticketConfig.businessName}*%0AGracias por tu compra.%0A%0A*Detalles de tu pedido:*%0A${itemsText}%0A%0A*Total:* $${sale.total.toFixed(2)}%0A*Ticket:* ${sale.id}%0A%0A_Este es un comprobante digital._`;
    window.open(`https://wa.me/52${phone}?text=${msg}`, '_blank');
  };

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === product.id);
      if (existing) return prev.map(i => i.id === product.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.filter(i => i.id !== id));
  };

  const handleCreateTicket = () => {
    if (!customer || cart.length === 0 || !manualDate) {
      alert("Faltan datos (Cliente, Productos o Fecha).");
      return;
    }

    const timestamp = new Date(manualDate).getTime();
    if (isNaN(timestamp)) {
      alert("Fecha inválida.");
      return;
    }

    const splits: PaymentSplit[] = [{ method: 'Efectivo', amount: total }];

    const newSale = addSale(
      customer.id, 
      cart, 
      total, 
      total, 
      splits, 
      0, 
      timestamp
    );

    setShowSuccessModal(newSale);

    setCart([]);
    setSelectedCustomerId('');
    setSearchCustomer('');
  };

  return (
    <div className="h-full bg-slate-50 flex flex-col animate-fadeIn overflow-hidden pb-24 relative">
      <ModuleHeader title="Gestión de Tickets" onBack={onBack} />

      <div className="px-6 flex gap-2 mb-4 shrink-0">
        <button onClick={() => setActiveTab('create')} className={`flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'create' ? 'bg-slate-700 text-white shadow-lg' : 'bg-white text-slate-400'}`}>Emitir Retroactivo</button>
        <button onClick={() => setActiveTab('history')} className={`flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'history' ? 'bg-slate-700 text-white shadow-lg' : 'bg-white text-slate-400'}`}>Últimos Emitidos</button>
      </div>

      <div className="flex-1 overflow-y-auto px-6 space-y-6 no-scrollbar pb-10">

        {activeTab === 'create' && (
          <div className="space-y-6">
            <RoundedCard className="bg-slate-800 text-white border-none">
              <div className="flex items-center gap-3 mb-4">
                 <i className="fas fa-clock text-rose-400 text-xl"></i>
                 <h3 className="font-black uppercase text-sm">Fecha de Emisión</h3>
              </div>
              <p className="text-[10px] text-slate-400 mb-2">Selecciona la fecha y hora exacta que aparecerá en el ticket.</p>
              <input 
                type="datetime-local" 
                value={manualDate}
                onChange={(e) => setManualDate(e.target.value)}
                className="w-full bg-slate-700 text-white p-4 rounded-2xl outline-none font-bold text-lg border border-slate-600 focus:border-rose-400 transition-colors"
              />
            </RoundedCard>

            <section>
              <h4 className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2 px-2">Cliente</h4>
              <div className="relative">
                <input 
                  type="text" 
                  placeholder="Buscar cliente..." 
                  value={searchCustomer}
                  onChange={e => setSearchCustomer(e.target.value)}
                  className="w-full bg-white p-4 rounded-[1.5rem] shadow-sm font-bold text-slate-800 outline-none"
                />
                {searchCustomer && !selectedCustomerId && (
                  <div className="absolute top-full left-0 right-0 bg-white z-20 shadow-xl rounded-xl mt-2 max-h-40 overflow-y-auto border border-slate-100">
                    {customers.filter(c => c.alias.toLowerCase().includes(searchCustomer.toLowerCase())).map(c => (
                      <button 
                        key={c.id} 
                        onClick={() => { setSelectedCustomerId(c.id); setSearchCustomer(c.alias); }}
                        className="w-full text-left p-3 border-b border-slate-50 font-bold text-xs text-slate-600 hover:bg-slate-50"
                      >
                        {c.alias}
                      </button>
                    ))}
                  </div>
                )}
                {customer && (
                   <div className="mt-2 bg-emerald-50 text-emerald-600 px-4 py-2 rounded-xl text-xs font-black uppercase flex justify-between items-center border border-emerald-100">
                     <span>{customer.alias}</span>
                     <button onClick={() => { setSelectedCustomerId(''); setSearchCustomer(''); }}><i className="fas fa-times"></i></button>
                   </div>
                )}
              </div>
            </section>

            <section>
               <h4 className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2 px-2">Productos</h4>
               <div className="grid grid-cols-2 gap-2">
                 {products.map(p => (
                   <button 
                    key={p.id} 
                    onClick={() => addToCart(p)}
                    className="bg-white p-3 rounded-xl shadow-sm text-left active:scale-95 transition-transform border border-slate-50"
                   >
                     <p className="text-[9px] font-black uppercase text-slate-800">{p.name}</p>
                     <p className="text-xs font-bold text-slate-500">${p.price}</p>
                   </button>
                 ))}
               </div>
            </section>

            {cart.length > 0 && (
              <div className="bg-white p-5 rounded-[2rem] shadow-lg border border-slate-100">
                 <h4 className="text-xs font-black uppercase text-slate-800 mb-3 border-b pb-2">Resumen</h4>
                 {cart.map(i => (
                   <div key={i.id} className="flex justify-between items-center mb-2 text-xs">
                      <span className="font-bold text-slate-600">{i.quantity}x {i.name}</span>
                      <div className="flex items-center gap-3">
                         <span className="font-black text-slate-900">${(i.quantity * i.price)}</span>
                         <button onClick={() => removeFromCart(i.id)} className="text-rose-400"><i className="fas fa-trash"></i></button>
                      </div>
                   </div>
                 ))}
                 <div className="mt-4 pt-2 border-t flex justify-between items-center">
                    <span className="font-black text-slate-800 text-lg">TOTAL</span>
                    <span className="font-black text-slate-900 text-2xl">${total.toFixed(2)}</span>
                 </div>
                 <div className="mt-6">
                   <ActionButton onClick={handleCreateTicket} variant="primary">Guardar Ticket</ActionButton>
                 </div>
              </div>
            )}
          </div>
        )}

        {activeTab === 'history' && (
          <div className="space-y-4">
             {sales.length === 0 ? (
               <p className="text-center text-slate-400 text-xs py-10">No hay tickets registrados.</p>
             ) : (
               sales.slice(0, 20).map(s => (
                 <div key={s.id} className="bg-white p-5 rounded-[1.5rem] shadow-sm border border-slate-100">
                    <div className="flex justify-between items-center mb-4">
                      <div>
                         <div className="flex items-center gap-2">
                            <span className="bg-slate-100 text-slate-600 text-[8px] font-black px-2 py-0.5 rounded-full">{s.id}</span>
                            <span className="text-xs font-black text-slate-800">{s.customerAlias}</span>
                         </div>
                         <p className="text-[10px] text-slate-400 font-bold mt-1">
                           {new Date(s.timestamp).toLocaleDateString()} {new Date(s.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                         </p>
                      </div>
                      <span className="text-xl font-black text-slate-700">${s.total}</span>
                    </div>

                    <div className="flex gap-2">
                      <button 
                        onClick={() => setViewingTicket(s)} 
                        className="flex-1 bg-slate-50 text-slate-600 py-2 rounded-xl text-[9px] font-black uppercase flex items-center justify-center gap-2 active:bg-slate-200 transition-colors"
                      >
                        <i className="fas fa-eye"></i> Ver / PDF
                      </button>
                      <button 
                        onClick={() => handleSendWhatsApp(s)} 
                        className="flex-1 bg-emerald-50 text-emerald-600 py-2 rounded-xl text-[9px] font-black uppercase flex items-center justify-center gap-2 active:bg-emerald-100 transition-colors"
                      >
                        <i className="fab fa-whatsapp"></i> WA (Txt)
                      </button>
                    </div>
                 </div>
               ))
             )}
          </div>
        )}
      </div>

      {/* Visor de Ticket (PDF Mode) */}
      {(showSuccessModal || viewingTicket) && (
        <TicketViewerModal 
          sale={showSuccessModal || viewingTicket!}
          config={ticketConfig}
          onClose={() => { setShowSuccessModal(null); setViewingTicket(null); }}
        />
      )}
    </div>
  );
};

export type ViewType = 'dashboard' | 'pos' | 'orders' | 'logistics' | 'production' | 'sync' | 'whatsapp' | 'customers' | 'employees' | 'reports' | 'settings' | 'quality' | 'scanner' | 'inventory' | 'tickets' | 'supplies';

export interface Product {
  id: string;
  name: string;
  price: number;
  stock: number;
  category?: 'Agua' | 'Insumos' | 'Accesorios';
}

export type GarrafonType = 'Aqua' | 'Bonafont' | 'Ciel' | 'E-Pura' | 'Generico';

export interface Customer {
  id: string;
  name: string;
  alias: string;
  address?: string; // New field
  phone?: string;
  specialPrice?: number;
  lat?: number;
  lng?: number;
  garrafonType?: GarrafonType;
  balance: number;
}

export interface TicketConfig {
  businessName: string;
  rfc: string;
  address: string;
  phone: string;
  footerMessage: string;
  logoUrl?: string;
  website?: string;
  socialMedia?: string;
  extraNote?: string;
  slogan?: string;
  email?: string;
}

export interface CloudConfig {
  url: string;
  apiKey: string;
  autoSync: boolean;
  lastSync?: number;
}

export interface Order {
  id: string;
  customerId: string;
  customerAlias: string;
  items: CartItem[];
  total: number;
  status: 'pendiente' | 'asignado' | 'entregado' | 'cancelado';
  vehicleId?: string;
  timestamp: number;
  priority: number;
}

export interface CartItem extends Product {
  quantity: number;
}

export type PaymentMethod = 'Efectivo' | 'Transferencia' | 'Crédito' | 'Multimodal';

export interface PaymentSplit {
  method: 'Efectivo' | 'Transferencia';
  amount: number;
}

export interface Sale {
  id: string;
  timestamp: number;
  customerId: string;
  customerAlias: string;
  items: CartItem[];
  total: number;
  paidAmount: number;
  change: number;
  paymentSplits: PaymentSplit[];
  emptyGarrafonsReturned: number;
  synced: boolean;
}

export interface QualityRecord {
  id: string;
  timestamp: number;
  type: 'Cruda' | 'Producto';
  ph: number;
  cloro: number;
  tds: number;
  dureza: number;
  color: string;
  sabor: string;
  turbiedad: string;
  employeeId: string;
}

export interface Task {
  id: string;
  employeeId: string;
  title: string;
  description?: string;
  status: 'pendiente' | 'completada';
  timestamp: number;
  date: string;
}

export interface Attendance {
  id: string;
  employeeId: string;
  timestamp: number;
  date: string;
  status: 'presente' | 'falta' | 'retardo';
}

export interface Employee {
  id: string;
  name: string;
  role: 'Repartidor' | 'Planta' | 'Administrador';
  phone: string;
  pin: string;
  permissions: ViewType[];
}

export interface FuelRecord {
  id: string;
  date: number;
  mileage: number;
  liters: number;
  cost: number;
  notes?: string;
}

export interface Vehicle {
  id: string;
  plate: string;
  description: string;
  loadCapacity: number;
  currentLoad: number;
  inventory: CartItem[]; // Detalle de productos en la unidad
  fuelHistory: FuelRecord[]; // Registro de combustible
}

export interface SavedReport {
  id: string;
  timestamp: number;
  rangeType: 'day' | 'week' | 'month';
  dateLabel: string; // "12 Oct 2023" or "Semana 42"
  totalGross: number;
  totalTransactions: number;
  averageTicket: number;
  payments: { cash: number, transfer: number };
  topProducts: { name: string, qty: number, total: number }[];
  notes?: string;
}

import { useState, useEffect, useCallback } from 'react';
import { Product, Customer, Sale, CartItem, Order, Employee, Vehicle, PaymentSplit, ViewType, QualityRecord, Task, Attendance, TicketConfig, CloudConfig, SavedReport, FuelRecord } from '../types';
import { INITIAL_PRODUCTS, INITIAL_CUSTOMERS } from '../constants';

const DEFAULT_PERMISSIONS: ViewType[] = ['dashboard', 'pos', 'orders', 'customers', 'logistics', 'inventory', 'whatsapp', 'production', 'sync', 'reports', 'settings', 'employees', 'quality', 'scanner', 'tickets'];

const INITIAL_TICKET_CONFIG: TicketConfig = {
  businessName: 'AQUA+ FUNDADORES',
  rfc: 'AQUA900101-XXX',
  address: 'Calle del Agua #123, Col. Manantiales',
  phone: '33-1234-5678',
  footerMessage: '¡Gracias por tu preferencia! Frescura que hidrata tu vida.',
  website: 'www.aquafun.mx',
  socialMedia: '@aquafun_pro',
  extraNote: 'No hay cambios después de 24 horas.',
  logoUrl: 'data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 100 100%22><rect width=%22100%22 height=%22100%22 rx=%2225%22 fill=%22%230284c7%22/><path d=%22M50 20C50 20 30 45 30 60C30 71.0457 38.9543 80 50 80C61.0457 80 70 71.0457 70 60C70 45 50 20 50 20Z%22 fill=%22white%22/></svg>'
};

const INITIAL_CLOUD_CONFIG: CloudConfig = {
  url: 'https://aquamasfundadores-default-rtdb.firebaseio.com/',
  apiKey: 't8rzxkeWbMIKGufdW7RV1j1bKS0TKf2gPkgmZ36A',
  autoSync: true
};

export const useERPData = () => {
  const [products, setProducts] = useState<Product[]>(() => {
    const saved = localStorage.getItem('aqua_products');
    return saved ? JSON.parse(saved) : INITIAL_PRODUCTS;
  });

  const [customers, setCustomers] = useState<Customer[]>(() => {
    const saved = localStorage.getItem('aqua_customers');
    return saved ? JSON.parse(saved).map((c: any) => ({ ...c, balance: c.balance || 0 })) : INITIAL_CUSTOMERS;
  });

  const [ticketConfig, setTicketConfig] = useState<TicketConfig>(() => {
    const saved = localStorage.getItem('aqua_ticket_config');
    return saved ? JSON.parse(saved) : INITIAL_TICKET_CONFIG;
  });

  const [cloudConfig, setCloudConfig] = useState<CloudConfig>(() => {
    const saved = localStorage.getItem('aqua_cloud_config');
    if (saved) {
      const parsed = JSON.parse(saved);
      if (!parsed.url || parsed.url === '') {
        return INITIAL_CLOUD_CONFIG;
      }
      return parsed;
    }
    return INITIAL_CLOUD_CONFIG;
  });

  const [sales, setSales] = useState<Sale[]>(() => {
    const saved = localStorage.getItem('aqua_sales');
    return saved ? JSON.parse(saved) : [];
  });

  const [orders, setOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('aqua_orders');
    return saved ? JSON.parse(saved) : [];
  });

  const [employees, setEmployees] = useState<Employee[]>(() => {
    const saved = localStorage.getItem('aqua_employees');
    const initial = saved ? JSON.parse(saved) : [
      { id: 'admin', name: 'Gerente General', role: 'Administrador', phone: '3312345678', pin: '1234', permissions: [...DEFAULT_PERMISSIONS] }
    ];
    return initial;
  });

  useEffect(() => {
    setEmployees(prev => prev.map(e => 
      e.role === 'Administrador' 
        ? { ...e, permissions: [...DEFAULT_PERMISSIONS] } 
        : e
    ));
  }, []);

  const [vehicles, setVehicles] = useState<Vehicle[]>(() => {
    const saved = localStorage.getItem('aqua_vehicles');
    // Migration: ensure inventory and fuelHistory arrays exist
    const parsed = saved ? JSON.parse(saved) : [{ id: 'v1', plate: 'ABC-123', description: 'Nissan NP300', loadCapacity: 60, currentLoad: 0, inventory: [], fuelHistory: [] }];
    return parsed.map((v: any) => ({
        ...v,
        inventory: v.inventory || [],
        fuelHistory: v.fuelHistory || []
    }));
  });

  const [qualityRecords, setQualityRecords] = useState<QualityRecord[]>(() => {
    const saved = localStorage.getItem('aqua_quality');
    return saved ? JSON.parse(saved) : [];
  });

  const [tasks, setTasks] = useState<Task[]>(() => {
    const saved = localStorage.getItem('aqua_tasks');
    return saved ? JSON.parse(saved) : [];
  });

  const [attendance, setAttendance] = useState<Attendance[]>(() => {
    const saved = localStorage.getItem('aqua_attendance');
    return saved ? JSON.parse(saved) : [];
  });

  const [savedReports, setSavedReports] = useState<SavedReport[]>(() => {
    const saved = localStorage.getItem('aqua_saved_reports');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => {
    localStorage.setItem('aqua_products', JSON.stringify(products));
    localStorage.setItem('aqua_customers', JSON.stringify(customers));
    localStorage.setItem('aqua_sales', JSON.stringify(sales));
    localStorage.setItem('aqua_orders', JSON.stringify(orders));
    localStorage.setItem('aqua_employees', JSON.stringify(employees));
    localStorage.setItem('aqua_vehicles', JSON.stringify(vehicles));
    localStorage.setItem('aqua_ticket_config', JSON.stringify(ticketConfig));
    localStorage.setItem('aqua_quality', JSON.stringify(qualityRecords));
    localStorage.setItem('aqua_tasks', JSON.stringify(tasks));
    localStorage.setItem('aqua_attendance', JSON.stringify(attendance));
    localStorage.setItem('aqua_cloud_config', JSON.stringify(cloudConfig));
    localStorage.setItem('aqua_saved_reports', JSON.stringify(savedReports));
  }, [products, customers, sales, orders, employees, vehicles, ticketConfig, qualityRecords, tasks, attendance, cloudConfig, savedReports]);

  // Helper para fecha local ISO YYYY-MM-DD
  const getLocalDateISO = () => {
    const d = new Date();
    const offset = d.getTimezoneOffset() * 60000;
    return new Date(d.getTime() - offset).toISOString().split('T')[0];
  };

  const addSale = (
    customerId: string, 
    items: CartItem[], 
    total: number, 
    paidAmount: number, 
    splits: PaymentSplit[], 
    returnedVacios: number, 
    manualTimestamp?: number,
    vehicleId?: string // New optional parameter
  ) => {
    const debtAmount = Math.max(0, total - paidAmount);
    const newSale: Sale = {
      id: `TKT-${Date.now().toString().slice(-6)}`,
      timestamp: manualTimestamp || Date.now(),
      customerId,
      customerAlias: customers.find(c => c.id === customerId)?.alias || 'Anonimo',
      items,
      total,
      paidAmount,
      change: Math.max(0, paidAmount - total),
      paymentSplits: splits,
      emptyGarrafonsReturned: returnedVacios,
      synced: false
    };

    setSales(prev => [newSale, ...prev]);
    setCustomers(prev => prev.map(c => c.id === customerId ? { ...c, balance: (c.balance || 0) + debtAmount } : c));

    // Logic to deduct inventory
    if (vehicleId && vehicleId !== 'plant') {
      // Deduct from specific vehicle
      setVehicles(prev => prev.map(v => {
        if (v.id !== vehicleId) return v;

        let currentInventory = [...(v.inventory || [])];

        items.forEach(soldItem => {
          const idx = currentInventory.findIndex(inv => inv.id === soldItem.id);
          if (idx !== -1) {
            // Reduce quantity
            const newQty = Math.max(0, currentInventory[idx].quantity - soldItem.quantity);
            if (newQty === 0) {
               currentInventory.splice(idx, 1);
            } else {
               currentInventory[idx] = { ...currentInventory[idx], quantity: newQty };
            }
          }
        });

        const newLoad = currentInventory.reduce((acc, i) => acc + (i.quantity || 0), 0);
        return { ...v, inventory: currentInventory, currentLoad: newLoad };
      }));
    } else {
      // Deduct from Plant (Default)
      setProducts(prev => prev.map(p => {
        const cartItem = items.find(item => item.id === p.id);
        return cartItem ? { ...p, stock: p.stock - cartItem.quantity } : p;
      }));
    }

    return newSale;
  };

  const resetSales = () => {
    setSales([]);
    alert("Todas las ventas han sido eliminadas. El historial está limpio.");
  };

  const syncData = useCallback((externalData: any) => {
    if (!externalData) return false;
    let changesMade = false;

    if (externalData.sales) {
      setSales(prev => {
        const existingIds = new Set(prev.map(s => s.id));
        const newSales = (externalData.sales as Sale[]).filter(s => !existingIds.has(s.id));
        if (newSales.length > 0) changesMade = true;
        return [...newSales, ...prev].sort((a, b) => b.timestamp - a.timestamp);
      });
    }

    if (externalData.customers) {
      setCustomers(prev => {
        const existingMap = new Map(prev.map(c => [c.id, c]));
        (externalData.customers as Customer[]).forEach(c => {
          if (JSON.stringify(existingMap.get(c.id)) !== JSON.stringify(c)) {
             existingMap.set(c.id, c);
             changesMade = true;
           }
        });
        return Array.from(existingMap.values());
      });
    }

    if (externalData.products) {
      setProducts(prev => {
        const existingMap = new Map(prev.map(p => [p.id, p]));
        (externalData.products as Product[]).forEach(p => {
           if (JSON.stringify(existingMap.get(p.id)) !== JSON.stringify(p)) {
             existingMap.set(p.id, p);
             changesMade = true;
           }
        });
        return Array.from(existingMap.values());
      });
    }

    return changesMade;
  }, []);

  const importCustomers = useCallback((newCustomers: Customer[]) => {
    setCustomers(prev => {
      const existingIds = new Set(prev.map(c => c.id));
      const filteredNew = newCustomers.filter(c => !existingIds.has(c.id));
      return [...prev, ...filteredNew];
    });
  }, []);

  const loadVehicle = (vehicleId: string, product: Product, delta: number) => {
    if (!product || !product.id) return;

    const currentProduct = products.find(p => p.id === product.id);
    if (!currentProduct) return;

    if (delta > 0 && currentProduct.stock < delta) {
        alert("Stock insuficiente en planta.");
        return;
    }

    setVehicles(prev => prev.map(v => {
        if (v.id !== vehicleId) return v;

        const newInventory = Array.isArray(v.inventory) ? [...v.inventory] : [];
        const existingItemIndex = newInventory.findIndex(i => i.id === product.id);

        if (existingItemIndex > -1) {
            const newQty = newInventory[existingItemIndex].quantity + delta;
            if (newQty <= 0) {
                newInventory.splice(existingItemIndex, 1);
            } else {
                newInventory[existingItemIndex] = { ...newInventory[existingItemIndex], quantity: newQty };
            }
        } else if (delta > 0) {
            newInventory.push({ ...product, quantity: delta });
        }

        const newLoad = newInventory.reduce((acc, item) => acc + (item.quantity || 0), 0);

        return { ...v, inventory: newInventory, currentLoad: newLoad };
    }));

    setProducts(prev => prev.map(p => {
        if (p.id === product.id) {
            return { ...p, stock: p.stock - delta };
        }
        return p;
    }));
  };

  const addFuelRecord = (vehicleId: string, record: FuelRecord) => {
    setVehicles(prev => prev.map(v => {
      if (v.id !== vehicleId) return v;
      return { 
        ...v, 
        fuelHistory: [record, ...(v.fuelHistory || [])] 
      };
    }));
  };

  return { 
    products, 
    saveProduct: (p: Product) => setProducts(prev => prev.find(x => x.id === p.id) ? prev.map(x => x.id === p.id ? p : x) : [...prev, p]),
    deleteProduct: (id: string) => setProducts(prev => prev.filter(p => p.id !== id)),
    customers, 
    saveCustomer: (c: Customer) => setCustomers(prev => prev.find(x => x.id === c.id) ? prev.map(x => x.id === c.id ? c : x) : [...prev, c]),
    deleteCustomer: (id: string) => setCustomers(prev => prev.filter(c => c.id !== id)),
    importCustomers,
    sales, addSale, resetSales,
    orders, 
    setOrders,
    addOrder: (o: Partial<Order>) => {
      const newOrder: Order = {
        id: `ORD-${Date.now().toString().slice(-6)}`,
        timestamp: Date.now(),
        status: 'pendiente',
        priority: 1,
        items: [],
        total: 0,
        customerId: '',
        customerAlias: '',
        ...o
      } as Order;
      setOrders(prev => [newOrder, ...prev]);
    },
    updateOrder: (o: Order) => setOrders(prev => prev.map(item => item.id === o.id ? o : item)),
    employees, 
    saveEmployee: (e: Employee) => setEmployees(prev => prev.find(x => x.id === e.id) ? prev.map(x => x.id === e.id ? e : x) : [...prev, e]),
    vehicles, 
    setVehicles,
    loadVehicle,
    deleteVehicle: (id: string) => setVehicles(prev => prev.filter(v => v.id !== id)),
    addFuelRecord,
    tasks,
    addTask: (t: Partial<Task>) => {
      const newTask: Task = {
        id: `TSK-${Date.now().toString().slice(-4)}`,
        timestamp: Date.now(),
        status: 'pendiente',
        ...t
      } as Task;
      setTasks(prev => [newTask, ...prev]);
    },
    updateTaskStatus: (id: string, status: Task['status']) => setTasks(prev => prev.map(t => t.id === id ? { ...t, status } : t)),
    deleteTask: (id: string) => setTasks(prev => prev.filter(t => t.id !== id)),
    clearTasksByDate: (date: string) => setTasks(prev => prev.filter(t => t.date !== date)),
    attendance,
    recordAttendance: (employeeId: string, status: Attendance['status']) => {
      const date = getLocalDateISO();
      setAttendance(prev => {
        const filtered = prev.filter(a => !(a.employeeId === employeeId && a.date === date));
        return [{ id: `ATT-${Date.now()}`, employeeId, status, date, timestamp: Date.now() }, ...filtered];
      });
    },
    qualityRecords,
    addQualityRecord: (r: Partial<QualityRecord>) => {
      const newRecord: QualityRecord = {
        id: `QUAL-${Date.now().toString().slice(-4)}`,
        timestamp: Date.now(),
        employeeId: 'admin',
        ...r
      } as QualityRecord;
      setQualityRecords(prev => [newRecord, ...prev]);
    },
    ticketConfig, setTicketConfig,
    cloudConfig, setCloudConfig,
    syncData,
    savedReports,
    addSavedReport: (r: SavedReport) => setSavedReports(prev => [r, ...prev]),
    deleteSavedReport: (id: string) => setSavedReports(prev => prev.filter(r => r.id !== id)),
  };
};

