import { PDFDocument, StandardFonts, rgb } from 'pdf-lib';

async function generarTicketPDF(venta) {
  // Crear nuevo documento PDF
  const pdfDoc = await PDFDocument.create();
  const page = pdfDoc.addPage([300, 600]); // Ancho, Alto en puntos

  // Obtener fuentes
  const helveticaFont = await pdfDoc.embedFont(StandardFonts.Helvetica);
  const helveticaBold = await pdfDoc.embedFont(StandardFonts.HelveticaBold);

  const { width, height } = page.getSize();
  let yPos = height - 30;

  // Encabezado
  page.drawText('MI NEGOCIO', {
    x: 150,
    y: yPos,
    size: 14,
    font: helveticaBold,
    color: rgb(0, 0, 0),
    align: 'center',
  });
  yPos -= 20;

  page.drawText(`Ticket: ${venta.folio}`, {
    x: 20,
    y: yPos,
    size: 10,
    font: helveticaFont,
  });
  yPos -= 15;

  page.drawText(`Fecha: ${new Date().toLocaleString()}`, {
    x: 20,
    y: yPos,
    size: 10,
    font: helveticaFont,
  });
  yPos -= 20;

  // Línea separadora
  page.drawLine({
    start: { x: 20, y: yPos },
    end: { x: 280, y: yPos },
    thickness: 1,
    color: rgb(0, 0, 0),
  });
  yPos -= 20;

  // Encabezados de tabla
  page.drawText('Cant.', { x: 20, y: yPos, size: 10, font: helveticaBold });
  page.drawText('Descripción', { x: 60, y: yPos, size: 10, font: helveticaBold });
  page.drawText('Total', { x: 230, y: yPos, size: 10, font: helveticaBold });
  yPos -= 15;

  // Productos
  venta.productos.forEach(producto => {
    page.drawText(producto.cantidad.toString(), { 
      x: 20, y: yPos, size: 9, font: helveticaFont 
    });
    page.drawText(producto.nombre, { 
      x: 60, y: yPos, size: 9, font: helveticaFont 
    });
    page.drawText(`$${producto.total.toFixed(2)}`, { 
      x: 230, y: yPos, size: 9, font: helveticaFont 
    });
    yPos -= 12;
  });

  yPos -= 10;

  // Totales
  page.drawText(`Subtotal: $${venta.subtotal.toFixed(2)}`, {
    x: 280,
    y: yPos,
    size: 10,
    font: helveticaFont,
    align: 'right',
  });
  yPos -= 15;

  page.drawText(`IVA: $${venta.iva.toFixed(2)}`, {
    x: 280,
    y: yPos,
    size: 10,
    font: helveticaFont,
    align: 'right',
  });
  yPos -= 15;

  page.drawText(`TOTAL: $${venta.total.toFixed(2)}`, {
    x: 280,
    y: yPos,
    size: 12,
    font: helveticaBold,
    align: 'right',
  });

  // Guardar PDF
  const pdfBytes = await pdfDoc.save();

  // Crear Blob y descargar
  const blob = new Blob([pdfBytes], { type: 'application/pdf' });
  const url = URL.createObjectURL(blob);

  return {
    blob,
    url,
    nombreArchivo: `ticket_${venta.folio}.pdf`
  };
}


