  }

  // Return the Data URL string to be used in an iframe
  return doc.output('datauristring');
};

/**
 * Generates a Ticket PDF using pdf-lib and returns raw bytes
 */
export const generateTicketPDF = async (sale: Sale, config: TicketConfig): Promise<Uint8Array> => {
  // Crear nuevo documento PDF
  const pdfDoc = await PDFDocument.create();
  // Tamaño ticket (ancho ~10cm, alto ~21cm variable)
  const page = pdfDoc.addPage([300, 600]);

  // Obtener fuentes
  const helveticaFont = await pdfDoc.embedFont(StandardFonts.Helvetica);
  const helveticaBold = await pdfDoc.embedFont(StandardFonts.HelveticaBold);

  const { width, height } = page.getSize();
  let yPos = height - 30;

  const getTextWidth = (text: string, font: any, size: number) => font.widthOfTextAtSize(text, size);

  // Encabezado
  const headerText = config.businessName || 'MI NEGOCIO';
  const headerWidth = getTextWidth(headerText, helveticaBold, 14);
  page.drawText(headerText, {
    x: (width - headerWidth) / 2,
    y: yPos,
    size: 14,
    font: helveticaBold,
    color: rgb(0, 0, 0),
  });
  yPos -= 20;

  page.drawText(`Ticket: ${sale.id}`, { x: 20, y: yPos, size: 10, font: helveticaFont });
  yPos -= 15;

  page.drawText(`Fecha: ${new Date(sale.timestamp).toLocaleString()}`, { x: 20, y: yPos, size: 10, font: helveticaFont });
  yPos -= 20;

  // Línea separadora
  page.drawLine({
    start: { x: 20, y: yPos },
    end: { x: 280, y: yPos },
    thickness: 1,
    color: rgb(0, 0, 0),
  });
  yPos -= 20;

  // Encabezados de tabla
  page.drawText('Cant.', { x: 20, y: yPos, size: 10, font: helveticaBold });
  page.drawText('Descripción', { x: 60, y: yPos, size: 10, font: helveticaBold });

  const totalHeader = 'Total';
  const totalHeaderWidth = getTextWidth(totalHeader, helveticaBold, 10);
  page.drawText(totalHeader, { x: 280 - totalHeaderWidth, y: yPos, size: 10, font: helveticaBold });
  yPos -= 15;

  // Productos
  sale.items.forEach(producto => {
    page.drawText(producto.quantity.toString(), { 
      x: 20, y: yPos, size: 9, font: helveticaFont 
    });

    // Truncar nombre si es muy largo
    const name = producto.name.length > 25 ? producto.name.substring(0, 25) + '...' : producto.name;
    page.drawText(name, { 
      x: 60, y: yPos, size: 9, font: helveticaFont 
    });

    const totalStr = `$${(producto.quantity * producto.price).toFixed(2)}`;
    const totalWidth = getTextWidth(totalStr, helveticaFont, 9);

    page.drawText(totalStr, { 
      x: 280 - totalWidth, y: yPos, size: 9, font: helveticaFont 
    });
    yPos -= 12;
  });

  yPos -= 10;

  // Totales Helper
  const drawRightAligned = (label: string, value: string, font: any, size: number) => {
      const text = `${label} ${value}`;
      const textWidth = getTextWidth(text, font, size);
      page.drawText(text, { x: 280 - textWidth, y: yPos, size, font });
      yPos -= 15;
  };

  drawRightAligned('Total:', `$${sale.total.toFixed(2)}`, helveticaBold, 12);
  drawRightAligned('Pago:', `$${sale.paidAmount.toFixed(2)}`, helveticaFont, 10);

  if (sale.change > 0) {
    drawRightAligned('Cambio:', `$${sale.change.toFixed(2)}`, helveticaFont, 10);
  } else if (sale.paidAmount < sale.total) {
    drawRightAligned('Pendiente:', `$${(sale.total - sale.paidAmount).toFixed(2)}`, helveticaFont, 10);
  }

  // Footer Message
  if (config.footerMessage) {
      yPos -= 10;
      const footerW = getTextWidth(config.footerMessage, helveticaFont, 8);
      page.drawText(config.footerMessage, { x: (width - footerW) / 2, y: yPos, size: 8, font: helveticaFont, color: rgb(0.5, 0.5, 0.5) });
  }

  // Retornar bytes sin procesar
  return await pdfDoc.save();
}

import React, { useState, useEffect } from 'react';
