import React, { useState, useRef } from 'react';
import { Customer, GarrafonType } from '../types';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';
import { Filesystem, Directory, Encoding } from '@capacitor/filesystem';

const GARRAFON_TYPES: { type: GarrafonType, color: string }[] = [
  { type: 'Aqua', color: 'bg-blue-500' },
  { type: 'Bonafont', color: 'bg-orange-500' },
  { type: 'Ciel', color: 'bg-sky-400' },
  { type: 'E-Pura', color: 'bg-red-500' },
  { type: 'Generico', color: 'bg-slate-400' }
];

export const CustomersModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const { customers, saveCustomer, deleteCustomer, sales, importCustomers } = useERPData();
  const [search, setSearch] = useState('');
  const [editingCustomer, setEditingCustomer] = useState<Partial<Customer> | null>(null);
  const [viewingHistory, setViewingHistory] = useState<Customer | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const filteredCustomers = customers.filter(c => 
    c.name.toLowerCase().includes(search.toLowerCase()) || 
    c.alias.toLowerCase().includes(search.toLowerCase())
  );

  // --- LÓGICA DE NAVEGACIÓN INTELIGENTE ---
  const handleBackNavigation = () => {
    if (editingCustomer || viewingHistory) {
      setEditingCustomer(null);
      setViewingHistory(null);
    } else {
      onBack();
    }
  };

  const handleSave = () => {
    if (!editingCustomer?.name || !editingCustomer?.alias) {
      alert("Nombre y Alias son obligatorios.");
      return;
    }
    const customerToSave: Customer = {
      id: editingCustomer.id || Math.random().toString(36).substr(2, 9),
      name: editingCustomer.name,
      alias: editingCustomer.alias,
      phone: editingCustomer.phone || '',
      address: editingCustomer.address || '',
      specialPrice: editingCustomer.specialPrice || undefined,
      garrafonType: editingCustomer.garrafonType || 'Generico',
      balance: editingCustomer.balance || 0,
      lat: editingCustomer.lat,
      lng: editingCustomer.lng,
    };
    saveCustomer(customerToSave);
    setEditingCustomer(null);
  };

  const handleDelete = () => {
    if (!editingCustomer?.id) return;
    const confirmDelete = window.confirm(
      `¿Estás seguro de eliminar a "${editingCustomer.alias}"?\n\nEsta acción eliminará el registro del cliente permanentemente. Su historial de ventas se mantendrá como anónimo.`
    );
    if (confirmDelete) {
      deleteCustomer(editingCustomer.id);
      setEditingCustomer(null);
    }
  };

  const handleGetLocation = () => {
    if (!navigator.geolocation) {
      alert("Tu dispositivo no soporta geolocalización.");
      return;
    }

    const btn = document.getElementById('gps-btn');
    if(btn) {
       btn.innerHTML = '<i class="fas fa-circle-notch animate-spin"></i> Obteniendo...';
       btn.classList.add('opacity-50', 'pointer-events-none');
    }

    const onSuccess = (position: GeolocationPosition) => {
        setEditingCustomer(prev => prev ? ({
          ...prev,
          lat: position.coords.latitude,
          lng: position.coords.longitude
        }) : null);

        if(btn) {
          btn.innerHTML = '<i class="fas fa-check"></i> Ubicación Capturada';
          btn.classList.remove('opacity-50', 'pointer-events-none', 'bg-emerald-50', 'text-emerald-600');
          btn.classList.add('bg-emerald-50', 'text-white');
          setTimeout(() => {
             btn.innerHTML = '<i class="fas fa-location-crosshairs"></i> Actualizar GPS';
             btn.classList.remove('bg-emerald-500', 'text-white');
             btn.classList.add('bg-emerald-50', 'text-emerald-600');
          }, 3000);
        }
    };

    const onError = (error: GeolocationPositionError) => {
        console.error("GPS Error:", error);
        if(btn) {
          btn.innerHTML = '<i class="fas fa-triangle-exclamation"></i> Reintentar';
          btn.classList.remove('opacity-50', 'pointer-events-none');
        }
        alert(`No se pudo obtener la ubicación precise (Error ${error.code}). Verifica que el GPS esté encendido.`);
    };

    // Intento 1: Alta Precisión
    navigator.geolocation.getCurrentPosition(
      onSuccess,
      () => {
        console.warn("High accuracy failed, trying low accuracy...");
        // Intento 2: Baja Precisión (Fallback)
        navigator.geolocation.getCurrentPosition(onSuccess, onError, { 
            enableHighAccuracy: false, 
            timeout: 10000, 
            maximumAge: 0 
        });
      },
      { enableHighAccuracy: true, timeout: 5000, maximumAge: 0 }
    );
  };

  const openGoogleMaps = (lat?: number, lng?: number) => {
    if (lat && lng) {
      window.open(`https://www.google.com/maps/search/?api=1&query=${lat},${lng}`, '_blank');
    } else {
      alert("Este cliente no tiene ubicación registrada.");
    }
  };

  // --- LOGICA DE EXPORTACIÓN E IMPORTACIÓN ---

  const handleExportCSV = async () => {
    const headers = ["ID", "Nombre", "Alias", "Telefono", "Direccion", "Saldo", "Precio Especial", "Tipo Garrafon", "Lat", "Lng"];
    const rows = customers.map(c => [
      c.id,
      `"${c.name}"`,
      `"${c.alias}"`,
      c.phone || '',
      `"${c.address || ''}"`,
      c.balance,
      c.specialPrice || '',
      c.garrafonType || 'Generico',
      c.lat || '',
      c.lng || ''
    ]);
    const csvContent = [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
    const fileName = `Clientes_Aqua_${new Date().getTime()}.csv`;

    try {
        // Intento 1: Guardar en Sistema de Archivos (Android/iOS)
        await Filesystem.writeFile({
            path: fileName,
            data: csvContent,
            directory: Directory.Documents,
            encoding: Encoding.UTF8
        });
        alert('Archivo CSV guardado exitosamente en la carpeta "Documentos" de tu dispositivo.');
    } catch (e) {
        console.warn("Filesystem write failed, falling back to browser download", e);

        // Intento 2: Descarga Web Clásica (Fallback)
        const blob = new Blob([csvContent], { type: 'text/csv' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = fileName;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    }
  };

  // --- NUEVA FUNCIÓN: IMPORTAR CONTACTOS DEL TELÉFONO ---
  const handleImportContacts = async () => {
    const nav = navigator as any;

    // Verificar soporte de la API de Selección de Contactos (Chrome Android / PWA)
    if ('contacts' in nav && 'select' in nav.contacts) {
      try {
        const props = ['name', 'tel', 'address'];
        const opts = { multiple: true };

        const contacts = await nav.contacts.select(props, opts);

        if (contacts.length > 0) {
           const newCustomers: Customer[] = contacts.map((c: any) => ({
             id: Math.random().toString(36).substr(2, 9),
             name: c.name[0] || 'Desconocido',
             alias: c.name[0] || 'Desconocido',
             phone: c.tel ? c.tel[0] : '',
             address: c.address ? c.address[0]?.addressLine : '',
             balance: 0,
             garrafonType: 'Generico'
           }));

           importCustomers(newCustomers);
           alert(`Se importaron ${newCustomers.length} contactos exitosamente.`);
        }
      } catch (ex) {
        // El usuario canceló o hubo error
        console.log("Importación cancelada o fallida:", ex);
      }
    } else {
      // Fallback: Explicar
      alert("Tu dispositivo no soporta la selección directa de contactos. Por favor usa la opción de 'Importar CSV' o agrega manualmente.");
    }
  };

  const handleImportFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      if (!text) return;

      try {
        let importedCount = 0;
        const newCustomers: Customer[] = [];

        if (file.name.toLowerCase().endsWith('.csv')) {
          const lines = text.replace(/\r\n/g, '\n').replace(/\r/g, '\n').split('\n');
          if (lines.length > 0) {
            const headerLine = lines[0].toLowerCase();
            const headers = headerLine.split(',').map(h => h.trim().replace(/^"|"$/g, ''));

            const idxNombre = headers.findIndex(h => h.includes('nombre'));
            const idxAlias = headers.findIndex(h => h.includes('alias') || h.includes('comercial'));
            const idxTelefono = headers.findIndex(h => h.includes('telefono') || h.includes('celular') || h.includes('whatsapp'));
            const idxDireccion = headers.findIndex(h => h.includes('direccion') || h.includes('domicilio'));
            const idxSaldo = headers.findIndex(h => h.includes('saldo'));
            const idxPrecio = headers.findIndex(h => h.includes('precio'));

            lines.slice(1).forEach(line => {
              if (!line.trim()) return;
              const cols = line.split(',').map(c => c.replace(/^"|"$/g, '').trim());
              const finalName = (idxNombre !== -1 ? cols[idxNombre] : '') || (idxAlias !== -1 ? cols[idxAlias] : '') || 'Importado';
              const finalAlias = (idxAlias !== -1 ? cols[idxAlias] : '') || finalName;

              if (finalAlias) {
                newCustomers.push({
                  id: Math.random().toString(36).substr(2, 9),
                  name: finalName,
                  alias: finalAlias,
                  phone: idxTelefono !== -1 ? cols[idxTelefono] : '',
                  address: idxDireccion !== -1 ? cols[idxDireccion] : '',
                  balance: idxSaldo !== -1 ? (parseFloat(cols[idxSaldo]) || 0) : 0,
                  specialPrice: idxPrecio !== -1 ? (parseFloat(cols[idxPrecio]) || undefined) : undefined,
                  garrafonType: 'Generico',
                });
                importedCount++;
              }
            });
          }
        }

        if (importedCount > 0) {
          importCustomers(newCustomers);
          alert(`¡Éxito! Se importaron ${importedCount} clientes.`);
        } else {
          alert("No se encontraron datos válidos en el CSV.");
        }
      } catch (err) {
        alert("Error al procesar el archivo.");
      }
      if (fileInputRef.current) fileInputRef.current.value = '';
    };
    reader.readAsText(file);
  };

  // --- UI RENDER ---

  if (viewingHistory) {
    const customerSales = sales.filter(s => s.customerId === viewingHistory.id);
    const hasDebt = viewingHistory.balance > 0;
    const hasCredit = viewingHistory.balance < 0;

    return (
      <div className="h-full bg-sky-50 overflow-y-auto no-scrollbar pb-24">
        <ModuleHeader title={`Perfil: ${viewingHistory.alias}`} onBack={handleBackNavigation} />
        <div className="px-6 space-y-4">
          <RoundedCard className={`${hasDebt ? 'bg-red-500' : hasCredit ? 'bg-emerald-500' : 'bg-sky-600'} text-white shadow-lg border-none transition-colors duration-500`}>
             <div className="flex justify-between items-center">
                <div>
                   <span className="text-[10px] font-black uppercase opacity-70">
                     {hasDebt ? 'Estado: Adeudo' : hasCredit ? 'Estado: Saldo a Favor' : 'Estado: Al Corriente'}
                   </span>
                   <p className="text-3xl font-black">
                     ${Math.abs(viewingHistory.balance).toLocaleString()}
                   </p>
                </div>
                <div className="bg-white/20 p-4 rounded-2xl">
                   <i className={`fas ${hasDebt ? 'fa-hand-holding-dollar' : 'fa-piggy-bank'} text-2xl`}></i>
                </div>
             </div>
          </RoundedCard>

          {viewingHistory.address && (
            <div className="bg-white p-5 rounded-3xl shadow-sm border border-sky-50 flex items-start gap-3">
              <i className="fas fa-map-location-dot text-sky-300 mt-1"></i>
              <div>
                 <span className="text-[9px] font-black text-sky-400 uppercase block mb-1">Dirección Registrada</span>
                 <p className="text-sm font-bold text-sky-900 leading-tight">{viewingHistory.address}</p>
              </div>
            </div>
          )}

          <div className="grid grid-cols-2 gap-3">
             <div className="bg-white p-4 rounded-3xl shadow-sm border border-sky-50">
                <span className="text-[9px] font-black text-sky-400 uppercase block mb-1">WhatsApp</span>
                <p className="text-xs font-bold text-sky-900">{viewingHistory.phone || 'No registrado'}</p>
             </div>
             <div className="bg-white p-4 rounded-3xl shadow-sm border border-sky-50">
                <span className="text-[9px] font-black text-sky-400 uppercase block mb-1">Precio Esp.</span>
                <p className="text-xs font-bold text-sky-900">{viewingHistory.specialPrice ? `$${viewingHistory.specialPrice}` : 'Precio Base'}</p>
             </div>
          </div>

          <h4 className="text-[10px] font-black uppercase text-sky-400 tracking-widest px-2 mt-4">Transacciones Recientes</h4>
          {customerSales.length === 0 ? (
            <div className="text-center py-20 text-sky-300 italic animate-fadeIn">Sin compras registradas aún.</div>
          ) : (
            customerSales.map(s => (
              <RoundedCard key={s.id} className="py-5 border-none shadow-sm animate-fadeIn">
                <div className="flex justify-between items-start mb-3">
                  <div>
                    <span className="text-sky-900 font-black">{s.id}</span>
                    <p className="text-[10px] text-sky-400 font-bold uppercase">{new Date(s.timestamp).toLocaleDateString()}</p>
                  </div>
                  <span className="font-black text-sky-600 text-xl">${s.total}</span>
                </div>
                <div className="flex flex-wrap gap-2">
                  {s.items.map(i => <span key={i.id} className="bg-sky-50 text-sky-600 text-[8px] px-3 py-1 rounded-full font-black uppercase">{i.quantity}x {i.name}</span>)}
                </div>
              </RoundedCard>
            ))
          )}
        </div>
      </div>
    );
  }

  if (editingCustomer) {
    return (
      <div className="h-full bg-sky-50 overflow-y-auto no-scrollbar pb-32">
        <ModuleHeader title={editingCustomer.id ? "Editar Perfil" : "Nuevo Cliente"} onBack={handleBackNavigation} />
        <div className="px-6 space-y-5">
          <div className="space-y-4">
            <div>
               <label className="text-[10px] font-black text-sky-400 uppercase ml-3 mb-1 block">Nombre Comercial / Alias</label>
               <input className="w-full bg-white p-5 rounded-[2rem] outline-none shadow-sm font-bold text-sky-900 focus:ring-2 ring-sky-300 transition-all" placeholder="Ej: Doña Mary" value={editingCustomer.alias || ''} onChange={e => setEditingCustomer({...editingCustomer, alias: e.target.value})}/>
            </div>
            <div>
               <label className="text-[10px] font-black text-sky-400 uppercase ml-3 mb-1 block">Nombre Legal</label>
               <input className="w-full bg-white p-5 rounded-[2rem] outline-none shadow-sm text-sky-900 focus:ring-2 ring-sky-300 transition-all" placeholder="Ej: María de los Angeles" value={editingCustomer.name || ''} onChange={e => setEditingCustomer({...editingCustomer, name: e.target.value})}/>
            </div>
            <div>
               <label className="text-[10px] font-black text-sky-400 uppercase ml-3 mb-1 block">WhatsApp</label>
               <input className="w-full bg-white p-5 rounded-[2rem] outline-none shadow-sm text-sky-900 focus:ring-2 ring-sky-300 transition-all" placeholder="33..." value={editingCustomer.phone || ''} onChange={e => setEditingCustomer({...editingCustomer, phone: e.target.value})}/>
            </div>
            <div>
               <label className="text-[10px] font-black text-sky-400 uppercase ml-3 mb-1 block">Dirección / Domicilio</label>
               <input className="w-full bg-white p-5 rounded-[2rem] outline-none shadow-sm text-sky-900 focus:ring-2 ring-sky-300 transition-all" placeholder="Calle, Número, Colonia..." value={editingCustomer.address || ''} onChange={e => setEditingCustomer({...editingCustomer, address: e.target.value})}/>
            </div>

            {/* Sección de Geolocalización */}
            <div>
               <label className="text-[10px] font-black text-sky-400 uppercase ml-3 mb-1 block">Ubicación de Entrega</label>
               <div className="flex gap-2">
                 <button 
                   id="gps-btn"
                   onClick={handleGetLocation} 
                   className="flex-1 bg-emerald-50 text-emerald-600 p-4 rounded-[2rem] font-bold text-[10px] uppercase flex items-center justify-center gap-2 border border-emerald-100 shadow-sm active:scale-95 transition-all"
                 >
                   <i className="fas fa-location-crosshairs"></i> GPS Actual
                 </button>
                 {editingCustomer?.lat && (
                   <button 
                     onClick={() => openGoogleMaps(editingCustomer.lat, editingCustomer.lng)} 
                     className="w-14 bg-sky-50 text-sky-500 rounded-[1.5rem] flex items-center justify-center text-lg active:scale-90 transition-transform shadow-sm"
                   >
                     <i className="fas fa-map-location-dot text-red-500"></i>
                   </button>
                 )}
               </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                 <label className="text-[10px] font-black text-sky-400 uppercase ml-3 mb-1 block">Precio Especial</label>
                 <input type="number" className="w-full bg-white p-5 rounded-[2rem] outline-none shadow-sm font-black text-sky-600 text-xl focus:ring-2 ring-sky-300" placeholder="0.00" value={editingCustomer.specialPrice || ''} onChange={e => setEditingCustomer({...editingCustomer, specialPrice: Number(e.target.value)})}/>
              </div>
              <div>
                 <label className="text-[10px] font-black text-sky-400 uppercase ml-3 mb-1 block">Saldo (Deuda)</label>
                 <input type="number" className="w-full bg-white p-5 rounded-[2rem] outline-none shadow-sm font-black text-sky-900 text-xl focus:ring-2 ring-sky-300" placeholder="0.00" value={editingCustomer.balance || ''} onChange={e => setEditingCustomer({...editingCustomer, balance: Number(e.target.value)})}/>
              </div>
            </div>
          </div>

          <div className="pt-4 space-y-3">
             <ActionButton onClick={handleSave}>Guardar Cliente</ActionButton>

             {editingCustomer.id && (
               <button 
                 onClick={handleDelete}
                 className="w-full py-4 text-rose-500 font-black uppercase text-[10px] tracking-widest bg-rose-50 rounded-[2rem] active:scale-95 transition-all border border-rose-100 shadow-sm hover:bg-rose-100"
               >
                 <i className="fas fa-trash-can mr-2"></i> Eliminar Cliente
               </button>
             )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="h-full bg-sky-50 overflow-y-auto no-scrollbar pb-24">
      <ModuleHeader title="Directorio" onBack={handleBackNavigation} />
      <div className="px-6 space-y-4">

        {/* PANEL DE HERRAMIENTAS DE DATOS */}
        <div className="bg-indigo-600 rounded-[2.5rem] p-6 text-white shadow-lg shadow-indigo-200">
          <div className="flex justify-between items-center mb-4">
            <h4 className="text-sm font-black uppercase tracking-tight">Base de Datos</h4>
            <i className="fas fa-database opacity-50"></i>
          </div>
          <div className="grid grid-cols-3 gap-2">
            <button onClick={handleImportContacts} className="bg-white/10 hover:bg-white/20 p-3 rounded-2xl flex flex-col items-center gap-2 transition-colors">
               <i className="fas fa-mobile-screen-button text-xl"></i>
               <span className="text-[8px] font-bold uppercase text-center">Desde Agenda</span>
            </button>
            <button onClick={handleExportCSV} className="bg-white/10 hover:bg-white/20 p-3 rounded-2xl flex flex-col items-center gap-2 transition-colors">
               <i className="fas fa-file-export text-xl"></i>
               <span className="text-[8px] font-bold uppercase text-center">Exportar CSV</span>
            </button>
            <label className="bg-white/10 hover:bg-white/20 p-3 rounded-2xl flex flex-col items-center gap-2 transition-colors cursor-pointer relative">
               <i className="fas fa-file-import text-xl"></i>
               <span className="text-[8px] font-bold uppercase text-center">Importar CSV</span>
               <input 
                 type="file" 
                 ref={fileInputRef}
                 accept=".csv" 
                 className="absolute inset-0 opacity-0 cursor-pointer"
                 onChange={handleImportFile}
               />
            </label>
          </div>
        </div>

        <div className="relative">
          <input type="text" placeholder="Buscar por alias o teléfono..." className="w-full bg-white p-5 rounded-[2rem] outline-none shadow-sm focus:ring-2 ring-sky-300 font-medium" value={search} onChange={e => setSearch(e.target.value)}/>
          <i className="fas fa-search absolute right-6 top-1/2 -translate-y-1/2 text-sky-200"></i>
        </div>

        <div className="space-y-3">
          {filteredCustomers.map(c => (
            <RoundedCard key={c.id} className="py-5 border-none shadow-sm group hover:shadow-md transition-all active:scale-[0.98]">
              <div className="flex justify-between items-center">
                <div className="flex gap-4 items-center flex-1" onClick={() => setViewingHistory(c)}>
                  <div className={`w-14 h-14 rounded-3xl flex items-center justify-center text-white font-black text-xl shadow-lg transition-transform group-active:scale-90 ${GARRAFON_TYPES.find(g => g.type === c.garrafonType)?.color || 'bg-slate-400'}`}>
                    {c.alias ? c.alias.charAt(0).toUpperCase() : '?'}
                  </div>
                  <div>
                    <h4 className="font-black text-sky-900 leading-tight">{c.alias}</h4>
                    <div className="flex gap-2 mt-1 flex-wrap">
                      {c.address && (
                         <span className="bg-violet-100 text-violet-600 text-[8px] font-black px-2 py-0.5 rounded-full uppercase flex items-center gap-1">
                           <i className="fas fa-map-pin text-[8px]"></i> {c.address.slice(0, 10)}...
                         </span>
                      )}
                      {c.balance > 0 && (
                        <span className="bg-red-100 text-red-600 text-[8px] font-black px-2 py-0.5 rounded-full uppercase border border-red-200">
                          Adeudo: ${c.balance}
                        </span>
                      )}
                    </div>
                  </div>
                </div>
                <div className="flex gap-1">
                  <button onClick={() => setViewingHistory(c)} className="w-10 h-10 bg-sky-50 text-sky-500 rounded-xl flex items-center justify-center text-sm active:bg-sky-200 transition-colors"><i className="fas fa-eye"></i></button>
                  <button onClick={() => setEditingCustomer(c)} className="w-10 h-10 bg-sky-50 text-sky-500 rounded-xl flex items-center justify-center text-sm active:bg-sky-200 transition-colors"><i className="fas fa-pen"></i></button>
                  <a href={`https://wa.me/52${c.phone}`} className="w-10 h-10 bg-emerald-50 text-emerald-500 rounded-xl flex items-center justify-center text-sm active:bg-emerald-200 transition-colors"><i className="fab fa-whatsapp"></i></a>
                </div>
              </div>
            </RoundedCard>
          ))}
        </div>
        <button onClick={() => setEditingCustomer({})} className="w-full py-6 border-2 border-dashed border-sky-200 rounded-[2.5rem] text-sky-400 font-black text-sm uppercase hover:bg-white hover:text-sky-600 transition-all">+ Añadir Nuevo Cliente</button>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Customer, Product, CartItem, Order, Vehicle } from '../types';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';
import { optimizeRoute } from '../services/geminiService';

export const OrdersModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const { customers, products, orders, addOrder, updateOrder, vehicles, setOrders } = useERPData();
  const [activeTab, setActiveTab] = useState<'new' | 'pending' | 'assigned'>('pending');

  // --- STATE: NEW ORDER ---
  const [customer, setCustomer] = useState<Customer | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [search, setSearch] = useState('');
  const [isUrgent, setIsUrgent] = useState(false);
  const [scheduleDate, setScheduleDate] = useState<'today' | 'tomorrow' | string>('today');

  // --- STATE: MANAGEMENT ---
  const [optimizing, setOptimizing] = useState(false);
  const [selectedOrderIds, setSelectedOrderIds] = useState<Set<string>>(new Set());
  const [showAssignModal, setShowAssignModal] = useState(false);

  // --- COMPUTED ---
  const total = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);

  // --- ACTIONS: NEW ORDER ---
  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === product.id);
      if (existing) return prev.map(i => i.id === product.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.filter(i => i.id !== id));
  };

  const handleCreateOrder = () => {
    if (!customer || cart.length === 0) return alert("Selecciona cliente y productos.");

    // Calculate timestamp based on schedule
    const now = new Date();
    let targetDate = new Date();
    if (scheduleDate === 'tomorrow') {
        targetDate.setDate(now.getDate() + 1);
    } else if (scheduleDate !== 'today') {
        targetDate = new Date(scheduleDate); // YYYY-MM-DD
        // Set to 9 AM
        targetDate.setHours(9, 0, 0, 0);
    }

    addOrder({
      customerId: customer.id,
      customerAlias: customer.alias,
      items: cart,
      total,
      status: 'pendiente',
      priority: isUrgent ? 2 : 1,
      timestamp: targetDate.getTime()
    });

    // Reset Form
    setCustomer(null);
    setCart([]);
    setSearch('');
    setIsUrgent(false);
    setScheduleDate('today');
    setActiveTab('pending');
  };

  // --- ACTIONS: BULK MANAGEMENT ---
  const toggleOrderSelection = (id: string) => {
    const newSet = new Set(selectedOrderIds);
    if (newSet.has(id)) newSet.delete(id);
    else newSet.add(id);
    setSelectedOrderIds(newSet);
  };

  const selectAllPending = () => {
    const pendingIds = orders.filter(o => o.status === 'pendiente').map(o => o.id);
    if (selectedOrderIds.size === pendingIds.length) {
        setSelectedOrderIds(new Set());
    } else {
        setSelectedOrderIds(new Set(pendingIds));
    }
  };

  const handleAssignToVehicle = (vehicleId: string) => {
    const idsToAssign = Array.from(selectedOrderIds);
    if (idsToAssign.length === 0) return;

    // Bulk update logic
    const updatedOrders = orders.map(o => {
        if (idsToAssign.includes(o.id)) {
            return { ...o, vehicleId, status: 'asignado' as const };
        }
        return o;
    });

    setOrders(updatedOrders);
    setSelectedOrderIds(new Set());
    setShowAssignModal(false);
  };

  const handleOptimize = async () => {
    const pendingOrders = orders.filter(o => o.status === 'pendiente');
    if (pendingOrders.length < 2) return alert("Necesitas al menos 2 pedidos pendientes.");

    setOptimizing(true);
    const result = await optimizeRoute(pendingOrders);

    if (result.orderedIds) {
      const optimized = [...orders].sort((a, b) => {
        const idxA = result.orderedIds.indexOf(a.id);
        const idxB = result.orderedIds.indexOf(b.id);
        // If not in optimized list, keep original relative order or put at end
        if (idxA === -1 && idxB === -1) return 0;
        if (idxA === -1) return 1;
        if (idxB === -1) return -1;
        return idxA - idxB;
      });
      setOrders(optimized);
      alert("¡Ruta optimizada por IA!");
    }
    setOptimizing(false);
  };

  // --- RENDER HELPERS ---
  const pendingOrders = useMemo(() => orders.filter(o => o.status === 'pendiente'), [orders]);
  const assignedOrders = useMemo(() => orders.filter(o => o.status === 'asignado'), [orders]);

  return (
    <div className="h-full bg-sky-50 flex flex-col animate-fadeIn overflow-hidden pb-24 relative">
      <ModuleHeader title="Logística de Pedidos" onBack={onBack} />

      {/* TABS */}
      <div className="px-6 flex gap-2 mb-4 shrink-0">
        <button onClick={() => setActiveTab('new')} className={`flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'new' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-200' : 'bg-white text-slate-400'}`}>
            <i className="fas fa-plus mr-1"></i> Crear
        </button>
        <button onClick={() => setActiveTab('pending')} className={`flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all relative ${activeTab === 'pending' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-200' : 'bg-white text-slate-400'}`}>
            Pendientes
            {pendingOrders.length > 0 && <span className="absolute -top-1 -right-1 bg-rose-500 text-white w-5 h-5 flex items-center justify-center rounded-full text-[8px] border-2 border-sky-50">{pendingOrders.length}</span>}
        </button>
        <button onClick={() => setActiveTab('assigned')} className={`flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'assigned' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-200' : 'bg-white text-slate-400'}`}>
            En Ruta
        </button>
      </div>

      <div className="flex-1 overflow-y-auto px-6 space-y-4 no-scrollbar pb-24">

        {/* --- TAB: NEW ORDER --- */}
        {activeTab === 'new' && (
          <div className="space-y-6">

            {/* Customer Search */}
            <section className="relative z-20">
              <label className="text-[10px] font-black text-slate-400 uppercase ml-2 mb-1 block">1. Cliente</label>
              <div className="relative">
                <input 
                  type="text" 
                  placeholder="Nombre, alias o teléfono..." 
                  className="w-full bg-white border-none rounded-[2rem] py-5 px-6 shadow-sm outline-none focus:ring-2 ring-indigo-300 font-bold text-sky-900"
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                />
                <i className="fas fa-search absolute right-6 top-1/2 -translate-y-1/2 text-slate-300"></i>

                {search && !customer && (
                  <div className="absolute top-full left-0 right-0 bg-white shadow-2xl rounded-3xl mt-2 overflow-hidden border border-slate-100 max-h-48 overflow-y-auto">
                    {customers.filter(c => c.alias.toLowerCase().includes(search.toLowerCase())).map(c => (
                      <button key={c.id} onClick={() => { setCustomer(c); setSearch(c.alias); }} className="w-full text-left p-4 hover:bg-sky-50 border-b border-slate-50 last:border-none flex justify-between items-center group">
                        <span className="font-bold text-slate-700 text-sm">{c.alias}</span>
                        <i className="fas fa-plus-circle text-indigo-200 group-hover:text-indigo-500"></i>
                      </button>
                    ))}
                  </div>
                )}
              </div>
              {customer && (
                <div className="mt-3 bg-indigo-50 border border-indigo-100 p-4 rounded-[1.5rem] flex justify-between items-center animate-fadeIn">
                  <div className="flex items-center gap-3">
                      <div className="w-10 h-10 bg-indigo-100 rounded-full flex items-center justify-center text-indigo-600"><i className="fas fa-user-check"></i></div>
                      <div>
                          <p className="font-black text-indigo-900 text-sm">{customer.alias}</p>
                          <p className="text-[9px] text-indigo-400 font-bold uppercase">{customer.address || 'Sin dirección'}</p>
                      </div>
                  </div>
                  <button onClick={() => { setCustomer(null); setSearch(''); }} className="w-8 h-8 flex items-center justify-center bg-white rounded-full text-rose-400 shadow-sm"><i className="fas fa-times"></i></button>
                </div>
              )}
            </section>

            {/* Product Selection */}
            <section>
               <label className="text-[10px] font-black text-slate-400 uppercase ml-2 mb-2 block">2. Productos</label>
               <div className="grid grid-cols-2 gap-2">
                {products.map(p => {
                    const inCart = cart.find(i => i.id === p.id)?.quantity || 0;
                    return (
                        <button 
                            key={p.id} 
                            onClick={() => addToCart(p)} 
                            className={`p-3 rounded-2xl border text-left transition-all relative overflow-hidden ${inCart > 0 ? 'bg-indigo-600 text-white border-indigo-600 shadow-md' : 'bg-white border-transparent text-slate-600 hover:border-indigo-100'}`}
                        >
                            <div className="text-[10px] font-black uppercase leading-tight mb-1 pr-6">{p.name}</div>
                            <div className={`font-black ${inCart > 0 ? 'text-indigo-200' : 'text-indigo-500'}`}>${p.price}</div>
                            {inCart > 0 && (
                                <div className="absolute top-2 right-2 bg-white text-indigo-600 w-6 h-6 rounded-full flex items-center justify-center font-black text-xs shadow-sm">
                                    {inCart}
                                </div>
                            )}
                        </button>
                    );
                })}
               </div>
            </section>

            {/* Scheduling & Options */}
            <section className="bg-white p-5 rounded-[2rem] shadow-sm">
                <label className="text-[10px] font-black text-slate-400 uppercase mb-3 block">3. Detalles de Entrega</label>

                <div className="flex gap-2 mb-4 overflow-x-auto no-scrollbar">
                    <button onClick={() => setScheduleDate('today')} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase whitespace-nowrap transition-colors ${scheduleDate === 'today' ? 'bg-emerald-100 text-emerald-600 ring-2 ring-emerald-400' : 'bg-slate-50 text-slate-400'}`}>
                        Hoy
                    </button>
                    <button onClick={() => setScheduleDate('tomorrow')} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase whitespace-nowrap transition-colors ${scheduleDate === 'tomorrow' ? 'bg-sky-100 text-sky-600 ring-2 ring-sky-400' : 'bg-slate-50 text-slate-400'}`}>
                        Mañana
                    </button>
                    <input 
                        type="date" 
                        className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase bg-slate-50 text-slate-500 outline-none focus:ring-2 focus:ring-indigo-300 ${scheduleDate !== 'today' && scheduleDate !== 'tomorrow' ? 'ring-2 ring-indigo-400 bg-indigo-50 text-indigo-600' : ''}`}
                        onChange={(e) => setScheduleDate(e.target.value)}
                    />
                </div>

                <div className="flex items-center justify-between bg-rose-50 p-3 rounded-2xl border border-rose-100">
                    <div className="flex items-center gap-2">
                        <div className={`w-4 h-4 rounded-full border-2 flex items-center justify-center ${isUrgent ? 'border-rose-500 bg-rose-500' : 'border-rose-300'}`}>
                            {isUrgent && <i className="fas fa-check text-white text-[8px]"></i>}
                        </div>
                        <span className="text-xs font-bold text-rose-700">Marcar como URGENTE</span>
                    </div>
                    <input type="checkbox" checked={isUrgent} onChange={() => setIsUrgent(!isUrgent)} className="absolute opacity-0 w-full h-10 left-0 cursor-pointer" />
                </div>
            </section>

            {/* Summary & Action */}
            {cart.length > 0 && (
                <div className="pt-2 animate-slideUp">
                    <div className="flex justify-between items-end mb-4 px-2">
                        <span className="text-xs font-bold text-slate-400 uppercase">Total a Cobrar</span>
                        <span className="text-3xl font-black text-sky-900 tracking-tighter">${total.toFixed(2)}</span>
                    </div>
                    <ActionButton onClick={handleCreateOrder}>
                        Confirmar Pedido <i className="fas fa-check ml-2"></i>
                    </ActionButton>
                </div>
            )}
          </div>
        )}

        {/* --- TAB: PENDING --- */}
        {activeTab === 'pending' && (
          <div className="space-y-4">

            {/* Toolbar */}
            <div className="flex justify-between items-center bg-white p-2 pl-4 rounded-[1.5rem] shadow-sm mb-2 sticky top-0 z-10 border border-slate-50">
               <div className="flex items-center gap-2">
                  <div 
                    onClick={selectAllPending}
                    className={`w-5 h-5 rounded-lg border-2 flex items-center justify-center cursor-pointer transition-colors ${selectedOrderIds.size > 0 && selectedOrderIds.size === pendingOrders.length ? 'bg-indigo-600 border-indigo-600' : 'border-slate-300'}`}
                  >
                     {selectedOrderIds.size > 0 && <i className={`fas ${selectedOrderIds.size === pendingOrders.length ? 'fa-check' : 'fa-minus'} text-white text-[10px]`}></i>}
                  </div>
                  <span className="text-[10px] font-black uppercase text-slate-500">
                      {selectedOrderIds.size > 0 ? `${selectedOrderIds.size} Seleccionados` : 'Seleccionar Todo'}
                  </span>
               </div>
               <button 
                 onClick={handleOptimize} 
                 disabled={optimizing} 
                 className="w-10 h-10 bg-emerald-50 text-emerald-600 rounded-xl flex items-center justify-center active:scale-90 transition-transform"
               >
                 <i className={`fas ${optimizing ? 'fa-spinner animate-spin' : 'fa-wand-magic-sparkles'}`}></i>
               </button>
            </div>

            {pendingOrders.length === 0 ? (
                <div className="text-center py-20 opacity-40">
                    <i className="fas fa-clipboard-check text-6xl mb-4 text-slate-300"></i>
                    <p className="text-xs font-black uppercase text-slate-400">Todo al día</p>
                </div>
            ) : (
                pendingOrders.map((o) => {
                    const isSelected = selectedOrderIds.has(o.id);
                    const isUrgent = o.priority > 1;
                    const date = new Date(o.timestamp);
                    const isToday = date.getDate() === new Date().getDate();

                    return (
                        <div 
                            key={o.id} 
                            onClick={() => toggleOrderSelection(o.id)}
                            className={`relative p-5 rounded-[2rem] transition-all border-2 active:scale-[0.98] ${isSelected ? 'bg-indigo-50 border-indigo-500 shadow-md z-10' : 'bg-white border-transparent shadow-sm'}`}
                        >
                            {/* Urgent Badge */}
                            {isUrgent && <div className="absolute top-0 right-0 bg-rose-500 text-white text-[8px] font-black px-3 py-1 rounded-bl-xl rounded-tr-xl shadow-sm">URGENTE</div>}

                            <div className="flex justify-between items-start mb-3">
                                <div className="flex items-center gap-3">
                                    <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center shrink-0 ${isSelected ? 'bg-indigo-600 border-indigo-600' : 'border-slate-200'}`}>
                                        {isSelected && <i className="fas fa-check text-white text-[10px]"></i>}
                                    </div>
                                    <div>
                                        <h4 className="font-black text-sky-900 leading-none mb-1">{o.customerAlias}</h4>
                                        <div className="flex gap-2">
                                            <span className="text-[9px] font-bold text-slate-400 bg-slate-100 px-1.5 rounded uppercase">
                                                {isToday ? 'Entrega Hoy' : date.toLocaleDateString()}
                                            </span>
                                            <span className="text-[9px] font-bold text-slate-400">
                                                {new Date(o.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                                            </span>
                                        </div>
                                    </div>
                                </div>
                                <span className="font-black text-indigo-600 text-lg tracking-tighter">${o.total}</span>
                            </div>

                            <div className="flex flex-wrap gap-1 pl-9">
                                {o.items.map(i => (
                                    <span key={i.id} className="text-[9px] font-bold text-slate-600 bg-slate-50 px-2 py-1 rounded-lg border border-slate-100">
                                        {i.quantity}x {i.name.split(' ')[0]}
                                    </span>
                                ))}
                            </div>
                        </div>
                    );
                })
            )}
          </div>
        )}

        {/* --- TAB: ASSIGNED (EN RUTA) --- */}
        {activeTab === 'assigned' && (
          <div className="space-y-4">
             {assignedOrders.length === 0 ? (
                <div className="text-center py-20 opacity-40">
                    <i className="fas fa-truck-fast text-6xl mb-4 text-slate-300"></i>
                    <p className="text-xs font-black uppercase text-slate-400">Sin pedidos en ruta</p>
                </div>
             ) : (
                assignedOrders.map(o => {
                    const vehicle = vehicles.find(v => v.id === o.vehicleId);
                    return (
                        <RoundedCard key={o.id} className="border-l-4 border-l-emerald-400 relative overflow-hidden">
                            <div className="flex justify-between items-start">
                                <div>
                                    <h4 className="font-black text-sky-900 mb-1">{o.customerAlias}</h4>
                                    <div className="flex items-center gap-2">
                                        <i className="fas fa-truck text-emerald-500 text-xs"></i>
                                        <span className="text-[10px] font-bold text-slate-500 uppercase">{vehicle?.plate || 'Unidad ?'}</span>
                                    </div>
                                </div>
                                <div className="text-right">
                                    <span className="font-black text-sky-900 block mb-2">${o.total}</span>
                                    <button 
                                        onClick={() => updateOrder({...o, status: 'entregado'})}
                                        className="bg-emerald-100 text-emerald-600 px-3 py-1.5 rounded-lg text-[9px] font-black uppercase flex items-center gap-1 active:bg-emerald-200 transition-colors"
                                    >
                                        Entregado <i className="fas fa-check"></i>
                                    </button>
                                </div>
                            </div>
                        </RoundedCard>
                    );
                })
             )}
          </div>
        )}
      </div>

      {/* --- FLOATING ACTION BUTTON (ASSIGN) --- */}
      {selectedOrderIds.size > 0 && activeTab === 'pending' && (
        <div className="fixed bottom-6 left-6 right-6 z-30 animate-slideUp">
            <button 
                onClick={() => setShowAssignModal(true)}
                className="w-full bg-indigo-600 text-white py-4 rounded-[2rem] shadow-2xl shadow-indigo-500/40 flex items-center justify-center gap-3 font-black uppercase text-xs tracking-widest active:scale-95 transition-transform"
            >
                <span>Asignar {selectedOrderIds.size} Pedidos</span>
                <i className="fas fa-truck-arrow-right"></i>
            </button>
        </div>
      )}

      {/* --- MODAL: SELECT VEHICLE --- */}
      {showAssignModal && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[100] flex items-end justify-center animate-fadeIn">
            <div className="bg-white w-full max-w-md rounded-t-[2.5rem] p-6 shadow-2xl">
                <div className="flex justify-between items-center mb-6">
                    <h3 className="text-xl font-black text-sky-900">Seleccionar Unidad</h3>
                    <button onClick={() => setShowAssignModal(false)} className="w-10 h-10 bg-slate-100 rounded-full text-slate-400"><i className="fas fa-times"></i></button>
                </div>

                <div className="space-y-3 max-h-[60vh] overflow-y-auto no-scrollbar pb-6">
                    {vehicles.map(v => {
                        const loadPercent = Math.round((v.currentLoad / v.loadCapacity) * 100);
                        const isFull = loadPercent >= 100;

                        return (
                            <button 
                                key={v.id} 
                                onClick={() => handleAssignToVehicle(v.id)}
                                disabled={isFull}
                                className={`w-full p-4 rounded-[2rem] border-2 flex items-center justify-between transition-all ${isFull ? 'bg-slate-50 border-slate-100 opacity-60' : 'bg-white border-slate-100 active:border-indigo-500 active:bg-indigo-50'}`}
                            >
                                <div className="flex items-center gap-4">
                                    <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-xl ${isFull ? 'bg-slate-200 text-slate-400' : 'bg-indigo-100 text-indigo-600'}`}>
                                        <i className="fas fa-truck-front"></i>
                                    </div>
                                    <div className="text-left">
                                        <h5 className="font-black text-sky-900 text-sm uppercase">{v.plate}</h5>
                                        <p className="text-[10px] font-bold text-slate-400">{v.description}</p>
                                    </div>
                                </div>
                                <div className="text-right">
                                    <span className={`text-xs font-black ${isFull ? 'text-rose-500' : 'text-emerald-500'}`}>{loadPercent}% Carga</span>
                                    <div className="w-20 h-1.5 bg-slate-100 rounded-full mt-1 overflow-hidden">
                                        <div className={`h-full ${isFull ? 'bg-rose-500' : 'bg-emerald-500'}`} style={{width: `${Math.min(loadPercent, 100)}%`}}></div>
                                    </div>
                                </div>
                            </button>
                        );
                    })}
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { useNavigation } from './hooks/useNavigation';
import { Employee, Order } from './types';
import { Dashboard } from './components/Dashboard';
import { POSModule } from './components/POSModule';
import { ProductionModule } from './components/ProductionModule';
import { LogisticsModule } from './components/LogisticsModule';
import { InventoryModule } from './components/InventoryModule';
import { SuppliesModule } from './components/SuppliesModule';
import { WhatsAppModule } from './components/WhatsAppModule';
import { CustomersModule } from './components/CustomersModule';
import { EmployeesModule } from './components/EmployeesModule';
import { ReportsModule } from './components/ReportsModule';
import { SettingsModule } from './components/SettingsModule';
import { SyncModule } from './components/SyncModule';
import { OrdersModule } from './components/OrdersModule';
import { QualityModule } from './components/QualityModule';
import { ScannerModule } from './components/ScannerModule';
import { TicketModule } from './components/TicketModule';
import { VoiceAI } from './components/VoiceAI';

// Auth & UI Components
import { PermissionShield } from './components/auth/PermissionShield';
import { LoginScreen } from './components/auth/LoginScreen';
import { SplashScreen } from './components/ui/SplashScreen';

const App: React.FC = () => {
  const { currentView, navigateTo, goBack } = useNavigation();
  const [showSplash, setShowSplash] = useState(true);
  const [needsPermissions, setNeedsPermissions] = useState(() => !localStorage.getItem('aqua_permissions_granted'));
  const [user, setUser] = useState<Employee | null>(null);

  // State for passing Order to POS
  const [pendingOrderForPOS, setPendingOrderForPOS] = useState<Order | null>(null);

  const handleProcessOrder = (order: Order) => {
    setPendingOrderForPOS(order);
    navigateTo('pos');
  };

  if (needsPermissions) return <PermissionShield onGranted={() => setNeedsPermissions(false)} />;
  if (showSplash) return <SplashScreen onComplete={() => setShowSplash(false)} />;
  if (!user) return <LoginScreen onLogin={setUser} />;

  return (
    <div className="max-w-md mx-auto min-h-screen bg-sky-50 relative overflow-x-hidden shadow-2xl">
      <main className="min-h-screen">
        {currentView === 'dashboard' && <Dashboard setView={navigateTo} user={user} onLogout={() => setUser(null)} />}

        {currentView === 'pos' && (
          <POSModule 
            user={user} 
            onBack={goBack} 
            initialOrder={pendingOrderForPOS} 
            onClearInitialOrder={() => setPendingOrderForPOS(null)} 
          />
        )}

        {currentView === 'settings' && <SettingsModule currentUser={user} onBack={goBack} />}
        {currentView === 'whatsapp' && <WhatsAppModule onBack={goBack} />}
        {currentView === 'customers' && <CustomersModule onBack={goBack} />}
        {currentView === 'logistics' && <LogisticsModule onBack={goBack} />}
        {currentView === 'production' && <ProductionModule onBack={goBack} />}
        {currentView === 'sync' && <SyncModule onBack={goBack} onScanRequest={() => navigateTo('scanner')} />}
        {currentView === 'inventory' && <InventoryModule onBack={goBack} />}
        {currentView === 'supplies' && <SuppliesModule onBack={goBack} />}
        {currentView === 'employees' && <EmployeesModule onBack={goBack} currentUser={user} />}
        {currentView === 'reports' && <ReportsModule onBack={goBack} />}
        {currentView === 'quality' && <QualityModule onBack={goBack} />}
        {currentView === 'scanner' && <ScannerModule onBack={goBack} />}

        {currentView === 'orders' && (
          <OrdersModule 
            onBack={goBack} 
            onProcessOrder={handleProcessOrder} 
          />
        )}

        {currentView === 'tickets' && <TicketModule onBack={goBack} />}
      </main>
      {currentView === 'dashboard' && <VoiceAI onAction={(res) => res.action === 'SALE' && navigateTo('pos')} />}
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Customer, Product, CartItem, Order, Vehicle } from '../types';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';
import { optimizeRoute } from '../services/geminiService';

interface OrdersModuleProps {
  onBack: () => void;
  onProcessOrder: (order: Order) => void;
}

export const OrdersModule: React.FC<OrdersModuleProps> = ({ onBack, onProcessOrder }) => {
  const { customers, products, orders, addOrder, updateOrder, vehicles, setOrders } = useERPData();
  const [activeTab, setActiveTab] = useState<'new' | 'pending' | 'assigned'>('pending');

  // --- STATE: NEW ORDER ---
  const [customer, setCustomer] = useState<Customer | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [search, setSearch] = useState('');
  const [isUrgent, setIsUrgent] = useState(false);
  const [scheduleDate, setScheduleDate] = useState<'today' | 'tomorrow' | string>('today');

  // --- STATE: MANAGEMENT ---
  const [optimizing, setOptimizing] = useState(false);
  const [selectedOrderIds, setSelectedOrderIds] = useState<Set<string>>(new Set());
  const [showAssignModal, setShowAssignModal] = useState(false);

  // --- COMPUTED ---
  const total = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);

  // --- ACTIONS: NEW ORDER ---
  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === product.id);
      if (existing) return prev.map(i => i.id === product.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.filter(i => i.id !== id));
  };

  const handleCreateOrder = () => {
    if (!customer || cart.length === 0) return alert("Selecciona cliente y productos.");

    // Calculate timestamp based on schedule
    const now = new Date();
    let targetDate = new Date();
    if (scheduleDate === 'tomorrow') {
        targetDate.setDate(now.getDate() + 1);
    } else if (scheduleDate !== 'today') {
        targetDate = new Date(scheduleDate); // YYYY-MM-DD
        // Set to 9 AM
        targetDate.setHours(9, 0, 0, 0);
    }

    addOrder({
      customerId: customer.id,
      customerAlias: customer.alias,
      items: cart,
      total,
      status: 'pendiente',
      priority: isUrgent ? 2 : 1,
      timestamp: targetDate.getTime()
    });

    // Reset Form
    setCustomer(null);
    setCart([]);
    setSearch('');
    setIsUrgent(false);
    setScheduleDate('today');
    setActiveTab('pending');
  };

  // --- ACTIONS: BULK MANAGEMENT ---
  const toggleOrderSelection = (id: string) => {
    const newSet = new Set(selectedOrderIds);
    if (newSet.has(id)) newSet.delete(id);
    else newSet.add(id);
    setSelectedOrderIds(newSet);
  };

  const selectAllPending = () => {
    const pendingIds = orders.filter(o => o.status === 'pendiente').map(o => o.id);
    if (selectedOrderIds.size === pendingIds.length) {
        setSelectedOrderIds(new Set());
    } else {
        setSelectedOrderIds(new Set(pendingIds));
    }
  };

  const handleAssignToVehicle = (vehicleId: string) => {
    const idsToAssign = Array.from(selectedOrderIds);
    if (idsToAssign.length === 0) return;

    // Bulk update logic
    const updatedOrders = orders.map(o => {
        if (idsToAssign.includes(o.id)) {
            return { ...o, vehicleId, status: 'asignado' as const };
        }
        return o;
    });

    setOrders(updatedOrders);
    setSelectedOrderIds(new Set());
    setShowAssignModal(false);
  };

  const handleOptimize = async () => {
    const pendingOrders = orders.filter(o => o.status === 'pendiente');
    if (pendingOrders.length < 2) return alert("Necesitas al menos 2 pedidos pendientes.");

    setOptimizing(true);
    const result = await optimizeRoute(pendingOrders);

    if (result.orderedIds) {
      const optimized = [...orders].sort((a, b) => {
        const idxA = result.orderedIds.indexOf(a.id);
        const idxB = result.orderedIds.indexOf(b.id);
        // If not in optimized list, keep original relative order or put at end
        if (idxA === -1 && idxB === -1) return 0;
        if (idxA === -1) return 1;
        if (idxB === -1) return -1;
        return idxA - idxB;
      });
      setOrders(optimized);
      alert("¡Ruta optimizada por IA!");
    }
    setOptimizing(false);
  };

  // --- RENDER HELPERS ---
  const pendingOrders = useMemo(() => orders.filter(o => o.status === 'pendiente'), [orders]);
  const assignedOrders = useMemo(() => orders.filter(o => o.status === 'asignado'), [orders]);

  return (
    <div className="h-full bg-sky-50 flex flex-col animate-fadeIn overflow-hidden pb-24 relative">
      <ModuleHeader title="Logística de Pedidos" onBack={onBack} />

      {/* TABS */}
      <div className="px-6 flex gap-2 mb-4 shrink-0">
        <button onClick={() => setActiveTab('new')} className={`flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'new' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-200' : 'bg-white text-slate-400'}`}>
            <i className="fas fa-plus mr-1"></i> Crear
        </button>
        <button onClick={() => setActiveTab('pending')} className={`flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all relative ${activeTab === 'pending' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-200' : 'bg-white text-slate-400'}`}>
            Pendientes
            {pendingOrders.length > 0 && <span className="absolute -top-1 -right-1 bg-rose-500 text-white w-5 h-5 flex items-center justify-center rounded-full text-[8px] border-2 border-sky-50">{pendingOrders.length}</span>}
        </button>
        <button onClick={() => setActiveTab('assigned')} className={`flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'assigned' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-200' : 'bg-white text-slate-400'}`}>
            En Ruta
        </button>
      </div>

      <div className="flex-1 overflow-y-auto px-6 space-y-4 no-scrollbar pb-24">

        {/* --- TAB: NEW ORDER --- */}
        {activeTab === 'new' && (
          <div className="space-y-6">

            {/* Customer Search */}
            <section className="relative z-20">
              <label className="text-[10px] font-black text-slate-400 uppercase ml-2 mb-1 block">1. Cliente</label>
              <div className="relative">
                <input 
                  type="text" 
                  placeholder="Nombre, alias o teléfono..." 
                  className="w-full bg-white border-none rounded-[2rem] py-5 px-6 shadow-sm outline-none focus:ring-2 ring-indigo-300 font-bold text-sky-900"
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                />
                <i className="fas fa-search absolute right-6 top-1/2 -translate-y-1/2 text-slate-300"></i>

                {search && !customer && (
                  <div className="absolute top-full left-0 right-0 bg-white shadow-2xl rounded-3xl mt-2 overflow-hidden border border-slate-100 max-h-48 overflow-y-auto">
                    {customers.filter(c => c.alias.toLowerCase().includes(search.toLowerCase())).map(c => (
                      <button key={c.id} onClick={() => { setCustomer(c); setSearch(c.alias); }} className="w-full text-left p-4 hover:bg-sky-50 border-b border-slate-50 last:border-none flex justify-between items-center group">
                        <span className="font-bold text-slate-700 text-sm">{c.alias}</span>
                        <i className="fas fa-plus-circle text-indigo-200 group-hover:text-indigo-500"></i>
                      </button>
                    ))}
                  </div>
                )}
              </div>
              {customer && (
                <div className="mt-3 bg-indigo-50 border border-indigo-100 p-4 rounded-[1.5rem] flex justify-between items-center animate-fadeIn">
                  <div className="flex items-center gap-3">
