          alert("Error al generar imagen");
          setSharing(false);
          return;
        }

        const file = new File([blob], `Ticket_${sale.id}.png`, { type: "image/png" });

        // Intentar usar Web Share API Nivel 2 (Archivos) para compartir sin descarga manual
        if (navigator.canShare && navigator.canShare({ files: [file] })) {
          try {
            await navigator.share({
              files: [file],
