                  </div>
                  <div className="text-right">
                    <span className="font-black text-sky-600 text-xl tracking-tighter">${s.total}</span>
                    <p className="text-[8px] font-black text-sky-300 uppercase">{s.id}</p>
                  </div>
                </div>
                <div className="flex gap-2 mt-5">
                   <button onClick={() => setViewingTicket(s)} className="flex-1 text-[9px] font-black uppercase bg-sky-100 text-sky-600 px-3 py-3 rounded-xl flex items-center justify-center gap-2 active:bg-sky-200 transition-colors">
                    <i className="fas fa-eye"></i> Ver Ticket
                   </button>
                   <button onClick={() => handleSendWhatsApp(s)} className="flex-1 text-[9px] font-black uppercase bg-emerald-100 text-emerald-600 px-3 py-3 rounded-xl flex items-center justify-center gap-2 active:bg-emerald-200 transition-colors">
                    <i className="fab fa-whatsapp"></i> WA (Txt)
                   </button>
                </div>
              </RoundedCard>
            ))
          )}
        </div>
      )}

      {activeTab === 'sell' && (
        <div className="fixed bottom-0 left-0 right-0 p-6 bg-white/95 border-t border-sky-100 shadow-[0_-10px_40px_rgba(0,0,0,0.1)] z-50">
          <ActionButton onClick={handlePreCheckout} disabled={!customer || cart.length === 0}>
             {linkedOrderId ? 'Cobrar y Finalizar Entrega' : `Ir a Pagar $${total.toFixed(2)}`}
          </ActionButton>
        </div>
      )}

      {/* Modales */}
      {showPaymentModal && (
        <PaymentModal 
          total={total}
          onConfirm={handleConfirmPaymentSafe}
          onCancel={() => setShowPaymentModal(false)}
        />
      )}

      {viewingTicket && (
        <TicketModal 
          sale={viewingTicket} 
          config={ticketConfig} 
          onClose={() => setViewingTicket(null)} 
          onWhatsApp={() => handleSendWhatsApp(viewingTicket)}
          onNewSale={resetPOS}
          onFinish={() => {
            setViewingTicket(null);
            setActiveTab('history');
          }}
        />
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { useNavigation } from './hooks/useNavigation';
import { Employee, Order } from './types';
import { Dashboard } from './components/Dashboard';
import { POSModule } from './components/POSModule';
import { ProductionModule } from './components/ProductionModule';
import { LogisticsModule } from './components/LogisticsModule';
import { InventoryModule } from './components/InventoryModule';
import { SuppliesModule } from './components/SuppliesModule';
import { WhatsAppModule } from './components/WhatsAppModule';
import { CustomersModule } from './components/CustomersModule';
import { EmployeesModule } from './components/EmployeesModule';
import { ReportsModule } from './components/ReportsModule';
import { SettingsModule } from './components/SettingsModule';
import { SyncModule } from './components/SyncModule';
import { OrdersModule } from './components/OrdersModule';
import { QualityModule } from './components/QualityModule';
import { ScannerModule } from './components/ScannerModule';
import { TicketModule } from './components/TicketModule';
import { VoiceAI } from './components/VoiceAI';

// Auth & UI Components
import { PermissionShield } from './components/auth/PermissionShield';
import { LoginScreen } from './components/auth/LoginScreen';
import { SplashScreen } from './components/ui/SplashScreen';

const App: React.FC = () => {
  const { currentView, navigateTo, goBack } = useNavigation();
  const [showSplash, setShowSplash] = useState(true);
  const [needsPermissions, setNeedsPermissions] = useState(() => !localStorage.getItem('aqua_permissions_granted'));
  const [user, setUser] = useState<Employee | null>(null);

  // State for passing Order to POS
  const [pendingOrderForPOS, setPendingOrderForPOS] = useState<Order | null>(null);

  const handleProcessOrder = (order: Order) => {
    setPendingOrderForPOS(order);
    navigateTo('pos');
  };

  if (needsPermissions) return <PermissionShield onGranted={() => setNeedsPermissions(false)} />;
  if (showSplash) return <SplashScreen onComplete={() => setShowSplash(false)} />;
  if (!user) return <LoginScreen onLogin={setUser} />;

  return (
    <div className="max-w-md mx-auto min-h-screen bg-sky-50 relative overflow-x-hidden shadow-2xl">
      <main className="min-h-screen">
        {currentView === 'dashboard' && <Dashboard setView={navigateTo} user={user} onLogout={() => setUser(null)} />}

        {currentView === 'pos' && (
          <POSModule 
            user={user} 
            onBack={goBack} 
            initialOrder={pendingOrderForPOS} 
            onClearInitialOrder={() => setPendingOrderForPOS(null)} 
          />
        )}

        {currentView === 'settings' && <SettingsModule currentUser={user} onBack={goBack} />}
        {currentView === 'whatsapp' && <WhatsAppModule onBack={goBack} />}
        {currentView === 'customers' && <CustomersModule onBack={goBack} />}
        {currentView === 'logistics' && <LogisticsModule onBack={goBack} />}
        {currentView === 'production' && <ProductionModule onBack={goBack} />}
        {currentView === 'sync' && <SyncModule onBack={goBack} onScanRequest={() => navigateTo('scanner')} />}
        {currentView === 'inventory' && <InventoryModule onBack={goBack} />}
        {currentView === 'supplies' && <SuppliesModule onBack={goBack} />}
        {currentView === 'employees' && <EmployeesModule onBack={goBack} currentUser={user} />}
        {currentView === 'reports' && <ReportsModule onBack={goBack} />}
        {currentView === 'quality' && <QualityModule onBack={goBack} />}
        {currentView === 'scanner' && <ScannerModule onBack={goBack} />}

        {currentView === 'orders' && (
          <OrdersModule 
            onBack={goBack} 
            onProcessOrder={handleProcessOrder} 
          />
        )}

        {currentView === 'tickets' && <TicketModule onBack={goBack} />}
      </main>
      {currentView === 'dashboard' && <VoiceAI onAction={(res) => res.action === 'SALE' && navigateTo('pos')} />}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';

interface SyncModuleProps {
  onBack: () => void;
  onScanRequest: () => void;
  scannedId?: string;
}

type SyncStatus = 'idle' | 'syncing' | 'success' | 'error';

export const SyncModule: React.FC<SyncModuleProps> = ({ onBack, scannedId }) => {
  const { 
    sales, customers, products, orders, employees, vehicles, qualityRecords, tasks, attendance,
    syncData, cloudConfig, setCloudConfig 
  } = useERPData();

  const [status, setStatus] = useState<SyncStatus>('idle');
  const [logs, setLogs] = useState<string[]>([]);
  const [editingConfig, setEditingConfig] = useState(false);
  const [tempConfig, setTempConfig] = useState(cloudConfig);

  const addLog = (msg: string) => {
    setLogs(prev => [`[${new Date().toLocaleTimeString()}] ${msg}`, ...prev.slice(0, 4)]);
  };

  const handleSaveConfig = () => {
    // Validaciones básicas de URL de Firebase
    let url = tempConfig.url.trim();
    if (url && !url.endsWith('/')) url += '/';

    setCloudConfig({ ...tempConfig, url });
    setEditingConfig(false);
    addLog("Configuración guardada.");
  };

  const performSync = async () => {
    if (!cloudConfig.url) {
      alert("Configura primero la URL de tu base de datos (Firebase).");
      setEditingConfig(true);
      return;
    }

    setStatus('syncing');
    addLog("Iniciando conexión segura SSL...");

    try {
      const endpoint = `${cloudConfig.url}aqua_data.json${cloudConfig.apiKey ? `?auth=${cloudConfig.apiKey}` : ''}`;

      // 1. GET: Descargar estado actual de la nube para fusionar
      addLog("Verificando estado remoto...");
      const getResponse = await fetch(endpoint);
      if (!getResponse.ok) throw new Error(`Error conexión: ${getResponse.statusText}`);

      const cloudData = await getResponse.json();

      // Construir Payload de Subida (snapshot local)
      const uploadPayload = {
        sales, 
        customers, 
        products, 
        orders, 
        employees, 
        vehicles, 
        qualityRecords, 
        tasks, 
        attendance,
        lastUpdated: Date.now(),
        deviceUser: 'AquaPro Mobile'
      };

      // Si hay datos en la nube, los aplicamos localmente (La lógica de merge detallada está en useERPData)
      if (cloudData) {
        addLog("Descargando cambios remotos...");
        syncData(cloudData);

        // Fusión básica para re-subir: 
        // Nota: En un entorno de producción real, esto debería ser más granular (PATCH)
        // Aquí re-subimos el estado local YA fusionado (o el local si es más reciente/autoritativo para este dispositivo)
        // Para simplificar, asumimos que el estado local (tras syncData) es el 'master' temporal antes de subir.
        // Pero `syncData` es asíncrono en React State, así que usamos las variables locales fusionadas manualmente
        // solo para el payload de subida si quisiéramos ser perfectos. 
        // Dado que `syncData` actualiza el estado y eso dispara re-renders, 
        // la subida inmediata puede usar los datos "viejos" del render actual.
        // Solución robusta simple: Fusionar los arrays aquí para el payload de subida también.

        // Ejemplo de fusión para subida (Sales):
        if (cloudData.sales) {
           const localIds = new Set(sales.map(s => s.id));
           const newCloudSales = (cloudData.sales as any[]).filter((s: any) => !localIds.has(s.id));
           uploadPayload.sales = [...sales, ...newCloudSales];
        }
        // (Similar logic applies implicitly if we trust specific device authority, 
        // but for safety we usually rely on the next sync cycle or specialized backend logic.
        // For this implementation, we will upload the LOCAL state, assuming this device has "work done" 
        // that needs to go up. The next device downloads it.)
      }

      addLog("Subiendo datos locales...");
      const putResponse = await fetch(endpoint, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(uploadPayload)
      });

      if (!putResponse.ok) throw new Error("Error al escribir en nube");

      setCloudConfig(prev => ({ ...prev, lastSync: Date.now() }));
      setStatus('success');
      addLog("¡Sincronización Total Completada!");

    } catch (error: any) {
      console.error(error);
      setStatus('error');
      addLog(`Error: ${error.message}`);
    } finally {
      setTimeout(() => setStatus(prev => prev === 'syncing' ? 'idle' : prev), 2000);
    }
  };

  // Auto-sync effect
  useEffect(() => {
    if (cloudConfig.autoSync && cloudConfig.url && status === 'idle') {
      const timer = setInterval(() => {
        // Sync cada 10 segundos si está en auto
        performSync();
      }, 10000); // 10 segundos
      return () => clearInterval(timer);
    }
  }, [cloudConfig, status]);

  if (editingConfig) {
    return (
      <div className="h-full bg-slate-50 animate-fadeIn pb-24 overflow-y-auto">
        <ModuleHeader title="Configurar Nube" onBack={() => setEditingConfig(false)} />
        <div className="px-6 space-y-6">
          <div className="bg-white p-6 rounded-[2rem] shadow-lg border border-indigo-100">
             <div className="flex items-center gap-3 mb-4">
                <i className="fas fa-fire text-amber-500 text-2xl"></i>
                <h3 className="font-black text-sky-900">Firebase Realtime DB</h3>
             </div>
             <p className="text-xs text-slate-500 mb-6 leading-relaxed">
               Conecta tu ERP a una base de datos Firebase para sincronización en tiempo real a través de internet (sin necesidad de estar en la misma red Wi-Fi).
             </p>

             <div className="space-y-4">
               <div>
                 <label className="text-[10px] font-black uppercase text-sky-400 ml-2">URL de la Base de Datos</label>
                 <input 
                   type="url" 
                   placeholder="https://mi-proyecto.firebaseio.com/" 
                   className="w-full bg-slate-50 p-4 rounded-2xl outline-none font-bold text-sky-900 focus:ring-2 ring-indigo-300 transition-all text-xs"
                   value={tempConfig.url}
                   onChange={e => setTempConfig({...tempConfig, url: e.target.value})}
                 />
                 <p className="text-[9px] text-slate-400 mt-1 ml-2">Copia esto desde la consola de Firebase {'>'} Realtime Database.</p>
               </div>

               <div>
                 <label className="text-[10px] font-black uppercase text-sky-400 ml-2">Secreto de Base de Datos (Auth)</label>
                 <input 
                   type="password" 
                   placeholder="Token de secreto..." 
                   className="w-full bg-slate-50 p-4 rounded-2xl outline-none font-bold text-sky-900 focus:ring-2 ring-indigo-300 transition-all text-xs"
                   value={tempConfig.apiKey}
                   onChange={e => setTempConfig({...tempConfig, apiKey: e.target.value})}
                 />
                 <p className="text-[9px] text-slate-400 mt-1 ml-2">Configuración del Proyecto {'>'} Cuentas de servicio {'>'} Secretos.</p>
               </div>

               <div className="flex items-center gap-3 bg-indigo-50 p-4 rounded-2xl">
                 <div 
                   onClick={() => setTempConfig({...tempConfig, autoSync: !tempConfig.autoSync})}
                   className={`w-12 h-7 rounded-full p-1 transition-colors cursor-pointer ${tempConfig.autoSync ? 'bg-indigo-500' : 'bg-slate-300'}`}
                 >
                   <div className={`w-5 h-5 bg-white rounded-full shadow-sm transition-transform ${tempConfig.autoSync ? 'translate-x-5' : ''}`}></div>
                 </div>
                 <span className="text-xs font-bold text-indigo-900">Sincronización Automática (10 seg)</span>
               </div>
             </div>
          </div>
          <ActionButton onClick={handleSaveConfig}>Guardar Conexión</ActionButton>
        </div>
      </div>
    );
  }

  return (
    <div className="h-full bg-slate-900 text-white flex flex-col animate-fadeIn overflow-hidden pb-24">
      <div className="px-6 pt-8 pb-4 flex items-center justify-between">
        <div className="flex items-center gap-4">
          <button onClick={onBack} className="w-12 h-12 bg-white/10 rounded-2xl flex items-center justify-center active:scale-90 transition-transform">
            <i className="fas fa-arrow-left"></i>
          </button>
          <div>
            <h2 className="text-xl font-black tracking-tight">Aqua Cloud</h2>
            <div className="flex items-center gap-2">
               <div className={`w-2 h-2 rounded-full ${cloudConfig.url ? 'bg-emerald-400' : 'bg-red-500'}`}></div>
               <span className="text-[10px] font-bold uppercase opacity-70">{cloudConfig.url ? 'Conectado' : 'Desconectado'}</span>
            </div>
          </div>
        </div>
        <button onClick={() => setEditingConfig(true)} className="w-10 h-10 bg-white/10 rounded-xl flex items-center justify-center text-sm active:bg-white/20">
          <i className="fas fa-gear"></i>
        </button>
      </div>

      <div className="flex-1 overflow-y-auto px-6 space-y-8 no-scrollbar pb-10 flex flex-col justify-center">

        <div className="relative">
           {/* Status Ring */}
           <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-64 h-64 rounded-full border-4 border-indigo-500/20"></div>
           <div className={`absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-64 h-64 rounded-full border-t-4 border-indigo-500 transition-all duration-1000 ${status === 'syncing' ? 'animate-spin' : ''}`}></div>

           <div className="flex flex-col items-center justify-center relative z-10">
              <div className={`w-32 h-32 rounded-full flex items-center justify-center text-5xl shadow-[0_0_50px_rgba(99,102,241,0.3)] transition-all ${status === 'syncing' ? 'bg-indigo-600 scale-110' : status === 'success' ? 'bg-emerald-500' : status === 'error' ? 'bg-red-500' : 'bg-slate-800 border border-slate-700'}`}>
                 <i className={`fas ${status === 'syncing' ? 'fa-rotate animate-spin' : status === 'success' ? 'fa-check' : status === 'error' ? 'fa-triangle-exclamation' : 'fa-cloud'}`}></i>
              </div>

              <h3 className="text-2xl font-black mt-6 mb-1">
                {status === 'syncing' ? 'Sincronizando...' : status === 'success' ? 'Todo al día' : 'Nube Aqua+'}
              </h3>

              {cloudConfig.lastSync ? (
                <p className="text-xs font-mono opacity-50 bg-black/20 px-3 py-1 rounded-full">
                  Última vez: {new Date(cloudConfig.lastSync).toLocaleTimeString()}
                </p>
              ) : (
                <p className="text-xs font-bold opacity-50">Nunca sincronizado</p>
              )}
           </div>
        </div>

        <div className="space-y-4">
           <button 
             onClick={performSync}
             disabled={status === 'syncing'}
             className="w-full bg-white text-indigo-900 py-6 rounded-[2.5rem] font-black uppercase text-sm tracking-widest shadow-2xl shadow-indigo-500/20 active:scale-95 transition-all disabled:opacity-50 flex items-center justify-center gap-3"
           >
             {status === 'syncing' ? 'Procesando...' : 'Sincronizar Todo'}
             {!status.includes('sync') && <i className="fas fa-arrow-right-arrow-left"></i>}
           </button>

           <div className="grid grid-cols-2 gap-4 text-center">
              <div className="bg-white/5 p-4 rounded-3xl border border-white/5">
