import React, { useState, useEffect } from 'react';
import { Product, Customer, CartItem, PaymentSplit, Sale, Employee, TicketConfig, Order } from '../types';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';
import html2canvas from 'html2canvas';
import { Filesystem, Directory } from '@capacitor/filesystem';
import { generateTicketPDF } from '../services/pdfGenerator';

// Helper to convert Uint8Array to Base64
const uint8ArrayToBase64 = (bytes: Uint8Array) => {
    let binary = '';
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) {
        binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
}

// --- COMPONENTE TICKET MODAL (ESTILO TÉRMICO) ---
interface TicketModalProps {
  sale: Sale;
  config: TicketConfig;
  onClose: () => void;
  onWhatsApp: () => void;
  onNewSale: () => void;
  onFinish: () => void;
}

const TicketModal = ({ sale, config, onClose, onWhatsApp, onNewSale, onFinish }: TicketModalProps) => {
  const [sharing, setSharing] = useState(false);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved' | 'error'>('idle');

  const qrData = btoa(`AQUA-PRO-SECURE|${JSON.stringify({ id: sale.id, total: sale.total })}`);
  const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(qrData)}`;

  // Auto-save effect
  useEffect(() => {
    const timer = setTimeout(() => {
      handleAutoSave();
    }, 800); // Wait for render
    return () => clearTimeout(timer);
  }, []);

  const handleAutoSave = async () => {
    try {
      setSaveStatus('saving');
      const element = document.getElementById('printable-ticket');
      if (!element) return;

      const canvas = await html2canvas(element, { 
        scale: 2, 
        backgroundColor: '#ffffff',
        logging: false 
      });

      const base64Data = canvas.toDataURL('image/png');
      const base64Content = base64Data.split(',')[1];
      const fileName = `Ticket_${sale.id}_${Date.now()}.png`;

      // Intentar guardar usando Filesystem nativo
      try {
        await Filesystem.writeFile({
          path: fileName,
          data: base64Content,
          directory: Directory.Documents
        });
        setSaveStatus('saved');
      } catch (fsError) {
        console.warn("Filesystem save failed (likely web browser), skipping auto-save to disk", fsError);
        setSaveStatus('error');
      }

    } catch (e) {
      console.error("Error generating image", e);
      setSaveStatus('error');
    }
  };

  const handleSharePDF = async () => {
    setSharing(true);
    try {
        const pdfBytes = await generateTicketPDF(sale, config);
        const file = new File([pdfBytes], `Ticket_${sale.id}.pdf`, { type: 'application/pdf' });

        if (navigator.canShare && navigator.canShare({ files: [file] })) {
            await navigator.share({
                title: `Ticket ${sale.id}`,
                text: `Hola ${sale.customerAlias}, adjunto tu ticket de compra.`,
                files: [file]
            });
        } else {
            alert("Tu dispositivo no soporta compartir archivos directamente. Se descargará el PDF.");
            const url = URL.createObjectURL(file);
            const link = document.createElement('a');
            link.href = url;
            link.download = file.name;
            link.click();
            setTimeout(() => URL.revokeObjectURL(url), 1000);
        }
    } catch (e) {
        console.error(e);
        // Ignore abort errors (user cancelled share)
    } finally {
        setSharing(false);
    }
  };

  const handleSavePDF = async () => {
    try {
      setSaveStatus('saving');
      const pdfBytes = await generateTicketPDF(sale, config);
      const base64Content = uint8ArrayToBase64(pdfBytes);
      const fileName = `Reporte_${sale.id}.pdf`;

      await Filesystem.writeFile({
        path: fileName,
        data: base64Content,
        directory: Directory.Documents
      });

      setSaveStatus('saved');
      alert(`PDF Guardado en Documentos como: ${fileName}`);

      if (!(window as any).Capacitor?.isNative) {
         // Browser Fallback
         const blob = new Blob([pdfBytes], { type: 'application/pdf' });
         const url = URL.createObjectURL(blob);
         const link = document.createElement('a');
         link.href = url;
         link.download = fileName;
         link.click();
         setTimeout(() => URL.revokeObjectURL(url), 1000);
      }

    } catch (e) {
      console.error("Error saving PDF", e);
      setSaveStatus('error');
      alert("Error al generar el PDF.");
    } finally {
      setTimeout(() => setSaveStatus('idle'), 2000);
    }
  };

  const handleNativeShare = async () => {
    setSharing(true);
    try {
      const element = document.getElementById('printable-ticket');
      if (!element) return;

      // Generar imagen del ticket
      const canvas = await html2canvas(element, { 
        scale: 2, 
        backgroundColor: '#ffffff',
        logging: false 
      });

      canvas.toBlob(async (blob: Blob | null) => {
        if (!blob) {
          alert("Error al generar imagen");
          setSharing(false);
          return;
        }

        const file = new File([blob], `Ticket_${sale.id}.png`, { type: "image/png" });

        // Intentar usar Web Share API Nivel 2 (Archivos) para compartir sin descarga manual
        if (navigator.canShare && navigator.canShare({ files: [file] })) {
          try {
            await navigator.share({
              files: [file],
              title: `Ticket ${sale.id}`,
              text: `Gracias por tu compra en ${config.businessName}.`
            });
          } catch (error) {
