import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import { PDFDocument, StandardFonts, rgb, PDFFont } from 'pdf-lib';
import { TicketConfig, Sale } from '../types';

// Interface for the data expected by the report generator
interface ReportData {
  label: string;
  rangeType: string;
  totalGross: number;
  totalTransactions: number;
  averageTicket: number;
  payments: { cash: number; transfer: number };
  topProducts: { name: string; qty: number; total: number }[];
}

export const generateFinancialPDF = (data: ReportData, config: TicketConfig): string => {
  const doc = new jsPDF();
  const pageWidth = doc.internal.pageSize.width;

  // --- HEADER ---
  doc.setFillColor(2, 132, 199); // Sky-600
  doc.rect(0, 0, pageWidth, 40, 'F');

  doc.setTextColor(255, 255, 255);
  doc.setFontSize(22);
  doc.setFont('helvetica', 'bold');
  doc.text(config.businessName, 15, 15);

  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');
  doc.text('REPORTE FINANCIERO', 15, 22);
  doc.text(`Generado: ${new Date().toLocaleString()}`, 15, 27);

  // Right side header info
  doc.setFontSize(10);
  doc.text(`Periodo: ${data.label}`, pageWidth - 15, 15, { align: 'right' });
  doc.text(`Tipo: ${data.rangeType.toUpperCase()}`, pageWidth - 15, 20, { align: 'right' });

  // --- KPI CARDS (Simulated) ---
  let yPos = 55;

  // Title
  doc.setTextColor(15, 23, 42); // Slate-900
  doc.setFontSize(14);
  doc.setFont('helvetica', 'bold');
  doc.text('Resumen General', 15, yPos);

  yPos += 10;

  // Draw Boxes for KPIs
  const boxWidth = (pageWidth - 40) / 3;
  const boxHeight = 25;

  // Box 1: Ventas
  doc.setDrawColor(226, 232, 240);
  doc.setFillColor(248, 250, 252);
  doc.roundedRect(15, yPos, boxWidth, boxHeight, 3, 3, 'FD');
  doc.setFontSize(8);
  doc.setTextColor(100, 116, 139);
  doc.text('VENTAS BRUTAS', 20, yPos + 8);
  doc.setFontSize(12);
  doc.setTextColor(15, 23, 42);
  doc.setFont('helvetica', 'bold');
  doc.text(`$${data.totalGross.toLocaleString()}`, 20, yPos + 18);

  // Box 2: Ops
  doc.roundedRect(15 + boxWidth + 5, yPos, boxWidth, boxHeight, 3, 3, 'FD');
  doc.setFontSize(8);
  doc.setTextColor(100, 116, 139);
  doc.setFont('helvetica', 'normal');
  doc.text('TRANSACCIONES', 20 + boxWidth + 5, yPos + 8);
  doc.setFontSize(12);
  doc.setTextColor(15, 23, 42);
  doc.setFont('helvetica', 'bold');
  doc.text(`${data.totalTransactions}`, 20 + boxWidth + 5, yPos + 18);

  // Box 3: Ticket Prom
  doc.roundedRect(15 + (boxWidth * 2) + 10, yPos, boxWidth, boxHeight, 3, 3, 'FD');
  doc.setFontSize(8);
  doc.setTextColor(100, 116, 139);
  doc.setFont('helvetica', 'normal');
  doc.text('TICKET PROMEDIO', 20 + (boxWidth * 2) + 10, yPos + 8);
  doc.setFontSize(12);
  doc.setTextColor(15, 23, 42);
  doc.setFont('helvetica', 'bold');
  doc.text(`$${data.averageTicket.toFixed(2)}`, 20 + (boxWidth * 2) + 10, yPos + 18);

  yPos += 40;

  // --- PAYMENTS SECTION ---
  doc.setFontSize(12);
  doc.setTextColor(15, 23, 42);
  doc.text('Desglose de Ingresos', 15, yPos);

  yPos += 5;

  (doc as any).autoTable({
    startY: yPos,
    head: [['Método de Pago', 'Monto Recaudado']],
    body: [
      ['Efectivo', `$${data.payments.cash.toLocaleString()}`],
      ['Transferencia', `$${data.payments.transfer.toLocaleString()}`],
      ['TOTAL', `$${(data.payments.cash + data.payments.transfer).toLocaleString()}`]
    ],
    theme: 'striped',
    headStyles: { fillColor: [2, 132, 199] },
    styles: { fontSize: 10 },
    columnStyles: { 1: { halign: 'right', fontStyle: 'bold' } },
    foot: [['Balance', `$${(data.payments.cash + data.payments.transfer).toLocaleString()}`]],
    footStyles: { fillColor: [241, 245, 249], textColor: [15, 23, 42] }
  });

  yPos = (doc as any).lastAutoTable.finalY + 20;

  // --- PRODUCTS SECTION ---
  doc.text('Top Productos Vendidos', 15, yPos);
  yPos += 5;

  const productRows = data.topProducts.map(p => [
    p.name,
    p.qty.toString(),
    `$${p.total.toLocaleString()}`
  ]);

  (doc as any).autoTable({
    startY: yPos,
    head: [['Producto', 'Cantidad', 'Venta Total']],
    body: productRows,
    theme: 'grid',
    headStyles: { fillColor: [71, 85, 105] },
    columnStyles: { 
      1: { halign: 'center' },
      2: { halign: 'right' }
    }
  });

  // --- FOOTER ---
  const pageCount = (doc as any).internal.getNumberOfPages();
  for(let i = 1; i <= pageCount; i++) {
    doc.setPage(i);
    doc.setFontSize(8);
    doc.setTextColor(150);
    doc.text(`Aqua+ ERP - Documento Confidencial - Página ${i} de ${pageCount}`, pageWidth / 2, doc.internal.pageSize.height - 10, { align: 'center' });
  }

  // Return the Data URL string to be used in an iframe
  return doc.output('datauristring');
};

/**
 * Generates a Ticket PDF using pdf-lib and returns raw bytes
 */
export const generateTicketPDF = async (sale: Sale, config: TicketConfig): Promise<Uint8Array> => {
  // Crear nuevo documento PDF
  const pdfDoc = await PDFDocument.create();

  // Calcular altura dinámica base
  const baseHeight = 350; // Cabecera + Pie
  const itemsHeight = sale.items.length * 25; // 25pt por item
  const ticketHeight = baseHeight + itemsHeight;
  const ticketWidth = 280; // ~10cm o ticket ancho

  const page = pdfDoc.addPage([ticketWidth, ticketHeight]);

  // Obtener fuentes
  const fontRegular = await pdfDoc.embedFont(StandardFonts.Helvetica);
  const fontBold = await pdfDoc.embedFont(StandardFonts.HelveticaBold);
  const fontCourier = await pdfDoc.embedFont(StandardFonts.Courier); // Para líneas punteadas

  const { width, height } = page.getSize();
  let yPos = height - 20;

  const centerX = width / 2;
  const margin = 15;
  const contentWidth = width - (margin * 2);

  // --- HELPERS ---
  const drawCenteredText = (text: string, font: PDFFont, size: number, color = rgb(0,0,0)) => {
    const textWidth = font.widthOfTextAtSize(text, size);
    page.drawText(text, { x: centerX - (textWidth / 2), y: yPos, size, font, color });
    yPos -= (size + 4);
  };

  const drawLeftRight = (left: string, right: string, font: PDFFont, size: number, isBold = false) => {
    const rightWidth = font.widthOfTextAtSize(right, size);
    page.drawText(left, { x: margin, y: yPos, size, font });
    page.drawText(right, { x: width - margin - rightWidth, y: yPos, size, font: isBold ? fontBold : font });
    yPos -= (size + 6);
  };

  const drawDashedLine = () => {
    const dash = '- - - - - - - - - - - - - - - - - - - - - - - - - - - -';
    const textWidth = fontCourier.widthOfTextAtSize(dash, 10);
    // Centrar la línea
    page.drawText(dash, { x: centerX - (textWidth / 2), y: yPos, size: 10, font: fontCourier, color: rgb(0.5, 0.5, 0.5) });
    yPos -= 12;
  };

  // --- LOGO ---
  if (config.logoUrl && config.logoUrl.startsWith('data:image')) {
    try {
      // Extraer base64
      const base64Data = config.logoUrl.split(',')[1];
      const imageBytes = Uint8Array.from(atob(base64Data), c => c.charCodeAt(0));

      let logoImage;
      if (config.logoUrl.includes('image/png')) {
        logoImage = await pdfDoc.embedPng(imageBytes);
      } else {
        logoImage = await pdfDoc.embedJpg(imageBytes);
      }

      // Escalar logo manteniendo relación de aspecto
      const logoDims = logoImage.scale(1);
      const maxLogoWidth = 80;
      const scaleFactor = maxLogoWidth / logoDims.width;
      const scaledWidth = logoDims.width * scaleFactor;
      const scaledHeight = logoDims.height * scaleFactor;

      page.drawImage(logoImage, {
        x: centerX - (scaledWidth / 2),
        y: yPos - scaledHeight,
        width: scaledWidth,
        height: scaledHeight,
      });
      yPos -= (scaledHeight + 10);
    } catch (e) {
      console.warn("Error embedding logo", e);
    }
  } else {
    // Espacio si no hay logo
    yPos -= 10;
  }

  // --- HEADER ---
  drawCenteredText(config.businessName, fontBold, 16);
  if (config.slogan) drawCenteredText(`"${config.slogan}"`, fontRegular, 9, rgb(0.4, 0.4, 0.4));

  yPos -= 5;
  drawCenteredText(config.address, fontRegular, 9);
  drawCenteredText(`Tel: ${config.phone}`, fontRegular, 9);
  if (config.rfc) drawCenteredText(`RFC: ${config.rfc}`, fontRegular, 9);

  yPos -= 5;
  drawDashedLine();

  // --- META INFO ---
  drawLeftRight('Folio:', sale.id, fontRegular, 10, true);
  drawLeftRight('Fecha:', new Date(sale.timestamp).toLocaleDateString(), fontRegular, 10);
  drawLeftRight('Hora:', new Date(sale.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}), fontRegular, 10);
  drawLeftRight('Cliente:', sale.customerAlias.substring(0, 18), fontRegular, 10, true);

  yPos -= 5;

  // --- TABLE HEADER ---
  // Background rectangle for header
  page.drawRectangle({
    x: margin,
    y: yPos - 2,
    width: contentWidth,
    height: 14,
    color: rgb(0.9, 0.9, 0.9),
  });

  page.drawText('CANT', { x: margin + 5, y: yPos, size: 8, font: fontBold });
  page.drawText('DESCRIPCION', { x: margin + 45, y: yPos, size: 8, font: fontBold });
  const impHeaderWidth = fontBold.widthOfTextAtSize('IMPORTE', 8);
  page.drawText('IMPORTE', { x: width - margin - impHeaderWidth - 5, y: yPos, size: 8, font: fontBold });
  yPos -= 18;

  // --- ITEMS ---
  sale.items.forEach(item => {
    // Cantidad
    page.drawText(item.quantity.toString(), { x: margin + 8, y: yPos, size: 10, font: fontBold });

    // Descripción (Manejo de texto largo)
    const name = item.name.length > 20 ? item.name.substring(0, 20) + '...' : item.name;
    page.drawText(name, { x: margin + 45, y: yPos, size: 9, font: fontRegular });

    // Importe
    const totalItem = (item.quantity * item.price).toFixed(2);
    const totalItemWidth = fontRegular.widthOfTextAtSize(`$${totalItem}`, 10);
    page.drawText(`$${totalItem}`, { x: width - margin - totalItemWidth, y: yPos, size: 10, font: fontRegular });

    yPos -= 15;
  });

  drawDashedLine();

  // --- TOTALS ---
  // Alinear a la derecha
  const drawTotalLine = (label: string, value: string, isBig = false) => {
    const size = isBig ? 16 : 10;
    const font = isBig ? fontBold : fontRegular;
    const labelWidth = font.widthOfTextAtSize(label, size);
    const valueWidth = font.widthOfTextAtSize(value, size);

    // Dibujar label un poco a la izquierda
    const valueX = width - margin - valueWidth;
    const labelX = valueX - labelWidth - 10; // 10px padding

    page.drawText(label, { x: labelX, y: yPos, size, font });
    page.drawText(value, { x: valueX, y: yPos, size, font });
    yPos -= (size + 8);
  };

  drawTotalLine('TOTAL:', `$${sale.total.toFixed(2)}`, true);

  if (sale.paymentSplits && sale.paymentSplits.length > 0) {
     sale.paymentSplits.forEach(split => {
        drawTotalLine(`${split.method}:`, `$${split.amount.toFixed(2)}`);
     });
  } else {
     drawTotalLine('Su Pago:', `$${sale.paidAmount.toFixed(2)}`);
  }

  if (sale.change > 0) {
    drawTotalLine('Cambio:', `$${sale.change.toFixed(2)}`);
  } else if (sale.paidAmount < sale.total) {
    page.drawText('SALDO PENDIENTE', { x: margin, y: yPos + 5, size: 10, font: fontBold, color: rgb(1, 0, 0) }); // Red text visual trick (converted to grayscale usually) but shows importance
    drawTotalLine('RESTANTE:', `$${(sale.total - sale.paidAmount).toFixed(2)}`);
  }

  // --- GARRAFONES RETURNED ---
  if (sale.emptyGarrafonsReturned > 0) {
    yPos -= 5;
    page.drawRectangle({
      x: margin + 20,
      y: yPos - 5,
      width: contentWidth - 40,
      height: 25,
      borderColor: rgb(0, 0, 0),
      borderWidth: 1,
    });
    const text = `★ ${sale.emptyGarrafonsReturned} Envases Recibidos ★`;
    const textW = fontBold.widthOfTextAtSize(text, 10);
    page.drawText(text, { x: centerX - (textW/2), y: yPos + 5, size: 10, font: fontBold });
    yPos -= 25;
  }

  // --- FOOTER ---
  yPos -= 15;
  if (config.footerMessage) {
    // Dividir en líneas si es muy largo
    const words = config.footerMessage.split(' ');
    let line = '';
    for (const word of words) {
        const testLine = line + word + ' ';
        const testWidth = fontRegular.widthOfTextAtSize(testLine, 9);
        if (testWidth > contentWidth) {
            drawCenteredText(line, fontRegular, 9);
            line = word + ' ';
        } else {
            line = testLine;
        }
    }
    drawCenteredText(line, fontRegular, 9);
  }

  if (config.extraNote) {
    drawCenteredText(config.extraNote, fontRegular, 8, rgb(0.5, 0.5, 0.5));
  }

  drawCenteredText('*** GRACIAS POR SU PREFERENCIA ***', fontBold, 9);

  return await pdfDoc.save();
}

import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import { PDFDocument, StandardFonts, rgb, PDFFont } from 'pdf-lib';
import { TicketConfig, Sale } from '../types';

// Interface for the data expected by the report generator
interface ReportData {
  label: string;
  rangeType: string;
  totalGross: number;
  totalTransactions: number;
  averageTicket: number;
  payments: { cash: number; transfer: number };
  topProducts: { name: string; qty: number; total: number }[];
}

export const generateFinancialPDF = (data: ReportData, config: TicketConfig): string => {
  const doc = new jsPDF();
  const pageWidth = doc.internal.pageSize.width;

  // --- HEADER ---
  doc.setFillColor(2, 132, 199); // Sky-600
  doc.rect(0, 0, pageWidth, 40, 'F');

  doc.setTextColor(255, 255, 255);
  doc.setFontSize(22);
  doc.setFont('helvetica', 'bold');
  doc.text(config.businessName, 15, 15);

  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');
  doc.text('REPORTE FINANCIERO', 15, 22);
  doc.text(`Generado: ${new Date().toLocaleString()}`, 15, 27);

  // Right side header info
  doc.setFontSize(10);
  doc.text(`Periodo: ${data.label}`, pageWidth - 15, 15, { align: 'right' });
  doc.text(`Tipo: ${data.rangeType.toUpperCase()}`, pageWidth - 15, 20, { align: 'right' });

  // --- KPI CARDS (Simulated) ---
  let yPos = 55;

  // Title
  doc.setTextColor(15, 23, 42); // Slate-900
  doc.setFontSize(14);
  doc.setFont('helvetica', 'bold');
  doc.text('Resumen General', 15, yPos);

  yPos += 10;

  // Draw Boxes for KPIs
  const boxWidth = (pageWidth - 40) / 3;
  const boxHeight = 25;

  // Box 1: Ventas
  doc.setDrawColor(226, 232, 240);
  doc.setFillColor(248, 250, 252);
  doc.roundedRect(15, yPos, boxWidth, boxHeight, 3, 3, 'FD');
  doc.setFontSize(8);
  doc.setTextColor(100, 116, 139);
  doc.text('VENTAS BRUTAS', 20, yPos + 8);
  doc.setFontSize(12);
  doc.setTextColor(15, 23, 42);
  doc.setFont('helvetica', 'bold');
  doc.text(`$${data.totalGross.toLocaleString()}`, 20, yPos + 18);

  // Box 2: Ops
  doc.roundedRect(15 + boxWidth + 5, yPos, boxWidth, boxHeight, 3, 3, 'FD');
  doc.setFontSize(8);
  doc.setTextColor(100, 116, 139);
  doc.setFont('helvetica', 'normal');
  doc.text('TRANSACCIONES', 20 + boxWidth + 5, yPos + 8);
  doc.setFontSize(12);
  doc.setTextColor(15, 23, 42);
  doc.setFont('helvetica', 'bold');
  doc.text(`${data.totalTransactions}`, 20 + boxWidth + 5, yPos + 18);

  // Box 3: Ticket Prom
  doc.roundedRect(15 + (boxWidth * 2) + 10, yPos, boxWidth, boxHeight, 3, 3, 'FD');
  doc.setFontSize(8);
  doc.setTextColor(100, 116, 139);
  doc.setFont('helvetica', 'normal');
  doc.text('TICKET PROMEDIO', 20 + (boxWidth * 2) + 10, yPos + 8);
  doc.setFontSize(12);
  doc.setTextColor(15, 23, 42);
  doc.setFont('helvetica', 'bold');
  doc.text(`$${data.averageTicket.toFixed(2)}`, 20 + (boxWidth * 2) + 10, yPos + 18);

  yPos += 40;

  // --- PAYMENTS SECTION ---
  doc.setFontSize(12);
  doc.setTextColor(15, 23, 42);
  doc.text('Desglose de Ingresos', 15, yPos);

  yPos += 5;

  (doc as any).autoTable({
    startY: yPos,
    head: [['Método de Pago', 'Monto Recaudado']],
    body: [
      ['Efectivo', `$${data.payments.cash.toLocaleString()}`],
      ['Transferencia', `$${data.payments.transfer.toLocaleString()}`],
      ['TOTAL', `$${(data.payments.cash + data.payments.transfer).toLocaleString()}`]
    ],
    theme: 'striped',
    headStyles: { fillColor: [2, 132, 199] },
    styles: { fontSize: 10 },
    columnStyles: { 1: { halign: 'right', fontStyle: 'bold' } },
    foot: [['Balance', `$${(data.payments.cash + data.payments.transfer).toLocaleString()}`]],
    footStyles: { fillColor: [241, 245, 249], textColor: [15, 23, 42] }
  });

  yPos = (doc as any).lastAutoTable.finalY + 20;

  // --- PRODUCTS SECTION ---
  doc.text('Top Productos Vendidos', 15, yPos);
  yPos += 5;

  const productRows = data.topProducts.map(p => [
    p.name,
    p.qty.toString(),
    `$${p.total.toLocaleString()}`
  ]);

  (doc as any).autoTable({
    startY: yPos,
    head: [['Producto', 'Cantidad', 'Venta Total']],
    body: productRows,
    theme: 'grid',
    headStyles: { fillColor: [71, 85, 105] },
    columnStyles: { 
      1: { halign: 'center' },
      2: { halign: 'right' }
    }
  });

  // --- FOOTER ---
  const pageCount = (doc as any).internal.getNumberOfPages();
  for(let i = 1; i <= pageCount; i++) {
    doc.setPage(i);
    doc.setFontSize(8);
    doc.setTextColor(150);
    doc.text(`Aqua+ ERP - Documento Confidencial - Página ${i} de ${pageCount}`, pageWidth / 2, doc.internal.pageSize.height - 10, { align: 'center' });
  }

  // Return the Data URL string to be used in an iframe
  return doc.output('datauristring');
};

/**
 * Generates a Ticket PDF using pdf-lib and returns raw bytes
 */
export const generateTicketPDF = async (sale: Sale, config: TicketConfig): Promise<Uint8Array> => {
  // Crear nuevo documento PDF
  const pdfDoc = await PDFDocument.create();

  // Calcular altura dinámica base
  const baseHeight = 350; // Cabecera + Pie
  const itemsHeight = sale.items.length * 25; // 25pt por item
  const ticketHeight = baseHeight + itemsHeight;
  const ticketWidth = 280; // ~10cm o ticket ancho

  const page = pdfDoc.addPage([ticketWidth, ticketHeight]);

  // Obtener fuentes
  const fontRegular = await pdfDoc.embedFont(StandardFonts.Helvetica);
  const fontBold = await pdfDoc.embedFont(StandardFonts.HelveticaBold);
  const fontCourier = await pdfDoc.embedFont(StandardFonts.Courier); // Para líneas punteadas

  const { width, height } = page.getSize();
  let yPos = height - 20;

  const centerX = width / 2;
  const margin = 15;
  const contentWidth = width - (margin * 2);

  // --- HELPERS ---
  const drawCenteredText = (text: string, font: PDFFont, size: number, color = rgb(0,0,0)) => {
    const textWidth = font.widthOfTextAtSize(text, size);
    page.drawText(text, { x: centerX - (textWidth / 2), y: yPos, size, font, color });
    yPos -= (size + 4);
  };

  const drawLeftRight = (left: string, right: string, font: PDFFont, size: number, isBold = false) => {
    const rightWidth = font.widthOfTextAtSize(right, size);
    page.drawText(left, { x: margin, y: yPos, size, font });
    page.drawText(right, { x: width - margin - rightWidth, y: yPos, size, font: isBold ? fontBold : font });
    yPos -= (size + 6);
  };

  const drawDashedLine = () => {
    const dash = '- - - - - - - - - - - - - - - - - - - - - - - - - - - -';
    const textWidth = fontCourier.widthOfTextAtSize(dash, 10);
    // Centrar la línea
    page.drawText(dash, { x: centerX - (textWidth / 2), y: yPos, size: 10, font: fontCourier, color: rgb(0.5, 0.5, 0.5) });
    yPos -= 12;
  };

  // --- LOGO ---
  if (config.logoUrl && config.logoUrl.startsWith('data:image')) {
    try {
      // Extraer base64
      const base64Data = config.logoUrl.split(',')[1];
      const imageBytes = Uint8Array.from(atob(base64Data), c => c.charCodeAt(0));

      let logoImage;
      if (config.logoUrl.includes('image/png')) {
        logoImage = await pdfDoc.embedPng(imageBytes);
      } else {
        logoImage = await pdfDoc.embedJpg(imageBytes);
      }

      // Escalar logo manteniendo relación de aspecto
      const logoDims = logoImage.scale(1);
      const maxLogoWidth = 80;
      const scaleFactor = maxLogoWidth / logoDims.width;
      const scaledWidth = logoDims.width * scaleFactor;
      const scaledHeight = logoDims.height * scaleFactor;

      page.drawImage(logoImage, {
        x: centerX - (scaledWidth / 2),
        y: yPos - scaledHeight,
        width: scaledWidth,
        height: scaledHeight,
      });
      yPos -= (scaledHeight + 10);
    } catch (e) {
      console.warn("Error embedding logo", e);
    }
  } else {
    // Espacio si no hay logo
    yPos -= 10;
  }

  // --- HEADER ---
  drawCenteredText(config.businessName, fontBold, 16);
  if (config.slogan) drawCenteredText(`"${config.slogan}"`, fontRegular, 9, rgb(0.4, 0.4, 0.4));

  yPos -= 5;
  drawCenteredText(config.address, fontRegular, 9);
  drawCenteredText(`Tel: ${config.phone}`, fontRegular, 9);
  if (config.rfc) drawCenteredText(`RFC: ${config.rfc}`, fontRegular, 9);

  yPos -= 5;
  drawDashedLine();

  // --- META INFO ---
  drawLeftRight('Folio:', sale.id, fontRegular, 10, true);
  drawLeftRight('Fecha:', new Date(sale.timestamp).toLocaleDateString(), fontRegular, 10);
  drawLeftRight('Hora:', new Date(sale.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}), fontRegular, 10);
  drawLeftRight('Cliente:', sale.customerAlias.substring(0, 18), fontRegular, 10, true);

  yPos -= 5;

  // --- TABLE HEADER ---
  // Background rectangle for header
  page.drawRectangle({
    x: margin,
    y: yPos - 2,
    width: contentWidth,
    height: 14,
    color: rgb(0.9, 0.9, 0.9),
  });

  page.drawText('CANT', { x: margin + 5, y: yPos, size: 8, font: fontBold });
  page.drawText('DESCRIPCION', { x: margin + 45, y: yPos, size: 8, font: fontBold });
  const impHeaderWidth = fontBold.widthOfTextAtSize('IMPORTE', 8);
  page.drawText('IMPORTE', { x: width - margin - impHeaderWidth - 5, y: yPos, size: 8, font: fontBold });
  yPos -= 18;

  // --- ITEMS ---
  sale.items.forEach(item => {
    // Cantidad
    page.drawText(item.quantity.toString(), { x: margin + 8, y: yPos, size: 10, font: fontBold });

    // Descripción (Manejo de texto largo)
    const name = item.name.length > 20 ? item.name.substring(0, 20) + '...' : item.name;
    page.drawText(name, { x: margin + 45, y: yPos, size: 9, font: fontRegular });

    // Importe
    const totalItem = (item.quantity * item.price).toFixed(2);
    const totalItemWidth = fontRegular.widthOfTextAtSize(`$${totalItem}`, 10);
    page.drawText(`$${totalItem}`, { x: width - margin - totalItemWidth, y: yPos, size: 10, font: fontRegular });

    yPos -= 15;
  });

  drawDashedLine();

  // --- TOTALS ---
  // Alinear a la derecha
  const drawTotalLine = (label: string, value: string, isBig = false) => {
    const size = isBig ? 16 : 10;
    const font = isBig ? fontBold : fontRegular;
    const labelWidth = font.widthOfTextAtSize(label, size);
    const valueWidth = font.widthOfTextAtSize(value, size);

    // Dibujar label un poco a la izquierda
    const valueX = width - margin - valueWidth;
    const labelX = valueX - labelWidth - 10; // 10px padding

    page.drawText(label, { x: labelX, y: yPos, size, font });
    page.drawText(value, { x: valueX, y: yPos, size, font });
    yPos -= (size + 8);
  };

  drawTotalLine('TOTAL:', `$${sale.total.toFixed(2)}`, true);

  if (sale.paymentSplits && sale.paymentSplits.length > 0) {
     sale.paymentSplits.forEach(split => {
        drawTotalLine(`${split.method}:`, `$${split.amount.toFixed(2)}`);
     });
  } else {
     drawTotalLine('Su Pago:', `$${sale.paidAmount.toFixed(2)}`);
  }

  if (sale.change > 0) {
    drawTotalLine('Cambio:', `$${sale.change.toFixed(2)}`);
  } else if (sale.paidAmount < sale.total) {
    page.drawText('SALDO PENDIENTE', { x: margin, y: yPos + 5, size: 10, font: fontBold, color: rgb(1, 0, 0) }); // Red text visual trick (converted to grayscale usually) but shows importance
    drawTotalLine('RESTANTE:', `$${(sale.total - sale.paidAmount).toFixed(2)}`);
  }

  // --- GARRAFONES RETURNED ---
  if (sale.emptyGarrafonsReturned > 0) {
    yPos -= 5;
    page.drawRectangle({
      x: margin + 20,
      y: yPos - 5,
      width: contentWidth - 40,
      height: 25,
      borderColor: rgb(0, 0, 0),
      borderWidth: 1,
    });
    // Replace unsupported '★' with '*'
    const text = `* ${sale.emptyGarrafonsReturned} Envases Recibidos *`;
    const textW = fontBold.widthOfTextAtSize(text, 10);
    page.drawText(text, { x: centerX - (textW/2), y: yPos + 5, size: 10, font: fontBold });
    yPos -= 25;
  }

  // --- FOOTER ---
  yPos -= 15;
  if (config.footerMessage) {
    // Dividir en líneas si es muy largo
    const words = config.footerMessage.split(' ');
    let line = '';
    for (const word of words) {
        const testLine = line + word + ' ';
        const testWidth = fontRegular.widthOfTextAtSize(testLine, 9);
        if (testWidth > contentWidth) {
            drawCenteredText(line, fontRegular, 9);
            line = word + ' ';
        } else {
            line = testLine;
        }
    }
    drawCenteredText(line, fontRegular, 9);
  }

  if (config.extraNote) {
    drawCenteredText(config.extraNote, fontRegular, 8, rgb(0.5, 0.5, 0.5));
  }

  drawCenteredText('*** GRACIAS POR SU PREFERENCIA ***', fontBold, 9);

  return await pdfDoc.save();
}

