  id: string;
  name: string;
  price: number;
  stock: number;
  category?: 'Agua' | 'Insumos' | 'Accesorios';
}

export type GarrafonType = 'Aqua' | 'Bonafont' | 'Ciel' | 'E-Pura' | 'Generico';

export interface Customer {
  id: string;
  name: string;
  alias: string;
  address?: string; // New field
  phone?: string;
  specialPrice?: number;
  lat?: number;
  lng?: number;
  garrafonType?: GarrafonType;
  balance: number;
}

export interface TicketConfig {
  businessName: string;
  rfc: string;
  address: string;
  phone: string;
  footerMessage: string;
  logoUrl?: string;
  website?: string;
  socialMedia?: string;
  extraNote?: string;
