        ? currentRoles.filter(r => r !== role)
        : [...currentRoles, role];
    setEditingEmployee({ ...editingEmployee, roles: newRoles });
  };

  const handleAddTask = (preset: typeof TASK_PRESETS[0] | { title: string, desc: string }) => {
