        addTask({
          id: `AUTO-${Date.now()}-${count++}`,
          employeeId: e.id,
          title: 'Ruta de Reparto',
          description: 'Entrega a clientes programados',
          date: today
        });
      } 

      if (e.roles.includes('Planta')) {
        addTask({
          id: `AUTO-${Date.now()}-${count++}`,
          employeeId: e.id,
          title: 'Apertura y Limpieza',
          description: 'Protocolo de higiene inicial',
          date: today
        });
        addTask({
          id: `AUTO-${Date.now()}-${count++}`,
          employeeId: e.id,
          title: 'Producción',
          description: 'Supervisión de llenado y calidad',
          date: today
        });
      }
