                     <h4 className="font-black text-sky-900 text-sm leading-tight">{p.name}</h4>
                     <span className="text-[9px] font-bold text-sky-400 uppercase tracking-widest">{p.category || 'Agua'}</span>
                  </div>
               </div>

               {/* Quick stock adjustment controls */}
               <div className="flex items-center gap-2 bg-sky-50/50 p-1.5 rounded-2xl ml-4">
                 <button 
                  onClick={(e) => { e.stopPropagation(); adjustStock(p, -1); }}
                  className="w-8 h-8 bg-white shadow-sm text-sky-600 rounded-xl flex items-center justify-center font-black active:scale-90 transition-all"
                 >
                   -
                 </button>
                 <div className="text-center min-w-[30px]" onClick={() => setEditingProduct(p)}>
                    <span className={`text-xl font-black block leading-none ${p.stock < 15 ? 'text-rose-500' : 'text-sky-900'}`}>{p.stock}</span>
                 </div>
                 <button 
                  onClick={(e) => { e.stopPropagation(); adjustStock(p, 1); }}
                  className="w-8 h-8 bg-sky-600 text-white shadow-md rounded-xl flex items-center justify-center font-black active:scale-90 transition-all"
                 >
                   +
                 </button>
               </div>
            </div>

            <div className="mt-4 pt-3 border-t border-sky-50 flex justify-between items-center">
               {/* Inline Price Edit */}
               <div className="flex items-center gap-2">
                 <span className="text-[10px] font-black text-sky-400 uppercase tracking-widest">Precio: $</span>
                 <input 
                    type="number" 
                    className="w-16 bg-sky-50 rounded-lg px-2 py-1 text-sm font-black text-sky-900 outline-none focus:ring-1 ring-sky-300 transition-all"
                    defaultValue={p.price}
                    onBlur={(e) => handlePriceChange(p, e.target.value)}
                    onKeyDown={(e) => {
                      if (e.key === 'Enter') {
                        e.currentTarget.blur();
                      }
                    }}
                    onClick={(e) => e.stopPropagation()} 
                 />
                 <i className="fas fa-pen text-[8px] text-sky-300"></i>
               </div>

               <div className="flex items-center gap-1" onClick={() => setEditingProduct(p)}>
                 <div className={`w-1.5 h-1.5 rounded-full ${p.stock < 15 ? 'bg-rose-500 animate-pulse' : 'bg-emerald-500'}`}></div>
                 <span className={`text-[8px] font-black uppercase ${p.stock < 15 ? 'text-rose-500' : 'text-emerald-500'}`}>
                    {p.stock < 15 ? 'Stock Crítico' : 'Stock Saludable'}
                 </span>
               </div>
            </div>
          </RoundedCard>
        ))}

        <button 
          onClick={() => setEditingProduct({ category: 'Agua', stock: 0, price: 0 })}
          className="w-full py-6 border-2 border-dashed border-violet-200 rounded-[2.5rem] text-violet-400 font-black text-sm uppercase hover:bg-white transition-all"
        >
          + Agregar Nuevo Producto
        </button>
      </div>
    </div>
  );
};

import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import { PDFDocument, StandardFonts, rgb, PDFFont } from 'pdf-lib';
import { TicketConfig, Sale, Task, Employee } from '../types';

// Interface for the data expected by the report generator
interface ReportData {
  label: string;
  rangeType: string;
  totalGross: number;
  totalTransactions: number;
  averageTicket: number;
  payments: { cash: number; transfer: number };
  topProducts: { name: string; qty: number; total: number }[];
}

interface TaskReportData {
  label: string;
  rangeType: string;
  totalTasks: number;
  completedTasks: number;
  pendingTasks: number;
  byEmployee: { id: string; name: string; completed: number; total: number; tasks: Task[] }[];
}

// Helper to convert hex to rgb 0-1 range
const hexToRgbScale = (hex: string) => {
  const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
  return result ? {
    r: parseInt(result[1], 16) / 255,
    g: parseInt(result[2], 16) / 255,
    b: parseInt(result[3], 16) / 255
  } : { r: 0, g: 0, b: 0 };
};

export const generateFinancialPDF = (data: ReportData, config: TicketConfig): string => {
  const doc = new jsPDF();
  const pageWidth = doc.internal.pageSize.width;

  // --- HEADER ---
  doc.setFillColor(2, 132, 199); // Sky-600
  doc.rect(0, 0, pageWidth, 40, 'F');

  doc.setTextColor(255, 255, 255);
  doc.setFontSize(22);
  doc.setFont('helvetica', 'bold');
  doc.text(config.businessName, 15, 15);

  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');
  doc.text('REPORTE FINANCIERO', 15, 22);
  doc.text(`Generado: ${new Date().toLocaleString()}`, 15, 27);

  // Right side header info
  doc.setFontSize(10);
  doc.text(`Periodo: ${data.label}`, pageWidth - 15, 15, { align: 'right' });
  doc.text(`Tipo: ${data.rangeType.toUpperCase()}`, pageWidth - 15, 20, { align: 'right' });

  // --- KPI CARDS (Simulated) ---
  let yPos = 55;

  // Title
  doc.setTextColor(15, 23, 42); // Slate-900
  doc.setFontSize(14);
  doc.setFont('helvetica', 'bold');
  doc.text('Resumen General', 15, yPos);

  yPos += 10;

  // Draw Boxes for KPIs
  const boxWidth = (pageWidth - 40) / 3;
  const boxHeight = 25;

  // Box 1: Ventas
  doc.setDrawColor(226, 232, 240);
  doc.setFillColor(248, 250, 252);
  doc.roundedRect(15, yPos, boxWidth, boxHeight, 3, 3, 'FD');
  doc.setFontSize(8);
  doc.setTextColor(100, 116, 139);
  doc.text('VENTAS BRUTAS', 20, yPos + 8);
  doc.setFontSize(12);
  doc.setTextColor(15, 23, 42);
  doc.setFont('helvetica', 'bold');
  doc.text(`$${data.totalGross.toLocaleString()}`, 20, yPos + 18);

  // Box 2: Ops
  doc.roundedRect(15 + boxWidth + 5, yPos, boxWidth, boxHeight, 3, 3, 'FD');
  doc.setFontSize(8);
  doc.setTextColor(100, 116, 139);
  doc.setFont('helvetica', 'normal');
  doc.text('TRANSACCIONES', 20 + boxWidth + 5, yPos + 8);
  doc.setFontSize(12);
  doc.setTextColor(15, 23, 42);
  doc.setFont('helvetica', 'bold');
  doc.text(`${data.totalTransactions}`, 20 + boxWidth + 5, yPos + 18);

  // Box 3: Ticket Prom
  doc.roundedRect(15 + (boxWidth * 2) + 10, yPos, boxWidth, boxHeight, 3, 3, 'FD');
  doc.setFontSize(8);
  doc.setTextColor(100, 116, 139);
  doc.setFont('helvetica', 'normal');
  doc.text('TICKET PROMEDIO', 20 + (boxWidth * 2) + 10, yPos + 8);
  doc.setFontSize(12);
  doc.setTextColor(15, 23, 42);
  doc.setFont('helvetica', 'bold');
  doc.text(`$${data.averageTicket.toFixed(2)}`, 20 + (boxWidth * 2) + 10, yPos + 18);

  yPos += 40;

  // --- PAYMENTS SECTION ---
  doc.setFontSize(12);
  doc.setTextColor(15, 23, 42);
  doc.text('Desglose de Ingresos', 15, yPos);

  yPos += 5;

  (doc as any).autoTable({
    startY: yPos,
    head: [['Método de Pago', 'Monto Recaudado']],
    body: [
      ['Efectivo', `$${data.payments.cash.toLocaleString()}`],
      ['Transferencia', `$${data.payments.transfer.toLocaleString()}`],
      ['TOTAL', `$${(data.payments.cash + data.payments.transfer).toLocaleString()}`]
    ],
    theme: 'striped',
    headStyles: { fillColor: [2, 132, 199] },
    styles: { fontSize: 10 },
    columnStyles: { 1: { halign: 'right', fontStyle: 'bold' } },
    foot: [['Balance', `$${(data.payments.cash + data.payments.transfer).toLocaleString()}`]],
    footStyles: { fillColor: [241, 245, 249], textColor: [15, 23, 42] }
  });

  yPos = (doc as any).lastAutoTable.finalY + 20;

  // --- PRODUCTS SECTION ---
  doc.text('Top Productos Vendidos', 15, yPos);
  yPos += 5;

  const productRows = data.topProducts.map(p => [
    p.name,
    p.qty.toString(),
    `$${p.total.toLocaleString()}`
  ]);

  (doc as any).autoTable({
    startY: yPos,
    head: [['Producto', 'Cantidad', 'Venta Total']],
    body: productRows,
    theme: 'grid',
    headStyles: { fillColor: [71, 85, 105] },
    columnStyles: { 
      1: { halign: 'center' },
      2: { halign: 'right' }
    }
  });

  // --- FOOTER ---
  const pageCount = (doc as any).internal.getNumberOfPages();
  for(let i = 1; i <= pageCount; i++) {
    doc.setPage(i);
    doc.setFontSize(8);
    doc.setTextColor(150);
    doc.text(`Aqua+ ERP - Documento Confidencial - Página ${i} de ${pageCount}`, pageWidth / 2, doc.internal.pageSize.height - 10, { align: 'center' });
  }

  // Return the Data URL string to be used in an iframe
  return doc.output('datauristring');
};

export const generateTaskReportPDF = (data: TaskReportData, config: TicketConfig): string => {
  const doc = new jsPDF();
