export const ReportsModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const { sales, savedReports, addSavedReport, deleteSavedReport, ticketConfig, tasks, employees } = useERPData();
  const [activeTab, setActiveTab] = useState<'live' | 'history'>('live');
  const [reportType, setReportType] = useState<ReportType>('financial');
  const [timeRange, setTimeRange] = useState<TimeRange>('day');

  // Estado para ver un reporte guardado especifico
  const [viewingReport, setViewingReport] = useState<SavedReport | null>(null);

  // Estado para el visor de PDF
  const [pdfUrl, setPdfUrl] = useState<string | null>(null);

  // --- LOGICA DE PROCESAMIENTO FINANCIERO ---
  const processSalesData = (salesToProcess: Sale[], label: string): DashboardData => {
    const totalGross = salesToProcess.reduce((acc, s) => acc + (s.total || 0), 0);
    const payments = { cash: 0, transfer: 0 };
    const productStats: Record<string, { qty: number, total: number }> = {};

    salesToProcess.forEach(s => {
      // Safe payments breakdown
      if (s.paymentSplits && Array.isArray(s.paymentSplits)) {
        s.paymentSplits.forEach(p => {
          if(p.method === 'Efectivo') payments.cash += (p.amount || 0);
          if(p.method === 'Transferencia') payments.transfer += (p.amount || 0);
        });
      } else if (s.paidAmount > 0) {
        payments.cash += s.paidAmount;
      }

      // Safe items breakdown
      if (s.items && Array.isArray(s.items)) {
        s.items.forEach(item => {
          const name = item.name || 'Producto';
          if (!productStats[name]) productStats[name] = { qty: 0, total: 0 };
          productStats[name].qty += (item.quantity || 0);
          productStats[name].total += (item.quantity || 0) * (item.price || 0);
        });
      }
    });

    const topProducts = Object.entries(productStats)
      .map(([name, stats]) => ({ name, ...stats }))
      .sort((a, b) => b.qty - a.qty)
      .slice(0, 5);

    const maxQty = Math.max(...Object.values(productStats).map(s => s.qty), 1);
    const averageTicket = salesToProcess.length > 0 ? totalGross / salesToProcess.length : 0;

    return {
      totalGross,
      totalTransactions: salesToProcess.length,
      averageTicket,
      payments,
      topProducts,
      maxQty,
      label
    };
  };

  // --- LOGICA DE PROCESAMIENTO OPERATIVO ---
  const processTaskData = (tasksToProcess: Task[], label: string): TaskDashboardData => {
    const employeeStats: Record<string, { completed: number, total: number, tasks: Task[] }> = {};

    tasksToProcess.forEach(t => {
      if (!employeeStats[t.employeeId]) {
        employeeStats[t.employeeId] = { completed: 0, total: 0, tasks: [] };
      }
      employeeStats[t.employeeId].total++;
      employeeStats[t.employeeId].tasks.push(t);
      if (t.status === 'completada') {
        employeeStats[t.employeeId].completed++;
      }
    });

    const byEmployee = Object.entries(employeeStats).map(([id, stats]) => ({
      id,
      name: employees.find(e => e.id === id)?.name || 'Desconocido',
      ...stats
    }));

    return {
      totalTasks: tasksToProcess.length,
      completedTasks: tasksToProcess.filter(t => t.status === 'completada').length,
      pendingTasks: tasksToProcess.filter(t => t.status === 'pendiente').length,
      byEmployee,
      label
    };
  };

  // --- DATOS EN VIVO (FILTERED) ---
  const timeFilter = useMemo(() => {
    const now = new Date();
    let startTime = 0;
    // Simple filter: start of day/week/month
    if (timeRange === 'day') {
      startTime = new Date(now.setHours(0,0,0,0)).getTime();
    } else if (timeRange === 'week') {
      const day = now.getDay(); 
      const diff = now.getDate() - day + (day === 0 ? -6 : 1); 
      const monday = new Date(now.setDate(diff));
      startTime = new Date(monday.setHours(0,0,0,0)).getTime();
    } else if (timeRange === 'month') {
      startTime = new Date(now.getFullYear(), now.getMonth(), 1).getTime();
    }
    return startTime;
  }, [timeRange]);

  const liveFilteredSales = useMemo(() => {
    return sales.filter(s => s.timestamp >= timeFilter);
  }, [sales, timeFilter]);

  const liveFilteredTasks = useMemo(() => {
    // Tasks store date as YYYY-MM-DD string or timestamp? 
    // In Types Task has 'date' string YYYY-MM-DD. We need to filter by that string.
    // Converting timeFilter timestamp back to YYYY-MM-DD for simple comparison (Tasks don't have full timestamp usually in this app logic yet, but let's assume 'date' field is primary)

    // Simplification for 'Tasks': They store YYYY-MM-DD in `date` field.
    // We will filter tasks that match the date string range.
    return tasks.filter(t => {
       const taskDate = new Date(t.date); // Treat YYYY-MM-DD as UTC midnight or local
       // Add 'T00:00' to ensure parsing consistency if needed, but simple string compare is often safer for strict dates
       // Let's use simple logic:
       const taskTs = new Date(t.date + 'T00:00:00').getTime(); 
       // Adjust timeFilter (which is local midnight) to compare properly
       return taskTs >= timeFilter; 
    });
  }, [tasks, timeFilter]);

  const liveData = processSalesData(liveFilteredSales, timeRange === 'day' ? 'Hoy' : timeRange === 'week' ? 'Esta Semana' : 'Este Mes');
  const taskData = processTaskData(liveFilteredTasks, timeRange === 'day' ? 'Hoy' : timeRange === 'week' ? 'Esta Semana' : 'Este Mes');

  const handleSaveSnapshot = () => {
    if (reportType === 'operational') return alert("El historial de reportes operativos se gestiona automáticamente en Bitácoras."); // Placeholder logic

    if (liveFilteredSales.length === 0) {
      alert("No hay datos para guardar en este reporte.");
      return;
    }

    if(!confirm(`¿Guardar reporte de ${timeRange === 'day' ? 'Hoy' : timeRange === 'week' ? 'Esta Semana' : 'Este Mes'} en el historial?`)) return;

    const dateLabel = new Date().toLocaleDateString('es-MX', {
      day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute:'2-digit'
    });

    const newReport: SavedReport = {
      id: `REP-${Date.now()}`,
      timestamp: Date.now(),
      rangeType: timeRange,
      dateLabel: dateLabel,
      totalGross: liveData.totalGross,
      totalTransactions: liveData.totalTransactions,
      averageTicket: liveData.averageTicket,
      payments: liveData.payments,
      topProducts: liveData.topProducts,
    };

    addSavedReport(newReport);
    setActiveTab('history');
  };

  const handleGeneratePDF = () => {
    try {
      let url = '';
      if (reportType === 'financial') {
        const reportData = {
          ...liveData,
          rangeType: timeRange
        };
        url = generateFinancialPDF(reportData, ticketConfig);
      } else {
        const reportData = {
          ...taskData,
          rangeType: timeRange
        };
        url = generateTaskReportPDF(reportData, ticketConfig);
      }
      setPdfUrl(url);
    } catch (e) {
      console.error(e);
      alert("Error generando PDF");
    }
  };

  // --- VISTA DETALLADA DE HISTORIAL ---
  if (viewingReport) {
    const historicData: DashboardData = {
      totalGross: viewingReport.totalGross,
      totalTransactions: viewingReport.totalTransactions,
      averageTicket: viewingReport.averageTicket,
      payments: viewingReport.payments,
      topProducts: viewingReport.topProducts,
      maxQty: Math.max(...viewingReport.topProducts.map(p => p.qty), 1),
      label: viewingReport.dateLabel
    };

    return (
      <div className="h-full bg-sky-50 overflow-y-auto pb-32 no-scrollbar animate-fadeIn">
         <ModuleHeader title="Detalle de Reporte" onBack={() => setViewingReport(null)} />
         <div className="px-6 space-y-4">
           <div className="bg-sky-600 text-white p-4 rounded-3xl flex justify-between items-center shadow-lg shadow-sky-200">
              <div>
                 <span className="text-[10px] font-black uppercase opacity-60">Fecha de Corte</span>
                 <p className="font-bold text-sm">{viewingReport.dateLabel}</p>
                 <span className="bg-white/20 text-[9px] px-2 py-0.5 rounded uppercase font-black mt-1 inline-block">
                    Tipo: {viewingReport.rangeType === 'day' ? 'Diario' : viewingReport.rangeType === 'week' ? 'Semanal' : 'Mensual'}
                 </span>
              </div>
              <div className="flex gap-2">
                <button 
                  onClick={() => {
                     const url = generateFinancialPDF({...historicData, rangeType: viewingReport.rangeType}, ticketConfig);
                     setPdfUrl(url);
                  }}
                  className="w-10 h-10 bg-white/20 rounded-full flex items-center justify-center text-white active:scale-95 transition-all"
                  title="Exportar PDF"
                >
                  <i className="fas fa-file-pdf"></i>
                </button>
                <button 
                   onClick={() => {
                      if(confirm("¿Eliminar este reporte permanentemente?")) {
                         deleteSavedReport(viewingReport.id);
                         setViewingReport(null);
                      }
                   }}
                   className="w-10 h-10 bg-white/10 rounded-full flex items-center justify-center text-white active:bg-red-500 transition-colors"
                >
                  <i className="fas fa-trash-can"></i>
                </button>
              </div>
           </div>

           <ReportDashboard data={historicData} />
         </div>
         {pdfUrl && <PDFReaderModal url={pdfUrl} onClose={() => setPdfUrl(null)} />}
      </div>
    );
  }

  return (
    <div className="h-full bg-sky-50 overflow-y-auto pb-32 no-scrollbar">
      <ModuleHeader title="Reportes y Finanzas" onBack={onBack} />

      <div className="px-6 flex gap-2 mb-4 shrink-0">
        <button onClick={() => setActiveTab('live')} className={`flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'live' ? 'bg-sky-600 text-white shadow-lg' : 'bg-white text-sky-400'}`}>Análisis en Vivo</button>
        <button onClick={() => setActiveTab('history')} className={`flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'history' ? 'bg-sky-600 text-white shadow-lg' : 'bg-white text-sky-400'}`}>Historial</button>
      </div>

      <div className="px-6 space-y-6">
        {activeTab === 'live' && (
          <>
            <div className="flex bg-white p-1.5 rounded-[2rem] shadow-sm mb-2">
              <button onClick={() => setReportType('financial')} className={`flex-1 py-3 rounded-[1.5rem] text-[10px] font-black uppercase tracking-widest transition-all ${reportType === 'financial' ? 'bg-indigo-500 text-white shadow-md' : 'text-indigo-300'}`}>
                 <i className="fas fa-coins mr-1"></i> Finanzas
              </button>
              <button onClick={() => setReportType('operational')} className={`flex-1 py-3 rounded-[1.5rem] text-[10px] font-black uppercase tracking-widest transition-all ${reportType === 'operational' ? 'bg-amber-500 text-white shadow-md' : 'text-amber-300'}`}>
                 <i className="fas fa-list-check mr-1"></i> Operaciones
              </button>
            </div>

            <div className="flex bg-white p-1.5 rounded-[2rem] shadow-sm">
              <button onClick={() => setTimeRange('day')} className={`flex-1 py-2.5 rounded-[1.5rem] text-[10px] font-black uppercase tracking-widest transition-all ${timeRange === 'day' ? 'bg-sky-50 text-sky-600 border border-sky-100' : 'text-slate-300'}`}>Día</button>
              <button onClick={() => setTimeRange('week')} className={`flex-1 py-2.5 rounded-[1.5rem] text-[10px] font-black uppercase tracking-widest transition-all ${timeRange === 'week' ? 'bg-sky-50 text-sky-600 border border-sky-100' : 'text-slate-300'}`}>Semana</button>
              <button onClick={() => setTimeRange('month')} className={`flex-1 py-2.5 rounded-[1.5rem] text-[10px] font-black uppercase tracking-widest transition-all ${timeRange === 'month' ? 'bg-sky-50 text-sky-600 border border-sky-100' : 'text-slate-300'}`}>Mes</button>
            </div>

            {reportType === 'financial' ? (
               <ReportDashboard data={liveData} />
            ) : (
               <TaskReportDashboard data={taskData} />
            )}

            <div className="flex gap-3">
              <button 
                onClick={handleGeneratePDF}
                className="flex-1 py-5 bg-white text-sky-600 rounded-[2.5rem] font-black text-xs uppercase tracking-widest shadow-sm border border-sky-100 active:scale-95 transition-all flex items-center justify-center gap-2"
              >
                <i className="fas fa-file-pdf"></i> PDF
              </button>

              {reportType === 'financial' && (
                <button 
                  onClick={handleSaveSnapshot}
                  className="flex-[2] py-5 bg-indigo-600 text-white rounded-[2.5rem] font-black text-xs uppercase tracking-widest shadow-xl shadow-indigo-200 active:scale-95 transition-all flex items-center justify-center gap-3"
                >
                  <i className="fas fa-save"></i> Generar Corte
                </button>
              )}
            </div>
          </>
        )}

        {activeTab === 'history' && (
          <div className="space-y-3 animate-fadeIn">
            {savedReports.length === 0 ? (
               <div className="text-center py-20 opacity-30">
                  <i className="fas fa-folder-open text-6xl mb-4 text-sky-300"></i>
                  <p className="text-xs font-black uppercase text-sky-400">No hay reportes guardados</p>
               </div>
            ) : (
               savedReports.sort((a,b) => b.timestamp - a.timestamp).map(report => (
                 <RoundedCard key={report.id} onClick={() => setViewingReport(report)} className="py-4 cursor-pointer hover:shadow-md transition-all active:scale-[0.98]">
                    <div className="flex justify-between items-center">
                       <div className="flex items-center gap-4">
                          <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-white text-lg shadow-sm ${
                            report.rangeType === 'day' ? 'bg-emerald-400' : report.rangeType === 'week' ? 'bg-indigo-400' : 'bg-purple-400'
                          }`}>
                            <i className="fas fa-chart-bar"></i>
                          </div>
                          <div>
                             <h4 className="font-black text-sky-900 text-sm">{report.dateLabel}</h4>
                             <span className="text-[9px] font-bold text-sky-400 uppercase">
                               Corte: {report.rangeType === 'day' ? 'Diario' : report.rangeType === 'week' ? 'Semanal' : 'Mensual'}
                             </span>
                          </div>
                       </div>
                       <div className="text-right">
                          <span className="block font-black text-sky-600 text-lg">${report.totalGross.toLocaleString()}</span>
                          <span className="text-[9px] font-bold text-sky-300">{report.totalTransactions} Ops</span>
                       </div>
                    </div>
                 </RoundedCard>
               ))
            )}
          </div>
        )}
      </div>

      {/* PDF Reader Overlay */}
      {pdfUrl && <PDFReaderModal url={pdfUrl} onClose={() => setPdfUrl(null)} />}
    </div>
  );
};

import React, { useState } from 'react';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';
import { Employee, ViewType, Task, Attendance, Role } from '../types';

const TASK_PRESETS = [
  { title: 'Reparto', icon: 'fa-truck-fast', desc: 'Ruta de entrega programada' },
  { title: 'Lavado y Llenado', icon: 'fa-faucet-drip', desc: 'Higienización y llenado de garrafones' },
  { title: 'Apertura de Local', icon: 'fa-door-open', desc: 'Protocolo de apertura 8:00 AM' },
  { title: 'Cierre de Local', icon: 'fa-door-closed', desc: 'Protocolo de cierre y corte de caja' },
  { title: 'Lavado de Tinacos', icon: 'fa-circle-dot', desc: 'Mantenimiento preventivo de tinacos' },
  { title: 'Regeneración', icon: 'fa-flask-vial', desc: 'Regeneración química de resinas' },
  { title: 'Retrolavado', icon: 'fa-water-ladder', desc: 'Limpieza de filtros multimedia' },
  { title: 'Mantenimiento General', icon: 'fa-tools', desc: 'Revisión técnica de equipos' },
];

const AVAILABLE_ROLES: Role[] = ['Administrador', 'Repartidor', 'Planta'];

export const EmployeesModule: React.FC<{ onBack: () => void; currentUser: Employee }> = ({ onBack, currentUser }) => {
  const { employees, saveEmployee, tasks, addTask, updateTaskStatus, deleteTask, clearTasksByDate, attendance, recordAttendance } = useERPData();
  const [activeTab, setActiveTab] = useState<'roster' | 'assignments' | 'attendance'>('roster');
  const [editingEmployee, setEditingEmployee] = useState<Partial<Employee> | null>(null);
  const [assigningTo, setAssigningTo] = useState<Employee | null>(null);
  const [customTaskTitle, setCustomTaskTitle] = useState('');

  const isAdmin = currentUser.roles.includes('Administrador');

  // Robust Local Date
  const today = (() => {
    const d = new Date();
    const offset = d.getTimezoneOffset() * 60000;
    return new Date(d.getTime() - offset).toISOString().split('T')[0];
  })();

  const rosterModules: { id: ViewType; label: string; icon: string }[] = [
    { id: 'pos', label: 'Ventas', icon: 'fa-cash-register' },
    { id: 'orders', label: 'Pedidos', icon: 'fa-clipboard-list' },
    { id: 'customers', label: 'Clientes', icon: 'fa-address-book' },
    { id: 'inventory', label: 'Inventario', icon: 'fa-box-open' },
    { id: 'logistics', label: 'Flota', icon: 'fa-truck-moving' },
    { id: 'whatsapp', label: 'Preventa', icon: 'fa-brands fa-whatsapp' },
    { id: 'production', label: 'Producción', icon: 'fa-industry' },
    { id: 'quality', label: 'Bitácoras', icon: 'fa-book-medical' },
    { id: 'scanner', label: 'Scanner', icon: 'fa-qrcode' },
    { id: 'employees', label: 'Equipo', icon: 'fa-users-gear' },
    { id: 'reports', label: 'Reportes', icon: 'fa-chart-pie' },
    { id: 'sync', label: 'P2P Sync', icon: 'fa-cloud-arrow-up' },
    { id: 'settings', label: 'Ajustes', icon: 'fa-sliders' },
  ];

  const getRoleColor = (role: string) => {
    switch(role) {
      case 'Administrador': return 'bg-rose-500';
      case 'Repartidor': return 'bg-sky-500';
      case 'Planta': return 'bg-amber-500';
      default: return 'bg-slate-500';
    }
  };

  const getTaskStats = (empId: string) => {
    const todaysTasks = tasks.filter(t => t.employeeId === empId && t.date === today);
    return {
      total: todaysTasks.length,
      pending: todaysTasks.filter(t => t.status === 'pendiente').length
    };
  };

  const handleSaveEmployee = () => {
    if (!editingEmployee?.name || !editingEmployee?.pin || !editingEmployee?.roles || editingEmployee.roles.length === 0) {
      alert("Nombre, PIN y al menos un Rol son obligatorios.");
      return;
    }
    const empToSave: Employee = {
      id: editingEmployee.id || `EMP-${Date.now().toString().slice(-4)}`,
      name: editingEmployee.name,
      roles: editingEmployee.roles,
      phone: editingEmployee.phone || '',
      pin: editingEmployee.pin,
      permissions: editingEmployee.permissions || ['dashboard']
    };
    saveEmployee(empToSave);
    setEditingEmployee(null);
  };

  const togglePermission = (modId: ViewType) => {
    if (!editingEmployee) return;
    const currentPerms = editingEmployee.permissions || [];
    const newPerms = currentPerms.includes(modId)
      ? currentPerms.filter(p => p !== modId)
      : [...currentPerms, modId];
    setEditingEmployee({ ...editingEmployee, permissions: newPerms });
  };

  const toggleRole = (role: Role) => {
    if (!editingEmployee) return;
    const currentRoles = editingEmployee.roles || [];
    const newRoles = currentRoles.includes(role)
        ? currentRoles.filter(r => r !== role)
        : [...currentRoles, role];
    setEditingEmployee({ ...editingEmployee, roles: newRoles });
  };

  const handleAddTask = (preset: typeof TASK_PRESETS[0] | { title: string, desc: string }) => {
    if (!assigningTo) return;

    addTask({
      employeeId: assigningTo.id,
      title: preset.title,
      description: preset.desc,
      date: today
    });
    setAssigningTo(null);
    setCustomTaskTitle('');
  };

  const generateDailyRoutine = () => {
    if (!confirm("¿Generar rutina automática para hoy?\nSe asignarán tareas base a todos los colaboradores activos según sus roles.")) return;

    let count = 0;
    employees.forEach(e => {
      // Ignorar administradores para tareas operativas automáticas (a menos que tengan otro rol)
      if (e.roles.includes('Administrador') && e.roles.length === 1) return;

      if (e.roles.includes('Repartidor')) {
        addTask({
          id: `AUTO-${Date.now()}-${count++}`,
          employeeId: e.id,
          title: 'Carga de Unidad',
          description: 'Verificar inventario y cargar camión',
          date: today
        });
        addTask({
          id: `AUTO-${Date.now()}-${count++}`,
          employeeId: e.id,
          title: 'Ruta de Reparto',
          description: 'Entrega a clientes programados',
          date: today
        });
      } 

      if (e.roles.includes('Planta')) {
        addTask({
          id: `AUTO-${Date.now()}-${count++}`,
          employeeId: e.id,
          title: 'Apertura y Limpieza',
          description: 'Protocolo de higiene inicial',
          date: today
        });
        addTask({
          id: `AUTO-${Date.now()}-${count++}`,
          employeeId: e.id,
          title: 'Producción',
          description: 'Supervisión de llenado y calidad',
          date: today
        });
      }
    });
  };

  const handleClearDay = () => {
    if (confirm("¿Estás seguro de ELIMINAR TODAS las tareas de hoy para todos los empleados?")) {
      clearTasksByDate(today);
    }
  };

  if (editingEmployee) {
    return (
      <div className="h-full bg-sky-50 overflow-y-auto no-scrollbar pb-32">
        <ModuleHeader title={editingEmployee.id ? "Editar Colaborador" : "Nuevo Colaborador"} onBack={() => setEditingEmployee(null)} />
        <div className="px-6 space-y-6 animate-fadeIn">
          <div className="space-y-4">
             <div>
                <label className="text-[10px] font-black text-sky-400 uppercase ml-3 mb-1 block">Nombre Completo</label>
                <input className="w-full bg-white p-5 rounded-[2rem] outline-none shadow-sm font-bold text-sky-900 focus:ring-2 ring-sky-300 transition-all" placeholder="Ej: Juan Pérez" value={editingEmployee.name || ''} onChange={e => setEditingEmployee({...editingEmployee, name: e.target.value})}/>
             </div>

             <div>
                <label className="text-[10px] font-black text-sky-400 uppercase ml-3 mb-1 block">PIN de Acceso</label>
                <input maxLength={4} className="w-full bg-white p-5 rounded-[2rem] outline-none shadow-sm font-black text-sky-900 text-center tracking-[0.5em] focus:ring-2 ring-sky-300" placeholder="0000" value={editingEmployee.pin || ''} onChange={e => setEditingEmployee({...editingEmployee, pin: e.target.value})}/>
             </div>

             <section className="space-y-3">
                <label className="text-[10px] font-black text-sky-400 uppercase ml-3 block">Roles Asignados</label>
                <div className="flex flex-wrap gap-2">
                   {AVAILABLE_ROLES.map(role => {
                     const isSelected = editingEmployee.roles?.includes(role);
                     return (
                        <button 
                          key={role}
                          onClick={() => toggleRole(role)}
                          className={`flex-1 py-3 px-4 rounded-2xl font-black text-[10px] uppercase tracking-wider transition-all border ${isSelected ? `${getRoleColor(role)} text-white border-transparent shadow-lg` : 'bg-white text-slate-400 border-slate-100'}`}
                        >
                          {role}
                        </button>
                     );
                   })}
                </div>
             </section>

             <div>
                <label className="text-[10px] font-black text-sky-400 uppercase ml-3 mb-1 block">WhatsApp</label>
                <input className="w-full bg-white p-5 rounded-[2rem] outline-none shadow-sm text-sky-900 focus:ring-2 ring-sky-300" placeholder="33..." value={editingEmployee.phone || ''} onChange={e => setEditingEmployee({...editingEmployee, phone: e.target.value})}/>
             </div>

             <section className="space-y-3">
                <label className="text-[10px] font-black text-sky-400 uppercase ml-3 block">Permisos de Módulo</label>
                <div className="grid grid-cols-2 gap-2">
                   {rosterModules.map(mod => (
                     <button 
                        key={mod.id} 
                        onClick={() => togglePermission(mod.id)}
                        className={`flex items-center gap-2 p-3 rounded-2xl transition-all ${editingEmployee.permissions?.includes(mod.id) ? 'bg-sky-600 text-white shadow-md' : 'bg-white text-sky-300 border border-sky-50'}`}
                      >
                       <i className={`fas ${mod.icon} text-[10px]`}></i>
                       <span className="text-[9px] font-black uppercase tracking-tighter">{mod.label}</span>
                     </button>
                   ))}
                </div>
             </section>
          </div>

          <div className="pt-4">
             <ActionButton onClick={handleSaveEmployee}>Guardar Cambios</ActionButton>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="h-full bg-sky-50 flex flex-col animate-fadeIn overflow-hidden pb-24">
      <ModuleHeader title="Gestión de Equipo" onBack={onBack} />

      {/* Tab Selector */}
      <div className="px-6 flex gap-2 mb-6 shrink-0">
        <button onClick={() => setActiveTab('roster')} className={`flex-1 py-3.5 rounded-2xl text-[9px] font-black uppercase tracking-widest transition-all ${activeTab === 'roster' ? 'bg-sky-600 text-white shadow-lg shadow-sky-100' : 'bg-white text-sky-400'}`}>Roster</button>
        <button onClick={() => setActiveTab('assignments')} className={`flex-1 py-3.5 rounded-2xl text-[9px] font-black uppercase tracking-widest transition-all ${activeTab === 'assignments' ? 'bg-sky-600 text-white shadow-lg shadow-sky-100' : 'bg-white text-sky-400'}`}>Tareas</button>
        <button onClick={() => setActiveTab('attendance')} className={`flex-1 py-3.5 rounded-2xl text-[9px] font-black uppercase tracking-widest transition-all ${activeTab === 'attendance' ? 'bg-sky-600 text-white shadow-lg shadow-sky-100' : 'bg-white text-sky-400'}`}>Asistencias</button>
      </div>

      <div className="flex-1 overflow-y-auto px-6 space-y-6 no-scrollbar pb-10">

        {/* ROSTER TAB */}
        {activeTab === 'roster' && (
          <div className="space-y-4">
            {/* Replaced RoundedCard with plain div to ensure background color visibility */}
            <div className="bg-sky-900 text-white rounded-[2.5rem] p-6 shadow-xl flex items-center gap-4">
                <div className="w-16 h-16 bg-white/20 rounded-[2rem] flex items-center justify-center text-3xl">
                  <i className="fas fa-users-viewfinder"></i>
                </div>
                <div>
                  <h3 className="text-xl font-black">Capital Humano</h3>
                  <p className="text-[10px] font-bold uppercase opacity-60 tracking-widest">{employees.length} Colaboradores Activos</p>
                </div>
            </div>

            {employees.map(e => {
              const stats = getTaskStats(e.id);
              const mainRole = e.roles[0] || 'Planta';
              return (
                <RoundedCard key={e.id} className="py-4 border-none shadow-sm group">
                  <div className="flex justify-between items-center">
                    <div className="flex items-center gap-4">
                      <div className={`w-14 h-14 ${getRoleColor(mainRole)} text-white rounded-3xl flex items-center justify-center text-xl shadow-lg shadow-sky-100`}>
                        <i className={`fas ${mainRole === 'Administrador' ? 'fa-user-tie' : mainRole === 'Repartidor' ? 'fa-truck-fast' : 'fa-industry'}`}></i>
                      </div>
                      <div>
                        <h4 className="font-black text-sky-900 text-sm">{e.name}</h4>
                        <div className="flex flex-wrap items-center gap-1 mt-1">
                          {e.roles.map(r => (
                             <span key={r} className={`text-[8px] font-black uppercase text-white px-2 py-0.5 rounded-full ${getRoleColor(r)}`}>{r}</span>
                          ))}
                          {stats.total > 0 && (
                            <span className={`text-[8px] font-black uppercase px-2 py-0.5 rounded-full ${stats.pending === 0 ? 'bg-emerald-100 text-emerald-600' : 'bg-amber-100 text-amber-600'}`}>
                              {stats.pending > 0 ? `${stats.pending} Pendientes` : 'Todo Listo'}
                            </span>
                          )}
                        </div>
                      </div>
                    </div>
                    <div className="flex gap-2">
                      {isAdmin && (
                        <button onClick={() => setEditingEmployee(e)} className="w-10 h-10 bg-sky-50 text-sky-500 rounded-xl flex items-center justify-center active:bg-sky-200"><i className="fas fa-pen"></i></button>
                      )}
                      <a href={`https://wa.me/52${e.phone}`} className="w-10 h-10 bg-emerald-50 text-emerald-500 rounded-xl flex items-center justify-center active:bg-emerald-200"><i className="fab fa-whatsapp"></i></a>
                    </div>
                  </div>
                </RoundedCard>
              );
            })}

            {isAdmin && (
              <button 
                onClick={() => setEditingEmployee({ roles: ['Repartidor'], permissions: ['dashboard'] })}
                className="w-full py-6 border-2 border-dashed border-sky-200 rounded-[2.5rem] text-sky-400 font-black text-xs uppercase tracking-widest hover:bg-white transition-all"
              >
                + Registrar Colaborador
              </button>
            )}
          </div>
        )}

        {/* ASSIGNMENTS TAB */}
        {activeTab === 'assignments' && (
          <div className="space-y-6">
            {isAdmin && (
              <section className="space-y-3">
                <div className="flex justify-between items-center px-2">
                  <h4 className="text-[10px] font-black uppercase text-sky-400 tracking-widest">Asignar Tarea ({today})</h4>
                  <div className="flex gap-2">
                    <button onClick={handleClearDay} className="text-[9px] font-black uppercase bg-white text-rose-400 border border-rose-100 px-3 py-1.5 rounded-full flex items-center gap-1 active:scale-95 transition-transform">
                      <i className="fas fa-trash-can"></i> Limpiar
                    </button>
                    <button onClick={generateDailyRoutine} className="text-[9px] font-black uppercase bg-indigo-50 text-indigo-600 px-3 py-1.5 rounded-full flex items-center gap-1 active:scale-95 transition-transform">
                      <i className="fas fa-wand-magic-sparkles"></i> Generar Rutina
                    </button>
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-3">
                  {employees.filter(e => !e.roles.includes('Administrador') || e.roles.length > 1).map(e => (
                    <button key={e.id} onClick={() => setAssigningTo(e)} className="bg-white p-4 rounded-[1.8rem] border border-sky-50 flex items-center gap-3 active:scale-95 transition-all text-left">
                       <div className={`w-8 h-8 ${getRoleColor(e.roles[0])} rounded-xl flex items-center justify-center text-white text-[10px]`}><i className="fas fa-user"></i></div>
                       <span className="text-[10px] font-black text-sky-900 uppercase truncate">{e.name.split(' ')[0]}</span>
                    </button>
                  ))}
                </div>
              </section>
            )}

            <section className="space-y-4">
              <h4 className="text-[10px] font-black uppercase text-sky-400 tracking-widest px-2">Tareas de Hoy</h4>
              {tasks.filter(t => t.date === today).length === 0 ? (
                <div className="text-center py-20 text-sky-300 italic flex flex-col items-center gap-4">
                  <i className="fas fa-list-check text-5xl opacity-20"></i>
                  No hay tareas asignadas para hoy.
                </div>
              ) : (
                tasks.filter(t => t.date === today).map(t => (
                  <RoundedCard key={t.id} className={`py-4 border-none shadow-sm relative overflow-hidden ${t.status === 'completada' ? 'opacity-60 bg-emerald-50' : 'bg-white'}`}>
                    <div className="flex justify-between items-center">
                       <div className="flex items-center gap-4">
                          <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-white ${t.status === 'completada' ? 'bg-emerald-400' : 'bg-sky-600 shadow-lg shadow-sky-100'}`}>
                             <i className={`fas ${t.status === 'completada' ? 'fa-check' : 'fa-thumbtack'}`}></i>
                          </div>
                          <div>
                             <h4 className={`font-black text-sky-900 text-sm ${t.status === 'completada' ? 'line-through' : ''}`}>{t.title}</h4>
                             <p className="text-[10px] text-sky-400 font-bold uppercase">{employees.find(e => e.id === t.employeeId)?.name || 'Anónimo'}</p>
                          </div>
                       </div>
                       <div className="flex items-center gap-2">
                         {t.employeeId === currentUser.id && t.status === 'pendiente' && (
                           <button onClick={() => updateTaskStatus(t.id, 'completada')} className="bg-emerald-500 text-white px-4 py-2 rounded-xl text-[9px] font-black uppercase shadow-lg shadow-emerald-100">Completar</button>
                         )}
                         {t.status === 'completada' && (
                           <span className="text-[10px] font-black text-emerald-600 uppercase">Lista <i className="fas fa-circle-check ml-1"></i></span>
                         )}
                         {isAdmin && (
                            <button onClick={() => deleteTask(t.id)} className="w-8 h-8 bg-rose-50 text-rose-400 rounded-xl flex items-center justify-center active:bg-rose-100 transition-colors">
                              <i className="fas fa-trash-can text-xs"></i>
                            </button>
                         )}
                       </div>
                    </div>
                  </RoundedCard>
                ))
              )}
            </section>
          </div>
        )}

        {/* ATTENDANCE TAB */}
        {activeTab === 'attendance' && (
          <div className="space-y-6">
            <RoundedCard className="bg-white border-l-4 border-l-emerald-500 p-6 shadow-sm">
               <div className="flex justify-between items-center mb-1">
                  <h4 className="text-lg font-black text-sky-900">Registro de Hoy</h4>
                  <span className="text-[10px] font-black text-emerald-600 uppercase bg-emerald-50 px-3 py-1 rounded-full">{today}</span>
               </div>
               <p className="text-[11px] text-sky-400 font-bold mb-6 italic">Marca la asistencia de los colaboradores al llegar a la planta.</p>

               <div className="space-y-3">
                  {employees.filter(e => !e.roles.includes('Administrador') || e.roles.length > 1).map(e => {
                    const record = attendance.find(a => a.employeeId === e.id && a.date === today);
                    return (
                      <div key={e.id} className="flex items-center justify-between p-3 bg-sky-50/50 rounded-2xl border border-sky-50">
                        <div className="flex items-center gap-3">
                           <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-white text-xs ${getRoleColor(e.roles[0])} shadow-sm`}>
                              <i className="fas fa-user"></i>
                           </div>
                           <span className="text-xs font-black text-sky-900 uppercase truncate max-w-[100px]">{e.name.split(' ')[0]}</span>
                        </div>
                        <div className="flex gap-2">
                          <button onClick={() => recordAttendance(e.id, 'presente')} className={`w-10 h-10 rounded-xl flex items-center justify-center text-sm transition-all ${record?.status === 'presente' ? 'bg-emerald-500 text-white shadow-md' : 'bg-white text-emerald-500 border border-emerald-100'}`} title="Presente"><i className="fas fa-check"></i></button>
                          <button onClick={() => recordAttendance(e.id, 'retardo')} className={`w-10 h-10 rounded-xl flex items-center justify-center text-sm transition-all ${record?.status === 'retardo' ? 'bg-amber-500 text-white shadow-md' : 'bg-white text-amber-500 border border-amber-100'}`} title="Retardo"><i className="fas fa-clock"></i></button>
                          <button onClick={() => recordAttendance(e.id, 'falta')} className={`w-10 h-10 rounded-xl flex items-center justify-center text-sm transition-all ${record?.status === 'falta' ? 'bg-red-500 text-white shadow-md' : 'bg-white text-red-500 border border-red-100'}`} title="Falta"><i className="fas fa-times"></i></button>
                        </div>
                      </div>
                    );
                  })}
               </div>
            </RoundedCard>

            <section className="space-y-3">
              <h4 className="text-[10px] font-black uppercase text-sky-400 tracking-widest px-2">Historial de Puntualidad</h4>
              <div className="bg-white rounded-[2rem] p-6 shadow-sm border border-sky-50">
                 {attendance.length === 0 ? (
                   <p className="text-center text-sky-300 text-xs italic py-10">No hay registros históricos.</p>
                 ) : (
                   <div className="space-y-4 max-h-60 overflow-y-auto no-scrollbar">
                     {attendance.sort((a,b) => b.timestamp - a.timestamp).slice(0, 10).map(a => (
                       <div key={a.id} className="flex justify-between items-center border-b border-sky-50 pb-3 last:border-none">
                          <div className="flex flex-col">
                             <span className="text-[10px] font-black text-sky-900 uppercase">{employees.find(e => e.id === a.employeeId)?.name || '??'}</span>
                             <span className="text-[8px] font-bold text-sky-300">{a.date}</span>
                          </div>
                          <span className={`text-[8px] font-black uppercase px-2 py-0.5 rounded-full ${a.status === 'presente' ? 'bg-emerald-100 text-emerald-600' : a.status === 'retardo' ? 'bg-amber-100 text-amber-600' : 'bg-red-100 text-red-600'}`}>
                             {a.status}
                          </span>
                       </div>
                     ))}
                   </div>
                 )}
              </div>
            </section>
          </div>
        )}
      </div>

      {/* Assignment Modal */}
      {assigningTo && (
        <div className="fixed inset-0 bg-sky-900/60 backdrop-blur-md z-[100] flex items-end">
           <div className="w-full bg-white rounded-t-[2.5rem] p-8 animate-fadeIn max-h-[90vh] overflow-y-auto no-scrollbar">
              <div className="flex justify-between items-center mb-8">
                 <div>
                    <h3 className="text-xl font-black text-sky-900">Asignar Tarea</h3>
                    <p className="text-[10px] font-bold text-sky-400 uppercase tracking-widest">Para: {assigningTo.name}</p>
                 </div>
                 <button onClick={() => setAssigningTo(null)} className="w-12 h-12 bg-sky-50 text-sky-400 rounded-full flex items-center justify-center active:scale-90 transition-all"><i className="fas fa-times"></i></button>
              </div>

              <div className="grid grid-cols-2 gap-3 mb-8">
                 {TASK_PRESETS.map(preset => (
                   <button 
                    key={preset.title} 
                    onClick={() => handleAddTask(preset)}
                    className="bg-sky-50 p-5 rounded-[2rem] text-left border border-white hover:border-sky-300 active:scale-95 transition-all group"
                   >
                     <i className={`fas ${preset.icon} text-sky-600 mb-3 text-lg group-hover:rotate-12 transition-transform`}></i>
                     <h5 className="text-[10px] font-black text-sky-900 uppercase leading-none mb-1">{preset.title}</h5>
                     <p className="text-[8px] font-bold text-sky-400 leading-tight">{preset.desc}</p>
                   </button>
                 ))}
              </div>

              <div className="space-y-4 pt-6 border-t border-sky-50">
                 <h4 className="text-[10px] font-black uppercase text-sky-400 tracking-widest">Tarea Personalizada</h4>
                 <input 
                  type="text" 
                  className="w-full bg-sky-50 border-none rounded-2xl p-5 text-sky-900 font-bold outline-none focus:ring-2 ring-sky-300" 
                  placeholder="Título de la tarea..." 
                  value={customTaskTitle}
                  onChange={e => setCustomTaskTitle(e.target.value)}
                 />
                 <ActionButton onClick={() => handleAddTask({ title: customTaskTitle, desc: 'Tarea personalizada asignada por administrador' })} disabled={!customTaskTitle}>Asignar Personalizada</ActionButton>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import { PDFDocument, StandardFonts, rgb, PDFFont } from 'pdf-lib';
import { TicketConfig, Sale, Task, Employee } from '../types';

// Interface for the data expected by the report generator
interface ReportData {
  label: string;
  rangeType: string;
  totalGross: number;
  totalTransactions: number;
  averageTicket: number;
  payments: { cash: number; transfer: number };
  topProducts: { name: string; qty: number; total: number }[];
}

interface TaskReportData {
  label: string;
  rangeType: string;
  totalTasks: number;
  completedTasks: number;
  pendingTasks: number;
  byEmployee: { id: string; name: string; completed: number; total: number; tasks: Task[] }[];
}

// Helper to convert hex to rgb 0-1 range
const hexToRgbScale = (hex: string) => {
  const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
  return result ? {
    r: parseInt(result[1], 16) / 255,
    g: parseInt(result[2], 16) / 255,
    b: parseInt(result[3], 16) / 255
  } : { r: 0, g: 0, b: 0 };
};

export const generateFinancialPDF = (data: ReportData, config: TicketConfig): string => {
  const doc = new jsPDF();
  const pageWidth = doc.internal.pageSize.width;

  // --- HEADER ---
  doc.setFillColor(2, 132, 199); // Sky-600
  doc.rect(0, 0, pageWidth, 40, 'F');

  doc.setTextColor(255, 255, 255);
  doc.setFontSize(22);
  doc.setFont('helvetica', 'bold');
  doc.text(config.businessName, 15, 15);

  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');
  doc.text('REPORTE FINANCIERO', 15, 22);
  doc.text(`Generado: ${new Date().toLocaleString()}`, 15, 27);

  // Right side header info
  doc.setFontSize(10);
  doc.text(`Periodo: ${data.label}`, pageWidth - 15, 15, { align: 'right' });
  doc.text(`Tipo: ${data.rangeType.toUpperCase()}`, pageWidth - 15, 20, { align: 'right' });

  // --- KPI CARDS (Simulated) ---
  let yPos = 55;

  // Title
  doc.setTextColor(15, 23, 42); // Slate-900
  doc.setFontSize(14);
  doc.setFont('helvetica', 'bold');
  doc.text('Resumen General', 15, yPos);

  yPos += 10;

  // Draw Boxes for KPIs
  const boxWidth = (pageWidth - 40) / 3;
  const boxHeight = 25;

  // Box 1: Ventas
  doc.setDrawColor(226, 232, 240);
  doc.setFillColor(248, 250, 252);
  doc.roundedRect(15, yPos, boxWidth, boxHeight, 3, 3, 'FD');
  doc.setFontSize(8);
  doc.setTextColor(100, 116, 139);
  doc.text('VENTAS BRUTAS', 20, yPos + 8);
  doc.setFontSize(12);
  doc.setTextColor(15, 23, 42);
  doc.setFont('helvetica', 'bold');
  doc.text(`$${data.totalGross.toLocaleString()}`, 20, yPos + 18);

  // Box 2: Ops
  doc.roundedRect(15 + boxWidth + 5, yPos, boxWidth, boxHeight, 3, 3, 'FD');
  doc.setFontSize(8);
  doc.setTextColor(100, 116, 139);
  doc.setFont('helvetica', 'normal');
  doc.text('TRANSACCIONES', 20 + boxWidth + 5, yPos + 8);
  doc.setFontSize(12);
  doc.setTextColor(15, 23, 42);
  doc.setFont('helvetica', 'bold');
  doc.text(`${data.totalTransactions}`, 20 + boxWidth + 5, yPos + 18);

  // Box 3: Ticket Prom
  doc.roundedRect(15 + (boxWidth * 2) + 10, yPos, boxWidth, boxHeight, 3, 3, 'FD');
  doc.setFontSize(8);
  doc.setTextColor(100, 116, 139);
  doc.setFont('helvetica', 'normal');
  doc.text('TICKET PROMEDIO', 20 + (boxWidth * 2) + 10, yPos + 8);
  doc.setFontSize(12);
  doc.setTextColor(15, 23, 42);
  doc.setFont('helvetica', 'bold');
  doc.text(`$${data.averageTicket.toFixed(2)}`, 20 + (boxWidth * 2) + 10, yPos + 18);

  yPos += 40;

  // --- PAYMENTS SECTION ---
  doc.setFontSize(12);
  doc.setTextColor(15, 23, 42);
  doc.text('Desglose de Ingresos', 15, yPos);

  yPos += 5;

  autoTable(doc, {
    startY: yPos,
    head: [['Método de Pago', 'Monto Recaudado']],
    body: [
      ['Efectivo', `$${data.payments.cash.toLocaleString()}`],
      ['Transferencia', `$${data.payments.transfer.toLocaleString()}`],
      ['TOTAL', `$${(data.payments.cash + data.payments.transfer).toLocaleString()}`]
    ],
    theme: 'striped',
    headStyles: { fillColor: [2, 132, 199] },
    styles: { fontSize: 10 },
    columnStyles: { 1: { halign: 'right', fontStyle: 'bold' } },
    foot: [['Balance', `$${(data.payments.cash + data.payments.transfer).toLocaleString()}`]],
    footStyles: { fillColor: [241, 245, 249], textColor: [15, 23, 42] }
  });

  yPos = (doc as any).lastAutoTable.finalY + 20;

  // --- PRODUCTS SECTION ---
  doc.text('Top Productos Vendidos', 15, yPos);
  yPos += 5;

  const productRows = data.topProducts.map(p => [
    p.name,
    p.qty.toString(),
    `$${p.total.toLocaleString()}`
  ]);

  autoTable(doc, {
    startY: yPos,
    head: [['Producto', 'Cantidad', 'Venta Total']],
    body: productRows,
    theme: 'grid',
    headStyles: { fillColor: [71, 85, 105] },
    columnStyles: { 
      1: { halign: 'center' },
      2: { halign: 'right' }
    }
  });

  // --- FOOTER ---
  const pageCount = (doc as any).internal.getNumberOfPages();
  for(let i = 1; i <= pageCount; i++) {
    doc.setPage(i);
    doc.setFontSize(8);
    doc.setTextColor(150);
    doc.text(`Aqua+ ERP - Documento Confidencial - Página ${i} de ${pageCount}`, pageWidth / 2, doc.internal.pageSize.height - 10, { align: 'center' });
  }

  // Return the Data URL string to be used in an iframe
  return doc.output('datauristring');
};

export const generateTaskReportPDF = (data: TaskReportData, config: TicketConfig): string => {
  const doc = new jsPDF();
  const pageWidth = doc.internal.pageSize.width;

  // --- HEADER ---
  doc.setFillColor(245, 158, 11); // Amber-500
  doc.rect(0, 0, pageWidth, 40, 'F');

  doc.setTextColor(255, 255, 255);
  doc.setFontSize(22);
  doc.setFont('helvetica', 'bold');
  doc.text(config.businessName, 15, 15);

  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');
