  // Right side header info
  doc.setFontSize(10);
  doc.text(`Periodo: ${data.label}`, pageWidth - 15, 15, { align: 'right' });
  doc.text(`Cumplimiento: ${Math.round((data.completedTasks / (data.totalTasks || 1)) * 100)}%`, pageWidth - 15, 20, { align: 'right' });

  let yPos = 55;

  // --- SUMMARY ---
  doc.setTextColor(15, 23, 42);
  doc.setFontSize(14);
  doc.setFont('helvetica', 'bold');
  doc.text('Resumen de Productividad', 15, yPos);

  yPos += 10;

  // Draw Boxes
  const boxWidth = (pageWidth - 40) / 3;
  const boxHeight = 25;

  // Box 1: Total
  doc.setDrawColor(226, 232, 240);
  doc.setFillColor(248, 250, 252);
  doc.roundedRect(15, yPos, boxWidth, boxHeight, 3, 3, 'FD');
  doc.setFontSize(8);
  doc.setTextColor(100, 116, 139);
  doc.text('TOTAL ASIGNADAS', 20, yPos + 8);
  doc.setFontSize(12);
  doc.setTextColor(15, 23, 42);
  doc.setFont('helvetica', 'bold');
  doc.text(`${data.totalTasks}`, 20, yPos + 18);

  // Box 2: Completadas
  doc.roundedRect(15 + boxWidth + 5, yPos, boxWidth, boxHeight, 3, 3, 'FD');
  doc.setFontSize(8);
  doc.setTextColor(100, 116, 139);
  doc.text('COMPLETADAS', 20 + boxWidth + 5, yPos + 8);
  doc.setFontSize(12);
  doc.setTextColor(34, 197, 94); // Green
  doc.setFont('helvetica', 'bold');
  doc.text(`${data.completedTasks}`, 20 + boxWidth + 5, yPos + 18);

  // Box 3: Pendientes
  doc.roundedRect(15 + (boxWidth * 2) + 10, yPos, boxWidth, boxHeight, 3, 3, 'FD');
  doc.setFontSize(8);
  doc.setTextColor(100, 116, 139);
  doc.text('PENDIENTES', 20 + (boxWidth * 2) + 10, yPos + 8);
  doc.setFontSize(12);
  doc.setTextColor(239, 68, 68); // Red
  doc.setFont('helvetica', 'bold');
  doc.text(`${data.pendingTasks}`, 20 + (boxWidth * 2) + 10, yPos + 18);

  yPos += 40;

  // --- DETAILS PER EMPLOYEE ---
  data.byEmployee.forEach((emp) => {
    if (yPos > 250) {
      doc.addPage();
      yPos = 20;
    }

    doc.setFontSize(12);
    doc.setTextColor(15, 23, 42);
    doc.text(`Colaborador: ${emp.name} (${Math.round((emp.completed / (emp.total || 1)) * 100)}%)`, 15, yPos);
    yPos += 5;

    // Group tasks by date
    const tasksByDate = emp.tasks.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    let lastDate = '';

    const taskRows = tasksByDate.map(t => {
      const isNewDate = t.date !== lastDate;
      if(isNewDate) lastDate = t.date;

      const time = new Date(t.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

      return [
        isNewDate ? t.date : '', // Group visual
        time,
        t.title,
        t.status === 'completada' ? 'COMPLETA' : 'PENDIENTE',
        t.description || '-'
      ];
    });

    autoTable(doc, {
      startY: yPos,
      head: [['Fecha', 'Hora', 'Tarea', 'Estado', 'Detalle']],
      body: taskRows,
      theme: 'grid',
      headStyles: { fillColor: [245, 158, 11] }, // Amber header
      styles: { fontSize: 8 },
      columnStyles: { 
        0: { fontStyle: 'bold', cellWidth: 25 },
        3: { fontStyle: 'bold' }
      },
      didParseCell: (data: any) => {
        if (data.section === 'body' && data.column.index === 3) {
          if (data.cell.raw === 'PENDIENTE') {
            data.cell.styles.textColor = [220, 38, 38]; // Red
          } else {
            data.cell.styles.textColor = [22, 163, 74]; // Green
          }
        }
      }
    });

    yPos = (doc as any).lastAutoTable.finalY + 15;
  });

  // --- FOOTER ---
  const pageCount = (doc as any).internal.getNumberOfPages();
  for(let i = 1; i <= pageCount; i++) {
    doc.setPage(i);
    doc.setFontSize(8);
    doc.setTextColor(150);
    doc.text(`Aqua+ ERP - Reporte Operativo - Página ${i} de ${pageCount}`, pageWidth / 2, doc.internal.pageSize.height - 10, { align: 'center' });
  }

  return doc.output('datauristring');
};

/**
 * Generates a Ticket PDF using pdf-lib and returns raw bytes
 */
export const generateTicketPDF = async (sale: Sale, config: TicketConfig): Promise<Uint8Array> => {
  // Crear nuevo documento PDF
  const pdfDoc = await PDFDocument.create();

  const accent = hexToRgbScale(config.colorHex || '#000000');
  const accentColor = rgb(accent.r, accent.g, accent.b);

  // Calcular altura dinámica base
  const itemsHeight = sale.items.length * 25; 
  const qrSpace = 120;
  const baseHeight = 400; // Increased base height for extra fields
  const ticketHeight = baseHeight + itemsHeight + qrSpace;
  const ticketWidth = 280; 

  const page = pdfDoc.addPage([ticketWidth, ticketHeight]);

  // Obtener fuentes
  const fontRegular = await pdfDoc.embedFont(StandardFonts.Helvetica);
  const fontBold = await pdfDoc.embedFont(StandardFonts.HelveticaBold);
  const fontCourier = await pdfDoc.embedFont(StandardFonts.Courier);

  const { width, height } = page.getSize();
  let yPos = height - 20;

  const centerX = width / 2;
  const margin = 15;
  const contentWidth = width - (margin * 2);

  // --- HELPERS ---
  const sanitize = (text: string) => {
    if (!text) return '';
    return text
      .replace(/★/g, '*')
      .replace(/☆/g, '*')
      .replace(/●/g, '-')
      .replace(/•/g, '-');
  };

  const drawCenteredText = (text: string, font: PDFFont, size: number, color = rgb(0,0,0)) => {
    const safeText = sanitize(text);
    const textWidth = font.widthOfTextAtSize(safeText, size);
    page.drawText(safeText, { x: centerX - (textWidth / 2), y: yPos, size, font, color });
    yPos -= (size + 4);
  };

  const drawLeftRight = (left: string, right: string, font: PDFFont, size: number, isBold = false) => {
    const safeLeft = sanitize(left);
    const safeRight = sanitize(right);
    const rightWidth = font.widthOfTextAtSize(safeRight, size);
    page.drawText(safeLeft, { x: margin, y: yPos, size, font });
    page.drawText(safeRight, { x: width - margin - rightWidth, y: yPos, size, font: isBold ? fontBold : font });
    yPos -= (size + 6);
  };

  const drawDashedLine = () => {
    const dash = '- - - - - - - - - - - - - - - - - - - - - - - - - - - -';
    const textWidth = fontCourier.widthOfTextAtSize(dash, 10);
    page.drawText(dash, { x: centerX - (textWidth / 2), y: yPos, size: 10, font: fontCourier, color: rgb(0.5, 0.5, 0.5) });
    yPos -= 12;
  };

  // --- LOGO ---
  if (config.logoUrl && config.logoUrl.startsWith('data:image')) {
    try {
      const base64Data = config.logoUrl.split(',')[1];
      const imageBytes = Uint8Array.from(atob(base64Data), c => c.charCodeAt(0));

      let logoImage;
      if (config.logoUrl.includes('image/png')) {
        logoImage = await pdfDoc.embedPng(imageBytes);
      } else {
        logoImage = await pdfDoc.embedJpg(imageBytes);
      }

      const logoDims = logoImage.scale(1);
      const maxLogoWidth = 80;
      const scaleFactor = maxLogoWidth / logoDims.width;
      const scaledWidth = logoDims.width * scaleFactor;
      const scaledHeight = logoDims.height * scaleFactor;

      page.drawImage(logoImage, {
        x: centerX - (scaledWidth / 2),
        y: yPos - scaledHeight,
        width: scaledWidth,
        height: scaledHeight,
      });
      yPos -= (scaledHeight + 10);
    } catch (e) {
      console.warn("Error embedding logo", e);
    }
  } else {
    yPos -= 10;
  }

  // --- HEADER ---
  drawCenteredText(config.businessName, fontBold, 16, accentColor);
  if (config.slogan) drawCenteredText(`"${config.slogan}"`, fontRegular, 9, rgb(0.4, 0.4, 0.4));

  yPos -= 5;
  drawCenteredText(config.address, fontRegular, 9);
  drawCenteredText(`Tel: ${config.phone}`, fontRegular, 9);
  if (config.email) drawCenteredText(config.email, fontRegular, 8);
  if (config.website) drawCenteredText(config.website, fontRegular, 8);
  if (config.rfc) drawCenteredText(`RFC: ${config.rfc}`, fontRegular, 9);

  yPos -= 5;
  drawDashedLine();

  // --- META INFO ---
  drawLeftRight('Folio:', sale.id, fontRegular, 10, true);
  drawLeftRight('Fecha:', new Date(sale.timestamp).toLocaleDateString(), fontRegular, 10);
  drawLeftRight('Hora:', new Date(sale.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}), fontRegular, 10);
  drawLeftRight('Cliente:', sale.customerAlias.substring(0, 18), fontRegular, 10, true);

  yPos -= 5;

  // --- TABLE HEADER ---
  page.drawRectangle({
    x: margin,
    y: yPos - 2,
    width: contentWidth,
    height: 14,
    color: accentColor, 
    opacity: 0.1
  });

  page.drawText('CANT', { x: margin + 5, y: yPos, size: 8, font: fontBold, color: accentColor });
  page.drawText('DESCRIPCION', { x: margin + 45, y: yPos, size: 8, font: fontBold, color: accentColor });
  const impHeaderWidth = fontBold.widthOfTextAtSize('IMPORTE', 8);
  page.drawText('IMPORTE', { x: width - margin - impHeaderWidth - 5, y: yPos, size: 8, font: fontBold, color: accentColor });
  yPos -= 18;

  // --- ITEMS ---
  sale.items.forEach(item => {
    // Cantidad
    page.drawText(item.quantity.toString(), { x: margin + 8, y: yPos, size: 10, font: fontBold });

    // Descripción
    const cleanName = sanitize(item.name);
    const name = cleanName.length > 20 ? cleanName.substring(0, 20) + '...' : cleanName;
    page.drawText(name, { x: margin + 45, y: yPos, size: 9, font: fontRegular });

    // Importe
    const totalItem = (item.quantity * item.price).toFixed(2);
    const totalItemWidth = fontRegular.widthOfTextAtSize(`$${totalItem}`, 10);
    page.drawText(`$${totalItem}`, { x: width - margin - totalItemWidth, y: yPos, size: 10, font: fontRegular });

    yPos -= 15;
  });

  drawDashedLine();

  // --- TOTALS ---
  const drawTotalLine = (label: string, value: string, isBig = false) => {
    const safeLabel = sanitize(label);
    const safeValue = sanitize(value);

    const size = isBig ? 16 : 10;
    const font = isBig ? fontBold : fontRegular;
    const color = isBig ? accentColor : rgb(0,0,0);

    const labelWidth = font.widthOfTextAtSize(safeLabel, size);
    const valueWidth = font.widthOfTextAtSize(safeValue, size);

    const valueX = width - margin - valueWidth;
    const labelX = valueX - labelWidth - 10;

    page.drawText(safeLabel, { x: labelX, y: yPos, size, font, color });
    page.drawText(safeValue, { x: valueX, y: yPos, size, font, color });
    yPos -= (size + 8);
  };

  drawTotalLine('TOTAL:', `$${sale.total.toFixed(2)}`, true);

  if (sale.paymentSplits && sale.paymentSplits.length > 0) {
     sale.paymentSplits.forEach(split => {
        drawTotalLine(`${split.method}:`, `$${split.amount.toFixed(2)}`);
     });
  } else {
     drawTotalLine('Su Pago:', `$${sale.paidAmount.toFixed(2)}`);
  }

  if (sale.change > 0) {
    drawTotalLine('Cambio:', `$${sale.change.toFixed(2)}`);
  } else if (sale.paidAmount < sale.total) {
    // Background for Debt warning
    page.drawRectangle({
        x: margin,
        y: yPos - 8,
        width: contentWidth,
        height: 20,
        color: accentColor,
    });

    page.drawText('SALDO PENDIENTE', { x: margin + 5, y: yPos + 2, size: 10, font: fontBold, color: rgb(1,1,1) });
    const debtStr = `$${(sale.total - sale.paidAmount).toFixed(2)}`;
    const debtW = fontBold.widthOfTextAtSize(debtStr, 10);
    page.drawText(debtStr, { x: width - margin - debtW - 5, y: yPos + 2, size: 10, font: fontBold, color: rgb(1,1,1) });
    yPos -= 25;
  }

  // --- GARRAFONES RETURNED ---
  if (sale.emptyGarrafonsReturned > 0) {
    yPos -= 5;
    page.drawRectangle({
      x: margin + 20,
      y: yPos - 5,
      width: contentWidth - 40,
      height: 25,
      borderColor: accentColor,
      borderWidth: 1,
    });
    const text = `* ${sale.emptyGarrafonsReturned} Envases Recibidos *`;
    const textW = fontBold.widthOfTextAtSize(text, 10);
    page.drawText(text, { x: centerX - (textW/2), y: yPos + 5, size: 10, font: fontBold, color: accentColor });
    yPos -= 25;
  }

  // --- FOOTER & QR CODE ---
  yPos -= 10;
  if (config.footerMessage) {
    const words = sanitize(config.footerMessage).split(' ');
    let line = '';
    for (const word of words) {
        const testLine = line + word + ' ';
        const testWidth = fontRegular.widthOfTextAtSize(testLine, 9);
        if (testWidth > contentWidth) {
            drawCenteredText(line, fontRegular, 9);
            line = word + ' ';
        } else {
            line = testLine;
        }
    }
    drawCenteredText(line, fontRegular, 9);
  }

  if (config.extraNote) {
    drawCenteredText(sanitize(config.extraNote), fontRegular, 8, rgb(0.5, 0.5, 0.5));
  }

  drawCenteredText('*** GRACIAS POR SU PREFERENCIA ***', fontBold, 9);

  // QR Code at the bottom
  yPos -= 10;
  try {
    const qrData = btoa(`AQUA-PRO-SECURE|${JSON.stringify({ id: sale.id, total: sale.total })}`);
    const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(qrData)}`;

    // Fetch image data
    const qrResponse = await fetch(qrUrl);
    const qrArrayBuffer = await qrResponse.arrayBuffer();
    const qrImage = await pdfDoc.embedPng(qrArrayBuffer);

    const qrSize = 100;

    page.drawImage(qrImage, {
        x: centerX - (qrSize / 2),
        y: yPos - qrSize,
        width: qrSize,
        height: qrSize
    });
  } catch (e) {
    console.warn("Could not embed QR code in PDF", e);
    // Draw placeholder
    yPos -= 20;
    drawCenteredText('[ CODIGO QR NO DISPONIBLE ]', fontCourier, 8);
  }

  return await pdfDoc.save();
}

