};

// Hook Logic Factory
const useERPFactory = () => {
  const [products, setProducts] = useState<Product[]>(() => {
    const saved = localStorage.getItem('aqua_products');
    return saved ? JSON.parse(saved) : INITIAL_PRODUCTS;
  });

  const [customers, setCustomers] = useState<Customer[]>(() => {
    const saved = localStorage.getItem('aqua_customers');
    return saved ? JSON.parse(saved).map((c: any) => ({ ...c, balance: c.balance || 0 })) : INITIAL_CUSTOMERS;
  });

  const [ticketConfig, setTicketConfig] = useState<TicketConfig>(() => {
    const saved = localStorage.getItem('aqua_ticket_config');
    // Ensure colorHex exists for older saved configs
    const parsed = saved ? JSON.parse(saved) : INITIAL_TICKET_CONFIG;
    return { ...INITIAL_TICKET_CONFIG, ...parsed };
  });

  const [cloudConfig, setCloudConfig] = useState<CloudConfig>(() => {
    const saved = localStorage.getItem('aqua_cloud_config');
    if (saved) {
      const parsed = JSON.parse(saved);
      if (!parsed.url || parsed.url === '') {
        return INITIAL_CLOUD_CONFIG;
      }
      return parsed;
    }
    return INITIAL_CLOUD_CONFIG;
  });

  const [sales, setSales] = useState<Sale[]>(() => {
    const saved = localStorage.getItem('aqua_sales');
    return saved ? JSON.parse(saved) : [];
  });

  const [orders, setOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('aqua_orders');
    return saved ? JSON.parse(saved) : [];
  });

  const [employees, setEmployees] = useState<Employee[]>(() => {
    const saved = localStorage.getItem('aqua_employees');
    let initial = saved ? JSON.parse(saved) : [
      { id: 'admin', name: 'Gerente General', roles: ['Administrador'], phone: '3312345678', pin: '1234', permissions: [...DEFAULT_PERMISSIONS] }
    ];

    // MIGRATION: Convert single role string to roles array if needed
    initial = initial.map((e: any) => {
      if (e.role && !e.roles) {
        return { ...e, roles: [e.role], role: undefined };
      }
      return e;
    });

    return initial;
  });

  // Ensure Admins always have full permissions on load
  useEffect(() => {
    setEmployees(prev => prev.map(e => 
      e.roles.includes('Administrador')
        ? { ...e, permissions: [...DEFAULT_PERMISSIONS] } 
        : e
    ));
  }, []);

  const [vehicles, setVehicles] = useState<Vehicle[]>(() => {
    const saved = localStorage.getItem('aqua_vehicles');
    // Migration: ensure inventory and fuelHistory arrays exist
    const parsed = saved ? JSON.parse(saved) : [{ id: 'v1', plate: 'ABC-123', description: 'Nissan NP300', loadCapacity: 60, currentLoad: 0, inventory: [], fuelHistory: [] }];
    return parsed.map((v: any) => ({
        ...v,
        inventory: v.inventory || [],
        fuelHistory: v.fuelHistory || []
    }));
  });

  const [qualityRecords, setQualityRecords] = useState<QualityRecord[]>(() => {
    const saved = localStorage.getItem('aqua_quality');
    return saved ? JSON.parse(saved) : [];
  });

  const [tasks, setTasks] = useState<Task[]>(() => {
    const saved = localStorage.getItem('aqua_tasks');
    return saved ? JSON.parse(saved) : [];
  });

  const [attendance, setAttendance] = useState<Attendance[]>(() => {
    const saved = localStorage.getItem('aqua_attendance');
    return saved ? JSON.parse(saved) : [];
  });

  const [savedReports, setSavedReports] = useState<SavedReport[]>(() => {
    const saved = localStorage.getItem('aqua_saved_reports');
    return saved ? JSON.parse(saved) : [];
  });

  const [messages, setMessages] = useState<Message[]>(() => {
    const saved = localStorage.getItem('aqua_messages');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => {
    localStorage.setItem('aqua_products', JSON.stringify(products));
    localStorage.setItem('aqua_customers', JSON.stringify(customers));
    localStorage.setItem('aqua_sales', JSON.stringify(sales));
    localStorage.setItem('aqua_orders', JSON.stringify(orders));
    localStorage.setItem('aqua_employees', JSON.stringify(employees));
    localStorage.setItem('aqua_vehicles', JSON.stringify(vehicles));
    localStorage.setItem('aqua_ticket_config', JSON.stringify(ticketConfig));
    localStorage.setItem('aqua_quality', JSON.stringify(qualityRecords));
    localStorage.setItem('aqua_tasks', JSON.stringify(tasks));
    localStorage.setItem('aqua_attendance', JSON.stringify(attendance));
    localStorage.setItem('aqua_cloud_config', JSON.stringify(cloudConfig));
    localStorage.setItem('aqua_saved_reports', JSON.stringify(savedReports));
    localStorage.setItem('aqua_messages', JSON.stringify(messages));
  }, [products, customers, sales, orders, employees, vehicles, ticketConfig, qualityRecords, tasks, attendance, cloudConfig, savedReports, messages]);

  // Helper para fecha local ISO YYYY-MM-DD
  const getLocalDateISO = () => {
    const d = new Date();
    const offset = d.getTimezoneOffset() * 60000;
    return new Date(d.getTime() - offset).toISOString().split('T')[0];
  };

  const addSale = (
    customerId: string, 
    items: CartItem[], 
    total: number, 
    paidAmount: number, 
    splits: PaymentSplit[], 
    returnedVacios: number, 
    manualTimestamp?: number,
    vehicleId?: string // New optional parameter
  ) => {
    const debtAmount = Math.max(0, total - paidAmount);

    // Calculate Asset Movement (Jugs)
    const jugsSold = items
      .filter(i => i.category === 'Agua' || i.name.toLowerCase().includes('garraf'))
      .reduce((acc, item) => acc + item.quantity, 0);

    const netJugChange = jugsSold - returnedVacios;

    const newSale: Sale = {
      id: `TKT-${Date.now().toString().slice(-6)}`,
      timestamp: manualTimestamp || Date.now(),
      customerId,
      customerAlias: customers.find(c => c.id === customerId)?.alias || 'Anonimo',
      items,
      total,
      paidAmount,
      change: Math.max(0, paidAmount - total),
      paymentSplits: splits,
      emptyGarrafonsReturned: returnedVacios,
      synced: false
    };

    setSales(prev => [newSale, ...prev]);

    // Update Customer Balance and Jug Inventory
    setCustomers(prev => prev.map(c => {
      if (c.id === customerId) {
        return { 
          ...c, 
          balance: (c.balance || 0) + debtAmount,
          jugsOnLoan: Math.max(0, (c.jugsOnLoan || 0) + netJugChange)
        };
      }
      return c;
    }));

    // Logic to deduct inventory
    if (vehicleId && vehicleId !== 'plant') {
      // Deduct from specific vehicle
      setVehicles(prev => prev.map(v => {
        if (v.id !== vehicleId) return v;

        let currentInventory = [...(v.inventory || [])];

        items.forEach(soldItem => {
          const idx = currentInventory.findIndex(inv => inv.id === soldItem.id);
          if (idx !== -1) {
            // Reduce quantity
            const newQty = Math.max(0, currentInventory[idx].quantity - soldItem.quantity);
            if (newQty === 0) {
               currentInventory.splice(idx, 1);
            } else {
               currentInventory[idx] = { ...currentInventory[idx], quantity: newQty };
            }
          }
        });

        const newLoad = currentInventory.reduce((acc, i) => acc + (i.quantity || 0), 0);
        return { ...v, inventory: currentInventory, currentLoad: newLoad };
      }));
    } else {
      // Deduct from Plant (Default)
      setProducts(prev => prev.map(p => {
        const cartItem = items.find(item => item.id === p.id);
        return cartItem ? { ...p, stock: p.stock - cartItem.quantity } : p;
      }));
    }

    return newSale;
  };

  const resetSales = () => {
    setSales([]);
    alert("Todas las ventas han sido eliminadas. El historial está limpio.");
  };

  // --- MEGA SYNC FUNCTION ---
  // Merges external data for ALL modules into local state
  const syncData = useCallback((externalData: any) => {
    if (!externalData) return false;
    let changesMade = false;

    const mergeArray = <T extends { id: string }>(
      current: T[], 
      incoming: T[] | undefined, 
      setter: React.Dispatch<React.SetStateAction<T[]>>,
      sortFn?: (a: T, b: T) => number
    ) => {
      if (!incoming || !Array.isArray(incoming)) return;

      setter(prev => {
        const existingMap = new Map(prev.map(item => [item.id, item]));
        let localChanges = false;

        incoming.forEach(item => {
          const existing = existingMap.get(item.id);
          // Simple check: if not exists or stringified is different (deep compare equivalent)
          if (!existing || JSON.stringify(existing) !== JSON.stringify(item)) {
            // MIGRATION ON SYNC: If incoming employee has 'role' string, convert to 'roles'
            if ('role' in item && !('roles' in item)) {
               (item as any).roles = [(item as any).role];
               delete (item as any).role;
            }
            existingMap.set(item.id, item);
            localChanges = true;
            changesMade = true;
          }
        });

        if (!localChanges) return prev;

        const merged = Array.from(existingMap.values());
        return sortFn ? merged.sort(sortFn) : merged;
      });
    };

    // 1. Sales
    mergeArray(sales, externalData.sales, setSales, (a: any, b: any) => b.timestamp - a.timestamp);

    // 2. Customers
    mergeArray(customers, externalData.customers, setCustomers, (a: any, b: any) => a.alias.localeCompare(b.alias));

    // 3. Products
    mergeArray(products, externalData.products, setProducts);

    // 4. Orders
    mergeArray(orders, externalData.orders, setOrders, (a: any, b: any) => b.timestamp - a.timestamp);

    // 5. Vehicles
    mergeArray(vehicles, externalData.vehicles, setVehicles);

    // 6. Employees
    mergeArray(employees, externalData.employees, setEmployees);

    // 7. Quality
    mergeArray(qualityRecords, externalData.qualityRecords, setQualityRecords, (a: any, b: any) => b.timestamp - a.timestamp);

    // 8. Tasks
    mergeArray(tasks, externalData.tasks, setTasks, (a: any, b: any) => b.timestamp - a.timestamp);

    // 9. Attendance
    mergeArray(attendance, externalData.attendance, setAttendance, (a: any, b: any) => b.timestamp - a.timestamp);

    // 10. Saved Reports
    mergeArray(savedReports, externalData.savedReports, setSavedReports, (a: any, b: any) => b.timestamp - a.timestamp);

    // 11. Messages
    mergeArray(messages, externalData.messages, setMessages, (a: any, b: any) => a.timestamp - b.timestamp);

    // 12. Ticket Config (Object merge)
    if (externalData.ticketConfig) {
      if (JSON.stringify(ticketConfig) !== JSON.stringify(externalData.ticketConfig)) {
        setTicketConfig(externalData.ticketConfig);
        changesMade = true;
      }
    }

    return changesMade;
  }, []);

  const importCustomers = useCallback((newCustomers: Customer[]) => {
    setCustomers(prev => {
      const existingIds = new Set(prev.map(c => c.id));
      const filteredNew = newCustomers.filter(c => !existingIds.has(c.id));
      return [...prev, ...filteredNew];
    });
  }, []);

  const loadVehicle = (vehicleId: string, product: Product, delta: number) => {
    if (!product || !product.id) return;

    // Check plant stock only if loading (delta > 0)
    if (delta > 0) {
      const currentProduct = products.find(p => p.id === product.id);
      if (!currentProduct) return;
      if (currentProduct.stock < delta) {
          alert("Stock insuficiente en planta.");
          return;
      }
    }

    setVehicles(prev => prev.map(v => {
        if (v.id !== vehicleId) return v;

        const newInventory = Array.isArray(v.inventory) ? [...v.inventory] : [];
        const existingItemIndex = newInventory.findIndex(i => i.id === product.id);

        if (existingItemIndex > -1) {
            const newQty = newInventory[existingItemIndex].quantity + delta;
            if (newQty <= 0) {
                newInventory.splice(existingItemIndex, 1);
            } else {
                newInventory[existingItemIndex] = { ...newInventory[existingItemIndex], quantity: newQty };
            }
        } else if (delta > 0) {
            newInventory.push({ ...product, quantity: delta });
        }

        const newLoad = newInventory.reduce((acc, item) => acc + (item.quantity || 0), 0);

        return { ...v, inventory: newInventory, currentLoad: newLoad };
    }));

    setProducts(prev => prev.map(p => {
        if (p.id === product.id) {
            return { ...p, stock: p.stock - delta };
        }
        return p;
    }));
  };

  const addFuelRecord = (vehicleId: string, record: FuelRecord) => {
    setVehicles(prev => prev.map(v => {
      if (v.id !== vehicleId) return v;
      return { 
        ...v, 
        fuelHistory: [record, ...(v.fuelHistory || [])] 
      };
    }));
  };

  const sendMessage = (text: string, senderId: string, receiverId: string) => {
    const newMessage: Message = {
      id: `MSG-${Date.now()}`,
      text,
      senderId,
      receiverId,
      timestamp: Date.now(),
      read: false
    };

    // Update local state and trigger an immediate cloud push
    setMessages(prev => {
        const updatedMessages = [...prev, newMessage];

        // Background Cloud Push (Fire and Forget)
        if (cloudConfig.url && cloudConfig.autoSync) {
            const endpoint = `${cloudConfig.url}messages.json${cloudConfig.apiKey ? `?auth=${cloudConfig.apiKey}` : ''}`;
            fetch(endpoint, {
                method: 'PUT', // Overwrites the messages list with the new one
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(updatedMessages)
            }).catch(err => console.error("Error pushing message to cloud:", err));
        }

        return updatedMessages;
    });
  };

  return { 
    products, 
    saveProduct: (p: Product) => setProducts(prev => prev.find(x => x.id === p.id) ? prev.map(x => x.id === p.id ? p : x) : [...prev, p]),
    deleteProduct: (id: string) => setProducts(prev => prev.filter(p => p.id !== id)),
    customers, 
    saveCustomer: (c: Customer) => setCustomers(prev => prev.find(x => x.id === c.id) ? prev.map(x => x.id === c.id ? c : x) : [...prev, c]),
    deleteCustomer: (id: string) => setCustomers(prev => prev.filter(c => c.id !== id)),
    importCustomers,
    sales, addSale, resetSales,
    orders, 
    setOrders,
    addOrder: (o: Partial<Order>) => {
      const newOrder: Order = {
        id: `ORD-${Date.now().toString().slice(-6)}`,
        timestamp: Date.now(),
        status: 'pendiente',
        priority: 1,
        items: [],
        total: 0,
        customerId: '',
        customerAlias: '',
        ...o
      } as Order;
      setOrders(prev => [newOrder, ...prev]);
    },
    updateOrder: (o: Order) => setOrders(prev => prev.map(item => item.id === o.id ? o : item)),
    employees, 
    saveEmployee: (e: Employee) => setEmployees(prev => prev.find(x => x.id === e.id) ? prev.map(x => x.id === e.id ? e : x) : [...prev, e]),
    vehicles, 
    setVehicles,
    loadVehicle,
    deleteVehicle: (id: string) => setVehicles(prev => prev.filter(v => v.id !== id)),
    addFuelRecord,
    tasks,
    addTask: (t: Partial<Task>) => {
      const newTask: Task = {
        id: `TSK-${Date.now().toString().slice(-4)}`,
        timestamp: Date.now(),
        status: 'pendiente',
        ...t
      } as Task;
      setTasks(prev => [newTask, ...prev]);
    },
    updateTaskStatus: (id: string, status: Task['status']) => setTasks(prev => prev.map(t => t.id === id ? { ...t, status } : t)),
    deleteTask: (id: string) => setTasks(prev => prev.filter(t => t.id !== id)),
    clearTasksByDate: (date: string) => setTasks(prev => prev.filter(t => t.date !== date)),
    attendance,
    recordAttendance: (employeeId: string, status: Attendance['status']) => {
      const date = getLocalDateISO();
      setAttendance(prev => {
        const filtered = prev.filter(a => !(a.employeeId === employeeId && a.date === date));
        return [{ id: `ATT-${Date.now()}`, employeeId, status, date, timestamp: Date.now() }, ...filtered];
      });
    },
    qualityRecords,
    addQualityRecord: (r: Partial<QualityRecord>) => {
      const newRecord: QualityRecord = {
        id: `QUAL-${Date.now().toString().slice(-4)}`,
        timestamp: Date.now(),
        employeeId: 'admin',
        ...r
      } as QualityRecord;
      setQualityRecords(prev => [newRecord, ...prev]);
    },
    ticketConfig, setTicketConfig,
    cloudConfig, setCloudConfig,
    syncData,
    savedReports,
    addSavedReport: (r: SavedReport) => setSavedReports(prev => [r, ...prev]),
    deleteSavedReport: (id: string) => setSavedReports(prev => prev.filter(r => r.id !== id)),
    messages,
    sendMessage,
  };
};

// Create Context
const ERPContext = createContext<ReturnType<typeof useERPFactory> | null>(null);

// Provider Component
export const ERPProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const data = useERPFactory();
  return <ERPContext.Provider value={data}>{children}</ERPContext.Provider>;
};

// Accessor Hook (to be re-exported)
export const useERPDataHook = () => {
  const context = useContext(ERPContext);
  if (!context) throw new Error("useERPData must be used within ERPProvider");
  return context;
};

import React, { useState, useRef } from 'react';
import { Customer, GarrafonType } from '../types';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';
import { Filesystem, Directory, Encoding } from '@capacitor/filesystem';

const GARRAFON_TYPES: { type: GarrafonType, color: string }[] = [
  { type: 'Aqua', color: 'bg-blue-500' },
  { type: 'Bonafont', color: 'bg-orange-500' },
  { type: 'Ciel', color: 'bg-sky-400' },
  { type: 'E-Pura', color: 'bg-red-500' },
  { type: 'Generico', color: 'bg-slate-400' }
];

export const CustomersModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const { customers, saveCustomer, deleteCustomer, sales, importCustomers } = useERPData();
  const [search, setSearch] = useState('');
  const [editingCustomer, setEditingCustomer] = useState<Partial<Customer> | null>(null);
  const [viewingHistory, setViewingHistory] = useState<Customer | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const filteredCustomers = customers.filter(c => 
    c.name.toLowerCase().includes(search.toLowerCase()) || 
    c.alias.toLowerCase().includes(search.toLowerCase())
  );

  // --- LÓGICA DE NAVEGACIÓN INTELIGENTE ---
  const handleBackNavigation = () => {
    if (editingCustomer || viewingHistory) {
      setEditingCustomer(null);
      setViewingHistory(null);
    } else {
      onBack();
    }
  };

  const handleSave = () => {
    if (!editingCustomer?.name || !editingCustomer?.alias) {
      alert("Nombre y Alias son obligatorios.");
      return;
    }
    const customerToSave: Customer = {
      id: editingCustomer.id || Math.random().toString(36).substr(2, 9),
      name: editingCustomer.name,
      alias: editingCustomer.alias,
      phone: editingCustomer.phone || '',
      address: editingCustomer.address || '',
      specialPrice: editingCustomer.specialPrice || undefined,
      garrafonType: editingCustomer.garrafonType || 'Generico',
      jugsOnLoan: editingCustomer.jugsOnLoan || 0,
      balance: editingCustomer.balance || 0,
      lat: editingCustomer.lat,
      lng: editingCustomer.lng,
    };
    saveCustomer(customerToSave);
    setEditingCustomer(null);
  };

  const handleDelete = () => {
    if (!editingCustomer?.id) return;
    const confirmDelete = window.confirm(
      `¿Estás seguro de eliminar a "${editingCustomer.alias}"?\n\nEsta acción eliminará el registro del cliente permanentemente. Su historial de ventas se mantendrá como anónimo.`
    );
    if (confirmDelete) {
      deleteCustomer(editingCustomer.id);
      setEditingCustomer(null);
    }
  };

  const handleGetLocation = () => {
    if (!navigator.geolocation) {
      alert("Tu dispositivo no soporta geolocalización.");
      return;
    }

    const btn = document.getElementById('gps-btn');
    if(btn) {
       btn.innerHTML = '<i class="fas fa-circle-notch animate-spin"></i> Obteniendo...';
       btn.classList.add('opacity-50', 'pointer-events-none');
    }

    const onSuccess = (position: GeolocationPosition) => {
        setEditingCustomer(prev => prev ? ({
          ...prev,
          lat: position.coords.latitude,
          lng: position.coords.longitude
        }) : null);

        if(btn) {
          btn.innerHTML = '<i class="fas fa-check"></i> Ubicación Capturada';
          btn.classList.remove('opacity-50', 'pointer-events-none', 'bg-emerald-50', 'text-emerald-600');
          btn.classList.add('bg-emerald-50', 'text-white');
          setTimeout(() => {
             btn.innerHTML = '<i class="fas fa-location-crosshairs"></i> Actualizar GPS';
             btn.classList.remove('bg-emerald-500', 'text-white');
             btn.classList.add('bg-emerald-50', 'text-emerald-600');
          }, 3000);
        }
    };

    const onError = (error: GeolocationPositionError) => {
        console.error("GPS Error:", error);
        if(btn) {
          btn.innerHTML = '<i class="fas fa-triangle-exclamation"></i> Reintentar';
          btn.classList.remove('opacity-50', 'pointer-events-none');
        }
        alert(`No se pudo obtener la ubicación precise (Error ${error.code}). Verifica que el GPS esté encendido.`);
    };

    // Intento 1: Alta Precisión
    navigator.geolocation.getCurrentPosition(
      onSuccess,
      () => {
        console.warn("High accuracy failed, trying low accuracy...");
        // Intento 2: Baja Precisión (Fallback)
        navigator.geolocation.getCurrentPosition(onSuccess, onError, { 
            enableHighAccuracy: false, 
            timeout: 10000, 
            maximumAge: 0 
        });
      },
      { enableHighAccuracy: true, timeout: 5000, maximumAge: 0 }
    );
  };

  const openGoogleMaps = (lat?: number, lng?: number) => {
    if (lat && lng) {
      window.open(`https://www.google.com/maps/search/?api=1&query=${lat},${lng}`, '_blank');
    } else {
      alert("Este cliente no tiene ubicación registrada.");
    }
  };

  // --- LOGICA DE EXPORTACIÓN E IMPORTACIÓN ---

  const handleExportCSV = async () => {
    const headers = ["ID", "Nombre", "Alias", "Telefono", "Direccion", "Saldo", "Precio Especial", "Tipo Garrafon", "Garrafones Prestados", "Lat", "Lng"];
    const rows = customers.map(c => [
      c.id,
      `"${c.name}"`,
      `"${c.alias}"`,
      c.phone || '',
      `"${c.address || ''}"`,
      c.balance,
      c.specialPrice || '',
      c.garrafonType || 'Generico',
      c.jugsOnLoan || 0,
      c.lat || '',
      c.lng || ''
    ]);
    const csvContent = [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
    const fileName = `Clientes_Aqua_${new Date().getTime()}.csv`;

    try {
        // Intento 1: Guardar en Sistema de Archivos (Android/iOS)
        await Filesystem.writeFile({
            path: fileName,
            data: csvContent,
            directory: Directory.Documents,
            encoding: Encoding.UTF8
        });
        alert('Archivo CSV guardado exitosamente en la carpeta "Documentos" de tu dispositivo.');
    } catch (e) {
        console.warn("Filesystem write failed, falling back to browser download", e);

        // Intento 2: Descarga Web Clásica (Fallback)
        const blob = new Blob([csvContent], { type: 'text/csv' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = fileName;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    }
  };

  // --- NUEVA FUNCIÓN: IMPORTAR CONTACTOS DEL TELÉFONO ---
  const handleImportContacts = async () => {
    const nav = navigator as any;

    // Verificar soporte de la API de Selección de Contactos (Chrome Android / PWA)
    if ('contacts' in nav && 'select' in nav.contacts) {
      try {
        const props = ['name', 'tel', 'address'];
        const opts = { multiple: true };

        const contacts = await nav.contacts.select(props, opts);

        if (contacts.length > 0) {
           const newCustomers: Customer[] = contacts.map((c: any) => ({
             id: Math.random().toString(36).substr(2, 9),
             name: c.name[0] || 'Desconocido',
             alias: c.name[0] || 'Desconocido',
             phone: c.tel ? c.tel[0] : '',
             address: c.address ? c.address[0]?.addressLine : '',
             balance: 0,
             garrafonType: 'Generico'
           }));

           importCustomers(newCustomers);
           alert(`Se importaron ${newCustomers.length} contactos exitosamente.`);
        }
      } catch (ex) {
        // El usuario canceló o hubo error
        console.log("Importación cancelada o fallida:", ex);
      }
    } else {
      // Fallback: Explicar
      alert("Tu dispositivo no soporta la selección directa de contactos. Por favor usa la opción de 'Importar CSV' o agrega manualmente.");
    }
  };

  const handleImportFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      if (!text) return;

      try {
        let importedCount = 0;
        const newCustomers: Customer[] = [];

        if (file.name.toLowerCase().endsWith('.csv')) {
          const lines = text.replace(/\r\n/g, '\n').replace(/\r/g, '\n').split('\n');
          if (lines.length > 0) {
            const headerLine = lines[0].toLowerCase();
            const headers = headerLine.split(',').map(h => h.trim().replace(/^"|"$/g, ''));

            const idxNombre = headers.findIndex(h => h.includes('nombre'));
            const idxAlias = headers.findIndex(h => h.includes('alias') || h.includes('comercial'));
            const idxTelefono = headers.findIndex(h => h.includes('telefono') || h.includes('celular') || h.includes('whatsapp'));
            const idxDireccion = headers.findIndex(h => h.includes('direccion') || h.includes('domicilio'));
            const idxSaldo = headers.findIndex(h => h.includes('saldo'));
            const idxPrecio = headers.findIndex(h => h.includes('precio'));

            lines.slice(1).forEach(line => {
              if (!line.trim()) return;
              const cols = line.split(',').map(c => c.replace(/^"|"$/g, '').trim());
              const finalName = (idxNombre !== -1 ? cols[idxNombre] : '') || (idxAlias !== -1 ? cols[idxAlias] : '') || 'Importado';
              const finalAlias = (idxAlias !== -1 ? cols[idxAlias] : '') || finalName;

              if (finalAlias) {
                newCustomers.push({
                  id: Math.random().toString(36).substr(2, 9),
                  name: finalName,
                  alias: finalAlias,
                  phone: idxTelefono !== -1 ? cols[idxTelefono] : '',
                  address: idxDireccion !== -1 ? cols[idxDireccion] : '',
                  balance: idxSaldo !== -1 ? (parseFloat(cols[idxSaldo]) || 0) : 0,
                  specialPrice: idxPrecio !== -1 ? (parseFloat(cols[idxPrecio]) || undefined) : undefined,
                  garrafonType: 'Generico',
                });
                importedCount++;
              }
            });
          }
        }

        if (importedCount > 0) {
          importCustomers(newCustomers);
          alert(`¡Éxito! Se importaron ${importedCount} clientes.`);
        } else {
          alert("No se encontraron datos válidos en el CSV.");
        }
      } catch (err) {
