import React, { useState, useEffect } from 'react';
import { Product, Customer, CartItem, PaymentSplit, Sale, Employee, TicketConfig, Order } from '../types';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';
import html2canvas from 'html2canvas';
import { Filesystem, Directory } from '@capacitor/filesystem';
import { Share } from '@capacitor/share';
import { generateTicketPDF } from '../services/pdfGenerator';

// Helper to convert Uint8Array to Base64
const uint8ArrayToBase64 = (bytes: Uint8Array) => {
    let binary = '';
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) {
        binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
}

// --- COMPONENTE TICKET MODAL (ESTILO TÉRMICO) ---
interface TicketModalProps {
  sale: Sale;
  config: TicketConfig;
  onClose: () => void;
  onWhatsApp: () => void;
  onNewSale: () => void;
  onFinish: () => void;
}

const TicketModal = ({ sale, config, onClose, onWhatsApp, onNewSale, onFinish }: TicketModalProps) => {
  const [sharing, setSharing] = useState(false);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved' | 'error'>('idle');

  const qrData = btoa(`AQUA-PRO-SECURE|${JSON.stringify({ id: sale.id, total: sale.total })}`);
  const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(qrData)}`;

  // Auto-save effect
  useEffect(() => {
    const timer = setTimeout(() => {
      handleAutoSave();
    }, 800); // Wait for render
    return () => clearTimeout(timer);
  }, []);

  const handleAutoSave = async () => {
    try {
      setSaveStatus('saving');
      const element = document.getElementById('printable-ticket');
      if (!element) return;

      const canvas = await html2canvas(element, { 
        scale: 2, 
        backgroundColor: '#ffffff',
        logging: false 
      });

      const base64Data = canvas.toDataURL('image/png');
      const base64Content = base64Data.split(',')[1];
      const folderName = 'AquaTickets';
      const fileName = `Ticket_${sale.id}_${Date.now()}.png`;

      // Intentar guardar usando Filesystem nativo
      try {
        // 1. Crear directorio si no existe (recursive: true no tira error si ya existe)
        await Filesystem.mkdir({
            path: folderName,
            directory: Directory.Documents,
            recursive: true
        });

        // 2. Guardar archivo dentro del directorio
        await Filesystem.writeFile({
          path: `${folderName}/${fileName}`,
          data: base64Content,
          directory: Directory.Documents
        });
        setSaveStatus('saved');
      } catch (fsError) {
        console.warn("Filesystem save failed (likely web browser), skipping auto-save to disk", fsError);
        setSaveStatus('error');
      }

    } catch (e) {
      console.error("Error generating image", e);
      setSaveStatus('error');
    }
  };

  const handleSharePDF = async () => {
    setSharing(true);
    try {
        const pdfBytes = await generateTicketPDF(sale, config);
        const base64Content = uint8ArrayToBase64(pdfBytes);
        const fileName = `Ticket_${sale.id}.pdf`;

        // 1. Guardar temporalmente en Cache
        const savedFile = await Filesystem.writeFile({
          path: fileName,
          data: base64Content,
          directory: Directory.Cache
        });

        // 2. Compartir usando Plugin Nativo
        await Share.share({
          title: `Ticket ${sale.id}`,
          text: `Hola ${sale.customerAlias}, adjunto tu ticket de compra.`,
          url: savedFile.uri,
          dialogTitle: 'Compartir Ticket PDF'
        });

    } catch (e) {
        console.error("Error compartiendo PDF:", e);
        // Fallback para navegador web
        try {
             const pdfBytes = await generateTicketPDF(sale, config);
             const file = new File([pdfBytes], `Ticket_${sale.id}.pdf`, { type: 'application/pdf' });
             const url = URL.createObjectURL(file);
             const link = document.createElement('a');
             link.href = url;
             link.download = file.name;
             link.click();
             setTimeout(() => URL.revokeObjectURL(url), 1000);
             alert("Se descargó el PDF (Modo Web).");
        } catch(webErr) {
             alert("No se pudo compartir ni descargar el archivo.");
        }
    } finally {
        setSharing(false);
    }
  };

  const handleSavePDF = async () => {
    try {
      setSaveStatus('saving');
      const pdfBytes = await generateTicketPDF(sale, config);
      const base64Content = uint8ArrayToBase64(pdfBytes);
      const folderName = 'AquaTickets';
      const fileName = `Reporte_${sale.id}.pdf`;

      // Crear directorio
      await Filesystem.mkdir({
          path: folderName,
          directory: Directory.Documents,
          recursive: true
      });

      await Filesystem.writeFile({
        path: `${folderName}/${fileName}`,
        data: base64Content,
        directory: Directory.Documents
      });

      setSaveStatus('saved');
      alert(`PDF Guardado en: Documentos/${folderName}/${fileName}`);

      if (!(window as any).Capacitor?.isNative) {
         // Browser Fallback
         const blob = new Blob([pdfBytes], { type: 'application/pdf' });
         const url = URL.createObjectURL(blob);
         const link = document.createElement('a');
         link.href = url;
         link.download = fileName;
         link.click();
         setTimeout(() => URL.revokeObjectURL(url), 1000);
      }

    } catch (e) {
      console.error("Error saving PDF", e);
      setSaveStatus('error');
      alert("Error al generar el PDF.");
    } finally {
      setTimeout(() => setSaveStatus('idle'), 2000);
    }
  };

  const handleNativeShare = async () => {
    setSharing(true);
    try {
      const element = document.getElementById('printable-ticket');
      if (!element) return;

      const canvas = await html2canvas(element, { 
        scale: 2, 
        backgroundColor: '#ffffff',
        logging: false 
      });

      const base64Data = canvas.toDataURL('image/png');
      const base64Content = base64Data.split(',')[1];
      const fileName = `Ticket_${sale.id}.png`;

      // 1. Guardar en Cache
      const savedFile = await Filesystem.writeFile({
          path: fileName,
          data: base64Content,
          directory: Directory.Cache
      });

      // 2. Compartir Nativo
      await Share.share({
        title: `Ticket ${sale.id}`,
        text: `Gracias por tu compra en ${config.businessName}.`,
        url: savedFile.uri,
        dialogTitle: 'Compartir Imagen Ticket'
      });

    } catch (e) {
      console.error(e);
      // Fallback Web
      alert("Error al compartir nativamente. Descargando imagen...");
      try {
        const element = document.getElementById('printable-ticket');
        if (element) {
             const canvas = await html2canvas(element);
             const link = document.createElement('a');
             link.href = canvas.toDataURL('image/png');
             link.download = `Ticket_${sale.id}.png`;
             link.click();
        }
      } catch (webErr) { console.error(webErr); }
    } finally {
      setSharing(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[300] bg-slate-900/80 backdrop-blur-sm flex flex-col items-center justify-center p-4 animate-fadeIn">
      {/* Contenedor Visual del Ticket (Simula Papel) - Adaptado */}
      <div className="bg-white w-full max-w-[340px] max-h-[85vh] shadow-2xl rounded-3xl overflow-hidden flex flex-col relative print:w-full print:shadow-none print:max-w-none print:max-h-none print:absolute print:top-0 print:left-0 print:rounded-none">

        {/* Efecto de papel cortado */}
