};

// --- DEVICE ID MANAGEMENT ---
const getDeviceId = () => {
  let id = localStorage.getItem('aqua_device_id');
  if (!id) {
    // Generar un ID corto único (ej: 4A2B)
    id = Math.random().toString(36).substring(2, 6).toUpperCase();
    localStorage.setItem('aqua_device_id', id);
  }
  return id;
};

// Hook Logic Factory
const useERPFactory = () => {
  const [deviceId] = useState(getDeviceId());

  const [products, setProducts] = useState<Product[]>(() => {
    const saved = localStorage.getItem('aqua_products');
    return saved ? JSON.parse(saved) : INITIAL_PRODUCTS;
  });

  const [customers, setCustomers] = useState<Customer[]>(() => {
    const saved = localStorage.getItem('aqua_customers');
    return saved ? JSON.parse(saved).map((c: any) => ({ ...c, balance: c.balance || 0 })) : INITIAL_CUSTOMERS;
  });

  const [ticketConfig, setTicketConfig] = useState<TicketConfig>(() => {
    const saved = localStorage.getItem('aqua_ticket_config');
    // Ensure colorHex exists for older saved configs
    const parsed = saved ? JSON.parse(saved) : INITIAL_TICKET_CONFIG;
    return { ...INITIAL_TICKET_CONFIG, ...parsed };
  });

  const [cloudConfig, setCloudConfig] = useState<CloudConfig>(() => {
    const saved = localStorage.getItem('aqua_cloud_config');
    if (saved) {
      const parsed = JSON.parse(saved);
      if (!parsed.url || parsed.url === '') {
        return INITIAL_CLOUD_CONFIG;
      }
      return parsed;
    }
    return INITIAL_CLOUD_CONFIG;
  });

  const [sales, setSales] = useState<Sale[]>(() => {
    const saved = localStorage.getItem('aqua_sales');
    return saved ? JSON.parse(saved) : [];
  });

  const [orders, setOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('aqua_orders');
    return saved ? JSON.parse(saved) : [];
  });

  const [employees, setEmployees] = useState<Employee[]>(() => {
    const saved = localStorage.getItem('aqua_employees');
    let initial = saved ? JSON.parse(saved) : [
      { id: 'admin', name: 'Gerente General', roles: ['Administrador'], phone: '3312345678', pin: '1234', permissions: [...DEFAULT_PERMISSIONS] }
    ];

    // MIGRATION: Convert single role string to roles array if needed
    initial = initial.map((e: any) => {
      if (e.role && !e.roles) {
        return { ...e, roles: [e.role], role: undefined };
      }
      return e;
    });

    return initial;
  });

  // Ensure Admins always have full permissions on load
  useEffect(() => {
    setEmployees(prev => prev.map(e => 
      e.roles.includes('Administrador')
        ? { ...e, permissions: [...DEFAULT_PERMISSIONS] } 
        : e
    ));
  }, []);

  const [vehicles, setVehicles] = useState<Vehicle[]>(() => {
    const saved = localStorage.getItem('aqua_vehicles');
    // Migration: ensure inventory and fuelHistory arrays exist
    const parsed = saved ? JSON.parse(saved) : [{ id: 'v1', plate: 'ABC-123', description: 'Nissan NP300', loadCapacity: 60, currentLoad: 0, inventory: [], fuelHistory: [] }];
    return parsed.map((v: any) => ({
        ...v,
        inventory: v.inventory || [],
        fuelHistory: v.fuelHistory || []
    }));
  });

  const [qualityRecords, setQualityRecords] = useState<QualityRecord[]>(() => {
    const saved = localStorage.getItem('aqua_quality');
    return saved ? JSON.parse(saved) : [];
  });

  const [tasks, setTasks] = useState<Task[]>(() => {
    const saved = localStorage.getItem('aqua_tasks');
    return saved ? JSON.parse(saved) : [];
  });

  const [attendance, setAttendance] = useState<Attendance[]>(() => {
    const saved = localStorage.getItem('aqua_attendance');
    return saved ? JSON.parse(saved) : [];
  });

  const [savedReports, setSavedReports] = useState<SavedReport[]>(() => {
    const saved = localStorage.getItem('aqua_saved_reports');
    return saved ? JSON.parse(saved) : [];
  });

  const [messages, setMessages] = useState<Message[]>(() => {
    const saved = localStorage.getItem('aqua_messages');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => {
    localStorage.setItem('aqua_products', JSON.stringify(products));
    localStorage.setItem('aqua_customers', JSON.stringify(customers));
    localStorage.setItem('aqua_sales', JSON.stringify(sales));
    localStorage.setItem('aqua_orders', JSON.stringify(orders));
    localStorage.setItem('aqua_employees', JSON.stringify(employees));
    localStorage.setItem('aqua_vehicles', JSON.stringify(vehicles));
    localStorage.setItem('aqua_ticket_config', JSON.stringify(ticketConfig));
    localStorage.setItem('aqua_quality', JSON.stringify(qualityRecords));
    localStorage.setItem('aqua_tasks', JSON.stringify(tasks));
    localStorage.setItem('aqua_attendance', JSON.stringify(attendance));
    localStorage.setItem('aqua_cloud_config', JSON.stringify(cloudConfig));
    localStorage.setItem('aqua_saved_reports', JSON.stringify(savedReports));
    localStorage.setItem('aqua_messages', JSON.stringify(messages));
  }, [products, customers, sales, orders, employees, vehicles, ticketConfig, qualityRecords, tasks, attendance, cloudConfig, savedReports, messages]);

  // Helper para fecha local ISO YYYY-MM-DD
  const getLocalDateISO = () => {
    const d = new Date();
    const offset = d.getTimezoneOffset() * 60000;
    return new Date(d.getTime() - offset).toISOString().split('T')[0];
  };

  const addSale = (
    customerId: string, 
    items: CartItem[], 
    total: number, 
    paidAmount: number, 
    splits: PaymentSplit[], 
    returnedVacios: number, 
    manualTimestamp?: number,
    vehicleId?: string // New optional parameter
  ) => {
    const debtAmount = Math.max(0, total - paidAmount);

    // Calculate Asset Movement (Jugs)
    const jugsSold = items
      .filter(i => i.category === 'Agua' || i.name.toLowerCase().includes('garraf'))
      .reduce((acc, item) => acc + item.quantity, 0);

    const netJugChange = jugsSold - returnedVacios;

    // ID GENERATION: Includes Device ID to prevent collisions during sync
    const timestamp = manualTimestamp || Date.now();
    const uniqueId = `TKT-${timestamp.toString().slice(-6)}-${deviceId}`;

    const newSale: Sale = {
      id: uniqueId,
      timestamp: timestamp,
      customerId,
      customerAlias: customers.find(c => c.id === customerId)?.alias || 'Anonimo',
      items,
      total,
      paidAmount,
      change: Math.max(0, paidAmount - total),
      paymentSplits: splits,
      emptyGarrafonsReturned: returnedVacios,
      synced: false,
      deviceId: deviceId // Metadata for traceability
    };

    setSales(prev => [newSale, ...prev]);

    // Update Customer Balance and Jug Inventory
    setCustomers(prev => prev.map(c => {
      if (c.id === customerId) {
        return { 
          ...c, 
          balance: (c.balance || 0) + debtAmount,
          jugsOnLoan: Math.max(0, (c.jugsOnLoan || 0) + netJugChange)
        };
      }
      return c;
    }));

    // Logic to deduct inventory
    if (vehicleId && vehicleId !== 'plant') {
      // Deduct from specific vehicle
      setVehicles(prev => prev.map(v => {
        if (v.id !== vehicleId) return v;

        let currentInventory = [...(v.inventory || [])];

        items.forEach(soldItem => {
          const idx = currentInventory.findIndex(inv => inv.id === soldItem.id);
          if (idx !== -1) {
            // Reduce quantity
            const newQty = Math.max(0, currentInventory[idx].quantity - soldItem.quantity);
            if (newQty === 0) {
               currentInventory.splice(idx, 1);
            } else {
               currentInventory[idx] = { ...currentInventory[idx], quantity: newQty };
            }
          }
        });

        const newLoad = currentInventory.reduce((acc, i) => acc + (i.quantity || 0), 0);
        return { ...v, inventory: currentInventory, currentLoad: newLoad };
      }));
    } else {
      // Deduct from Plant (Default)
      setProducts(prev => prev.map(p => {
        const cartItem = items.find(item => item.id === p.id);
        return cartItem ? { ...p, stock: p.stock - cartItem.quantity } : p;
      }));
    }

    return newSale;
  };

  const resetSales = () => {
    setSales([]);
    alert("Todas las ventas han sido eliminadas. El historial está limpio.");
  };

  // --- MEGA SYNC FUNCTION ---
  // Merges external data for ALL modules into local state
  const syncData = useCallback((externalData: any) => {
    if (!externalData) return false;
    let changesMade = false;

    const mergeArray = <T extends { id: string }>(
      current: T[], 
      incoming: T[] | undefined, 
      setter: React.Dispatch<React.SetStateAction<T[]>>,
      sortFn?: (a: T, b: T) => number
    ) => {
      if (!incoming || !Array.isArray(incoming)) return;

      setter(prev => {
        const existingMap = new Map(prev.map(item => [item.id, item]));
        let localChanges = false;

        incoming.forEach(item => {
          const existing = existingMap.get(item.id);
          // Simple check: if not exists or stringified is different (deep compare equivalent)
          if (!existing || JSON.stringify(existing) !== JSON.stringify(item)) {
            // MIGRATION ON SYNC: If incoming employee has 'role' string, convert to 'roles'
            if ('role' in item && !('roles' in item)) {
               (item as any).roles = [(item as any).role];
               delete (item as any).role;
            }
            existingMap.set(item.id, item);
            localChanges = true;
            changesMade = true;
          }
        });

        if (!localChanges) return prev;

        const merged = Array.from(existingMap.values());
        return sortFn ? merged.sort(sortFn) : merged;
      });
    };

    // 1. Sales
    mergeArray(sales, externalData.sales, setSales, (a: any, b: any) => b.timestamp - a.timestamp);

    // 2. Customers
    mergeArray(customers, externalData.customers, setCustomers, (a: any, b: any) => a.alias.localeCompare(b.alias));

    // 3. Products
    mergeArray(products, externalData.products, setProducts);

    // 4. Orders
    mergeArray(orders, externalData.orders, setOrders, (a: any, b: any) => b.timestamp - a.timestamp);

    // 5. Vehicles
    mergeArray(vehicles, externalData.vehicles, setVehicles);

    // 6. Employees
    mergeArray(employees, externalData.employees, setEmployees);

    // 7. Quality
    mergeArray(qualityRecords, externalData.qualityRecords, setQualityRecords, (a: any, b: any) => b.timestamp - a.timestamp);

    // 8. Tasks
    mergeArray(tasks, externalData.tasks, setTasks, (a: any, b: any) => b.timestamp - a.timestamp);

    // 9. Attendance
    mergeArray(attendance, externalData.attendance, setAttendance, (a: any, b: any) => b.timestamp - a.timestamp);

    // 10. Saved Reports
    mergeArray(savedReports, externalData.savedReports, setSavedReports, (a: any, b: any) => b.timestamp - a.timestamp);

    // 11. Messages
    mergeArray(messages, externalData.messages, setMessages, (a: any, b: any) => a.timestamp - b.timestamp);

    // 12. Ticket Config (Object merge)
    if (externalData.ticketConfig) {
      if (JSON.stringify(ticketConfig) !== JSON.stringify(externalData.ticketConfig)) {
        setTicketConfig(externalData.ticketConfig);
        changesMade = true;
      }
    }

    return changesMade;
  }, []);

  const importCustomers = useCallback((newCustomers: Customer[]) => {
    setCustomers(prev => {
      const existingIds = new Set(prev.map(c => c.id));
      const filteredNew = newCustomers.filter(c => !existingIds.has(c.id));
      return [...prev, ...filteredNew];
    });
  }, []);

  const loadVehicle = (vehicleId: string, product: Product, delta: number) => {
    if (!product || !product.id) return;

    // Check plant stock only if loading (delta > 0)
    if (delta > 0) {
      const currentProduct = products.find(p => p.id === product.id);
      if (!currentProduct) return;
      if (currentProduct.stock < delta) {
          alert("Stock insuficiente en planta.");
          return;
      }
    }

    setVehicles(prev => prev.map(v => {
        if (v.id !== vehicleId) return v;

        const newInventory = Array.isArray(v.inventory) ? [...v.inventory] : [];
        const existingItemIndex = newInventory.findIndex(i => i.id === product.id);

        if (existingItemIndex > -1) {
            const newQty = newInventory[existingItemIndex].quantity + delta;
            if (newQty <= 0) {
                newInventory.splice(existingItemIndex, 1);
            } else {
                newInventory[existingItemIndex] = { ...newInventory[existingItemIndex], quantity: newQty };
            }
        } else if (delta > 0) {
            newInventory.push({ ...product, quantity: delta });
        }

        const newLoad = newInventory.reduce((acc, item) => acc + (item.quantity || 0), 0);

        return { ...v, inventory: newInventory, currentLoad: newLoad };
    }));

    setProducts(prev => prev.map(p => {
        if (p.id === product.id) {
            return { ...p, stock: p.stock - delta };
        }
        return p;
    }));
  };

  const addFuelRecord = (vehicleId: string, record: FuelRecord) => {
    setVehicles(prev => prev.map(v => {
      if (v.id !== vehicleId) return v;
      return { 
        ...v, 
        fuelHistory: [record, ...(v.fuelHistory || [])] 
      };
    }));
  };

  const sendMessage = (text: string, senderId: string, receiverId: string) => {
    const newMessage: Message = {
      id: `MSG-${Date.now()}`,
      text,
      senderId,
      receiverId,
      timestamp: Date.now(),
      read: false
    };

    // Update local state and trigger an immediate cloud push
    setMessages(prev => {
        const updatedMessages = [...prev, newMessage];

        // Background Cloud Push (Fire and Forget)
        if (cloudConfig.url && cloudConfig.autoSync) {
            const endpoint = `${cloudConfig.url}messages.json${cloudConfig.apiKey ? `?auth=${cloudConfig.apiKey}` : ''}`;
            fetch(endpoint, {
                method: 'PUT', // Overwrites the messages list with the new one
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(updatedMessages)
            }).catch(err => console.error("Error pushing message to cloud:", err));
        }

        return updatedMessages;
    });
  };

  return { 
    deviceId, // Expose Device ID
    products, 
    saveProduct: (p: Product) => setProducts(prev => prev.find(x => x.id === p.id) ? prev.map(x => x.id === p.id ? p : x) : [...prev, p]),
    deleteProduct: (id: string) => setProducts(prev => prev.filter(p => p.id !== id)),
    customers, 
    saveCustomer: (c: Customer) => setCustomers(prev => prev.find(x => x.id === c.id) ? prev.map(x => x.id === c.id ? c : x) : [...prev, c]),
    deleteCustomer: (id: string) => setCustomers(prev => prev.filter(c => c.id !== id)),
    importCustomers,
    sales, addSale, resetSales,
    orders, 
    setOrders,
    addOrder: (o: Partial<Order>) => {
      const newOrder: Order = {
        // ID Generation with Device ID to prevent sync collisions
        id: `ORD-${Date.now().toString().slice(-6)}-${deviceId}`,
        timestamp: Date.now(),
        status: 'pendiente',
        priority: 1,
        items: [],
        total: 0,
        customerId: '',
        customerAlias: '',
        deviceId: deviceId, // Metadata
        ...o
      } as Order;
      setOrders(prev => [newOrder, ...prev]);
    },
    updateOrder: (o: Order) => setOrders(prev => prev.map(item => item.id === o.id ? o : item)),
    employees, 
    saveEmployee: (e: Employee) => setEmployees(prev => prev.find(x => x.id === e.id) ? prev.map(x => x.id === e.id ? e : x) : [...prev, e]),
    vehicles, 
    setVehicles,
    loadVehicle,
    deleteVehicle: (id: string) => setVehicles(prev => prev.filter(v => v.id !== id)),
    addFuelRecord,
    tasks,
    addTask: (t: Partial<Task>) => {
      const newTask: Task = {
        id: `TSK-${Date.now().toString().slice(-4)}-${deviceId}`,
        timestamp: Date.now(),
        status: 'pendiente',
        deviceId: deviceId,
        ...t
      } as Task;
      setTasks(prev => [newTask, ...prev]);
    },
    updateTaskStatus: (id: string, status: Task['status']) => setTasks(prev => prev.map(t => t.id === id ? { ...t, status } : t)),
    deleteTask: (id: string) => setTasks(prev => prev.filter(t => t.id !== id)),
    clearTasksByDate: (date: string) => setTasks(prev => prev.filter(t => t.date !== date)),
    attendance,
    recordAttendance: (employeeId: string, status: Attendance['status']) => {
      const date = getLocalDateISO();
      setAttendance(prev => {
        const filtered = prev.filter(a => !(a.employeeId === employeeId && a.date === date));
        return [{ id: `ATT-${Date.now()}`, employeeId, status, date, timestamp: Date.now() }, ...filtered];
      });
    },
    qualityRecords,
    addQualityRecord: (r: Partial<QualityRecord>) => {
      const newRecord: QualityRecord = {
        id: `QUAL-${Date.now().toString().slice(-4)}`,
        timestamp: Date.now(),
        employeeId: 'admin',
        ...r
      } as QualityRecord;
      setQualityRecords(prev => [newRecord, ...prev]);
    },
    ticketConfig, setTicketConfig,
    cloudConfig, setCloudConfig,
    syncData,
    savedReports,
    addSavedReport: (r: SavedReport) => setSavedReports(prev => [r, ...prev]),
    deleteSavedReport: (id: string) => setSavedReports(prev => prev.filter(r => r.id !== id)),
    messages,
    sendMessage,
  };
};

// Create Context
const ERPContext = createContext<ReturnType<typeof useERPFactory> | null>(null);

// Provider Component
export const ERPProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const data = useERPFactory();
  return <ERPContext.Provider value={data}>{children}</ERPContext.Provider>;
};

// Accessor Hook (to be re-exported)
export const useERPDataHook = () => {
  const context = useContext(ERPContext);
  if (!context) throw new Error("useERPData must be used within ERPProvider");
  return context;
};

import React, { useState, useEffect } from 'react';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';

interface SyncModuleProps {
  onBack: () => void;
  onScanRequest: () => void;
  scannedId?: string;
}

type SyncStatus = 'idle' | 'syncing' | 'success' | 'error';

export const SyncModule: React.FC<SyncModuleProps> = ({ onBack, scannedId }) => {
  const { 
    sales, customers, products, orders, employees, vehicles, qualityRecords, tasks, attendance, savedReports, ticketConfig, messages,
    syncData, cloudConfig, setCloudConfig, deviceId // Added deviceId
  } = useERPData();

  const [status, setStatus] = useState<SyncStatus>('idle');
  const [logs, setLogs] = useState<string[]>([]);
  const [editingConfig, setEditingConfig] = useState(false);
  const [tempConfig, setTempConfig] = useState(cloudConfig);

  const addLog = (msg: string) => {
    setLogs(prev => [`[${new Date().toLocaleTimeString()}] ${msg}`, ...prev.slice(0, 4)]);
  };

  const handleSaveConfig = () => {
    // Validaciones básicas de URL de Firebase
    let url = tempConfig.url.trim();
    if (url && !url.endsWith('/')) url += '/';

    setCloudConfig({ ...tempConfig, url });
    setEditingConfig(false);
    addLog("Configuración guardada.");
  };

  const performSync = async () => {
    if (!cloudConfig.url) {
      alert("Configura primero la URL de tu base de datos (Firebase).");
      setEditingConfig(true);
      return;
    }

    setStatus('syncing');
    addLog(`Conectando ID: ${deviceId}...`);

    try {
      const endpoint = `${cloudConfig.url}aqua_data.json${cloudConfig.apiKey ? `?auth=${cloudConfig.apiKey}` : ''}`;

      // 1. GET: Descargar estado actual de la nube para fusionar
      addLog("Verificando estado remoto...");
      const getResponse = await fetch(endpoint);
      if (!getResponse.ok) throw new Error(`Error conexión: ${getResponse.statusText}`);

      const cloudData = await getResponse.json();

      // Construir Payload de Subida (Snapshot Local Completo)
      const uploadPayload = {
        sales, 
        customers, 
        products, 
        orders, 
        employees, 
        vehicles, 
        qualityRecords, 
        tasks, 
        attendance,
        savedReports, // Financial History
        ticketConfig, // System Settings
        messages,     // Chat History
        lastUpdated: Date.now(),
        deviceUser: deviceId || 'AquaPro Mobile' // Use actual Device ID
      };

      // Si hay datos en la nube, los aplicamos localmente primero
      if (cloudData) {
        addLog("Descargando cambios remotos...");
        syncData(cloudData);

        // Estrategia Robusta Simple:
        // Fusionamos manualmente los arrays críticos para el payload de subida inmediata
        // para no perder datos si cerramos la app inmediatamente después.

        const mergeForUpload = (localArr: any[], cloudArr: any[]) => {
           if (!cloudArr) return localArr;
           const localIds = new Set(localArr.map(i => i.id));
           const missingInLocal = cloudArr.filter((i: any) => !localIds.has(i.id));
           return [...localArr, ...missingInLocal];
        };

        uploadPayload.sales = mergeForUpload(sales, cloudData.sales);
        uploadPayload.customers = mergeForUpload(customers, cloudData.customers);
        uploadPayload.orders = mergeForUpload(orders, cloudData.orders);
        uploadPayload.messages = mergeForUpload(messages, cloudData.messages);
        uploadPayload.tasks = mergeForUpload(tasks, cloudData.tasks);
      }

      addLog("Subiendo datos locales...");
      const putResponse = await fetch(endpoint, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(uploadPayload)
      });

      if (!putResponse.ok) throw new Error("Error al escribir en nube");

      setCloudConfig(prev => ({ ...prev, lastSync: Date.now() }));
      setStatus('success');
      addLog("¡Sincronización Total Completada!");

    } catch (error: any) {
      console.error(error);
      setStatus('error');
      addLog(`Error: ${error.message}`);
    } finally {
      setTimeout(() => setStatus(prev => prev === 'syncing' ? 'idle' : prev), 2000);
    }
  };

  // Auto-sync effect
  useEffect(() => {
    if (cloudConfig.autoSync && cloudConfig.url && status === 'idle') {
      const timer = setInterval(() => {
        // Sync cada 10 segundos si está en auto
        performSync();
      }, 10000); // 10 segundos
      return () => clearInterval(timer);
    }
  }, [cloudConfig, status]);

  if (editingConfig) {
    return (
      <div className="h-full bg-slate-50 animate-fadeIn pb-24 overflow-y-auto">
        <ModuleHeader title="Configurar Nube" onBack={() => setEditingConfig(false)} />
        <div className="px-6 space-y-6">
          <div className="bg-white p-6 rounded-[2rem] shadow-lg border border-indigo-100">
             <div className="flex items-center gap-3 mb-4">
                <i className="fas fa-fire text-amber-500 text-2xl"></i>
                <h3 className="font-black text-sky-900">Firebase Realtime DB</h3>
             </div>
             <p className="text-xs text-slate-500 mb-6 leading-relaxed">
               Conecta tu ERP a una base de datos Firebase para sincronización en tiempo real a través de internet (sin necesidad de estar en la misma red Wi-Fi).
             </p>

             <div className="space-y-4">
               <div>
                 <label className="text-[10px] font-black uppercase text-sky-400 ml-2">URL de la Base de Datos</label>
                 <input 
                   type="url" 
                   placeholder="https://mi-proyecto.firebaseio.com/" 
                   className="w-full bg-slate-50 p-4 rounded-2xl outline-none font-bold text-sky-900 focus:ring-2 ring-indigo-300 transition-all text-xs"
                   value={tempConfig.url}
                   onChange={e => setTempConfig({...tempConfig, url: e.target.value})}
                 />
                 <p className="text-[9px] text-slate-400 mt-1 ml-2">Copia esto desde la consola de Firebase {'>'} Realtime Database.</p>
               </div>

               <div>
                 <label className="text-[10px] font-black uppercase text-sky-400 ml-2">Secreto de Base de Datos (Auth)</label>
                 <input 
                   type="password" 
                   placeholder="Token de secreto..." 
                   className="w-full bg-slate-50 p-4 rounded-2xl outline-none font-bold text-sky-900 focus:ring-2 ring-indigo-300 transition-all text-xs"
                   value={tempConfig.apiKey}
                   onChange={e => setTempConfig({...tempConfig, apiKey: e.target.value})}
                 />
                 <p className="text-[9px] text-slate-400 mt-1 ml-2">Configuración del Proyecto {'>'} Cuentas de servicio {'>'} Secretos.</p>
               </div>

               <div className="flex items-center gap-3 bg-indigo-50 p-4 rounded-2xl">
                 <div 
                   onClick={() => setTempConfig({...tempConfig, autoSync: !tempConfig.autoSync})}
                   className={`w-12 h-7 rounded-full p-1 transition-colors cursor-pointer ${tempConfig.autoSync ? 'bg-indigo-500' : 'bg-slate-300'}`}
                 >
                   <div className={`w-5 h-5 bg-white rounded-full shadow-sm transition-transform ${tempConfig.autoSync ? 'translate-x-5' : ''}`}></div>
                 </div>
                 <span className="text-xs font-bold text-indigo-900">Sincronización Automática (10 seg)</span>
               </div>
             </div>
          </div>
          <ActionButton onClick={handleSaveConfig}>Guardar Conexión</ActionButton>
        </div>
      </div>
    );
  }

  return (
    <div className="h-full bg-slate-900 text-white flex flex-col animate-fadeIn overflow-hidden pb-24">
      <div className="px-6 pt-8 pb-4 flex items-center justify-between">
        <div className="flex items-center gap-4">
          <button onClick={onBack} className="w-12 h-12 bg-white/10 rounded-2xl flex items-center justify-center active:scale-90 transition-transform">
            <i className="fas fa-arrow-left"></i>
          </button>
          <div>
            <h2 className="text-xl font-black tracking-tight">Aqua Cloud</h2>
            <div className="flex items-center gap-2">
               <div className={`w-2 h-2 rounded-full ${cloudConfig.url ? 'bg-emerald-400' : 'bg-red-500'}`}></div>
               <span className="text-[10px] font-bold uppercase opacity-70">{cloudConfig.url ? 'Conectado' : 'Desconectado'}</span>
            </div>
          </div>
        </div>
        <button onClick={() => setEditingConfig(true)} className="w-10 h-10 bg-white/10 rounded-xl flex items-center justify-center text-sm active:bg-white/20">
          <i className="fas fa-gear"></i>
        </button>
      </div>

      <div className="flex-1 overflow-y-auto px-6 space-y-8 no-scrollbar pb-10 flex flex-col justify-center">

        <div className="relative">
           {/* Status Ring */}
           <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-64 h-64 rounded-full border-4 border-indigo-500/20"></div>
           <div className={`absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-64 h-64 rounded-full border-t-4 border-indigo-500 transition-all duration-1000 ${status === 'syncing' ? 'animate-spin' : ''}`}></div>

           <div className="flex flex-col items-center justify-center relative z-10">
              <div className={`w-32 h-32 rounded-full flex items-center justify-center text-5xl shadow-[0_0_50px_rgba(99,102,241,0.3)] transition-all ${status === 'syncing' ? 'bg-indigo-600 scale-110' : status === 'success' ? 'bg-emerald-500' : status === 'error' ? 'bg-red-500' : 'bg-slate-800 border border-slate-700'}`}>
                 <i className={`fas ${status === 'syncing' ? 'fa-rotate animate-spin' : status === 'success' ? 'fa-check' : status === 'error' ? 'fa-triangle-exclamation' : 'fa-cloud'}`}></i>
              </div>

              <h3 className="text-2xl font-black mt-6 mb-1">
                {status === 'syncing' ? 'Sincronizando...' : status === 'success' ? 'Todo al día' : 'Nube Aqua+'}
              </h3>

              {cloudConfig.lastSync ? (
                <div className="flex flex-col items-center gap-1">
                  <p className="text-xs font-mono opacity-50 bg-black/20 px-3 py-1 rounded-full">
                    Última vez: {new Date(cloudConfig.lastSync).toLocaleTimeString()}
                  </p>
                  <p className="text-[8px] font-mono text-indigo-400">ID: {deviceId}</p>
                </div>
              ) : (
                <p className="text-xs font-bold opacity-50">Nunca sincronizado</p>
              )}
           </div>
        </div>

        <div className="space-y-4">
           <button 
             onClick={performSync}
             disabled={status === 'syncing'}
             className="w-full bg-white text-indigo-900 py-6 rounded-[2.5rem] font-black uppercase text-sm tracking-widest shadow-2xl shadow-indigo-500/20 active:scale-95 transition-all disabled:opacity-50 flex items-center justify-center gap-3"
           >
             {status === 'syncing' ? 'Procesando...' : 'Sincronizar Todo'}
             {!status.includes('sync') && <i className="fas fa-arrow-right-arrow-left"></i>}
           </button>

           <div className="grid grid-cols-2 gap-4 text-center">
              <div className="bg-white/5 p-4 rounded-3xl border border-white/5">
                 <p className="text-[10px] font-black uppercase opacity-40 mb-1">Ventas</p>
                 <p className="text-xl font-black">{sales.length}</p>
              </div>
              <div className="bg-white/5 p-4 rounded-3xl border border-white/5">
                 <p className="text-[10px] font-black uppercase opacity-40 mb-1">Inventario</p>
                 <p className="text-xl font-black">{products.reduce((a,b) => a + b.stock, 0)}</p>
              </div>
              <div className="bg-white/5 p-4 rounded-3xl border border-white/5">
                 <p className="text-[10px] font-black uppercase opacity-40 mb-1">Pedidos</p>
                 <p className="text-xl font-black">{orders.length}</p>
              </div>
              <div className="bg-white/5 p-4 rounded-3xl border border-white/5">
                 <p className="text-[10px] font-black uppercase opacity-40 mb-1">Clientes</p>
                 <p className="text-xl font-black">{customers.length}</p>
              </div>
           </div>
        </div>

        {/* Console Log */}
        <div className="bg-black/40 rounded-2xl p-4 font-mono text-[9px] h-32 overflow-hidden border border-white/5 relative">
          <div className="flex justify-between items-center mb-2 opacity-50 sticky top-0">
            <span>ACTIVITY LOG</span>
            <i className="fas fa-terminal"></i>
          </div>
          <div className="space-y-1">
            {logs.length === 0 && <span className="opacity-30">Esperando acción...</span>}
            {logs.map((log, i) => (
              <div key={i} className="opacity-80 border-l-2 border-indigo-500 pl-2">{log}</div>
            ))}
          </div>
        </div>

      </div>
    </div>
  );
};

export type ViewType = 'dashboard' | 'pos' | 'orders' | 'logistics' | 'production' | 'sync' | 'whatsapp' | 'customers' | 'employees' | 'reports' | 'settings' | 'quality' | 'scanner' | 'inventory' | 'tickets' | 'supplies' | 'messages';

export interface Product {
  id: string;
  name: string;
  price: number;
  stock: number;
  category?: 'Agua' | 'Insumos' | 'Accesorios';
  lastUpdated?: number;
}

export type GarrafonType = 'Aqua' | 'Bonafont' | 'Ciel' | 'E-Pura' | 'Generico';

export interface Customer {
  id: string;
  name: string;
  alias: string;
  address?: string; 
  phone?: string;
  specialPrice?: number;
  lat?: number;
  lng?: number;
  garrafonType?: GarrafonType;
  jugsOnLoan?: number; 
  balance: number;
  lastUpdated?: number;
}

export interface TicketConfig {
  businessName: string;
  rfc: string;
  address: string;
  phone: string;
  footerMessage: string;
  logoUrl?: string;
  website?: string;
  socialMedia?: string;
  extraNote?: string;
  slogan?: string;
  email?: string;
  colorHex?: string; 
}

export interface CloudConfig {
  url: string;
  apiKey: string;
  autoSync: boolean;
  lastSync?: number;
}

export interface Order {
  id: string;
  customerId: string;
  customerAlias: string;
  items: CartItem[];
  total: number;
  status: 'pendiente' | 'asignado' | 'entregado' | 'cancelado';
  vehicleId?: string;
  timestamp: number;
  priority: number;
  deviceId?: string; 
  lastUpdated?: number; // Crucial for sync conflict resolution
}

export interface CartItem extends Product {
  quantity: number;
}

export type PaymentMethod = 'Efectivo' | 'Transferencia' | 'Crédito' | 'Multimodal';

export interface PaymentSplit {
  method: 'Efectivo' | 'Transferencia';
  amount: number;
}

export interface Sale {
  id: string;
  timestamp: number;
  customerId: string;
  customerAlias: string;
  items: CartItem[];
  total: number;
  paidAmount: number;
  change: number;
  paymentSplits: PaymentSplit[];
  emptyGarrafonsReturned: number;
  synced: boolean;
  deviceId?: string; 
}

export interface QualityRecord {
  id: string;
  timestamp: number;
  type: 'Cruda' | 'Producto';
  ph: number;
  cloro: number;
  tds: number;
  dureza: number;
  color: string;
  sabor: string;
  turbiedad: string;
  employeeId: string;
}

export interface Task {
  id: string;
  employeeId: string;
  title: string;
  description?: string;
  status: 'pendiente' | 'completada';
  timestamp: number;
  date: string;
  deviceId?: string; 
  lastUpdated?: number;
}

export interface Attendance {
  id: string;
  employeeId: string;
  timestamp: number;
  date: string;
  status: 'presente' | 'falta' | 'retardo';
}

export type Role = 'Repartidor' | 'Planta' | 'Administrador';

export interface Employee {
  id: string;
  name: string;
  roles: Role[]; 
  phone: string;
  pin: string;
  permissions: ViewType[];
  lastUpdated?: number;
}

export interface FuelRecord {
  id: string;
  date: number;
  mileage: number;
  liters: number;
  cost: number;
  notes?: string;
}

export interface Vehicle {
  id: string;
  plate: string;
  description: string;
  loadCapacity: number;
  currentLoad: number;
  inventory: CartItem[]; 
  fuelHistory: FuelRecord[]; 
  lastUpdated?: number;
}

export interface SavedReport {
  id: string;
  timestamp: number;
  rangeType: 'day' | 'week' | 'month';
  dateLabel: string; 
  totalGross: number;
  totalTransactions: number;
  averageTicket: number;
  payments: { cash: number, transfer: number };
  topProducts: { name: string, qty: number, total: number }[];
  notes?: string;
}

export interface Message {
  id: string;
  text: string;
  senderId: string;
  receiverId: string; 
  timestamp: number;
  read: boolean;
}

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { Product, Customer, Sale, CartItem, Order, Employee, Vehicle, PaymentSplit, ViewType, QualityRecord, Task, Attendance, TicketConfig, CloudConfig, SavedReport, FuelRecord, Message, Role } from '../types';
import { INITIAL_PRODUCTS, INITIAL_CUSTOMERS } from '../constants';

const DEFAULT_PERMISSIONS: ViewType[] = ['dashboard', 'pos', 'orders', 'customers', 'logistics', 'inventory', 'whatsapp', 'production', 'sync', 'reports', 'settings', 'employees', 'quality', 'scanner', 'tickets', 'messages'];

const INITIAL_TICKET_CONFIG: TicketConfig = {
  businessName: 'AQUA+ FUNDADORES',
  rfc: 'AQUA900101-XXX',
  address: 'Calle del Agua #123, Col. Manantiales',
  phone: '33-1234-5678',
  footerMessage: '¡Gracias por tu preferencia! Frescura que hidrata tu vida.',
  website: 'www.aquafun.mx',
  socialMedia: '@aquafun_pro',
  extraNote: 'No hay cambios después de 24 horas.',
  logoUrl: 'data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 100 100%22><rect width=%22100%22 height=%22100%22 rx=%2225%22 fill=%22%230284c7%22/><path d=%22M50 20C50 20 30 45 30 60C30 71.0457 38.9543 80 50 80C61.0457 80 70 71.0457 70 60C70 45 50 20 50 20Z%22 fill=%22white%22/></svg>',
  colorHex: '#0284c7', // Sky-600 default
  email: 'contacto@aquafun.mx'
};

const INITIAL_CLOUD_CONFIG: CloudConfig = {
  url: 'https://aquamasfundadores-default-rtdb.firebaseio.com/',
  apiKey: 't8rzxkeWbMIKGufdW7RV1j1bKS0TKf2gPkgmZ36A',
  autoSync: true
};

// --- DEVICE ID MANAGEMENT ---
const getDeviceId = () => {
  let id = localStorage.getItem('aqua_device_id');
  if (!id) {
    // Generar un ID corto único (ej: 4A2B)
    id = Math.random().toString(36).substring(2, 6).toUpperCase();
    localStorage.setItem('aqua_device_id', id);
  }
  return id;
};

// Hook Logic Factory
const useERPFactory = () => {
  const [deviceId] = useState(getDeviceId());

  const [products, setProducts] = useState<Product[]>(() => {
    const saved = localStorage.getItem('aqua_products');
    return saved ? JSON.parse(saved) : INITIAL_PRODUCTS;
  });

  const [customers, setCustomers] = useState<Customer[]>(() => {
    const saved = localStorage.getItem('aqua_customers');
    return saved ? JSON.parse(saved).map((c: any) => ({ ...c, balance: c.balance || 0 })) : INITIAL_CUSTOMERS;
  });

  const [ticketConfig, setTicketConfig] = useState<TicketConfig>(() => {
    const saved = localStorage.getItem('aqua_ticket_config');
    // Ensure colorHex exists for older saved configs
    const parsed = saved ? JSON.parse(saved) : INITIAL_TICKET_CONFIG;
    return { ...INITIAL_TICKET_CONFIG, ...parsed };
  });

  const [cloudConfig, setCloudConfig] = useState<CloudConfig>(() => {
    const saved = localStorage.getItem('aqua_cloud_config');
    if (saved) {
      const parsed = JSON.parse(saved);
      if (!parsed.url || parsed.url === '') {
        return INITIAL_CLOUD_CONFIG;
      }
      return parsed;
    }
    return INITIAL_CLOUD_CONFIG;
  });

  const [sales, setSales] = useState<Sale[]>(() => {
    const saved = localStorage.getItem('aqua_sales');
    return saved ? JSON.parse(saved) : [];
  });

  const [orders, setOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('aqua_orders');
    return saved ? JSON.parse(saved) : [];
  });

  const [employees, setEmployees] = useState<Employee[]>(() => {
    const saved = localStorage.getItem('aqua_employees');
    let initial = saved ? JSON.parse(saved) : [
      { id: 'admin', name: 'Gerente General', roles: ['Administrador'], phone: '3312345678', pin: '1234', permissions: [...DEFAULT_PERMISSIONS] }
    ];

    // MIGRATION: Convert single role string to roles array if needed
    initial = initial.map((e: any) => {
      if (e.role && !e.roles) {
        return { ...e, roles: [e.role], role: undefined };
      }
      return e;
    });

    return initial;
  });

  // Ensure Admins always have full permissions on load
  useEffect(() => {
    setEmployees(prev => prev.map(e => 
      e.roles.includes('Administrador')
        ? { ...e, permissions: [...DEFAULT_PERMISSIONS] } 
        : e
    ));
  }, []);

  const [vehicles, setVehicles] = useState<Vehicle[]>(() => {
    const saved = localStorage.getItem('aqua_vehicles');
    // Migration: ensure inventory and fuelHistory arrays exist
    const parsed = saved ? JSON.parse(saved) : [{ id: 'v1', plate: 'ABC-123', description: 'Nissan NP300', loadCapacity: 60, currentLoad: 0, inventory: [], fuelHistory: [] }];
    return parsed.map((v: any) => ({
        ...v,
        inventory: v.inventory || [],
        fuelHistory: v.fuelHistory || []
    }));
  });

  const [qualityRecords, setQualityRecords] = useState<QualityRecord[]>(() => {
    const saved = localStorage.getItem('aqua_quality');
    return saved ? JSON.parse(saved) : [];
  });

  const [tasks, setTasks] = useState<Task[]>(() => {
    const saved = localStorage.getItem('aqua_tasks');
    return saved ? JSON.parse(saved) : [];
  });

  const [attendance, setAttendance] = useState<Attendance[]>(() => {
    const saved = localStorage.getItem('aqua_attendance');
    return saved ? JSON.parse(saved) : [];
  });

  const [savedReports, setSavedReports] = useState<SavedReport[]>(() => {
    const saved = localStorage.getItem('aqua_saved_reports');
    return saved ? JSON.parse(saved) : [];
  });

  const [messages, setMessages] = useState<Message[]>(() => {
    const saved = localStorage.getItem('aqua_messages');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => {
    localStorage.setItem('aqua_products', JSON.stringify(products));
    localStorage.setItem('aqua_customers', JSON.stringify(customers));
    localStorage.setItem('aqua_sales', JSON.stringify(sales));
    localStorage.setItem('aqua_orders', JSON.stringify(orders));
    localStorage.setItem('aqua_employees', JSON.stringify(employees));
    localStorage.setItem('aqua_vehicles', JSON.stringify(vehicles));
    localStorage.setItem('aqua_ticket_config', JSON.stringify(ticketConfig));
    localStorage.setItem('aqua_quality', JSON.stringify(qualityRecords));
    localStorage.setItem('aqua_tasks', JSON.stringify(tasks));
    localStorage.setItem('aqua_attendance', JSON.stringify(attendance));
    localStorage.setItem('aqua_cloud_config', JSON.stringify(cloudConfig));
    localStorage.setItem('aqua_saved_reports', JSON.stringify(savedReports));
    localStorage.setItem('aqua_messages', JSON.stringify(messages));
  }, [products, customers, sales, orders, employees, vehicles, ticketConfig, qualityRecords, tasks, attendance, cloudConfig, savedReports, messages]);

  // Helper para fecha local ISO YYYY-MM-DD
  const getLocalDateISO = () => {
    const d = new Date();
    const offset = d.getTimezoneOffset() * 60000;
    return new Date(d.getTime() - offset).toISOString().split('T')[0];
  };

  const addSale = (
    customerId: string, 
    items: CartItem[], 
    total: number, 
    paidAmount: number, 
    splits: PaymentSplit[], 
    returnedVacios: number, 
    manualTimestamp?: number,
    vehicleId?: string // New optional parameter
  ) => {
    const debtAmount = Math.max(0, total - paidAmount);

    // Calculate Asset Movement (Jugs)
    const jugsSold = items
      .filter(i => i.category === 'Agua' || i.name.toLowerCase().includes('garraf'))
      .reduce((acc, item) => acc + item.quantity, 0);

    const netJugChange = jugsSold - returnedVacios;

    // ID GENERATION: Includes Device ID to prevent collisions during sync
    const timestamp = manualTimestamp || Date.now();
    const uniqueId = `TKT-${timestamp.toString().slice(-6)}-${deviceId}`;

    const newSale: Sale = {
      id: uniqueId,
      timestamp: timestamp,
      customerId,
      customerAlias: customers.find(c => c.id === customerId)?.alias || 'Anonimo',
      items,
      total,
      paidAmount,
      change: Math.max(0, paidAmount - total),
      paymentSplits: splits,
      emptyGarrafonsReturned: returnedVacios,
      synced: false,
      deviceId: deviceId // Metadata for traceability
    };

    setSales(prev => [newSale, ...prev]);

    // Update Customer Balance and Jug Inventory with LAST UPDATED
    setCustomers(prev => prev.map(c => {
      if (c.id === customerId) {
        return { 
          ...c, 
          balance: (c.balance || 0) + debtAmount,
          jugsOnLoan: Math.max(0, (c.jugsOnLoan || 0) + netJugChange),
          lastUpdated: Date.now() // Track change
        };
      }
      return c;
    }));

    // Logic to deduct inventory
    if (vehicleId && vehicleId !== 'plant') {
      // Deduct from specific vehicle
      setVehicles(prev => prev.map(v => {
        if (v.id !== vehicleId) return v;

        let currentInventory = [...(v.inventory || [])];

        items.forEach(soldItem => {
          const idx = currentInventory.findIndex(inv => inv.id === soldItem.id);
          if (idx !== -1) {
            // Reduce quantity
            const newQty = Math.max(0, currentInventory[idx].quantity - soldItem.quantity);
            if (newQty === 0) {
               currentInventory.splice(idx, 1);
            } else {
               currentInventory[idx] = { ...currentInventory[idx], quantity: newQty };
            }
          }
        });

        const newLoad = currentInventory.reduce((acc, i) => acc + (i.quantity || 0), 0);
        return { ...v, inventory: currentInventory, currentLoad: newLoad, lastUpdated: Date.now() };
      }));
    } else {
      // Deduct from Plant (Default)
      setProducts(prev => prev.map(p => {
        const cartItem = items.find(item => item.id === p.id);
        return cartItem ? { ...p, stock: p.stock - cartItem.quantity, lastUpdated: Date.now() } : p;
      }));
    }

    return newSale;
  };

  const resetSales = () => {
    setSales([]);
    alert("Todas las ventas han sido eliminadas. El historial está limpio.");
  };

  // --- MEGA SYNC FUNCTION ---
  // Accepts a partial State object and merges it.
  // Note: Most merge logic is now handled in SyncModule's smartMerge before calling this,
  // but we keep basic safety checks here.
  const syncData = useCallback((externalData: any) => {
    if (!externalData) return false;
    let changesMade = false;

    // Helper to just set the data (assuming SyncModule did the heavy lifting/merging)
    const setIfPresent = <T,>(key: string, setter: React.Dispatch<React.SetStateAction<T>>) => {
        if (externalData[key]) {
            setter(externalData[key]);
            changesMade = true;
        }
    };

    setIfPresent('sales', setSales);
    setIfPresent('customers', setCustomers);
    setIfPresent('products', setProducts);
    setIfPresent('orders', setOrders);
    setIfPresent('vehicles', setVehicles);
    setIfPresent('employees', setEmployees);
    setIfPresent('qualityRecords', setQualityRecords);
    setIfPresent('tasks', setTasks);
    setIfPresent('attendance', setAttendance);
    setIfPresent('savedReports', setSavedReports);
    setIfPresent('messages', setMessages);

    // Ticket Config (Object merge)
    if (externalData.ticketConfig) {
      if (JSON.stringify(ticketConfig) !== JSON.stringify(externalData.ticketConfig)) {
        setTicketConfig(externalData.ticketConfig);
        changesMade = true;
      }
    }

    return changesMade;
  }, [ticketConfig]);

  const importCustomers = useCallback((newCustomers: Customer[]) => {
    setCustomers(prev => {
      const existingIds = new Set(prev.map(c => c.id));
      const filteredNew = newCustomers.filter(c => !existingIds.has(c.id));
      // Mark imported as updated now
      const withTimestamp = filteredNew.map(c => ({...c, lastUpdated: Date.now()}));
      return [...prev, ...withTimestamp];
    });
  }, []);

  const loadVehicle = (vehicleId: string, product: Product, delta: number) => {
    if (!product || !product.id) return;

    if (delta > 0) {
      const currentProduct = products.find(p => p.id === product.id);
      if (!currentProduct) return;
      if (currentProduct.stock < delta) {
          alert("Stock insuficiente en planta.");
          return;
      }
    }

    setVehicles(prev => prev.map(v => {
        if (v.id !== vehicleId) return v;

        const newInventory = Array.isArray(v.inventory) ? [...v.inventory] : [];
        const existingItemIndex = newInventory.findIndex(i => i.id === product.id);

        if (existingItemIndex > -1) {
            const newQty = newInventory[existingItemIndex].quantity + delta;
            if (newQty <= 0) {
                newInventory.splice(existingItemIndex, 1);
            } else {
                newInventory[existingItemIndex] = { ...newInventory[existingItemIndex], quantity: newQty };
            }
        } else if (delta > 0) {
            newInventory.push({ ...product, quantity: delta });
        }

        const newLoad = newInventory.reduce((acc, item) => acc + (item.quantity || 0), 0);

        return { ...v, inventory: newInventory, currentLoad: newLoad, lastUpdated: Date.now() };
    }));

    setProducts(prev => prev.map(p => {
        if (p.id === product.id) {
            return { ...p, stock: p.stock - delta, lastUpdated: Date.now() };
        }
        return p;
    }));
  };

  const addFuelRecord = (vehicleId: string, record: FuelRecord) => {
    setVehicles(prev => prev.map(v => {
      if (v.id !== vehicleId) return v;
      return { 
        ...v, 
        fuelHistory: [record, ...(v.fuelHistory || [])],
        lastUpdated: Date.now()
      };
    }));
  };

  const sendMessage = (text: string, senderId: string, receiverId: string) => {
    const newMessage: Message = {
      id: `MSG-${Date.now()}`,
      text,
      senderId,
      receiverId,
      timestamp: Date.now(),
      read: false
    };

    setMessages(prev => {
        const updatedMessages = [...prev, newMessage];
        if (cloudConfig.url && cloudConfig.autoSync) {
            const endpoint = `${cloudConfig.url}messages.json${cloudConfig.apiKey ? `?auth=${cloudConfig.apiKey}` : ''}`;
            fetch(endpoint, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(updatedMessages)
            }).catch(err => console.error("Error pushing message to cloud:", err));
        }
        return updatedMessages;
    });
  };

  return { 
    deviceId,
    products, 
    saveProduct: (p: Product) => setProducts(prev => prev.find(x => x.id === p.id) ? prev.map(x => x.id === p.id ? { ...p, lastUpdated: Date.now() } : x) : [...prev, { ...p, lastUpdated: Date.now() }]),
    deleteProduct: (id: string) => setProducts(prev => prev.filter(p => p.id !== id)),
    customers, 
    saveCustomer: (c: Customer) => setCustomers(prev => prev.find(x => x.id === c.id) ? prev.map(x => x.id === c.id ? { ...c, lastUpdated: Date.now() } : x) : [...prev, { ...c, lastUpdated: Date.now() }]),
    deleteCustomer: (id: string) => setCustomers(prev => prev.filter(c => c.id !== id)),
    importCustomers,
    sales, addSale, resetSales,
    orders, 
    setOrders,
    addOrder: (o: Partial<Order>) => {
      const newOrder: Order = {
        id: `ORD-${Date.now().toString().slice(-6)}-${deviceId}`,
        timestamp: Date.now(),
        status: 'pendiente',
        priority: 1,
        items: [],
        total: 0,
        customerId: '',
        customerAlias: '',
        deviceId: deviceId,
        lastUpdated: Date.now(), // Track creation
        ...o
      } as Order;
      setOrders(prev => [newOrder, ...prev]);
    },
    updateOrder: (o: Order) => setOrders(prev => prev.map(item => item.id === o.id ? { ...o, lastUpdated: Date.now() } : item)),
    employees, 
    saveEmployee: (e: Employee) => setEmployees(prev => prev.find(x => x.id === e.id) ? prev.map(x => x.id === e.id ? { ...e, lastUpdated: Date.now() } : x) : [...prev, { ...e, lastUpdated: Date.now() }]),
    vehicles, 
    setVehicles,
    loadVehicle,
    deleteVehicle: (id: string) => setVehicles(prev => prev.filter(v => v.id !== id)),
    addFuelRecord,
    tasks,
    addTask: (t: Partial<Task>) => {
      const newTask: Task = {
        id: `TSK-${Date.now().toString().slice(-4)}-${deviceId}`,
        timestamp: Date.now(),
        status: 'pendiente',
        deviceId: deviceId,
        lastUpdated: Date.now(),
        ...t
      } as Task;
      setTasks(prev => [newTask, ...prev]);
    },
    updateTaskStatus: (id: string, status: Task['status']) => setTasks(prev => prev.map(t => t.id === id ? { ...t, status, lastUpdated: Date.now() } : t)),
    deleteTask: (id: string) => setTasks(prev => prev.filter(t => t.id !== id)),
    clearTasksByDate: (date: string) => setTasks(prev => prev.filter(t => t.date !== date)),
    attendance,
    recordAttendance: (employeeId: string, status: Attendance['status']) => {
      const date = getLocalDateISO();
      setAttendance(prev => {
        const filtered = prev.filter(a => !(a.employeeId === employeeId && a.date === date));
        return [{ id: `ATT-${Date.now()}`, employeeId, status, date, timestamp: Date.now() }, ...filtered];
      });
    },
    qualityRecords,
    addQualityRecord: (r: Partial<QualityRecord>) => {
      const newRecord: QualityRecord = {
        id: `QUAL-${Date.now().toString().slice(-4)}`,
        timestamp: Date.now(),
        employeeId: 'admin',
        ...r
      } as QualityRecord;
      setQualityRecords(prev => [newRecord, ...prev]);
    },
    ticketConfig, setTicketConfig,
    cloudConfig, setCloudConfig,
    syncData,
    savedReports,
    addSavedReport: (r: SavedReport) => setSavedReports(prev => [r, ...prev]),
    deleteSavedReport: (id: string) => setSavedReports(prev => prev.filter(r => r.id !== id)),
    messages,
    sendMessage,
  };
};

// Create Context
const ERPContext = createContext<ReturnType<typeof useERPFactory> | null>(null);

// Provider Component
export const ERPProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const data = useERPFactory();
  return <ERPContext.Provider value={data}>{children}</ERPContext.Provider>;
};

// Accessor Hook (to be re-exported)
export const useERPDataHook = () => {
  const context = useContext(ERPContext);
  if (!context) throw new Error("useERPData must be used within ERPProvider");
  return context;
};

import React, { useState, useEffect } from 'react';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';

interface SyncModuleProps {
  onBack: () => void;
  onScanRequest: () => void;
  scannedId?: string;
}

type SyncStatus = 'idle' | 'syncing' | 'success' | 'error';

export const SyncModule: React.FC<SyncModuleProps> = ({ onBack, scannedId }) => {
  const { 
    sales, customers, products, orders, employees, vehicles, qualityRecords, tasks, attendance, savedReports, ticketConfig, messages,
    syncData, cloudConfig, setCloudConfig, deviceId
  } = useERPData();

  const [status, setStatus] = useState<SyncStatus>('idle');
  const [logs, setLogs] = useState<string[]>([]);
  const [editingConfig, setEditingConfig] = useState(false);
  const [tempConfig, setTempConfig] = useState(cloudConfig);

  const addLog = (msg: string) => {
    setLogs(prev => [`[${new Date().toLocaleTimeString()}] ${msg}`, ...prev.slice(0, 4)]);
  };

  const handleSaveConfig = () => {
    let url = tempConfig.url.trim();
    if (url && !url.endsWith('/')) url += '/';
    setCloudConfig({ ...tempConfig, url });
    setEditingConfig(false);
    addLog("Configuración guardada.");
  };

  // --- SMART MERGE ALGORITHM ---
  // Combines local data with cloud data, prioritizing the most recently modified item
  const smartMerge = <T extends { id: string, timestamp?: number, lastUpdated?: number }>(
    localList: T[], 
    cloudList: T[] = []
  ): T[] => {
    const combinedMap = new Map<string, T>();

    // 1. Start with Cloud Data
    if (Array.isArray(cloudList)) {
        cloudList.forEach(item => combinedMap.set(item.id, item));
    }

    // 2. Merge Local Data
    localList.forEach(localItem => {
        const existingCloudItem = combinedMap.get(localItem.id);

        if (!existingCloudItem) {
            // New local item, simply add
            combinedMap.set(localItem.id, localItem);
        } else {
            // Conflict! Resolve by Timestamp
            // Prefer 'lastUpdated', fallback to 'timestamp' (creation time)
            const localTime = localItem.lastUpdated || localItem.timestamp || 0;
            const cloudTime = existingCloudItem.lastUpdated || existingCloudItem.timestamp || 0;

            if (localTime >= cloudTime) {
                // Local is newer or equal, overwrite cloud version
                combinedMap.set(localItem.id, localItem);
            } 
            // Else: Cloud is newer, keep existingCloudItem (do nothing)
        }
    });

    return Array.from(combinedMap.values());
  };

  const performSync = async () => {
    if (!cloudConfig.url) {
      alert("Configura primero la URL de tu base de datos (Firebase).");
      setEditingConfig(true);
      return;
    }

    setStatus('syncing');
    addLog(`Iniciando Smart Sync ID: ${deviceId}...`);

    try {
      const endpoint = `${cloudConfig.url}aqua_data.json${cloudConfig.apiKey ? `?auth=${cloudConfig.apiKey}` : ''}`;

      // 1. GET: Descargar estado actual de la nube
      addLog("📥 Descargando nube...");
      const getResponse = await fetch(endpoint);
      if (!getResponse.ok) throw new Error(`Error conexión: ${getResponse.statusText}`);

      const cloudData = await getResponse.json() || {};

      // 2. MERGE: Fusión inteligente en memoria
      addLog("⚡ Fusionando cambios...");

      const mergedSales = smartMerge(sales, cloudData.sales);
      const mergedCustomers = smartMerge(customers, cloudData.customers);
      const mergedProducts = smartMerge(products, cloudData.products); // Inventory implies lastUpdated check
      const mergedOrders = smartMerge(orders, cloudData.orders);
      const mergedTasks = smartMerge(tasks, cloudData.tasks);
      const mergedEmployees = smartMerge(employees, cloudData.employees);
      const mergedVehicles = smartMerge(vehicles, cloudData.vehicles);
      const mergedMessages = smartMerge(messages, cloudData.messages);

      // Data sets that are additive-only usually (logs)
      const mergedQuality = smartMerge(qualityRecords, cloudData.qualityRecords);
      const mergedAttendance = smartMerge(attendance, cloudData.attendance);
      const mergedReports = smartMerge(savedReports, cloudData.savedReports);

      // 3. APPLY: Actualizar estado local con la fusión
      // We reconstruct a full data object to pass to syncData
      const finalState = {
          sales: mergedSales,
          customers: mergedCustomers,
          products: mergedProducts,
          orders: mergedOrders,
          employees: mergedEmployees,
          vehicles: mergedVehicles,
          qualityRecords: mergedQuality,
          tasks: mergedTasks,
          attendance: mergedAttendance,
          savedReports: mergedReports,
          messages: mergedMessages,
          ticketConfig: cloudData.ticketConfig || ticketConfig // Prefer cloud config if exists
      };

      syncData(finalState);

      // 4. UPLOAD: Subir la fusión maestra a la nube
      // This is safer now because we included everything from cloud that we didn't have
      addLog("📤 Subiendo maestro...");

      const uploadPayload = {
        ...finalState,
        lastUpdated: Date.now(),
        deviceUser: deviceId || 'AquaPro Mobile'
      };

      const putResponse = await fetch(endpoint, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(uploadPayload)
      });

      if (!putResponse.ok) throw new Error("Error al escribir en nube");

      setCloudConfig(prev => ({ ...prev, lastSync: Date.now() }));
      setStatus('success');
      addLog("✅ Sincronización Exitosa");

    } catch (error: any) {
      console.error(error);
      setStatus('error');
      addLog(`❌ Error: ${error.message}`);
    } finally {
      setTimeout(() => setStatus(prev => prev === 'syncing' ? 'idle' : prev), 2000);
    }
  };

  // Auto-sync effect
  useEffect(() => {
    if (cloudConfig.autoSync && cloudConfig.url && status === 'idle') {
      const timer = setInterval(() => {
        // Sync cada 15 segundos si está en auto
        performSync();
      }, 15000); 
      return () => clearInterval(timer);
    }
  }, [cloudConfig, status]);

  if (editingConfig) {
    return (
      <div className="h-full bg-slate-50 animate-fadeIn pb-24 overflow-y-auto">
        <ModuleHeader title="Configurar Nube" onBack={() => setEditingConfig(false)} />
        <div className="px-6 space-y-6">
          <div className="bg-white p-6 rounded-[2rem] shadow-lg border border-indigo-100">
             <div className="flex items-center gap-3 mb-4">
                <i className="fas fa-fire text-amber-500 text-2xl"></i>
                <h3 className="font-black text-sky-900">Firebase Realtime DB</h3>
             </div>
             <p className="text-xs text-slate-500 mb-6 leading-relaxed">
               Conecta tu ERP a una base de datos Firebase para sincronización en tiempo real a través de internet (sin necesidad de estar en la misma red Wi-Fi).
             </p>

             <div className="space-y-4">
               <div>
                 <label className="text-[10px] font-black uppercase text-sky-400 ml-2">URL de la Base de Datos</label>
                 <input 
                   type="url" 
                   placeholder="https://mi-proyecto.firebaseio.com/" 
                   className="w-full bg-slate-50 p-4 rounded-2xl outline-none font-bold text-sky-900 focus:ring-2 ring-indigo-300 transition-all text-xs"
                   value={tempConfig.url}
                   onChange={e => setTempConfig({...tempConfig, url: e.target.value})}
                 />
                 <p className="text-[9px] text-slate-400 mt-1 ml-2">Copia esto desde la consola de Firebase {'>'} Realtime Database.</p>
               </div>

               <div>
                 <label className="text-[10px] font-black uppercase text-sky-400 ml-2">Secreto de Base de Datos (Auth)</label>
                 <input 
                   type="password" 
                   placeholder="Token de secreto..." 
                   className="w-full bg-slate-50 p-4 rounded-2xl outline-none font-bold text-sky-900 focus:ring-2 ring-indigo-300 transition-all text-xs"
                   value={tempConfig.apiKey}
                   onChange={e => setTempConfig({...tempConfig, apiKey: e.target.value})}
                 />
                 <p className="text-[9px] text-slate-400 mt-1 ml-2">Configuración del Proyecto {'>'} Cuentas de servicio {'>'} Secretos.</p>
               </div>

               <div className="flex items-center gap-3 bg-indigo-50 p-4 rounded-2xl">
                 <div 
                   onClick={() => setTempConfig({...tempConfig, autoSync: !tempConfig.autoSync})}
                   className={`w-12 h-7 rounded-full p-1 transition-colors cursor-pointer ${tempConfig.autoSync ? 'bg-indigo-500' : 'bg-slate-300'}`}
                 >
                   <div className={`w-5 h-5 bg-white rounded-full shadow-sm transition-transform ${tempConfig.autoSync ? 'translate-x-5' : ''}`}></div>
                 </div>
                 <span className="text-xs font-bold text-indigo-900">Sincronización Automática (15 seg)</span>
               </div>
             </div>
          </div>
          <ActionButton onClick={handleSaveConfig}>Guardar Conexión</ActionButton>
        </div>
      </div>
    );
  }

  return (
    <div className="h-full bg-slate-900 text-white flex flex-col animate-fadeIn overflow-hidden pb-24">
      <div className="px-6 pt-8 pb-4 flex items-center justify-between">
        <div className="flex items-center gap-4">
          <button onClick={onBack} className="w-12 h-12 bg-white/10 rounded-2xl flex items-center justify-center active:scale-90 transition-transform">
            <i className="fas fa-arrow-left"></i>
          </button>
          <div>
            <h2 className="text-xl font-black tracking-tight">Aqua Cloud</h2>
            <div className="flex items-center gap-2">
               <div className={`w-2 h-2 rounded-full ${cloudConfig.url ? 'bg-emerald-400' : 'bg-red-500'}`}></div>
               <span className="text-[10px] font-bold uppercase opacity-70">{cloudConfig.url ? 'Conectado' : 'Desconectado'}</span>
            </div>
          </div>
        </div>
        <button onClick={() => setEditingConfig(true)} className="w-10 h-10 bg-white/10 rounded-xl flex items-center justify-center text-sm active:bg-white/20">
          <i className="fas fa-gear"></i>
        </button>
      </div>

      <div className="flex-1 overflow-y-auto px-6 space-y-8 no-scrollbar pb-10 flex flex-col justify-center">

        <div className="relative">
           {/* Status Ring */}
           <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-64 h-64 rounded-full border-4 border-indigo-500/20"></div>
           <div className={`absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-64 h-64 rounded-full border-t-4 border-indigo-500 transition-all duration-1000 ${status === 'syncing' ? 'animate-spin' : ''}`}></div>

           <div className="flex flex-col items-center justify-center relative z-10">
              <div className={`w-32 h-32 rounded-full flex items-center justify-center text-5xl shadow-[0_0_50px_rgba(99,102,241,0.3)] transition-all ${status === 'syncing' ? 'bg-indigo-600 scale-110' : status === 'success' ? 'bg-emerald-500' : status === 'error' ? 'bg-red-500' : 'bg-slate-800 border border-slate-700'}`}>
                 <i className={`fas ${status === 'syncing' ? 'fa-rotate animate-spin' : status === 'success' ? 'fa-check' : status === 'error' ? 'fa-triangle-exclamation' : 'fa-cloud'}`}></i>
              </div>

              <h3 className="text-2xl font-black mt-6 mb-1">
                {status === 'syncing' ? 'Sincronizando...' : status === 'success' ? 'Todo al día' : 'Nube Aqua+'}
              </h3>

              {cloudConfig.lastSync ? (
                <div className="flex flex-col items-center gap-1">
                  <p className="text-xs font-mono opacity-50 bg-black/20 px-3 py-1 rounded-full">
                    Última vez: {new Date(cloudConfig.lastSync).toLocaleTimeString()}
                  </p>
                  <p className="text-[8px] font-mono text-indigo-400">ID: {deviceId}</p>
                </div>
              ) : (
                <p className="text-xs font-bold opacity-50">Nunca sincronizado</p>
              )}
           </div>
        </div>

        <div className="space-y-4">
           <button 
             onClick={performSync}
             disabled={status === 'syncing'}
             className="w-full bg-white text-indigo-900 py-6 rounded-[2.5rem] font-black uppercase text-sm tracking-widest shadow-2xl shadow-indigo-500/20 active:scale-95 transition-all disabled:opacity-50 flex items-center justify-center gap-3"
           >
             {status === 'syncing' ? 'Procesando...' : 'Sincronizar Todo'}
             {!status.includes('sync') && <i className="fas fa-arrow-right-arrow-left"></i>}
           </button>

           <div className="grid grid-cols-2 gap-4 text-center">
              <div className="bg-white/5 p-4 rounded-3xl border border-white/5">
                 <p className="text-[10px] font-black uppercase opacity-40 mb-1">Ventas</p>
                 <p className="text-xl font-black">{sales.length}</p>
              </div>
              <div className="bg-white/5 p-4 rounded-3xl border border-white/5">
                 <p className="text-[10px] font-black uppercase opacity-40 mb-1">Inventario</p>
                 <p className="text-xl font-black">{products.reduce((a,b) => a + b.stock, 0)}</p>
              </div>
              <div className="bg-white/5 p-4 rounded-3xl border border-white/5">
                 <p className="text-[10px] font-black uppercase opacity-40 mb-1">Pedidos</p>
                 <p className="text-xl font-black">{orders.length}</p>
              </div>
              <div className="bg-white/5 p-4 rounded-3xl border border-white/5">
                 <p className="text-[10px] font-black uppercase opacity-40 mb-1">Clientes</p>
                 <p className="text-xl font-black">{customers.length}</p>
              </div>
           </div>
        </div>

        {/* Console Log */}
        <div className="bg-black/40 rounded-2xl p-4 font-mono text-[9px] h-32 overflow-hidden border border-white/5 relative">
          <div className="flex justify-between items-center mb-2 opacity-50 sticky top-0">
            <span>ACTIVITY LOG</span>
            <i className="fas fa-terminal"></i>
          </div>
          <div className="space-y-1">
            {logs.length === 0 && <span className="opacity-30">Esperando acción...</span>}
            {logs.map((log, i) => (
              <div key={i} className="opacity-80 border-l-2 border-indigo-500 pl-2">{log}</div>
            ))}
          </div>
        </div>

      </div>
    </div>
  );
};

