        3: { fontStyle: 'bold' }
      },
      didParseCell: (data: any) => {
        if (data.section === 'body' && data.column.index === 3) {
          if (data.cell.raw === 'PENDIENTE') {
            data.cell.styles.textColor = [220, 38, 38]; // Red
          } else {
            data.cell.styles.textColor = [22, 163, 74]; // Green
          }
        }
      }
    });

    yPos = (doc as any).lastAutoTable.finalY + 15;
  });

  // --- FOOTER ---
  const pageCount = (doc as any).internal.getNumberOfPages();
  for(let i = 1; i <= pageCount; i++) {
    doc.setPage(i);
    doc.setFontSize(8);
    doc.setTextColor(150);
    doc.text(`Aqua+ ERP - Reporte Operativo - Página ${i} de ${pageCount}`, pageWidth / 2, doc.internal.pageSize.height - 10, { align: 'center' });
  }

  return doc.output('datauristring');
};

/**
 * Generates a Ticket PDF using pdf-lib and returns raw bytes
 */
export const generateTicketPDF = async (sale: Sale, config: TicketConfig): Promise<Uint8Array> => {
  // Crear nuevo documento PDF
  const pdfDoc = await PDFDocument.create();

  const accent = hexToRgbScale(config.colorHex || '#000000');
  const accentColor = rgb(accent.r, accent.g, accent.b);

  // Calcular altura dinámica base
  const itemsHeight = sale.items.length * 25; 
  const qrSpace = 120;
  const baseHeight = 400; // Increased base height for extra fields
  const ticketHeight = baseHeight + itemsHeight + qrSpace;
  const ticketWidth = 280; 

  const page = pdfDoc.addPage([ticketWidth, ticketHeight]);

  // Obtener fuentes
  const fontRegular = await pdfDoc.embedFont(StandardFonts.Helvetica);
  const fontBold = await pdfDoc.embedFont(StandardFonts.HelveticaBold);
  const fontCourier = await pdfDoc.embedFont(StandardFonts.Courier);

  const { width, height } = page.getSize();
  let yPos = height - 20;

  const centerX = width / 2;
  const margin = 15;
  const contentWidth = width - (margin * 2);

  // --- HELPERS ---
  const sanitize = (text: string) => {
    if (!text) return '';
    return text
      .replace(/★/g, '*')
      .replace(/☆/g, '*')
      .replace(/●/g, '-')
      .replace(/•/g, '-');
  };

  const drawCenteredText = (text: string, font: PDFFont, size: number, color = rgb(0,0,0)) => {
    const safeText = sanitize(text);
    const textWidth = font.widthOfTextAtSize(safeText, size);
    page.drawText(safeText, { x: centerX - (textWidth / 2), y: yPos, size, font, color });
    yPos -= (size + 4);
  };

  const drawLeftRight = (left: string, right: string, font: PDFFont, size: number, isBold = false) => {
    const safeLeft = sanitize(left);
    const safeRight = sanitize(right);
    const rightWidth = font.widthOfTextAtSize(safeRight, size);
    page.drawText(safeLeft, { x: margin, y: yPos, size, font });
    page.drawText(safeRight, { x: width - margin - rightWidth, y: yPos, size, font: isBold ? fontBold : font });
    yPos -= (size + 6);
  };

  const drawDashedLine = () => {
    const dash = '- - - - - - - - - - - - - - - - - - - - - - - - - - - -';
    const textWidth = fontCourier.widthOfTextAtSize(dash, 10);
    page.drawText(dash, { x: centerX - (textWidth / 2), y: yPos, size: 10, font: fontCourier, color: rgb(0.5, 0.5, 0.5) });
    yPos -= 12;
  };

  // --- LOGO ---
  if (config.logoUrl && config.logoUrl.startsWith('data:image')) {
    try {
      // FIX: pdf-lib DOES NOT support SVG. Must skip if SVG or error will occur.
      if (config.logoUrl.includes('image/svg+xml')) {
         console.warn("SVG logos cannot be embedded in PDF-Lib directly. Skipping logo.");
         // Optionally draw placeholder
         yPos -= 10;
      } else {
          const base64Data = config.logoUrl.split(',')[1];
          const imageBytes = Uint8Array.from(atob(base64Data), c => c.charCodeAt(0));

          let logoImage;
          if (config.logoUrl.includes('image/png')) {
            logoImage = await pdfDoc.embedPng(imageBytes);
          } else if (config.logoUrl.includes('image/jpeg') || config.logoUrl.includes('image/jpg')) {
            logoImage = await pdfDoc.embedJpg(imageBytes);
          }

          if (logoImage) {
              const logoDims = logoImage.scale(1);
              const maxLogoWidth = 80;
              const scaleFactor = maxLogoWidth / logoDims.width;
              const scaledWidth = logoDims.width * scaleFactor;
              const scaledHeight = logoDims.height * scaleFactor;

              page.drawImage(logoImage, {
                x: centerX - (scaledWidth / 2),
                y: yPos - scaledHeight,
                width: scaledWidth,
                height: scaledHeight,
              });
              yPos -= (scaledHeight + 10);
          } else {
              yPos -= 10;
          }
      }
    } catch (e) {
      console.warn("Error embedding logo", e);
      yPos -= 10;
    }
  } else {
    yPos -= 10;
  }

  // --- HEADER ---
  drawCenteredText(config.businessName, fontBold, 16, accentColor);
  if (config.slogan) drawCenteredText(`"${config.slogan}"`, fontRegular, 9, rgb(0.4, 0.4, 0.4));

  yPos -= 5;
  drawCenteredText(config.address, fontRegular, 9);
  drawCenteredText(`Tel: ${config.phone}`, fontRegular, 9);
  if (config.email) drawCenteredText(config.email, fontRegular, 8);
  if (config.website) drawCenteredText(config.website, fontRegular, 8);
  if (config.rfc) drawCenteredText(`RFC: ${config.rfc}`, fontRegular, 9);

  yPos -= 5;
  drawDashedLine();

  // --- META INFO ---
  drawLeftRight('Folio:', sale.id, fontRegular, 10, true);
  drawLeftRight('Fecha:', new Date(sale.timestamp).toLocaleDateString(), fontRegular, 10);
  drawLeftRight('Hora:', new Date(sale.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}), fontRegular, 10);
  drawLeftRight('Cliente:', sale.customerAlias.substring(0, 18), fontRegular, 10, true);

  yPos -= 5;

  // --- TABLE HEADER ---
  page.drawRectangle({
    x: margin,
    y: yPos - 2,
    width: contentWidth,
    height: 14,
    color: accentColor, 
    opacity: 0.1
  });

  page.drawText('CANT', { x: margin + 5, y: yPos, size: 8, font: fontBold, color: accentColor });
  page.drawText('DESCRIPCION', { x: margin + 45, y: yPos, size: 8, font: fontBold, color: accentColor });
  const impHeaderWidth = fontBold.widthOfTextAtSize('IMPORTE', 8);
  page.drawText('IMPORTE', { x: width - margin - impHeaderWidth - 5, y: yPos, size: 8, font: fontBold, color: accentColor });
  yPos -= 18;

  // --- ITEMS ---
  sale.items.forEach(item => {
    // Cantidad
    page.drawText(item.quantity.toString(), { x: margin + 8, y: yPos, size: 10, font: fontBold });

    // Descripción
    const cleanName = sanitize(item.name);
    const name = cleanName.length > 20 ? cleanName.substring(0, 20) + '...' : cleanName;
    page.drawText(name, { x: margin + 45, y: yPos, size: 9, font: fontRegular });

    // Importe
    const totalItem = (item.quantity * item.price).toFixed(2);
    const totalItemWidth = fontRegular.widthOfTextAtSize(`$${totalItem}`, 10);
    page.drawText(`$${totalItem}`, { x: width - margin - totalItemWidth, y: yPos, size: 10, font: fontRegular });

    yPos -= 15;
  });

  drawDashedLine();

  // --- TOTALS ---
  const drawTotalLine = (label: string, value: string, isBig = false) => {
    const safeLabel = sanitize(label);
    const safeValue = sanitize(value);

    const size = isBig ? 16 : 10;
    const font = isBig ? fontBold : fontRegular;
    const color = isBig ? accentColor : rgb(0,0,0);

    const labelWidth = font.widthOfTextAtSize(safeLabel, size);
    const valueWidth = font.widthOfTextAtSize(safeValue, size);

    const valueX = width - margin - valueWidth;
    const labelX = valueX - labelWidth - 10;

    page.drawText(safeLabel, { x: labelX, y: yPos, size, font, color });
    page.drawText(safeValue, { x: valueX, y: yPos, size, font, color });
    yPos -= (size + 8);
  };

  drawTotalLine('TOTAL:', `$${sale.total.toFixed(2)}`, true);

  if (sale.paymentSplits && sale.paymentSplits.length > 0) {
     sale.paymentSplits.forEach(split => {
        drawTotalLine(`${split.method}:`, `$${split.amount.toFixed(2)}`);
     });
  } else {
     drawTotalLine('Su Pago:', `$${sale.paidAmount.toFixed(2)}`);
  }

  if (sale.change > 0) {
    drawTotalLine('Cambio:', `$${sale.change.toFixed(2)}`);
  } else if (sale.paidAmount < sale.total) {
    // Background for Debt warning
    page.drawRectangle({
        x: margin,
        y: yPos - 8,
        width: contentWidth,
        height: 20,
        color: accentColor,
    });

    page.drawText('SALDO PENDIENTE', { x: margin + 5, y: yPos + 2, size: 10, font: fontBold, color: rgb(1,1,1) });
    const debtStr = `$${(sale.total - sale.paidAmount).toFixed(2)}`;
    const debtW = fontBold.widthOfTextAtSize(debtStr, 10);
    page.drawText(debtStr, { x: width - margin - debtW - 5, y: yPos + 2, size: 10, font: fontBold, color: rgb(1,1,1) });
    yPos -= 25;
  }

  // --- GARRAFONES RETURNED ---
  if (sale.emptyGarrafonsReturned > 0) {
    yPos -= 5;
    page.drawRectangle({
      x: margin + 20,
      y: yPos - 5,
      width: contentWidth - 40,
      height: 25,
      borderColor: accentColor,
      borderWidth: 1,
    });
    const text = `* ${sale.emptyGarrafonsReturned} Envases Recibidos *`;
    const textW = fontBold.widthOfTextAtSize(text, 10);
    page.drawText(text, { x: centerX - (textW/2), y: yPos + 5, size: 10, font: fontBold, color: accentColor });
    yPos -= 25;
  }

  // --- FOOTER & QR CODE ---
  yPos -= 10;
  if (config.footerMessage) {
    const words = sanitize(config.footerMessage).split(' ');
    let line = '';
    for (const word of words) {
        const testLine = line + word + ' ';
        const testWidth = fontRegular.widthOfTextAtSize(testLine, 9);
        if (testWidth > contentWidth) {
            drawCenteredText(line, fontRegular, 9);
            line = word + ' ';
        } else {
            line = testLine;
        }
    }
    drawCenteredText(line, fontRegular, 9);
  }

  if (config.extraNote) {
    drawCenteredText(sanitize(config.extraNote), fontRegular, 8, rgb(0.5, 0.5, 0.5));
  }

  drawCenteredText('*** GRACIAS POR SU PREFERENCIA ***', fontBold, 9);

  // QR Code at the bottom
  yPos -= 10;
  try {
    const qrData = btoa(`AQUA-PRO-SECURE|${JSON.stringify({ id: sale.id, total: sale.total })}`);
    const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(qrData)}`;

    // Fetch image data
    const qrResponse = await fetch(qrUrl);
    const qrArrayBuffer = await qrResponse.arrayBuffer();
    const qrImage = await pdfDoc.embedPng(qrArrayBuffer);

    const qrSize = 100;

    page.drawImage(qrImage, {
        x: centerX - (qrSize / 2),
        y: yPos - qrSize,
        width: qrSize,
        height: qrSize
    });
  } catch (e) {
    console.warn("Could not embed QR code in PDF", e);
    // Draw placeholder
    yPos -= 20;
    drawCenteredText('[ CODIGO QR NO DISPONIBLE ]', fontCourier, 8);
  }

  return await pdfDoc.save();
}

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { Product, Customer, Sale, CartItem, Order, Employee, Vehicle, PaymentSplit, ViewType, QualityRecord, Task, Attendance, TicketConfig, CloudConfig, SavedReport, FuelRecord, Message, Role } from '../types';
import { INITIAL_PRODUCTS, INITIAL_CUSTOMERS } from '../constants';

const DEFAULT_PERMISSIONS: ViewType[] = ['dashboard', 'pos', 'orders', 'customers', 'logistics', 'inventory', 'whatsapp', 'production', 'sync', 'reports', 'settings', 'employees', 'quality', 'scanner', 'tickets', 'messages'];

// Updated to use a blank PNG placeholder instead of SVG to be safe for PDF-LIB
const INITIAL_TICKET_CONFIG: TicketConfig = {
  businessName: 'AQUA+ FUNDADORES',
  rfc: 'AQUA900101-XXX',
  address: 'Calle del Agua #123, Col. Manantiales',
  phone: '33-1234-5678',
  footerMessage: '¡Gracias por tu preferencia! Frescura que hidrata tu vida.',
  website: 'www.aquafun.mx',
  socialMedia: '@aquafun_pro',
  extraNote: 'No hay cambios después de 24 horas.',
  // Use a 1x1 transparent PNG or valid PNG base64 to avoid crashes in PDF generator which doesn't support SVG
  logoUrl: 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=', 
  colorHex: '#0284c7', // Sky-600 default
  email: 'contacto@aquafun.mx'
};

const INITIAL_CLOUD_CONFIG: CloudConfig = {
  url: 'https://aquamasfundadores-default-rtdb.firebaseio.com/',
  apiKey: 't8rzxkeWbMIKGufdW7RV1j1bKS0TKf2gPkgmZ36A',
  autoSync: true
};

// --- DEVICE ID MANAGEMENT ---
const getDeviceId = () => {
  let id = localStorage.getItem('aqua_device_id');
  if (!id) {
    // Generar un ID corto único (ej: 4A2B)
    id = Math.random().toString(36).substring(2, 6).toUpperCase();
    localStorage.setItem('aqua_device_id', id);
  }
  return id;
};

// Hook Logic Factory
const useERPFactory = () => {
  const [deviceId] = useState(getDeviceId());

  const [products, setProducts] = useState<Product[]>(() => {
    const saved = localStorage.getItem('aqua_products');
    return saved ? JSON.parse(saved) : INITIAL_PRODUCTS;
  });

  const [customers, setCustomers] = useState<Customer[]>(() => {
    const saved = localStorage.getItem('aqua_customers');
    return saved ? JSON.parse(saved).map((c: any) => ({ ...c, balance: c.balance || 0 })) : INITIAL_CUSTOMERS;
  });

  const [ticketConfig, setTicketConfig] = useState<TicketConfig>(() => {
    const saved = localStorage.getItem('aqua_ticket_config');
    // Ensure colorHex exists for older saved configs
    const parsed = saved ? JSON.parse(saved) : INITIAL_TICKET_CONFIG;
    return { ...INITIAL_TICKET_CONFIG, ...parsed };
  });

  const [cloudConfig, setCloudConfig] = useState<CloudConfig>(() => {
    const saved = localStorage.getItem('aqua_cloud_config');
    if (saved) {
      const parsed = JSON.parse(saved);
      if (!parsed.url || parsed.url === '') {
        return INITIAL_CLOUD_CONFIG;
      }
      return parsed;
    }
    return INITIAL_CLOUD_CONFIG;
  });

  const [sales, setSales] = useState<Sale[]>(() => {
    const saved = localStorage.getItem('aqua_sales');
    return saved ? JSON.parse(saved) : [];
  });

  const [orders, setOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('aqua_orders');
    return saved ? JSON.parse(saved) : [];
  });

  const [employees, setEmployees] = useState<Employee[]>(() => {
    const saved = localStorage.getItem('aqua_employees');
    let initial = saved ? JSON.parse(saved) : [
      { id: 'admin', name: 'Gerente General', roles: ['Administrador'], phone: '3312345678', pin: '1234', permissions: [...DEFAULT_PERMISSIONS] }
    ];

    // MIGRATION: Convert single role string to roles array if needed
    initial = initial.map((e: any) => {
      if (e.role && !e.roles) {
        return { ...e, roles: [e.role], role: undefined };
      }
      return e;
    });

    return initial;
  });

  // Ensure Admins always have full permissions on load
  useEffect(() => {
    setEmployees(prev => prev.map(e => 
      e.roles.includes('Administrador')
        ? { ...e, permissions: [...DEFAULT_PERMISSIONS] } 
        : e
    ));
  }, []);

  const [vehicles, setVehicles] = useState<Vehicle[]>(() => {
    const saved = localStorage.getItem('aqua_vehicles');
    // Migration: ensure inventory and fuelHistory arrays exist
    const parsed = saved ? JSON.parse(saved) : [{ id: 'v1', plate: 'ABC-123', description: 'Nissan NP300', loadCapacity: 60, currentLoad: 0, inventory: [], fuelHistory: [] }];
    return parsed.map((v: any) => ({
        ...v,
        inventory: v.inventory || [],
        fuelHistory: v.fuelHistory || []
    }));
  });

  const [qualityRecords, setQualityRecords] = useState<QualityRecord[]>(() => {
    const saved = localStorage.getItem('aqua_quality');
    return saved ? JSON.parse(saved) : [];
  });

  const [tasks, setTasks] = useState<Task[]>(() => {
    const saved = localStorage.getItem('aqua_tasks');
    return saved ? JSON.parse(saved) : [];
  });

  const [attendance, setAttendance] = useState<Attendance[]>(() => {
    const saved = localStorage.getItem('aqua_attendance');
    return saved ? JSON.parse(saved) : [];
  });

  const [savedReports, setSavedReports] = useState<SavedReport[]>(() => {
    const saved = localStorage.getItem('aqua_saved_reports');
    return saved ? JSON.parse(saved) : [];
  });

  const [messages, setMessages] = useState<Message[]>(() => {
    const saved = localStorage.getItem('aqua_messages');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => {
    localStorage.setItem('aqua_products', JSON.stringify(products));
    localStorage.setItem('aqua_customers', JSON.stringify(customers));
    localStorage.setItem('aqua_sales', JSON.stringify(sales));
    localStorage.setItem('aqua_orders', JSON.stringify(orders));
    localStorage.setItem('aqua_employees', JSON.stringify(employees));
    localStorage.setItem('aqua_vehicles', JSON.stringify(vehicles));
    localStorage.setItem('aqua_ticket_config', JSON.stringify(ticketConfig));
    localStorage.setItem('aqua_quality', JSON.stringify(qualityRecords));
    localStorage.setItem('aqua_tasks', JSON.stringify(tasks));
    localStorage.setItem('aqua_attendance', JSON.stringify(attendance));
    localStorage.setItem('aqua_cloud_config', JSON.stringify(cloudConfig));
    localStorage.setItem('aqua_saved_reports', JSON.stringify(savedReports));
    localStorage.setItem('aqua_messages', JSON.stringify(messages));
  }, [products, customers, sales, orders, employees, vehicles, ticketConfig, qualityRecords, tasks, attendance, cloudConfig, savedReports, messages]);

  // Helper para fecha local ISO YYYY-MM-DD
  const getLocalDateISO = () => {
    const d = new Date();
    const offset = d.getTimezoneOffset() * 60000;
    return new Date(d.getTime() - offset).toISOString().split('T')[0];
  };

  const addSale = (
    customerId: string, 
    items: CartItem[], 
    total: number, 
    paidAmount: number, 
    splits: PaymentSplit[], 
    returnedVacios: number, 
    manualTimestamp?: number,
    vehicleId?: string // New optional parameter
  ) => {
    const debtAmount = Math.max(0, total - paidAmount);

    // Calculate Asset Movement (Jugs)
    const jugsSold = items
      .filter(i => i.category === 'Agua' || i.name.toLowerCase().includes('garraf'))
      .reduce((acc, item) => acc + item.quantity, 0);

    const netJugChange = jugsSold - returnedVacios;

    // ID GENERATION: Includes Device ID to prevent collisions during sync
    const timestamp = manualTimestamp || Date.now();
    const uniqueId = `TKT-${timestamp.toString().slice(-6)}-${deviceId}`;

    const newSale: Sale = {
      id: uniqueId,
      timestamp: timestamp,
      customerId,
      customerAlias: customers.find(c => c.id === customerId)?.alias || 'Anonimo',
      items,
      total,
      paidAmount,
      change: Math.max(0, paidAmount - total),
      paymentSplits: splits,
      emptyGarrafonsReturned: returnedVacios,
      synced: false,
      deviceId: deviceId // Metadata for traceability
    };

    setSales(prev => [newSale, ...prev]);

    // Update Customer Balance and Jug Inventory with LAST UPDATED
    setCustomers(prev => prev.map(c => {
      if (c.id === customerId) {
        return { 
          ...c, 
          balance: (c.balance || 0) + debtAmount,
          jugsOnLoan: Math.max(0, (c.jugsOnLoan || 0) + netJugChange),
          lastUpdated: Date.now() // Track change
        };
      }
      return c;
    }));

    // Logic to deduct inventory
    if (vehicleId && vehicleId !== 'plant') {
      // Deduct from specific vehicle
      setVehicles(prev => prev.map(v => {
        if (v.id !== vehicleId) return v;

        let currentInventory = [...(v.inventory || [])];

        items.forEach(soldItem => {
          const idx = currentInventory.findIndex(inv => inv.id === soldItem.id);
          if (idx !== -1) {
            // Reduce quantity
            const newQty = Math.max(0, currentInventory[idx].quantity - soldItem.quantity);
            if (newQty === 0) {
               currentInventory.splice(idx, 1);
            } else {
               currentInventory[idx] = { ...currentInventory[idx], quantity: newQty };
            }
          }
        });

        const newLoad = currentInventory.reduce((acc, i) => acc + (i.quantity || 0), 0);
        return { ...v, inventory: currentInventory, currentLoad: newLoad, lastUpdated: Date.now() };
      }));
    } else {
      // Deduct from Plant (Default)
      setProducts(prev => prev.map(p => {
        const cartItem = items.find(item => item.id === p.id);
        return cartItem ? { ...p, stock: p.stock - cartItem.quantity, lastUpdated: Date.now() } : p;
      }));
    }

    return newSale;
  };

  const resetSales = () => {
    setSales([]);
    alert("Todas las ventas han sido eliminadas. El historial está limpio.");
  };

  // --- MEGA SYNC FUNCTION ---
  // Accepts a partial State object and merges it.
  // Note: Most merge logic is now handled in SyncModule's smartMerge before calling this,
  // but we keep basic safety checks here.
  const syncData = useCallback((externalData: any) => {
    if (!externalData) return false;
    let changesMade = false;

    // Helper to just set the data (assuming SyncModule did the heavy lifting/merging)
    const setIfPresent = <T,>(key: string, setter: React.Dispatch<React.SetStateAction<T>>) => {
        if (externalData[key]) {
            setter(externalData[key]);
            changesMade = true;
        }
    };

    setIfPresent('sales', setSales);
    setIfPresent('customers', setCustomers);
    setIfPresent('products', setProducts);
    setIfPresent('orders', setOrders);
    setIfPresent('vehicles', setVehicles);
    setIfPresent('employees', setEmployees);
    setIfPresent('qualityRecords', setQualityRecords);
    setIfPresent('tasks', setTasks);
    setIfPresent('attendance', setAttendance);
    setIfPresent('savedReports', setSavedReports);
    setIfPresent('messages', setMessages);

    // Ticket Config (Object merge)
    if (externalData.ticketConfig) {
      if (JSON.stringify(ticketConfig) !== JSON.stringify(externalData.ticketConfig)) {
        setTicketConfig(externalData.ticketConfig);
        changesMade = true;
      }
    }

    return changesMade;
  }, [ticketConfig]);

  const importCustomers = useCallback((newCustomers: Customer[]) => {
    setCustomers(prev => {
      const existingIds = new Set(prev.map(c => c.id));
      const filteredNew = newCustomers.filter(c => !existingIds.has(c.id));
      // Mark imported as updated now
      const withTimestamp = filteredNew.map(c => ({...c, lastUpdated: Date.now()}));
      return [...prev, ...withTimestamp];
    });
  }, []);

  const loadVehicle = (vehicleId: string, product: Product, delta: number) => {
    if (!product || !product.id) return;

    if (delta > 0) {
      const currentProduct = products.find(p => p.id === product.id);
      if (!currentProduct) return;
      if (currentProduct.stock < delta) {
          alert("Stock insuficiente en planta.");
          return;
      }
    }

    setVehicles(prev => prev.map(v => {
        if (v.id !== vehicleId) return v;

        const newInventory = Array.isArray(v.inventory) ? [...v.inventory] : [];
        const existingItemIndex = newInventory.findIndex(i => i.id === product.id);

        if (existingItemIndex > -1) {
            const newQty = newInventory[existingItemIndex].quantity + delta;
            if (newQty <= 0) {
                newInventory.splice(existingItemIndex, 1);
            } else {
                newInventory[existingItemIndex] = { ...newInventory[existingItemIndex], quantity: newQty };
            }
        } else if (delta > 0) {
            newInventory.push({ ...product, quantity: delta });
        }

        const newLoad = newInventory.reduce((acc, item) => acc + (item.quantity || 0), 0);

        return { ...v, inventory: newInventory, currentLoad: newLoad, lastUpdated: Date.now() };
    }));

    setProducts(prev => prev.map(p => {
        if (p.id === product.id) {
            return { ...p, stock: p.stock - delta, lastUpdated: Date.now() };
        }
        return p;
    }));
  };

  const addFuelRecord = (vehicleId: string, record: FuelRecord) => {
    setVehicles(prev => prev.map(v => {
      if (v.id !== vehicleId) return v;
      return { 
        ...v, 
        fuelHistory: [record, ...(v.fuelHistory || [])],
        lastUpdated: Date.now()
      };
    }));
  };

  const sendMessage = (text: string, senderId: string, receiverId: string) => {
    const newMessage: Message = {
      id: `MSG-${Date.now()}`,
      text,
      senderId,
      receiverId,
      timestamp: Date.now(),
      read: false
    };

    setMessages(prev => {
        const updatedMessages = [...prev, newMessage];
        if (cloudConfig.url && cloudConfig.autoSync) {
            const endpoint = `${cloudConfig.url}messages.json${cloudConfig.apiKey ? `?auth=${cloudConfig.apiKey}` : ''}`;
            fetch(endpoint, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(updatedMessages)
            }).catch(err => console.error("Error pushing message to cloud:", err));
        }
        return updatedMessages;
    });
  };

  return { 
    deviceId, // Expose Device ID
    products, 
    saveProduct: (p: Product) => setProducts(prev => prev.find(x => x.id === p.id) ? prev.map(x => x.id === p.id ? { ...p, lastUpdated: Date.now() } : x) : [...prev, { ...p, lastUpdated: Date.now() }]),
    deleteProduct: (id: string) => setProducts(prev => prev.filter(p => p.id !== id)),
    customers, 
    saveCustomer: (c: Customer) => setCustomers(prev => prev.find(x => x.id === c.id) ? prev.map(x => x.id === c.id ? { ...c, lastUpdated: Date.now() } : x) : [...prev, { ...c, lastUpdated: Date.now() }]),
    deleteCustomer: (id: string) => setCustomers(prev => prev.filter(c => c.id !== id)),
    importCustomers,
    sales, addSale, resetSales,
    orders, 
    setOrders,
    addOrder: (o: Partial<Order>) => {
      const newOrder: Order = {
        id: `ORD-${Date.now().toString().slice(-6)}-${deviceId}`,
        timestamp: Date.now(),
        status: 'pendiente',
        priority: 1,
        items: [],
        total: 0,
        customerId: '',
        customerAlias: '',
        deviceId: deviceId,
        lastUpdated: Date.now(), // Track creation
        ...o
      } as Order;
      setOrders(prev => [newOrder, ...prev]);
    },
    updateOrder: (o: Order) => setOrders(prev => prev.map(item => item.id === o.id ? { ...o, lastUpdated: Date.now() } : item)),
    employees, 
    saveEmployee: (e: Employee) => setEmployees(prev => prev.find(x => x.id === e.id) ? prev.map(x => x.id === e.id ? { ...e, lastUpdated: Date.now() } : x) : [...prev, { ...e, lastUpdated: Date.now() }]),
    vehicles, 
    setVehicles,
    loadVehicle,
    deleteVehicle: (id: string) => setVehicles(prev => prev.filter(v => v.id !== id)),
    addFuelRecord,
    tasks,
    addTask: (t: Partial<Task>) => {
      const newTask: Task = {
        id: `TSK-${Date.now().toString().slice(-4)}-${deviceId}`,
        timestamp: Date.now(),
        status: 'pendiente',
        deviceId: deviceId,
        lastUpdated: Date.now(),
        ...t
      } as Task;
      setTasks(prev => [newTask, ...prev]);
    },
    updateTaskStatus: (id: string, status: Task['status']) => setTasks(prev => prev.map(t => t.id === id ? { ...t, status, lastUpdated: Date.now() } : t)),
    deleteTask: (id: string) => setTasks(prev => prev.filter(t => t.id !== id)),
    clearTasksByDate: (date: string) => setTasks(prev => prev.filter(t => t.date !== date)),
    attendance,
    recordAttendance: (employeeId: string, status: Attendance['status']) => {
      const date = getLocalDateISO();
      setAttendance(prev => {
        const filtered = prev.filter(a => !(a.employeeId === employeeId && a.date === date));
        return [{ id: `ATT-${Date.now()}`, employeeId, status, date, timestamp: Date.now() }, ...filtered];
      });
    },
    qualityRecords,
    addQualityRecord: (r: Partial<QualityRecord>) => {
      const newRecord: QualityRecord = {
        id: `QUAL-${Date.now().toString().slice(-4)}`,
        timestamp: Date.now(),
        employeeId: 'admin',
        ...r
      } as QualityRecord;
      setQualityRecords(prev => [newRecord, ...prev]);
    },
    ticketConfig, setTicketConfig,
    cloudConfig, setCloudConfig,
    syncData,
    savedReports,
    addSavedReport: (r: SavedReport) => setSavedReports(prev => [r, ...prev]),
    deleteSavedReport: (id: string) => setSavedReports(prev => prev.filter(r => r.id !== id)),
    messages,
    sendMessage,
  };
};

// Create Context
const ERPContext = createContext<ReturnType<typeof useERPFactory> | null>(null);

// Provider Component
export const ERPProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const data = useERPFactory();
  return <ERPContext.Provider value={data}>{children}</ERPContext.Provider>;
};

// Accessor Hook (to be re-exported)
export const useERPDataHook = () => {
  const context = useContext(ERPContext);
  if (!context) throw new Error("useERPData must be used within ERPProvider");
  return context;
};

import React, { useState, useEffect, useRef } from 'react';
import { ModuleHeader, RoundedCard } from './ui/Cards';
import jsQR from 'jsqr';

interface ScannerModuleProps {
  onBack: () => void;
  onScanSuccess?: (data: string, type: 'TICKET' | 'SYNC') => void;
  mode?: 'TICKET' | 'P2P';
}

export const ScannerModule: React.FC<ScannerModuleProps> = ({ onBack, onScanSuccess, mode = 'TICKET' }) => {
  const [scanning, setScanning] = useState(true);
  const [result, setResult] = useState<any>(null);
  const [cameraError, setCameraError] = useState<string | null>(null);
  const [debugInfo, setDebugInfo] = useState<string>('');

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationRef = useRef<number>(0);
  const streamRef = useRef<MediaStream | null>(null);

  // Limpieza agresiva de streams previos
  const cleanupMedia = () => {
    if (animationRef.current) cancelAnimationFrame(animationRef.current);

    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => {
        track.stop();
        // Asegurar que el estado enabled también se apague
        track.enabled = false; 
      });
      streamRef.current = null;
    }

    if (videoRef.current) {
      videoRef.current.srcObject = null;
      videoRef.current.load();
    }
  };

  // Iniciar Cámara
  useEffect(() => {
    if (!scanning) {
      cleanupMedia();
      return;
    }

    const startCamera = async () => {
      cleanupMedia(); // Ensure clean slate
      setCameraError(null);
      setDebugInfo('Iniciando cámara...');

      try {
        if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
          throw new Error("API de cámara no soportada en este dispositivo.");
        }

        // Estrategia 1: Buscar ID de cámara trasera explícitamente
        let backCameraId = null;
        try {
          const devices = await navigator.mediaDevices.enumerateDevices();
          const videoDevices = devices.filter(d => d.kind === 'videoinput');
          const backDevice = videoDevices.find(d => 
            d.label.toLowerCase().includes('back') || 
            d.label.toLowerCase().includes('trasera') || 
            d.label.toLowerCase().includes('environment')
          );
          if (backDevice) backCameraId = backDevice.deviceId;
          if (!backCameraId && videoDevices.length === 1) backCameraId = videoDevices[0].deviceId;
        } catch (e) {
          console.warn("Error enumerando dispositivos:", e);
        }

        const tryStream = async (constraints: MediaStreamConstraints) => {
          try {
            return await navigator.mediaDevices.getUserMedia(constraints);
          } catch (err: any) {
            console.warn(`Intento fallido: ${JSON.stringify(constraints)}`, err);
            return null;
          }
        };

        let stream: MediaStream | null = null;

        if (backCameraId) {
          stream = await tryStream({ 
            video: { 
              deviceId: { exact: backCameraId },
              width: { ideal: 1280 },
              height: { ideal: 720 }
            } 
          });
        }

        if (!stream) {
          stream = await tryStream({ 
            video: { facingMode: "environment", width: { ideal: 640 } } 
          });
        }

        if (!stream) {
          stream = await tryStream({ video: true });
        }

        if (stream) {
          streamRef.current = stream;
          if (videoRef.current) {
            videoRef.current.srcObject = stream;
            videoRef.current.setAttribute("playsinline", "true");

            await videoRef.current.play().catch(error => {
                console.error("Error al reproducir video:", error);
                setCameraError("generic");
                setDebugInfo(`Play error: ${error.message}`);
            });

            requestAnimationFrame(tick);
            setDebugInfo('');
          }
        } else {
          throw new Error("No se pudo obtener ningún stream de video.");
        }

      } catch (err: any) {
        console.error("Camera Fatal Error:", err);
        if (err.name === 'NotAllowedError' || err.name === 'PermissionDeniedError') {
          setCameraError("permiso");
        } else if (err.name === 'NotFoundError') {
          setCameraError("no_device");
        } else if (err.name === 'NotReadableError') {
          setCameraError("generic");
          setDebugInfo("Hardware ocupado. Reinicia la app.");
        } else {
          setCameraError("generic");
          setDebugInfo(`${err.name}: ${err.message}`);
        }
      }
    };

    const timer = setTimeout(startCamera, 300);
    return () => {
      clearTimeout(timer);
      cleanupMedia();
    };
  }, [scanning]);

  // Ensure cleanup on unmount
  useEffect(() => {
      return () => cleanupMedia();
  }, []);

  const tick = () => {
    if (!videoRef.current || !canvasRef.current || !scanning) return;

    if (videoRef.current.readyState === videoRef.current.HAVE_ENOUGH_DATA) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      const ctx = canvas.getContext('2d');

      if (ctx) {
        canvas.height = video.videoHeight;
        canvas.width = video.videoWidth;
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);

        try {
          const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
          const code = jsQR(imageData.data, imageData.width, imageData.height, {
            inversionAttempts: "dontInvert",
          });

          if (code && code.data) {
            handleScan(code.data);
            return; 
          }
        } catch (e) {
          // Ignore decoding errors per frame
        }
      }
    }
    animationRef.current = requestAnimationFrame(tick);
  };

  const decryptData = (encrypted: string) => {
    try {
      const decoded = atob(encrypted);
      if (decoded.startsWith('AQUA-PRO-SECURE|')) {
        return { type: 'TICKET', data: JSON.parse(decoded.split('|')[1]) };
      }
      return null;
    } catch {
      if (mode === 'P2P' && (encrypted.length > 5 || encrypted.startsWith('AQUA-'))) {
         return { type: 'SYNC', data: encrypted };
      }
      return null;
    }
  };

  const handleScan = (code: string) => {
    if (!scanning) return;

    if (navigator.vibrate) navigator.vibrate(200);

    if (mode === 'P2P') {
      cleanupMedia();
      if (onScanSuccess) onScanSuccess(code, 'SYNC');
      return;
    }

    const decoded = decryptData(code);
    if (decoded?.type === 'TICKET') {
      cleanupMedia();
      if (onScanSuccess && mode === 'TICKET') {
        onScanSuccess(code, 'TICKET');
      } else {
        setResult(decoded.data);
        setScanning(false);
      }
    }
  };

  const handleManualEntry = (code: string) => {
    handleScan(code);
  };

  return (
    <div className={`h-full flex flex-col animate-fadeIn overflow-hidden ${mode === 'P2P' ? 'bg-slate-800' : 'bg-sky-900'}`}>
      <div className="px-6 pt-8 pb-4 flex items-center gap-4 relative z-20">
        <button onClick={onBack} className="w-12 h-12 bg-white/10 text-white rounded-2xl flex items-center justify-center active:scale-90 transition-transform">
          <i className="fas fa-arrow-left"></i>
        </button>
        <h2 className="text-2xl font-black tracking-tight text-white">
          {mode === 'P2P' ? 'Conectar' : 'Validar Ticket'}
        </h2>
      </div>

      <div className="flex-1 flex flex-col items-center justify-center px-6 relative">
        {scanning ? (
          <div className="w-full h-full flex flex-col items-center justify-center">

            {cameraError ? (
               <div className="bg-white p-8 rounded-[2rem] max-w-sm text-center shadow-2xl animate-fadeIn z-30">
                  <div className="w-20 h-20 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4 text-red-500 text-3xl">
                     <i className="fas fa-video-slash"></i>
                  </div>
                  <h3 className="text-xl font-black text-sky-900 mb-2">Error de Cámara</h3>

                  {cameraError === 'permiso' ? (
                    <div className="text-sm text-sky-600 mb-6 text-left bg-sky-50 p-4 rounded-xl">
                       <p className="font-bold mb-2">Permisos Requeridos:</p>
                       <p className="text-xs">Ve a Ajustes {'>'} Apps {'>'} Aqua+ Pro {'>'} Permisos y activa la Cámara.</p>
                    </div>
                  ) : (
                    <div className="mb-6">
                      <p className="text-sm text-sky-500 mb-2 font-bold">No se pudo iniciar el video.</p>
                      <p className="text-[10px] bg-slate-100 p-2 rounded text-slate-500 font-mono break-all">{debugInfo}</p>
                    </div>
                  )}

                  <button onClick={() => { setCameraError(null); setScanning(true); window.location.reload(); }} className="w-full bg-sky-600 text-white py-4 rounded-xl font-black uppercase text-xs shadow-lg">Reiniciar App</button>
               </div>
            ) : (
               <div className="relative w-full max-w-xs aspect-square rounded-[2rem] overflow-hidden shadow-2xl bg-black border border-white/10">
                  <video ref={videoRef} className="absolute inset-0 w-full h-full object-cover opacity-90" muted playsInline></video>
                  <canvas ref={canvasRef} className="hidden"></canvas>

                  {/* Viewfinder Corners */}
                  <div className="absolute top-6 left-6 w-10 h-10 border-t-4 border-l-4 border-white/40 rounded-tl-2xl z-20 pointer-events-none"></div>
                  <div className="absolute top-6 right-6 w-10 h-10 border-t-4 border-r-4 border-white/40 rounded-tr-2xl z-20 pointer-events-none"></div>
                  <div className="absolute bottom-6 left-6 w-10 h-10 border-b-4 border-l-4 border-white/40 rounded-bl-2xl z-20 pointer-events-none"></div>
                  <div className="absolute bottom-6 right-6 w-10 h-10 border-b-4 border-r-4 border-white/40 rounded-br-2xl z-20 pointer-events-none"></div>

                  {/* Enhanced Scanner Animation */}
                  <div className="absolute inset-0 z-20 overflow-hidden pointer-events-none">
                    <div className={`w-full h-1/2 bg-gradient-to-b from-transparent ${mode === 'P2P' ? 'to-emerald-500/20' : 'to-sky-500/20'} absolute top-[-50%] left-0 animate-scan-trail`}></div>
                    <div className={`w-full h-0.5 ${mode === 'P2P' ? 'bg-emerald-400 shadow-[0_0_20px_rgba(52,211,153,0.8)]' : 'bg-sky-400 shadow-[0_0_20px_rgba(56,189,248,0.8)]'} absolute top-0 left-0 animate-scan-line`}></div>
                  </div>

                  <div className="absolute inset-0 flex items-center justify-center z-10 pointer-events-none">
                     <i className="fas fa-expand text-white/5 text-8xl"></i>
                  </div>

                  <div className="absolute bottom-8 left-0 right-0 text-center z-30 pointer-events-none">
                     <p className="text-white/90 text-[10px] font-bold uppercase tracking-[0.2em] bg-black/40 inline-block px-4 py-1.5 rounded-full backdrop-blur-md border border-white/10">
                        {mode === 'P2P' ? 'Sincronizando...' : 'Escaneando...'}
                     </p>
                  </div>

                  {/* Debug info */}
                  {debugInfo && <div className="absolute top-2 left-2 text-[8px] text-white/50 font-mono z-30">{debugInfo}</div>}
               </div>
            )}

            {!cameraError && (
              <div className="w-full max-w-xs mt-8">
                <input 
                  type="text" 
                  placeholder="Código Manual..." 
                  className="w-full border border-white/20 bg-white/10 text-white rounded-2xl p-5 text-sm outline-none focus:ring-2 ring-white/30 transition-all placeholder-white/40 font-bold text-center backdrop-blur-md"
                  onKeyDown={e => e.key === 'Enter' && handleManualEntry(e.currentTarget.value)}
                />
              </div>
            )}
          </div>
        ) : (
          <RoundedCard className="w-full bg-white animate-fadeIn p-8">
            <div className="flex flex-col items-center text-center">
              <div className="w-20 h-20 bg-emerald-100 text-emerald-500 rounded-full flex items-center justify-center mb-6">
                <i className="fas fa-check-circle text-4xl"></i>
              </div>
              <h3 className="text-2xl font-black text-sky-900 mb-2">Código Detectado</h3>
              <div className="w-full bg-sky-50 rounded-3xl p-6 mb-8 space-y-4">
                <div className="flex justify-between">
                  <span className="text-[10px] font-black text-sky-400 uppercase">ID</span>
                  <span className="text-xs font-black text-sky-900">{result?.id || 'N/A'}</span>
                </div>
                {result?.total && (
                  <div className="flex justify-between border-t border-sky-100 pt-3">
