        <section className="space-y-4">
          <div className="flex items-center gap-2 px-2">
            <i className="fas fa-gear text-sky-400 text-xs"></i>
            <h4 className="text-[10px] font-black uppercase text-sky-400 tracking-widest">Sistema</h4>
          </div>
          <RoundedCard>
            <div className="flex justify-between items-center mb-3">
               <span className="text-xs font-bold text-sky-600">Sincronización Nube</span>
               <div className="w-10 h-6 bg-sky-600 rounded-full relative"><div className="w-4 h-4 bg-white rounded-full absolute right-1 top-1"></div></div>
            </div>
            <p className="text-[10px] text-sky-300 italic leading-relaxed font-bold">Respaldo automático vía internet (Firebase).</p>
          </RoundedCard>
        </section>

        {currentUser.roles.includes('Administrador') && (
          <section className="space-y-4">
             <div className="flex items-center gap-2 px-2">
               <i className="fas fa-triangle-exclamation text-red-400 text-xs"></i>
               <h4 className="text-[10px] font-black uppercase text-red-400 tracking-widest">Zona de Peligro</h4>
             </div>
             <button onClick={handleResetSales} className="w-full bg-white border border-red-100 text-red-500 py-5 rounded-[2rem] font-black text-[10px] uppercase tracking-widest shadow-sm active:bg-red-50 transition-all flex items-center justify-center gap-2">
               <i className="fas fa-trash-can"></i> Reiniciar Ventas
             </button>
          </section>
        )}

        {/* Info & Support */}
        <div className="text-center py-6">
           <p className="text-[10px] font-bold text-slate-300 uppercase tracking-widest">Aqua+ Fundadores Pro</p>
           <p className="text-[9px] text-slate-300">v3.5.0 Enterprise Edition</p>
           <p className="text-[8px] text-slate-200 mt-1">{localStorage.getItem('aqua_device_id') || 'ID Desconocido'}</p>
        </div>

        <div className="pt-2">
          <button onClick={() => window.location.reload()} className="w-full bg-sky-100 text-sky-600 py-6 rounded-[2.5rem] font-black text-xs uppercase tracking-[0.2em] flex items-center justify-center gap-3 active:scale-95 transition-all">
            <i className="fas fa-rotate"></i> Reiniciar Aplicación
          </button>
        </div>
      </div>
    </div>
  );
};

export type ViewType = 'dashboard' | 'pos' | 'orders' | 'logistics' | 'production' | 'sync' | 'whatsapp' | 'customers' | 'employees' | 'reports' | 'settings' | 'quality' | 'scanner' | 'inventory' | 'tickets' | 'supplies' | 'messages';

export interface Product {
  id: string;
  name: string;
  price: number;
  stock: number;
  category?: 'Agua' | 'Insumos' | 'Accesorios';
  lastUpdated?: number;
}

export type GarrafonType = 'Aqua' | 'Bonafont' | 'Ciel' | 'E-Pura' | 'Generico';

export interface Customer {
  id: string;
  name: string;
  alias: string;
  address?: string; 
  phone?: string;
  specialPrice?: number;
  lat?: number;
  lng?: number;
  garrafonType?: GarrafonType;
  jugsOnLoan?: number; 
  balance: number;
  lastUpdated?: number;
}

export interface TicketConfig {
  businessName: string;
  rfc: string;
  address: string;
  phone: string;
  footerMessage: string;
  logoUrl?: string;
  website?: string;
  socialMedia?: string;
  extraNote?: string;
  slogan?: string;
  email?: string;
  colorHex?: string; 
  paperWidth?: '58mm' | '80mm';
}

export interface ProcessStep {
  stage: string;
  process: string;
  time: number; // Seconds
}

export interface ProductionConfig {
  backwashSequence: ProcessStep[];
  regenerationSequence: ProcessStep[];
}

export interface CloudConfig {
  url: string;
  apiKey: string;
  autoSync: boolean;
  lastSync?: number;
}

export interface Order {
  id: string;
  customerId: string;
  customerAlias: string;
  items: CartItem[];
  total: number;
  status: 'pendiente' | 'asignado' | 'entregado' | 'cancelado';
  vehicleId?: string;
  timestamp: number;
  priority: number;
  deviceId?: string; 
  lastUpdated?: number; // Crucial for sync conflict resolution
}

export interface CartItem extends Product {
  quantity: number;
}

export type PaymentMethod = 'Efectivo' | 'Transferencia' | 'Crédito' | 'Multimodal';

export interface PaymentSplit {
  method: 'Efectivo' | 'Transferencia';
  amount: number;
}

export interface Sale {
  id: string;
  timestamp: number;
  customerId: string;
  customerAlias: string;
  items: CartItem[];
  total: number;
  paidAmount: number;
  change: number;
  paymentSplits: PaymentSplit[];
  emptyGarrafonsReturned: number;
  synced: boolean;
  deviceId?: string; 
}

export interface QualityRecord {
  id: string;
  timestamp: number;
  type: 'Cruda' | 'Producto';
  ph: number;
  cloro: number;
  tds: number;
  dureza: number;
  color: string;
  sabor: string;
  turbiedad: string;
  employeeId: string;
}

export interface Task {
  id: string;
  employeeId: string;
  title: string;
  description?: string;
  status: 'pendiente' | 'completada';
  timestamp: number;
  date: string;
  deviceId?: string; 
  lastUpdated?: number;
}

export interface Attendance {
  id: string;
  employeeId: string;
  timestamp: number;
  date: string;
  status: 'presente' | 'falta' | 'retardo';
}

export type Role = 'Repartidor' | 'Planta' | 'Administrador';

export interface Employee {
  id: string;
  name: string;
  roles: Role[]; 
  phone: string;
  pin: string;
  permissions: ViewType[];
  lastUpdated?: number;
}

export interface FuelRecord {
  id: string;
  date: number;
  mileage: number;
  liters: number;
  cost: number;
  notes?: string;
}

export interface Vehicle {
  id: string;
  plate: string;
  description: string;
  loadCapacity: number;
  currentLoad: number;
  inventory: CartItem[]; 
  fuelHistory: FuelRecord[]; 
  lastUpdated?: number;
}

export interface SavedReport {
  id: string;
  timestamp: number;
  rangeType: 'day' | 'week' | 'month';
  dateLabel: string; 
  totalGross: number;
  totalTransactions: number;
  averageTicket: number;
  payments: { cash: number, transfer: number };
  topProducts: { name: string, qty: number, total: number }[];
  notes?: string;
}

export interface Message {
  id: string;
  text: string;
  senderId: string;
  receiverId: string; 
  timestamp: number;
  read: boolean;
}

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { Product, Customer, Sale, CartItem, Order, Employee, Vehicle, PaymentSplit, ViewType, QualityRecord, Task, Attendance, TicketConfig, CloudConfig, SavedReport, FuelRecord, Message, Role, ProductionConfig } from '../types';
import { INITIAL_PRODUCTS, INITIAL_CUSTOMERS, BACKWASH_SEQUENCE, REGENERATION_SEQUENCE } from '../constants';

const DEFAULT_PERMISSIONS: ViewType[] = ['dashboard', 'pos', 'orders', 'customers', 'logistics', 'inventory', 'whatsapp', 'production', 'sync', 'reports', 'settings', 'employees', 'quality', 'scanner', 'tickets', 'messages'];

// Updated to use a blank PNG placeholder instead of SVG to be safe for PDF-LIB
const INITIAL_TICKET_CONFIG: TicketConfig = {
  businessName: 'AQUA+ FUNDADORES',
  rfc: 'AQUA900101-XXX',
  address: 'Calle del Agua #123, Col. Manantiales',
  phone: '33-1234-5678',
  footerMessage: '¡Gracias por tu preferencia! Frescura que hidrata tu vida.',
  website: 'www.aquafun.mx',
  socialMedia: '@aquafun_pro',
  extraNote: 'No hay cambios después de 24 horas.',
  // Use a 1x1 transparent PNG or valid PNG base64 to avoid crashes in PDF generator which doesn't support SVG
  logoUrl: 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=', 
  colorHex: '#0284c7', // Sky-600 default
  email: 'contacto@aquafun.mx',
  paperWidth: '80mm'
};

const INITIAL_CLOUD_CONFIG: CloudConfig = {
  url: 'https://aquamasfundadores-default-rtdb.firebaseio.com/',
  apiKey: 't8rzxkeWbMIKGufdW7RV1j1bKS0TKf2gPkgmZ36A',
  autoSync: true
};

// --- DEVICE ID MANAGEMENT ---
const getDeviceId = () => {
  let id = localStorage.getItem('aqua_device_id');
  if (!id) {
    // Generar un ID corto único (ej: 4A2B)
    id = Math.random().toString(36).substring(2, 6).toUpperCase();
    localStorage.setItem('aqua_device_id', id);
  }
  return id;
};

// Hook Logic Factory
const useERPFactory = () => {
  const [deviceId] = useState(getDeviceId());

  const [products, setProducts] = useState<Product[]>(() => {
    const saved = localStorage.getItem('aqua_products');
    return saved ? JSON.parse(saved) : INITIAL_PRODUCTS;
  });

  const [customers, setCustomers] = useState<Customer[]>(() => {
    const saved = localStorage.getItem('aqua_customers');
    return saved ? JSON.parse(saved).map((c: any) => ({ ...c, balance: c.balance || 0 })) : INITIAL_CUSTOMERS;
  });

  const [ticketConfig, setTicketConfig] = useState<TicketConfig>(() => {
    const saved = localStorage.getItem('aqua_ticket_config');
    // Ensure colorHex exists for older saved configs
    const parsed = saved ? JSON.parse(saved) : INITIAL_TICKET_CONFIG;
    return { ...INITIAL_TICKET_CONFIG, ...parsed };
  });

  const [productionConfig, setProductionConfig] = useState<ProductionConfig>(() => {
    const saved = localStorage.getItem('aqua_production_config');
    return saved ? JSON.parse(saved) : { 
      backwashSequence: BACKWASH_SEQUENCE, 
      regenerationSequence: REGENERATION_SEQUENCE 
    };
  });

  const [cloudConfig, setCloudConfig] = useState<CloudConfig>(() => {
    const saved = localStorage.getItem('aqua_cloud_config');
    if (saved) {
      const parsed = JSON.parse(saved);
      if (!parsed.url || parsed.url === '') {
        return INITIAL_CLOUD_CONFIG;
      }
      return parsed;
    }
    return INITIAL_CLOUD_CONFIG;
  });

  const [sales, setSales] = useState<Sale[]>(() => {
    const saved = localStorage.getItem('aqua_sales');
    return saved ? JSON.parse(saved) : [];
  });

  const [orders, setOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('aqua_orders');
    return saved ? JSON.parse(saved) : [];
  });

  const [employees, setEmployees] = useState<Employee[]>(() => {
    const saved = localStorage.getItem('aqua_employees');
    let initial = saved ? JSON.parse(saved) : [
      { id: 'admin', name: 'Gerente General', roles: ['Administrador'], phone: '3312345678', pin: '1234', permissions: [...DEFAULT_PERMISSIONS] }
    ];

    // MIGRATION: Convert single role string to roles array if needed
    initial = initial.map((e: any) => {
      if (e.role && !e.roles) {
        return { ...e, roles: [e.role], role: undefined };
      }
      return e;
    });

    return initial;
  });

  // Ensure Admins always have full permissions on load
  useEffect(() => {
    setEmployees(prev => prev.map(e => 
      e.roles.includes('Administrador')
        ? { ...e, permissions: [...DEFAULT_PERMISSIONS] } 
        : e
    ));
  }, []);

  const [vehicles, setVehicles] = useState<Vehicle[]>(() => {
    const saved = localStorage.getItem('aqua_vehicles');
    // Migration: ensure inventory and fuelHistory arrays exist
    const parsed = saved ? JSON.parse(saved) : [{ id: 'v1', plate: 'ABC-123', description: 'Nissan NP300', loadCapacity: 60, currentLoad: 0, inventory: [], fuelHistory: [] }];
    return parsed.map((v: any) => ({
        ...v,
        inventory: v.inventory || [],
        fuelHistory: v.fuelHistory || []
    }));
  });

  const [qualityRecords, setQualityRecords] = useState<QualityRecord[]>(() => {
    const saved = localStorage.getItem('aqua_quality');
    return saved ? JSON.parse(saved) : [];
  });

  const [tasks, setTasks] = useState<Task[]>(() => {
    const saved = localStorage.getItem('aqua_tasks');
    return saved ? JSON.parse(saved) : [];
  });

  const [attendance, setAttendance] = useState<Attendance[]>(() => {
    const saved = localStorage.getItem('aqua_attendance');
    return saved ? JSON.parse(saved) : [];
  });

  const [savedReports, setSavedReports] = useState<SavedReport[]>(() => {
    const saved = localStorage.getItem('aqua_saved_reports');
    return saved ? JSON.parse(saved) : [];
  });

  const [messages, setMessages] = useState<Message[]>(() => {
    const saved = localStorage.getItem('aqua_messages');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => {
    localStorage.setItem('aqua_products', JSON.stringify(products));
    localStorage.setItem('aqua_customers', JSON.stringify(customers));
    localStorage.setItem('aqua_sales', JSON.stringify(sales));
    localStorage.setItem('aqua_orders', JSON.stringify(orders));
    localStorage.setItem('aqua_employees', JSON.stringify(employees));
    localStorage.setItem('aqua_vehicles', JSON.stringify(vehicles));
    localStorage.setItem('aqua_ticket_config', JSON.stringify(ticketConfig));
    localStorage.setItem('aqua_production_config', JSON.stringify(productionConfig));
    localStorage.setItem('aqua_quality', JSON.stringify(qualityRecords));
    localStorage.setItem('aqua_tasks', JSON.stringify(tasks));
    localStorage.setItem('aqua_attendance', JSON.stringify(attendance));
    localStorage.setItem('aqua_cloud_config', JSON.stringify(cloudConfig));
    localStorage.setItem('aqua_saved_reports', JSON.stringify(savedReports));
    localStorage.setItem('aqua_messages', JSON.stringify(messages));
  }, [products, customers, sales, orders, employees, vehicles, ticketConfig, productionConfig, qualityRecords, tasks, attendance, cloudConfig, savedReports, messages]);

  // Helper para fecha local ISO YYYY-MM-DD
  const getLocalDateISO = () => {
    const d = new Date();
    const offset = d.getTimezoneOffset() * 60000;
    return new Date(d.getTime() - offset).toISOString().split('T')[0];
  };

  const addSale = (
    customerId: string, 
    items: CartItem[], 
    total: number, 
    paidAmount: number, 
    splits: PaymentSplit[], 
    returnedVacios: number, 
    manualTimestamp?: number,
    vehicleId?: string // New optional parameter
  ) => {
    const debtAmount = Math.max(0, total - paidAmount);

    // Calculate Asset Movement (Jugs)
    const jugsSold = items
      .filter(i => i.category === 'Agua' || i.name.toLowerCase().includes('garraf'))
      .reduce((acc, item) => acc + item.quantity, 0);

    const netJugChange = jugsSold - returnedVacios;

    // ID GENERATION: Includes Device ID to prevent collisions during sync
    const timestamp = manualTimestamp || Date.now();
    const uniqueId = `TKT-${timestamp.toString().slice(-6)}-${deviceId}`;

    const newSale: Sale = {
      id: uniqueId,
      timestamp: timestamp,
      customerId,
      customerAlias: customers.find(c => c.id === customerId)?.alias || 'Anonimo',
      items,
      total,
      paidAmount,
      change: Math.max(0, paidAmount - total),
      paymentSplits: splits,
      emptyGarrafonsReturned: returnedVacios,
      synced: false,
      deviceId: deviceId // Metadata for traceability
    };

    setSales(prev => [newSale, ...prev]);

    // Update Customer Balance and Jug Inventory with LAST UPDATED
    setCustomers(prev => prev.map(c => {
      if (c.id === customerId) {
        return { 
          ...c, 
          balance: (c.balance || 0) + debtAmount,
          jugsOnLoan: Math.max(0, (c.jugsOnLoan || 0) + netJugChange),
          lastUpdated: Date.now() // Track change
        };
      }
      return c;
    }));

    // Logic to deduct inventory
    if (vehicleId && vehicleId !== 'plant') {
      // Deduct from specific vehicle
      setVehicles(prev => prev.map(v => {
        if (v.id !== vehicleId) return v;

        let currentInventory = [...(v.inventory || [])];

        items.forEach(soldItem => {
          const idx = currentInventory.findIndex(inv => inv.id === soldItem.id);
          if (idx !== -1) {
            // Reduce quantity
            const newQty = Math.max(0, currentInventory[idx].quantity - soldItem.quantity);
            if (newQty === 0) {
               currentInventory.splice(idx, 1);
            } else {
               currentInventory[idx] = { ...currentInventory[idx], quantity: newQty };
            }
          }
        });

        const newLoad = currentInventory.reduce((acc, i) => acc + (i.quantity || 0), 0);
        return { ...v, inventory: currentInventory, currentLoad: newLoad, lastUpdated: Date.now() };
      }));
    } else {
      // Deduct from Plant (Default)
      setProducts(prev => prev.map(p => {
        const cartItem = items.find(item => item.id === p.id);
        return cartItem ? { ...p, stock: p.stock - cartItem.quantity, lastUpdated: Date.now() } : p;
      }));
    }

    return newSale;
  };

  const resetSales = () => {
    setSales([]);
    alert("Todas las ventas han sido eliminadas. El historial está limpio.");
  };

  // --- MEGA SYNC FUNCTION ---
  // Accepts a partial State object and merges it.
  // Note: Most merge logic is now handled in SyncModule's smartMerge before calling this,
  // but we keep basic safety checks here.
  const syncData = useCallback((externalData: any) => {
    if (!externalData) return false;
    let changesMade = false;

    // Helper to just set the data (assuming SyncModule did the heavy lifting/merging)
    const setIfPresent = <T,>(key: string, setter: React.Dispatch<React.SetStateAction<T>>) => {
        if (externalData[key]) {
            setter(externalData[key]);
            changesMade = true;
        }
    };

    setIfPresent('sales', setSales);
    setIfPresent('customers', setCustomers);
    setIfPresent('products', setProducts);
    setIfPresent('orders', setOrders);
    setIfPresent('vehicles', setVehicles);
    setIfPresent('employees', setEmployees);
    setIfPresent('qualityRecords', setQualityRecords);
    setIfPresent('tasks', setTasks);
    setIfPresent('attendance', setAttendance);
    setIfPresent('savedReports', setSavedReports);
    setIfPresent('messages', setMessages);
    setIfPresent('productionConfig', setProductionConfig);

    // Ticket Config (Object merge)
    if (externalData.ticketConfig) {
      if (JSON.stringify(ticketConfig) !== JSON.stringify(externalData.ticketConfig)) {
        setTicketConfig(externalData.ticketConfig);
        changesMade = true;
      }
    }

    return changesMade;
  }, [ticketConfig]);

  const importCustomers = useCallback((newCustomers: Customer[]) => {
    setCustomers(prev => {
      const existingIds = new Set(prev.map(c => c.id));
      const filteredNew = newCustomers.filter(c => !existingIds.has(c.id));
      // Mark imported as updated now
      const withTimestamp = filteredNew.map(c => ({...c, lastUpdated: Date.now()}));
      return [...prev, ...withTimestamp];
    });
  }, []);

  const loadVehicle = (vehicleId: string, product: Product, delta: number) => {
    if (!product || !product.id) return;

    if (delta > 0) {
      const currentProduct = products.find(p => p.id === product.id);
      if (!currentProduct) return;
      if (currentProduct.stock < delta) {
          alert("Stock insuficiente en planta.");
          return;
      }
    }

    setVehicles(prev => prev.map(v => {
        if (v.id !== vehicleId) return v;

        const newInventory = Array.isArray(v.inventory) ? [...v.inventory] : [];
        const existingItemIndex = newInventory.findIndex(i => i.id === product.id);

        if (existingItemIndex > -1) {
            const newQty = newInventory[existingItemIndex].quantity + delta;
            if (newQty <= 0) {
                newInventory.splice(existingItemIndex, 1);
            } else {
                newInventory[existingItemIndex] = { ...newInventory[existingItemIndex], quantity: newQty };
            }
        } else if (delta > 0) {
            newInventory.push({ ...product, quantity: delta });
        }

        const newLoad = newInventory.reduce((acc, item) => acc + (item.quantity || 0), 0);

        return { ...v, inventory: newInventory, currentLoad: newLoad, lastUpdated: Date.now() };
    }));

    setProducts(prev => prev.map(p => {
        if (p.id === product.id) {
            return { ...p, stock: p.stock - delta, lastUpdated: Date.now() };
        }
        return p;
    }));
  };

  const addFuelRecord = (vehicleId: string, record: FuelRecord) => {
    setVehicles(prev => prev.map(v => {
      if (v.id !== vehicleId) return v;
      return { 
        ...v, 
        fuelHistory: [record, ...(v.fuelHistory || [])],
        lastUpdated: Date.now()
      };
    }));
  };

  const sendMessage = (text: string, senderId: string, receiverId: string) => {
    const newMessage: Message = {
      id: `MSG-${Date.now()}`,
      text,
      senderId,
      receiverId,
      timestamp: Date.now(),
      read: false
    };

    setMessages(prev => {
        const updatedMessages = [...prev, newMessage];
        if (cloudConfig.url && cloudConfig.autoSync) {
            const endpoint = `${cloudConfig.url}messages.json${cloudConfig.apiKey ? `?auth=${cloudConfig.apiKey}` : ''}`;
            fetch(endpoint, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(updatedMessages)
            }).catch(err => console.error("Error pushing message to cloud:", err));
        }
        return updatedMessages;
    });
  };

  return { 
    deviceId, // Expose Device ID
    products, 
    saveProduct: (p: Product) => setProducts(prev => prev.find(x => x.id === p.id) ? prev.map(x => x.id === p.id ? { ...p, lastUpdated: Date.now() } : x) : [...prev, { ...p, lastUpdated: Date.now() }]),
    deleteProduct: (id: string) => setProducts(prev => prev.filter(p => p.id !== id)),
    customers, 
    saveCustomer: (c: Customer) => setCustomers(prev => prev.find(x => x.id === c.id) ? prev.map(x => x.id === c.id ? { ...c, lastUpdated: Date.now() } : x) : [...prev, { ...c, lastUpdated: Date.now() }]),
    deleteCustomer: (id: string) => setCustomers(prev => prev.filter(c => c.id !== id)),
    importCustomers,
    sales, addSale, resetSales,
    orders, 
    setOrders,
    addOrder: (o: Partial<Order>) => {
      const newOrder: Order = {
        id: `ORD-${Date.now().toString().slice(-6)}-${deviceId}`,
        timestamp: Date.now(),
        status: 'pendiente',
        priority: 1,
        items: [],
        total: 0,
        customerId: '',
        customerAlias: '',
        deviceId: deviceId,
        lastUpdated: Date.now(), // Track creation
        ...o
      } as Order;
      setOrders(prev => [newOrder, ...prev]);
    },
    updateOrder: (o: Order) => setOrders(prev => prev.map(item => item.id === o.id ? { ...o, lastUpdated: Date.now() } : item)),
    employees, 
    saveEmployee: (e: Employee) => setEmployees(prev => prev.find(x => x.id === e.id) ? prev.map(x => x.id === e.id ? { ...e, lastUpdated: Date.now() } : x) : [...prev, { ...e, lastUpdated: Date.now() }]),
    vehicles, 
    setVehicles,
    loadVehicle,
    deleteVehicle: (id: string) => setVehicles(prev => prev.filter(v => v.id !== id)),
    addFuelRecord,
    tasks,
    addTask: (t: Partial<Task>) => {
      const newTask: Task = {
        id: `TSK-${Date.now().toString().slice(-4)}-${deviceId}`,
        timestamp: Date.now(),
        status: 'pendiente',
        deviceId: deviceId,
        lastUpdated: Date.now(),
        ...t
      } as Task;
      setTasks(prev => [newTask, ...prev]);
    },
    updateTaskStatus: (id: string, status: Task['status']) => setTasks(prev => prev.map(t => t.id === id ? { ...t, status, lastUpdated: Date.now() } : t)),
    deleteTask: (id: string) => setTasks(prev => prev.filter(t => t.id !== id)),
    clearTasksByDate: (date: string) => setTasks(prev => prev.filter(t => t.date !== date)),
    attendance,
    recordAttendance: (employeeId: string, status: Attendance['status']) => {
      const date = getLocalDateISO();
      setAttendance(prev => {
        const filtered = prev.filter(a => !(a.employeeId === employeeId && a.date === date));
        return [{ id: `ATT-${Date.now()}`, employeeId, status, date, timestamp: Date.now() }, ...filtered];
      });
    },
    qualityRecords,
    addQualityRecord: (r: Partial<QualityRecord>) => {
      const newRecord: QualityRecord = {
        id: `QUAL-${Date.now().toString().slice(-4)}`,
        timestamp: Date.now(),
        employeeId: 'admin',
        ...r
      } as QualityRecord;
      setQualityRecords(prev => [newRecord, ...prev]);
    },
    ticketConfig, setTicketConfig,
    productionConfig, setProductionConfig,
    cloudConfig, setCloudConfig,
    syncData,
    savedReports,
    addSavedReport: (r: SavedReport) => setSavedReports(prev => [r, ...prev]),
    deleteSavedReport: (id: string) => setSavedReports(prev => prev.filter(r => r.id !== id)),
    messages,
    sendMessage,
  };
};

// Create Context
const ERPContext = createContext<ReturnType<typeof useERPFactory> | null>(null);

// Provider Component
export const ERPProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const data = useERPFactory();
  return <ERPContext.Provider value={data}>{children}</ERPContext.Provider>;
};

// Accessor Hook (to be re-exported)
export const useERPDataHook = () => {
  const context = useContext(ERPContext);
  if (!context) throw new Error("useERPData must be used within ERPProvider");
  return context;
};

import React, { useState, useEffect, useRef } from 'react';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard } from './ui/Cards';

const TRANSITION_TIME = 15; 
const STORAGE_KEY = 'aqua_production_state_v3'; 

export const ProductionModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const { productionConfig } = useERPData(); // Now getting config from state

  const [mode, setMode] = useState<'backwash' | 'regen'>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved).mode : 'backwash';
  });

  const [currentStepIdx, setCurrentStepIdx] = useState(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved).currentStepIdx : 0;
  });

  const [isRunning, setIsRunning] = useState(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved).isRunning : false;
  });

  const [isTransitioning, setIsTransitioning] = useState(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved).isTransitioning : false;
  });

  const [endTime, setEndTime] = useState<number | null>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved).endTime : null;
  });

  const [timeLeft, setTimeLeft] = useState(0);
  const [hardness, setHardness] = useState(8);
  const wakeLock = useRef<WakeLockSentinel | null>(null);

  // Dynamic sequences
  const currentSequence = mode === 'backwash' ? productionConfig.backwashSequence : productionConfig.regenerationSequence;

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      if (parsed.isRunning && parsed.endTime) {
        const now = Date.now();
        const diff = Math.ceil((parsed.endTime - now) / 1000);
        if (diff > 0) {
          setTimeLeft(diff);
          requestWakeLock();
        } else {
          setTimeLeft(0);
        }
      } else {
        const defaultTime = parsed.isTransitioning ? TRANSITION_TIME : currentSequence[parsed.currentStepIdx]?.time || 0;
        setTimeLeft(parsed.savedTimeLeft || defaultTime);
      }
    } else {
      setTimeLeft(currentSequence[0]?.time || 0);
    }
  }, [currentSequence]); // Add dependency on currentSequence changes

  useEffect(() => {
    const stateToSave = { mode, currentStepIdx, endTime, isRunning, isTransitioning, savedTimeLeft: timeLeft };
    localStorage.setItem(STORAGE_KEY, JSON.stringify(stateToSave));
  }, [mode, currentStepIdx, endTime, isRunning, timeLeft, isTransitioning]);

  const requestWakeLock = async () => {
    try { if ('wakeLock' in navigator && !wakeLock.current) wakeLock.current = await navigator.wakeLock.request('screen'); } 
    catch (err) { console.warn(err); }
  };

  const releaseWakeLock = async () => {
    if (wakeLock.current) { await wakeLock.current.release(); wakeLock.current = null; }
  };

  useEffect(() => {
    let interval: any;
    if (isRunning && endTime) {
      requestWakeLock(); 
      interval = setInterval(() => {
        const now = Date.now();
        const remaining = Math.ceil((endTime - now) / 1000);
        if (remaining <= 0) {
          if (isTransitioning) {
            setIsTransitioning(false);
            const nextIdx = currentStepIdx + 1;
            setCurrentStepIdx(nextIdx);
            const nextStepTime = currentSequence[nextIdx]?.time || 0;
            const newEndTime = Date.now() + nextStepTime * 1000;
            setEndTime(newEndTime);
            setTimeLeft(nextStepTime);
          } else {
            if (navigator.vibrate) navigator.vibrate([1000, 500, 1000]); 
            if (currentStepIdx < currentSequence.length - 1) {
              setIsTransitioning(true);
              const newEndTime = Date.now() + TRANSITION_TIME * 1000;
              setEndTime(newEndTime);
              setTimeLeft(TRANSITION_TIME);
            } else {
              setIsRunning(false);
              setEndTime(null);
              releaseWakeLock();
              localStorage.removeItem(STORAGE_KEY);
              alert("PROCESO FINALIZADO");
            }
          }
        } else {
          setTimeLeft(remaining);
        }
      }, 1000);
    } else {
      releaseWakeLock();
    }
    return () => clearInterval(interval);
  }, [isRunning, endTime, currentStepIdx, currentSequence, mode, isTransitioning]);

  const startSequence = () => {
    const duration = timeLeft > 0 ? timeLeft : (isTransitioning ? TRANSITION_TIME : currentSequence[currentStepIdx].time);
    setEndTime(Date.now() + duration * 1000);
    setIsRunning(true);
  };

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s.toString().padStart(2, '0')}`;
  };

  return (
    <div className="px-6 py-8 animate-fadeIn h-full bg-slate-900 overflow-y-auto pb-24 no-scrollbar text-white">
      <div className="flex items-center gap-4 mb-6">
        <button onClick={onBack} className="w-12 h-12 bg-white/10 rounded-2xl flex items-center justify-center active:scale-90 transition-transform">
          <i className="fas fa-arrow-left"></i>
        </button>
        <h2 className="text-2xl font-black tracking-tight">Control Planta</h2>
      </div>

      <div className="space-y-6">
        <div className="flex bg-white/10 p-1.5 rounded-[2rem] shadow-inner border border-white/5">
          <button onClick={() => { if(!isRunning) { setMode('backwash'); setCurrentStepIdx(0); setTimeLeft(productionConfig.backwashSequence[0].time); }}} disabled={isRunning} className={`flex-1 py-4 rounded-[1.8rem] text-[10px] font-black uppercase tracking-widest transition-all ${mode === 'backwash' ? 'bg-sky-500 text-white shadow-lg' : 'text-slate-400'} ${isRunning ? 'opacity-50' : ''}`}>
            Retrolavado
          </button>
          <button onClick={() => { if(!isRunning) { setMode('regen'); setCurrentStepIdx(0); setTimeLeft(productionConfig.regenerationSequence[0].time); }}} disabled={isRunning} className={`flex-1 py-4 rounded-[1.8rem] text-[10px] font-black uppercase tracking-widest transition-all ${mode === 'regen' ? 'bg-amber-500 text-white shadow-lg' : 'text-slate-400'} ${isRunning ? 'opacity-50' : ''}`}>
            Regeneración
          </button>
        </div>

        <div className="flex justify-between gap-1 px-2 mb-2">
          {currentSequence.map((s, idx) => (
            <div key={idx} className="flex-1 flex flex-col items-center gap-2">
              <div className={`h-1.5 w-full rounded-full transition-all duration-500 ${idx < currentStepIdx ? 'bg-emerald-500' : idx === currentStepIdx ? (isTransitioning ? 'bg-emerald-500' : (mode === 'regen' ? 'bg-amber-500' : 'bg-sky-500')) : 'bg-white/10'}`}></div>
            </div>
          ))}
        </div>

        <div className={`relative overflow-hidden rounded-[2.5rem] shadow-2xl transition-all duration-500 ${isTransitioning ? 'bg-violet-600' : 'bg-slate-800 border border-white/10'}`}>
          <div className="p-8 text-center relative z-10">
            <div className={`w-fit mx-auto px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest mb-4 border ${isTransitioning ? 'bg-violet-500 border-violet-400 text-white animate-pulse' : 'bg-white/10 border-white/10 text-white/70'}`}>
              {isTransitioning ? 'AJUSTE VÁLVULAS' : `Paso ${currentStepIdx + 1}/${currentSequence.length}`}
            </div>

            <h3 className="text-3xl font-black tracking-tight leading-none mb-2 text-white">
              {isTransitioning ? 'CAMBIO DE FASE' : currentSequence[currentStepIdx]?.stage}
            </h3>
            <p className={`font-black uppercase text-sm tracking-widest mb-8 ${isTransitioning ? 'text-violet-200' : 'text-sky-400'}`}>
              {isTransitioning ? `Siguiente: ${currentSequence[currentStepIdx + 1]?.process}` : currentSequence[currentStepIdx]?.process}
            </p>

            <div className="text-8xl font-mono font-black mb-8 tracking-tighter tabular-nums text-white drop-shadow-2xl">
              {isTransitioning ? timeLeft : formatTime(timeLeft)}
              <span className="text-lg text-white/30 ml-2 font-sans font-bold">{isTransitioning ? 'seg' : 'min'}</span>
            </div>

            {!isRunning ? (
              <button onClick={startSequence} className={`w-full py-5 rounded-[2rem] font-black text-sm uppercase tracking-widest shadow-xl active:scale-95 transition-all ${mode === 'regen' ? 'bg-amber-500 text-black' : 'bg-sky-500 text-white'}`}>
                {timeLeft > 0 && timeLeft < currentSequence[currentStepIdx].time ? 'Reanudar' : 'Iniciar Proceso'}
              </button>
            ) : (
              <button onClick={() => setIsRunning(false)} className="w-full bg-red-500/20 border border-red-500 text-red-400 py-5 rounded-[2rem] font-black text-sm uppercase tracking-widest active:scale-95 transition-all flex items-center justify-center gap-2">
                <i className="fas fa-pause"></i> Pausar
              </button>
            )}
          </div>

          {/* Progress BG */}
          <div className="absolute bottom-0 left-0 h-2 bg-black/30 w-full">
             <div className={`h-full transition-all duration-1000 ease-linear ${isTransitioning ? 'bg-white' : (mode === 'regen' ? 'bg-amber-500' : 'bg-sky-500')}`} style={{ width: `${isTransitioning ? ((TRANSITION_TIME - timeLeft)/TRANSITION_TIME)*100 : ((currentSequence[currentStepIdx].time - timeLeft)/currentSequence[currentStepIdx].time)*100}%` }}></div>
          </div>
        </div>

        {!isTransitioning && (
          <div className="bg-white/5 border border-white/10 rounded-[2rem] p-6 flex justify-between items-center">
             <div className="flex items-center gap-4">
                <div className="w-12 h-12 bg-white/10 rounded-2xl flex items-center justify-center text-white text-xl"><i className="fas fa-flask"></i></div>
                <div>
                   <p className="text-[10px] font-black uppercase text-white/50 tracking-widest">Dureza (PPM)</p>
                   <p className="text-2xl font-black text-white">{hardness * 17.1} <span className="text-xs text-white/30 font-bold">mg/L</span></p>
                </div>
             </div>
             <div className="flex gap-2">
                <button onClick={() => setHardness(Math.max(0, hardness - 1))} className="w-10 h-10 bg-white/10 rounded-xl text-white font-black hover:bg-white/20">-</button>
                <span className="w-10 flex items-center justify-center font-black text-xl">{hardness}</span>
                <button onClick={() => setHardness(hardness + 1)} className="w-10 h-10 bg-white/10 rounded-xl text-white font-black hover:bg-white/20">+</button>
             </div>
          </div>
        )}
      </div>
    </div>
  );
};

