  doc.roundedRect(15 + (boxWidth * 2) + 10, yPos, boxWidth, boxHeight, 3, 3, 'FD');
  doc.setTextColor(255, 255, 255);
  doc.setFontSize(8);
  doc.text('TOTAL AUDITADO', 20 + (boxWidth * 2) + 10, yPos + 8);
  doc.setFontSize(16);
  doc.text(`${data.totalAssets}`, 20 + (boxWidth * 2) + 10, yPos + 18);

