  doc.text('EN RUTA', 20 + boxWidth + 5, yPos + 8);
  doc.setFontSize(16);
  doc.text(`${data.routeStock}`, 20 + boxWidth + 5, yPos + 18);

  // Box 3: Total
  doc.setFillColor(13, 148, 136); // Teal-600
  doc.roundedRect(15 + (boxWidth * 2) + 10, yPos, boxWidth, boxHeight, 3, 3, 'FD');
  doc.setTextColor(255, 255, 255);
  doc.setFontSize(8);
  doc.text('TOTAL AUDITADO', 20 + (boxWidth * 2) + 10, yPos + 8);
  doc.setFontSize(16);
  doc.text(`${data.totalAssets}`, 20 + (boxWidth * 2) + 10, yPos + 18);

  yPos += 40;

  // --- MOVEMENT BALANCE ---
  doc.setTextColor(15, 23, 42);
  doc.setFontSize(12);
  doc.text('Balance de Flujo (Movimientos en Periodo)', 15, yPos);
  yPos += 5;

  autoTable(doc, {
    startY: yPos,
    head: [['Concepto', 'Cantidad', 'Interpretación']],
    body: [
      ['Salidas (Ventas)', data.soldCount, 'Envases entregados a clientes'],
      ['Entradas (Retornos)', data.returnedCount, 'Envases vacíos recibidos'],
      ['Balance Neto', data.netMovement, data.netMovement > 0 ? 'Más envases en calle (Deuda)' : 'Recuperación de envases']
    ],
    theme: 'grid',
    headStyles: { fillColor: [13, 148, 136] }, // Teal
    columnStyles: { 1: { fontStyle: 'bold', halign: 'center' } },
    didParseCell: (dataCell: any) => {
        if(dataCell.row.index === 2 && dataCell.column.index === 1) {
            dataCell.cell.styles.textColor = data.netMovement > 0 ? [220, 38, 38] : [22, 163, 74];
        }
    }
  });

  yPos = (doc as any).lastAutoTable.finalY + 20;

  // --- VEHICLE BREAKDOWN ---
  doc.text('Desglose por Unidad Móvil', 15, yPos);
  yPos += 5;

  const vehicleRows = data.vehicleBreakdown.map(v => [
    v.plate,
    `${v.load} Unidades`,
    v.items
  ]);

  autoTable(doc, {
    startY: yPos,
    head: [['Unidad / Placa', 'Carga Total', 'Detalle de Carga']],
    body: vehicleRows.length > 0 ? vehicleRows : [['Sin unidades activas', '-', '-']],
    theme: 'striped',
    headStyles: { fillColor: [15, 23, 42] }, // Slate-900
  });

  // --- FOOTER ---
  const pageCount = (doc as any).internal.getNumberOfPages();
  for(let i = 1; i <= pageCount; i++) {
    doc.setPage(i);
    doc.setFontSize(8);
    doc.setTextColor(150);
    doc.text(`Aqua+ ERP - Control de Activos - Página ${i} de ${pageCount}`, pageWidth / 2, doc.internal.pageSize.height - 10, { align: 'center' });
  }

  return doc.output('datauristring');
};

export const generateTaskReportPDF = (data: TaskReportData, config: TicketConfig): string => {
  const doc = new jsPDF();
  const pageWidth = doc.internal.pageSize.width;

  // --- HEADER ---
  doc.setFillColor(245, 158, 11); // Amber-500
  doc.rect(0, 0, pageWidth, 40, 'F');

  doc.setTextColor(255, 255, 255);
  doc.setFontSize(22);
  doc.setFont('helvetica', 'bold');
  doc.text(config.businessName, 15, 15);

  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');
  doc.text('REPORTE OPERATIVO DE TAREAS', 15, 22);
  doc.text(`Generado: ${new Date().toLocaleString()}`, 15, 27);

  // Right side header info
  doc.setFontSize(10);
  doc.text(`Periodo: ${data.label}`, pageWidth - 15, 15, { align: 'right' });
  doc.text(`Cumplimiento: ${Math.round((data.completedTasks / (data.totalTasks || 1)) * 100)}%`, pageWidth - 15, 20, { align: 'right' });

  let yPos = 55;

  // --- SUMMARY ---
  doc.setTextColor(15, 23, 42);
  doc.setFontSize(14);
  doc.setFont('helvetica', 'bold');
  doc.text('Resumen de Productividad', 15, yPos);

  yPos += 10;

  // Draw Boxes
  const boxWidth = (pageWidth - 40) / 3;
  const boxHeight = 25;

  // Box 1: Total
  doc.setDrawColor(226, 232, 240);
  doc.setFillColor(248, 250, 252);
  doc.roundedRect(15, yPos, boxWidth, boxHeight, 3, 3, 'FD');
  doc.setFontSize(8);
  doc.setTextColor(100, 116, 139);
  doc.text('TOTAL ASIGNADAS', 20, yPos + 8);
  doc.setFontSize(12);
  doc.setTextColor(15, 23, 42);
  doc.setFont('helvetica', 'bold');
  doc.text(`${data.totalTasks}`, 20, yPos + 18);

  // Box 2: Completadas
  doc.roundedRect(15 + boxWidth + 5, yPos, boxWidth, boxHeight, 3, 3, 'FD');
  doc.setFontSize(8);
  doc.setTextColor(100, 116, 139);
  doc.text('COMPLETADAS', 20 + boxWidth + 5, yPos + 8);
  doc.setFontSize(12);
  doc.setTextColor(34, 197, 94); // Green
  doc.setFont('helvetica', 'bold');
  doc.text(`${data.completedTasks}`, 20 + boxWidth + 5, yPos + 18);

  // Box 3: Pendientes
  doc.roundedRect(15 + (boxWidth * 2) + 10, yPos, boxWidth, boxHeight, 3, 3, 'FD');
  doc.setFontSize(8);
  doc.setTextColor(100, 116, 139);
  doc.text('PENDIENTES', 20 + (boxWidth * 2) + 10, yPos + 8);
  doc.setFontSize(12);
  doc.setTextColor(239, 68, 68); // Red
  doc.setFont('helvetica', 'bold');
  doc.text(`${data.pendingTasks}`, 20 + (boxWidth * 2) + 10, yPos + 18);

  yPos += 40;

  // --- DETAILS PER EMPLOYEE ---
  data.byEmployee.forEach((emp) => {
    if (yPos > 250) {
      doc.addPage();
      yPos = 20;
    }

    doc.setFontSize(12);
    doc.setTextColor(15, 23, 42);
    doc.text(`Colaborador: ${emp.name} (${Math.round((emp.completed / (emp.total || 1)) * 100)}%)`, 15, yPos);
    yPos += 5;

    // Group tasks by date
    const tasksByDate = emp.tasks.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    let lastDate = '';

    const taskRows = tasksByDate.map(t => {
      const isNewDate = t.date !== lastDate;
      if(isNewDate) lastDate = t.date;

      const time = new Date(t.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

      return [
        isNewDate ? t.date : '', // Group visual
        time,
        t.title,
        t.status === 'completada' ? 'COMPLETA' : 'PENDIENTE',
        t.description || '-'
      ];
    });

    autoTable(doc, {
      startY: yPos,
      head: [['Fecha', 'Hora', 'Tarea', 'Estado', 'Detalle']],
      body: taskRows,
      theme: 'grid',
      headStyles: { fillColor: [245, 158, 11] }, // Amber header
      styles: { fontSize: 8 },
      columnStyles: { 
        0: { fontStyle: 'bold', cellWidth: 25 },
        3: { fontStyle: 'bold' }
      },
      didParseCell: (data: any) => {
        if (data.section === 'body' && data.column.index === 3) {
          if (data.cell.raw === 'PENDIENTE') {
            data.cell.styles.textColor = [220, 38, 38]; // Red
          } else {
            data.cell.styles.textColor = [22, 163, 74]; // Green
          }
        }
      }
    });

    yPos = (doc as any).lastAutoTable.finalY + 15;
  });

  // --- FOOTER ---
  const pageCount = (doc as any).internal.getNumberOfPages();
  for(let i = 1; i <= pageCount; i++) {
    doc.setPage(i);
    doc.setFontSize(8);
    doc.setTextColor(150);
    doc.text(`Aqua+ ERP - Reporte Operativo - Página ${i} de ${pageCount}`, pageWidth / 2, doc.internal.pageSize.height - 10, { align: 'center' });
  }

  return doc.output('datauristring');
};

/**
 * Generates a Ticket PDF using pdf-lib and returns raw bytes
 */
export const generateTicketPDF = async (sale: Sale, config: TicketConfig): Promise<Uint8Array> => {
  // Crear nuevo documento PDF
  const pdfDoc = await PDFDocument.create();

  const accent = hexToRgbScale(config.colorHex || '#000000');
  const accentColor = rgb(accent.r, accent.g, accent.b);

  // Calcular altura dinámica base
  const itemsHeight = sale.items.length * 25; 
  // Dynamic space for optional elements
  const qrSpace = config.showQr !== false ? 120 : 20; 
  const footerSpace = config.showFooter !== false ? 60 : 20;
  const logoSpace = (config.showLogo !== false && config.logoUrl) ? 80 : 0;

  const baseHeight = 300 + logoSpace; 
  const ticketHeight = baseHeight + itemsHeight + qrSpace + footerSpace;

  // DYNAMIC WIDTH: 80mm approx 226pts, 58mm approx 164pts.
  // Default to 80mm standard (280pts wide for readability with margins) unless 58mm specified.
  const is58mm = config.paperWidth === '58mm';
  const ticketWidth = is58mm ? 164 : 280; 
  const contentWidth = ticketWidth - 30; // 15 margin each side
  const centerX = ticketWidth / 2;
  const margin = 15;

  const page = pdfDoc.addPage([ticketWidth, ticketHeight]);

  // Obtener fuentes
  const fontRegular = await pdfDoc.embedFont(StandardFonts.Helvetica);
  const fontBold = await pdfDoc.embedFont(StandardFonts.HelveticaBold);
  const fontCourier = await pdfDoc.embedFont(StandardFonts.Courier);

  // Font Size Scaling for 58mm
  const fs = (size: number) => is58mm ? Math.max(6, size * 0.75) : size; 

  let yPos = ticketHeight - 20;

  // --- HELPERS ---
  const sanitize = (text: string) => {
    if (!text) return '';
    return text
      .replace(/★/g, '*')
      .replace(/☆/g, '*')
      .replace(/●/g, '-')
      .replace(/•/g, '-');
  };

  const drawCenteredText = (text: string, font: PDFFont, size: number, color = rgb(0,0,0)) => {
    const safeText = sanitize(text);
    const scaledSize = fs(size);
    const textWidth = font.widthOfTextAtSize(safeText, scaledSize);
    page.drawText(safeText, { x: centerX - (textWidth / 2), y: yPos, size: scaledSize, font, color });
    yPos -= (scaledSize + 4);
  };

  const drawLeftRight = (left: string, right: string, font: PDFFont, size: number, isBold = false) => {
    const safeLeft = sanitize(left);
    const safeRight = sanitize(right);
    const scaledSize = fs(size);
    const rightWidth = font.widthOfTextAtSize(safeRight, scaledSize);
    page.drawText(safeLeft, { x: margin, y: yPos, size: scaledSize, font });
    page.drawText(safeRight, { x: ticketWidth - margin - rightWidth, y: yPos, size: scaledSize, font: isBold ? fontBold : font });
    yPos -= (scaledSize + 6);
  };

  const drawDashedLine = () => {
    const dash = '- - - - - - - - - - - - - - - - - - - - - - - - - - - -';
    const scaledSize = fs(10);
    const textWidth = fontCourier.widthOfTextAtSize(dash, scaledSize);
    page.drawText(dash, { x: centerX - (textWidth / 2), y: yPos, size: scaledSize, font: fontCourier, color: rgb(0.5, 0.5, 0.5) });
    yPos -= 12;
  };

  // --- LOGO ---
  if (config.showLogo !== false && config.logoUrl && config.logoUrl.startsWith('data:image')) {
    try {
      if (config.logoUrl.includes('image/svg+xml')) {
         yPos -= 10;
      } else {
          const base64Data = config.logoUrl.split(',')[1];
          const imageBytes = Uint8Array.from(atob(base64Data), c => c.charCodeAt(0));

          let logoImage;
          if (config.logoUrl.includes('image/png')) {
            logoImage = await pdfDoc.embedPng(imageBytes);
          } else if (config.logoUrl.includes('image/jpeg') || config.logoUrl.includes('image/jpg')) {
            logoImage = await pdfDoc.embedJpg(imageBytes);
          }

          if (logoImage) {
              const logoDims = logoImage.scale(1);
              const maxLogoWidth = is58mm ? 50 : 80;
              const scaleFactor = maxLogoWidth / logoDims.width;
              const scaledWidth = logoDims.width * scaleFactor;
              const scaledHeight = logoDims.height * scaleFactor;

              page.drawImage(logoImage, {
                x: centerX - (scaledWidth / 2),
                y: yPos - scaledHeight,
                width: scaledWidth,
                height: scaledHeight,
              });
              yPos -= (scaledHeight + 10);
          } else {
              yPos -= 10;
          }
      }
    } catch (e) {
      console.warn("Error embedding logo", e);
      yPos -= 10;
    }
  } else {
    yPos -= 10;
  }

  // --- HEADER ---
  drawCenteredText(config.businessName, fontBold, 16, accentColor);
  if (config.slogan) drawCenteredText(`"${config.slogan}"`, fontRegular, 9, rgb(0.4, 0.4, 0.4));

  yPos -= 5;
  drawCenteredText(config.address, fontRegular, 9);
  drawCenteredText(`Tel: ${config.phone}`, fontRegular, 9);
  if (config.email) drawCenteredText(config.email, fontRegular, 8);
  if (config.website) drawCenteredText(config.website, fontRegular, 8);
  if (config.rfc) drawCenteredText(`RFC: ${config.rfc}`, fontRegular, 9);

  yPos -= 5;
  drawDashedLine();

  // --- META INFO ---
  drawLeftRight('Folio:', sale.id, fontRegular, 10, true);
  drawLeftRight('Fecha:', new Date(sale.timestamp).toLocaleDateString(), fontRegular, 10);
  drawLeftRight('Hora:', new Date(sale.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}), fontRegular, 10);
  drawLeftRight('Cliente:', sale.customerAlias.substring(0, is58mm ? 12 : 18), fontRegular, 10, true);

  yPos -= 5;

  // --- TABLE HEADER ---
  const headerSize = fs(8);
  page.drawRectangle({
    x: margin,
    y: yPos - 2,
    width: contentWidth,
    height: 14,
    color: accentColor, 
    opacity: 0.1
  });

  page.drawText('CANT', { x: margin + 5, y: yPos, size: headerSize, font: fontBold, color: accentColor });
  page.drawText('DESCRIPCION', { x: margin + (is58mm ? 35 : 45), y: yPos, size: headerSize, font: fontBold, color: accentColor });
  const impHeaderWidth = fontBold.widthOfTextAtSize('IMPORTE', headerSize);
  page.drawText('IMPORTE', { x: ticketWidth - margin - impHeaderWidth - 5, y: yPos, size: headerSize, font: fontBold, color: accentColor });
  yPos -= 18;

  // --- ITEMS ---
  const itemSize = fs(10);
  const descSize = fs(9);
  sale.items.forEach(item => {
    // Cantidad
    page.drawText(item.quantity.toString(), { x: margin + 8, y: yPos, size: itemSize, font: fontBold });

    // Descripción
    const cleanName = sanitize(item.name);
    const maxChars = is58mm ? 12 : 20;
    const name = cleanName.length > maxChars ? cleanName.substring(0, maxChars) + '...' : cleanName;
    page.drawText(name, { x: margin + (is58mm ? 35 : 45), y: yPos, size: descSize, font: fontRegular });

    // Importe
    const totalItem = (item.quantity * item.price).toFixed(2);
    const totalItemWidth = fontRegular.widthOfTextAtSize(`$${totalItem}`, itemSize);
    page.drawText(`$${totalItem}`, { x: ticketWidth - margin - totalItemWidth, y: yPos, size: itemSize, font: fontRegular });

    yPos -= 15;
  });

  drawDashedLine();

  // --- TOTALS ---
  const drawTotalLine = (label: string, value: string, isBig = false) => {
    const safeLabel = sanitize(label);
    const safeValue = sanitize(value);

    const size = isBig ? fs(16) : fs(10);
    const font = isBig ? fontBold : fontRegular;
    const color = isBig ? accentColor : rgb(0,0,0);

    const labelWidth = font.widthOfTextAtSize(safeLabel, size);
    const valueWidth = font.widthOfTextAtSize(safeValue, size);

    const valueX = ticketWidth - margin - valueWidth;
    const labelX = valueX - labelWidth - 10;

    page.drawText(safeLabel, { x: labelX, y: yPos, size, font, color });
    page.drawText(safeValue, { x: valueX, y: yPos, size, font, color });
    yPos -= (size + 8);
  };

  drawTotalLine('TOTAL:', `$${sale.total.toFixed(2)}`, true);

  if (sale.paymentSplits && sale.paymentSplits.length > 0) {
     sale.paymentSplits.forEach(split => {
        drawTotalLine(`${split.method}:`, `$${split.amount.toFixed(2)}`);
     });
  } else {
     drawTotalLine('Su Pago:', `$${sale.paidAmount.toFixed(2)}`);
  }

  if (sale.change > 0) {
    drawTotalLine('Cambio:', `$${sale.change.toFixed(2)}`);
  } else if (sale.paidAmount < sale.total) {
    // Background for Debt warning
    page.drawRectangle({
        x: margin,
        y: yPos - 8,
        width: contentWidth,
        height: 20,
        color: accentColor,
    });

    page.drawText('SALDO PENDIENTE', { x: margin + 5, y: yPos + 2, size: fs(10), font: fontBold, color: rgb(1,1,1) });
    const debtStr = `$${(sale.total - sale.paidAmount).toFixed(2)}`;
    const debtW = fontBold.widthOfTextAtSize(debtStr, fs(10));
    page.drawText(debtStr, { x: ticketWidth - margin - debtW - 5, y: yPos + 2, size: fs(10), font: fontBold, color: rgb(1,1,1) });
    yPos -= 25;
  }

  // --- GARRAFONES RETURNED ---
  if (sale.emptyGarrafonsReturned > 0) {
    yPos -= 5;
    page.drawRectangle({
      x: margin + 10,
      y: yPos - 5,
      width: contentWidth - 20,
      height: 25,
      borderColor: accentColor,
      borderWidth: 1,
    });
    const text = `* ${sale.emptyGarrafonsReturned} Envases Recibidos *`;
    const textW = fontBold.widthOfTextAtSize(text, fs(10));
    page.drawText(text, { x: centerX - (textW/2), y: yPos + 5, size: fs(10), font: fontBold, color: accentColor });
    yPos -= 25;
  }

  // --- FOOTER & QR CODE ---
  if (config.showFooter !== false) {
      yPos -= 10;
      const footerSize = fs(9);

      if (config.footerMessage) {
        const words = sanitize(config.footerMessage).split(' ');
        let line = '';
        for (const word of words) {
            const testLine = line + word + ' ';
            const testWidth = fontRegular.widthOfTextAtSize(testLine, footerSize);
            if (testWidth > contentWidth) {
                drawCenteredText(line, fontRegular, footerSize);
                line = word + ' ';
            } else {
                line = testLine;
            }
        }
        drawCenteredText(line, fontRegular, footerSize);
      }

      if (config.extraNote) {
        drawCenteredText(sanitize(config.extraNote), fontRegular, fs(8), rgb(0.5, 0.5, 0.5));
      }

      drawCenteredText('*** GRACIAS POR SU PREFERENCIA ***', fontBold, footerSize);
  }

  // QR Code at the bottom
  if (config.showQr !== false) {
      yPos -= 10;
      try {
        const qrData = btoa(`AQUA-PRO-SECURE|${JSON.stringify({ id: sale.id, total: sale.total })}`);
        const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(qrData)}`;

        // Fetch image data
        const qrResponse = await fetch(qrUrl);
        const qrArrayBuffer = await qrResponse.arrayBuffer();
        const qrImage = await pdfDoc.embedPng(qrArrayBuffer);

        const qrSize = is58mm ? 80 : 100;

        page.drawImage(qrImage, {
            x: centerX - (qrSize / 2),
            y: yPos - qrSize,
            width: qrSize,
            height: qrSize
        });
      } catch (e) {
        console.warn("Could not embed QR code in PDF", e);
        // Draw placeholder
        yPos -= 20;
        drawCenteredText('[ CODIGO QR NO DISPONIBLE ]', fontCourier, 8);
      }
  }

  return await pdfDoc.save();
}

export type ViewType = 'dashboard' | 'pos' | 'orders' | 'logistics' | 'production' | 'sync' | 'whatsapp' | 'customers' | 'employees' | 'reports' | 'settings' | 'quality' | 'scanner' | 'inventory' | 'tickets' | 'supplies' | 'messages';

export interface Product {
  id: string;
  name: string;
  price: number;
  stock: number;
  category?: 'Agua' | 'Insumos' | 'Accesorios';
  lastUpdated?: number;
}

export type GarrafonType = 'Aqua' | 'Bonafont' | 'Ciel' | 'E-Pura' | 'Generico';

export interface Customer {
  id: string;
  name: string;
  alias: string;
  address?: string; 
  phone?: string;
  specialPrice?: number;
  lat?: number;
  lng?: number;
  garrafonType?: GarrafonType;
  jugsOnLoan?: number; 
  balance: number;
  lastUpdated?: number;
}

export interface TicketConfig {
  businessName: string;
  rfc: string;
  address: string;
  phone: string;
  footerMessage: string;
  logoUrl?: string;
  website?: string;
  socialMedia?: string;
  extraNote?: string;
  slogan?: string;
  email?: string;
  colorHex?: string; 
  paperWidth?: '58mm' | '80mm';
  showLogo?: boolean;
  showQr?: boolean;
  showFooter?: boolean;
}

export interface ProcessStep {
  stage: string;
  process: string;
  time: number; // Seconds
}

export interface ProductionConfig {
  backwashSequence: ProcessStep[];
  regenerationSequence: ProcessStep[];
}

export interface CloudConfig {
  url: string;
  apiKey: string;
  autoSync: boolean;
  lastSync?: number;
}

export interface Order {
  id: string;
  customerId: string;
  customerAlias: string;
  items: CartItem[];
  total: number;
  status: 'pendiente' | 'asignado' | 'entregado' | 'cancelado';
  vehicleId?: string;
  timestamp: number;
  priority: number;
  deviceId?: string; 
  lastUpdated?: number; // Crucial for sync conflict resolution
}

export interface CartItem extends Product {
  quantity: number;
}

export type PaymentMethod = 'Efectivo' | 'Transferencia' | 'Tarjeta' | 'Crédito' | 'Multimodal';

export interface PaymentSplit {
  method: 'Efectivo' | 'Transferencia' | 'Tarjeta';
  amount: number;
}

export interface Sale {
  id: string;
  timestamp: number;
  customerId: string;
  customerAlias: string;
  items: CartItem[];
  total: number;
  paidAmount: number;
  change: number;
  paymentSplits: PaymentSplit[];
  emptyGarrafonsReturned: number;
  synced: boolean;
  deviceId?: string; 
}

export interface QualityRecord {
  id: string;
  timestamp: number;
  type: 'Cruda' | 'Producto';
  ph: number;
  cloro: number;
  tds: number;
  dureza: number;
  color: string;
  sabor: string;
  turbiedad: string;
  employeeId: string;
}

export interface Task {
  id: string;
  employeeId: string;
  title: string;
  description?: string;
  status: 'pendiente' | 'completada';
  timestamp: number;
  date: string;
  deviceId?: string; 
  lastUpdated?: number;
}

export interface Attendance {
  id: string;
  employeeId: string;
  timestamp: number;
  date: string;
  status: 'presente' | 'falta' | 'retardo';
}

export type Role = 'Repartidor' | 'Planta' | 'Administrador';

export interface Employee {
  id: string;
  name: string;
  roles: Role[]; 
  phone: string;
  pin: string;
  permissions: ViewType[];
  lastUpdated?: number;
}

export interface FuelRecord {
  id: string;
  date: number;
  mileage: number;
  liters: number;
  cost: number;
  notes?: string;
}

export interface Vehicle {
  id: string;
  plate: string;
  description: string;
  loadCapacity: number;
  currentLoad: number;
  inventory: CartItem[]; 
  fuelHistory: FuelRecord[]; 
  lastUpdated?: number;
}

export interface SavedReport {
  id: string;
  timestamp: number;
  rangeType: 'day' | 'week' | 'month';
  dateLabel: string; 
  totalGross: number;
  totalTransactions: number;
  averageTicket: number;
  payments: { cash: number, transfer: number, card: number };
  topProducts: { name: string, qty: number, total: number }[];
  notes?: string;
}

export interface Message {
  id: string;
  text: string;
  senderId: string;
  receiverId: string; 
  timestamp: number;
  read: boolean;
}

import React, { useState, useEffect } from 'react';
import { Product, Customer, CartItem, PaymentSplit, Sale, Employee, TicketConfig, Order } from '../types';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';
import html2canvas from 'html2canvas';
import { Filesystem, Directory } from '@capacitor/filesystem';
import { Share } from '@capacitor/share';
import { generateTicketPDF } from '../services/pdfGenerator';

// Helper to convert Uint8Array to Base64
const uint8ArrayToBase64 = (bytes: Uint8Array) => {
    let binary = '';
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) {
        binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
}

const TicketModal = ({ sale, config, onClose, onWhatsApp, onNewSale, onFinish }: any) => {
  const [sharing, setSharing] = useState(false);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved' | 'error'>('idle');
  const qrData = btoa(`AQUA-PRO-SECURE|${JSON.stringify({ id: sale.id, total: sale.total })}`);
  const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(qrData)}`;

  // Auto-save logic restored
  const handleAutoSave = async () => {
    try {
      setSaveStatus('saving');
      const element = document.getElementById('printable-ticket');
      if (!element) return;

      const canvas = await html2canvas(element, { scale: 2, backgroundColor: '#ffffff', logging: false });
      const base64Data = canvas.toDataURL('image/png').split(',')[1];
      const folderName = 'AquaTickets';
      const fileName = `Ticket_${sale.id}_${Date.now()}.png`;

      try {
        await Filesystem.mkdir({ path: folderName, directory: Directory.Documents, recursive: true });
        await Filesystem.writeFile({ path: `${folderName}/${fileName}`, data: base64Data, directory: Directory.Documents });
        setSaveStatus('saved');
      } catch (fsError) {
        console.warn("Auto-save skipped (Web mode)", fsError);
        setSaveStatus('error');
      }
    } catch (e) {
      console.error("Error generating image", e);
      setSaveStatus('error');
    }
  };

  useEffect(() => { setTimeout(handleAutoSave, 800); }, []);

  const handleSharePDF = async () => {
    setSharing(true);
    try {
        const pdfBytes = await generateTicketPDF(sale, config);
        const base64Content = uint8ArrayToBase64(pdfBytes);
        const fileName = `Ticket_${sale.id}.pdf`;

        const savedFile = await Filesystem.writeFile({
          path: fileName,
          data: base64Content,
          directory: Directory.Cache
        });

        await Share.share({
            title: `Ticket ${sale.id}`,
            text: `Hola ${sale.customerAlias}, adjunto tu ticket de compra en Aqua+.`,
            url: savedFile.uri,
            dialogTitle: 'Compartir Ticket'
        });
    } catch (e) {
        console.error(e);
        // Fallback Web
        try {
            const pdfBytes = await generateTicketPDF(sale, config);
            const file = new File([pdfBytes], `Ticket_${sale.id}.pdf`, { type: 'application/pdf' });
            const url = URL.createObjectURL(file);
            const link = document.createElement('a');
            link.href = url;
            link.download = file.name;
            link.click();
            setTimeout(() => URL.revokeObjectURL(url), 1000);
        } catch(webErr) {
            alert("No se pudo compartir.");
        }
    } finally {
        setSharing(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[300] bg-slate-900/80 backdrop-blur-md flex flex-col items-center justify-center p-4 animate-fadeIn">
      <div className="bg-white w-full max-w-[340px] max-h-[85vh] shadow-2xl rounded-[2.5rem] overflow-hidden flex flex-col relative">
        <div className="absolute top-0 left-0 right-0 h-1.5 bg-gradient-to-r from-sky-400 via-indigo-500 to-sky-400"></div>

        {saveStatus === 'saved' && (
          <div className="absolute top-3 right-4 bg-emerald-100 text-emerald-600 px-2 py-0.5 rounded-full text-[8px] font-black uppercase flex items-center gap-1 animate-fadeIn z-20">
            <i className="fas fa-check-circle"></i> Guardado
          </div>
        )}

        <div className="overflow-y-auto flex-1 p-6 pb-2 text-center font-mono text-slate-800 leading-tight text-xs relative custom-scrollbar" id="printable-ticket">
            {config.logoUrl && <img src={config.logoUrl} alt="Logo" className="w-20 h-20 object-contain mx-auto mb-3 grayscale mix-blend-multiply" />}
            <h2 className="text-lg font-black uppercase mb-1 tracking-tighter text-sky-900">{config.businessName}</h2>

            <div className="border-b-2 border-dashed border-slate-200 pb-3 mb-3 space-y-0.5 text-slate-500">
              <p>{new Date(sale.timestamp).toLocaleString()}</p>
              <p>Folio: {sale.id}</p>
            </div>

            <table className="w-full mb-3 border-collapse">
              <thead>
                <tr className="border-b border-slate-900">
                  <th className="text-left py-1 w-8">Cant</th>
                  <th className="text-left py-1">Desc</th>
                  <th className="text-right py-1">Total</th>
                </tr>
              </thead>
              <tbody>
                {sale.items.map((item: any, i: number) => (
                  <tr key={i}>
                    <td className="text-left py-1 align-top font-bold">{item.quantity}</td>
                    <td className="text-left py-1 align-top">{item.name.slice(0, 18)}</td>
                    <td className="text-right py-1 align-top">${(item.quantity * item.price).toFixed(2)}</td>
                  </tr>
                ))}
              </tbody>
            </table>

            <div className="border-t-2 border-slate-900 pt-2 mb-2 text-right">
              <p className="text-xl font-black">TOTAL: ${sale.total.toFixed(2)}</p>
            </div>

            <div className="flex flex-col items-center pb-2 mt-4">
              <img src={qrUrl} alt="QR" className="w-16 h-16 mb-1 mix-blend-multiply opacity-80" />
              <p className="text-[8px] uppercase font-bold text-slate-400">Gracias por su compra</p>
            </div>
        </div>

        <div className="bg-slate-50 p-4 border-t border-slate-100 shrink-0 space-y-3 z-20">
             <div className="grid grid-cols-2 gap-3">
                <button onClick={handleSharePDF} disabled={sharing} className="bg-indigo-600 text-white py-3 rounded-2xl font-black text-[10px] uppercase shadow-lg shadow-indigo-200 active:scale-95 transition-transform flex items-center justify-center gap-2">
                    {sharing ? <i className="fas fa-spinner animate-spin"></i> : <i className="fas fa-share-nodes"></i>} Compartir
                </button>
                <button onClick={onWhatsApp} className="bg-emerald-500 text-white py-3 rounded-2xl font-black text-[10px] uppercase shadow-lg shadow-emerald-200 active:scale-95 transition-transform flex items-center justify-center gap-2">
                    <i className="fab fa-whatsapp"></i> WhatsApp
                </button>
             </div>
             <button onClick={onNewSale} className="w-full bg-sky-500 text-white py-3 rounded-2xl font-black text-[10px] uppercase shadow-lg shadow-sky-200 active:scale-95 transition-transform">
                Nueva Venta
             </button>
             <button onClick={onFinish} className="w-full text-slate-400 text-[10px] font-bold uppercase hover:text-rose-400 transition-colors">Cerrar</button>
        </div>
      </div>
    </div>
  );
};

const PaymentModal = ({ total, onConfirm, onCancel }: any) => {
  const [cash, setCash] = useState('');
  const [transfer, setTransfer] = useState('');
  const [card, setCard] = useState('');
  const numCash = parseFloat(cash) || 0;
  const numTransfer = parseFloat(transfer) || 0;
  const numCard = parseFloat(card) || 0;

  const totalPaid = numCash + numTransfer + numCard;
  const remaining = total - totalPaid;
  const isComplete = totalPaid >= (total - 0.01);

  return (
    <div className="fixed inset-0 z-[150] bg-slate-900/80 backdrop-blur-sm flex items-end sm:items-center justify-center animate-fadeIn">
      <div className="bg-white w-full max-w-md rounded-t-[2.5rem] sm:rounded-[2.5rem] p-8 shadow-2xl max-h-[90vh] overflow-y-auto no-scrollbar">
         <div className="flex justify-between items-center mb-6">
            <h3 className="text-xl font-black text-slate-800">Método de Pago</h3>
            <button onClick={onCancel} className="w-10 h-10 bg-slate-100 rounded-full text-slate-400 hover:bg-slate-200 transition-colors"><i className="fas fa-times"></i></button>
         </div>

         <div className="text-center mb-6">
            <p className="text-xs font-bold uppercase text-slate-400 tracking-widest mb-1">Total a Cobrar</p>
            <p className="text-5xl font-black text-slate-800 tracking-tighter">${total.toFixed(2)}</p>
         </div>

         <div className="space-y-3 mb-8">
            <div className="bg-slate-50 p-4 rounded-[1.5rem] flex items-center gap-4 border border-slate-100 focus-within:ring-2 ring-emerald-400 transition-all">
               <div className="w-12 h-12 bg-white rounded-2xl flex items-center justify-center text-emerald-500 shadow-sm text-xl"><i className="fas fa-money-bill-wave"></i></div>
               <div className="flex-1">
                  <label className="text-[9px] font-black uppercase text-slate-400 block mb-1">Efectivo</label>
                  <input type="number" placeholder="0.00" className="w-full bg-transparent font-black text-xl text-slate-800 outline-none placeholder-slate-300" value={cash} onChange={e => setCash(e.target.value)} autoFocus />
               </div>
            </div>

            <div className="bg-slate-50 p-4 rounded-[1.5rem] flex items-center gap-4 border border-slate-100 focus-within:ring-2 ring-indigo-400 transition-all">
               <div className="w-12 h-12 bg-white rounded-2xl flex items-center justify-center text-indigo-500 shadow-sm text-xl"><i className="fas fa-building-columns"></i></div>
               <div className="flex-1">
                  <label className="text-[9px] font-black uppercase text-slate-400 block mb-1">Transferencia</label>
                  <input type="number" placeholder="0.00" className="w-full bg-transparent font-black text-xl text-slate-800 outline-none placeholder-slate-300" value={transfer} onChange={e => setTransfer(e.target.value)} />
               </div>
            </div>

            <div className="bg-slate-50 p-4 rounded-[1.5rem] flex items-center gap-4 border border-slate-100 focus-within:ring-2 ring-purple-400 transition-all">
               <div className="w-12 h-12 bg-white rounded-2xl flex items-center justify-center text-purple-500 shadow-sm text-xl"><i className="fas fa-credit-card"></i></div>
               <div className="flex-1">
                  <label className="text-[9px] font-black uppercase text-slate-400 block mb-1">Tarjeta (T. Crédito/Débito)</label>
                  <input type="number" placeholder="0.00" className="w-full bg-transparent font-black text-xl text-slate-800 outline-none placeholder-slate-300" value={card} onChange={e => setCard(e.target.value)} />
               </div>
            </div>
         </div>

         <ActionButton onClick={() => onConfirm(numCash, numTransfer, numCard)} variant={isComplete ? 'primary' : 'secondary'}>
            {isComplete ? 'Confirmar Cobro' : `Restan $${remaining.toFixed(2)}`}
         </ActionButton>
      </div>
    </div>
  );
};

export const POSModule: React.FC<{ onBack: () => void; user: Employee; initialOrder?: Order | null; onClearInitialOrder?: () => void; }> = ({ onBack, user, initialOrder, onClearInitialOrder }) => {
  const { products, customers, sales, addSale, ticketConfig, vehicles, updateOrder } = useERPData();
  const [activeTab, setActiveTab] = useState<'sell' | 'history'>('sell');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [customer, setCustomer] = useState<Customer | null>(null);
  const [search, setSearch] = useState('');
  const [vacios, setVacios] = useState(0);
  const [selectedSource, setSelectedSource] = useState<string>('plant');
  const [showPaymentModal, setShowPaymentModal] = useState(false);
  const [viewingTicket, setViewingTicket] = useState<Sale | null>(null);
  const [linkedOrderId, setLinkedOrderId] = useState<string | null>(null);
  const [originalOrder, setOriginalOrder] = useState<Order | null>(null);

  useEffect(() => {
    if (initialOrder) {
      let client = customers.find(c => c.id === initialOrder.customerId);
      if (!client) {
         client = { id: initialOrder.customerId, name: initialOrder.customerAlias, alias: initialOrder.customerAlias, balance: 0, phone: '', garrafonType: 'Generico' } as Customer;
      }
      setCustomer(client);
      setSearch(client.alias);
      setCart(initialOrder.items);
      if (initialOrder.vehicleId && vehicles.some(v => v.id === initialOrder.vehicleId)) setSelectedSource(initialOrder.vehicleId);
      setLinkedOrderId(initialOrder.id);
      setOriginalOrder(initialOrder);
      if (onClearInitialOrder) onClearInitialOrder();
    }
  }, [initialOrder, customers, vehicles, onClearInitialOrder]);

  const total = cart.reduce((sum, item) => {
    const price = (customer?.specialPrice && item.id === '1') ? customer.specialPrice : item.price;
    return sum + (price * item.quantity);
  }, 0);

  useEffect(() => {
    const garrafonesInCart = cart.filter(i => i.name.toLowerCase().includes('garraf') || i.category === 'Agua').reduce((acc, i) => acc + i.quantity, 0);
    if (cart.length > 0 && vacios === 0) setVacios(garrafonesInCart);
    else if (cart.length === 0) setVacios(0);
  }, [cart]);

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === product.id);
      if (existing) return prev.map(i => i.id === product.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const decreaseQuantity = (productId: string) => {
    setCart(prev => prev.map(item => item.id === productId ? { ...item, quantity: Math.max(0, item.quantity - 1) } : item).filter(item => item.quantity > 0));
  };

  const handlePreCheckout = () => {
    if (!customer) return alert("Selecciona un cliente.");
    if (cart.length === 0) return alert("Carrito vacío.");

    // VALIDACIÓN DE STOCK (Solo si es vehículo)
    if (selectedSource !== 'plant') {
        const vehicle = vehicles.find(v => v.id === selectedSource);
        if (vehicle) {
            const currentInv = vehicle.inventory || [];

            const missing = cart.filter(item => {
                const stockItem = currentInv.find(i => i.id === item.id);
                // Es nulo si no existe el item o si la cantidad es menor a la requerida
                return !stockItem || stockItem.quantity < item.quantity;
            });

            if (missing.length > 0) {
                const names = missing.map(m => `- ${m.name}`).join('\n');
                const confirmSale = window.confirm(
                    `⚠️ STOCK INSUFICIENTE EN UNIDAD\n\n` +
                    `El vehículo no tiene carga suficiente de:\n${names}\n\n` +
                    `¿Deseas forzar la venta (Stock Negativo)?`
                );
                if (!confirmSale) return;
            }
        }
    }

    setShowPaymentModal(true);
  };

  const handleConfirmPayment = (cash: number, transfer: number, card: number) => {
    if(!customer) return;
    const totalPaid = cash + transfer + card;
    const splits: PaymentSplit[] = [];
    if (cash > 0) splits.push({ method: 'Efectivo', amount: cash });
    if (transfer > 0) splits.push({ method: 'Transferencia', amount: transfer });
    if (card > 0) splits.push({ method: 'Tarjeta', amount: card });

    // La validación principal ya se hizo en handlePreCheckout
    // Aquí solo procesamos la venta (incluso si genera negativo)
    const sale = addSale(customer.id, cart, total, totalPaid, splits, vacios, undefined, selectedSource === 'plant' ? undefined : selectedSource);

    if (originalOrder) {
       updateOrder({ ...originalOrder, status: 'entregado' });
    }

    setShowPaymentModal(false);
    setViewingTicket(sale);
  };

  const resetPOS = () => {
    setViewingTicket(null);
    setCart([]);
    setCustomer(null);
    setSearch('');
    setVacios(0);
    setLinkedOrderId(null);
    setOriginalOrder(null);
    setActiveTab('sell');
  };

  return (
    <div className="h-full flex flex-col animate-fadeIn bg-transparent pb-24 overflow-hidden relative">
      <ModuleHeader title="Punto de Venta" onBack={onBack} />

      <div className="px-6 flex gap-2 mb-4 shrink-0">
        <button onClick={() => setActiveTab('sell')} className={`flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'sell' ? 'bg-sky-600 text-white shadow-lg' : 'bg-white text-slate-400'}`}>Venta</button>
        <button onClick={() => setActiveTab('history')} className={`flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'history' ? 'bg-sky-600 text-white shadow-lg' : 'bg-white text-slate-400'}`}>Historial</button>
      </div>

      {activeTab === 'sell' ? (
        <div className="flex-1 overflow-y-auto px-6 space-y-6 pb-32 no-scrollbar">

          {linkedOrderId && (
            <div className="bg-amber-100 text-amber-700 p-4 rounded-[1.5rem] border border-amber-200 flex justify-between items-center shadow-sm">
               <span className="text-xs font-black uppercase tracking-wide flex items-center gap-2"><i className="fas fa-clipboard-check"></i> Pedido: {linkedOrderId}</span>
               <button onClick={resetPOS} className="w-8 h-8 bg-white rounded-full text-amber-500 flex items-center justify-center shadow-sm active:scale-90 transition-transform"><i className="fas fa-times"></i></button>
            </div>
          )}

          <div className="overflow-x-auto pb-2 no-scrollbar">
            <div className="flex gap-2 min-w-max">
              <button 
                onClick={() => setSelectedSource('plant')}
                className={`px-5 py-3 rounded-2xl text-[10px] font-black uppercase flex items-center gap-2 transition-all ${selectedSource === 'plant' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-200' : 'bg-white text-slate-400 border border-slate-100'}`}
              >
                <i className="fas fa-store"></i> Planta
              </button>
              {vehicles.map(v => (
                <button 
                  key={v.id}
                  onClick={() => setSelectedSource(v.id)}
                  className={`px-5 py-3 rounded-2xl text-[10px] font-black uppercase flex items-center gap-2 transition-all ${selectedSource === v.id ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-200' : 'bg-white text-slate-400 border border-slate-100'}`}
                >
                  <i className="fas fa-truck"></i> {v.plate}
                </button>
              ))}
            </div>
          </div>

          <div className="relative z-20">
            <input type="text" placeholder="Buscar Cliente..." className="w-full bg-white border-none rounded-[1.5rem] py-4 px-6 shadow-sm outline-none font-bold text-slate-700 placeholder-slate-300 focus:ring-2 ring-sky-300 transition-all" value={search} onChange={e => setSearch(e.target.value)} />
            {search && !customer && (
              <div className="absolute top-full left-0 right-0 bg-white shadow-xl rounded-[1.5rem] mt-2 overflow-hidden border border-slate-100 max-h-48 overflow-y-auto z-50">
                {customers.filter(c => c.alias.toLowerCase().includes(search.toLowerCase())).map(c => (
                  <button key={c.id} onClick={() => { setCustomer(c); setSearch(c.alias); }} className="w-full text-left p-4 hover:bg-sky-50 border-b border-slate-50 last:border-none">
                    <span className="text-slate-800 font-bold text-sm block">{c.alias}</span>
                  </button>
                ))}
              </div>
            )}
            {customer && (
              <div className="mt-2 bg-white p-3 rounded-[1.5rem] shadow-sm border border-sky-100 flex justify-between items-center animate-fadeIn">
                <div className="flex items-center gap-3">
                   <div className="w-10 h-10 bg-sky-100 rounded-full flex items-center justify-center text-sky-600"><i className="fas fa-user-check"></i></div>
                   <span className="font-black text-slate-800 text-sm">{customer.alias}</span>
                </div>
                <button onClick={() => {setCustomer(null); setSearch('');}} className="w-8 h-8 flex items-center justify-center text-rose-400 bg-rose-50 rounded-full hover:bg-rose-100 transition-colors"><i className="fas fa-times"></i></button>
              </div>
            )}
          </div>

          <div className="grid grid-cols-2 gap-3">
            {products.filter(p => p.category !== 'Insumos').map(p => {
               const inCart = cart.find(i => i.id === p.id)?.quantity || 0;
               return (
                <button key={p.id} onClick={() => addToCart(p)} className={`p-4 rounded-[1.8rem] text-left transition-all relative overflow-hidden group ${inCart > 0 ? 'bg-gradient-to-br from-sky-500 to-indigo-600 text-white shadow-lg shadow-sky-300' : 'bg-white text-slate-600 shadow-sm border border-white'}`}>
                  <div className="relative z-10">
                    <p className={`text-[9px] font-black uppercase mb-1 tracking-wide ${inCart > 0 ? 'text-sky-100' : 'text-slate-400'}`}>{p.category}</p>
                    <h4 className="font-bold text-sm leading-tight mb-2 pr-4">{p.name.replace('Garrafón', 'G.')}</h4>
                    <p className="text-lg font-black">${p.price}</p>
                  </div>
                  {inCart > 0 && (
                    <div className="absolute top-3 right-3 w-8 h-8 bg-white text-sky-600 rounded-full flex items-center justify-center font-black text-sm shadow-sm animate-bounce">
                      {inCart}
                    </div>
                  )}
                  <div className={`absolute -bottom-4 -right-4 w-16 h-16 rounded-full ${inCart > 0 ? 'bg-white/10' : 'bg-slate-50'} blur-xl`}></div>
                </button>
               );
            })}
          </div>

          {cart.length > 0 && (
            <div className="bg-white rounded-[2rem] p-5 shadow-lg shadow-slate-100/50 border border-white animate-slideUp">
               <div className="flex justify-between items-center mb-4">
                  <h4 className="text-xs font-black text-slate-400 uppercase tracking-widest">Resumen</h4>
                  <button onClick={() => setCart([])} className="text-[10px] text-rose-500 font-bold uppercase hover:underline">Vaciar Carrito</button>
               </div>

               <div className="space-y-2 mb-6">
                 {cart.map(i => (
                   <div key={i.id} className="flex justify-between items-center py-2 border-b border-slate-50 last:border-none">
                      <div className="flex items-center gap-3">
                         <div className="flex items-center gap-2 bg-slate-50 rounded-xl p-1">
                            <button onClick={() => decreaseQuantity(i.id)} className="w-7 h-7 flex items-center justify-center bg-white rounded-lg shadow-sm text-slate-400 font-bold hover:text-sky-500 transition-colors">-</button>
                            <span className="text-xs font-black w-5 text-center text-slate-700">{i.quantity}</span>
                            <button onClick={() => addToCart(i)} className="w-7 h-7 flex items-center justify-center bg-sky-500 text-white rounded-lg shadow-sm font-bold hover:bg-sky-600 transition-colors">+</button>
                         </div>
                         <span className="text-xs font-bold text-slate-700 truncate max-w-[120px]">{i.name}</span>
                      </div>
                      <span className="text-sm font-black text-slate-800">${(( (customer?.specialPrice && i.id === '1') ? customer.specialPrice : i.price ) * i.quantity).toFixed(2)}</span>
                   </div>
                 ))}
               </div>

               <div className="bg-slate-50 p-4 rounded-[1.5rem] flex justify-between items-center mb-2">
                  <span className="text-[10px] font-bold text-slate-500 uppercase tracking-wide">Envases Vacíos Recibidos</span>
                  <div className="flex items-center gap-3">
                     <button onClick={() => setVacios(Math.max(0, vacios - 1))} className="w-8 h-8 bg-white rounded-full shadow-sm text-slate-400 font-bold hover:text-sky-500">-</button>
                     <span className="font-black text-slate-800 text-lg">{vacios}</span>
                     <button onClick={() => setVacios(vacios + 1)} className="w-8 h-8 bg-sky-500 rounded-full shadow-lg shadow-sky-200 text-white font-bold hover:bg-sky-600 active:scale-90 transition-transform">+</button>
                  </div>
               </div>
            </div>
          )}
        </div>
      ) : (
        <div className="flex-1 overflow-y-auto px-6 space-y-3 pb-10 no-scrollbar">
           {sales.map(s => (
             <RoundedCard key={s.id} className="p-4 flex justify-between items-center">
                <div className="flex items-center gap-4">
                   <div className="w-12 h-12 bg-slate-100 rounded-2xl flex items-center justify-center text-slate-400 text-lg">
                      <i className="fas fa-receipt"></i>
                   </div>
                   <div>
                      <h4 className="font-black text-slate-800 text-sm">{s.customerAlias}</h4>
                      <p className="text-[10px] text-slate-400 font-bold uppercase">{new Date(s.timestamp).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}</p>
                   </div>
                </div>
                <div className="text-right">
                   <span className="block font-black text-slate-800 text-lg">${s.total}</span>
                   <button onClick={() => setViewingTicket(s)} className="text-[10px] text-sky-500 font-bold uppercase bg-sky-50 px-3 py-1 rounded-lg mt-1 active:bg-sky-100">Ver Ticket</button>
                </div>
             </RoundedCard>
           ))}
        </div>
      )}

      {activeTab === 'sell' && (
        <div className="fixed bottom-0 left-0 right-0 p-6 bg-white/80 backdrop-blur-md border-t border-white/50 shadow-[0_-10px_30px_rgba(0,0,0,0.05)] z-50">
          <ActionButton onClick={handlePreCheckout} disabled={!customer || cart.length === 0}>
             <div className="flex justify-between w-full px-4 items-center">
                <span>{linkedOrderId ? 'Finalizar Entrega' : 'Cobrar'}</span>
                <span className="bg-white/20 px-3 py-1 rounded-xl text-sm font-black backdrop-blur-sm shadow-sm">${total.toFixed(2)}</span>
             </div>
          </ActionButton>
        </div>
      )}

      {showPaymentModal && <PaymentModal total={total} onConfirm={handleConfirmPayment} onCancel={() => setShowPaymentModal(false)} />}

      {viewingTicket && (
        <TicketModal 
          sale={viewingTicket} 
          config={ticketConfig} 
          onClose={() => setViewingTicket(null)} 
          onWhatsApp={() => {
             const phone = customers.find(c => c.id === viewingTicket.customerId)?.phone;
             if(phone) window.open(`https://wa.me/52${phone.replace(/\D/g,'')}?text=Hola, adjunto tu ticket ${viewingTicket.id}. Total: $${viewingTicket.total}`, '_blank');
             else alert("Sin teléfono registrado");
          }}
          onNewSale={resetPOS}
          onFinish={() => { setViewingTicket(null); setActiveTab('history'); }}
        />
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';
import { Product, CartItem, PaymentSplit, Sale, TicketConfig, Customer } from '../types';
import html2canvas from 'html2canvas';
import { Filesystem, Directory } from '@capacitor/filesystem';
import { Share } from '@capacitor/share';
import { generateTicketPDF } from '../services/pdfGenerator';

// Helper to convert Uint8Array to Base64
const uint8ArrayToBase64 = (bytes: Uint8Array) => {
    let binary = '';
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) {
        binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
}

// Componente Interno del Visualizador de Ticket
const TicketViewerModal = ({ sale, config, onClose }: { sale: Sale, config: TicketConfig, onClose: () => void }) => {
  const [sharing, setSharing] = useState(false);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved' | 'error'>('idle');
  const qrData = btoa(`AQUA-PRO-SECURE|${JSON.stringify({ id: sale.id, total: sale.total })}`);
  const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(qrData)}`;

  // Custom Color Logic
  const accentColor = config.colorHex || '#0284c7';

  // Auto-save effect (Imagen PNG)
  useEffect(() => {
    const timer = setTimeout(() => {
      handleAutoSaveImage();
    }, 800); // Wait for render
    return () => clearTimeout(timer);
  }, []);

  const handleAutoSaveImage = async () => {
    try {
      setSaveStatus('saving');
      const element = document.getElementById('printable-area');
      if (!element) return;

      const canvas = await html2canvas(element, { 
        scale: 2, 
        backgroundColor: '#ffffff',
        logging: false 
      });

      const base64Data = canvas.toDataURL('image/png');
      const base64Content = base64Data.split(',')[1];

      const folderName = 'AquaTickets';
      const fileName = `Ticket_${sale.id}_${Date.now()}.png`;

      try {
        await Filesystem.mkdir({
            path: folderName,
            directory: Directory.Documents,
            recursive: true
        });

        await Filesystem.writeFile({
          path: `${folderName}/${fileName}`,
          data: base64Content,
          directory: Directory.Documents
        });
        setSaveStatus('saved');
      } catch (fsError) {
        console.warn("Filesystem save failed (likely web browser), skipping auto-save to disk", fsError);
        setSaveStatus('error');
      }

    } catch (e) {
      console.error("Error generating image", e);
      setSaveStatus('error');
    }
  };

  const handleSavePDF = async () => {
    try {
      setSaveStatus('saving');
      const pdfBytes = await generateTicketPDF(sale, config);
      const base64Content = uint8ArrayToBase64(pdfBytes);

      const folderName = 'AquaTickets';
      const fileName = `Reporte_${sale.id}.pdf`;

      await Filesystem.mkdir({
          path: folderName,
          directory: Directory.Documents,
          recursive: true
      });

      await Filesystem.writeFile({
        path: `${folderName}/${fileName}`,
        data: base64Content,
        directory: Directory.Documents
      });

      setSaveStatus('saved');
      alert(`PDF Guardado en: Documentos/${folderName}/${fileName}`);

      if (!(window as any).Capacitor?.isNative) {
         const blob = new Blob([pdfBytes], { type: 'application/pdf' });
         const url = URL.createObjectURL(blob);
         const link = document.createElement('a');
         link.href = url;
         link.download = fileName;
         link.click();
         setTimeout(() => URL.revokeObjectURL(url), 1000);
      }

    } catch (e) {
      console.error("Error saving PDF", e);
      setSaveStatus('error');
      alert("Error al generar el PDF.");
    } finally {
      setTimeout(() => setSaveStatus('idle'), 2000);
    }
  };

  const handleSharePDF = async () => {
    setSharing(true);
    try {
        const pdfBytes = await generateTicketPDF(sale, config);
        const base64Content = uint8ArrayToBase64(pdfBytes);
        const fileName = `Ticket_${sale.id}.pdf`;

        const savedFile = await Filesystem.writeFile({
          path: fileName,
          data: base64Content,
          directory: Directory.Cache
        });

        await Share.share({
            title: `Ticket ${sale.id}`,
            text: `Hola ${sale.customerAlias}, adjunto tu ticket de compra.`,
            url: savedFile.uri,
            dialogTitle: 'Compartir Ticket'
        });

    } catch (e) {
        console.error(e);
        try {
            const pdfBytes = await generateTicketPDF(sale, config);
            const file = new File([pdfBytes], `Ticket_${sale.id}.pdf`, { type: 'application/pdf' });
            const url = URL.createObjectURL(file);
            const link = document.createElement('a');
            link.href = url;
            link.download = file.name;
            link.click();
            setTimeout(() => URL.revokeObjectURL(url), 1000);
            alert("Modo Web: Archivo descargado.");
        } catch(webErr) {
            alert("No se pudo compartir.");
        }
    } finally {
        setSharing(false);
    }
  };

  const handleNativeShareImage = async () => {
    setSharing(true);
    try {
      const element = document.getElementById('printable-area');
      if (!element) return;

      const canvas = await html2canvas(element, { 
        scale: 2, 
        backgroundColor: '#ffffff',
        logging: false 
      });

      const base64Data = canvas.toDataURL('image/png');
      const base64Content = base64Data.split(',')[1];
      const fileName = `Ticket_${sale.id}.png`;

      const savedFile = await Filesystem.writeFile({
          path: fileName,
          data: base64Content,
          directory: Directory.Cache
      });

      await Share.share({
          title: `Ticket ${sale.id}`,
          text: `Hola ${sale.customerAlias}, aquí tienes tu ticket.`,
          url: savedFile.uri,
          dialogTitle: 'Compartir Imagen'
      });

    } catch (e) {
      console.error(e);
      alert("Error al compartir imagen. Intenta guardarla primero.");
    } finally {
      setSharing(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[300] bg-slate-900/80 backdrop-blur-sm flex flex-col items-center justify-center p-4 animate-fadeIn">
      <button onClick={onClose} className="absolute top-6 right-6 w-12 h-12 bg-white/10 text-white rounded-full flex items-center justify-center hover:bg-white/20 active:scale-90 transition-all z-50 backdrop-blur-sm">
        <i className="fas fa-times text-xl"></i>
      </button>

      <div className="bg-white w-full max-w-[340px] max-h-[85vh] shadow-2xl rounded-3xl overflow-hidden flex flex-col relative print:w-full">
        {/* Efecto de papel */}
        <div className="absolute top-0 left-0 right-0 h-1 bg-[url('data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHdpZHRoPSIxMCIgaGVpZ2h0PSIxMCIgdmlld0JveD0iMCAwIDEwIDEwIj48cGF0aCBkPSJNTAgMTBMNSAwTDEwIDEwWiIgZmlsbD0iI2YzZjRZjYiLz48L3N2Zz4=')] opacity-50 z-10 pointer-events-none print:hidden"></div>

        {saveStatus === 'saved' && (
          <div className="absolute top-4 right-16 z-20 bg-emerald-100 text-emerald-600 px-2 py-1 rounded-full text-[8px] font-black uppercase flex items-center gap-1 animate-fadeIn">
            <i className="fas fa-check-circle"></i> Guardado en AquaTickets
          </div>
        )}

        <div className="overflow-y-auto flex-1 p-6 pb-2 text-center font-mono text-slate-900 leading-tight text-xs relative custom-scrollbar" id="printable-area">
            {config.logoUrl && <img src={config.logoUrl} alt="Logo" className="w-20 h-20 object-contain mx-auto mb-3 grayscale mix-blend-multiply" />}

            <h2 className="text-lg font-black uppercase mb-1 tracking-tighter" style={{ color: accentColor }}>{config.businessName}</h2>
            {config.slogan && <p className="text-[9px] italic mb-3 opacity-70">"{config.slogan}"</p>}

            <div className="border-b-2 border-dashed border-slate-300 pb-3 mb-3 space-y-0.5">
              <p>RFC: {config.rfc}</p>
              <p>{config.address}</p>
              <p>Tel: {config.phone}</p>
              {config.email && <p>{config.email}</p>}
              {config.website && <p>{config.website}</p>}
              <p>{new Date(sale.timestamp).toLocaleString()}</p>
            </div>

            <div className="text-left mb-3 space-y-1">
              <p>FOLIO: <span className="font-bold">{sale.id}</span></p>
              <p>CLIENTE: {sale.customerAlias.toUpperCase()}</p>
            </div>

            <table className="w-full mb-3 border-collapse">
              <thead>
                <tr className="border-b" style={{ borderColor: accentColor }}>
                  <th className="text-left py-1 w-8">CANT</th>
                  <th className="text-left py-1">DESC</th>
                  <th className="text-right py-1">IMP</th>
                </tr>
              </thead>
              <tbody>
                {sale.items.map((item, i) => (
                  <tr key={i}>
                    <td className="text-left py-1 align-top font-bold">{item.quantity}</td>
                    <td className="text-left py-1 align-top">{item.name.slice(0, 18)}</td>
                    <td className="text-right py-1 align-top">${(item.quantity * item.price).toFixed(2)}</td>
                  </tr>
                ))}
              </tbody>
            </table>

            <div className="border-t-2 pt-2 mb-2 text-right" style={{ borderColor: accentColor }}>
              <p className="text-xl font-black" style={{ color: accentColor }}>TOTAL: ${sale.total.toFixed(2)}</p>
            </div>

            <div className="text-right mb-4 space-y-0.5 text-[10px]">
              <p>SU PAGO: ${sale.paidAmount.toFixed(2)}</p>
              {sale.paidAmount < sale.total ? (
                  <p className="font-bold text-white inline-block px-1" style={{ backgroundColor: accentColor }}>PENDIENTE: ${(sale.total - sale.paidAmount).toFixed(2)}</p>
              ) : (
                  <p>CAMBIO: ${sale.change.toFixed(2)}</p>
              )}
            </div>

            {sale.emptyGarrafonsReturned > 0 && (
              <div className="border-2 p-2 mb-4 text-xs font-bold uppercase text-center" style={{ borderColor: accentColor, color: accentColor }}>
                  * {sale.emptyGarrafonsReturned} Envases Recibidos *
              </div>
            )}

            <div className="pt-2 mb-4 text-center opacity-80">
              <p className="font-bold mb-1">{config.footerMessage}</p>
              <p className="text-[8px] italic">{config.extraNote}</p>
            </div>

            <div className="flex flex-col items-center pb-2">
              <img src={qrUrl} alt="QR" className="w-20 h-20 mb-1 mix-blend-multiply" />
            </div>
        </div>

        <div className="bg-slate-100 p-4 border-t border-slate-200 shrink-0 print:hidden grid grid-cols-2 gap-3 z-20 relative">
             <button 
                onClick={handleSharePDF} 
                disabled={sharing}
                className="bg-indigo-600 text-white py-3 rounded-xl font-black uppercase text-[10px] flex items-center justify-center gap-2 active:scale-95 transition-transform shadow-lg shadow-indigo-200 col-span-2"
              >
                  {sharing ? <i className="fas fa-spinner animate-spin"></i> : <i className="fab fa-whatsapp"></i>}
                  Compartir PDF
              </button>

             <button 
                onClick={handleNativeShareImage} 
                disabled={sharing}
                className="bg-emerald-500 text-white py-3 rounded-xl font-black uppercase text-[10px] flex items-center justify-center gap-2 active:scale-95 transition-transform shadow-lg shadow-emerald-100"
              >
                  <i className="fas fa-image"></i> Imagen
