export const ReportsModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const { sales, savedReports, addSavedReport, deleteSavedReport, ticketConfig, tasks, employees, products, vehicles } = useERPData();
  const [activeTab, setActiveTab] = useState<'live' | 'history'>('live');
  const [reportType, setReportType] = useState<ReportType>('financial');
  const [timeRange, setTimeRange] = useState<TimeRange>('day');

  // Estado para ver un reporte guardado especifico
  const [viewingReport, setViewingReport] = useState<SavedReport | null>(null);

  // Estado para el visor de PDF
  const [pdfUrl, setPdfUrl] = useState<string | null>(null);

  // --- LOGICA DE PROCESAMIENTO FINANCIERO ---
  const processSalesData = (salesToProcess: Sale[], label: string): DashboardData => {
    const totalGross = salesToProcess.reduce((acc, s) => acc + (s.total || 0), 0);
    const payments = { cash: 0, transfer: 0, card: 0 };
    const productStats: Record<string, { qty: number, total: number }> = {};
    const hourlyMap: Record<string, { count: number, total: number }> = {};

    // Initialize hours 08:00 to 20:00 just to be clean, or dynamic
    for(let i=8; i<=20; i++) {
        const h = i.toString().padStart(2, '0') + ':00';
        hourlyMap[h] = { count: 0, total: 0 };
    }

    salesToProcess.forEach(s => {
      // 1. Payments
      if (s.paymentSplits && Array.isArray(s.paymentSplits)) {
        s.paymentSplits.forEach(p => {
          if(p.method === 'Efectivo') payments.cash += (p.amount || 0);
          if(p.method === 'Transferencia') payments.transfer += (p.amount || 0);
          if(p.method === 'Tarjeta') payments.card += (p.amount || 0);
        });
      } else if (s.paidAmount > 0) {
        payments.cash += s.paidAmount;
      }

      // 2. Products
      if (s.items && Array.isArray(s.items)) {
        s.items.forEach(item => {
          const name = item.name || 'Producto';
          if (!productStats[name]) productStats[name] = { qty: 0, total: 0 };
          productStats[name].qty += (item.quantity || 0);
          productStats[name].total += (item.quantity || 0) * (item.price || 0);
        });
      }

      // 3. Hourly Stats
      const date = new Date(s.timestamp);
      const hourKey = date.getHours().toString().padStart(2, '0') + ':00';
      if (!hourlyMap[hourKey]) hourlyMap[hourKey] = { count: 0, total: 0 };
      hourlyMap[hourKey].count += 1;
      hourlyMap[hourKey].total += s.total;
    });

    const topProducts = Object.entries(productStats)
      .map(([name, stats]) => ({ name, ...stats }))
      .sort((a, b) => b.qty - a.qty)
      .slice(0, 5);

    const hourlyStats = Object.entries(hourlyMap)
        .map(([hour, stats]) => ({ hour, ...stats }))
        .sort((a, b) => a.hour.localeCompare(b.hour))
        .filter(h => h.count > 0); // Only show active hours

    const maxQty = Math.max(...Object.values(productStats).map(s => s.qty), 1);
    const averageTicket = salesToProcess.length > 0 ? totalGross / salesToProcess.length : 0;

    return {
      totalGross,
      totalTransactions: salesToProcess.length,
      averageTicket,
      payments,
      topProducts,
      hourlyStats,
      categoryStats: [], // Placeholder for now
      maxQty,
      label
    };
  };

  // --- LOGICA DE PROCESAMIENTO OPERATIVO ---
  const processTaskData = (tasksToProcess: Task[], label: string): TaskDashboardData => {
    const employeeStats: Record<string, { completed: number, total: number, tasks: Task[] }> = {};

    tasksToProcess.forEach(t => {
      if (!employeeStats[t.employeeId]) {
        employeeStats[t.employeeId] = { completed: 0, total: 0, tasks: [] };
      }
      employeeStats[t.employeeId].total++;
      employeeStats[t.employeeId].tasks.push(t);
      if (t.status === 'completada') {
        employeeStats[t.employeeId].completed++;
      }
    });

    const byEmployee = Object.entries(employeeStats).map(([id, stats]) => ({
      id,
      name: employees.find(e => e.id === id)?.name || 'Desconocido',
      ...stats
    }));

    return {
      totalTasks: tasksToProcess.length,
      completedTasks: tasksToProcess.filter(t => t.status === 'completada').length,
      pendingTasks: tasksToProcess.filter(t => t.status === 'pendiente').length,
      byEmployee,
      label
    };
  };

  // --- LOGICA DE PROCESAMIENTO DE ACTIVOS (GARRAFONES) ---
  const processAssetData = (salesToProcess: Sale[], label: string): AssetDashboardData => {
    // 1. Plant Stock: Only items matching "Garraf" or Category 'Agua'
    const plantStock = products
      .filter(p => p.name.toLowerCase().includes('garraf') || p.category === 'Agua')
      .reduce((acc, p) => acc + p.stock, 0);

    // 2. Route Stock: Check all vehicles
    const routeStock = vehicles.reduce((acc, v) => acc + v.currentLoad, 0);
    const vehicleBreakdown = vehicles.map(v => ({
       plate: v.plate,
       load: v.currentLoad,
       items: v.inventory.filter(i => i.name.toLowerCase().includes('garraf')).map(i => `${i.quantity}x ${i.name.split(' ')[0]}`).join(', ')
    })).filter(v => v.load > 0);

    // 3. Movement from Sales
    let soldCount = 0;
    let returnedCount = 0;

    salesToProcess.forEach(s => {
       // Out
       s.items.forEach(i => {
          if (i.name.toLowerCase().includes('garraf') || i.category === 'Agua') {
             soldCount += i.quantity;
          }
       });
       // In
       returnedCount += (s.emptyGarrafonsReturned || 0);
    });

    const netMovement = soldCount - returnedCount;

    return {
       plantStock,
       routeStock,
       soldCount,
       returnedCount,
       netMovement,
       vehicleBreakdown,
       label
    };
  };

  // --- DATOS EN VIVO (FILTERED) ---
  const timeFilter = useMemo(() => {
    const now = new Date();
    let startTime = 0;
    // Simple filter: start of day/week/month
    if (timeRange === 'day') {
      startTime = new Date(now.setHours(0,0,0,0)).getTime();
    } else if (timeRange === 'week') {
      const day = now.getDay(); 
      const diff = now.getDate() - day + (day === 0 ? -6 : 1); 
      const monday = new Date(now.setDate(diff));
      startTime = new Date(monday.setHours(0,0,0,0)).getTime();
    } else if (timeRange === 'month') {
      startTime = new Date(now.getFullYear(), now.getMonth(), 1).getTime();
    }
    return startTime;
  }, [timeRange]);

  const liveFilteredSales = useMemo(() => {
    return sales.filter(s => s.timestamp >= timeFilter);
  }, [sales, timeFilter]);

  const liveFilteredTasks = useMemo(() => {
    return tasks.filter(t => {
       const taskTs = new Date(t.date + 'T00:00:00').getTime(); 
       return taskTs >= timeFilter; 
    });
  }, [tasks, timeFilter]);

  const liveData = processSalesData(liveFilteredSales, timeRange === 'day' ? 'Hoy' : timeRange === 'week' ? 'Esta Semana' : 'Este Mes');
  const taskData = processTaskData(liveFilteredTasks, timeRange === 'day' ? 'Hoy' : timeRange === 'week' ? 'Esta Semana' : 'Este Mes');
  const assetData = processAssetData(liveFilteredSales, timeRange === 'day' ? 'Hoy' : timeRange === 'week' ? 'Esta Semana' : 'Este Mes');

  const handleSaveSnapshot = () => {
    if (reportType !== 'financial') return alert("Solo se pueden guardar reportes financieros en el historial histórico.");

    if (liveFilteredSales.length === 0) {
      alert("No hay datos para guardar en este reporte.");
      return;
    }

    if(!confirm(`¿Guardar reporte de ${timeRange === 'day' ? 'Hoy' : timeRange === 'week' ? 'Esta Semana' : 'Este Mes'} en el historial?`)) return;

    const dateLabel = new Date().toLocaleDateString('es-MX', {
      day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute:'2-digit'
    });

    const newReport: SavedReport = {
      id: `REP-${Date.now()}`,
      timestamp: Date.now(),
      rangeType: timeRange,
      dateLabel: dateLabel,
      totalGross: liveData.totalGross,
      totalTransactions: liveData.totalTransactions,
      averageTicket: liveData.averageTicket,
      payments: liveData.payments,
      topProducts: liveData.topProducts,
    };

    addSavedReport(newReport);
    setActiveTab('history');
  };

  const handleGeneratePDF = () => {
    try {
      let url = '';
      if (reportType === 'financial') {
        const reportData = {
          ...liveData,
          rangeType: timeRange
        };
        url = generateFinancialPDF(reportData, ticketConfig);
      } else if (reportType === 'assets') {
        url = generateGarrafonReportPDF({ ...assetData, totalAssets: assetData.plantStock + assetData.routeStock }, ticketConfig);
      } else {
        const reportData = {
          ...taskData,
          rangeType: timeRange
        };
        url = generateTaskReportPDF(reportData, ticketConfig);
      }
      setPdfUrl(url);
    } catch (e) {
      console.error(e);
      alert("Error generando PDF");
    }
  };

  // --- VISTA DETALLADA DE HISTORIAL ---
  if (viewingReport) {
    // Only supports financial history viewing for now
    const historicData: DashboardData = {
      totalGross: viewingReport.totalGross,
      totalTransactions: viewingReport.totalTransactions,
      averageTicket: viewingReport.averageTicket,
      payments: { ...viewingReport.payments, card: viewingReport.payments.card || 0 }, // Ensure card prop exists
      topProducts: viewingReport.topProducts,
      hourlyStats: [], // Not saved in history object yet
      categoryStats: [],
      maxQty: Math.max(...viewingReport.topProducts.map(p => p.qty), 1),
      label: viewingReport.dateLabel
    };

    return (
      <div className="h-full bg-sky-50 overflow-y-auto pb-32 no-scrollbar animate-fadeIn">
         <ModuleHeader title="Detalle de Reporte" onBack={() => setViewingReport(null)} />
         <div className="px-6 space-y-4">
           <div className="bg-sky-600 text-white p-4 rounded-3xl flex justify-between items-center shadow-lg shadow-sky-200">
              <div>
                 <span className="text-[10px] font-black uppercase opacity-60">Fecha de Corte</span>
                 <p className="font-bold text-sm">{viewingReport.dateLabel}</p>
                 <span className="bg-white/20 text-[9px] px-2 py-0.5 rounded uppercase font-black mt-1 inline-block">
                    Tipo: {viewingReport.rangeType === 'day' ? 'Diario' : viewingReport.rangeType === 'week' ? 'Semanal' : 'Mensual'}
                 </span>
              </div>
              <div className="flex gap-2">
                <button 
                  onClick={() => {
                     const url = generateFinancialPDF({...historicData, rangeType: viewingReport.rangeType}, ticketConfig);
                     setPdfUrl(url);
                  }}
                  className="w-10 h-10 bg-white/20 rounded-full flex items-center justify-center text-white active:scale-95 transition-all"
                  title="Exportar PDF"
                >
                  <i className="fas fa-file-pdf"></i>
                </button>
                <button 
                   onClick={() => {
                      if(confirm("¿Eliminar este reporte permanentemente?")) {
                         deleteSavedReport(viewingReport.id);
                         setViewingReport(null);
                      }
                   }}
                   className="w-10 h-10 bg-white/10 rounded-full flex items-center justify-center text-white active:bg-red-500 transition-colors"
                >
                  <i className="fas fa-trash-can"></i>
                </button>
              </div>
           </div>

           <ReportDashboard data={historicData} />
         </div>
         {pdfUrl && <PDFReaderModal url={pdfUrl} onClose={() => setPdfUrl(null)} />}
      </div>
    );
  }

  return (
    <div className="h-full bg-sky-50 overflow-y-auto pb-32 no-scrollbar">
      <ModuleHeader title="Reportes y Finanzas" onBack={onBack} />

      <div className="px-6 flex gap-2 mb-4 shrink-0">
        <button onClick={() => setActiveTab('live')} className={`flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'live' ? 'bg-sky-600 text-white shadow-lg' : 'bg-white text-sky-400'}`}>Análisis en Vivo</button>
        <button onClick={() => setActiveTab('history')} className={`flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'history' ? 'bg-sky-600 text-white shadow-lg' : 'bg-white text-sky-400'}`}>Historial</button>
      </div>

      <div className="px-6 space-y-6">
        {activeTab === 'live' && (
          <>
            <div className="flex bg-white p-1 rounded-[2rem] shadow-sm mb-2 overflow-x-auto no-scrollbar">
              <button onClick={() => setReportType('financial')} className={`flex-1 py-3 px-4 rounded-[1.5rem] text-[10px] font-black uppercase tracking-widest whitespace-nowrap transition-all ${reportType === 'financial' ? 'bg-indigo-500 text-white shadow-md' : 'text-indigo-300'}`}>
                 <i className="fas fa-coins mr-1"></i> Finanzas
              </button>
              <button onClick={() => setReportType('operational')} className={`flex-1 py-3 px-4 rounded-[1.5rem] text-[10px] font-black uppercase tracking-widest whitespace-nowrap transition-all ${reportType === 'operational' ? 'bg-amber-500 text-white shadow-md' : 'text-amber-300'}`}>
                 <i className="fas fa-list-check mr-1"></i> Operaciones
              </button>
              <button onClick={() => setReportType('assets')} className={`flex-1 py-3 px-4 rounded-[1.5rem] text-[10px] font-black uppercase tracking-widest whitespace-nowrap transition-all ${reportType === 'assets' ? 'bg-teal-500 text-white shadow-md' : 'text-teal-300'}`}>
                 <i className="fas fa-bottle-water mr-1"></i> Envases
              </button>
            </div>

            <div className="flex bg-white p-1.5 rounded-[2rem] shadow-sm">
              <button onClick={() => setTimeRange('day')} className={`flex-1 py-2.5 rounded-[1.5rem] text-[10px] font-black uppercase tracking-widest transition-all ${timeRange === 'day' ? 'bg-sky-50 text-sky-600 border border-sky-100' : 'text-slate-300'}`}>Día</button>
              <button onClick={() => setTimeRange('week')} className={`flex-1 py-2.5 rounded-[1.5rem] text-[10px] font-black uppercase tracking-widest transition-all ${timeRange === 'week' ? 'bg-sky-50 text-sky-600 border border-sky-100' : 'text-slate-300'}`}>Semana</button>
              <button onClick={() => setTimeRange('month')} className={`flex-1 py-2.5 rounded-[1.5rem] text-[10px] font-black uppercase tracking-widest transition-all ${timeRange === 'month' ? 'bg-sky-50 text-sky-600 border border-sky-100' : 'text-slate-300'}`}>Mes</button>
            </div>

            {reportType === 'financial' ? (
               <ReportDashboard data={liveData} />
            ) : reportType === 'operational' ? (
               <TaskReportDashboard data={taskData} />
            ) : (
               <AssetReportDashboard data={assetData} />
            )}

            <div className="flex gap-3">
              <button 
                onClick={handleGeneratePDF}
                className="flex-1 py-5 bg-white text-sky-600 rounded-[2.5rem] font-black text-xs uppercase tracking-widest shadow-sm border border-sky-100 active:scale-95 transition-all flex items-center justify-center gap-2"
              >
                <i className="fas fa-file-pdf"></i> PDF
              </button>

              {reportType === 'financial' && (
                <button 
                  onClick={handleSaveSnapshot}
                  className="flex-[2] py-5 bg-indigo-600 text-white rounded-[2.5rem] font-black text-xs uppercase tracking-widest shadow-xl shadow-indigo-200 active:scale-95 transition-all flex items-center justify-center gap-3"
                >
                  <i className="fas fa-save"></i> Generar Corte
                </button>
              )}
            </div>
          </>
        )}

        {activeTab === 'history' && (
          <div className="space-y-3 animate-fadeIn">
            {savedReports.length === 0 ? (
               <div className="text-center py-20 opacity-30">
                  <i className="fas fa-folder-open text-6xl mb-4 text-sky-300"></i>
                  <p className="text-xs font-black uppercase text-sky-400">No hay reportes guardados</p>
               </div>
            ) : (
               savedReports.sort((a,b) => b.timestamp - a.timestamp).map(report => (
                 <RoundedCard key={report.id} onClick={() => setViewingReport(report)} className="py-4 cursor-pointer hover:shadow-md transition-all active:scale-[0.98]">
                    <div className="flex justify-between items-center">
                       <div className="flex items-center gap-4">
                          <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-white text-lg shadow-sm ${
                            report.rangeType === 'day' ? 'bg-emerald-400' : report.rangeType === 'week' ? 'bg-indigo-400' : 'bg-purple-400'
                          }`}>
                            <i className="fas fa-chart-bar"></i>
                          </div>
                          <div>
                             <h4 className="font-black text-sky-900 text-sm">{report.dateLabel}</h4>
                             <span className="text-[9px] font-bold text-sky-400 uppercase">
                               Corte: {report.rangeType === 'day' ? 'Diario' : report.rangeType === 'week' ? 'Semanal' : 'Mensual'}
                             </span>
                          </div>
                       </div>
                       <div className="text-right">
                          <span className="block font-black text-sky-600 text-lg">${report.totalGross.toLocaleString()}</span>
                          <span className="text-[9px] font-bold text-sky-300">{report.totalTransactions} Ops</span>
                       </div>
                    </div>
                 </RoundedCard>
               ))
            )}
          </div>
        )}
      </div>

      {/* PDF Reader Overlay */}
      {pdfUrl && <PDFReaderModal url={pdfUrl} onClose={() => setPdfUrl(null)} />}
    </div>
  );
};

import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import { PDFDocument, StandardFonts, rgb, PDFFont } from 'pdf-lib';
import { TicketConfig, Sale, Task, Employee } from '../types';

// Interface for the data expected by the report generator
interface ReportData {
  label: string;
  rangeType: string;
  totalGross: number;
  totalTransactions: number;
  averageTicket: number;
  payments: { cash: number; transfer: number; card: number };
  topProducts: { name: string; qty: number; total: number }[];
  hourlyStats?: { hour: string; count: number; total: number }[]; // New
  categoryStats?: { name: string; total: number }[]; // New
}

interface TaskReportData {
  label: string;
  rangeType: string;
  totalTasks: number;
  completedTasks: number;
  pendingTasks: number;
  byEmployee: { id: string; name: string; completed: number; total: number; tasks: Task[] }[];
}

interface AssetReportData {
  label: string;
  plantStock: number;
  routeStock: number;
  totalAssets: number;
  netMovement: number; // Out - In
  returnedCount: number;
  soldCount: number;
  vehicleBreakdown: { plate: string; load: number; items: string }[];
}

// Helper to convert hex to rgb 0-1 range
const hexToRgbScale = (hex: string) => {
  const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
  return result ? {
    r: parseInt(result[1], 16) / 255,
    g: parseInt(result[2], 16) / 255,
    b: parseInt(result[3], 16) / 255
  } : { r: 0, g: 0, b: 0 };
};

export const generateFinancialPDF = (data: ReportData, config: TicketConfig): string => {
  const doc = new jsPDF();
  const pageWidth = doc.internal.pageSize.width;

  // --- HEADER ---
  doc.setFillColor(2, 132, 199); // Sky-600
  doc.rect(0, 0, pageWidth, 40, 'F');

  doc.setTextColor(255, 255, 255);
  doc.setFontSize(22);
  doc.setFont('helvetica', 'bold');
  doc.text(config.businessName, 15, 15);

  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');
  doc.text('REPORTE FINANCIERO INTEGRAL', 15, 22);
  doc.text(`Generado: ${new Date().toLocaleString()}`, 15, 27);

  // Right side header info
  doc.setFontSize(10);
  doc.text(`Periodo: ${data.label}`, pageWidth - 15, 15, { align: 'right' });
  doc.text(`Tipo: ${data.rangeType.toUpperCase()}`, pageWidth - 15, 20, { align: 'right' });

  // --- KPI CARDS (Simulated) ---
  let yPos = 55;

  // Title
  doc.setTextColor(15, 23, 42); // Slate-900
  doc.setFontSize(14);
  doc.setFont('helvetica', 'bold');
  doc.text('Resumen General', 15, yPos);

  yPos += 10;

  // Draw Boxes for KPIs
  const boxWidth = (pageWidth - 40) / 3;
  const boxHeight = 25;

  // Box 1: Ventas
  doc.setDrawColor(226, 232, 240);
  doc.setFillColor(248, 250, 252);
  doc.roundedRect(15, yPos, boxWidth, boxHeight, 3, 3, 'FD');
  doc.setFontSize(8);
  doc.setTextColor(100, 116, 139);
  doc.text('VENTAS BRUTAS', 20, yPos + 8);
  doc.setFontSize(12);
  doc.setTextColor(15, 23, 42);
  doc.setFont('helvetica', 'bold');
  doc.text(`$${data.totalGross.toLocaleString()}`, 20, yPos + 18);

  // Box 2: Ops
  doc.roundedRect(15 + boxWidth + 5, yPos, boxWidth, boxHeight, 3, 3, 'FD');
  doc.setFontSize(8);
  doc.setTextColor(100, 116, 139);
  doc.setFont('helvetica', 'normal');
  doc.text('TRANSACCIONES', 20 + boxWidth + 5, yPos + 8);
  doc.setFontSize(12);
  doc.setTextColor(15, 23, 42);
  doc.setFont('helvetica', 'bold');
  doc.text(`${data.totalTransactions}`, 20 + boxWidth + 5, yPos + 18);

  // Box 3: Ticket Prom
  doc.roundedRect(15 + (boxWidth * 2) + 10, yPos, boxWidth, boxHeight, 3, 3, 'FD');
  doc.setFontSize(8);
  doc.setTextColor(100, 116, 139);
  doc.setFont('helvetica', 'normal');
  doc.text('TICKET PROMEDIO', 20 + (boxWidth * 2) + 10, yPos + 8);
  doc.setFontSize(12);
  doc.setTextColor(15, 23, 42);
  doc.setFont('helvetica', 'bold');
  doc.text(`$${data.averageTicket.toFixed(2)}`, 20 + (boxWidth * 2) + 10, yPos + 18);

  yPos += 40;

  // --- PAYMENTS SECTION ---
  doc.setFontSize(12);
  doc.setTextColor(15, 23, 42);
  doc.text('Desglose de Ingresos', 15, yPos);
  yPos += 5;

  const total = data.payments.cash + data.payments.transfer + data.payments.card;

  autoTable(doc, {
    startY: yPos,
    head: [['Método de Pago', 'Monto Recaudado']],
    body: [
      ['Efectivo', `$${data.payments.cash.toLocaleString()}`],
      ['Transferencia', `$${data.payments.transfer.toLocaleString()}`],
      ['Tarjeta', `$${data.payments.card.toLocaleString()}`],
      ['TOTAL', `$${total.toLocaleString()}`]
    ],
    theme: 'striped',
    headStyles: { fillColor: [2, 132, 199] },
    styles: { fontSize: 10 },
    columnStyles: { 1: { halign: 'right', fontStyle: 'bold' } },
    foot: [['Balance', `$${total.toLocaleString()}`]],
    footStyles: { fillColor: [241, 245, 249], textColor: [15, 23, 42] }
  });

  yPos = (doc as any).lastAutoTable.finalY + 15;

  // --- HOURLY STATS (NEW) ---
  if (data.hourlyStats && data.hourlyStats.length > 0) {
    if (yPos > 240) { doc.addPage(); yPos = 20; }

    doc.text('Ventas por Horario (Picos de Actividad)', 15, yPos);
    yPos += 5;

    const hourlyRows = data.hourlyStats.map(h => [h.hour, h.count, `$${h.total.toLocaleString()}`]);

    autoTable(doc, {
        startY: yPos,
        head: [['Hora', 'Tickets', 'Venta']],
        body: hourlyRows,
        theme: 'grid',
        headStyles: { fillColor: [71, 85, 105] },
        columnStyles: { 1: { halign: 'center' }, 2: { halign: 'right' } }
    });
    yPos = (doc as any).lastAutoTable.finalY + 15;
  }

  // --- PRODUCTS SECTION ---
  if (yPos > 240) { doc.addPage(); yPos = 20; }
  doc.text('Top Productos Vendidos', 15, yPos);
  yPos += 5;

  const productRows = data.topProducts.map(p => [
    p.name,
    p.qty.toString(),
    `$${p.total.toLocaleString()}`
  ]);

  autoTable(doc, {
    startY: yPos,
    head: [['Producto', 'Cantidad', 'Venta Total']],
    body: productRows,
    theme: 'grid',
    headStyles: { fillColor: [2, 132, 199] },
    columnStyles: { 
      1: { halign: 'center' },
      2: { halign: 'right' }
    }
  });

  // --- FOOTER ---
  const pageCount = (doc as any).internal.getNumberOfPages();
  for(let i = 1; i <= pageCount; i++) {
    doc.setPage(i);
    doc.setFontSize(8);
    doc.setTextColor(150);
    doc.text(`Aqua+ ERP - Documento Confidencial - Página ${i} de ${pageCount}`, pageWidth / 2, doc.internal.pageSize.height - 10, { align: 'center' });
  }

  // Return the Data URL string to be used in an iframe
  return doc.output('datauristring');
};

export const generateGarrafonReportPDF = (data: AssetReportData, config: TicketConfig): string => {
  const doc = new jsPDF();
  const pageWidth = doc.internal.pageSize.width;

  // --- HEADER ---
  doc.setFillColor(13, 148, 136); // Teal-600
  doc.rect(0, 0, pageWidth, 40, 'F');

  doc.setTextColor(255, 255, 255);
  doc.setFontSize(22);
  doc.setFont('helvetica', 'bold');
  doc.text(config.businessName, 15, 15);

  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');
  doc.text('REPORTE DE ACTIVOS Y ENVASES', 15, 22);
  doc.text(`Generado: ${new Date().toLocaleString()}`, 15, 27);

  // Right side header info
  doc.text(`Corte: ${data.label}`, pageWidth - 15, 15, { align: 'right' });

  let yPos = 55;

  // --- INVENTORY SUMMARY ---
  doc.setTextColor(15, 23, 42);
  doc.setFontSize(14);
  doc.setFont('helvetica', 'bold');
  doc.text('Ubicación de Activos (Garrafones Llenos)', 15, yPos);

  yPos += 10;

  // Draw Boxes
  const boxWidth = (pageWidth - 40) / 3;
  const boxHeight = 25;

  // Box 1: Planta
  doc.setDrawColor(20, 184, 166); // Teal border
  doc.setFillColor(240, 253, 250); // Teal-50
  doc.roundedRect(15, yPos, boxWidth, boxHeight, 3, 3, 'FD');
  doc.setFontSize(8);
  doc.setTextColor(13, 148, 136);
  doc.text('EN PLANTA', 20, yPos + 8);
  doc.setFontSize(16);
  doc.setFont('helvetica', 'bold');
  doc.text(`${data.plantStock}`, 20, yPos + 18);

  // Box 2: Ruta
  doc.roundedRect(15 + boxWidth + 5, yPos, boxWidth, boxHeight, 3, 3, 'FD');
  doc.setFontSize(8);
  doc.text('EN RUTA', 20 + boxWidth + 5, yPos + 8);
  doc.setFontSize(16);
  doc.text(`${data.routeStock}`, 20 + boxWidth + 5, yPos + 18);

  // Box 3: Total
  doc.setFillColor(13, 148, 136); // Teal-600
  doc.roundedRect(15 + (boxWidth * 2) + 10, yPos, boxWidth, boxHeight, 3, 3, 'FD');
  doc.setTextColor(255, 255, 255);
  doc.setFontSize(8);
  doc.text('TOTAL AUDITADO', 20 + (boxWidth * 2) + 10, yPos + 8);
  doc.setFontSize(16);
  doc.text(`${data.totalAssets}`, 20 + (boxWidth * 2) + 10, yPos + 18);

  yPos += 40;

  // --- MOVEMENT BALANCE ---
  doc.setTextColor(15, 23, 42);
  doc.setFontSize(12);
  doc.text('Balance de Flujo (Movimientos en Periodo)', 15, yPos);
  yPos += 5;

  autoTable(doc, {
    startY: yPos,
    head: [['Concepto', 'Cantidad', 'Interpretación']],
    body: [
      ['Salidas (Ventas)', data.soldCount, 'Envases entregados a clientes'],
      ['Entradas (Retornos)', data.returnedCount, 'Envases vacíos recibidos'],
      ['Balance Neto', data.netMovement, data.netMovement > 0 ? 'Más envases en calle (Deuda)' : 'Recuperación de envases']
    ],
    theme: 'grid',
    headStyles: { fillColor: [13, 148, 136] }, // Teal
    columnStyles: { 1: { fontStyle: 'bold', halign: 'center' } },
    didParseCell: (dataCell: any) => {
        if(dataCell.row.index === 2 && dataCell.column.index === 1) {
            dataCell.cell.styles.textColor = data.netMovement > 0 ? [220, 38, 38] : [22, 163, 74];
        }
    }
  });

  yPos = (doc as any).lastAutoTable.finalY + 20;

  // --- VEHICLE BREAKDOWN ---
  doc.text('Desglose por Unidad Móvil', 15, yPos);
  yPos += 5;

  const vehicleRows = data.vehicleBreakdown.map(v => [
    v.plate,
    `${v.load} Unidades`,
    v.items
  ]);

  autoTable(doc, {
    startY: yPos,
    head: [['Unidad / Placa', 'Carga Total', 'Detalle de Carga']],
    body: vehicleRows.length > 0 ? vehicleRows : [['Sin unidades activas', '-', '-']],
    theme: 'striped',
    headStyles: { fillColor: [15, 23, 42] }, // Slate-900
  });

  // --- FOOTER ---
  const pageCount = (doc as any).internal.getNumberOfPages();
  for(let i = 1; i <= pageCount; i++) {
    doc.setPage(i);
    doc.setFontSize(8);
    doc.setTextColor(150);
    doc.text(`Aqua+ ERP - Control de Activos - Página ${i} de ${pageCount}`, pageWidth / 2, doc.internal.pageSize.height - 10, { align: 'center' });
  }

  return doc.output('datauristring');
};

export const generateTaskReportPDF = (data: TaskReportData, config: TicketConfig): string => {
  const doc = new jsPDF();
  const pageWidth = doc.internal.pageSize.width;

  // --- HEADER ---
  doc.setFillColor(245, 158, 11); // Amber-500
  doc.rect(0, 0, pageWidth, 40, 'F');

  doc.setTextColor(255, 255, 255);
  doc.setFontSize(22);
  doc.setFont('helvetica', 'bold');
  doc.text(config.businessName, 15, 15);

  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');
  doc.text('REPORTE OPERATIVO DE TAREAS', 15, 22);
  doc.text(`Generado: ${new Date().toLocaleString()}`, 15, 27);

  // Right side header info
  doc.setFontSize(10);
  doc.text(`Periodo: ${data.label}`, pageWidth - 15, 15, { align: 'right' });
  doc.text(`Cumplimiento: ${Math.round((data.completedTasks / (data.totalTasks || 1)) * 100)}%`, pageWidth - 15, 20, { align: 'right' });

  let yPos = 55;

  // --- SUMMARY ---
  doc.setTextColor(15, 23, 42);
  doc.setFontSize(14);
  doc.setFont('helvetica', 'bold');
  doc.text('Resumen de Productividad', 15, yPos);

  yPos += 10;

  // Draw Boxes
  const boxWidth = (pageWidth - 40) / 3;
  const boxHeight = 25;

  // Box 1: Total
  doc.setDrawColor(226, 232, 240);
  doc.setFillColor(248, 250, 252);
  doc.roundedRect(15, yPos, boxWidth, boxHeight, 3, 3, 'FD');
  doc.setFontSize(8);
  doc.setTextColor(100, 116, 139);
  doc.text('TOTAL ASIGNADAS', 20, yPos + 8);
  doc.setFontSize(12);
  doc.setTextColor(15, 23, 42);
  doc.setFont('helvetica', 'bold');
  doc.text(`${data.totalTasks}`, 20, yPos + 18);

  // Box 2: Completadas
  doc.roundedRect(15 + boxWidth + 5, yPos, boxWidth, boxHeight, 3, 3, 'FD');
  doc.setFontSize(8);
  doc.setTextColor(100, 116, 139);
  doc.text('COMPLETADAS', 20 + boxWidth + 5, yPos + 8);
  doc.setFontSize(12);
  doc.setTextColor(34, 197, 94); // Green
  doc.setFont('helvetica', 'bold');
  doc.text(`${data.completedTasks}`, 20 + boxWidth + 5, yPos + 18);

  // Box 3: Pendientes
  doc.roundedRect(15 + (boxWidth * 2) + 10, yPos, boxWidth, boxHeight, 3, 3, 'FD');
  doc.setFontSize(8);
  doc.setTextColor(100, 116, 139);
  doc.text('PENDIENTES', 20 + (boxWidth * 2) + 10, yPos + 8);
  doc.setFontSize(12);
  doc.setTextColor(239, 68, 68); // Red
  doc.setFont('helvetica', 'bold');
  doc.text(`${data.pendingTasks}`, 20 + (boxWidth * 2) + 10, yPos + 18);

  yPos += 40;

  // --- DETAILS PER EMPLOYEE ---
  data.byEmployee.forEach((emp) => {
    if (yPos > 250) {
      doc.addPage();
      yPos = 20;
    }

    doc.setFontSize(12);
    doc.setTextColor(15, 23, 42);
    doc.text(`Colaborador: ${emp.name} (${Math.round((emp.completed / (emp.total || 1)) * 100)}%)`, 15, yPos);
    yPos += 5;

    // Group tasks by date
    const tasksByDate = emp.tasks.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    let lastDate = '';

    const taskRows = tasksByDate.map(t => {
      const isNewDate = t.date !== lastDate;
      if(isNewDate) lastDate = t.date;

      const time = new Date(t.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

      return [
        isNewDate ? t.date : '', // Group visual
        time,
        t.title,
        t.status === 'completada' ? 'COMPLETA' : 'PENDIENTE',
        t.description || '-'
      ];
    });

    autoTable(doc, {
      startY: yPos,
      head: [['Fecha', 'Hora', 'Tarea', 'Estado', 'Detalle']],
      body: taskRows,
      theme: 'grid',
      headStyles: { fillColor: [245, 158, 11] }, // Amber header
      styles: { fontSize: 8 },
      columnStyles: { 
        0: { fontStyle: 'bold', cellWidth: 25 },
        3: { fontStyle: 'bold' }
      },
      didParseCell: (data: any) => {
        if (data.section === 'body' && data.column.index === 3) {
          if (data.cell.raw === 'PENDIENTE') {
            data.cell.styles.textColor = [220, 38, 38]; // Red
          } else {
            data.cell.styles.textColor = [22, 163, 74]; // Green
          }
        }
      }
    });

    yPos = (doc as any).lastAutoTable.finalY + 15;
  });

  // --- FOOTER ---
  const pageCount = (doc as any).internal.getNumberOfPages();
  for(let i = 1; i <= pageCount; i++) {
    doc.setPage(i);
    doc.setFontSize(8);
    doc.setTextColor(150);
    doc.text(`Aqua+ ERP - Reporte Operativo - Página ${i} de ${pageCount}`, pageWidth / 2, doc.internal.pageSize.height - 10, { align: 'center' });
  }

  return doc.output('datauristring');
};

/**
 * Generates a Ticket PDF using pdf-lib and returns raw bytes
 */
export const generateTicketPDF = async (sale: Sale, config: TicketConfig): Promise<Uint8Array> => {
  // Crear nuevo documento PDF
  const pdfDoc = await PDFDocument.create();

  const accent = hexToRgbScale(config.colorHex || '#000000');
  const accentColor = rgb(accent.r, accent.g, accent.b);

  // Calcular altura dinámica base
  const itemsHeight = sale.items.length * 25; 
  // Dynamic space for optional elements
  const qrSpace = config.showQr !== false ? 120 : 20; 
  const footerSpace = config.showFooter !== false ? 60 : 20;
  const logoSpace = (config.showLogo !== false && config.logoUrl) ? 80 : 0;

  const baseHeight = 300 + logoSpace; 
  const ticketHeight = baseHeight + itemsHeight + qrSpace + footerSpace;

  // DYNAMIC WIDTH: 80mm approx 226pts, 58mm approx 164pts.
  // Default to 80mm standard (280pts wide for readability with margins) unless 58mm specified.
  const is58mm = config.paperWidth === '58mm';
  const ticketWidth = is58mm ? 164 : 280; 
  const contentWidth = ticketWidth - 30; // 15 margin each side
  const centerX = ticketWidth / 2;
  const margin = 15;

  const page = pdfDoc.addPage([ticketWidth, ticketHeight]);

  // Obtener fuentes
  const fontRegular = await pdfDoc.embedFont(StandardFonts.Helvetica);
  const fontBold = await pdfDoc.embedFont(StandardFonts.HelveticaBold);
  const fontCourier = await pdfDoc.embedFont(StandardFonts.Courier);

  // Font Size Scaling for 58mm
  const fs = (size: number) => is58mm ? Math.max(6, size * 0.75) : size; 

  let yPos = ticketHeight - 20;

  // --- HELPERS ---
  const sanitize = (text: string) => {
    if (!text) return '';
    return text
      .replace(/★/g, '*')
      .replace(/☆/g, '*')
      .replace(/●/g, '-')
      .replace(/•/g, '-');
  };

  const drawCenteredText = (text: string, font: PDFFont, size: number, color = rgb(0,0,0)) => {
    const safeText = sanitize(text);
    const scaledSize = fs(size);
    const textWidth = font.widthOfTextAtSize(safeText, scaledSize);
    page.drawText(safeText, { x: centerX - (textWidth / 2), y: yPos, size: scaledSize, font, color });
    yPos -= (scaledSize + 4);
  };

  const drawLeftRight = (left: string, right: string, font: PDFFont, size: number, isBold = false) => {
    const safeLeft = sanitize(left);
    const safeRight = sanitize(right);
    const scaledSize = fs(size);
    const rightWidth = font.widthOfTextAtSize(safeRight, scaledSize);
    page.drawText(safeLeft, { x: margin, y: yPos, size: scaledSize, font });
    page.drawText(safeRight, { x: ticketWidth - margin - rightWidth, y: yPos, size: scaledSize, font: isBold ? fontBold : font });
    yPos -= (scaledSize + 6);
  };

  const drawDashedLine = () => {
    const dash = '- - - - - - - - - - - - - - - - - - - - - - - - - - - -';
    const scaledSize = fs(10);
    const textWidth = fontCourier.widthOfTextAtSize(dash, scaledSize);
    page.drawText(dash, { x: centerX - (textWidth / 2), y: yPos, size: scaledSize, font: fontCourier, color: rgb(0.5, 0.5, 0.5) });
    yPos -= 12;
  };

  // --- LOGO ---
  if (config.showLogo !== false && config.logoUrl && config.logoUrl.startsWith('data:image')) {
    try {
      if (config.logoUrl.includes('image/svg+xml')) {
         yPos -= 10;
      } else {
          const base64Data = config.logoUrl.split(',')[1];
          const imageBytes = Uint8Array.from(atob(base64Data), c => c.charCodeAt(0));

          let logoImage;
          if (config.logoUrl.includes('image/png')) {
            logoImage = await pdfDoc.embedPng(imageBytes);
          } else if (config.logoUrl.includes('image/jpeg') || config.logoUrl.includes('image/jpg')) {
            logoImage = await pdfDoc.embedJpg(imageBytes);
          }

          if (logoImage) {
              const logoDims = logoImage.scale(1);
              const maxLogoWidth = is58mm ? 50 : 80;
              const scaleFactor = maxLogoWidth / logoDims.width;
              const scaledWidth = logoDims.width * scaleFactor;
              const scaledHeight = logoDims.height * scaleFactor;

              page.drawImage(logoImage, {
                x: centerX - (scaledWidth / 2),
                y: yPos - scaledHeight,
                width: scaledWidth,
                height: scaledHeight,
              });
              yPos -= (scaledHeight + 10);
          } else {
              yPos -= 10;
          }
      }
    } catch (e) {
      console.warn("Error embedding logo", e);
      yPos -= 10;
    }
  } else {
    yPos -= 10;
  }

  // --- HEADER ---
  drawCenteredText(config.businessName, fontBold, 16, accentColor);
  if (config.slogan) drawCenteredText(`"${config.slogan}"`, fontRegular, 9, rgb(0.4, 0.4, 0.4));

  yPos -= 5;
  drawCenteredText(config.address, fontRegular, 9);
  drawCenteredText(`Tel: ${config.phone}`, fontRegular, 9);
  if (config.email) drawCenteredText(config.email, fontRegular, 8);
  if (config.website) drawCenteredText(config.website, fontRegular, 8);
  if (config.rfc) drawCenteredText(`RFC: ${config.rfc}`, fontRegular, 9);

  yPos -= 5;
  drawDashedLine();

  // --- META INFO ---
  drawLeftRight('Folio:', sale.id, fontRegular, 10, true);
  drawLeftRight('Fecha:', new Date(sale.timestamp).toLocaleDateString(), fontRegular, 10);
  drawLeftRight('Hora:', new Date(sale.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}), fontRegular, 10);
  drawLeftRight('Cliente:', sale.customerAlias.substring(0, is58mm ? 12 : 18), fontRegular, 10, true);

  yPos -= 5;

  // --- TABLE HEADER ---
  const headerSize = fs(8);
  page.drawRectangle({
    x: margin,
    y: yPos - 2,
    width: contentWidth,
    height: 14,
    color: accentColor, 
    opacity: 0.1
  });

  page.drawText('CANT', { x: margin + 5, y: yPos, size: headerSize, font: fontBold, color: accentColor });
  page.drawText('DESCRIPCION', { x: margin + (is58mm ? 35 : 45), y: yPos, size: headerSize, font: fontBold, color: accentColor });
  const impHeaderWidth = fontBold.widthOfTextAtSize('IMPORTE', headerSize);
  page.drawText('IMPORTE', { x: ticketWidth - margin - impHeaderWidth - 5, y: yPos, size: headerSize, font: fontBold, color: accentColor });
  yPos -= 18;

  // --- ITEMS ---
  const itemSize = fs(10);
  const descSize = fs(9);
  sale.items.forEach(item => {
    // Cantidad
    page.drawText(item.quantity.toString(), { x: margin + 8, y: yPos, size: itemSize, font: fontBold });

    // Descripción
    const cleanName = sanitize(item.name);
    const maxChars = is58mm ? 12 : 20;
    const name = cleanName.length > maxChars ? cleanName.substring(0, maxChars) + '...' : cleanName;
    page.drawText(name, { x: margin + (is58mm ? 35 : 45), y: yPos, size: descSize, font: fontRegular });

    // Importe
    const totalItem = (item.quantity * item.price).toFixed(2);
    const totalItemWidth = fontRegular.widthOfTextAtSize(`$${totalItem}`, itemSize);
    page.drawText(`$${totalItem}`, { x: ticketWidth - margin - totalItemWidth, y: yPos, size: itemSize, font: fontRegular });

    yPos -= 15;
  });

  drawDashedLine();

  // --- TOTALS ---
  const drawTotalLine = (label: string, value: string, isBig = false) => {
    const safeLabel = sanitize(label);
    const safeValue = sanitize(value);

    const size = isBig ? fs(16) : fs(10);
    const font = isBig ? fontBold : fontRegular;
    const color = isBig ? accentColor : rgb(0,0,0);

    const labelWidth = font.widthOfTextAtSize(safeLabel, size);
    const valueWidth = font.widthOfTextAtSize(safeValue, size);

    const valueX = ticketWidth - margin - valueWidth;
    const labelX = valueX - labelWidth - 10;

    page.drawText(safeLabel, { x: labelX, y: yPos, size, font, color });
    page.drawText(safeValue, { x: valueX, y: yPos, size, font, color });
    yPos -= (size + 8);
  };

  drawTotalLine('TOTAL:', `$${sale.total.toFixed(2)}`, true);

  if (sale.paymentSplits && sale.paymentSplits.length > 0) {
     sale.paymentSplits.forEach(split => {
        drawTotalLine(`${split.method}:`, `$${split.amount.toFixed(2)}`);
     });
  } else {
     drawTotalLine('Su Pago:', `$${sale.paidAmount.toFixed(2)}`);
  }

  if (sale.change > 0) {
    drawTotalLine('Cambio:', `$${sale.change.toFixed(2)}`);
  } else if (sale.paidAmount < sale.total) {
    // Background for Debt warning
    page.drawRectangle({
        x: margin,
        y: yPos - 8,
        width: contentWidth,
        height: 20,
        color: accentColor,
    });

    page.drawText('SALDO PENDIENTE', { x: margin + 5, y: yPos + 2, size: fs(10), font: fontBold, color: rgb(1,1,1) });
    const debtStr = `$${(sale.total - sale.paidAmount).toFixed(2)}`;
    const debtW = fontBold.widthOfTextAtSize(debtStr, fs(10));
    page.drawText(debtStr, { x: ticketWidth - margin - debtW - 5, y: yPos + 2, size: fs(10), font: fontBold, color: rgb(1,1,1) });
    yPos -= 25;
  }

  // --- GARRAFONES RETURNED ---
  if (sale.emptyGarrafonsReturned > 0) {
    yPos -= 5;
    page.drawRectangle({
      x: margin + 10,
      y: yPos - 5,
      width: contentWidth - 20,
      height: 25,
      borderColor: accentColor,
      borderWidth: 1,
    });
    const text = `* ${sale.emptyGarrafonsReturned} Envases Recibidos *`;
    const textW = fontBold.widthOfTextAtSize(text, fs(10));
    page.drawText(text, { x: centerX - (textW/2), y: yPos + 5, size: fs(10), font: fontBold, color: accentColor });
    yPos -= 25;
  }

  // --- FOOTER & QR CODE ---
  if (config.showFooter !== false) {
      yPos -= 10;
      const footerSize = fs(9);

      if (config.footerMessage) {
        const words = sanitize(config.footerMessage).split(' ');
        let line = '';
        for (const word of words) {
            const testLine = line + word + ' ';
            const testWidth = fontRegular.widthOfTextAtSize(testLine, footerSize);
            if (testWidth > contentWidth) {
                drawCenteredText(line, fontRegular, footerSize);
                line = word + ' ';
            } else {
                line = testLine;
            }
        }
        drawCenteredText(line, fontRegular, footerSize);
      }

      if (config.extraNote) {
        drawCenteredText(sanitize(config.extraNote), fontRegular, fs(8), rgb(0.5, 0.5, 0.5));
      }

      drawCenteredText('*** GRACIAS POR SU PREFERENCIA ***', fontBold, footerSize);
  }

  // QR Code at the bottom
  if (config.showQr !== false) {
      yPos -= 10;
      try {
        const qrData = btoa(`AQUA-PRO-SECURE|${JSON.stringify({ id: sale.id, total: sale.total })}`);
        const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(qrData)}`;

        // Fetch image data
        const qrResponse = await fetch(qrUrl);
        const qrArrayBuffer = await qrResponse.arrayBuffer();
        const qrImage = await pdfDoc.embedPng(qrArrayBuffer);

        const qrSize = is58mm ? 80 : 100;

        page.drawImage(qrImage, {
            x: centerX - (qrSize / 2),
            y: yPos - qrSize,
            width: qrSize,
            height: qrSize
        });
      } catch (e) {
        console.warn("Could not embed QR code in PDF", e);
        // Draw placeholder
        yPos -= 20;
        drawCenteredText('[ CODIGO QR NO DISPONIBLE ]', fontCourier, 8);
      }
  }

  return await pdfDoc.save();
}

export type ViewType = 'dashboard' | 'pos' | 'orders' | 'logistics' | 'production' | 'sync' | 'whatsapp' | 'customers' | 'employees' | 'reports' | 'settings' | 'quality' | 'scanner' | 'inventory' | 'tickets' | 'supplies' | 'messages';

export interface Product {
  id: string;
  name: string;
  price: number;
  stock: number;
  category?: 'Agua' | 'Insumos' | 'Accesorios';
  lastUpdated?: number;
}

export type GarrafonType = 'Aqua' | 'Bonafont' | 'Ciel' | 'E-Pura' | 'Generico';

export interface Customer {
  id: string;
  name: string;
  alias: string;
  address?: string; 
  phone?: string;
  specialPrice?: number;
  lat?: number;
  lng?: number;
  garrafonType?: GarrafonType;
  jugsOnLoan?: number; 
  balance: number;
  lastUpdated?: number;
}

export interface TicketConfig {
  businessName: string;
  rfc: string;
  address: string;
  phone: string;
  footerMessage: string;
  logoUrl?: string;
  website?: string;
  socialMedia?: string;
  extraNote?: string;
  slogan?: string;
  email?: string;
  colorHex?: string; 
  paperWidth?: '58mm' | '80mm';
  showLogo?: boolean;
  showQr?: boolean;
  showFooter?: boolean;
}

export interface ProcessStep {
  stage: string;
  process: string;
  time: number; // Seconds
}

export interface ProductionConfig {
  backwashSequence: ProcessStep[];
  regenerationSequence: ProcessStep[];
}

export interface CloudConfig {
  url: string;
  apiKey: string;
  autoSync: boolean;
  lastSync?: number;
}

export interface Order {
  id: string;
  customerId: string;
  customerAlias: string;
  items: CartItem[];
  total: number;
  status: 'pendiente' | 'asignado' | 'entregado' | 'cancelado';
  vehicleId?: string;
  timestamp: number;
  priority: number;
  deviceId?: string; 
  lastUpdated?: number; // Crucial for sync conflict resolution
}

export interface CartItem extends Product {
  quantity: number;
}

export type PaymentMethod = 'Efectivo' | 'Transferencia' | 'Tarjeta' | 'Crédito' | 'Multimodal';

export interface PaymentSplit {
  method: 'Efectivo' | 'Transferencia' | 'Tarjeta';
