  deviceId?: string; 
}

export interface QualityRecord {
  id: string;
  timestamp: number;
  type: 'Cruda' | 'Producto';
  ph: number;
  cloro: number;
  tds: number;
  dureza: number;
  color: string;
  sabor: string;
  turbiedad: string;
  employeeId: string;
}

export interface Task {
  id: string;
  employeeId: string;
  title: string;
  description?: string;
  status: 'pendiente' | 'completada';
  timestamp: number;
  date: string;
  deviceId?: string; 
  lastUpdated?: number;
}

export interface Attendance {
  id: string;
  employeeId: string;
  timestamp: number;
  date: string;
  status: 'presente' | 'falta' | 'retardo';
}

export type Role = 'Repartidor' | 'Planta' | 'Administrador';

export interface Employee {
  id: string;
  name: string;
  roles: Role[]; 
  phone: string;
  pin: string;
