}

export interface FuelRecord {
  id: string;
  date: number;
  mileage: number;
  liters: number;
  cost: number;
  notes?: string;
}

export interface Vehicle {
  id: string;
  plate: string;
  description: string;
  loadCapacity: number;
  currentLoad: number;
