  }

  return doc.output('datauristring');
};

/**
 * Generates a Ticket PDF using pdf-lib and returns raw bytes
 */
export const generateTicketPDF = async (sale: Sale, config: TicketConfig): Promise<Uint8Array> => {
  // Crear nuevo documento PDF
  const pdfDoc = await PDFDocument.create();

  const accent = hexToRgbScale(config.colorHex || '#000000');
  const accentColor = rgb(accent.r, accent.g, accent.b);

  // Calcular altura dinámica base
  const itemsHeight = sale.items.length * 25; 
  // Dynamic space for optional elements
  const qrSpace = config.showQr !== false ? 120 : 20; 
  const footerSpace = config.showFooter !== false ? 60 : 20;
  const logoSpace = (config.showLogo !== false && config.logoUrl) ? 80 : 0;

  const baseHeight = 300 + logoSpace; 
  const ticketHeight = baseHeight + itemsHeight + qrSpace + footerSpace;

  // DYNAMIC WIDTH: 80mm approx 226pts, 58mm approx 164pts.
  // Default to 80mm standard (280pts wide for readability with margins) unless 58mm specified.
  const is58mm = config.paperWidth === '58mm';
  const ticketWidth = is58mm ? 164 : 280; 
  const contentWidth = ticketWidth - 30; // 15 margin each side
  const centerX = ticketWidth / 2;
  const margin = 15;

  const page = pdfDoc.addPage([ticketWidth, ticketHeight]);

  // Obtener fuentes
  const fontRegular = await pdfDoc.embedFont(StandardFonts.Helvetica);
  const fontBold = await pdfDoc.embedFont(StandardFonts.HelveticaBold);
  const fontCourier = await pdfDoc.embedFont(StandardFonts.Courier);

  // Font Size Scaling for 58mm
  const fs = (size: number) => is58mm ? Math.max(6, size * 0.75) : size; 

  let yPos = ticketHeight - 20;

  // --- HELPERS ---
  const sanitize = (text: string) => {
    if (!text) return '';
    return text
      .replace(/★/g, '*')
      .replace(/☆/g, '*')
      .replace(/●/g, '-')
      .replace(/•/g, '-');
  };

  const drawCenteredText = (text: string, font: PDFFont, size: number, color = rgb(0,0,0)) => {
    const safeText = sanitize(text);
    const scaledSize = fs(size);
    const textWidth = font.widthOfTextAtSize(safeText, scaledSize);
    page.drawText(safeText, { x: centerX - (textWidth / 2), y: yPos, size: scaledSize, font, color });
    yPos -= (scaledSize + 4);
  };

  const drawLeftRight = (left: string, right: string, font: PDFFont, size: number, isBold = false) => {
    const safeLeft = sanitize(left);
    const safeRight = sanitize(right);
    const scaledSize = fs(size);
    const rightWidth = font.widthOfTextAtSize(safeRight, scaledSize);
    page.drawText(safeLeft, { x: margin, y: yPos, size: scaledSize, font });
    page.drawText(safeRight, { x: ticketWidth - margin - rightWidth, y: yPos, size: scaledSize, font: isBold ? fontBold : font });
    yPos -= (scaledSize + 6);
  };

  const drawDashedLine = () => {
    const dash = '- - - - - - - - - - - - - - - - - - - - - - - - - - - -';
    const scaledSize = fs(10);
    const textWidth = fontCourier.widthOfTextAtSize(dash, scaledSize);
    page.drawText(dash, { x: centerX - (textWidth / 2), y: yPos, size: scaledSize, font: fontCourier, color: rgb(0.5, 0.5, 0.5) });
    yPos -= 12;
  };

  // --- LOGO ---
  if (config.showLogo !== false && config.logoUrl && config.logoUrl.startsWith('data:image')) {
    try {
      if (config.logoUrl.includes('image/svg+xml')) {
         yPos -= 10;
      } else {
          const base64Data = config.logoUrl.split(',')[1];
          const imageBytes = Uint8Array.from(atob(base64Data), c => c.charCodeAt(0));

          let logoImage;
          if (config.logoUrl.includes('image/png')) {
            logoImage = await pdfDoc.embedPng(imageBytes);
          } else if (config.logoUrl.includes('image/jpeg') || config.logoUrl.includes('image/jpg')) {
            logoImage = await pdfDoc.embedJpg(imageBytes);
          }

          if (logoImage) {
              const logoDims = logoImage.scale(1);
              const maxLogoWidth = is58mm ? 50 : 80;
              const scaleFactor = maxLogoWidth / logoDims.width;
              const scaledWidth = logoDims.width * scaleFactor;
              const scaledHeight = logoDims.height * scaleFactor;

              page.drawImage(logoImage, {
                x: centerX - (scaledWidth / 2),
                y: yPos - scaledHeight,
                width: scaledWidth,
                height: scaledHeight,
              });
              yPos -= (scaledHeight + 10);
          } else {
              yPos -= 10;
          }
      }
    } catch (e) {
      console.warn("Error embedding logo", e);
      yPos -= 10;
    }
  } else {
    yPos -= 10;
  }

  // --- HEADER ---
  drawCenteredText(config.businessName, fontBold, 16, accentColor);
  if (config.slogan) drawCenteredText(`"${config.slogan}"`, fontRegular, 9, rgb(0.4, 0.4, 0.4));

  yPos -= 5;
  drawCenteredText(config.address, fontRegular, 9);
  drawCenteredText(`Tel: ${config.phone}`, fontRegular, 9);
  if (config.email) drawCenteredText(config.email, fontRegular, 8);
  if (config.website) drawCenteredText(config.website, fontRegular, 8);
  if (config.rfc) drawCenteredText(`RFC: ${config.rfc}`, fontRegular, 9);

  yPos -= 5;
  drawDashedLine();

  // --- META INFO ---
  drawLeftRight('Folio:', sale.id, fontRegular, 10, true);
  drawLeftRight('Fecha:', new Date(sale.timestamp).toLocaleDateString(), fontRegular, 10);
  drawLeftRight('Hora:', new Date(sale.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}), fontRegular, 10);
  drawLeftRight('Cliente:', sale.customerAlias.substring(0, is58mm ? 12 : 18), fontRegular, 10, true);

  yPos -= 5;

  // --- TABLE HEADER ---
  const headerSize = fs(8);
  page.drawRectangle({
    x: margin,
    y: yPos - 2,
    width: contentWidth,
    height: 14,
    color: accentColor, 
    opacity: 0.1
  });

  page.drawText('CANT', { x: margin + 5, y: yPos, size: headerSize, font: fontBold, color: accentColor });
  page.drawText('DESCRIPCION', { x: margin + (is58mm ? 35 : 45), y: yPos, size: headerSize, font: fontBold, color: accentColor });
  const impHeaderWidth = fontBold.widthOfTextAtSize('IMPORTE', headerSize);
  page.drawText('IMPORTE', { x: ticketWidth - margin - impHeaderWidth - 5, y: yPos, size: headerSize, font: fontBold, color: accentColor });
  yPos -= 18;

  // --- ITEMS ---
  const itemSize = fs(10);
  const descSize = fs(9);
  sale.items.forEach(item => {
    // Cantidad
    page.drawText(item.quantity.toString(), { x: margin + 8, y: yPos, size: itemSize, font: fontBold });

    // Descripción
    const cleanName = sanitize(item.name);
    const maxChars = is58mm ? 12 : 20;
    const name = cleanName.length > maxChars ? cleanName.substring(0, maxChars) + '...' : cleanName;
    page.drawText(name, { x: margin + (is58mm ? 35 : 45), y: yPos, size: descSize, font: fontRegular });

    // Importe
    const totalItem = (item.quantity * item.price).toFixed(2);
    const totalItemWidth = fontRegular.widthOfTextAtSize(`$${totalItem}`, itemSize);
    page.drawText(`$${totalItem}`, { x: ticketWidth - margin - totalItemWidth, y: yPos, size: itemSize, font: fontRegular });

    yPos -= 15;
  });

  drawDashedLine();

  // --- TOTALS ---
  const drawTotalLine = (label: string, value: string, isBig = false) => {
    const safeLabel = sanitize(label);
    const safeValue = sanitize(value);

    const size = isBig ? fs(16) : fs(10);
    const font = isBig ? fontBold : fontRegular;
    const color = isBig ? accentColor : rgb(0,0,0);

    const labelWidth = font.widthOfTextAtSize(safeLabel, size);
    const valueWidth = font.widthOfTextAtSize(safeValue, size);

    const valueX = ticketWidth - margin - valueWidth;
    const labelX = valueX - labelWidth - 10;

    page.drawText(safeLabel, { x: labelX, y: yPos, size, font, color });
    page.drawText(safeValue, { x: valueX, y: yPos, size, font, color });
    yPos -= (size + 8);
  };

  drawTotalLine('TOTAL:', `$${sale.total.toFixed(2)}`, true);

  if (sale.paymentSplits && sale.paymentSplits.length > 0) {
     sale.paymentSplits.forEach(split => {
        drawTotalLine(`${split.method}:`, `$${split.amount.toFixed(2)}`);
     });
  } else {
     drawTotalLine('Su Pago:', `$${sale.paidAmount.toFixed(2)}`);
  }

  if (sale.change > 0) {
    drawTotalLine('Cambio:', `$${sale.change.toFixed(2)}`);
  } else if (sale.paidAmount < sale.total) {
    // Background for Debt warning
    page.drawRectangle({
        x: margin,
        y: yPos - 8,
        width: contentWidth,
        height: 20,
        color: accentColor,
    });

    page.drawText('SALDO PENDIENTE', { x: margin + 5, y: yPos + 2, size: fs(10), font: fontBold, color: rgb(1,1,1) });
    const debtStr = `$${(sale.total - sale.paidAmount).toFixed(2)}`;
    const debtW = fontBold.widthOfTextAtSize(debtStr, fs(10));
    page.drawText(debtStr, { x: ticketWidth - margin - debtW - 5, y: yPos + 2, size: fs(10), font: fontBold, color: rgb(1,1,1) });
    yPos -= 25;
  }

  // --- GARRAFONES RETURNED ---
  if (sale.emptyGarrafonsReturned > 0) {
    yPos -= 5;
    page.drawRectangle({
      x: margin + 10,
      y: yPos - 5,
      width: contentWidth - 20,
      height: 25,
      borderColor: accentColor,
      borderWidth: 1,
    });
    const text = `* ${sale.emptyGarrafonsReturned} Envases Recibidos *`;
    const textW = fontBold.widthOfTextAtSize(text, fs(10));
    page.drawText(text, { x: centerX - (textW/2), y: yPos + 5, size: fs(10), font: fontBold, color: accentColor });
    yPos -= 25;
  }

  // --- FOOTER & QR CODE ---
  if (config.showFooter !== false) {
      yPos -= 10;
      const footerSize = fs(9);

      if (config.footerMessage) {
        const words = sanitize(config.footerMessage).split(' ');
        let line = '';
        for (const word of words) {
            const testLine = line + word + ' ';
            const testWidth = fontRegular.widthOfTextAtSize(testLine, footerSize);
            if (testWidth > contentWidth) {
                drawCenteredText(line, fontRegular, footerSize);
                line = word + ' ';
            } else {
                line = testLine;
            }
        }
        drawCenteredText(line, fontRegular, footerSize);
      }

      if (config.extraNote) {
        drawCenteredText(sanitize(config.extraNote), fontRegular, fs(8), rgb(0.5, 0.5, 0.5));
      }

      drawCenteredText('*** GRACIAS POR SU PREFERENCIA ***', fontBold, footerSize);
  }

  // QR Code at the bottom
  if (config.showQr !== false) {
      yPos -= 10;
      try {
        const qrData = btoa(`AQUA-PRO-SECURE|${JSON.stringify({ id: sale.id, total: sale.total })}`);
        const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(qrData)}`;

        // Fetch image data
        const qrResponse = await fetch(qrUrl);
        const qrArrayBuffer = await qrResponse.arrayBuffer();
        const qrImage = await pdfDoc.embedPng(qrArrayBuffer);

        const qrSize = is58mm ? 80 : 100;

        page.drawImage(qrImage, {
            x: centerX - (qrSize / 2),
            y: yPos - qrSize,
            width: qrSize,
            height: qrSize
        });
      } catch (e) {
        console.warn("Could not embed QR code in PDF", e);
        // Draw placeholder
        yPos -= 20;
        drawCenteredText('[ CODIGO QR NO DISPONIBLE ]', fontCourier, 8);
      }
  }

  return await pdfDoc.save();
}

import React, { useState, useMemo } from 'react';
import { Customer, Product, CartItem, Order, Vehicle } from '../types';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';
import { optimizeRoute } from '../services/geminiService';

interface OrdersModuleProps {
  onBack: () => void;
  onProcessOrder: (order: Order) => void;
}

export const OrdersModule: React.FC<OrdersModuleProps> = ({ onBack, onProcessOrder }) => {
  const { customers, products, orders, addOrder, updateOrder, vehicles, setOrders } = useERPData();
  const [activeTab, setActiveTab] = useState<'new' | 'pending' | 'assigned'>('pending');

  // --- STATE: NEW ORDER ---
  const [customer, setCustomer] = useState<Customer | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [search, setSearch] = useState('');
  const [isUrgent, setIsUrgent] = useState(false);
  const [scheduleDate, setScheduleDate] = useState<'today' | 'tomorrow' | string>('today');

  // --- STATE: MANAGEMENT ---
  const [optimizing, setOptimizing] = useState(false);
  const [selectedOrderIds, setSelectedOrderIds] = useState<Set<string>>(new Set());
  const [showAssignModal, setShowAssignModal] = useState(false);

  // --- COMPUTED ---
  // Fix: Total respects customer special price logic (ID '1' is Garrafón)
  const total = cart.reduce((sum, item) => {
    const price = (customer?.specialPrice && item.id === '1') ? customer.specialPrice : item.price;
    return sum + (price * item.quantity);
  }, 0);

  // --- ACTIONS: NEW ORDER ---
  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === product.id);
      if (existing) return prev.map(i => i.id === product.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.filter(i => i.id !== id));
  };

  const handleCreateOrder = () => {
    if (!customer || cart.length === 0) return alert("Selecciona cliente y productos.");

    // Calculate timestamp based on schedule
    const now = new Date();
    let targetDate = new Date();
    if (scheduleDate === 'tomorrow') {
        targetDate.setDate(now.getDate() + 1);
    } else if (scheduleDate !== 'today') {
        targetDate = new Date(scheduleDate); // YYYY-MM-DD
        // Set to 9 AM
        targetDate.setHours(9, 0, 0, 0);
    }

    addOrder({
      customerId: customer.id,
      customerAlias: customer.alias,
      items: cart,
      total,
      status: 'pendiente',
      priority: isUrgent ? 2 : 1,
      timestamp: targetDate.getTime()
    });

    // Reset Form
    setCustomer(null);
    setCart([]);
    setSearch('');
    setIsUrgent(false);
    setScheduleDate('today');
    setActiveTab('pending');
  };

  // --- ACTIONS: BULK MANAGEMENT ---
  const toggleOrderSelection = (id: string) => {
    const newSet = new Set(selectedOrderIds);
    if (newSet.has(id)) newSet.delete(id);
    else newSet.add(id);
    setSelectedOrderIds(newSet);
  };

  const selectAllPending = () => {
    const pendingIds = orders.filter(o => o.status === 'pendiente').map(o => o.id);
    if (selectedOrderIds.size === pendingIds.length) {
        setSelectedOrderIds(new Set());
    } else {
        setSelectedOrderIds(new Set(pendingIds));
    }
  };

  const handleAssignToVehicle = (vehicleId: string) => {
    const idsToAssign = Array.from(selectedOrderIds);
    if (idsToAssign.length === 0) return;

    // Bulk update logic
    const updatedOrders = orders.map(o => {
        if (idsToAssign.includes(o.id)) {
            return { ...o, vehicleId, status: 'asignado' as const };
        }
        return o;
    });

    setOrders(updatedOrders);
    setSelectedOrderIds(new Set());
    setShowAssignModal(false);
  };

  const handleOptimize = async () => {
    const pendingOrders = orders.filter(o => o.status === 'pendiente');
    if (pendingOrders.length < 2) return alert("Necesitas al menos 2 pedidos pendientes.");

    setOptimizing(true);
    const result = await optimizeRoute(pendingOrders);

    if (result.orderedIds) {
      const optimized = [...orders].sort((a, b) => {
        const idxA = result.orderedIds.indexOf(a.id);
        const idxB = result.orderedIds.indexOf(b.id);
        // If not in optimized list, keep original relative order or put at end
        if (idxA === -1 && idxB === -1) return 0;
        if (idxA === -1) return 1;
        if (idxB === -1) return -1;
        return idxA - idxB;
      });
      setOrders(optimized);
      alert("¡Ruta optimizada por IA!");
    }
    setOptimizing(false);
  };

  // --- RENDER HELPERS ---
