                                <div className="flex items-center gap-4">
                                    <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-xl ${isFull ? 'bg-slate-200 text-slate-400' : 'bg-indigo-100 text-indigo-600'}`}>
