export const POSModule: React.FC<{ onBack: () => void; user: Employee; initialOrder?: Order | null; onClearInitialOrder?: () => void; }> = ({ onBack, user, initialOrder, onClearInitialOrder }) => {
  const { products, customers, sales, addSale, ticketConfig, vehicles, updateOrder } = useERPData();
  const [activeTab, setActiveTab] = useState<'sell' | 'history'>('sell');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [customer, setCustomer] = useState<Customer | null>(null);
  const [search, setSearch] = useState('');
  const [vacios, setVacios] = useState(0);
  const [selectedSource, setSelectedSource] = useState<string>('plant');
  const [showPaymentModal, setShowPaymentModal] = useState(false);
  const [viewingTicket, setViewingTicket] = useState<Sale | null>(null);
  const [linkedOrderId, setLinkedOrderId] = useState<string | null>(null);
  const [originalOrder, setOriginalOrder] = useState<Order | null>(null);

  // Load Order Data
  useEffect(() => {
    if (initialOrder) {
      let client = customers.find(c => c.id === initialOrder.customerId);
      if (!client) {
         // Fallback if client isn't in DB yet
         client = { 
           id: initialOrder.customerId, 
           name: initialOrder.customerAlias, 
           alias: initialOrder.customerAlias, 
           balance: 0, 
           phone: '', 
           garrafonType: 'Generico' 
         } as Customer;
      }
      setCustomer(client);
      setSearch(client.alias);
      setCart(initialOrder.items);

      // Auto-load jug quantity into 'vacios' (1:1 exchange assumption) to ensure seamless flow
      const initialJugs = initialOrder.items
        .filter(i => i.name.toLowerCase().includes('garraf') || i.category === 'Agua')
        .reduce((acc, i) => acc + i.quantity, 0);
      setVacios(initialJugs);

      if (initialOrder.vehicleId && vehicles.some(v => v.id === initialOrder.vehicleId)) setSelectedSource(initialOrder.vehicleId);
      setLinkedOrderId(initialOrder.id);
      setOriginalOrder(initialOrder);

      // Crucial: Clear order from App state to prevent stale data re-load, 
      // but ensure POS doesn't unmount (handled in App.tsx by static key)
      if (onClearInitialOrder) onClearInitialOrder();
    }
  }, [initialOrder, customers, vehicles, onClearInitialOrder]);

  // SPECIAL PRICE LOGIC: Always respects customer specific price for ID 1 (Garrafon)
  const total = cart.reduce((sum, item) => {
    const price = (customer?.specialPrice && item.id === '1') ? customer.specialPrice : item.price;
    return sum + (price * item.quantity);
  }, 0);

  useEffect(() => {
    // Only auto-update vacios if user hasn't started messing with it manually OR if it's the initial load
    // The previous useEffect handles initial load from Order.
    // This effect handles dynamic cart changes.
    // We check if it's NOT a linked order to avoid overriding the initial logic, or simply sync
    if (!linkedOrderId) {
        const garrafonesInCart = cart.filter(i => i.name.toLowerCase().includes('garraf') || i.category === 'Agua').reduce((acc, i) => acc + i.quantity, 0);
        if (cart.length > 0 && vacios === 0) setVacios(garrafonesInCart);
        else if (cart.length === 0) setVacios(0);
    }
  }, [cart, linkedOrderId]);

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === product.id);
      if (existing) return prev.map(i => i.id === product.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const decreaseQuantity = (productId: string) => {
    setCart(prev => prev.map(item => item.id === productId ? { ...item, quantity: Math.max(0, item.quantity - 1) } : item).filter(item => item.quantity > 0));
  };

  const handlePreCheckout = () => {
    if (!customer) return alert("Selecciona un cliente.");
    if (cart.length === 0) return alert("Carrito vacío.");

    // VALIDACIÓN DE STOCK (Solo si es vehículo)
    if (selectedSource !== 'plant') {
        const vehicle = vehicles.find(v => v.id === selectedSource);
        if (vehicle) {
            const currentInv = vehicle.inventory || [];

            const missing = cart.filter(item => {
                const stockItem = currentInv.find(i => i.id === item.id);
                // Es nulo si no existe el item o si la cantidad es menor a la requerida
                return !stockItem || stockItem.quantity < item.quantity;
            });

            if (missing.length > 0) {
                const names = missing.map(m => `- ${m.name}`).join('\n');
                const confirmSale = window.confirm(
                    `⚠️ STOCK INSUFICIENTE EN UNIDAD\n\n` +
                    `El vehículo no tiene carga suficiente de:\n${names}\n\n` +
                    `¿Deseas forzar la venta (Stock Negativo)?`
                );
                if (!confirmSale) return;
            }
        }
    }

    setShowPaymentModal(true);
  };

  const handleConfirmPayment = (cash: number, transfer: number, card: number) => {
    if(!customer) return;
    const totalPaid = cash + transfer + card;
    const splits: PaymentSplit[] = [];
    if (cash > 0) splits.push({ method: 'Efectivo', amount: cash });
    if (transfer > 0) splits.push({ method: 'Transferencia', amount: transfer });
    if (card > 0) splits.push({ method: 'Tarjeta', amount: card });

    // La validación principal ya se hizo en handlePreCheckout
    // Aquí solo procesamos la venta (incluso si genera negativo)
    const sale = addSale(customer.id, cart, total, totalPaid, splits, vacios, undefined, selectedSource === 'plant' ? undefined : selectedSource);

    if (originalOrder) {
       updateOrder({ ...originalOrder, status: 'entregado' });
    }

    setShowPaymentModal(false);
    setViewingTicket(sale);
  };

  const resetPOS = () => {
    setViewingTicket(null);
    setCart([]);
    setCustomer(null);
    setSearch('');
    setVacios(0);
    setLinkedOrderId(null);
    setOriginalOrder(null);
    setActiveTab('sell');
  };

  return (
    <div className="h-full flex flex-col animate-fadeIn bg-transparent pb-24 overflow-hidden relative">
      <ModuleHeader title="Punto de Venta" onBack={onBack} />

      <div className="px-6 flex gap-2 mb-4 shrink-0">
        <button onClick={() => setActiveTab('sell')} className={`flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'sell' ? 'bg-sky-600 text-white shadow-lg' : 'bg-white text-slate-400'}`}>Venta</button>
        <button onClick={() => setActiveTab('history')} className={`flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'history' ? 'bg-sky-600 text-white shadow-lg' : 'bg-white text-slate-400'}`}>Historial</button>
      </div>

      {activeTab === 'sell' ? (
        <div className="flex-1 overflow-y-auto px-6 space-y-6 pb-32 no-scrollbar">

          {linkedOrderId && (
            <div className="bg-amber-100 text-amber-700 p-4 rounded-[1.5rem] border border-amber-200 flex justify-between items-center shadow-sm">
               <span className="text-xs font-black uppercase tracking-wide flex items-center gap-2"><i className="fas fa-clipboard-check"></i> Pedido: {linkedOrderId}</span>
               <button onClick={resetPOS} className="w-8 h-8 bg-white rounded-full text-amber-500 flex items-center justify-center shadow-sm active:scale-90 transition-transform"><i className="fas fa-times"></i></button>
            </div>
          )}

          <div className="overflow-x-auto pb-2 no-scrollbar">
            <div className="flex gap-2 min-w-max">
              <button 
                onClick={() => setSelectedSource('plant')}
                className={`px-5 py-3 rounded-2xl text-[10px] font-black uppercase flex items-center gap-2 transition-all ${selectedSource === 'plant' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-200' : 'bg-white text-slate-400 border border-slate-100'}`}
              >
                <i className="fas fa-store"></i> Planta
              </button>
              {vehicles.map(v => (
                <button 
                  key={v.id}
                  onClick={() => setSelectedSource(v.id)}
                  className={`px-5 py-3 rounded-2xl text-[10px] font-black uppercase flex items-center gap-2 transition-all ${selectedSource === v.id ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-200' : 'bg-white text-slate-400 border border-slate-100'}`}
                >
                  <i className="fas fa-truck"></i> {v.plate}
                </button>
              ))}
            </div>
          </div>

          <div className="relative z-20">
            <input type="text" placeholder="Buscar Cliente..." className="w-full bg-white border-none rounded-[1.5rem] py-4 px-6 shadow-sm outline-none font-bold text-slate-700 placeholder-slate-300 focus:ring-2 ring-sky-300 transition-all" value={search} onChange={e => setSearch(e.target.value)} />
            {search && !customer && (
              <div className="absolute top-full left-0 right-0 bg-white shadow-xl rounded-[1.5rem] mt-2 overflow-hidden border border-slate-100 max-h-48 overflow-y-auto z-50">
                {customers.filter(c => c.alias.toLowerCase().includes(search.toLowerCase())).map(c => (
                  <button key={c.id} onClick={() => { setCustomer(c); setSearch(c.alias); }} className="w-full text-left p-4 hover:bg-sky-50 border-b border-slate-50 last:border-none">
                    <span className="text-slate-800 font-bold text-sm block">{c.alias}</span>
                  </button>
                ))}
              </div>
            )}
            {customer && (
              <div className="mt-2 bg-white p-3 rounded-[1.5rem] shadow-sm border border-sky-100 flex justify-between items-center animate-fadeIn">
                <div className="flex items-center gap-3">
                   <div className="w-10 h-10 bg-sky-100 rounded-full flex items-center justify-center text-sky-600"><i className="fas fa-user-check"></i></div>
                   <div>
                      <span className="font-black text-slate-800 text-sm block">{customer.alias}</span>
                      {customer.specialPrice && <span className="text-[9px] text-amber-500 font-bold uppercase">Precio Esp: ${customer.specialPrice}</span>}
                   </div>
                </div>
                <button onClick={() => {setCustomer(null); setSearch('');}} className="w-8 h-8 flex items-center justify-center text-rose-400 bg-rose-50 rounded-full hover:bg-rose-100 transition-colors"><i className="fas fa-times"></i></button>
              </div>
            )}
          </div>

          <div className="grid grid-cols-2 gap-3">
            {products.filter(p => p.category !== 'Insumos').map(p => {
               const inCart = cart.find(i => i.id === p.id)?.quantity || 0;
               // Determine price to show (Customer specific or default)
               const effectivePrice = (customer?.specialPrice && p.id === '1') ? customer.specialPrice : p.price;
               const isSpecial = (customer?.specialPrice && p.id === '1');

               return (
                <button key={p.id} onClick={() => addToCart(p)} className={`p-4 rounded-[1.8rem] text-left transition-all relative overflow-hidden group ${inCart > 0 ? 'bg-gradient-to-br from-sky-500 to-indigo-600 text-white shadow-lg shadow-sky-300' : 'bg-white text-slate-600 shadow-sm border border-white'}`}>
                  <div className="relative z-10">
                    <p className={`text-[9px] font-black uppercase mb-1 tracking-wide ${inCart > 0 ? 'text-sky-100' : 'text-slate-400'}`}>{p.category}</p>
                    <h4 className="font-bold text-sm leading-tight mb-2 pr-4">{p.name.replace('Garrafón', 'G.')}</h4>
                    <div className="flex items-center gap-1">
                        <p className="text-lg font-black">${effectivePrice}</p>
                        {isSpecial && <i className={`fas fa-tag text-[10px] ${inCart > 0 ? 'text-amber-300' : 'text-amber-500'}`}></i>}
                    </div>
                  </div>
                  {inCart > 0 && (
                    <div className="absolute top-3 right-3 w-8 h-8 bg-white text-sky-600 rounded-full flex items-center justify-center font-black text-sm shadow-sm animate-bounce">
                      {inCart}
                    </div>
                  )}
                  <div className={`absolute -bottom-4 -right-4 w-16 h-16 rounded-full ${inCart > 0 ? 'bg-white/10' : 'bg-slate-50'} blur-xl`}></div>
                </button>
               );
            })}
          </div>

          {cart.length > 0 && (
            <div className="bg-white rounded-[2rem] p-5 shadow-lg shadow-slate-100/50 border border-white animate-slideUp">
               <div className="flex justify-between items-center mb-4">
                  <h4 className="text-xs font-black text-slate-400 uppercase tracking-widest">Resumen</h4>
                  <button onClick={() => setCart([])} className="text-[10px] text-rose-500 font-bold uppercase hover:underline">Vaciar Carrito</button>
               </div>

               <div className="space-y-2 mb-6">
                 {cart.map(i => (
                   <div key={i.id} className="flex justify-between items-center py-2 border-b border-slate-50 last:border-none">
                      <div className="flex items-center gap-3">
                         <div className="flex items-center gap-2 bg-slate-50 rounded-xl p-1">
                            <button onClick={() => decreaseQuantity(i.id)} className="w-7 h-7 flex items-center justify-center bg-white rounded-lg shadow-sm text-slate-400 font-bold hover:text-sky-500 transition-colors">-</button>
                            <span className="text-xs font-black w-5 text-center text-slate-700">{i.quantity}</span>
                            <button onClick={() => addToCart(i)} className="w-7 h-7 flex items-center justify-center bg-sky-500 text-white rounded-lg shadow-sm font-bold hover:bg-sky-600 transition-colors">+</button>
                         </div>
                         <span className="text-xs font-bold text-slate-700 truncate max-w-[120px]">{i.name}</span>
                      </div>
                      <span className="text-sm font-black text-slate-800">${(( (customer?.specialPrice && i.id === '1') ? customer.specialPrice : i.price ) * i.quantity).toFixed(2)}</span>
                   </div>
                 ))}
               </div>

               <div className="bg-slate-50 p-4 rounded-[1.5rem] flex justify-between items-center mb-2">
                  <span className="text-[10px] font-bold text-slate-500 uppercase tracking-wide">Envases Vacíos Recibidos</span>
                  <div className="flex items-center gap-3">
                     <button onClick={() => setVacios(Math.max(0, vacios - 1))} className="w-8 h-8 bg-white rounded-full shadow-sm text-slate-400 font-bold hover:text-sky-500">-</button>
                     <span className="font-black text-slate-800 text-lg">{vacios}</span>
                     <button onClick={() => setVacios(vacios + 1)} className="w-8 h-8 bg-sky-500 rounded-full shadow-lg shadow-sky-200 text-white font-bold hover:bg-sky-600 active:scale-90 transition-transform">+</button>
                  </div>
               </div>
            </div>
          )}
        </div>
      ) : (
        <div className="flex-1 overflow-y-auto px-6 space-y-3 pb-10 no-scrollbar">
           {sales.map(s => (
             <RoundedCard key={s.id} className="p-4 flex justify-between items-center">
                <div className="flex items-center gap-4">
                   <div className="w-12 h-12 bg-slate-100 rounded-2xl flex items-center justify-center text-slate-400 text-lg">
                      <i className="fas fa-receipt"></i>
                   </div>
                   <div>
                      <h4 className="font-black text-slate-800 text-sm">{s.customerAlias}</h4>
                      <p className="text-[10px] text-slate-400 font-bold uppercase">{new Date(s.timestamp).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}</p>
                   </div>
                </div>
                <div className="text-right">
                   <span className="block font-black text-slate-800 text-lg">${s.total}</span>
                   <button onClick={() => setViewingTicket(s)} className="text-[10px] text-sky-500 font-bold uppercase bg-sky-50 px-3 py-1 rounded-lg mt-1 active:bg-sky-100">Ver Ticket</button>
                </div>
             </RoundedCard>
           ))}
        </div>
      )}

      {activeTab === 'sell' && (
        <div className="fixed bottom-0 left-0 right-0 p-6 bg-white/80 backdrop-blur-md border-t border-white/50 shadow-[0_-10px_30px_rgba(0,0,0,0.05)] z-50">
          <ActionButton onClick={handlePreCheckout} disabled={!customer || cart.length === 0}>
             <div className="flex justify-between w-full px-4 items-center">
                <span>{linkedOrderId ? 'Finalizar Entrega' : 'Cobrar'}</span>
                <span className="bg-white/20 px-3 py-1 rounded-xl text-sm font-black backdrop-blur-sm shadow-sm">${total.toFixed(2)}</span>
             </div>
          </ActionButton>
        </div>
      )}

      {showPaymentModal && <PaymentModal total={total} onConfirm={handleConfirmPayment} onCancel={() => setShowPaymentModal(false)} />}

      {viewingTicket && (
        <TicketModal 
          sale={viewingTicket} 
          config={ticketConfig} 
          onClose={() => setViewingTicket(null)} 
          onWhatsApp={() => {
             const phone = customers.find(c => c.id === viewingTicket.customerId)?.phone;
             if(phone) window.open(`https://wa.me/52${phone.replace(/\D/g,'')}?text=Hola, adjunto tu ticket ${viewingTicket.id}. Total: $${viewingTicket.total}`, '_blank');
             else alert("Sin teléfono registrado");
          }}
          onNewSale={resetPOS}
          onFinish={() => { setViewingTicket(null); setActiveTab('history'); }}
        />
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';
import { Vehicle, Product, FuelRecord } from '../types';

const LoadingModal = ({ vehicleId, onClose }: { vehicleId: string, onClose: () => void }) => {
  const { vehicles, products, loadVehicle } = useERPData();
  const vehicle = vehicles.find(v => v.id === vehicleId);

  if (!vehicle) return null;

  return (
    <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[200] flex items-center justify-center p-4 animate-fadeIn">
      <div className="bg-white w-full max-w-md rounded-[2.5rem] p-6 shadow-2xl max-h-[85vh] flex flex-col relative overflow-hidden">
        <div className="absolute top-0 left-0 right-0 h-2 bg-gradient-to-r from-sky-400 to-indigo-500"></div>
        <div className="flex justify-between items-center mb-6 shrink-0">
          <div>
            <h3 className="text-xl font-black text-sky-900">Cargar Unidad</h3>
            <p className="text-[10px] text-sky-400 font-bold uppercase tracking-wide">{vehicle.description}</p>
          </div>
          <button onClick={onClose} className="w-10 h-10 bg-slate-100 rounded-full flex items-center justify-center text-slate-400 hover:bg-slate-200 transition-colors"><i className="fas fa-times"></i></button>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar space-y-3 pr-1 pb-4">
          {products.filter(p => p.category !== 'Insumos').map(p => {
            const inVehicle = vehicle.inventory?.find(i => i.id === p.id)?.quantity || 0;
            return (
              <div key={p.id} className="bg-sky-50 p-4 rounded-[1.5rem] flex flex-col gap-3 border border-sky-100 relative overflow-hidden">
                <div className="flex justify-between items-center relative z-10">
                  <p className="text-[10px] font-black text-sky-900 uppercase">{p.name}</p>
                  <span className="text-[8px] bg-white px-2 py-1 rounded-lg text-sky-400 font-bold border border-sky-100 shadow-sm">Planta: {p.stock}</span>
                </div>

                <div className="flex items-center justify-between bg-white rounded-2xl p-1.5 shadow-sm relative z-10">
                  <button onClick={() => loadVehicle(vehicle.id, p, -1)} className="w-10 h-10 bg-sky-50 rounded-xl text-sky-600 font-black active:scale-90 transition-transform text-lg">-</button>
                  <div className="flex flex-col items-center">
                     <span className="font-black text-sky-900 text-lg leading-none">{inVehicle}</span>
                     <span className="text-[7px] text-sky-300 font-bold uppercase tracking-widest">Cargados</span>
                  </div>
                  <button onClick={() => loadVehicle(vehicle.id, p, 1)} className="w-10 h-10 bg-sky-600 rounded-xl text-white font-black active:scale-90 transition-transform text-lg shadow-lg shadow-sky-200">+</button>
                </div>

                {/* Visual fill based on some arbitrary max per item for effect */}
                <div className="absolute bottom-0 left-0 h-1 bg-sky-200" style={{ width: `${Math.min(inVehicle * 2, 100)}%` }}></div>
              </div>
            );
          })}
        </div>

        <div className="mt-4 pt-4 border-t border-sky-100 flex justify-between items-center shrink-0">
           <div>
             <p className="text-[9px] font-black text-sky-400 uppercase tracking-widest">Capacidad Total</p>
             <p className="text-2xl font-black text-sky-900 tracking-tighter">{vehicle.currentLoad} <span className="text-sm text-slate-300">/ {vehicle.loadCapacity}</span></p>
           </div>
           <button onClick={onClose} className="px-8 py-4 bg-emerald-500 text-white rounded-[1.5rem] font-black text-xs uppercase shadow-lg shadow-emerald-200 active:scale-95 transition-all">
             Listo
           </button>
        </div>
      </div>
    </div>
  );
};

const FuelModal = ({ vehicleId, onClose }: { vehicleId: string, onClose: () => void }) => {
  const { vehicles, addFuelRecord } = useERPData();
  const vehicle = vehicles.find(v => v.id === vehicleId);
  const [fuelForm, setFuelForm] = useState<Partial<FuelRecord>>({ mileage: undefined, liters: undefined, cost: undefined, notes: '' });

  if (!vehicle) return null;

  const handleAddFuel = () => {
    if (!fuelForm.mileage || !fuelForm.liters || !fuelForm.cost) {
      alert("Por favor completa los campos.");
      return;
    }
    addFuelRecord(vehicleId, {
      id: Date.now().toString(),
      date: Date.now(),
      mileage: fuelForm.mileage,
      liters: fuelForm.liters,
      cost: fuelForm.cost,
      notes: fuelForm.notes
    });
    setFuelForm({ mileage: undefined, liters: undefined, cost: undefined, notes: '' });
    alert("Carga registrada.");
  };

  const history = vehicle.fuelHistory || [];
  const costPerLiter = (fuelForm.cost && fuelForm.liters) ? (fuelForm.cost / fuelForm.liters) : 0;

  return (
    <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[200] flex items-center justify-center p-4 animate-fadeIn">
      <div className="bg-white w-full max-w-md rounded-[2.5rem] p-6 shadow-2xl max-h-[85vh] overflow-y-auto no-scrollbar">
        <div className="flex justify-between items-center mb-6">
          <div className="flex items-center gap-3">
            <div className="w-12 h-12 bg-amber-100 text-amber-500 rounded-2xl flex items-center justify-center text-xl shadow-sm">
              <i className="fas fa-gas-pump"></i>
            </div>
            <div>
              <h3 className="text-lg font-black text-sky-900">Combustible</h3>
              <p className="text-[10px] text-sky-400 font-bold uppercase">{vehicle.plate}</p>
            </div>
          </div>
          <button onClick={onClose} className="w-10 h-10 bg-slate-100 rounded-full flex items-center justify-center text-slate-400 hover:bg-slate-200 transition-colors"><i className="fas fa-times"></i></button>
        </div>

        <div className="bg-slate-50 p-5 rounded-[2rem] border border-slate-100 mb-6">
           <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Nueva Carga</h4>
           <div className="grid grid-cols-2 gap-3 mb-3">
             <div className="bg-white p-3 rounded-2xl shadow-sm">
               <label className="text-[8px] font-black text-slate-400 uppercase block mb-1">Kilometraje</label>
               <input type="number" className="w-full outline-none text-sm font-bold text-slate-700 bg-transparent" placeholder="KM" value={fuelForm.mileage || ''} onChange={e => setFuelForm({...fuelForm, mileage: Number(e.target.value)})}/>
             </div>
             <div className="bg-white p-3 rounded-2xl shadow-sm">
               <label className="text-[8px] font-black text-slate-400 uppercase block mb-1">Litros</label>
               <input type="number" className="w-full outline-none text-sm font-bold text-slate-700 bg-transparent" placeholder="L" value={fuelForm.liters || ''} onChange={e => setFuelForm({...fuelForm, liters: Number(e.target.value)})}/>
             </div>
           </div>
           <div className="bg-white p-3 rounded-2xl shadow-sm mb-4 relative">
             <label className="text-[8px] font-black text-slate-400 uppercase block mb-1">Costo Total ($)</label>
             <input type="number" className="w-full outline-none text-lg font-black text-emerald-600 bg-transparent" placeholder="0.00" value={fuelForm.cost || ''} onChange={e => setFuelForm({...fuelForm, cost: Number(e.target.value)})}/>
             {costPerLiter > 0 && <span className="absolute right-3 top-1/2 -translate-y-1/2 text-[9px] font-bold text-slate-400 bg-slate-50 px-2 py-1 rounded">${costPerLiter.toFixed(2)}/L</span>}
           </div>
           <button onClick={handleAddFuel} className="w-full py-4 bg-amber-500 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-lg shadow-amber-200 active:scale-95 transition-all">Registrar</button>
        </div>

        <div>
          <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 ml-2">Historial</h4>
          <div className="space-y-2 max-h-60 overflow-y-auto no-scrollbar">
             {history.length === 0 ? <p className="text-center text-[10px] text-slate-400 py-4 italic">Sin registros previos.</p> : history.map(r => (
               <div key={r.id} className="bg-white p-3 rounded-2xl shadow-sm border border-slate-50 flex justify-between items-center">
                  <div>
                     <p className="text-[10px] font-black text-slate-400 uppercase">{new Date(r.date).toLocaleDateString()}</p>
                     <p className="text-xs font-bold text-slate-700">{r.mileage.toLocaleString()} km</p>
                  </div>
                  <div className="text-right">
                     <p className="text-sm font-black text-emerald-600">${r.cost.toLocaleString()}</p>
                     <p className="text-[9px] font-bold text-amber-500">{r.liters} L</p>
                  </div>
               </div>
             ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export const LogisticsModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const { vehicles, setVehicles, deleteVehicle } = useERPData();
  const [editingVehicle, setEditingVehicle] = useState<Partial<Vehicle> | null>(null);
  const [loadingVehicleId, setLoadingVehicleId] = useState<string | null>(null);
  const [fuelVehicleId, setFuelVehicleId] = useState<string | null>(null);

  const saveVehicle = () => {
    if (!editingVehicle?.plate || !editingVehicle?.description) return alert("Completa los datos.");
    setVehicles(prev => {
      const exists = prev.find(v => v.id === editingVehicle.id);
      if (exists) return prev.map(v => v.id === editingVehicle.id ? { ...v, ...editingVehicle } as Vehicle : v);
      return [...prev, { ...editingVehicle, id: editingVehicle.id || Date.now().toString(), currentLoad: 0, inventory: [], fuelHistory: [] } as Vehicle];
    });
    setEditingVehicle(null);
  };

  if (editingVehicle) {
    return (
      <div className="h-full bg-sky-50 animate-fadeIn overflow-y-auto no-scrollbar pb-32">
        <ModuleHeader title={editingVehicle.id ? "Editar Unidad" : "Nueva Unidad"} onBack={() => setEditingVehicle(null)} />
        <div className="px-6 space-y-5">
           <input className="w-full bg-white p-5 rounded-[2rem] shadow-sm outline-none font-bold text-sky-900 text-sm focus:ring-2 ring-sky-300" placeholder="Placa / Identificador" value={editingVehicle.plate || ''} onChange={e => setEditingVehicle({...editingVehicle, plate: e.target.value})}/>
           <input className="w-full bg-white p-5 rounded-[2rem] shadow-sm outline-none font-bold text-sky-900 text-sm focus:ring-2 ring-sky-300" placeholder="Descripción (Ej: Nissan Blanca)" value={editingVehicle.description || ''} onChange={e => setEditingVehicle({...editingVehicle, description: e.target.value})}/>
           <div className="bg-white p-5 rounded-[2rem] shadow-sm">
              <label className="text-[10px] font-black text-sky-400 uppercase mb-2 block">Capacidad de Carga</label>
              <input type="number" className="w-full bg-slate-50 p-4 rounded-2xl outline-none font-black text-sky-600 text-2xl text-center" value={editingVehicle.loadCapacity || ''} onChange={e => setEditingVehicle({...editingVehicle, loadCapacity: Number(e.target.value)})}/>
           </div>

           <ActionButton onClick={saveVehicle}>Guardar Unidad</ActionButton>

           {editingVehicle.id && (
             <button onClick={() => { if (confirm("¿Eliminar unidad?")) { deleteVehicle(editingVehicle.id!); setEditingVehicle(null); } }} className="w-full py-4 text-rose-500 font-black uppercase text-[10px] tracking-widest bg-rose-50 rounded-[2rem] border border-rose-100 shadow-sm active:scale-95 transition-all">
                Eliminar Unidad
             </button>
           )}
        </div>
      </div>
    );
  }

  return (
    <div className="h-full bg-sky-50 overflow-y-auto no-scrollbar pb-24 relative">
      <ModuleHeader title="Gestión de Flota" onBack={onBack} />
      <div className="px-6 space-y-6">
        {vehicles.map(v => (
          <RoundedCard key={v.id} className="relative overflow-hidden border-none shadow-xl bg-white group active:scale-[0.99] transition-all p-0">
             <div className="p-6 pb-4">
               <div className="flex justify-between items-start mb-6">
                 <div className="flex gap-4">
                   <div className="w-14 h-14 bg-gradient-to-br from-sky-700 to-slate-800 text-white rounded-[1.5rem] flex items-center justify-center text-2xl shadow-lg shadow-slate-300">
                      <i className="fas fa-truck-pickup"></i>
                   </div>
                   <div>
                     <span className="text-[10px] font-black text-sky-400 uppercase tracking-widest leading-none block mb-1">{v.plate}</span>
                     <h3 className="text-xl font-black text-sky-900 leading-tight">{v.description}</h3>
                   </div>
                 </div>
                 <div className="flex gap-2">
                   <button onClick={() => setFuelVehicleId(v.id)} className="w-10 h-10 bg-amber-50 text-amber-500 rounded-full flex items-center justify-center hover:bg-amber-100 transition-colors shadow-sm"><i className="fas fa-gas-pump"></i></button>
                   <button onClick={() => setEditingVehicle(v)} className="w-10 h-10 bg-sky-50 text-sky-400 rounded-full flex items-center justify-center hover:bg-sky-100 transition-colors"><i className="fas fa-pen"></i></button>
                 </div>
               </div>

               <div className="flex items-end justify-between mb-4">
                 <div>
                   <p className="text-[10px] font-black text-sky-400 uppercase tracking-tighter mb-1">Carga Actual</p>
                   <p className="text-4xl font-black text-sky-600 tracking-tighter">{v.currentLoad} <span className="text-xs font-bold text-sky-300 ml-1">/{v.loadCapacity}</span></p>
                 </div>
                 <button onClick={() => setLoadingVehicleId(v.id)} className="px-6 py-3 bg-sky-600 text-white rounded-2xl font-black text-[10px] uppercase shadow-lg shadow-sky-200 active:scale-95 transition-all flex items-center gap-2">
                   <i className="fas fa-boxes-packing"></i> Cargar
                 </button>
               </div>

               {/* Inventory Tags */}
               <div className="flex flex-wrap gap-2 mb-5">
                 {(!v.inventory || v.inventory.length === 0) ? (
                   <span className="text-[9px] font-bold text-slate-300 italic px-2">Unidad vacía</span>
                 ) : (
                   v.inventory.map(item => (
                     <span key={item.id} className="bg-sky-50 text-sky-700 text-[8px] font-bold px-2 py-1 rounded-lg border border-sky-100 uppercase tracking-tight">
                       {item.quantity}x {item.name.split(' ')[0]}
                     </span>
                   ))
                 )}
               </div>

               {/* Gradient Progress Bar */}
               <div className="w-full bg-slate-100 h-2.5 rounded-full overflow-hidden">
                 <div className="h-full bg-gradient-to-r from-sky-400 to-indigo-500 transition-all duration-700 ease-out shadow-[0_0_10px_rgba(99,102,241,0.5)]" style={{ width: `${Math.min((v.currentLoad/v.loadCapacity)*100, 100)}%` }}></div>
               </div>
             </div>
          </RoundedCard>
        ))}

        <button onClick={() => setEditingVehicle({})} className="w-full py-7 border-2 border-dashed border-sky-200 rounded-[2.5rem] text-sky-400 font-black text-sm uppercase hover:bg-white hover:text-sky-600 transition-all flex items-center justify-center gap-2">
          <i className="fas fa-plus"></i> Nueva Unidad
        </button>
      </div>

      {loadingVehicleId && <LoadingModal vehicleId={loadingVehicleId} onClose={() => setLoadingVehicleId(null)} />}
      {fuelVehicleId && <FuelModal vehicleId={fuelVehicleId} onClose={() => setFuelVehicleId(null)} />}
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Customer, Product, CartItem, Order, Vehicle } from '../types';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';
import { optimizeRoute } from '../services/geminiService';

interface OrdersModuleProps {
  onBack: () => void;
  onProcessOrder: (order: Order) => void;
}

export const OrdersModule: React.FC<OrdersModuleProps> = ({ onBack, onProcessOrder }) => {
  const { customers, products, orders, addOrder, updateOrder, vehicles, setOrders } = useERPData();
  const [activeTab, setActiveTab] = useState<'new' | 'pending' | 'assigned'>('pending');

  // --- STATE: NEW ORDER ---
  const [customer, setCustomer] = useState<Customer | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [search, setSearch] = useState('');
  const [isUrgent, setIsUrgent] = useState(false);
  const [scheduleDate, setScheduleDate] = useState<'today' | 'tomorrow' | string>('today');

  // --- STATE: MANAGEMENT ---
  const [optimizing, setOptimizing] = useState(false);
  const [selectedOrderIds, setSelectedOrderIds] = useState<Set<string>>(new Set());
  const [showAssignModal, setShowAssignModal] = useState(false);

  // --- COMPUTED ---
  // Fix: Total respects customer special price logic (ID '1' is Garrafón)
  const total = cart.reduce((sum, item) => {
    const price = (customer?.specialPrice && item.id === '1') ? customer.specialPrice : item.price;
    return sum + (price * item.quantity);
  }, 0);

  // --- ACTIONS: NEW ORDER ---
  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === product.id);
      if (existing) return prev.map(i => i.id === product.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.filter(i => i.id !== id));
  };

  const handleCreateOrder = () => {
    if (!customer || cart.length === 0) return alert("Selecciona cliente y productos.");

    // Calculate timestamp based on schedule
    const now = new Date();
    let targetDate = new Date();
    if (scheduleDate === 'tomorrow') {
        targetDate.setDate(now.getDate() + 1);
    } else if (scheduleDate !== 'today') {
        targetDate = new Date(scheduleDate); // YYYY-MM-DD
        // Set to 9 AM
        targetDate.setHours(9, 0, 0, 0);
    }

    addOrder({
      customerId: customer.id,
      customerAlias: customer.alias,
      items: cart,
      total,
      status: 'pendiente',
      priority: isUrgent ? 2 : 1,
      timestamp: targetDate.getTime()
    });

    // Reset Form
    setCustomer(null);
    setCart([]);
    setSearch('');
    setIsUrgent(false);
    setScheduleDate('today');
    setActiveTab('pending');
  };

  // --- ACTIONS: BULK MANAGEMENT ---
  const toggleOrderSelection = (id: string) => {
    const newSet = new Set(selectedOrderIds);
    if (newSet.has(id)) newSet.delete(id);
    else newSet.add(id);
    setSelectedOrderIds(newSet);
  };

  const selectAllPending = () => {
    const pendingIds = orders.filter(o => o.status === 'pendiente').map(o => o.id);
    if (selectedOrderIds.size === pendingIds.length) {
        setSelectedOrderIds(new Set());
    } else {
        setSelectedOrderIds(new Set(pendingIds));
    }
  };

  const handleAssignToVehicle = (vehicleId: string) => {
    const idsToAssign = Array.from(selectedOrderIds);
    if (idsToAssign.length === 0) return;

    // Bulk update logic
    const updatedOrders = orders.map(o => {
        if (idsToAssign.includes(o.id)) {
            return { ...o, vehicleId, status: 'asignado' as const };
        }
        return o;
    });

    setOrders(updatedOrders);
    setSelectedOrderIds(new Set());
    setShowAssignModal(false);
  };

  const handleOptimize = async () => {
    const pendingOrders = orders.filter(o => o.status === 'pendiente');
    if (pendingOrders.length < 2) return alert("Necesitas al menos 2 pedidos pendientes.");

    setOptimizing(true);
    const result = await optimizeRoute(pendingOrders);

    if (result.orderedIds) {
      const optimized = [...orders].sort((a, b) => {
        const idxA = result.orderedIds.indexOf(a.id);
        const idxB = result.orderedIds.indexOf(b.id);
        // If not in optimized list, keep original relative order or put at end
        if (idxA === -1 && idxB === -1) return 0;
        if (idxA === -1) return 1;
        if (idxB === -1) return -1;
        return idxA - idxB;
      });
      setOrders(optimized);
      alert("¡Ruta optimizada por IA!");
    }
    setOptimizing(false);
  };

  // --- RENDER HELPERS ---
  const pendingOrders = useMemo(() => orders.filter(o => o.status === 'pendiente'), [orders]);
  const assignedOrders = useMemo(() => orders.filter(o => o.status === 'asignado'), [orders]);

  return (
    <div className="h-full bg-sky-50 flex flex-col animate-fadeIn overflow-hidden pb-24 relative">
      <ModuleHeader title="Logística de Pedidos" onBack={onBack} />

      {/* TABS */}
      <div className="px-6 flex gap-2 mb-4 shrink-0">
        <button onClick={() => setActiveTab('new')} className={`flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'new' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-200' : 'bg-white text-slate-400'}`}>
            <i className="fas fa-plus mr-1"></i> Crear
        </button>
        <button onClick={() => setActiveTab('pending')} className={`flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all relative ${activeTab === 'pending' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-200' : 'bg-white text-slate-400'}`}>
            Pendientes
            {pendingOrders.length > 0 && <span className="absolute -top-1 -right-1 bg-rose-500 text-white w-5 h-5 flex items-center justify-center rounded-full text-[8px] border-2 border-sky-50">{pendingOrders.length}</span>}
        </button>
        <button onClick={() => setActiveTab('assigned')} className={`flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'assigned' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-200' : 'bg-white text-slate-400'}`}>
            En Ruta
        </button>
      </div>

      <div className="flex-1 overflow-y-auto px-6 space-y-4 no-scrollbar pb-24">

        {/* --- TAB: NEW ORDER --- */}
        {activeTab === 'new' && (
          <div className="space-y-6">

            {/* Customer Search */}
            <section className="relative z-20">
              <label className="text-[10px] font-black text-slate-400 uppercase ml-2 mb-1 block">1. Cliente</label>
              <div className="relative">
                <input 
                  type="text" 
                  placeholder="Nombre, alias o teléfono..." 
                  className="w-full bg-white border-none rounded-[2rem] py-5 px-6 shadow-sm outline-none focus:ring-2 ring-indigo-300 font-bold text-sky-900"
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                />
                <i className="fas fa-search absolute right-6 top-1/2 -translate-y-1/2 text-slate-300"></i>

                {search && !customer && (
                  <div className="absolute top-full left-0 right-0 bg-white shadow-2xl rounded-3xl mt-2 overflow-hidden border border-slate-100 max-h-48 overflow-y-auto">
                    {customers.filter(c => c.alias.toLowerCase().includes(search.toLowerCase())).map(c => (
                      <button key={c.id} onClick={() => { setCustomer(c); setSearch(c.alias); }} className="w-full text-left p-4 hover:bg-sky-50 border-b border-slate-50 last:border-none flex justify-between items-center group">
                        <span className="font-bold text-slate-700 text-sm">{c.alias}</span>
                        <i className="fas fa-plus-circle text-indigo-200 group-hover:text-indigo-500"></i>
                      </button>
                    ))}
                  </div>
                )}
              </div>
              {customer && (
                <div className="mt-3 bg-indigo-50 border border-indigo-100 p-4 rounded-[1.5rem] flex justify-between items-center animate-fadeIn">
                  <div className="flex items-center gap-3">
                      <div className="w-10 h-10 bg-indigo-100 rounded-full flex items-center justify-center text-indigo-600"><i className="fas fa-user-check"></i></div>
                      <div>
                          <p className="font-black text-indigo-900 text-sm">{customer.alias}</p>
                          <p className="text-[9px] text-indigo-400 font-bold uppercase">{customer.address || 'Sin dirección'}</p>
                          {customer.specialPrice && <p className="text-[9px] text-emerald-500 font-black uppercase">Precio Especial: ${customer.specialPrice}</p>}
                      </div>
                  </div>
                  <button onClick={() => { setCustomer(null); setSearch(''); }} className="w-8 h-8 flex items-center justify-center bg-white rounded-full text-rose-400 shadow-sm"><i className="fas fa-times"></i></button>
                </div>
              )}
            </section>

            {/* Product Selection */}
            <section>
               <label className="text-[10px] font-black text-slate-400 uppercase ml-2 mb-2 block">2. Productos</label>
               <div className="grid grid-cols-2 gap-2">
                {products.filter(p => p.category !== 'Insumos').map(p => {
                    const inCart = cart.find(i => i.id === p.id)?.quantity || 0;
                    // Check for special price
                    const effectivePrice = (customer?.specialPrice && p.id === '1') ? customer.specialPrice : p.price;
                    const isSpecial = (customer?.specialPrice && p.id === '1');

                    return (
                        <button 
                            key={p.id} 
                            onClick={() => addToCart(p)} 
                            className={`p-3 rounded-2xl border text-left transition-all relative overflow-hidden ${inCart > 0 ? 'bg-indigo-600 text-white border-indigo-600 shadow-md' : 'bg-white border-transparent text-slate-600 hover:border-indigo-100'}`}
                        >
                            <div className="text-[10px] font-black uppercase leading-tight mb-1 pr-6">{p.name}</div>
                            <div className={`font-black flex items-center gap-1 ${inCart > 0 ? 'text-indigo-200' : 'text-indigo-500'}`}>
                                ${effectivePrice}
                                {isSpecial && <i className="fas fa-tag text-[8px]"></i>}
                            </div>
                            {inCart > 0 && (
                                <div className="absolute top-2 right-2 bg-white text-indigo-600 w-6 h-6 rounded-full flex items-center justify-center font-black text-xs shadow-sm">
                                    {inCart}
                                </div>
                            )}
                        </button>
                    );
                })}
               </div>
            </section>

            {/* Scheduling & Options */}
            <section className="bg-white p-5 rounded-[2rem] shadow-sm">
                <label className="text-[10px] font-black text-slate-400 uppercase mb-3 block">3. Detalles de Entrega</label>

                <div className="flex gap-2 mb-4 overflow-x-auto no-scrollbar">
                    <button onClick={() => setScheduleDate('today')} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase whitespace-nowrap transition-colors ${scheduleDate === 'today' ? 'bg-emerald-100 text-emerald-600 ring-2 ring-emerald-400' : 'bg-slate-50 text-slate-400'}`}>
                        Hoy
                    </button>
                    <button onClick={() => setScheduleDate('tomorrow')} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase whitespace-nowrap transition-colors ${scheduleDate === 'tomorrow' ? 'bg-sky-100 text-sky-600 ring-2 ring-sky-400' : 'bg-slate-50 text-slate-400'}`}>
                        Mañana
                    </button>
                    <input 
                        type="date" 
                        className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase bg-slate-50 text-slate-500 outline-none focus:ring-2 focus:ring-indigo-300 ${scheduleDate !== 'today' && scheduleDate !== 'tomorrow' ? 'ring-2 ring-indigo-400 bg-indigo-50 text-indigo-600' : ''}`}
                        onChange={(e) => setScheduleDate(e.target.value)}
                    />
                </div>

                <div className="flex items-center justify-between bg-rose-50 p-3 rounded-2xl border border-rose-100 relative">
                    <div className="flex items-center gap-2">
                        <div className={`w-4 h-4 rounded-full border-2 flex items-center justify-center ${isUrgent ? 'border-rose-500 bg-rose-500' : 'border-rose-300'}`}>
                            {isUrgent && <i className="fas fa-check text-white text-[8px]"></i>}
                        </div>
                        <span className="text-xs font-bold text-rose-700">Marcar como URGENTE</span>
                    </div>
                    {/* Improved checkbox hit area */}
                    <input type="checkbox" checked={isUrgent} onChange={() => setIsUrgent(!isUrgent)} className="absolute inset-0 opacity-0 w-full h-full cursor-pointer z-10" />
                </div>
            </section>

            {/* Summary & Action */}
            {cart.length > 0 && (
                <div className="pt-2 animate-slideUp">
                    <div className="flex justify-between items-end mb-4 px-2">
                        <span className="text-xs font-bold text-slate-400 uppercase">Total a Cobrar</span>
                        <span className="text-3xl font-black text-sky-900 tracking-tighter">${total.toFixed(2)}</span>
                    </div>
                    <ActionButton onClick={handleCreateOrder}>
                        Confirmar Pedido <i className="fas fa-check ml-2"></i>
                    </ActionButton>
                </div>
            )}
          </div>
        )}

        {/* --- TAB: PENDING --- */}
        {activeTab === 'pending' && (
          <div className="space-y-4">

            {/* Toolbar */}
            <div className="flex justify-between items-center bg-white p-2 pl-4 rounded-[1.5rem] shadow-sm mb-2 sticky top-0 z-10 border border-slate-50">
               <div className="flex items-center gap-2">
                  <div 
                    onClick={selectAllPending}
                    className={`w-5 h-5 rounded-lg border-2 flex items-center justify-center cursor-pointer transition-colors ${selectedOrderIds.size > 0 && selectedOrderIds.size === pendingOrders.length ? 'bg-indigo-600 border-indigo-600' : 'border-slate-300'}`}
                  >
                     {selectedOrderIds.size > 0 && <i className={`fas ${selectedOrderIds.size === pendingOrders.length ? 'fa-check' : 'fa-minus'} text-white text-[10px]`}></i>}
                  </div>
                  <span className="text-[10px] font-black uppercase text-slate-500">
                      {selectedOrderIds.size > 0 ? `${selectedOrderIds.size} Seleccionados` : 'Seleccionar Todo'}
                  </span>
               </div>
               <button 
                 onClick={handleOptimize} 
                 disabled={optimizing} 
                 className="w-10 h-10 bg-emerald-50 text-emerald-600 rounded-xl flex items-center justify-center active:scale-90 transition-transform"
               >
                 <i className={`fas ${optimizing ? 'fa-spinner animate-spin' : 'fa-wand-magic-sparkles'}`}></i>
               </button>
            </div>

            {pendingOrders.length === 0 ? (
                <div className="text-center py-20 opacity-40">
                    <i className="fas fa-clipboard-check text-6xl mb-4 text-slate-300"></i>
                    <p className="text-xs font-black uppercase text-slate-400">Todo al día</p>
                </div>
            ) : (
                pendingOrders.map((o) => {
                    const isSelected = selectedOrderIds.has(o.id);
                    const isUrgent = o.priority > 1;
                    const date = new Date(o.timestamp);
                    const isToday = date.getDate() === new Date().getDate();

                    return (
                        <div 
                            key={o.id} 
                            className={`relative p-5 rounded-[2rem] transition-all border-2 ${isSelected ? 'bg-indigo-50 border-indigo-500 shadow-md z-10' : 'bg-white border-transparent shadow-sm'}`}
                        >
                            <div className="absolute inset-0 z-0" onClick={() => toggleOrderSelection(o.id)}></div>
                            {/* Urgent Badge */}
                            {isUrgent && <div className="absolute top-0 right-0 bg-rose-500 text-white text-[8px] font-black px-3 py-1 rounded-bl-xl rounded-tr-xl shadow-sm z-10">URGENTE</div>}

                            <div className="flex justify-between items-start mb-3 relative z-10 pointer-events-none">
                                <div className="flex items-center gap-3">
                                    <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center shrink-0 ${isSelected ? 'bg-indigo-600 border-indigo-600' : 'border-slate-200'}`}>
                                        {isSelected && <i className="fas fa-check text-white text-[10px]"></i>}
                                    </div>
                                    <div>
                                        <h4 className="font-black text-sky-900 leading-none mb-1">{o.customerAlias}</h4>
                                        <div className="flex gap-2">
                                            <span className="text-[9px] font-bold text-slate-400 bg-slate-100 px-1.5 rounded uppercase">
                                                {isToday ? 'Entrega Hoy' : date.toLocaleDateString()}
                                            </span>
                                            <span className="text-[9px] font-bold text-slate-400">
                                                {new Date(o.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                                            </span>
                                        </div>
                                    </div>
                                </div>
                                <span className="font-black text-indigo-600 text-lg tracking-tighter">${o.total}</span>
                            </div>

                            <div className="flex flex-wrap gap-1 pl-9 relative z-10 pointer-events-none mb-3">
                                {o.items.map(i => (
                                    <span key={i.id} className="text-[9px] font-bold text-slate-600 bg-slate-50 px-2 py-1 rounded-lg border border-slate-100">
                                        {i.quantity}x {i.name.split(' ')[0]}
                                    </span>
                                ))}
                            </div>

                            {/* Direct Pay Action */}
                            <div className="pl-9 relative z-20">
                                <button 
                                    onClick={(e) => { e.stopPropagation(); onProcessOrder(o); }}
                                    className="w-full bg-emerald-50 text-emerald-600 border border-emerald-200 py-2 rounded-xl text-[9px] font-black uppercase flex items-center justify-center gap-2 active:bg-emerald-100 transition-colors"
                                >
                                    <i className="fas fa-cash-register"></i> Cobrar / Entregar
                                </button>
                            </div>
                        </div>
                    );
                })
            )}
          </div>
        )}

        {/* --- TAB: ASSIGNED (EN RUTA) --- */}
        {activeTab === 'assigned' && (
          <div className="space-y-4">
             {assignedOrders.length === 0 ? (
                <div className="text-center py-20 opacity-40">
                    <i className="fas fa-truck-fast text-6xl mb-4 text-slate-300"></i>
                    <p className="text-xs font-black uppercase text-slate-400">Sin pedidos en ruta</p>
                </div>
             ) : (
                assignedOrders.map(o => {
                    const vehicle = vehicles.find(v => v.id === o.vehicleId);
                    const isUrgent = o.priority > 1; // Check priority

                    return (
                        <RoundedCard key={o.id} className="border-l-4 border-l-emerald-400 relative overflow-hidden">
                            {/* Urgent Badge in Route Card */}
                            {isUrgent && <div className="absolute top-0 right-0 bg-rose-500 text-white text-[8px] font-black px-3 py-1 rounded-bl-xl rounded-tr-[2.5rem] shadow-sm z-10">URGENTE</div>}

                            <div className="flex justify-between items-start">
                                <div>
                                    <h4 className="font-black text-sky-900 mb-1">{o.customerAlias}</h4>
                                    <div className="flex items-center gap-2">
                                        <i className="fas fa-truck text-emerald-500 text-xs"></i>
                                        <span className="text-[10px] font-bold text-slate-500 uppercase">{vehicle?.plate || 'Unidad ?'}</span>
                                    </div>
                                    <div className="flex flex-wrap gap-1 mt-2">
                                        {o.items.map(i => (
                                            <span key={i.id} className="text-[8px] font-bold text-slate-600 bg-slate-50 px-2 py-0.5 rounded border border-slate-100">
                                                {i.quantity}x {i.name}
                                            </span>
                                        ))}
                                    </div>
                                </div>
                                <div className="text-right flex flex-col justify-between h-full min-h-[80px]">
                                    <span className="font-black text-sky-900 block mb-2 text-lg">${o.total}</span>
                                    <button 
                                        onClick={() => onProcessOrder(o)}
                                        className="bg-emerald-500 text-white px-4 py-2 rounded-xl text-[9px] font-black uppercase flex items-center gap-1 active:bg-emerald-600 transition-colors shadow-lg shadow-emerald-200"
                                    >
                                        Entregar <i className="fas fa-arrow-right"></i>
                                    </button>
                                </div>
                            </div>
                        </RoundedCard>
                    );
                })
             )}
          </div>
        )}
      </div>

      {/* --- FLOATING ACTION BUTTON (ASSIGN) --- */}
      {selectedOrderIds.size > 0 && activeTab === 'pending' && (
        <div className="fixed bottom-6 left-6 right-6 z-30 animate-slideUp">
            <button 
                onClick={() => setShowAssignModal(true)}
                className="w-full bg-indigo-600 text-white py-4 rounded-[2rem] shadow-2xl shadow-indigo-500/40 flex items-center justify-center gap-3 font-black uppercase text-xs tracking-widest active:scale-95 transition-transform"
            >
                <span>Asignar {selectedOrderIds.size} Pedidos</span>
                <i className="fas fa-truck-arrow-right"></i>
            </button>
        </div>
      )}

      {/* --- MODAL: SELECT VEHICLE --- */}
      {showAssignModal && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[100] flex items-end justify-center animate-fadeIn">
            <div className="bg-white w-full max-w-md rounded-t-[2.5rem] p-6 shadow-2xl">
                <div className="flex justify-between items-center mb-6">
                    <h3 className="text-xl font-black text-sky-900">Seleccionar Unidad</h3>
                    <button onClick={() => setShowAssignModal(false)} className="w-10 h-10 bg-slate-100 rounded-full text-slate-400"><i className="fas fa-times"></i></button>
                </div>

                <div className="space-y-3 max-h-[60vh] overflow-y-auto no-scrollbar pb-6">
                    {vehicles.map(v => {
                        const loadPercent = Math.round((v.currentLoad / v.loadCapacity) * 100);
                        const isFull = loadPercent >= 100;

                        return (
                            <button 
                                key={v.id} 
                                onClick={() => handleAssignToVehicle(v.id)}
                                disabled={isFull}
                                className={`w-full p-4 rounded-[2rem] border-2 flex items-center justify-between transition-all ${isFull ? 'bg-slate-50 border-slate-100 opacity-60' : 'bg-white border-slate-100 active:border-indigo-500 active:bg-indigo-50'}`}
                            >
                                <div className="flex items-center gap-4">
                                    <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-xl ${isFull ? 'bg-slate-200 text-slate-400' : 'bg-indigo-100 text-indigo-600'}`}>
                                        <i className="fas fa-truck-front"></i>
                                    </div>
                                    <div className="text-left">
                                        <h5 className="font-black text-sky-900 text-sm uppercase">{v.plate}</h5>
