import React, { useState, useEffect, useRef } from 'react';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard } from './ui/Cards';

const TRANSITION_TIME = 15; 
const STORAGE_KEY = 'aqua_production_state_v3'; 

export const ProductionModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const { productionConfig, setProductionConfig } = useERPData();

  const [mode, setMode] = useState<'backwash' | 'regen'>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved).mode : 'backwash';
  });

  const [currentStepIdx, setCurrentStepIdx] = useState(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved).currentStepIdx : 0;
  });

  const [isRunning, setIsRunning] = useState(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved).isRunning : false;
  });

  const [isTransitioning, setIsTransitioning] = useState(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved).isTransitioning : false;
  });

  const [endTime, setEndTime] = useState<number | null>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved).endTime : null;
  });

  const [timeLeft, setTimeLeft] = useState(0);

  // Logic for Hardness Planner
  const [hardnessGPG, setHardnessGPG] = useState(10); // Default hardness
  const [resinFt3, setResinFt3] = useState(productionConfig.softenerVolumeFt3 || 1.0);
  const [batchInput, setBatchInput] = useState(0);

  const wakeLock = useRef<WakeLockSentinel | null>(null);

  // Dynamic sequences
  const currentSequence = mode === 'backwash' ? productionConfig.backwashSequence : productionConfig.regenerationSequence;

  // Calculos de Capacidad
  // Formula: Capacidad (Granos) = PiesCubicos * 30,000
  // Galones = Capacidad / Dureza(GPG)
  // Litros = Galones * 3.785
  const totalCapacityGrains = resinFt3 * 30000;
  const totalCapacityGallons = hardnessGPG > 0 ? totalCapacityGrains / hardnessGPG : 0;
  const totalCapacityLiters = totalCapacityGallons * 3.785;
  const currentUsage = productionConfig.currentUsageLiters || 0;
  const remainingLiters = Math.max(0, totalCapacityLiters - currentUsage);
  const percentageUsed = (currentUsage / totalCapacityLiters) * 100;

  // Update context when resin size changes locally
  useEffect(() => {
    if (Math.abs(resinFt3 - (productionConfig.softenerVolumeFt3 || 0)) > 0.1) {
        setProductionConfig({ ...productionConfig, softenerVolumeFt3: resinFt3 });
    }
  }, [resinFt3]);

  const handleAddBatch = () => {
    if (batchInput <= 0) return;
    const litersToAdd = batchInput * 20; // 20 Litros por garrafón
    setProductionConfig({
        ...productionConfig,
        currentUsageLiters: (productionConfig.currentUsageLiters || 0) + litersToAdd
    });
    setBatchInput(0);
    alert(`Registrados ${litersToAdd} litros procesados.`);
  };

  const handleResetUsage = () => {
    setProductionConfig({
        ...productionConfig,
        currentUsageLiters: 0,
        lastRegenDate: Date.now()
    });
  };

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      if (parsed.isRunning && parsed.endTime) {
        const now = Date.now();
        const diff = Math.ceil((parsed.endTime - now) / 1000);
        if (diff > 0) {
          setTimeLeft(diff);
          requestWakeLock();
        } else {
          setTimeLeft(0);
        }
      } else {
        const defaultTime = parsed.isTransitioning ? TRANSITION_TIME : currentSequence[parsed.currentStepIdx]?.time || 0;
        setTimeLeft(parsed.savedTimeLeft || defaultTime);
      }
    } else {
      setTimeLeft(currentSequence[0]?.time || 0);
    }
  }, [currentSequence]); 

  useEffect(() => {
    const stateToSave = { mode, currentStepIdx, endTime, isRunning, isTransitioning, savedTimeLeft: timeLeft };
    localStorage.setItem(STORAGE_KEY, JSON.stringify(stateToSave));
  }, [mode, currentStepIdx, endTime, isRunning, timeLeft, isTransitioning]);

  const requestWakeLock = async () => {
    try { if ('wakeLock' in navigator && !wakeLock.current) wakeLock.current = await navigator.wakeLock.request('screen'); } 
    catch (err) { console.warn(err); }
  };

  const releaseWakeLock = async () => {
    if (wakeLock.current) { await wakeLock.current.release(); wakeLock.current = null; }
  };

  useEffect(() => {
    let interval: any;
    if (isRunning && endTime) {
      requestWakeLock(); 
      interval = setInterval(() => {
        const now = Date.now();
        const remaining = Math.ceil((endTime - now) / 1000);
        if (remaining <= 0) {
          if (isTransitioning) {
            setIsTransitioning(false);
            const nextIdx = currentStepIdx + 1;
            setCurrentStepIdx(nextIdx);
            const nextStepTime = currentSequence[nextIdx]?.time || 0;
            const newEndTime = Date.now() + nextStepTime * 1000;
            setEndTime(newEndTime);
            setTimeLeft(nextStepTime);
          } else {
            if (navigator.vibrate) navigator.vibrate([1000, 500, 1000]); 
            if (currentStepIdx < currentSequence.length - 1) {
              setIsTransitioning(true);
              const newEndTime = Date.now() + TRANSITION_TIME * 1000;
              setEndTime(newEndTime);
              setTimeLeft(TRANSITION_TIME);
            } else {
              // PROCESS FINISHED
              setIsRunning(false);
              setEndTime(null);
              releaseWakeLock();
              localStorage.removeItem(STORAGE_KEY);

              // AUTO RESET LOGIC IF REGENERATION
              if (mode === 'regen') {
                  handleResetUsage();
                  alert("REGENERACIÓN COMPLETADA.\nContador de uso reiniciado.");
              } else {
                  alert("RETROLAVADO FINALIZADO");
              }
            }
          }
        } else {
          setTimeLeft(remaining);
        }
      }, 1000);
    } else {
      releaseWakeLock();
    }
    return () => clearInterval(interval);
  }, [isRunning, endTime, currentStepIdx, currentSequence, mode, isTransitioning]);

  const startSequence = () => {
    const duration = timeLeft > 0 ? timeLeft : (isTransitioning ? TRANSITION_TIME : currentSequence[currentStepIdx].time);
    setEndTime(Date.now() + duration * 1000);
    setIsRunning(true);
  };

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s.toString().padStart(2, '0')}`;
  };

  return (
    <div className="px-6 py-8 animate-fadeIn h-full bg-slate-900 overflow-y-auto pb-24 no-scrollbar text-white">
      <div className="flex items-center gap-4 mb-6">
        <button onClick={onBack} className="w-12 h-12 bg-white/10 rounded-2xl flex items-center justify-center active:scale-90 transition-transform">
          <i className="fas fa-arrow-left"></i>
        </button>
        <h2 className="text-2xl font-black tracking-tight">Control Planta</h2>
      </div>

      <div className="space-y-6">
        {/* --- SECTION: HARDNESS PLANNER --- */}
        {!isRunning && (
            <div className="bg-gradient-to-br from-indigo-900 to-slate-800 p-6 rounded-[2.5rem] border border-indigo-500/30 shadow-2xl relative overflow-hidden">
                <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-500/10 rounded-full blur-2xl -mr-10 -mt-10"></div>

                <div className="flex justify-between items-start mb-4 relative z-10">
                    <div>
                        <h3 className="text-lg font-black text-indigo-300 uppercase tracking-wide">Planeación</h3>
                        <p className="text-[10px] text-white/60">Basado en dureza y volumen de resina</p>
                    </div>
                    {percentageUsed >= 90 && (
                        <div className="animate-pulse bg-red-500 text-white px-3 py-1 rounded-full text-[9px] font-black uppercase shadow-lg shadow-red-500/40">
                            ¡Regenerar!
                        </div>
                    )}
                </div>

                <div className="flex items-center justify-between mb-6 relative z-10">
                    <div className="flex flex-col gap-3">
                        <div className="flex items-center gap-2">
                            <div className="w-8 h-8 bg-white/10 rounded-lg flex items-center justify-center text-white"><i className="fas fa-flask"></i></div>
                            <div>
                                <label className="text-[8px] font-bold text-indigo-300 uppercase block">Dureza (Gotas/GPG)</label>
                                <div className="flex items-center gap-2">
                                    <button onClick={() => setHardnessGPG(Math.max(1, hardnessGPG - 1))} className="w-6 h-6 bg-white/5 rounded text-white font-bold">-</button>
                                    <span className="font-black text-xl w-6 text-center">{hardnessGPG}</span>
                                    <button onClick={() => setHardnessGPG(hardnessGPG + 1)} className="w-6 h-6 bg-white/5 rounded text-white font-bold">+</button>
                                </div>
                            </div>
                        </div>
                        <div className="flex items-center gap-2">
                            <div className="w-8 h-8 bg-white/10 rounded-lg flex items-center justify-center text-white"><i className="fas fa-cube"></i></div>
                            <div>
                                <label className="text-[8px] font-bold text-indigo-300 uppercase block">Resina (Pies³)</label>
                                <input 
                                    type="number" 
                                    className="bg-transparent border-b border-white/20 w-16 text-xl font-black text-white outline-none text-center"
                                    value={resinFt3}
                                    onChange={e => setResinFt3(parseFloat(e.target.value) || 0)}
                                    step="0.5"
                                />
                            </div>
                        </div>
                    </div>

                    {/* Circular Progress */}
                    <div className="relative w-28 h-28 flex items-center justify-center">
                        <svg className="w-full h-full -rotate-90">
                            <circle cx="56" cy="56" r="48" stroke="currentColor" strokeWidth="8" fill="transparent" className="text-slate-700" />
                            <circle 
                                cx="56" cy="56" r="48" 
                                stroke="currentColor" strokeWidth="8" fill="transparent" 
                                strokeDasharray={`${Math.min(percentageUsed, 100) * 3}, 300`}
                                strokeLinecap="round"
                                className={percentageUsed > 90 ? 'text-red-500' : percentageUsed > 75 ? 'text-amber-500' : 'text-emerald-500'}
                            />
                        </svg>
                        <div className="absolute flex flex-col items-center">
                            <span className="text-2xl font-black">{Math.round(remainingLiters)}</span>
                            <span className="text-[8px] uppercase font-bold text-white/50">Litros Restantes</span>
                        </div>
                    </div>
                </div>

                <div className="bg-black/20 p-3 rounded-2xl flex items-center justify-between gap-2">
                    <div className="flex items-center gap-2">
                        <input 
                            type="number" 
                            className="w-12 bg-white/10 rounded-lg p-2 text-center text-sm font-bold text-white outline-none"
                            placeholder="0"
                            value={batchInput === 0 ? '' : batchInput}
                            onChange={e => setBatchInput(parseInt(e.target.value) || 0)}
                        />
                        <span className="text-[9px] font-bold text-white/60 uppercase leading-tight">Garrafones<br/>Producidos</span>
                    </div>
                    <button 
                        onClick={handleAddBatch}
                        className="bg-indigo-500 hover:bg-indigo-400 text-white px-4 py-2 rounded-xl text-[9px] font-black uppercase transition-colors"
                    >
                        Registrar Lote
                    </button>
                </div>
            </div>
        )}

        {/* --- SECTION: CONTROLS --- */}
        <div className="flex bg-white/10 p-1.5 rounded-[2rem] shadow-inner border border-white/5">
          <button onClick={() => { if(!isRunning) { setMode('backwash'); setCurrentStepIdx(0); setTimeLeft(productionConfig.backwashSequence[0].time); }}} disabled={isRunning} className={`flex-1 py-4 rounded-[1.8rem] text-[10px] font-black uppercase tracking-widest transition-all ${mode === 'backwash' ? 'bg-sky-500 text-white shadow-lg' : 'text-slate-400'} ${isRunning ? 'opacity-50' : ''}`}>
            Retrolavado
          </button>
          <button onClick={() => { if(!isRunning) { setMode('regen'); setCurrentStepIdx(0); setTimeLeft(productionConfig.regenerationSequence[0].time); }}} disabled={isRunning} className={`flex-1 py-4 rounded-[1.8rem] text-[10px] font-black uppercase tracking-widest transition-all ${mode === 'regen' ? 'bg-amber-500 text-white shadow-lg' : 'text-slate-400'} ${isRunning ? 'opacity-50' : ''}`}>
            Regeneración
          </button>
        </div>

        <div className="flex justify-between gap-1 px-2 mb-2">
          {currentSequence.map((s, idx) => (
            <div key={idx} className="flex-1 flex flex-col items-center gap-2">
              <div className={`h-1.5 w-full rounded-full transition-all duration-500 ${idx < currentStepIdx ? 'bg-emerald-500' : idx === currentStepIdx ? (isTransitioning ? 'bg-emerald-500' : (mode === 'regen' ? 'bg-amber-500' : 'bg-sky-500')) : 'bg-white/10'}`}></div>
            </div>
          ))}
        </div>

        <div className={`relative overflow-hidden rounded-[2.5rem] shadow-2xl transition-all duration-500 ${isTransitioning ? 'bg-violet-600' : 'bg-slate-800 border border-white/10'}`}>
          <div className="p-8 text-center relative z-10">
            <div className={`w-fit mx-auto px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest mb-4 border ${isTransitioning ? 'bg-violet-500 border-violet-400 text-white animate-pulse' : 'bg-white/10 border-white/10 text-white/70'}`}>
              {isTransitioning ? 'AJUSTE VÁLVULAS' : `Paso ${currentStepIdx + 1}/${currentSequence.length}`}
            </div>

            <h3 className="text-3xl font-black tracking-tight leading-none mb-2 text-white">
              {isTransitioning ? 'CAMBIO DE FASE' : currentSequence[currentStepIdx]?.stage}
            </h3>
            <p className={`font-black uppercase text-sm tracking-widest mb-8 ${isTransitioning ? 'text-violet-200' : 'text-sky-400'}`}>
              {isTransitioning ? `Siguiente: ${currentSequence[currentStepIdx + 1]?.process}` : currentSequence[currentStepIdx]?.process}
            </p>

            <div className="text-8xl font-mono font-black mb-8 tracking-tighter tabular-nums text-white drop-shadow-2xl">
              {isTransitioning ? timeLeft : formatTime(timeLeft)}
              <span className="text-lg text-white/30 ml-2 font-sans font-bold">{isTransitioning ? 'seg' : 'min'}</span>
            </div>

            {!isRunning ? (
              <button onClick={startSequence} className={`w-full py-5 rounded-[2rem] font-black text-sm uppercase tracking-widest shadow-xl active:scale-95 transition-all ${mode === 'regen' ? 'bg-amber-500 text-black' : 'bg-sky-500 text-white'}`}>
                {timeLeft > 0 && timeLeft < currentSequence[currentStepIdx].time ? 'Reanudar' : 'Iniciar Proceso'}
              </button>
            ) : (
              <button onClick={() => setIsRunning(false)} className="w-full bg-red-500/20 border border-red-500 text-red-400 py-5 rounded-[2rem] font-black text-sm uppercase tracking-widest active:scale-95 transition-all flex items-center justify-center gap-2">
                <i className="fas fa-pause"></i> Pausar
              </button>
            )}
          </div>

          {/* Progress BG */}
          <div className="absolute bottom-0 left-0 h-2 bg-black/30 w-full">
             <div className={`h-full transition-all duration-1000 ease-linear ${isTransitioning ? 'bg-white' : (mode === 'regen' ? 'bg-amber-500' : 'bg-sky-500')}`} style={{ width: `${isTransitioning ? ((TRANSITION_TIME - timeLeft)/TRANSITION_TIME)*100 : ((currentSequence[currentStepIdx].time - timeLeft)/currentSequence[currentStepIdx].time)*100}%` }}></div>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';
import { Employee, ViewType, TicketConfig, ProductionConfig } from '../types';
import { BACKWASH_SEQUENCE, REGENERATION_SEQUENCE } from '../constants';

const COLORS = [
  { name: 'Sky', hex: '#0284c7' },
  { name: 'Rose', hex: '#e11d48' },
  { name: 'Emerald', hex: '#059669' },
  { name: 'Amber', hex: '#d97706' },
  { name: 'Indigo', hex: '#4f46e5' },
  { name: 'Slate', hex: '#0f172a' },
];

export const SettingsModule: React.FC<{ onBack: () => void; currentUser: Employee }> = ({ onBack, currentUser }) => {
  const { employees, saveEmployee, ticketConfig, setTicketConfig, productionConfig, setProductionConfig, resetSales, products, customers, sales, orders, vehicles, qualityRecords, tasks, attendance, savedReports, messages, syncData } = useERPData();
  const [selectedEmp, setSelectedEmp] = useState<Employee | null>(null);
  const [editingTicket, setEditingTicket] = useState(false);
  const [editingProduction, setEditingProduction] = useState(false);
  const [tempTicket, setTempTicket] = useState<TicketConfig>(ticketConfig);
  const [tempProduction, setTempProduction] = useState<ProductionConfig>(productionConfig);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const modules: { id: ViewType; label: string; icon: string }[] = [
    { id: 'pos', label: 'Ventas', icon: 'fa-cart-plus' },
    { id: 'orders', label: 'Pedidos', icon: 'fa-clipboard-list' },
    { id: 'customers', label: 'Clientes', icon: 'fa-users' },
    { id: 'inventory', label: 'Inventario', icon: 'fa-box-open' },
    { id: 'supplies', label: 'Insumos', icon: 'fa-boxes-stacked' },
    { id: 'logistics', label: 'Logística', icon: 'fa-truck-fast' },
    { id: 'whatsapp', label: 'Preventa', icon: 'fa-brands fa-whatsapp' },
    { id: 'messages', label: 'Mensajes', icon: 'fa-comments' },
    { id: 'production', label: 'Planta', icon: 'fa-industry' },
    { id: 'quality', label: 'Calidad', icon: 'fa-clipboard-check' },
    { id: 'scanner', label: 'Scanner', icon: 'fa-expand' },
    { id: 'employees', label: 'Equipo', icon: 'fa-id-card' },
    { id: 'reports', label: 'Reportes', icon: 'fa-chart-pie' },
    { id: 'tickets', label: 'Tickets', icon: 'fa-ticket' },
    { id: 'sync', label: 'Nube Sync', icon: 'fa-cloud' },
    { id: 'settings', label: 'Ajustes', icon: 'fa-gear' },
  ];

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 200000) {
        alert("La imagen es muy pesada. Intenta con una menor a 200kb.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setTempTicket({ ...tempTicket, logoUrl: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveTicketConfig = () => {
    setTicketConfig(tempTicket);
    setEditingTicket(false);
    alert("Identidad del ticket actualizada correctamente.");
  };

  const handleSaveProductionConfig = () => {
    setProductionConfig(tempProduction);
    setEditingProduction(false);
    alert("Configuración de planta actualizada correctamente.");
  };

  const handleResetProductionDefaults = () => {
    if(confirm("¿Estás seguro de restaurar los tiempos originales de fábrica? Se perderán las personalizaciones.")) {
        setTempProduction({
            backwashSequence: BACKWASH_SEQUENCE,
            regenerationSequence: REGENERATION_SEQUENCE,
            softenerVolumeFt3: 1.5
        });
    }
  };

  const updateProductionTime = (type: 'backwash' | 'regen', index: number, newMinutes: number) => {
    const seconds = Math.max(0, newMinutes * 60);
    if (type === 'backwash') {
        const newSeq = [...tempProduction.backwashSequence];
        newSeq[index] = { ...newSeq[index], time: seconds };
        setTempProduction({ ...tempProduction, backwashSequence: newSeq });
    } else {
        const newSeq = [...tempProduction.regenerationSequence];
        newSeq[index] = { ...newSeq[index], time: seconds };
        setTempProduction({ ...tempProduction, regenerationSequence: newSeq });
    }
  };

  const handleResetSales = () => {
    if (confirm("⚠️ ¿Estás seguro de que quieres reiniciar las ventas?\n\nEsta acción eliminará TODOS los tickets del historial. No afecta clientes ni inventario.")) {
      if (confirm("🔴 ÚLTIMA ADVERTENCIA\n\nEsta acción NO se puede deshacer. ¿Proceder con el borrado?")) {
        resetSales();
      }
    }
  };

  // --- BACKUP LOGIC ---
  const handleExportData = () => {
    const backup = {
      timestamp: Date.now(),
      version: "1.0",
      data: {
        products, customers, sales, orders, employees, vehicles, ticketConfig, productionConfig, qualityRecords, tasks, attendance, savedReports, messages
      }
    };
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(backup));
    const downloadAnchorNode = document.createElement('a');
    downloadAnchorNode.setAttribute("href", dataStr);
    downloadAnchorNode.setAttribute("download", `Respaldo_Aqua_${Date.now()}.json`);
    document.body.appendChild(downloadAnchorNode);
    downloadAnchorNode.click();
    downloadAnchorNode.remove();
  };

  const handleImportData = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (json.data) {
           if(confirm("¿Restaurar respaldo? Esto sobrescribirá los datos locales y sincronizará con la nube.")) {
             syncData(json.data);
             alert("Datos restaurados correctamente.");
           }
        } else {
          alert("Formato de archivo inválido. Falta estructura 'data'.");
        }
      } catch (err) {
        alert("Error al leer el archivo JSON.");
      }
    };
    reader.readAsText(file);
  };

  if (editingProduction) {
    return (
      <div className="h-full bg-slate-900 animate-fadeIn overflow-y-auto no-scrollbar pb-32 text-white">
        <ModuleHeader title="Configurar Planta" onBack={() => setEditingProduction(false)} />
        <div className="px-6 space-y-8">

           {/* Section 0: Equipment Specs */}
           <section>
