        cloudList.forEach(item => cloudMap.set(item.id, item));
    }

    // 2. Process Local Items vs Cloud
    localList.forEach(localItem => {
        const cloudItem = cloudMap.get(localItem.id);

        if (!cloudItem) {
            // Item exists locally but not in cloud (New Local)
            combinedMap.set(localItem.id, localItem);
            // We count this as 'unchanged' relative to local state, or 'added' to cloud payload
        } else {
            // Conflict Resolution
            const localTime = localItem.lastUpdated || localItem.timestamp || 0;
            const cloudTime = cloudItem.lastUpdated || cloudItem.timestamp || 0;

            if (localTime > cloudTime) {
                // Local is newer
                combinedMap.set(localItem.id, localItem);
                stats.updated++;
            } else if (cloudTime > localTime) {
                // Cloud is newer (Updates Local)
                combinedMap.set(localItem.id, cloudItem);
                stats.updated++;
            } else {
                // Same
                combinedMap.set(localItem.id, localItem);
                stats.unchanged++;
            }
            // Remove from cloudMap to identify what is ONLY in cloud later
            cloudMap.delete(localItem.id);
        }
    });

    // 3. Add remaining Cloud Items (New from Cloud)
    cloudMap.forEach((cloudItem, id) => {
        combinedMap.set(id, cloudItem);
        stats.added++;
    });

    return { merged: Array.from(combinedMap.values()), stats };
  };

  const executeSync = async (mode: SyncMode) => {
    if (!cloudConfig.url) {
      alert("Configura la URL de Firebase primero.");
      setEditingConfig(true);
      return;
    }
    if (!isOnline) {
      alert("Sin conexión a internet.");
      return;
    }

    setStatus('syncing');
    setLastStats(null);
    setLogs([]); // Clear logs for new run
    addLog(`Iniciando ${mode === 'bidirectional' ? 'Sincronización Inteligente' : mode === 'pull' ? 'Descarga' : 'Subida'}...`);

    try {
      const endpoint = `${cloudConfig.url}aqua_data.json${cloudConfig.apiKey ? `?auth=${cloudConfig.apiKey}` : ''}`;

      let cloudData: any = {};

      // STEP 1: FETCH (Always fetch first unless it's a blind force push, but even then we should merge to be safe)
      if (mode !== 'push') {
          addLog("☁️ Descargando datos de nube...");
          const getResponse = await fetch(endpoint);
          if (!getResponse.ok) throw new Error(`Error HTTP: ${getResponse.status}`);
          cloudData = await getResponse.json() || {};
          addLog("✅ Datos recibidos.");
      }

      // STEP 2: MERGE LOGIC
      let finalState: any = {};
      let syncStats: Record<string, SyncStats> = {};

      if (mode === 'pull') {
          // Dangerous: Cloud overwrites local completely? Or merge? 
          // Let's do merge but prioritizing cloud for safety, essentially standard merge
          addLog("⚡ Procesando descarga...");
          // We utilize smart merge but the logic handles "cloud newer" naturally.
          // To strictly enforce PULL (Cloud Wins), we could artificially boost cloud timestamps, but smartMerge is safer.
      } 

      const mergeCollection = (key: string, local: any[], cloud: any[]) => {
          addLog(`.. Procesando ${key}`);
          const { merged, stats } = smartMerge(local, cloud);
          finalState[key] = merged;
          syncStats[key] = stats;
      };

      // Perform Merges
      if (mode === 'push') {
          // Just use local data as truth, but we need to structure it
          addLog("⚠️ Modo Push: Usando datos locales como maestro.");
          finalState = {
              sales, customers, products, orders, employees, vehicles, qualityRecords, tasks, attendance, savedReports, messages, ticketConfig
          };
          // Mock stats
          syncStats['Total'] = { added: 0, updated: 0, unchanged: 0 };
      } else {
          // Bidirectional or Pull
          mergeCollection('sales', sales, cloudData.sales);
          mergeCollection('customers', customers, cloudData.customers);
          mergeCollection('products', products, cloudData.products);
          mergeCollection('orders', orders, cloudData.orders);
          mergeCollection('employees', employees, cloudData.employees);
          mergeCollection('vehicles', vehicles, cloudData.vehicles);
          mergeCollection('qualityRecords', qualityRecords, cloudData.qualityRecords);
          mergeCollection('tasks', tasks, cloudData.tasks);
          mergeCollection('attendance', attendance, cloudData.attendance);
          mergeCollection('savedReports', savedReports, cloudData.savedReports);
          mergeCollection('messages', messages, cloudData.messages);

          // Config merge
          finalState.ticketConfig = cloudData.ticketConfig || ticketConfig;
      }

      // STEP 3: UPDATE LOCAL
      addLog("💾 Guardando en dispositivo...");
      syncData(finalState);
      setLastStats(syncStats);

      // STEP 4: UPLOAD (Only if not Pull-only)
      if (mode !== 'pull') {
          addLog("🚀 Subiendo cambios a nube...");
          const uploadPayload = {
            ...finalState,
            lastUpdated: Date.now(),
            deviceUser: deviceId || 'AquaPro Mobile'
          };

          const putResponse = await fetch(endpoint, {
            method: 'PUT', // PUT replaces the node. Safe because we merged first.
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(uploadPayload)
          });

          if (!putResponse.ok) throw new Error("Error al escribir en nube");
          addLog("✅ Nube actualizada correctamente.");
      } else {
          addLog("⏹️ Modo descarga finalizado (Sin subida).");
      }

      setCloudConfig(prev => ({ ...prev, lastSync: Date.now() }));
      setStatus('success');

    } catch (error: any) {
      console.error(error);
      setStatus('error');
      addLog(`❌ Error Crítico: ${error.message}`);
    }
  };

  // Auto-sync effect
  useEffect(() => {
    if (cloudConfig.autoSync && cloudConfig.url && status === 'idle' && isOnline) {
      const timer = setInterval(() => {
        executeSync('bidirectional');
      }, 30000); // 30 seconds interval for auto-sync
      return () => clearInterval(timer);
    }
  }, [cloudConfig, status, isOnline]);

  if (editingConfig) {
    return (
      <div className="h-full bg-slate-50 animate-fadeIn pb-24 overflow-y-auto">
        <ModuleHeader title="Configurar Nube" onBack={() => setEditingConfig(false)} />
        <div className="px-6 space-y-6">
          <div className="bg-white p-6 rounded-[2rem] shadow-lg border border-indigo-100">
             <div className="flex items-center gap-3 mb-4">
                <div className="w-12 h-12 bg-amber-100 rounded-2xl flex items-center justify-center text-amber-500 text-2xl">
                    <i className="fas fa-fire"></i>
                </div>
                <div>
                    <h3 className="font-black text-sky-900 leading-none">Firebase</h3>
                    <p className="text-[10px] font-bold text-sky-300 uppercase">Realtime Database</p>
                </div>
             </div>

             <div className="space-y-4">
               <div>
                 <label className="text-[10px] font-black uppercase text-sky-400 ml-2">URL del Proyecto</label>
                 <input 
                   type="url" 
                   placeholder="https://..." 
                   className="w-full bg-slate-50 p-4 rounded-2xl outline-none font-bold text-sky-900 text-xs focus:ring-2 ring-indigo-300 transition-all"
                   value={tempConfig.url}
