        {/* STATUS CARD */}
        <div className="bg-gradient-to-br from-slate-800 to-slate-900 p-6 rounded-[2.5rem] border border-white/5 relative overflow-hidden shrink-0">
           <div className={`absolute top-0 right-0 w-32 h-32 bg-indigo-500/10 rounded-full blur-2xl -mr-10 -mt-10 transition-opacity ${status === 'syncing' ? 'opacity-100' : 'opacity-0'}`}></div>

           <div className="flex flex-col items-center justify-center relative z-10 py-4">
              <div className={`w-24 h-24 rounded-full flex items-center justify-center text-4xl shadow-2xl transition-all duration-500 ${status === 'syncing' ? 'bg-indigo-600 scale-110 shadow-indigo-500/50' : status === 'success' ? 'bg-emerald-500 text-white' : status === 'error' ? 'bg-rose-500' : 'bg-slate-700'}`}>
                 <i className={`fas ${status === 'syncing' ? 'fa-arrows-rotate animate-spin' : status === 'success' ? 'fa-check' : status === 'error' ? 'fa-xmark' : 'fa-cloud'}`}></i>
              </div>

              <h3 className="text-xl font-black mt-4 mb-1 tracking-tight">
                {status === 'syncing' ? 'Sincronizando...' : status === 'success' ? 'Sincronización Exitosa' : status === 'error' ? 'Error de Sincronización' : 'Listo para Sincronizar'}
              </h3>

              <p className="text-[10px] font-mono text-slate-400">
                {cloudConfig.lastSync ? `Última vez: ${new Date(cloudConfig.lastSync).toLocaleTimeString()}` : 'Sin registros recientes'}
              </p>
           </div>
        </div>

        {/* ACTIONS GRID */}
        <div className="grid grid-cols-2 gap-3 shrink-0">
           <button 
             onClick={() => executeSync('bidirectional')}
             disabled={status === 'syncing' || !isOnline}
             className="col-span-2 bg-indigo-600 text-white py-5 rounded-[2rem] font-black uppercase text-xs tracking-widest shadow-xl shadow-indigo-500/20 active:scale-[0.98] transition-all disabled:opacity-50 disabled:grayscale flex items-center justify-center gap-2"
           >
             <i className="fas fa-arrows-rotate"></i> Sincronizar Todo
           </button>

           <button 
             onClick={() => executeSync('pull')}
             disabled={status === 'syncing' || !isOnline}
             className="bg-slate-800 text-sky-400 py-4 rounded-[1.5rem] font-black uppercase text-[9px] tracking-wide border border-slate-700 active:bg-slate-700 transition-all flex flex-col items-center gap-1"
           >
             <i className="fas fa-cloud-arrow-down text-lg"></i> Descargar Nube
           </button>

           <button 
             onClick={() => { if(confirm("¿Forzar subida? Esto sobrescribirá la nube con tus datos locales.")) executeSync('push'); }}
             disabled={status === 'syncing' || !isOnline}
             className="bg-slate-800 text-rose-400 py-4 rounded-[1.5rem] font-black uppercase text-[9px] tracking-wide border border-slate-700 active:bg-slate-700 transition-all flex flex-col items-center gap-1"
           >
             <i className="fas fa-cloud-arrow-up text-lg"></i> Forzar Subida
           </button>
        </div>

        {/* STATS & LOGS */}
        <div className="flex-1 min-h-[200px] bg-black/40 rounded-[2rem] p-5 font-mono text-[10px] border border-white/5 relative overflow-hidden flex flex-col">
          <div className="flex justify-between items-center mb-3 opacity-50 pb-2 border-b border-white/10">
            <span className="uppercase font-bold tracking-widest">Terminal Aqua+</span>
            <div className="flex gap-1">
               <div className="w-2 h-2 rounded-full bg-red-500"></div>
               <div className="w-2 h-2 rounded-full bg-yellow-500"></div>
               <div className="w-2 h-2 rounded-full bg-green-500"></div>
            </div>
          </div>

          <div className="flex-1 overflow-y-auto space-y-1 custom-scrollbar">
            {logs.length === 0 && <span className="opacity-30 italic">Esperando comandos...</span>}
            {logs.map((log, i) => (
              <div key={i} className={`opacity-80 break-words ${log.includes('Error') ? 'text-rose-400' : log.includes('✅') ? 'text-emerald-400' : 'text-slate-300'}`}>
                {log}
              </div>
            ))}

            {lastStats && (
               <div className="mt-4 pt-4 border-t border-white/10">
                  <p className="text-emerald-400 font-bold mb-2">RESUMEN DE CAMBIOS:</p>
                  {Object.entries(lastStats).map(([key, stat]) => {
                     const s = stat as SyncStats;
                     return (s.added > 0 || s.updated > 0) && (
                        <div key={key} className="flex justify-between text-[9px] text-slate-400">
                           <span>{key}:</span>
                           <span>+{s.added} Nuevos | ~{s.updated} Act.</span>
                        </div>
                     );
                  })}
                  {Object.values(lastStats).every((s: any) => s.added === 0 && s.updated === 0) && (
                     <p className="text-slate-500 italic">No hubo cambios significativos.</p>
                  )}
               </div>
            )}
          </div>
        </div>

      </div>
    </div>
  );
};

