import { INITIAL_PRODUCTS, INITIAL_CUSTOMERS, BACKWASH_SEQUENCE, REGENERATION_SEQUENCE } from '../constants';

const DEFAULT_PERMISSIONS: ViewType[] = ['dashboard', 'pos', 'orders', 'customers', 'logistics', 'inventory', 'whatsapp', 'production', 'sync', 'reports', 'settings', 'employees', 'quality', 'scanner', 'tickets', 'messages', 'notifications'];

