// --- DEVICE ID MANAGEMENT ---
const getDeviceId = () => {
  let id = localStorage.getItem('aqua_device_id');
  if (!id) {
    // Generar un ID corto único (ej: 4A2B)
    id = Math.random().toString(36).substring(2, 6).toUpperCase();
