import React, { useState, useEffect } from 'react';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';

interface SyncModuleProps {
  onBack: () => void;
  onScanRequest: () => void;
  scannedId?: string;
}

type SyncStatus = 'idle' | 'syncing' | 'success' | 'error' | 'offline';
type SyncMode = 'bidirectional' | 'pull' | 'push';

interface SyncStats {
  added: number;
  updated: number;
  unchanged: number;
}

export const SyncModule: React.FC<SyncModuleProps> = ({ onBack, scannedId }) => {
  const { 
    sales, customers, products, orders, employees, vehicles, qualityRecords, tasks, attendance, savedReports, ticketConfig, messages,
    syncData, cloudConfig, setCloudConfig, deviceId
  } = useERPData();

  const [status, setStatus] = useState<SyncStatus>('idle');
  const [logs, setLogs] = useState<string[]>([]);
  const [editingConfig, setEditingConfig] = useState(false);
  const [tempConfig, setTempConfig] = useState(cloudConfig);
  const [lastStats, setLastStats] = useState<Record<string, SyncStats> | null>(null);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  const addLog = (msg: string) => {
    setLogs(prev => [`> ${msg}`, ...prev.slice(0, 15)]);
  };

  const handleSaveConfig = () => {
    let url = tempConfig.url.trim();
    if (url && !url.endsWith('/')) url += '/';
    setCloudConfig({ ...tempConfig, url });
    setEditingConfig(false);
    addLog("Configuración actualizada.");
  };

  // --- SMART MERGE ALGORITHM V2 (Robust for Firebase Objects) ---
  const smartMerge = <T extends { id: string, timestamp?: number, lastUpdated?: number }>(
    localList: T[], 
    cloudPayload: any
  ): { merged: T[], stats: SyncStats } => {
    const combinedMap = new Map<string, T>();
    let stats = { added: 0, updated: 0, unchanged: 0 };

    // 1. Normalize Cloud Data (Handle Firebase Object-as-Array quirks)
    let cloudList: T[] = [];
    if (Array.isArray(cloudPayload)) {
        cloudList = cloudPayload;
    } else if (typeof cloudPayload === 'object' && cloudPayload !== null) {
        // Convert dictionary to array
        cloudList = Object.values(cloudPayload);
    }

    const cloudMap = new Map<string, T>();
    cloudList.forEach(item => {
        if (item && item.id) cloudMap.set(item.id, item);
    });

    // 2. Process Local Items vs Cloud
    localList.forEach(localItem => {
        const cloudItem = cloudMap.get(localItem.id);

        if (!cloudItem) {
            // Item exists locally but not in cloud (New Local)
            combinedMap.set(localItem.id, localItem);
            // Count logic could vary, but usually this means we push it
        } else {
            // Conflict Resolution
            const localTime = localItem.lastUpdated || localItem.timestamp || 0;
            const cloudTime = cloudItem.lastUpdated || cloudItem.timestamp || 0;

            // Logic: Highest timestamp wins. If equal, local usually preferred to avoid UI flicker, 
            // unless we want to force cloud authority.
            if (localTime > cloudTime) {
                // Local is newer
                combinedMap.set(localItem.id, localItem);
                stats.updated++;
            } else if (cloudTime > localTime) {
                // Cloud is newer (Updates Local)
                combinedMap.set(localItem.id, cloudItem);
                stats.updated++;
            } else {
                // Same
                combinedMap.set(localItem.id, localItem);
                stats.unchanged++;
            }
            // Remove from cloudMap to identify what is ONLY in cloud later
            cloudMap.delete(localItem.id);
        }
    });

    // 3. Add remaining Cloud Items (New from Cloud)
    cloudMap.forEach((cloudItem, id) => {
        combinedMap.set(id, cloudItem);
        stats.added++;
    });

    return { merged: Array.from(combinedMap.values()), stats };
  };

  const executeSync = async (mode: SyncMode) => {
    if (!cloudConfig.url) {
      alert("Configura la URL de Firebase primero.");
      setEditingConfig(true);
      return;
    }
    if (!isOnline) {
      alert("Sin conexión a internet.");
      return;
    }

    setStatus('syncing');
    setLastStats(null);
    setLogs([]); // Clear logs for new run
    addLog(`Iniciando ${mode === 'bidirectional' ? 'Sincronización Inteligente' : mode === 'pull' ? 'Descarga' : 'Subida'}...`);

    try {
      const endpoint = `${cloudConfig.url}aqua_data.json${cloudConfig.apiKey ? `?auth=${cloudConfig.apiKey}` : ''}`;

      let cloudData: any = {};

      // STEP 1: FETCH (Always fetch first unless it's a blind force push, but even then we should merge to be safe)
      if (mode !== 'push') {
          addLog("☁️ Descargando datos de nube...");
          const getResponse = await fetch(endpoint);
          if (!getResponse.ok) throw new Error(`Error HTTP: ${getResponse.status}`);
          cloudData = await getResponse.json() || {};
          addLog("✅ Datos recibidos.");
      }

      // STEP 2: MERGE LOGIC
      let finalState: any = {};
      let syncStats: Record<string, SyncStats> = {};

      if (mode === 'pull') {
          addLog("⚡ Procesando descarga...");
          // In pull mode, we still merge but rely on cloud timestamps being generally authoritative
      } 

      const mergeCollection = (key: string, local: any[], cloud: any) => {
          // addLog(`.. Procesando ${key}`);
          const { merged, stats } = smartMerge(local, cloud);
          finalState[key] = merged;
          syncStats[key] = stats;
      };

      // Perform Merges
      if (mode === 'push') {
          // Just use local data as truth
          addLog("⚠️ Modo Push: Usando datos locales como maestro.");
          finalState = {
              sales, customers, products, orders, employees, vehicles, qualityRecords, tasks, attendance, savedReports, messages, ticketConfig
          };
          // Mock stats
          syncStats['Total'] = { added: 0, updated: 0, unchanged: 0 };
      } else {
          // Bidirectional or Pull
          mergeCollection('sales', sales, cloudData.sales);
          mergeCollection('customers', customers, cloudData.customers);
          mergeCollection('products', products, cloudData.products); // Critical for inventory
          mergeCollection('orders', orders, cloudData.orders);
          mergeCollection('employees', employees, cloudData.employees);
          mergeCollection('vehicles', vehicles, cloudData.vehicles); // Critical for route inventory
          mergeCollection('qualityRecords', qualityRecords, cloudData.qualityRecords);
          mergeCollection('tasks', tasks, cloudData.tasks);
          mergeCollection('attendance', attendance, cloudData.attendance);
          mergeCollection('savedReports', savedReports, cloudData.savedReports);
          mergeCollection('messages', messages, cloudData.messages);

          // Config merge (Simple object merge)
          finalState.ticketConfig = cloudData.ticketConfig || ticketConfig;
          finalState.productionConfig = cloudData.productionConfig || {}; // Handle Prod Config
      }

      // STEP 3: UPDATE LOCAL
      addLog("💾 Guardando en dispositivo...");
      const hasChanges = syncData(finalState);
      setLastStats(syncStats);
      if (hasChanges) addLog("-> Datos locales actualizados.");

      // STEP 4: UPLOAD (Only if not Pull-only)
      if (mode !== 'pull') {
          addLog("🚀 Subiendo cambios a nube...");
          const uploadPayload = {
            ...finalState,
            lastUpdated: Date.now(),
            deviceUser: deviceId || 'AquaPro Mobile'
          };

          const putResponse = await fetch(endpoint, {
            method: 'PUT', // PUT replaces the node. Safe because we merged first.
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(uploadPayload)
          });

          if (!putResponse.ok) throw new Error("Error al escribir en nube");
          addLog("✅ Nube actualizada correctamente.");
      } else {
          addLog("⏹️ Modo descarga finalizado (Sin subida).");
      }

      setCloudConfig(prev => ({ ...prev, lastSync: Date.now() }));
      setStatus('success');

    } catch (error: any) {
      console.error(error);
      setStatus('error');
      addLog(`❌ Error Crítico: ${error.message}`);
    }
  };

  // Auto-sync effect
  useEffect(() => {
    if (cloudConfig.autoSync && cloudConfig.url && status === 'idle' && isOnline) {
      const timer = setInterval(() => {
        executeSync('bidirectional');
      }, 30000); // 30 seconds interval for auto-sync
      return () => clearInterval(timer);
    }
  }, [cloudConfig, status, isOnline]);

  if (editingConfig) {
    return (
      <div className="h-full bg-slate-50 animate-fadeIn pb-24 overflow-y-auto">
        <ModuleHeader title="Configurar Nube" onBack={() => setEditingConfig(false)} />
        <div className="px-6 space-y-6">
          <div className="bg-white p-6 rounded-[2rem] shadow-lg border border-indigo-100">
             <div className="flex items-center gap-3 mb-4">
                <div className="w-12 h-12 bg-amber-100 rounded-2xl flex items-center justify-center text-amber-500 text-2xl">
                    <i className="fas fa-fire"></i>
                </div>
                <div>
                    <h3 className="font-black text-sky-900 leading-none">Firebase</h3>
                    <p className="text-[10px] font-bold text-sky-300 uppercase">Realtime Database</p>
                </div>
             </div>

             <div className="space-y-4">
               <div>
                 <label className="text-[10px] font-black uppercase text-sky-400 ml-2">URL del Proyecto</label>
                 <input 
                   type="url" 
                   placeholder="https://..." 
                   className="w-full bg-slate-50 p-4 rounded-2xl outline-none font-bold text-sky-900 text-xs focus:ring-2 ring-indigo-300 transition-all"
                   value={tempConfig.url}
                   onChange={e => setTempConfig({...tempConfig, url: e.target.value})}
                 />
               </div>

               <div>
                 <label className="text-[10px] font-black uppercase text-sky-400 ml-2">Auth Secret (Opcional)</label>
                 <input 
                   type="password" 
                   placeholder="Token..." 
                   className="w-full bg-slate-50 p-4 rounded-2xl outline-none font-bold text-sky-900 text-xs focus:ring-2 ring-indigo-300 transition-all"
                   value={tempConfig.apiKey}
                   onChange={e => setTempConfig({...tempConfig, apiKey: e.target.value})}
                 />
               </div>

               <div className="flex items-center gap-3 bg-indigo-50 p-4 rounded-2xl cursor-pointer" onClick={() => setTempConfig({...tempConfig, autoSync: !tempConfig.autoSync})}>
                 <div className={`w-10 h-6 rounded-full p-1 transition-colors ${tempConfig.autoSync ? 'bg-indigo-500' : 'bg-slate-300'}`}>
                   <div className={`w-4 h-4 bg-white rounded-full shadow-sm transition-transform ${tempConfig.autoSync ? 'translate-x-4' : ''}`}></div>
                 </div>
                 <span className="text-[10px] font-black text-indigo-900 uppercase">Auto-Sync (30s)</span>
               </div>
             </div>
          </div>
          <ActionButton onClick={handleSaveConfig}>Guardar Conexión</ActionButton>
        </div>
      </div>
    );
  }

  return (
    <div className="h-full bg-slate-900 text-white flex flex-col animate-fadeIn overflow-hidden pb-24">
      <div className="px-6 pt-8 pb-4 flex items-center justify-between">
        <div className="flex items-center gap-4">
          <button onClick={onBack} className="w-12 h-12 bg-white/10 rounded-2xl flex items-center justify-center active:scale-90 transition-transform">
            <i className="fas fa-arrow-left"></i>
          </button>
          <div>
            <h2 className="text-xl font-black tracking-tight">Aqua Cloud</h2>
            <div className="flex items-center gap-2">
               <div className={`w-2 h-2 rounded-full ${isOnline ? (cloudConfig.url ? 'bg-emerald-400' : 'bg-amber-400') : 'bg-red-500'}`}></div>
               <span className="text-[10px] font-bold uppercase opacity-70">
                 {isOnline ? (cloudConfig.url ? 'Conectado' : 'Sin Config') : 'Offline'}
               </span>
            </div>
          </div>
        </div>
        <button onClick={() => setEditingConfig(true)} className="w-10 h-10 bg-white/10 rounded-xl flex items-center justify-center text-sm active:bg-white/20">
          <i className="fas fa-gear"></i>
        </button>
      </div>

      <div className="flex-1 overflow-y-auto px-6 space-y-6 no-scrollbar pb-10 flex flex-col">

        {/* STATUS CARD */}
        <div className="bg-gradient-to-br from-slate-800 to-slate-900 p-6 rounded-[2.5rem] border border-white/5 relative overflow-hidden shrink-0">
           <div className={`absolute top-0 right-0 w-32 h-32 bg-indigo-500/10 rounded-full blur-2xl -mr-10 -mt-10 transition-opacity ${status === 'syncing' ? 'opacity-100' : 'opacity-0'}`}></div>

           <div className="flex flex-col items-center justify-center relative z-10 py-4">
              <div className={`w-24 h-24 rounded-full flex items-center justify-center text-4xl shadow-2xl transition-all duration-500 ${status === 'syncing' ? 'bg-indigo-600 scale-110 shadow-indigo-500/50' : status === 'success' ? 'bg-emerald-500 text-white' : status === 'error' ? 'bg-rose-500' : 'bg-slate-700'}`}>
                 <i className={`fas ${status === 'syncing' ? 'fa-arrows-rotate animate-spin' : status === 'success' ? 'fa-check' : status === 'error' ? 'fa-xmark' : 'fa-cloud'}`}></i>
              </div>

              <h3 className="text-xl font-black mt-4 mb-1 tracking-tight">
                {status === 'syncing' ? 'Sincronizando...' : status === 'success' ? 'Sincronización Exitosa' : status === 'error' ? 'Error de Sincronización' : 'Listo para Sincronizar'}
              </h3>

              <p className="text-[10px] font-mono text-slate-400">
                {cloudConfig.lastSync ? `Última vez: ${new Date(cloudConfig.lastSync).toLocaleTimeString()}` : 'Sin registros recientes'}
              </p>
           </div>
        </div>

        {/* ACTIONS GRID */}
        <div className="grid grid-cols-2 gap-3 shrink-0">
           <button 
             onClick={() => executeSync('bidirectional')}
             disabled={status === 'syncing' || !isOnline}
             className="col-span-2 bg-indigo-600 text-white py-5 rounded-[2rem] font-black uppercase text-xs tracking-widest shadow-xl shadow-indigo-500/20 active:scale-[0.98] transition-all disabled:opacity-50 disabled:grayscale flex items-center justify-center gap-2"
           >
             <i className="fas fa-arrows-rotate"></i> Sincronizar Todo
           </button>

           <button 
             onClick={() => executeSync('pull')}
             disabled={status === 'syncing' || !isOnline}
             className="bg-slate-800 text-sky-400 py-4 rounded-[1.5rem] font-black uppercase text-[9px] tracking-wide border border-slate-700 active:bg-slate-700 transition-all flex flex-col items-center gap-1"
           >
             <i className="fas fa-cloud-arrow-down text-lg"></i> Descargar Nube
           </button>

           <button 
             onClick={() => { if(confirm("¿Forzar subida? Esto sobrescribirá la nube con tus datos locales.")) executeSync('push'); }}
             disabled={status === 'syncing' || !isOnline}
             className="bg-slate-800 text-rose-400 py-4 rounded-[1.5rem] font-black uppercase text-[9px] tracking-wide border border-slate-700 active:bg-slate-700 transition-all flex flex-col items-center gap-1"
           >
             <i className="fas fa-cloud-arrow-up text-lg"></i> Forzar Subida
           </button>
        </div>

        {/* STATS & LOGS */}
        <div className="flex-1 min-h-[200px] bg-black/40 rounded-[2rem] p-5 font-mono text-[10px] border border-white/5 relative overflow-hidden flex flex-col">
          <div className="flex justify-between items-center mb-3 opacity-50 pb-2 border-b border-white/10">
            <span className="uppercase font-bold tracking-widest">Terminal Aqua+</span>
            <div className="flex gap-1">
               <div className="w-2 h-2 rounded-full bg-red-500"></div>
               <div className="w-2 h-2 rounded-full bg-yellow-500"></div>
               <div className="w-2 h-2 rounded-full bg-green-500"></div>
            </div>
          </div>

          <div className="flex-1 overflow-y-auto space-y-1 custom-scrollbar">
            {logs.length === 0 && <span className="opacity-30 italic">Esperando comandos...</span>}
            {logs.map((log, i) => (
              <div key={i} className={`opacity-80 break-words ${log.includes('Error') ? 'text-rose-400' : log.includes('✅') ? 'text-emerald-400' : 'text-slate-300'}`}>
                {log}
              </div>
            ))}

            {lastStats && (
               <div className="mt-4 pt-4 border-t border-white/10">
                  <p className="text-emerald-400 font-bold mb-2">RESUMEN DE CAMBIOS:</p>
                  {Object.entries(lastStats).map(([key, stat]) => {
                     const s = stat as SyncStats;
                     return (s.added > 0 || s.updated > 0) && (
                        <div key={key} className="flex justify-between text-[9px] text-slate-400">
                           <span>{key}:</span>
                           <span>+{s.added} Nuevos | ~{s.updated} Act.</span>
                        </div>
                     );
                  })}
                  {Object.values(lastStats).every((s: any) => s.added === 0 && s.updated === 0) && (
                     <p className="text-slate-500 italic">No hubo cambios significativos.</p>
                  )}
               </div>
            )}
          </div>
        </div>

      </div>
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { Customer, GarrafonType } from '../types';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';
import { Filesystem, Directory, Encoding } from '@capacitor/filesystem';

const GARRAFON_TYPES: { type: GarrafonType, color: string, label: string }[] = [
  { type: 'Aqua', color: 'bg-indigo-500', label: 'Aqua+' },
  { type: 'Bonafont', color: 'bg-orange-400', label: 'Bonafont' },
  { type: 'Ciel', color: 'bg-sky-400', label: 'Ciel' },
  { type: 'E-Pura', color: 'bg-blue-600', label: 'Epura' },
  { type: 'Generico', color: 'bg-slate-400', label: 'Genérico' }
];

export const CustomersModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const { customers, saveCustomer, deleteCustomer, sales, importCustomers } = useERPData();
  const [search, setSearch] = useState('');
  const [editingCustomer, setEditingCustomer] = useState<Partial<Customer> | null>(null);
  const [viewingHistory, setViewingHistory] = useState<Customer | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const filteredCustomers = customers.filter(c => 
    c.name.toLowerCase().includes(search.toLowerCase()) || 
    c.alias.toLowerCase().includes(search.toLowerCase())
  );

  // --- LÓGICA DE NAVEGACIÓN INTELIGENTE ---
  const handleBackNavigation = () => {
    if (editingCustomer || viewingHistory) {
      setEditingCustomer(null);
      setViewingHistory(null);
    } else {
      onBack();
    }
  };

  const handleSave = () => {
    if (!editingCustomer?.name || !editingCustomer?.alias) {
      alert("Nombre y Alias son obligatorios.");
      return;
    }
    const customerToSave: Customer = {
      id: editingCustomer.id || Math.random().toString(36).substr(2, 9),
      name: editingCustomer.name,
      alias: editingCustomer.alias,
      phone: editingCustomer.phone || '',
      address: editingCustomer.address || '',
      specialPrice: editingCustomer.specialPrice || undefined,
      garrafonType: editingCustomer.garrafonType || 'Generico',
      jugsOnLoan: editingCustomer.jugsOnLoan || 0,
      balance: editingCustomer.balance || 0,
      lat: editingCustomer.lat,
      lng: editingCustomer.lng,
    };
    saveCustomer(customerToSave);
    setEditingCustomer(null);
  };

  const handleDelete = () => {
    if (!editingCustomer?.id) return;
    const confirmDelete = window.confirm(
      `¿Estás seguro de eliminar a "${editingCustomer.alias}"?\n\nEsta acción eliminará el registro del cliente permanentemente. Su historial de ventas se mantendrá como anónimo.`
    );
    if (confirmDelete) {
      deleteCustomer(editingCustomer.id);
      setEditingCustomer(null);
    }
  };

  const handleGetLocation = () => {
    if (!navigator.geolocation) {
      alert("Tu dispositivo no soporta geolocalización.");
      return;
    }

    const btn = document.getElementById('gps-btn');
    if(btn) {
       btn.innerHTML = '<i class="fas fa-circle-notch animate-spin"></i> Obteniendo...';
       btn.classList.add('opacity-50', 'pointer-events-none');
    }

    const onSuccess = (position: GeolocationPosition) => {
        // Al setear el estado, React re-renderiza y el botón cambiará a modo "Bloqueado" automáticamente
        setEditingCustomer(prev => prev ? ({
          ...prev,
          lat: position.coords.latitude,
          lng: position.coords.longitude
        }) : null);
    };

    const onError = (error: GeolocationPositionError) => {
        console.error("GPS Error:", error);
        if(btn) {
          btn.innerHTML = '<i class="fas fa-triangle-exclamation"></i> Reintentar';
          btn.classList.remove('opacity-50', 'pointer-events-none');
        }
        alert(`No se pudo obtener la ubicación precise (Error ${error.code}). Verifica que el GPS esté encendido.`);
    };

    // Intento 1: Alta Precisión
    navigator.geolocation.getCurrentPosition(
      onSuccess,
      () => {
        console.warn("High accuracy failed, trying low accuracy...");
        // Intento 2: Baja Precisión (Fallback)
        navigator.geolocation.getCurrentPosition(onSuccess, onError, { 
            enableHighAccuracy: false, 
            timeout: 10000, 
            maximumAge: 0 
        });
      },
      { enableHighAccuracy: true, timeout: 5000, maximumAge: 0 }
    );
  };

  const openGoogleMaps = (lat?: number, lng?: number) => {
    if (lat && lng) {
      window.open(`https://www.google.com/maps/search/?api=1&query=${lat},${lng}`, '_blank');
    } else {
      alert("Este cliente no tiene ubicación registrada.");
    }
  };

  // --- LOGICA DE EXPORTACIÓN E IMPORTACIÓN ---

  const handleExportCSV = async () => {
    const headers = ["ID", "Nombre", "Alias", "Telefono", "Direccion", "Saldo", "Precio Especial", "Tipo Garrafon", "Garrafones Prestados", "Lat", "Lng"];
    const rows = customers.map(c => [
      c.id,
      `"${c.name}"`,
      `"${c.alias}"`,
      c.phone || '',
      `"${c.address || ''}"`,
      c.balance,
      c.specialPrice || '',
      c.garrafonType || 'Generico',
      c.jugsOnLoan || 0,
      c.lat || '',
      c.lng || ''
    ]);
    const csvContent = [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
    const fileName = `Clientes_Aqua_${new Date().getTime()}.csv`;

    try {
        // Intento 1: Guardar en Sistema de Archivos (Android/iOS)
        await Filesystem.writeFile({
            path: fileName,
            data: csvContent,
            directory: Directory.Documents,
            encoding: Encoding.UTF8
        });
        alert('Archivo CSV guardado exitosamente en la carpeta "Documentos" de tu dispositivo.');
    } catch (e) {
        console.warn("Filesystem write failed, falling back to browser download", e);

        // Intento 2: Descarga Web Clásica (Fallback)
        const blob = new Blob([csvContent], { type: 'text/csv' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = fileName;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    }
  };

  // --- NUEVA FUNCIÓN: IMPORTAR CONTACTOS DEL TELÉFONO ---
  const handleImportContacts = async () => {
    const nav = navigator as any;

    // Verificar soporte de la API de Selección de Contactos (Chrome Android / PWA)
    if ('contacts' in nav && 'select' in nav.contacts) {
      try {
        const props = ['name', 'tel', 'address'];
        const opts = { multiple: true };

        const contacts = await nav.contacts.select(props, opts);

        if (contacts.length > 0) {
           const newCustomers: Customer[] = contacts.map((c: any) => ({
             id: Math.random().toString(36).substr(2, 9),
             name: c.name[0] || 'Desconocido',
             alias: c.name[0] || 'Desconocido',
             phone: c.tel ? c.tel[0] : '',
             address: c.address ? c.address[0]?.addressLine : '',
             balance: 0,
             garrafonType: 'Generico'
           }));

           importCustomers(newCustomers);
           alert(`Se importaron ${newCustomers.length} contactos exitosamente.`);
        }
      } catch (ex) {
        // El usuario canceló o hubo error
        console.log("Importación cancelada o fallida:", ex);
      }
    } else {
      // Fallback: Explicar
      alert("Tu dispositivo no soporta la selección directa de contactos. Por favor usa la opción de 'Importar CSV' o agrega manualmente.");
    }
  };

  const handleImportFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      if (!text) return;

      try {
        let importedCount = 0;
        const newCustomers: Customer[] = [];

        if (file.name.toLowerCase().endsWith('.csv')) {
          const lines = text.replace(/\r\n/g, '\n').replace(/\r/g, '\n').split('\n');
          if (lines.length > 0) {
            const headerLine = lines[0].toLowerCase();
            const headers = headerLine.split(',').map(h => h.trim().replace(/^"|"$/g, ''));

            const idxNombre = headers.findIndex(h => h.includes('nombre'));
            const idxAlias = headers.findIndex(h => h.includes('alias') || h.includes('comercial'));
            const idxTelefono = headers.findIndex(h => h.includes('telefono') || h.includes('celular') || h.includes('whatsapp'));
            const idxDireccion = headers.findIndex(h => h.includes('direccion') || h.includes('domicilio'));
            const idxSaldo = headers.findIndex(h => h.includes('saldo'));
            const idxPrecio = headers.findIndex(h => h.includes('precio'));

            lines.slice(1).forEach(line => {
              if (!line.trim()) return;
              const cols = line.split(',').map(c => c.replace(/^"|"$/g, '').trim());
              const finalName = (idxNombre !== -1 ? cols[idxNombre] : '') || (idxAlias !== -1 ? cols[idxAlias] : '') || 'Importado';
              const finalAlias = (idxAlias !== -1 ? cols[idxAlias] : '') || finalName;

              if (finalAlias) {
                newCustomers.push({
                  id: Math.random().toString(36).substr(2, 9),
                  name: finalName,
                  alias: finalAlias,
                  phone: idxTelefono !== -1 ? cols[idxTelefono] : '',
                  address: idxDireccion !== -1 ? cols[idxDireccion] : '',
                  balance: idxSaldo !== -1 ? (parseFloat(cols[idxSaldo]) || 0) : 0,
                  specialPrice: idxPrecio !== -1 ? (parseFloat(cols[idxPrecio]) || undefined) : undefined,
                  garrafonType: 'Generico',
                });
                importedCount++;
              }
            });
          }
        }

        if (importedCount > 0) {
          importCustomers(newCustomers);
          alert(`¡Éxito! Se importaron ${importedCount} clientes.`);
        } else {
          alert("No se encontraron datos válidos en el CSV.");
        }
      } catch (err) {
        alert("Error al procesar el archivo.");
      }
      if (fileInputRef.current) fileInputRef.current.value = '';
    };
    reader.readAsText(file);
  };

  // --- UI RENDER ---

  if (viewingHistory) {
    const customerSales = sales.filter(s => s.customerId === viewingHistory.id);
    const hasDebt = viewingHistory.balance > 0;
    const hasCredit = viewingHistory.balance < 0;
    const garrafon = GARRAFON_TYPES.find(g => g.type === (viewingHistory.garrafonType || 'Generico'));

    return (
      <div className="h-full bg-sky-50 overflow-y-auto no-scrollbar pb-24">
        <ModuleHeader title={`Perfil: ${viewingHistory.alias}`} onBack={handleBackNavigation} />
        <div className="px-6 space-y-4">
          <RoundedCard className={`${hasDebt ? 'bg-red-500' : hasCredit ? 'bg-emerald-500' : 'bg-sky-600'} text-white shadow-lg border-none transition-colors duration-500`}>
             <div className="flex justify-between items-center">
                <div>
                   <span className="text-[10px] font-black uppercase opacity-70">
