import React, { useState, useEffect } from 'react';
import { Product, Customer, CartItem, PaymentSplit, Sale, Employee, TicketConfig, Order, GarrafonType } from '../types';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';
import html2canvas from 'html2canvas';
import { Filesystem, Directory } from '@capacitor/filesystem';
import { Share } from '@capacitor/share';
import { generateTicketPDF } from '../services/pdfGenerator';

// Helper to convert Uint8Array to Base64
const uint8ArrayToBase64 = (bytes: Uint8Array) => {
    let binary = '';
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) {
        binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
}

const GARRAFON_COLORS: Record<GarrafonType, string> = {
  'Aqua': 'bg-indigo-500',
  'Bonafont': 'bg-orange-400',
  'Ciel': 'bg-sky-400',
  'E-Pura': 'bg-blue-600',
  'Generico': 'bg-slate-400'
};

const TicketModal = ({ sale, config, onClose, onWhatsApp, onNewSale, onFinish }: any) => {
  const [sharing, setSharing] = useState(false);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved' | 'error'>('idle');
  const qrData = btoa(`AQUA-PRO-SECURE|${JSON.stringify({ id: sale.id, total: sale.total })}`);
  const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(qrData)}`;

  // Auto-save logic restored
  const handleAutoSave = async () => {
    try {
      setSaveStatus('saving');
      const element = document.getElementById('printable-ticket');
      if (!element) return;

      const canvas = await html2canvas(element, { scale: 2, backgroundColor: '#ffffff', logging: false });
      const base64Data = canvas.toDataURL('image/png').split(',')[1];
      const folderName = 'AquaTickets';
      const fileName = `Ticket_${sale.id}_${Date.now()}.png`;

      try {
        await Filesystem.mkdir({ path: folderName, directory: Directory.Documents, recursive: true });
        await Filesystem.writeFile({ path: `${folderName}/${fileName}`, data: base64Data, directory: Directory.Documents });
        setSaveStatus('saved');
      } catch (fsError) {
        console.warn("Auto-save skipped (Web mode)", fsError);
        setSaveStatus('error');
      }
    } catch (e) {
      console.error("Error generating image", e);
      setSaveStatus('error');
    }
  };

  useEffect(() => { setTimeout(handleAutoSave, 800); }, []);

  const handleSharePDF = async () => {
    setSharing(true);
    try {
        const pdfBytes = await generateTicketPDF(sale, config);
        const base64Content = uint8ArrayToBase64(pdfBytes);
        const fileName = `Ticket_${sale.id}.pdf`;

        const savedFile = await Filesystem.writeFile({
          path: fileName,
          data: base64Content,
          directory: Directory.Cache
        });

        await Share.share({
            title: `Ticket ${sale.id}`,
            text: `Hola ${sale.customerAlias}, adjunto tu ticket de compra en Aqua+.`,
            url: savedFile.uri,
            dialogTitle: 'Compartir Ticket'
        });
    } catch (e) {
        console.error(e);
        // Fallback Web
        try {
            const pdfBytes = await generateTicketPDF(sale, config);
            const file = new File([pdfBytes], `Ticket_${sale.id}.pdf`, { type: 'application/pdf' });
            const url = URL.createObjectURL(file);
            const link = document.createElement('a');
            link.href = url;
            link.download = file.name;
            link.click();
            setTimeout(() => URL.revokeObjectURL(url), 1000);
        } catch(webErr) {
            alert("No se pudo compartir.");
        }
    } finally {
        setSharing(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[300] bg-slate-900/80 backdrop-blur-md flex flex-col items-center justify-center p-4 animate-fadeIn">
      <div className="bg-white w-full max-w-[340px] max-h-[85vh] shadow-2xl rounded-[2.5rem] overflow-hidden flex flex-col relative">
        <div className="absolute top-0 left-0 right-0 h-1.5 bg-gradient-to-r from-sky-400 via-indigo-500 to-sky-400"></div>

        {saveStatus === 'saved' && (
          <div className="absolute top-3 right-4 bg-emerald-100 text-emerald-600 px-2 py-0.5 rounded-full text-[8px] font-black uppercase flex items-center gap-1 animate-fadeIn z-20">
            <i className="fas fa-check-circle"></i> Guardado
          </div>
        )}

        <div className="overflow-y-auto flex-1 p-6 pb-2 text-center font-mono text-slate-800 leading-tight text-xs relative custom-scrollbar" id="printable-ticket">
            {config.logoUrl && <img src={config.logoUrl} alt="Logo" className="w-20 h-20 object-contain mx-auto mb-3 grayscale mix-blend-multiply" />}
            <h2 className="text-lg font-black uppercase mb-1 tracking-tighter text-sky-900">{config.businessName}</h2>

            <div className="border-b-2 border-dashed border-slate-200 pb-3 mb-3 space-y-0.5 text-slate-500">
              <p>{new Date(sale.timestamp).toLocaleString()}</p>
              <p>Folio: {sale.id}</p>
            </div>

            <table className="w-full mb-3 border-collapse">
              <thead>
                <tr className="border-b border-slate-900">
                  <th className="text-left py-1 w-8">Cant</th>
                  <th className="text-left py-1">Desc</th>
                  <th className="text-right py-1">Total</th>
                </tr>
              </thead>
              <tbody>
                {sale.items.map((item: any, i: number) => (
                  <tr key={i}>
                    <td className="text-left py-1 align-top font-bold">{item.quantity}</td>
                    <td className="text-left py-1 align-top">{item.name.slice(0, 18)}</td>
                    <td className="text-right py-1 align-top">${(item.quantity * item.price).toFixed(2)}</td>
                  </tr>
                ))}
              </tbody>
            </table>

            <div className="border-t-2 border-slate-900 pt-2 mb-2 text-right">
              <p className="text-xl font-black">TOTAL: ${sale.total.toFixed(2)}</p>
            </div>

            <div className="flex flex-col items-center pb-2 mt-4">
              <img src={qrUrl} alt="QR" className="w-16 h-16 mb-1 mix-blend-multiply opacity-80" />
              <p className="text-[8px] uppercase font-bold text-slate-400">Gracias por su compra</p>
            </div>
        </div>

        <div className="bg-slate-50 p-4 border-t border-slate-100 shrink-0 space-y-3 z-20">
             <div className="grid grid-cols-2 gap-3">
                <button onClick={handleSharePDF} disabled={sharing} className="bg-indigo-600 text-white py-3 rounded-2xl font-black text-[10px] uppercase shadow-lg shadow-indigo-200 active:scale-95 transition-transform flex items-center justify-center gap-2">
                    {sharing ? <i className="fas fa-spinner animate-spin"></i> : <i className="fas fa-share-nodes"></i>} Compartir
                </button>
                <button onClick={onWhatsApp} className="bg-emerald-500 text-white py-3 rounded-2xl font-black text-[10px] uppercase shadow-lg shadow-emerald-200 active:scale-95 transition-transform flex items-center justify-center gap-2">
                    <i className="fab fa-whatsapp"></i> WhatsApp
                </button>
             </div>
             <button onClick={onNewSale} className="w-full bg-sky-500 text-white py-3 rounded-2xl font-black text-[10px] uppercase shadow-lg shadow-sky-200 active:scale-95 transition-transform">
                Nueva Venta
             </button>
             <button onClick={onFinish} className="w-full text-slate-400 text-[10px] font-bold uppercase hover:text-rose-400 transition-colors">Cerrar</button>
        </div>
      </div>
    </div>
  );
};

const PaymentModal = ({ total, onConfirm, onCancel }: any) => {
  const [cash, setCash] = useState('');
  const [transfer, setTransfer] = useState('');
  const [card, setCard] = useState('');
  const numCash = parseFloat(cash) || 0;
  const numTransfer = parseFloat(transfer) || 0;
  const numCard = parseFloat(card) || 0;

  const totalPaid = numCash + numTransfer + numCard;
  const remaining = total - totalPaid;
  const isComplete = totalPaid >= (total - 0.01);

  return (
    <div className="fixed inset-0 z-[150] bg-slate-900/80 backdrop-blur-sm flex items-end sm:items-center justify-center animate-fadeIn">
      <div className="bg-white w-full max-w-md rounded-t-[2.5rem] sm:rounded-[2.5rem] p-8 shadow-2xl max-h-[90vh] overflow-y-auto no-scrollbar">
         <div className="flex justify-between items-center mb-6">
            <h3 className="text-xl font-black text-slate-800">Método de Pago</h3>
            <button onClick={onCancel} className="w-10 h-10 bg-slate-100 rounded-full text-slate-400 hover:bg-slate-200 transition-colors"><i className="fas fa-times"></i></button>
         </div>

         <div className="text-center mb-6">
            <p className="text-xs font-bold uppercase text-slate-400 tracking-widest mb-1">Total a Cobrar</p>
            <p className="text-5xl font-black text-slate-800 tracking-tighter">${total.toFixed(2)}</p>
         </div>

         <div className="space-y-3 mb-8">
            <div className="bg-slate-50 p-4 rounded-[1.5rem] flex items-center gap-4 border border-slate-100 focus-within:ring-2 ring-emerald-400 transition-all">
               <div className="w-12 h-12 bg-white rounded-2xl flex items-center justify-center text-emerald-500 shadow-sm text-xl"><i className="fas fa-money-bill-wave"></i></div>
               <div className="flex-1">
                  <label className="text-[9px] font-black uppercase text-slate-400 block mb-1">Efectivo</label>
                  <input type="number" placeholder="0.00" className="w-full bg-transparent font-black text-xl text-slate-800 outline-none placeholder-slate-300" value={cash} onChange={e => setCash(e.target.value)} autoFocus />
               </div>
            </div>

            <div className="bg-slate-50 p-4 rounded-[1.5rem] flex items-center gap-4 border border-slate-100 focus-within:ring-2 ring-indigo-400 transition-all">
               <div className="w-12 h-12 bg-white rounded-2xl flex items-center justify-center text-indigo-500 shadow-sm text-xl"><i className="fas fa-building-columns"></i></div>
               <div className="flex-1">
                  <label className="text-[9px] font-black uppercase text-slate-400 block mb-1">Transferencia</label>
                  <input type="number" placeholder="0.00" className="w-full bg-transparent font-black text-xl text-slate-800 outline-none placeholder-slate-300" value={transfer} onChange={e => setTransfer(e.target.value)} />
               </div>
            </div>

            <div className="bg-slate-50 p-4 rounded-[1.5rem] flex items-center gap-4 border border-slate-100 focus-within:ring-2 ring-purple-400 transition-all">
               <div className="w-12 h-12 bg-white rounded-2xl flex items-center justify-center text-purple-500 shadow-sm text-xl"><i className="fas fa-credit-card"></i></div>
               <div className="flex-1">
                  <label className="text-[9px] font-black uppercase text-slate-400 block mb-1">Tarjeta (T. Crédito/Débito)</label>
                  <input type="number" placeholder="0.00" className="w-full bg-transparent font-black text-xl text-slate-800 outline-none placeholder-slate-300" value={card} onChange={e => setCard(e.target.value)} />
               </div>
            </div>
         </div>

         <ActionButton onClick={() => onConfirm(numCash, numTransfer, numCard)} variant={isComplete ? 'primary' : 'secondary'}>
            {isComplete ? 'Confirmar Cobro' : `Restan $${remaining.toFixed(2)}`}
         </ActionButton>
      </div>
    </div>
  );
};

export const POSModule: React.FC<{ onBack: () => void; user: Employee; initialOrder?: Order | null; onClearInitialOrder?: () => void; }> = ({ onBack, user, initialOrder, onClearInitialOrder }) => {
  const { products, customers, sales, addSale, ticketConfig, vehicles, updateOrder } = useERPData();
  const [activeTab, setActiveTab] = useState<'sell' | 'history'>('sell');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [customer, setCustomer] = useState<Customer | null>(null);
  const [search, setSearch] = useState('');
  const [vacios, setVacios] = useState(0);
  const [selectedSource, setSelectedSource] = useState<string>('plant');
  const [showPaymentModal, setShowPaymentModal] = useState(false);
  const [viewingTicket, setViewingTicket] = useState<Sale | null>(null);
  const [linkedOrderId, setLinkedOrderId] = useState<string | null>(null);
  const [originalOrder, setOriginalOrder] = useState<Order | null>(null);

  // Load Order Data
  useEffect(() => {
    if (initialOrder) {
      let client = customers.find(c => c.id === initialOrder.customerId);
      if (!client) {
         // Fallback if client isn't in DB yet
         client = { 
           id: initialOrder.customerId, 
           name: initialOrder.customerAlias, 
           alias: initialOrder.customerAlias, 
           balance: 0, 
           phone: '', 
           garrafonType: 'Generico' 
         } as Customer;
      }
      setCustomer(client);
      setSearch(client.alias);
      setCart(initialOrder.items);

      // Auto-load jug quantity into 'vacios' (1:1 exchange assumption) to ensure seamless flow
      const initialJugs = initialOrder.items
        .filter(i => i.name.toLowerCase().includes('garraf') || i.category === 'Agua')
        .reduce((acc, i) => acc + i.quantity, 0);
      setVacios(initialJugs);

      if (initialOrder.vehicleId && vehicles.some(v => v.id === initialOrder.vehicleId)) setSelectedSource(initialOrder.vehicleId);
      setLinkedOrderId(initialOrder.id);
      setOriginalOrder(initialOrder);

      // Crucial: Clear order from App state to prevent stale data re-load, 
      // but ensure POS doesn't unmount (handled in App.tsx by static key)
      if (onClearInitialOrder) onClearInitialOrder();
    }
  }, [initialOrder, customers, vehicles, onClearInitialOrder]);

  // SPECIAL PRICE LOGIC: Always respects customer specific price for ID 1 (Garrafon)
  const total = cart.reduce((sum, item) => {
    const price = (customer?.specialPrice && item.id === '1') ? customer.specialPrice : item.price;
    return sum + (price * item.quantity);
  }, 0);

  useEffect(() => {
    // Only auto-update vacios if user hasn't started messing with it manually OR if it's the initial load
    // The previous useEffect handles initial load from Order.
    // This effect handles dynamic cart changes.
    // We check if it's NOT a linked order to avoid overriding the initial logic, or simply sync
    if (!linkedOrderId) {
        const garrafonesInCart = cart.filter(i => i.name.toLowerCase().includes('garraf') || i.category === 'Agua').reduce((acc, i) => acc + i.quantity, 0);
        if (cart.length > 0 && vacios === 0) setVacios(garrafonesInCart);
        else if (cart.length === 0) setVacios(0);
    }
  }, [cart, linkedOrderId]);

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === product.id);
      if (existing) return prev.map(i => i.id === product.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const decreaseQuantity = (productId: string) => {
    setCart(prev => prev.map(item => item.id === productId ? { ...item, quantity: Math.max(0, item.quantity - 1) } : item).filter(item => item.quantity > 0));
  };

  const handlePreCheckout = () => {
    if (!customer) return alert("Selecciona un cliente.");
    if (cart.length === 0) return alert("Carrito vacío.");

    // VALIDACIÓN DE STOCK (Solo si es vehículo)
    if (selectedSource !== 'plant') {
        const vehicle = vehicles.find(v => v.id === selectedSource);
        if (vehicle) {
            const currentInv = vehicle.inventory || [];

            const missing = cart.filter(item => {
                const stockItem = currentInv.find(i => i.id === item.id);
                // Es nulo si no existe el item o si la cantidad es menor a la requerida
                return !stockItem || stockItem.quantity < item.quantity;
            });

            if (missing.length > 0) {
                const names = missing.map(m => `- ${m.name}`).join('\n');
                const confirmSale = window.confirm(
                    `⚠️ STOCK INSUFICIENTE EN UNIDAD\n\n` +
                    `El vehículo no tiene carga suficiente de:\n${names}\n\n` +
                    `¿Deseas forzar la venta (Stock Negativo)?`
                );
                if (!confirmSale) return;
            }
        }
    }

    setShowPaymentModal(true);
  };

  const handleConfirmPayment = (cash: number, transfer: number, card: number) => {
    if(!customer) return;
    const totalPaid = cash + transfer + card;
    const splits: PaymentSplit[] = [];
    if (cash > 0) splits.push({ method: 'Efectivo', amount: cash });
    if (transfer > 0) splits.push({ method: 'Transferencia', amount: transfer });
    if (card > 0) splits.push({ method: 'Tarjeta', amount: card });

    // La validación principal ya se hizo en handlePreCheckout
    // Aquí solo procesamos la venta (incluso si genera negativo)
    const sale = addSale(customer.id, cart, total, totalPaid, splits, vacios, undefined, selectedSource === 'plant' ? undefined : selectedSource);

    if (originalOrder) {
       updateOrder({ ...originalOrder, status: 'entregado' });
    }

    setShowPaymentModal(false);
    setViewingTicket(sale);
  };

  const resetPOS = () => {
    setViewingTicket(null);
    setCart([]);
    setCustomer(null);
    setSearch('');
    setVacios(0);
    setLinkedOrderId(null);
    setOriginalOrder(null);
    setActiveTab('sell');
  };

  return (
    <div className="h-full flex flex-col animate-fadeIn bg-transparent pb-24 overflow-hidden relative">
      <ModuleHeader title="Punto de Venta" onBack={onBack} />

      <div className="px-6 flex gap-2 mb-4 shrink-0">
        <button onClick={() => setActiveTab('sell')} className={`flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'sell' ? 'bg-sky-600 text-white shadow-lg' : 'bg-white text-slate-400'}`}>Venta</button>
        <button onClick={() => setActiveTab('history')} className={`flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'history' ? 'bg-sky-600 text-white shadow-lg' : 'bg-white text-slate-400'}`}>Historial</button>
      </div>

      {activeTab === 'sell' ? (
        <div className="flex-1 overflow-y-auto px-6 space-y-6 pb-32 no-scrollbar">

          {linkedOrderId && (
            <div className="bg-amber-100 text-amber-700 p-4 rounded-[1.5rem] border border-amber-200 flex justify-between items-center shadow-sm">
               <span className="text-xs font-black uppercase tracking-wide flex items-center gap-2"><i className="fas fa-clipboard-check"></i> Pedido: {linkedOrderId}</span>
               <button onClick={resetPOS} className="w-8 h-8 bg-white rounded-full text-amber-500 flex items-center justify-center shadow-sm active:scale-90 transition-transform"><i className="fas fa-times"></i></button>
            </div>
          )}

          <div className="overflow-x-auto pb-2 no-scrollbar">
            <div className="flex gap-2 min-w-max">
              <button 
                onClick={() => setSelectedSource('plant')}
                className={`px-5 py-3 rounded-2xl text-[10px] font-black uppercase flex items-center gap-2 transition-all ${selectedSource === 'plant' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-200' : 'bg-white text-slate-400 border border-slate-100'}`}
              >
                <i className="fas fa-store"></i> Planta
              </button>
              {vehicles.map(v => (
                <button 
                  key={v.id}
                  onClick={() => setSelectedSource(v.id)}
                  className={`px-5 py-3 rounded-2xl text-[10px] font-black uppercase flex items-center gap-2 transition-all ${selectedSource === v.id ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-200' : 'bg-white text-slate-400 border border-slate-100'}`}
                >
                  <i className="fas fa-truck"></i> {v.plate}
                </button>
              ))}
            </div>
          </div>

          <div className="relative z-20">
            <input type="text" placeholder="Buscar Cliente..." className="w-full bg-white border-none rounded-[1.5rem] py-4 px-6 shadow-sm outline-none font-bold text-slate-700 placeholder-slate-300 focus:ring-2 ring-sky-300 transition-all" value={search} onChange={e => setSearch(e.target.value)} />
            {search && !customer && (
              <div className="absolute top-full left-0 right-0 bg-white shadow-xl rounded-[1.5rem] mt-2 overflow-hidden border border-slate-100 max-h-48 overflow-y-auto z-50">
                {customers.filter(c => c.alias.toLowerCase().includes(search.toLowerCase())).map(c => (
                  <button key={c.id} onClick={() => { setCustomer(c); setSearch(c.alias); }} className="w-full text-left p-4 hover:bg-sky-50 border-b border-slate-50 last:border-none">
                    <span className="text-slate-800 font-bold text-sm block">{c.alias}</span>
                  </button>
                ))}
              </div>
            )}
            {customer && (
              <div className="mt-2 bg-white p-3 rounded-[1.5rem] shadow-sm border border-sky-100 flex justify-between items-center animate-fadeIn">
                <div className="flex items-center gap-3">
                   <div className="w-10 h-10 bg-sky-100 rounded-full flex items-center justify-center text-sky-600"><i className="fas fa-user-check"></i></div>
                   <div>
                      <span className="font-black text-slate-800 text-sm block">{customer.alias}</span>
                      <div className="flex gap-2 items-center">
                        {customer.specialPrice && <span className="text-[8px] text-amber-500 font-bold uppercase">Precio Esp: ${customer.specialPrice}</span>}
                        {customer.garrafonType && (
                            <span className={`text-[8px] text-white font-bold uppercase px-2 py-0.5 rounded-full ${GARRAFON_COLORS[customer.garrafonType] || 'bg-slate-400'}`}>
                                Pref: {customer.garrafonType}
                            </span>
                        )}
                      </div>
                   </div>
                </div>
                <button onClick={() => {setCustomer(null); setSearch('');}} className="w-8 h-8 flex items-center justify-center text-rose-400 bg-rose-50 rounded-full hover:bg-rose-100 transition-colors"><i className="fas fa-times"></i></button>
              </div>
            )}
          </div>

          <div className="grid grid-cols-2 gap-3">
            {products.filter(p => p.category !== 'Insumos').map(p => {
               const inCart = cart.find(i => i.id === p.id)?.quantity || 0;
               // Determine price to show (Customer specific or default)
               const effectivePrice = (customer?.specialPrice && p.id === '1') ? customer.specialPrice : p.price;
               const isSpecial = (customer?.specialPrice && p.id === '1');

               return (
                <button key={p.id} onClick={() => addToCart(p)} className={`p-4 rounded-[1.8rem] text-left transition-all relative overflow-hidden group ${inCart > 0 ? 'bg-gradient-to-br from-sky-500 to-indigo-600 text-white shadow-lg shadow-sky-300' : 'bg-white text-slate-600 shadow-sm border border-white'}`}>
                  <div className="relative z-10">
                    <p className={`text-[9px] font-black uppercase mb-1 tracking-wide ${inCart > 0 ? 'text-sky-100' : 'text-slate-400'}`}>{p.category}</p>
                    <h4 className="font-bold text-sm leading-tight mb-2 pr-4">{p.name.replace('Garrafón', 'G.')}</h4>
                    <div className="flex items-center gap-1">
                        <p className="text-lg font-black">${effectivePrice}</p>
                        {isSpecial && <i className={`fas fa-tag text-[10px] ${inCart > 0 ? 'text-amber-300' : 'text-amber-500'}`}></i>}
                    </div>
                  </div>
                  {inCart > 0 && (
                    <div className="absolute top-3 right-3 w-8 h-8 bg-white text-sky-600 rounded-full flex items-center justify-center font-black text-sm shadow-sm animate-bounce">
                      {inCart}
                    </div>
                  )}
                  <div className={`absolute -bottom-4 -right-4 w-16 h-16 rounded-full ${inCart > 0 ? 'bg-white/10' : 'bg-slate-50'} blur-xl`}></div>
                </button>
               );
            })}
          </div>

          {cart.length > 0 && (
            <div className="bg-white rounded-[2rem] p-5 shadow-lg shadow-slate-100/50 border border-white animate-slideUp">
               <div className="flex justify-between items-center mb-4">
                  <h4 className="text-xs font-black text-slate-400 uppercase tracking-widest">Resumen</h4>
                  <button onClick={() => setCart([])} className="text-[10px] text-rose-500 font-bold uppercase hover:underline">Vaciar Carrito</button>
               </div>

               <div className="space-y-2 mb-6">
                 {cart.map(i => (
                   <div key={i.id} className="flex justify-between items-center py-2 border-b border-slate-50 last:border-none">
                      <div className="flex items-center gap-3">
                         <div className="flex items-center gap-2 bg-slate-50 rounded-xl p-1">
                            <button onClick={() => decreaseQuantity(i.id)} className="w-7 h-7 flex items-center justify-center bg-white rounded-lg shadow-sm text-slate-400 font-bold hover:text-sky-500 transition-colors">-</button>
                            <span className="text-xs font-black w-5 text-center text-slate-700">{i.quantity}</span>
                            <button onClick={() => addToCart(i)} className="w-7 h-7 flex items-center justify-center bg-sky-500 text-white rounded-lg shadow-sm font-bold hover:bg-sky-600 transition-colors">+</button>
                         </div>
                         <span className="text-xs font-bold text-slate-700 truncate max-w-[120px]">{i.name}</span>
                      </div>
                      <span className="text-sm font-black text-slate-800">${(( (customer?.specialPrice && i.id === '1') ? customer.specialPrice : i.price ) * i.quantity).toFixed(2)}</span>
                   </div>
                 ))}
               </div>

               <div className="bg-slate-50 p-4 rounded-[1.5rem] flex justify-between items-center mb-2">
                  <span className="text-[10px] font-bold text-slate-500 uppercase tracking-wide">Envases Vacíos Recibidos</span>
                  <div className="flex items-center gap-3">
                     <button onClick={() => setVacios(Math.max(0, vacios - 1))} className="w-8 h-8 bg-white rounded-full shadow-sm text-slate-400 font-bold hover:text-sky-500">-</button>
                     <span className="font-black text-slate-800 text-lg">{vacios}</span>
                     <button onClick={() => setVacios(vacios + 1)} className="w-8 h-8 bg-sky-500 rounded-full shadow-lg shadow-sky-200 text-white font-bold hover:bg-sky-600 active:scale-90 transition-transform">+</button>
                  </div>
               </div>
            </div>
          )}
        </div>
      ) : (
        <div className="flex-1 overflow-y-auto px-6 space-y-3 pb-10 no-scrollbar">
           {sales.map(s => (
             <RoundedCard key={s.id} className="p-4 flex justify-between items-center">
                <div className="flex items-center gap-4">
                   <div className="w-12 h-12 bg-slate-100 rounded-2xl flex items-center justify-center text-slate-400 text-lg">
                      <i className="fas fa-receipt"></i>
                   </div>
                   <div>
                      <h4 className="font-black text-slate-800 text-sm">{s.customerAlias}</h4>
                      <p className="text-[10px] text-slate-400 font-bold uppercase">{new Date(s.timestamp).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}</p>
                   </div>
                </div>
                <div className="text-right">
                   <span className="block font-black text-slate-800 text-lg">${s.total}</span>
                   <button onClick={() => setViewingTicket(s)} className="text-[10px] text-sky-500 font-bold uppercase bg-sky-50 px-3 py-1 rounded-lg mt-1 active:bg-sky-100">Ver Ticket</button>
                </div>
             </RoundedCard>
           ))}
        </div>
      )}

      {activeTab === 'sell' && (
        <div className="fixed bottom-0 left-0 right-0 p-6 bg-white/80 backdrop-blur-md border-t border-white/50 shadow-[0_-10px_30px_rgba(0,0,0,0.05)] z-50">
          <ActionButton onClick={handlePreCheckout} disabled={!customer || cart.length === 0}>
             <div className="flex justify-between w-full px-4 items-center">
                <span>{linkedOrderId ? 'Finalizar Entrega' : 'Cobrar'}</span>
                <span className="bg-white/20 px-3 py-1 rounded-xl text-sm font-black backdrop-blur-sm shadow-sm">${total.toFixed(2)}</span>
             </div>
          </ActionButton>
        </div>
      )}

      {showPaymentModal && <PaymentModal total={total} onConfirm={handleConfirmPayment} onCancel={() => setShowPaymentModal(false)} />}

      {viewingTicket && (
        <TicketModal 
          sale={viewingTicket} 
          config={ticketConfig} 
          onClose={() => setViewingTicket(null)} 
          onWhatsApp={() => {
             const phone = customers.find(c => c.id === viewingTicket.customerId)?.phone;
             if(phone) window.open(`https://wa.me/52${phone.replace(/\D/g,'')}?text=Hola, adjunto tu ticket ${viewingTicket.id}. Total: $${viewingTicket.total}`, '_blank');
             else alert("Sin teléfono registrado");
          }}
          onNewSale={resetPOS}
          onFinish={() => { setViewingTicket(null); setActiveTab('history'); }}
        />
      )}
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { Customer, GarrafonType } from '../types';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';
import { Filesystem, Directory, Encoding } from '@capacitor/filesystem';

const GARRAFON_TYPES: { type: GarrafonType, color: string, label: string }[] = [
  { type: 'Aqua', color: 'bg-indigo-500', label: 'Aqua+' },
  { type: 'Bonafont', color: 'bg-orange-400', label: 'Bonafont' },
  { type: 'Ciel', color: 'bg-sky-400', label: 'Ciel' },
  { type: 'E-Pura', color: 'bg-blue-600', label: 'Epura' },
  { type: 'Generico', color: 'bg-slate-400', label: 'Genérico' }
];

export const CustomersModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const { customers, saveCustomer, deleteCustomer, sales, importCustomers } = useERPData();
  const [search, setSearch] = useState('');
  const [editingCustomer, setEditingCustomer] = useState<Partial<Customer> | null>(null);
  const [viewingHistory, setViewingHistory] = useState<Customer | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const filteredCustomers = customers.filter(c => 
    c.name.toLowerCase().includes(search.toLowerCase()) || 
    c.alias.toLowerCase().includes(search.toLowerCase())
  );

  // --- LÓGICA DE NAVEGACIÓN INTELIGENTE ---
  const handleBackNavigation = () => {
    if (editingCustomer || viewingHistory) {
      setEditingCustomer(null);
      setViewingHistory(null);
    } else {
      onBack();
    }
  };

  const handleSave = () => {
    if (!editingCustomer?.name || !editingCustomer?.alias) {
      alert("Nombre y Alias son obligatorios.");
      return;
    }
    const customerToSave: Customer = {
      id: editingCustomer.id || Math.random().toString(36).substr(2, 9),
      name: editingCustomer.name,
      alias: editingCustomer.alias,
      phone: editingCustomer.phone || '',
      address: editingCustomer.address || '',
      specialPrice: editingCustomer.specialPrice || undefined,
      garrafonType: editingCustomer.garrafonType || 'Generico',
      jugsOnLoan: editingCustomer.jugsOnLoan || 0,
      balance: editingCustomer.balance || 0,
      lat: editingCustomer.lat,
      lng: editingCustomer.lng,
    };
    saveCustomer(customerToSave);
    setEditingCustomer(null);
  };

  const handleDelete = () => {
    if (!editingCustomer?.id) return;
    const confirmDelete = window.confirm(
      `¿Estás seguro de eliminar a "${editingCustomer.alias}"?\n\nEsta acción eliminará el registro del cliente permanentemente. Su historial de ventas se mantendrá como anónimo.`
    );
    if (confirmDelete) {
      deleteCustomer(editingCustomer.id);
      setEditingCustomer(null);
    }
  };

  const handleGetLocation = () => {
    if (!navigator.geolocation) {
      alert("Tu dispositivo no soporta geolocalización.");
      return;
    }

    const btn = document.getElementById('gps-btn');
    if(btn) {
       btn.innerHTML = '<i class="fas fa-circle-notch animate-spin"></i> Obteniendo...';
       btn.classList.add('opacity-50', 'pointer-events-none');
    }

    const onSuccess = (position: GeolocationPosition) => {
        // Al setear el estado, React re-renderiza y el botón cambiará a modo "Bloqueado" automáticamente
        setEditingCustomer(prev => prev ? ({
          ...prev,
          lat: position.coords.latitude,
          lng: position.coords.longitude
        }) : null);
    };

    const onError = (error: GeolocationPositionError) => {
        console.error("GPS Error:", error);
        if(btn) {
          btn.innerHTML = '<i class="fas fa-triangle-exclamation"></i> Reintentar';
          btn.classList.remove('opacity-50', 'pointer-events-none');
        }
        alert(`No se pudo obtener la ubicación precise (Error ${error.code}). Verifica que el GPS esté encendido.`);
    };

    // Intento 1: Alta Precisión
    navigator.geolocation.getCurrentPosition(
      onSuccess,
      () => {
        console.warn("High accuracy failed, trying low accuracy...");
        // Intento 2: Baja Precisión (Fallback)
        navigator.geolocation.getCurrentPosition(onSuccess, onError, { 
            enableHighAccuracy: false, 
            timeout: 10000, 
            maximumAge: 0 
        });
      },
      { enableHighAccuracy: true, timeout: 5000, maximumAge: 0 }
    );
  };

  const openGoogleMaps = (lat?: number, lng?: number) => {
    if (lat && lng) {
      window.open(`https://www.google.com/maps/search/?api=1&query=${lat},${lng}`, '_blank');
    } else {
      alert("Este cliente no tiene ubicación registrada.");
    }
  };

  // --- LOGICA DE EXPORTACIÓN E IMPORTACIÓN ---

  const handleExportCSV = async () => {
    const headers = ["ID", "Nombre", "Alias", "Telefono", "Direccion", "Saldo", "Precio Especial", "Tipo Garrafon", "Garrafones Prestados", "Lat", "Lng"];
    const rows = customers.map(c => [
      c.id,
      `"${c.name}"`,
      `"${c.alias}"`,
      c.phone || '',
      `"${c.address || ''}"`,
      c.balance,
      c.specialPrice || '',
      c.garrafonType || 'Generico',
      c.jugsOnLoan || 0,
      c.lat || '',
      c.lng || ''
    ]);
    const csvContent = [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
    const fileName = `Clientes_Aqua_${new Date().getTime()}.csv`;

    try {
        // Intento 1: Guardar en Sistema de Archivos (Android/iOS)
        await Filesystem.writeFile({
            path: fileName,
            data: csvContent,
            directory: Directory.Documents,
            encoding: Encoding.UTF8
        });
        alert('Archivo CSV guardado exitosamente en la carpeta "Documentos" de tu dispositivo.');
    } catch (e) {
        console.warn("Filesystem write failed, falling back to browser download", e);

        // Intento 2: Descarga Web Clásica (Fallback)
        const blob = new Blob([csvContent], { type: 'text/csv' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = fileName;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    }
  };

  // Helper para extraer dirección
  const extractAddress = (contact: any) => {
      if (contact.address && contact.address.length > 0) {
          const a = contact.address[0];
          // Intenta obtener la línea de dirección, o combina ciudad/estado
          if (a.addressLine) return Array.isArray(a.addressLine) ? a.addressLine.join(', ') : a.addressLine;
          return [a.street, a.city, a.region].filter(Boolean).join(', ');
      }
      return '';
  };

  // --- IMPORTAR CONTACTOS (BULK) ---
  const handleImportContacts = async () => {
    const nav = navigator as any;

    // Verificar soporte de la API de Selección de Contactos (Chrome Android / PWA)
    if ('contacts' in nav && 'select' in nav.contacts) {
      try {
        const props = ['name', 'tel', 'address'];
        const opts = { multiple: true };

        const contacts = await nav.contacts.select(props, opts);

        if (contacts.length > 0) {
           const newCustomers: Customer[] = contacts.map((c: any) => ({
             id: Math.random().toString(36).substr(2, 9),
             name: c.name[0] || 'Desconocido',
             alias: c.name[0] || 'Desconocido',
             phone: c.tel ? c.tel[0] : '',
             address: extractAddress(c),
             balance: 0,
             garrafonType: 'Generico'
           }));

           importCustomers(newCustomers);
           alert(`Se importaron ${newCustomers.length} contactos exitosamente.`);
        }
      } catch (ex) {
        console.log("Importación cancelada o fallida:", ex);
      }
    } else {
      alert("Tu dispositivo no soporta la selección directa de contactos. Por favor usa la opción de 'Importar CSV' o agrega manualmente.");
    }
  };

  // --- SELECCIONAR CONTACTO INDIVIDUAL (FORM) ---
  const handlePickContactForForm = async () => {
    const nav = navigator as any;
    if ('contacts' in nav && 'select' in nav.contacts) {
      try {
        const props = ['name', 'tel', 'address'];
        const opts = { multiple: false };

        const contacts = await nav.contacts.select(props, opts);

        if (contacts.length > 0) {
           const c = contacts[0];
           const name = c.name ? c.name[0] : '';
           const phone = c.tel ? c.tel[0] : '';
           const address = extractAddress(c);

           setEditingCustomer(prev => ({
               ...prev,
               name: name || prev?.name,
               alias: name || prev?.alias,
               phone: phone || prev?.phone,
               address: address || prev?.address
           }));
        }
      } catch (ex) {
        console.log("Selección cancelada", ex);
      }
    } else {
        alert("La selección de contactos no está disponible en este navegador/dispositivo.");
    }
  };

  const handleImportFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      if (!text) return;

      try {
        let importedCount = 0;
        const newCustomers: Customer[] = [];

        if (file.name.toLowerCase().endsWith('.csv')) {
          const lines = text.replace(/\r\n/g, '\n').replace(/\r/g, '\n').split('\n');
          if (lines.length > 0) {
            const headerLine = lines[0].toLowerCase();
            const headers = headerLine.split(',').map(h => h.trim().replace(/^"|"$/g, ''));

            const idxNombre = headers.findIndex(h => h.includes('nombre'));
            const idxAlias = headers.findIndex(h => h.includes('alias') || h.includes('comercial'));
            const idxTelefono = headers.findIndex(h => h.includes('telefono') || h.includes('celular') || h.includes('whatsapp'));
            const idxDireccion = headers.findIndex(h => h.includes('direccion') || h.includes('domicilio'));
            const idxSaldo = headers.findIndex(h => h.includes('saldo'));
            const idxPrecio = headers.findIndex(h => h.includes('precio'));

            lines.slice(1).forEach(line => {
              if (!line.trim()) return;
              const cols = line.split(',').map(c => c.replace(/^"|"$/g, '').trim());
              const finalName = (idxNombre !== -1 ? cols[idxNombre] : '') || (idxAlias !== -1 ? cols[idxAlias] : '') || 'Importado';
              const finalAlias = (idxAlias !== -1 ? cols[idxAlias] : '') || finalName;

              if (finalAlias) {
                newCustomers.push({
                  id: Math.random().toString(36).substr(2, 9),
                  name: finalName,
                  alias: finalAlias,
                  phone: idxTelefono !== -1 ? cols[idxTelefono] : '',
                  address: idxDireccion !== -1 ? cols[idxDireccion] : '',
                  balance: idxSaldo !== -1 ? (parseFloat(cols[idxSaldo]) || 0) : 0,
                  specialPrice: idxPrecio !== -1 ? (parseFloat(cols[idxPrecio]) || undefined) : undefined,
                  garrafonType: 'Generico',
                });
                importedCount++;
              }
            });
          }
        }

        if (importedCount > 0) {
          importCustomers(newCustomers);
          alert(`¡Éxito! Se importaron ${importedCount} clientes.`);
        } else {
          alert("No se encontraron datos válidos en el CSV.");
        }
      } catch (err) {
        alert("Error al procesar el archivo.");
      }
      if (fileInputRef.current) fileInputRef.current.value = '';
    };
    reader.readAsText(file);
  };

  // --- UI RENDER ---

  if (viewingHistory) {
    const customerSales = sales.filter(s => s.customerId === viewingHistory.id);
    const hasDebt = viewingHistory.balance > 0;
    const hasCredit = viewingHistory.balance < 0;
    const garrafon = GARRAFON_TYPES.find(g => g.type === (viewingHistory.garrafonType || 'Generico'));

    return (
      <div className="h-full bg-sky-50 overflow-y-auto no-scrollbar pb-24">
        <ModuleHeader title={`Perfil: ${viewingHistory.alias}`} onBack={handleBackNavigation} />
        <div className="px-6 space-y-4">
          <RoundedCard className={`${hasDebt ? 'bg-red-500' : hasCredit ? 'bg-emerald-500' : 'bg-sky-600'} text-white shadow-lg border-none transition-colors duration-500`}>
             <div className="flex justify-between items-center">
                <div>
                   <span className="text-[10px] font-black uppercase opacity-70">
                     {hasDebt ? 'Estado: Adeudo' : hasCredit ? 'Estado: Saldo a Favor' : 'Estado: Al Corriente'}
                   </span>
                   <p className="text-3xl font-black">
                     ${Math.abs(viewingHistory.balance).toLocaleString()}
                   </p>
                </div>
                <div className="bg-white/20 p-4 rounded-2xl">
                   <i className={`fas ${hasDebt ? 'fa-hand-holding-dollar' : 'fa-piggy-bank'} text-2xl`}></i>
                </div>
             </div>
          </RoundedCard>

          {viewingHistory.address && (
            <div className="bg-white p-5 rounded-3xl shadow-sm border border-sky-50 flex items-start gap-3">
              <i className="fas fa-map-location-dot text-sky-300 mt-1"></i>
              <div>
                 <span className="text-[9px] font-black text-sky-400 uppercase block mb-1">Dirección Registrada</span>
                 <p className="text-sm font-bold text-sky-900 leading-tight">{viewingHistory.address}</p>
              </div>
            </div>
          )}

          <div className="grid grid-cols-2 gap-3">
             <div className="bg-white p-4 rounded-3xl shadow-sm border border-sky-50">
                <span className="text-[9px] font-black text-sky-400 uppercase block mb-1">WhatsApp</span>
                <p className="text-xs font-bold text-sky-900">{viewingHistory.phone || 'No registrado'}</p>
             </div>
             <div className="bg-white p-4 rounded-3xl shadow-sm border border-sky-50">
                <span className="text-[9px] font-black text-sky-400 uppercase block mb-1">Precio Esp.</span>
                <p className="text-xs font-bold text-sky-900">{viewingHistory.specialPrice ? `$${viewingHistory.specialPrice}` : 'Precio Base'}</p>
             </div>
          </div>

          {/* Preferencia de Garrafón Visualización */}
          <div className="bg-white p-4 rounded-3xl shadow-sm border border-sky-50 flex items-center justify-between">
              <div>
                  <span className="text-[9px] font-black text-sky-400 uppercase block mb-1">Envases en Poder</span>
                  <p className="text-sm font-bold text-sky-900 flex items-center gap-2">
                    <span className="text-2xl">{viewingHistory.jugsOnLoan || 0}</span>
                    <span className={`text-[10px] text-white px-2 py-0.5 rounded uppercase ${garrafon?.color || 'bg-slate-400'}`}>{garrafon?.label || 'Genérico'}</span>
                  </p>
              </div>
              <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-white ${garrafon?.color || 'bg-slate-400'}`}>
                  <i className="fas fa-bottle-water"></i>
              </div>
          </div>

          <h4 className="text-[10px] font-black uppercase text-sky-400 tracking-widest px-2 mt-4">Transacciones Recientes</h4>
          {customerSales.length === 0 ? (
            <div className="text-center py-20 text-sky-300 italic animate-fadeIn">Sin compras registradas aún.</div>
          ) : (
            customerSales.map(s => (
              <RoundedCard key={s.id} className="py-5 border-none shadow-sm animate-fadeIn">
                <div className="flex justify-between items-start mb-3">
                  <div>
                    <span className="text-sky-900 font-black">{s.id}</span>
                    <p className="text-[10px] text-sky-400 font-bold uppercase">{new Date(s.timestamp).toLocaleDateString()}</p>
                  </div>
                  <span className="font-black text-sky-600 text-xl">${s.total}</span>
                </div>
                <div className="flex flex-wrap gap-2">
                  {s.items.map(i => <span key={i.id} className="bg-sky-50 text-sky-600 text-[8px] px-3 py-1 rounded-full font-black uppercase">{i.quantity}x {i.name}</span>)}
                </div>
              </RoundedCard>
            ))
          )}
        </div>
      </div>
    );
  }

  if (editingCustomer) {
    return (
      <div className="h-full bg-sky-50 overflow-y-auto no-scrollbar pb-32">
        <ModuleHeader title={editingCustomer.id ? "Editar Perfil" : "Nuevo Cliente"} onBack={handleBackNavigation} />
        <div className="px-6 space-y-5">
          <div className="space-y-4">

            {/* --- BOTÓN CARGA RÁPIDA DE CONTACTOS --- */}
            <div className="flex justify-end">
                <button onClick={handlePickContactForForm} className="text-[9px] font-bold text-sky-500 flex items-center gap-1 bg-white px-4 py-2 rounded-full shadow-sm active:scale-95 transition-transform border border-sky-100">
                   <i className="fas fa-address-book"></i> Cargar de Agenda
                </button>
            </div>

            <div>
               <label className="text-[10px] font-black text-sky-400 uppercase ml-3 mb-1 block">Nombre Comercial / Alias</label>
               <input className="w-full bg-white p-5 rounded-[2rem] outline-none shadow-sm font-bold text-sky-900 focus:ring-2 ring-sky-300 transition-all" placeholder="Ej: Doña Mary" value={editingCustomer.alias || ''} onChange={e => setEditingCustomer({...editingCustomer, alias: e.target.value})}/>
            </div>
            <div>
               <label className="text-[10px] font-black text-sky-400 uppercase ml-3 mb-1 block">Nombre Legal</label>
               <input className="w-full bg-white p-5 rounded-[2rem] outline-none shadow-sm text-sky-900 focus:ring-2 ring-sky-300 transition-all" placeholder="Ej: María de los Angeles" value={editingCustomer.name || ''} onChange={e => setEditingCustomer({...editingCustomer, name: e.target.value})}/>
            </div>
            <div>
               <label className="text-[10px] font-black text-sky-400 uppercase ml-3 mb-1 block">WhatsApp</label>
               <input className="w-full bg-white p-5 rounded-[2rem] outline-none shadow-sm text-sky-900 focus:ring-2 ring-sky-300 transition-all" placeholder="33..." value={editingCustomer.phone || ''} onChange={e => setEditingCustomer({...editingCustomer, phone: e.target.value})}/>
            </div>
            <div>
               <label className="text-[10px] font-black text-sky-400 uppercase ml-3 mb-1 block">Dirección / Domicilio</label>
               <input className="w-full bg-white p-5 rounded-[2rem] outline-none shadow-sm text-sky-900 focus:ring-2 ring-sky-300 transition-all" placeholder="Calle, Número, Colonia..." value={editingCustomer.address || ''} onChange={e => setEditingCustomer({...editingCustomer, address: e.target.value})}/>
            </div>

            {/* Sección de Geolocalización Actualizada */}
            <div>
               <label className="text-[10px] font-black text-sky-400 uppercase ml-3 mb-1 block">Ubicación de Entrega</label>
               <div className="flex gap-2">
                 {editingCustomer.lat && editingCustomer.lng ? (
                    // ESTADO BLOQUEADO: Se muestra cuando ya hay coordenadas
                    <>
                       <div className="flex-1 bg-emerald-50 text-emerald-600 p-4 rounded-[2rem] font-bold text-[10px] uppercase flex items-center justify-center gap-2 border border-emerald-100 shadow-sm">
                          <i className="fas fa-lock"></i> GPS Asignado
                       </div>

                       {/* Botón para Desbloquear/Borrar */}
                       <button
                         onClick={() => {
                            if(confirm("¿Desbloquear ubicación para actualizar?")) {
                                setEditingCustomer(prev => ({...prev, lat: undefined, lng: undefined}));
                            }
                         }}
                         className="w-14 bg-white border border-slate-100 text-slate-400 rounded-[1.5rem] flex items-center justify-center text-lg active:scale-90 transition-transform shadow-sm"
                         title="Cambiar Ubicación"
                       >
                         <i className="fas fa-pen text-xs"></i>
                       </button>
                    </>
                 ) : (
                    // ESTADO CAPTURA: Se muestra cuando no hay coordenadas
                    <button 
                      id="gps-btn"
                      onClick={handleGetLocation} 
                      className="flex-1 bg-sky-50 text-sky-600 p-4 rounded-[2rem] font-bold text-[10px] uppercase flex items-center justify-center gap-2 border border-sky-100 shadow-sm active:scale-95 transition-all"
                    >
                      <i className="fas fa-location-crosshairs"></i> Capturar GPS
                    </button>
                 )}

                 {/* Botón Mapa (Siempre visible si existen coordenadas) */}
                 {editingCustomer?.lat && (
                   <button 
                     onClick={() => openGoogleMaps(editingCustomer.lat, editingCustomer.lng)} 
                     className="w-14 bg-white border border-sky-100 text-sky-500 rounded-[1.5rem] flex items-center justify-center text-lg active:scale-90 transition-transform shadow-sm"
                   >
                     <i className="fas fa-map-location-dot text-red-500"></i>
                   </button>
                 )}
               </div>
            </div>

            {/* Selector de Marca de Garrafón */}
            <div>
               <label className="text-[10px] font-black text-sky-400 uppercase ml-3 mb-1 block">Marca de Garrafón Preferida</label>
               <div className="bg-white p-3 rounded-[2rem] shadow-sm border border-slate-50">
                 <div className="flex flex-wrap gap-2">
                    {GARRAFON_TYPES.map(g => {
                       const isSelected = editingCustomer.garrafonType === g.type;
                       return (
                         <button
                           key={g.type}
                           onClick={() => setEditingCustomer({...editingCustomer, garrafonType: g.type})}
                           className={`flex-1 min-w-[30%] py-3 px-2 rounded-2xl text-[9px] font-black uppercase transition-all flex flex-col items-center gap-1 border ${
                             isSelected 
                               ? `${g.color} text-white border-transparent shadow-md transform scale-105` 
                               : 'bg-slate-50 text-slate-400 border-transparent hover:bg-slate-100'
                           }`}
                         >
                           <i className={`fas ${isSelected ? 'fa-check-circle' : 'fa-circle'} opacity-50`}></i>
                           {g.label}
                         </button>
                       );
                    })}
                 </div>
               </div>
            </div>

            <div className="bg-white p-5 rounded-[2.5rem] shadow-sm border border-slate-50 space-y-4">
               <div>
                 <label className="text-[10px] font-black text-sky-400 uppercase ml-3 mb-1 block">Garrafones en Préstamo (Inicial/Ajuste)</label>
                 <div className="flex items-center gap-4 bg-sky-50 p-2 rounded-2xl">
                    <button 
                      onClick={() => setEditingCustomer(prev => ({...prev, jugsOnLoan: Math.max(0, (prev?.jugsOnLoan || 0) - 1)}))}
                      className="w-10 h-10 bg-white rounded-xl shadow-sm text-sky-600 flex items-center justify-center font-black active:scale-90 transition-transform"
                    >
                      -
                    </button>
                    <input 
                      type="number" 
                      className="flex-1 bg-transparent text-center font-black text-2xl text-sky-900 outline-none"
                      value={editingCustomer.jugsOnLoan || 0}
                      onChange={e => setEditingCustomer({...editingCustomer, jugsOnLoan: parseInt(e.target.value) || 0})}
                    />
                    <button 
                      onClick={() => setEditingCustomer(prev => ({...prev, jugsOnLoan: (prev?.jugsOnLoan || 0) + 1}))}
                      className="w-10 h-10 bg-sky-600 rounded-xl shadow-lg text-white flex items-center justify-center font-black active:scale-90 transition-transform"
                    >
                      +
                    </button>
                 </div>
               </div>

               <div className="grid grid-cols-2 gap-4">
                  <div>
                     <label className="text-[10px] font-black text-sky-400 uppercase ml-3 mb-1 block">Precio Especial</label>
                     <input type="number" className="w-full bg-sky-50 p-4 rounded-2xl outline-none font-black text-sky-600 text-lg focus:ring-2 ring-sky-300" placeholder="0.00" value={editingCustomer.specialPrice || ''} onChange={e => setEditingCustomer({...editingCustomer, specialPrice: Number(e.target.value)})}/>
                  </div>
                  <div>
                     <label className="text-[10px] font-black text-sky-400 uppercase ml-3 mb-1 block">Saldo (Deuda)</label>
                     <input type="number" className="w-full bg-sky-50 p-4 rounded-2xl outline-none font-black text-sky-900 text-lg focus:ring-2 ring-sky-300" placeholder="0.00" value={editingCustomer.balance || ''} onChange={e => setEditingCustomer({...editingCustomer, balance: Number(e.target.value)})}/>
                  </div>
               </div>
            </div>
          </div>

          <div className="pt-4 space-y-3">
             <ActionButton onClick={handleSave}>Guardar Cliente</ActionButton>

             {editingCustomer.id && (
               <button 
                 onClick={handleDelete}
                 className="w-full py-4 text-rose-500 font-black uppercase text-[10px] tracking-widest bg-rose-50 rounded-[2rem] active:scale-95 transition-all border border-rose-100 shadow-sm hover:bg-rose-100"
               >
                 <i className="fas fa-trash-can mr-2"></i> Eliminar Cliente
               </button>
             )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="h-full bg-sky-50 overflow-y-auto no-scrollbar pb-24">
      <ModuleHeader title="Directorio" onBack={handleBackNavigation} />
      <div className="px-6 space-y-4">

        {/* PANEL DE HERRAMIENTAS DE DATOS */}
        <div className="bg-indigo-600 rounded-[2.5rem] p-6 text-white shadow-lg shadow-indigo-200">
          <div className="flex justify-between items-center mb-4">
            <h4 className="text-sm font-black uppercase tracking-tight">Base de Datos</h4>
            <i className="fas fa-database opacity-50"></i>
          </div>
          <div className="grid grid-cols-3 gap-2">
            <button onClick={handleImportContacts} className="bg-white/10 hover:bg-white/20 p-3 rounded-2xl flex flex-col items-center gap-2 transition-colors">
               <i className="fas fa-mobile-screen-button text-xl"></i>
               <span className="text-[8px] font-bold uppercase text-center">Desde Agenda</span>
            </button>
            <button onClick={handleExportCSV} className="bg-white/10 hover:bg-white/20 p-3 rounded-2xl flex flex-col items-center gap-2 transition-colors">
               <i className="fas fa-file-export text-xl"></i>
               <span className="text-[8px] font-bold uppercase text-center">Exportar CSV</span>
            </button>
            <label className="bg-white/10 hover:bg-white/20 p-3 rounded-2xl flex flex-col items-center gap-2 transition-colors cursor-pointer relative">
               <i className="fas fa-file-import text-xl"></i>
               <span className="text-[8px] font-bold uppercase text-center">Importar CSV</span>
               <input 
                 type="file" 
                 ref={fileInputRef}
                 accept=".csv" 
                 className="absolute inset-0 opacity-0 cursor-pointer"
                 onChange={handleImportFile}
               />
            </label>
          </div>
        </div>

        <div className="relative">
          <input type="text" placeholder="Buscar por alias o teléfono..." className="w-full bg-white p-5 rounded-[2rem] outline-none shadow-sm focus:ring-2 ring-sky-300 font-medium" value={search} onChange={e => setSearch(e.target.value)}/>
          <i className="fas fa-search absolute right-6 top-1/2 -translate-y-1/2 text-sky-200"></i>
        </div>

        <div className="space-y-3">
          {filteredCustomers.map(c => (
            <RoundedCard key={c.id} className="py-5 border-none shadow-sm group hover:shadow-md transition-all active:scale-[0.98]">
              <div className="flex justify-between items-center">
                <div className="flex gap-4 items-center flex-1" onClick={() => setViewingHistory(c)}>
                  <div className={`w-14 h-14 rounded-3xl flex items-center justify-center text-white font-black text-xl shadow-lg transition-transform group-active:scale-90 ${GARRAFON_TYPES.find(g => g.type === c.garrafonType)?.color || 'bg-slate-400'}`}>
                    {c.alias ? c.alias.charAt(0).toUpperCase() : '?'}
                  </div>
                  <div>
                    <h4 className="font-black text-sky-900 leading-tight">{c.alias}</h4>
                    <div className="flex gap-2 mt-1 flex-wrap">
                      {c.address && (
                         <span className="bg-violet-100 text-violet-600 text-[8px] font-black px-2 py-0.5 rounded-full uppercase flex items-center gap-1">
                           <i className="fas fa-map-pin text-[8px]"></i> {c.address.slice(0, 10)}...
                         </span>
                      )}
                      {c.balance > 0 && (
                        <span className="bg-red-100 text-red-600 text-[8px] font-black px-2 py-0.5 rounded-full uppercase border border-red-200">
                          Adeudo: ${c.balance}
                        </span>
                      )}
                    </div>
                  </div>
                </div>
                <div className="flex gap-1">
                  <button onClick={() => setViewingHistory(c)} className="w-10 h-10 bg-sky-50 text-sky-500 rounded-xl flex items-center justify-center text-sm active:bg-sky-200 transition-colors"><i className="fas fa-eye"></i></button>
                  <button onClick={() => setEditingCustomer(c)} className="w-10 h-10 bg-sky-50 text-sky-500 rounded-xl flex items-center justify-center text-sm active:bg-sky-200 transition-colors"><i className="fas fa-pen"></i></button>
                  <a href={`https://wa.me/52${c.phone}`} className="w-10 h-10 bg-emerald-50 text-emerald-500 rounded-xl flex items-center justify-center text-sm active:bg-emerald-200 transition-colors"><i className="fab fa-whatsapp"></i></a>
                </div>
              </div>
            </RoundedCard>
          ))}
        </div>
        <button onClick={() => setEditingCustomer({})} className="w-full py-6 border-2 border-dashed border-sky-200 rounded-[2.5rem] text-sky-400 font-black text-sm uppercase hover:bg-white hover:text-sky-600 transition-all">+ Añadir Nuevo Cliente</button>
      </div>
    </div>
  );
};

