  businessName: 'AQUA+ FUNDADORES',
  rfc: 'AQUA900101-XXX',
  address: 'Calle del Agua #123, Col. Manantiales',
  phone: '33-1234-5678',
  footerMessage: '¡Gracias por tu preferencia! Frescura que hidrata tu vida.',
  website: 'www.aquafun.mx',
  socialMedia: '@aquafun_pro',
  extraNote: 'No hay cambios después de 24 horas.',
  // Use a 1x1 transparent PNG or valid PNG base64 to avoid crashes in PDF generator which doesn't support SVG
  logoUrl: 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=', 
  colorHex: '#0284c7', // Sky-600 default
  email: 'contacto@aquafun.mx',
  paperWidth: '80mm',
  showLogo: true,
  showQr: true,
  showFooter: true
};

const INITIAL_CLOUD_CONFIG: CloudConfig = {
  url: 'https://aquamasfundadores-default-rtdb.firebaseio.com/',
  apiKey: 't8rzxkeWbMIKGufdW7RV1j1bKS0TKf2gPkgmZ36A',
  autoSync: true
};

// --- DEVICE ID MANAGEMENT ---
const getDeviceId = () => {
  let id = localStorage.getItem('aqua_device_id');
  if (!id) {
    // Generar un ID corto único (ej: 4A2B)
    id = Math.random().toString(36).substring(2, 6).toUpperCase();
    localStorage.setItem('aqua_device_id', id);
  }
  return id;
};

// Hook Logic Factory
const useERPFactory = () => {
  const [deviceId] = useState(getDeviceId());

  const [products, setProducts] = useState<Product[]>(() => {
    const saved = localStorage.getItem('aqua_products');
    return saved ? JSON.parse(saved) : INITIAL_PRODUCTS;
  });

  const [customers, setCustomers] = useState<Customer[]>(() => {
    const saved = localStorage.getItem('aqua_customers');
    return saved ? JSON.parse(saved).map((c: any) => ({ ...c, balance: c.balance || 0 })) : INITIAL_CUSTOMERS;
  });

  const [ticketConfig, setTicketConfig] = useState<TicketConfig>(() => {
    const saved = localStorage.getItem('aqua_ticket_config');
    // Ensure colorHex exists for older saved configs
    const parsed = saved ? JSON.parse(saved) : INITIAL_TICKET_CONFIG;
    return { ...INITIAL_TICKET_CONFIG, ...parsed };
  });

  const [productionConfig, setProductionConfig] = useState<ProductionConfig>(() => {
    const saved = localStorage.getItem('aqua_production_config');
    return saved ? JSON.parse(saved) : { 
      backwashSequence: BACKWASH_SEQUENCE, 
      regenerationSequence: REGENERATION_SEQUENCE 
    };
  });

  const [cloudConfig, setCloudConfig] = useState<CloudConfig>(() => {
    const saved = localStorage.getItem('aqua_cloud_config');
    if (saved) {
      const parsed = JSON.parse(saved);
      if (!parsed.url || parsed.url === '') {
        return INITIAL_CLOUD_CONFIG;
      }
      return parsed;
    }
    return INITIAL_CLOUD_CONFIG;
  });

  const [sales, setSales] = useState<Sale[]>(() => {
    const saved = localStorage.getItem('aqua_sales');
    return saved ? JSON.parse(saved) : [];
  });

  const [orders, setOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('aqua_orders');
    return saved ? JSON.parse(saved) : [];
  });

  const [employees, setEmployees] = useState<Employee[]>(() => {
    const saved = localStorage.getItem('aqua_employees');
    let initial = saved ? JSON.parse(saved) : [
      { id: 'admin', name: 'Gerente General', roles: ['Administrador'], phone: '3312345678', pin: '1234', permissions: [...DEFAULT_PERMISSIONS] }
    ];

    // MIGRATION: Convert single role string to roles array if needed
    initial = initial.map((e: any) => {
      if (e.role && !e.roles) {
        return { ...e, roles: [e.role], role: undefined };
      }
      return e;
    });

    return initial;
  });

  // Ensure Admins always have full permissions on load
  useEffect(() => {
    setEmployees(prev => prev.map(e => 
      e.roles.includes('Administrador')
        ? { ...e, permissions: [...DEFAULT_PERMISSIONS] } 
        : e
    ));
  }, []);

  const [vehicles, setVehicles] = useState<Vehicle[]>(() => {
    const saved = localStorage.getItem('aqua_vehicles');
    // Migration: ensure inventory and fuelHistory arrays exist
    const parsed = saved ? JSON.parse(saved) : [{ id: 'v1', plate: 'ABC-123', description: 'Nissan NP300', loadCapacity: 60, currentLoad: 0, inventory: [], fuelHistory: [] }];
    return parsed.map((v: any) => ({
        ...v,
        inventory: v.inventory || [],
        fuelHistory: v.fuelHistory || []
    }));
  });

  const [qualityRecords, setQualityRecords] = useState<QualityRecord[]>(() => {
    const saved = localStorage.getItem('aqua_quality');
    return saved ? JSON.parse(saved) : [];
  });

  const [tasks, setTasks] = useState<Task[]>(() => {
    const saved = localStorage.getItem('aqua_tasks');
    return saved ? JSON.parse(saved) : [];
  });

  const [attendance, setAttendance] = useState<Attendance[]>(() => {
    const saved = localStorage.getItem('aqua_attendance');
    return saved ? JSON.parse(saved) : [];
  });

  const [savedReports, setSavedReports] = useState<SavedReport[]>(() => {
    const saved = localStorage.getItem('aqua_saved_reports');
    return saved ? JSON.parse(saved) : [];
  });

  const [messages, setMessages] = useState<Message[]>(() => {
    const saved = localStorage.getItem('aqua_messages');
    return saved ? JSON.parse(saved) : [];
  });

  // --- NOTIFICATIONS STATE ---
  const [notifications, setNotifications] = useState<AppNotification[]>(() => {
    const saved = localStorage.getItem('aqua_notifications');
    return saved ? JSON.parse(saved) : [];
  });

  // Play Sound Helper
  const playNotificationSound = (type: 'alarm' | 'alert') => {
    try {
      const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
      if (!AudioContext) return;

      const ctx = new AudioContext();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();

      osc.connect(gain);
      gain.connect(ctx.destination);

      if (type === 'alarm') {
        osc.type = 'square';
        osc.frequency.setValueAtTime(440, ctx.currentTime);
        osc.frequency.exponentialRampToValueAtTime(880, ctx.currentTime + 0.1);
        gain.gain.setValueAtTime(0.1, ctx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.5);
        osc.start();
        osc.stop(ctx.currentTime + 0.5);
      } else {
        // Soft alert
        osc.type = 'sine';
        osc.frequency.setValueAtTime(800, ctx.currentTime);
        gain.gain.setValueAtTime(0.05, ctx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.3);
        osc.start();
        osc.stop(ctx.currentTime + 0.3);
      }
    } catch (e) {
      console.error("Audio error", e);
    }
  };

  const addNotification = useCallback((note: Omit<AppNotification, 'id' | 'timestamp' | 'read'>) => {
    const newNote: AppNotification = {
      id: `NOT-${Date.now()}-${Math.random().toString(36).substr(2,4)}`,
      timestamp: Date.now(),
      read: false,
      ...note
    };

    // Check for duplicates to avoid spamming (e.g. low stock) within last hour
    setNotifications(prev => {
      const duplicate = prev.find(n => 
        n.title === newNote.title && 
        n.type === newNote.type && 
        (Date.now() - n.timestamp) < 3600000 && // 1 hour debounce for similar alerts
        !n.read
      );

      if (duplicate && newNote.type !== 'alarm') return prev; // Skip duplicate system alerts

      playNotificationSound(newNote.type === 'alarm' ? 'alarm' : 'alert');
      return [newNote, ...prev];
    });
  }, []);

  const markNotificationRead = (id: string) => {
    setNotifications(prev => prev.map(n => n.id === id ? { ...n, read: true } : n));
  };

  const deleteNotification = (id: string) => {
    setNotifications(prev => prev.filter(n => n.id !== id));
  };

  const clearAllNotifications = () => {
    setNotifications([]);
  };

  // --- AUTOMATED SYSTEM CHECKS ---
  useEffect(() => {
    const interval = setInterval(() => {
      // 1. Check Low Stock
      const lowStockItems = products.filter(p => p.stock < 20 && p.category !== 'Insumos');
      if (lowStockItems.length > 0) {
        addNotification({
          title: 'Stock Crítico',
          message: `${lowStockItems.length} productos están por agotarse.`,
          type: 'warning',
          actionLink: 'inventory'
        });
      }

      // 2. Check Pending Orders
      const pendingOrders = orders.filter(o => o.status === 'pendiente' && (Date.now() - o.timestamp) > 7200000); // 2 hours
      if (pendingOrders.length > 0) {
        addNotification({
          title: 'Pedidos Retrasados',
          message: `Hay ${pendingOrders.length} pedidos pendientes con más de 2 horas.`,
          type: 'urgent',
          actionLink: 'orders'
        });
      }

      // 3. Check Scheduled Alarms
      const now = Date.now();
      setNotifications(prev => prev.map(n => {
        if (n.scheduledFor && n.scheduledFor <= now && !n.read && n.type === 'alarm') {
           // It's time! Trigger sound if it wasn't already triggered
           // In a real app we'd need a separate "triggered" state. 
           // For now, we rely on the user seeing it.
           return n;
        }
        return n;
      }));

    }, 60000 * 5); // Run every 5 minutes

    return () => clearInterval(interval);
  }, [products, orders, addNotification]);

  useEffect(() => {
    localStorage.setItem('aqua_products', JSON.stringify(products));
    localStorage.setItem('aqua_customers', JSON.stringify(customers));
    localStorage.setItem('aqua_sales', JSON.stringify(sales));
    localStorage.setItem('aqua_orders', JSON.stringify(orders));
    localStorage.setItem('aqua_employees', JSON.stringify(employees));
    localStorage.setItem('aqua_vehicles', JSON.stringify(vehicles));
    localStorage.setItem('aqua_ticket_config', JSON.stringify(ticketConfig));
    localStorage.setItem('aqua_production_config', JSON.stringify(productionConfig));
    localStorage.setItem('aqua_quality', JSON.stringify(qualityRecords));
    localStorage.setItem('aqua_tasks', JSON.stringify(tasks));
    localStorage.setItem('aqua_attendance', JSON.stringify(attendance));
    localStorage.setItem('aqua_cloud_config', JSON.stringify(cloudConfig));
    localStorage.setItem('aqua_saved_reports', JSON.stringify(savedReports));
    localStorage.setItem('aqua_messages', JSON.stringify(messages));
    localStorage.setItem('aqua_notifications', JSON.stringify(notifications));
  }, [products, customers, sales, orders, employees, vehicles, ticketConfig, productionConfig, qualityRecords, tasks, attendance, cloudConfig, savedReports, messages, notifications]);

  // Helper para fecha local ISO YYYY-MM-DD
  const getLocalDateISO = () => {
    const d = new Date();
    const offset = d.getTimezoneOffset() * 60000;
    return new Date(d.getTime() - offset).toISOString().split('T')[0];
  };

  const addSale = (
    customerId: string, 
    items: CartItem[], 
    total: number, 
    paidAmount: number, 
    splits: PaymentSplit[], 
    returnedVacios: number, 
    manualTimestamp?: number,
    vehicleId?: string // New optional parameter
  ) => {
    const debtAmount = Math.max(0, total - paidAmount);

    // Calculate Asset Movement (Jugs)
    const jugsSold = items
      .filter(i => i.category === 'Agua' || i.name.toLowerCase().includes('garraf'))
      .reduce((acc, item) => acc + item.quantity, 0);

    const netJugChange = jugsSold - returnedVacios;

    // ID GENERATION: Includes Device ID to prevent collisions during sync
    const timestamp = manualTimestamp || Date.now();
    const uniqueId = `TKT-${timestamp.toString().slice(-6)}-${deviceId}`;

    const newSale: Sale = {
      id: uniqueId,
      timestamp: timestamp,
      customerId,
      customerAlias: customers.find(c => c.id === customerId)?.alias || 'Anonimo',
      items,
      total,
      paidAmount,
      change: Math.max(0, paidAmount - total),
      paymentSplits: splits,
      emptyGarrafonsReturned: returnedVacios,
      synced: false,
      deviceId: deviceId // Metadata for traceability
    };

    setSales(prev => [newSale, ...prev]);

    // Update Customer Balance and Jug Inventory with LAST UPDATED
    setCustomers(prev => prev.map(c => {
      if (c.id === customerId) {
        return { 
          ...c, 
          balance: (c.balance || 0) + debtAmount,
          jugsOnLoan: Math.max(0, (c.jugsOnLoan || 0) + netJugChange),
          lastUpdated: Date.now() // Track change
        };
      }
      return c;
    }));

    // Logic to deduct inventory
    if (vehicleId && vehicleId !== 'plant') {
      // Deduct from specific vehicle
      setVehicles(prev => prev.map(v => {
        if (v.id !== vehicleId) return v;

        let currentInventory = [...(v.inventory || [])];

        items.forEach(soldItem => {
          const idx = currentInventory.findIndex(inv => inv.id === soldItem.id);
          if (idx !== -1) {
            // Reduce quantity
            const newQty = Math.max(0, currentInventory[idx].quantity - soldItem.quantity);
            if (newQty === 0) {
               currentInventory.splice(idx, 1);
            } else {
               currentInventory[idx] = { ...currentInventory[idx], quantity: newQty };
            }
          }
        });

        const newLoad = currentInventory.reduce((acc, i) => acc + (i.quantity || 0), 0);
        return { ...v, inventory: currentInventory, currentLoad: newLoad, lastUpdated: Date.now() };
      }));
    } else {
      // Deduct from Plant (Default)
      setProducts(prev => prev.map(p => {
        const cartItem = items.find(item => item.id === p.id);
        return cartItem ? { ...p, stock: p.stock - cartItem.quantity, lastUpdated: Date.now() } : p;
      }));
    }

    return newSale;
  };

  const resetSales = () => {
    setSales([]);
    alert("Todas las ventas han sido eliminadas. El historial está limpio.");
  };

  // --- MEGA SYNC FUNCTION ---
  const syncData = useCallback((externalData: any) => {
    if (!externalData) return false;
    let changesMade = false;

    // Helper to just set the data (assuming SyncModule did the heavy lifting/merging)
    const setIfPresent = <T,>(key: string, setter: React.Dispatch<React.SetStateAction<T>>) => {
        if (externalData[key]) {
            setter(externalData[key]);
            changesMade = true;
        }
    };

    setIfPresent('sales', setSales);
    setIfPresent('customers', setCustomers);
    setIfPresent('products', setProducts);
    setIfPresent('orders', setOrders);
    setIfPresent('vehicles', setVehicles);
    setIfPresent('employees', setEmployees);
    setIfPresent('qualityRecords', setQualityRecords);
    setIfPresent('tasks', setTasks);
    setIfPresent('attendance', setAttendance);
    setIfPresent('savedReports', setSavedReports);
    setIfPresent('messages', setMessages);
    setIfPresent('productionConfig', setProductionConfig);

    // Ticket Config (Object merge)
    if (externalData.ticketConfig) {
      if (JSON.stringify(ticketConfig) !== JSON.stringify(externalData.ticketConfig)) {
        setTicketConfig(externalData.ticketConfig);
        changesMade = true;
      }
    }

    return changesMade;
  }, [ticketConfig]);

  const importCustomers = useCallback((newCustomers: Customer[]) => {
    setCustomers(prev => {
      const existingIds = new Set(prev.map(c => c.id));
      const filteredNew = newCustomers.filter(c => !existingIds.has(c.id));
      // Mark imported as updated now
      const withTimestamp = filteredNew.map(c => ({...c, lastUpdated: Date.now()}));
      return [...prev, ...withTimestamp];
    });
  }, []);

  const loadVehicle = (vehicleId: string, product: Product, delta: number) => {
    if (!product || !product.id) return;

    if (delta > 0) {
      const currentProduct = products.find(p => p.id === product.id);
      if (!currentProduct) return;
      if (currentProduct.stock < delta) {
          alert("Stock insuficiente en planta.");
          return;
      }
    }

    setVehicles(prev => prev.map(v => {
        if (v.id !== vehicleId) return v;

        const newInventory = Array.isArray(v.inventory) ? [...v.inventory] : [];
        const existingItemIndex = newInventory.findIndex(i => i.id === product.id);

        if (existingItemIndex > -1) {
            const newQty = newInventory[existingItemIndex].quantity + delta;
            if (newQty <= 0) {
                newInventory.splice(existingItemIndex, 1);
            } else {
                newInventory[existingItemIndex] = { ...newInventory[existingItemIndex], quantity: newQty };
            }
        } else if (delta > 0) {
            newInventory.push({ ...product, quantity: delta });
        }

        const newLoad = newInventory.reduce((acc, item) => acc + (item.quantity || 0), 0);

        return { ...v, inventory: newInventory, currentLoad: newLoad, lastUpdated: Date.now() };
    }));

    setProducts(prev => prev.map(p => {
        if (p.id === product.id) {
            return { ...p, stock: p.stock - delta, lastUpdated: Date.now() };
        }
        return p;
    }));
  };

  const addFuelRecord = (vehicleId: string, record: FuelRecord) => {
    setVehicles(prev => prev.map(v => {
      if (v.id !== vehicleId) return v;
      return { 
        ...v, 
        fuelHistory: [record, ...(v.fuelHistory || [])],
        lastUpdated: Date.now()
      };
    }));
  };

  const sendMessage = (text: string, senderId: string, receiverId: string) => {
    const newMessage: Message = {
      id: `MSG-${Date.now()}`,
      text,
      senderId,
      receiverId,
      timestamp: Date.now(),
      read: false
    };

    setMessages(prev => {
        const updatedMessages = [...prev, newMessage];
        if (cloudConfig.url && cloudConfig.autoSync) {
            const endpoint = `${cloudConfig.url}messages.json${cloudConfig.apiKey ? `?auth=${cloudConfig.apiKey}` : ''}`;
            fetch(endpoint, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(updatedMessages)
            }).catch(err => console.error("Error pushing message to cloud:", err));
        }
        return updatedMessages;
    });
  };

  return { 
    deviceId, 
    products, 
    saveProduct: (p: Product) => setProducts(prev => prev.find(x => x.id === p.id) ? prev.map(x => x.id === p.id ? { ...p, lastUpdated: Date.now() } : x) : [...prev, { ...p, lastUpdated: Date.now() }]),
    deleteProduct: (id: string) => setProducts(prev => prev.filter(p => p.id !== id)),
    customers, 
    saveCustomer: (c: Customer) => setCustomers(prev => prev.find(x => x.id === c.id) ? prev.map(x => x.id === c.id ? { ...c, lastUpdated: Date.now() } : x) : [...prev, { ...c, lastUpdated: Date.now() }]),
    deleteCustomer: (id: string) => setCustomers(prev => prev.filter(c => c.id !== id)),
    importCustomers,
    sales, addSale, resetSales,
    orders, 
    setOrders,
    addOrder: (o: Partial<Order>) => {
      const newOrder: Order = {
        id: `ORD-${Date.now().toString().slice(-6)}-${deviceId}`,
        timestamp: Date.now(),
        status: 'pendiente',
        priority: 1,
        items: [],
        total: 0,
        customerId: '',
        customerAlias: '',
        deviceId: deviceId,
        lastUpdated: Date.now(), 
        ...o
      } as Order;
      setOrders(prev => [newOrder, ...prev]);
    },
    updateOrder: (o: Order) => setOrders(prev => prev.map(item => item.id === o.id ? { ...o, lastUpdated: Date.now() } : item)),
    employees, 
    saveEmployee: (e: Employee) => setEmployees(prev => prev.find(x => x.id === e.id) ? prev.map(x => x.id === e.id ? { ...e, lastUpdated: Date.now() } : x) : [...prev, { ...e, lastUpdated: Date.now() }]),
    deleteEmployee: (id: string) => setEmployees(prev => prev.filter(e => e.id !== id)),
    vehicles, 
    setVehicles,
    loadVehicle,
    deleteVehicle: (id: string) => setVehicles(prev => prev.filter(v => v.id !== id)),
    addFuelRecord,
    tasks,
    addTask: (t: Partial<Task>) => {
      const newTask: Task = {
        id: `TSK-${Date.now().toString().slice(-4)}-${deviceId}`,
        timestamp: Date.now(),
        status: 'pendiente',
        deviceId: deviceId,
        lastUpdated: Date.now(),
        ...t
      } as Task;
      setTasks(prev => [newTask, ...prev]);
    },
    updateTaskStatus: (id: string, status: Task['status']) => setTasks(prev => prev.map(t => t.id === id ? { ...t, status, lastUpdated: Date.now() } : t)),
    updateTask: (task: Task) => setTasks(prev => prev.map(t => t.id === task.id ? { ...task, lastUpdated: Date.now() } : t)),
    deleteTask: (id: string) => setTasks(prev => prev.filter(t => t.id !== id)),
    clearTasksByDate: (date: string) => setTasks(prev => prev.filter(t => t.date !== date)),
    attendance,
    recordAttendance: (employeeId: string, status: Attendance['status']) => {
      const date = getLocalDateISO();
      setAttendance(prev => {
        const filtered = prev.filter(a => !(a.employeeId === employeeId && a.date === date));
        return [{ id: `ATT-${Date.now()}`, employeeId, status, date, timestamp: Date.now() }, ...filtered];
      });
    },
    qualityRecords,
    addQualityRecord: (r: Partial<QualityRecord>) => {
      const newRecord: QualityRecord = {
        id: `QUAL-${Date.now().toString().slice(-4)}`,
        timestamp: Date.now(),
        employeeId: 'admin',
        ...r
      } as QualityRecord;
      setQualityRecords(prev => [newRecord, ...prev]);
    },
    ticketConfig, setTicketConfig,
    productionConfig, setProductionConfig,
    cloudConfig, setCloudConfig,
    syncData,
    savedReports,
    addSavedReport: (r: SavedReport) => setSavedReports(prev => [r, ...prev]),
    deleteSavedReport: (id: string) => setSavedReports(prev => prev.filter(r => r.id !== id)),
    messages,
    sendMessage,
    notifications,
    addNotification,
    markNotificationRead,
    deleteNotification,
    clearAllNotifications
  };
};

// Create Context
const ERPContext = createContext<ReturnType<typeof useERPFactory> | null>(null);

// Provider Component
export const ERPProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const data = useERPFactory();
  return <ERPContext.Provider value={data}>{children}</ERPContext.Provider>;
};

// Accessor Hook (to be re-exported)
export const useERPDataHook = () => {
  const context = useContext(ERPContext);
  if (!context) throw new Error("useERPData must be used within ERPProvider");
  return context;
};

import React, { useState } from 'react';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';
import { Employee, ViewType, Task, Attendance, Role } from '../types';

const TASK_PRESETS = [
  { title: 'Reparto', icon: 'fa-truck-fast', desc: 'Ruta de entrega programada' },
  { title: 'Lavado y Llenado', icon: 'fa-faucet-drip', desc: 'Higienización y llenado de garrafones' },
  { title: 'Apertura de Local', icon: 'fa-door-open', desc: 'Protocolo de apertura 8:00 AM' },
  { title: 'Cierre de Local', icon: 'fa-door-closed', desc: 'Protocolo de cierre y corte de caja' },
  { title: 'Lavado de Tinacos', icon: 'fa-circle-dot', desc: 'Mantenimiento preventivo de tinacos' },
  { title: 'Regeneración', icon: 'fa-flask-vial', desc: 'Regeneración química de resinas' },
  { title: 'Retrolavado', icon: 'fa-water-ladder', desc: 'Limpieza de filtros multimedia' },
  { title: 'Mantenimiento General', icon: 'fa-tools', desc: 'Revisión técnica de equipos' },
];

const AVAILABLE_ROLES: Role[] = ['Administrador', 'Repartidor', 'Planta'];

export const EmployeesModule: React.FC<{ onBack: () => void; currentUser: Employee }> = ({ onBack, currentUser }) => {
  const { employees, saveEmployee, deleteEmployee, tasks, addTask, updateTaskStatus, updateTask, deleteTask, clearTasksByDate, attendance, recordAttendance } = useERPData();
  const [activeTab, setActiveTab] = useState<'roster' | 'assignments' | 'attendance'>('roster');
  const [editingEmployee, setEditingEmployee] = useState<Partial<Employee> | null>(null);
  const [assigningTo, setAssigningTo] = useState<Employee | null>(null);
  const [customTaskTitle, setCustomTaskTitle] = useState('');

  // Validation States
  const [validatingTask, setValidatingTask] = useState<Task | null>(null);
  const [validationDate, setValidationDate] = useState('');

  // New state for task status on creation
  const [markAsCompleted, setMarkAsCompleted] = useState(false);

  const isAdmin = currentUser.roles.includes('Administrador');

  // Robust Local Date
  const today = (() => {
    const d = new Date();
    const offset = d.getTimezoneOffset() * 60000;
    return new Date(d.getTime() - offset).toISOString().split('T')[0];
  })();

  const rosterModules: { id: ViewType; label: string; icon: string }[] = [
    { id: 'pos', label: 'Ventas', icon: 'fa-cash-register' },
    { id: 'orders', label: 'Pedidos', icon: 'fa-clipboard-list' },
    { id: 'customers', label: 'Clientes', icon: 'fa-address-book' },
    { id: 'inventory', label: 'Inventario', icon: 'fa-box-open' },
    { id: 'supplies', label: 'Insumos', icon: 'fa-boxes-stacked' },
    { id: 'logistics', label: 'Flota', icon: 'fa-truck-moving' },
    { id: 'whatsapp', label: 'Preventa', icon: 'fa-brands fa-whatsapp' },
    { id: 'messages', label: 'Mensajes', icon: 'fa-comments' },
    { id: 'production', label: 'Producción', icon: 'fa-industry' },
    { id: 'quality', label: 'Bitácoras', icon: 'fa-book-medical' },
    { id: 'scanner', label: 'Scanner', icon: 'fa-qrcode' },
    { id: 'employees', label: 'Equipo', icon: 'fa-users-gear' },
    { id: 'reports', label: 'Reportes', icon: 'fa-chart-pie' },
    { id: 'tickets', label: 'Tickets', icon: 'fa-ticket' },
    { id: 'sync', label: 'P2P Sync', icon: 'fa-cloud-arrow-up' },
    { id: 'settings', label: 'Ajustes', icon: 'fa-sliders' },
  ];

  const getRoleColor = (role: string) => {
    switch(role) {
      case 'Administrador': return 'bg-rose-500';
      case 'Repartidor': return 'bg-sky-500';
      case 'Planta': return 'bg-amber-500';
      default: return 'bg-slate-500';
    }
  };

  const getTaskStats = (empId: string) => {
    const todaysTasks = tasks.filter(t => t.employeeId === empId && t.date === today);
    return {
      total: todaysTasks.length,
      pending: todaysTasks.filter(t => t.status === 'pendiente').length
    };
  };

  const handleSaveEmployee = () => {
    if (!editingEmployee?.name || !editingEmployee?.pin || !editingEmployee?.roles || editingEmployee.roles.length === 0) {
      alert("Nombre, PIN y al menos un Rol son obligatorios.");
      return;
    }
    const empToSave: Employee = {
      id: editingEmployee.id || `EMP-${Date.now().toString().slice(-4)}`,
      name: editingEmployee.name,
      roles: editingEmployee.roles,
      phone: editingEmployee.phone || '',
      pin: editingEmployee.pin,
      permissions: editingEmployee.permissions || ['dashboard']
    };
    saveEmployee(empToSave);
    setEditingEmployee(null);
  };

  const handleDeleteEmployee = () => {
    if (!editingEmployee?.id) return;
    if (editingEmployee.id === currentUser.id) {
        alert("No puedes eliminar tu propio usuario.");
        return;
    }
    if (confirm(`¿Eliminar a ${editingEmployee.name}? Esta acción es irreversible.`)) {
        deleteEmployee(editingEmployee.id);
        setEditingEmployee(null);
    }
  };

  const togglePermission = (modId: ViewType) => {
    if (!editingEmployee) return;
    const currentPerms = editingEmployee.permissions || [];
    const newPerms = currentPerms.includes(modId)
      ? currentPerms.filter(p => p !== modId)
      : [...currentPerms, modId];
    setEditingEmployee({ ...editingEmployee, permissions: newPerms });
  };

  const toggleRole = (role: Role) => {
    if (!editingEmployee) return;
    const currentRoles = editingEmployee.roles || [];
    const newRoles = currentRoles.includes(role)
        ? currentRoles.filter(r => r !== role)
        : [...currentRoles, role];
    setEditingEmployee({ ...editingEmployee, roles: newRoles });
  };

  const handleAddTask = (preset: typeof TASK_PRESETS[0] | { title: string, desc: string }) => {
    if (!assigningTo) return;

    addTask({
      employeeId: assigningTo.id,
      title: preset.title,
      description: preset.desc,
      date: today,
      status: markAsCompleted ? 'completada' : 'pendiente'
    });
    setAssigningTo(null);
    setCustomTaskTitle('');
    setMarkAsCompleted(false); // Reset to default
  };

  const initiateValidation = (task: Task) => {
    // Si soy admin, abro el modal para elegir fecha
    if (isAdmin) {
        setValidatingTask(task);
        setValidationDate(today);
    } else {
        // Si no, completado simple (actual)
        updateTaskStatus(task.id, 'completada');
    }
  };

  const confirmValidation = () => {
    if (validatingTask && validationDate) {
        // Actualizamos estado y fecha (si el admin indica que se hizo ayer, se mueve a ayer)
        updateTask({
            ...validatingTask,
            status: 'completada',
            date: validationDate
        });
        setValidatingTask(null);
    }
  };

  const generateDailyRoutine = () => {
    if (!confirm("¿Generar rutina automática para hoy?\nSe asignarán tareas base a todos los colaboradores activos según sus roles.")) return;

    let count = 0;
    employees.forEach(e => {
      // Ignorar administradores para tareas operativas automáticas (a menos que tengan otro rol)
      if (e.roles.includes('Administrador') && e.roles.length === 1) return;

      if (e.roles.includes('Repartidor')) {
        addTask({
          id: `AUTO-${Date.now()}-${count++}`,
          employeeId: e.id,
          title: 'Carga de Unidad',
          description: 'Verificar inventario y cargar camión',
          date: today
        });
        addTask({
          id: `AUTO-${Date.now()}-${count++}`,
          employeeId: e.id,
          title: 'Ruta de Reparto',
          description: 'Entrega a clientes programados',
          date: today
        });
      } 

      if (e.roles.includes('Planta')) {
        addTask({
          id: `AUTO-${Date.now()}-${count++}`,
          employeeId: e.id,
          title: 'Apertura y Limpieza',
          description: 'Protocolo de higiene inicial',
          date: today
        });
        addTask({
          id: `AUTO-${Date.now()}-${count++}`,
          employeeId: e.id,
          title: 'Producción',
          description: 'Supervisión de llenado y calidad',
          date: today
        });
      }
    });
  };

  const handleClearDay = () => {
    if (confirm("¿Estás seguro de ELIMINAR TODAS las tareas de hoy para todos los empleados?")) {
      clearTasksByDate(today);
    }
  };

  if (editingEmployee) {
    return (
      <div className="h-full bg-sky-50 overflow-y-auto no-scrollbar pb-32">
        <ModuleHeader title={editingEmployee.id ? "Editar Colaborador" : "Nuevo Colaborador"} onBack={() => setEditingEmployee(null)} />
        <div className="px-6 space-y-6 animate-fadeIn">
          <div className="space-y-4">
             <div>
                <label className="text-[10px] font-black text-sky-400 uppercase ml-3 mb-1 block">Nombre Completo</label>
                <input className="w-full bg-white p-5 rounded-[2rem] outline-none shadow-sm font-bold text-sky-900 focus:ring-2 ring-sky-300 transition-all" placeholder="Ej: Juan Pérez" value={editingEmployee.name || ''} onChange={e => setEditingEmployee({...editingEmployee, name: e.target.value})}/>
             </div>

             <div>
                <label className="text-[10px] font-black text-sky-400 uppercase ml-3 mb-1 block">PIN de Acceso</label>
                <input maxLength={4} className="w-full bg-white p-5 rounded-[2rem] outline-none shadow-sm font-black text-sky-900 text-center tracking-[0.5em] focus:ring-2 ring-sky-300" placeholder="0000" value={editingEmployee.pin || ''} onChange={e => setEditingEmployee({...editingEmployee, pin: e.target.value})}/>
             </div>

             <section className="space-y-3">
                <label className="text-[10px] font-black text-sky-400 uppercase ml-3 block">Roles Asignados</label>
                <div className="flex flex-wrap gap-2">
                   {AVAILABLE_ROLES.map(role => {
                     const isSelected = editingEmployee.roles?.includes(role);
                     return (
                        <button 
                          key={role}
                          onClick={() => toggleRole(role)}
                          className={`flex-1 py-3 px-4 rounded-2xl font-black text-[10px] uppercase tracking-wider transition-all border ${isSelected ? `${getRoleColor(role)} text-white border-transparent shadow-lg` : 'bg-white text-slate-400 border-slate-100'}`}
                        >
                          {role}
                        </button>
                     );
                   })}
                </div>
             </section>

             <div>
                <label className="text-[10px] font-black text-sky-400 uppercase ml-3 mb-1 block">WhatsApp</label>
                <input className="w-full bg-white p-5 rounded-[2rem] outline-none shadow-sm text-sky-900 focus:ring-2 ring-sky-300" placeholder="33..." value={editingEmployee.phone || ''} onChange={e => setEditingEmployee({...editingEmployee, phone: e.target.value})}/>
             </div>

             <section className="space-y-3">
                <label className="text-[10px] font-black text-sky-400 uppercase ml-3 block">Permisos de Módulo</label>
                <div className="grid grid-cols-2 gap-2">
                   {rosterModules.map(mod => (
                     <button 
                        key={mod.id} 
                        onClick={() => togglePermission(mod.id)}
                        className={`flex items-center gap-2 p-3 rounded-2xl transition-all ${editingEmployee.permissions?.includes(mod.id) ? 'bg-sky-600 text-white shadow-md' : 'bg-white text-sky-300 border border-sky-50'}`}
                      >
                       <i className={`fas ${mod.icon} text-[10px]`}></i>
                       <span className="text-[9px] font-black uppercase tracking-tighter">{mod.label}</span>
                     </button>
                   ))}
                </div>
             </section>
          </div>

          <div className="pt-4 space-y-3">
             <ActionButton onClick={handleSaveEmployee}>Guardar Cambios</ActionButton>
             {editingEmployee.id && (
                <button 
                    onClick={handleDeleteEmployee}
                    className="w-full py-4 text-rose-500 font-black uppercase text-[10px] tracking-widest bg-rose-50 rounded-[1.5rem] border border-rose-100 shadow-sm active:scale-[0.97] transition-all flex items-center justify-center gap-2 hover:bg-rose-100"
                >
                    <i className="fas fa-trash-can"></i> Eliminar Colaborador
                </button>
             )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="h-full bg-sky-50 flex flex-col animate-fadeIn overflow-hidden pb-24">
      <ModuleHeader title="Gestión de Equipo" onBack={onBack} />

      {/* Tab Selector */}
      <div className="px-6 flex gap-2 mb-6 shrink-0">
        <button onClick={() => setActiveTab('roster')} className={`flex-1 py-3.5 rounded-2xl text-[9px] font-black uppercase tracking-widest transition-all ${activeTab === 'roster' ? 'bg-sky-600 text-white shadow-lg shadow-sky-100' : 'bg-white text-sky-400'}`}>Roster</button>
        <button onClick={() => setActiveTab('assignments')} className={`flex-1 py-3.5 rounded-2xl text-[9px] font-black uppercase tracking-widest transition-all ${activeTab === 'assignments' ? 'bg-sky-600 text-white shadow-lg shadow-sky-100' : 'bg-white text-sky-400'}`}>Tareas</button>
        <button onClick={() => setActiveTab('attendance')} className={`flex-1 py-3.5 rounded-2xl text-[9px] font-black uppercase tracking-widest transition-all ${activeTab === 'attendance' ? 'bg-sky-600 text-white shadow-lg shadow-sky-100' : 'bg-white text-sky-400'}`}>Asistencias</button>
      </div>

      <div className="flex-1 overflow-y-auto px-6 space-y-6 no-scrollbar pb-10">

        {/* ROSTER TAB */}
        {activeTab === 'roster' && (
          <div className="space-y-4">
            <div className="bg-sky-900 text-white rounded-[2.5rem] p-6 shadow-xl flex items-center gap-4">
                <div className="w-16 h-16 bg-white/20 rounded-[2rem] flex items-center justify-center text-3xl">
                  <i className="fas fa-users-viewfinder"></i>
                </div>
                <div>
                  <h3 className="text-xl font-black">Capital Humano</h3>
                  <p className="text-[10px] font-bold uppercase opacity-60 tracking-widest">{employees.length} Colaboradores Activos</p>
                </div>
            </div>

            {employees.map(e => {
              const stats = getTaskStats(e.id);
              const mainRole = e.roles[0] || 'Planta';
              return (
                <RoundedCard key={e.id} className="py-4 border-none shadow-sm group">
                  <div className="flex justify-between items-center">
                    <div className="flex items-center gap-4">
                      <div className={`w-14 h-14 ${getRoleColor(mainRole)} text-white rounded-3xl flex items-center justify-center text-xl shadow-lg shadow-sky-100`}>
                        <i className={`fas ${mainRole === 'Administrador' ? 'fa-user-tie' : mainRole === 'Repartidor' ? 'fa-truck-fast' : 'fa-industry'}`}></i>
