  })();

  const rosterModules: { id: ViewType; label: string; icon: string }[] = [
    { id: 'pos', label: 'Ventas', icon: 'fa-cash-register' },
    { id: 'orders', label: 'Pedidos', icon: 'fa-clipboard-list' },
