const LogisticsMap = ({ customers, vehicles }: { customers: Customer[], vehicles: Vehicle[] }) => {
  const mapRef = useRef<HTMLDivElement>(null);
  const mapInstance = useRef<L.Map | null>(null);
  const markersRef = useRef<L.LayerGroup | null>(null);
  const routeRef = useRef<L.Polyline | null>(null);

  // Simulation State
  const [isSimulating, setIsSimulating] = useState(false);
  const vehicleMarkers = useRef<Map<string, L.Marker>>(new Map());

  useEffect(() => {
    if (!mapRef.current) return;

    // 1. Init Map (Guadalajara default if no data)
    if (!mapInstance.current) {
        mapInstance.current = L.map(mapRef.current, {
            zoomControl: false,
            attributionControl: false
        }).setView([20.6766, -103.3468], 13); // Default GDL

        L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
            attribution: '&copy; OpenStreetMap'
        }).addTo(mapInstance.current);

        markersRef.current = L.layerGroup().addTo(mapInstance.current);
    }

    const map = mapInstance.current;
    const markersLayer = markersRef.current;

    // Clear previous markers (except vehicles handled separately)
    markersLayer?.clearLayers();

    // 2. Add Plant Marker
    const plantIcon = L.divIcon({
        className: 'custom-marker-icon',
        html: `<div style="background-color: #0ea5e9; width: 40px; height: 40px; border-radius: 50%; display: flex; align-items: center; justify-content: center; box-shadow: 0 4px 10px rgba(14, 165, 233, 0.4); border: 3px solid white;">
                <i class="fas fa-store text-white text-lg"></i>
               </div>`,
        iconSize: [40, 40],
        iconAnchor: [20, 40]
    });
    // Assuming Plant is at the default center or configurable. Using default for now.
    L.marker([20.6766, -103.3468], { icon: plantIcon }).addTo(markersLayer!)
     .bindPopup(`<div class="font-bold text-sky-900">Planta Matriz</div>`);

    // 3. Add Customer Markers
    let bounds = L.latLngBounds([20.6766, -103.3468]);

    customers.forEach(c => {
        if (c.lat && c.lng) {
            const hasDebt = c.balance > 0;
            const markerColor = hasDebt ? '#ef4444' : '#10b981';

            const custIcon = L.divIcon({
                className: 'custom-marker-icon',
                html: `<div style="background-color: ${markerColor}; width: 30px; height: 30px; border-radius: 50%; display: flex; align-items: center; justify-content: center; box-shadow: 0 2px 5px rgba(0,0,0,0.2); border: 2px solid white;">
                        <i class="fas ${hasDebt ? 'fa-dollar-sign' : 'fa-user'} text-white text-xs"></i>
                       </div>`,
                iconSize: [30, 30],
                iconAnchor: [15, 15]
            });

            L.marker([c.lat, c.lng], { icon: custIcon })
             .bindPopup(`
                <div class="text-center">
                    <p class="font-black text-slate-800 uppercase text-xs">${c.alias}</p>
                    <p class="text-[10px] ${hasDebt ? 'text-red-500 font-bold' : 'text-slate-500'}">${hasDebt ? `Adeudo: $${c.balance}` : 'Al corriente'}</p>
                </div>
             `)
             .addTo(markersLayer!);

            bounds.extend([c.lat, c.lng]);
        }
    });

    if (customers.some(c => c.lat && c.lng)) {
        map.fitBounds(bounds, { padding: [50, 50] });
    }

    // 4. Initialize Vehicle Markers
    vehicles.forEach((v, index) => {
        if (!vehicleMarkers.current.has(v.id)) {
            // Random start position around center for demo
            const offsetLat = (Math.random() - 0.5) * 0.02;
            const offsetLng = (Math.random() - 0.5) * 0.02;
            const startPos: [number, number] = [20.6766 + offsetLat, -103.3468 + offsetLng];

            const vehicleIcon = L.divIcon({
                className: 'custom-marker-icon',
                html: `<div style="background-color: #f59e0b; width: 48px; height: 48px; border-radius: 12px; display: flex; align-items: center; justify-content: center; box-shadow: 0 8px 15px rgba(245, 158, 11, 0.4); border: 3px solid white; transform: rotate(0deg);">
                        <i class="fas fa-truck-fast text-white text-xl"></i>
                       </div>`,
                iconSize: [48, 48],
                iconAnchor: [24, 24]
            });

            const marker = L.marker(startPos, { icon: vehicleIcon }).addTo(map);
            marker.bindPopup(`<p class="font-black text-amber-600 uppercase text-xs">${v.plate}</p>`);
            vehicleMarkers.current.set(v.id, marker);
        }
    });

  }, [customers, vehicles]);

  // --- SIMULATION EFFECT ---
  useEffect(() => {
    let interval: any;
    if (isSimulating) {
        interval = setInterval(() => {
            vehicleMarkers.current.forEach((marker) => {
                const currentLL = marker.getLatLng();
                // Move randomly slightly
                const moveLat = (Math.random() - 0.5) * 0.001;
                const moveLng = (Math.random() - 0.5) * 0.001;
                const newPos = [currentLL.lat + moveLat, currentLL.lng + moveLng] as [number, number];

                marker.setLatLng(newPos);
            });
        }, 1000);
    }
    return () => clearInterval(interval);
  }, [isSimulating]);

  return (
    <div className="relative w-full h-full rounded-[2.5rem] overflow-hidden shadow-inner border border-white/20">
        <div ref={mapRef} className="w-full h-full bg-slate-100 z-0" />

        {/* Map Controls */}
        <div className="absolute bottom-6 right-6 z-[400] flex flex-col gap-3">
            <button 
                onClick={() => setIsSimulating(!isSimulating)}
                className={`w-14 h-14 rounded-2xl flex items-center justify-center shadow-xl transition-all active:scale-90 ${isSimulating ? 'bg-red-500 text-white animate-pulse' : 'bg-white text-emerald-500'}`}
            >
                <i className={`fas ${isSimulating ? 'fa-stop' : 'fa-play'}`}></i>
            </button>
            <button className="w-14 h-14 bg-white text-sky-600 rounded-2xl flex items-center justify-center shadow-xl active:scale-90 transition-transform" onClick={() => mapInstance.current?.setZoom(mapInstance.current.getZoom() + 1)}>
                <i className="fas fa-plus"></i>
            </button>
            <button className="w-14 h-14 bg-white text-sky-600 rounded-2xl flex items-center justify-center shadow-xl active:scale-90 transition-transform" onClick={() => mapInstance.current?.setZoom(mapInstance.current.getZoom() - 1)}>
                <i className="fas fa-minus"></i>
            </button>
        </div>

        {/* Legend */}
        <div className="absolute top-6 left-6 z-[400] bg-white/90 backdrop-blur-md p-4 rounded-3xl shadow-lg border border-white/50">
            <h4 className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2">Simbología</h4>
            <div className="space-y-2">
                <div className="flex items-center gap-2">
                    <div className="w-3 h-3 rounded-full bg-emerald-500"></div>
                    <span className="text-[9px] font-bold text-slate-600">Cliente al Corriente</span>
                </div>
                <div className="flex items-center gap-2">
                    <div className="w-3 h-3 rounded-full bg-red-500"></div>
                    <span className="text-[9px] font-bold text-slate-600">Cliente con Deuda</span>
                </div>
                <div className="flex items-center gap-2">
                    <div className="w-3 h-3 rounded-md bg-amber-500"></div>
                    <span className="text-[9px] font-bold text-slate-600">Unidad en Ruta</span>
                </div>
            </div>
        </div>
    </div>
  );
};

export const LogisticsModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const { vehicles, setVehicles, deleteVehicle, customers } = useERPData();
  const [viewMode, setViewMode] = useState<'list' | 'map'>('list');
