};

const FuelModal = ({ vehicleId, onClose }: { vehicleId: string, onClose: () => void }) => {
  const { vehicles, addFuelRecord } = useERPData();
  const vehicle = vehicles.find(v => v.id === vehicleId);
  const [fuelForm, setFuelForm] = useState<Partial<FuelRecord>>({ mileage: undefined, liters: undefined, cost: undefined, notes: '' });

  if (!vehicle) return null;

  const handleAddFuel = () => {
    if (!fuelForm.mileage || !fuelForm.liters || !fuelForm.cost) {
      alert("Por favor completa los campos.");
      return;
    }
    addFuelRecord(vehicleId, {
      id: Date.now().toString(),
      date: Date.now(),
      mileage: fuelForm.mileage,
      liters: fuelForm.liters,
      cost: fuelForm.cost,
      notes: fuelForm.notes
    });
    setFuelForm({ mileage: undefined, liters: undefined, cost: undefined, notes: '' });
    alert("Carga registrada.");
  };

  const history = vehicle.fuelHistory || [];
  const costPerLiter = (fuelForm.cost && fuelForm.liters) ? (fuelForm.cost / fuelForm.liters) : 0;

  return (
    <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[200] flex items-center justify-center p-4 animate-fadeIn">
      <div className="bg-white w-full max-w-md rounded-[2.5rem] p-6 shadow-2xl max-h-[85vh] overflow-y-auto no-scrollbar">
        <div className="flex justify-between items-center mb-6">
          <div className="flex items-center gap-3">
            <div className="w-12 h-12 bg-amber-100 text-amber-500 rounded-2xl flex items-center justify-center text-xl shadow-sm">
              <i className="fas fa-gas-pump"></i>
            </div>
            <div>
              <h3 className="text-lg font-black text-sky-900">Combustible</h3>
              <p className="text-[10px] text-sky-400 font-bold uppercase">{vehicle.plate}</p>
            </div>
          </div>
          <button onClick={onClose} className="w-10 h-10 bg-slate-100 rounded-full flex items-center justify-center text-slate-400 hover:bg-slate-200 transition-colors"><i className="fas fa-times"></i></button>
        </div>

        <div className="bg-slate-50 p-5 rounded-[2rem] border border-slate-100 mb-6">
           <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Nueva Carga</h4>
           <div className="grid grid-cols-2 gap-3 mb-3">
             <div className="bg-white p-3 rounded-2xl shadow-sm">
               <label className="text-[8px] font-black text-slate-400 uppercase block mb-1">Kilometraje</label>
               <input type="number" className="w-full outline-none text-sm font-bold text-slate-700 bg-transparent" placeholder="KM" value={fuelForm.mileage || ''} onChange={e => setFuelForm({...fuelForm, mileage: Number(e.target.value)})}/>
             </div>
             <div className="bg-white p-3 rounded-2xl shadow-sm">
               <label className="text-[8px] font-black text-slate-400 uppercase block mb-1">Litros</label>
               <input type="number" className="w-full outline-none text-sm font-bold text-slate-700 bg-transparent" placeholder="L" value={fuelForm.liters || ''} onChange={e => setFuelForm({...fuelForm, liters: Number(e.target.value)})}/>
             </div>
           </div>
           <div className="bg-white p-3 rounded-2xl shadow-sm mb-4 relative">
             <label className="text-[8px] font-black text-slate-400 uppercase block mb-1">Costo Total ($)</label>
             <input type="number" className="w-full outline-none text-lg font-black text-emerald-600 bg-transparent" placeholder="0.00" value={fuelForm.cost || ''} onChange={e => setFuelForm({...fuelForm, cost: Number(e.target.value)})}/>
             {costPerLiter > 0 && <span className="absolute right-3 top-1/2 -translate-y-1/2 text-[9px] font-bold text-slate-400 bg-slate-50 px-2 py-1 rounded">${costPerLiter.toFixed(2)}/L</span>}
           </div>
           <button onClick={handleAddFuel} className="w-full py-4 bg-amber-500 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-lg shadow-amber-200 active:scale-95 transition-all">Registrar</button>
        </div>

        <div>
          <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 ml-2">Historial</h4>
          <div className="space-y-2 max-h-60 overflow-y-auto no-scrollbar">
             {history.length === 0 ? <p className="text-center text-[10px] text-slate-400 py-4 italic">Sin registros previos.</p> : history.map(r => (
               <div key={r.id} className="bg-white p-3 rounded-2xl shadow-sm border border-slate-50 flex justify-between items-center">
                  <div>
                     <p className="text-[10px] font-black text-slate-400 uppercase">{new Date(r.date).toLocaleDateString()}</p>
                     <p className="text-xs font-bold text-slate-700">{r.mileage.toLocaleString()} km</p>
                  </div>
                  <div className="text-right">
                     <p className="text-sm font-black text-emerald-600">${r.cost.toLocaleString()}</p>
                     <p className="text-[9px] font-bold text-amber-500">{r.liters} L</p>
                  </div>
               </div>
             ))}
          </div>
        </div>
      </div>
    </div>
  );
};

