import React, { useState, useEffect, useRef } from 'react';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';
import { Vehicle, Product, FuelRecord, Customer, Order } from '../types';
import L from 'leaflet';

// --- HELPER: ICONOS DE MAPA ---
const createIcon = (color: string, iconClass: string, size = 32) => {
    return L.divIcon({
        className: 'custom-marker-icon',
        html: `<div style="background-color: ${color}; width: ${size}px; height: ${size}px; border-radius: 50%; display: flex; align-items: center; justify-content: center; box-shadow: 0 4px 8px rgba(0,0,0,0.3); border: 2px solid white;">
                <i class="fas ${iconClass} text-white" style="font-size: ${size * 0.5}px"></i>
               </div>`,
        iconSize: [size, size],
        iconAnchor: [size / 2, size / 2]
    });
};

// --- MODALES (Carga y Combustible se mantienen igual para funcionalidad) ---
const LoadingModal = ({ vehicleId, onClose }: { vehicleId: string, onClose: () => void }) => {
  const { vehicles, products, loadVehicle } = useERPData();
  const vehicle = vehicles.find(v => v.id === vehicleId);
  if (!vehicle) return null;

  return (
    <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[200] flex items-center justify-center p-4 animate-fadeIn">
      <div className="bg-white w-full max-w-md rounded-[2.5rem] p-6 shadow-2xl max-h-[85vh] flex flex-col relative overflow-hidden">
        <div className="flex justify-between items-center mb-6 shrink-0">
          <div><h3 className="text-xl font-black text-sky-900">Cargar Unidad</h3><p className="text-[10px] text-sky-400 font-bold uppercase">{vehicle.description}</p></div>
          <button onClick={onClose} className="w-10 h-10 bg-slate-100 rounded-full flex items-center justify-center text-slate-400"><i className="fas fa-times"></i></button>
        </div>
        <div className="flex-1 overflow-y-auto custom-scrollbar space-y-3 pr-1 pb-4">
          {products.filter(p => p.category !== 'Insumos').map(p => {
            const inVehicle = vehicle.inventory?.find(i => i.id === p.id)?.quantity || 0;
            return (
              <div key={p.id} className="bg-sky-50 p-4 rounded-[1.5rem] flex items-center justify-between">
                <div><p className="text-[10px] font-black text-sky-900 uppercase">{p.name}</p><span className="text-[8px] text-sky-400 font-bold">Planta: {p.stock}</span></div>
                <div className="flex items-center gap-3 bg-white rounded-xl p-1">
                  <button onClick={() => loadVehicle(vehicle.id, p, -1)} className="w-8 h-8 bg-sky-100 text-sky-600 rounded-lg font-bold">-</button>
                  <span className="font-black text-sky-900 w-6 text-center">{inVehicle}</span>
                  <button onClick={() => loadVehicle(vehicle.id, p, 1)} className="w-8 h-8 bg-sky-600 text-white rounded-lg font-bold shadow-lg shadow-sky-200">+</button>
                </div>
              </div>
            );
          })}
        </div>
        <div className="mt-4 pt-4 border-t border-sky-100"><button onClick={onClose} className="w-full py-4 bg-emerald-500 text-white rounded-[1.5rem] font-black uppercase shadow-lg">Listo</button></div>
      </div>
    </div>
  );
};

const FuelModal = ({ vehicleId, onClose }: { vehicleId: string, onClose: () => void }) => {
  const { vehicles, addFuelRecord } = useERPData();
  const [fuelForm, setFuelForm] = useState<Partial<FuelRecord>>({});
  const handleAddFuel = () => {
    if (!fuelForm.mileage || !fuelForm.liters || !fuelForm.cost) return alert("Completa los campos");
    addFuelRecord(vehicleId, { id: Date.now().toString(), date: Date.now(), mileage: fuelForm.mileage, liters: fuelForm.liters, cost: fuelForm.cost, notes: fuelForm.notes } as FuelRecord);
    onClose();
  };
  return (
    <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[200] flex items-center justify-center p-4 animate-fadeIn">
      <div className="bg-white w-full max-w-md rounded-[2.5rem] p-6 shadow-2xl">
        <h3 className="text-lg font-black text-sky-900 mb-4">Registro Combustible</h3>
        <div className="space-y-3 mb-4">
           <input type="number" className="w-full bg-slate-50 p-3 rounded-xl font-bold text-slate-700" placeholder="Kilometraje Actual" onChange={e => setFuelForm({...fuelForm, mileage: Number(e.target.value)})}/>
           <input type="number" className="w-full bg-slate-50 p-3 rounded-xl font-bold text-slate-700" placeholder="Litros" onChange={e => setFuelForm({...fuelForm, liters: Number(e.target.value)})}/>
           <input type="number" className="w-full bg-slate-50 p-3 rounded-xl font-bold text-slate-700" placeholder="Costo Total ($)" onChange={e => setFuelForm({...fuelForm, cost: Number(e.target.value)})}/>
        </div>
        <div className="flex gap-2">
            <button onClick={onClose} className="flex-1 py-3 bg-slate-100 text-slate-400 rounded-xl font-bold uppercase">Cancelar</button>
            <button onClick={handleAddFuel} className="flex-1 py-3 bg-amber-500 text-white rounded-xl font-bold uppercase shadow-lg">Guardar</button>
        </div>
      </div>
    </div>
  );
};

// --- COMPONENTE DE MAPA REAL ---
const LogisticsMap = ({ customers, vehicles, orders, activeVehicleId }: { customers: Customer[], vehicles: Vehicle[], orders: Order[], activeVehicleId: string | null }) => {
  const mapRef = useRef<HTMLDivElement>(null);
  const mapInstance = useRef<L.Map | null>(null);
  const markersLayer = useRef<L.LayerGroup | null>(null);
  const routeLayer = useRef<L.LayerGroup | null>(null);

  useEffect(() => {
    if (!mapRef.current) return;

    // Inicializar Mapa
    if (!mapInstance.current) {
        mapInstance.current = L.map(mapRef.current, { zoomControl: false }).setView([20.6766, -103.3468], 12);
        L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
            attribution: '&copy; OpenStreetMap'
        }).addTo(mapInstance.current);
        markersLayer.current = L.layerGroup().addTo(mapInstance.current);
        routeLayer.current = L.layerGroup().addTo(mapInstance.current);
    }

    const map = mapInstance.current;
    const layer = markersLayer.current;
    if (!layer) return;

    layer.clearLayers(); // Limpiar marcadores viejos

    // 1. Renderizar Planta (Centro Fijo)
    // En producción real, esto vendría de Settings. Usamos GDL centro por defecto.
    L.marker([20.6766, -103.3468], { icon: createIcon('#0ea5e9', 'fa-industry', 40) })
     .bindPopup("<b>Planta Matriz</b>")
     .addTo(layer);

    // 2. Renderizar Clientes (Solo los que tienen Geo)
    const bounds = L.latLngBounds([20.6766, -103.3468]);
    let hasPoints = false;

    customers.forEach(c => {
        if (c.lat && c.lng) {
            const hasDebt = c.balance > 0;
            const hasActiveOrder = orders.some(o => o.customerId === c.id && o.status !== 'entregado' && o.status !== 'cancelado');

            const color = hasActiveOrder ? '#f59e0b' : (hasDebt ? '#ef4444' : '#10b981');
            const iconClass = hasActiveOrder ? 'fa-box' : (hasDebt ? 'fa-hand-holding-dollar' : 'fa-user');

            L.marker([c.lat, c.lng], { icon: createIcon(color, iconClass, 28) })
             .bindPopup(`<b>${c.alias}</b><br/>${c.address}`)
             .addTo(layer);

            bounds.extend([c.lat, c.lng]);
            hasPoints = true;
        }
    });

    // 3. Renderizar Vehículos (SOLO SI TIENEN UBICACIÓN REAL)
    vehicles.forEach(v => {
        // En typescript v.lat puede no existir si no se ha definido en la interfaz extendida, 
        // pero en JS runtime existe si lo guardamos. Asumimos extension.
        const vAny = v as any; 
        if (vAny.lat && vAny.lng) {
            const isMe = v.id === activeVehicleId;
            const markerHtml = `
                <div style="position: relative;">
                    <div style="background-color: ${isMe ? '#6366f1' : '#f59e0b'}; width: 40px; height: 40px; border-radius: 12px; display: flex; align-items: center; justify-content: center; border: 3px solid white; box-shadow: 0 4px 10px rgba(0,0,0,0.3);">
                        <i class="fas fa-truck text-white"></i>
                    </div>
                    ${isMe ? '<div style="position: absolute; top: -5px; right: -5px; width: 12px; height: 12px; background: #22c55e; border-radius: 50%; border: 2px solid white;"></div>' : ''}
                </div>
            `;

            const icon = L.divIcon({
                className: 'custom-vehicle-icon',
                html: markerHtml,
                iconSize: [40, 40],
                iconAnchor: [20, 20]
            });

            L.marker([vAny.lat, vAny.lng], { icon, zIndexOffset: 1000 })
             .bindPopup(`
                <div class="text-center">
                    <p class="font-bold uppercase text-xs mb-1">${v.plate}</p>
                    <p class="text-[9px] text-slate-500">Última act: ${v.lastUpdated ? new Date(v.lastUpdated).toLocaleTimeString() : 'N/A'}</p>
                </div>
             `)
             .addTo(layer);

            bounds.extend([vAny.lat, vAny.lng]);
            hasPoints = true;
        }
    });

    if (hasPoints) {
        map.fitBounds(bounds, { padding: [50, 50] });
    }

  }, [customers, vehicles, orders, activeVehicleId]);

  return <div ref={mapRef} className="w-full h-full bg-slate-100 z-0" style={{ filter: 'contrast(0.95)' }} />;
};

export const LogisticsModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const { vehicles, setVehicles, deleteVehicle, customers, orders, syncData } = useERPData();
  const [viewMode, setViewMode] = useState<'list' | 'map'>('list');
  const [editingVehicle, setEditingVehicle] = useState<Partial<Vehicle> | null>(null);
  const [activeVehicleId, setActiveVehicleId] = useState<string | null>(null);

  // Modales
  const [loadingVehicleId, setLoadingVehicleId] = useState<string | null>(null);
  const [fuelVehicleId, setFuelVehicleId] = useState<string | null>(null);

  // GPS Watch ID reference
  const watchIdRef = useRef<number | null>(null);

  // Limpiar GPS al desmontar
  useEffect(() => {
    return () => {
        if (watchIdRef.current !== null) {
            navigator.geolocation.clearWatch(watchIdRef.current);
        }
    };
  }, []);

  const startTracking = (vehicleId: string) => {
    if (!navigator.geolocation) return alert("GPS no disponible en este dispositivo.");

    // Detener tracking anterior si existe
    if (watchIdRef.current !== null) navigator.geolocation.clearWatch(watchIdRef.current);

    setActiveVehicleId(vehicleId);
    alert(`📡 Iniciando transmisión de ubicación para unidad: ${vehicles.find(v => v.id === vehicleId)?.plate}`);

    const options = {
        enableHighAccuracy: true,
        timeout: 10000,
        maximumAge: 0
    };

    watchIdRef.current = navigator.geolocation.watchPosition(
        (position) => {
            const { latitude, longitude, heading, speed } = position.coords;

            // Actualización Optimista Local
            setVehicles(prev => prev.map(v => {
                if (v.id === vehicleId) {
                    return {
                        ...v,
                        // Extendemos el tipo Vehicle "on the fly" o asumimos que syncData lo maneja
                        lat: latitude,
                        lng: longitude,
                        heading: heading,
                        speed: speed,
                        lastUpdated: Date.now()
                    } as any;
                }
                return v;
            }));

            // La sincronización con la nube (SyncModule) se encargará de subir estos cambios 
            // si el auto-sync está activado o en el siguiente ciclo.
        },
        (error) => {
            console.error("GPS Error:", error);
        },
        options
    );
  };

  const stopTracking = () => {
    if (watchIdRef.current !== null) {
        navigator.geolocation.clearWatch(watchIdRef.current);
        watchIdRef.current = null;
    }
    setActiveVehicleId(null);
    alert("⏹️ Transmisión de ubicación detenida.");
  };

  const saveVehicle = () => {
    if (!editingVehicle?.plate || !editingVehicle?.description) return alert("Completa los datos.");
    setVehicles(prev => {
      const exists = prev.find(v => v.id === editingVehicle.id);
      if (exists) return prev.map(v => v.id === editingVehicle.id ? { ...v, ...editingVehicle } as Vehicle : v);
      return [...prev, { ...editingVehicle, id: editingVehicle.id || Date.now().toString(), currentLoad: 0, inventory: [], fuelHistory: [] } as Vehicle];
    });
    setEditingVehicle(null);
  };

  if (editingVehicle) {
    return (
      <div className="h-full bg-sky-50 animate-fadeIn overflow-y-auto no-scrollbar pb-32">
        <ModuleHeader title={editingVehicle.id ? "Editar Unidad" : "Nueva Unidad"} onBack={() => setEditingVehicle(null)} />
        <div className="px-6 space-y-5">
           <input className="w-full bg-white p-5 rounded-[2rem] shadow-sm outline-none font-bold text-sky-900 text-sm focus:ring-2 ring-sky-300" placeholder="Placa / Identificador" value={editingVehicle.plate || ''} onChange={e => setEditingVehicle({...editingVehicle, plate: e.target.value})}/>
           <input className="w-full bg-white p-5 rounded-[2rem] shadow-sm outline-none font-bold text-sky-900 text-sm focus:ring-2 ring-sky-300" placeholder="Descripción (Ej: Nissan Blanca)" value={editingVehicle.description || ''} onChange={e => setEditingVehicle({...editingVehicle, description: e.target.value})}/>
           <div className="bg-white p-5 rounded-[2rem] shadow-sm">
              <label className="text-[10px] font-black text-sky-400 uppercase mb-2 block">Capacidad de Carga</label>
              <input type="number" className="w-full bg-slate-50 p-4 rounded-2xl outline-none font-black text-sky-600 text-2xl text-center" value={editingVehicle.loadCapacity || ''} onChange={e => setEditingVehicle({...editingVehicle, loadCapacity: Number(e.target.value)})}/>
           </div>

           <ActionButton onClick={saveVehicle}>Guardar Unidad</ActionButton>

           {editingVehicle.id && (
             <button onClick={() => { if (confirm("¿Eliminar unidad?")) { deleteVehicle(editingVehicle.id!); setEditingVehicle(null); } }} className="w-full py-4 text-rose-500 font-black uppercase text-[10px] tracking-widest bg-rose-50 rounded-[2rem] border border-rose-100 shadow-sm active:scale-95 transition-all">
                Eliminar Unidad
             </button>
           )}
        </div>
      </div>
    );
  }

  return (
    <div className="h-full bg-sky-50 overflow-y-auto no-scrollbar pb-24 relative flex flex-col">
      <ModuleHeader title="Centro Logístico" onBack={onBack} />

      {/* View Switcher */}
      <div className="px-6 flex gap-2 mb-4 shrink-0">
        <button onClick={() => setViewMode('list')} className={`flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${viewMode === 'list' ? 'bg-indigo-600 text-white shadow-lg' : 'bg-white text-slate-400'}`}>
            <i className="fas fa-list mr-2"></i> Flota
        </button>
        <button onClick={() => setViewMode('map')} className={`flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${viewMode === 'map' ? 'bg-indigo-600 text-white shadow-lg' : 'bg-white text-slate-400'}`}>
            <i className="fas fa-map-location-dot mr-2"></i> Mapa Real
        </button>
      </div>

      {viewMode === 'list' ? (
          <div className="px-6 space-y-6 flex-1 overflow-y-auto no-scrollbar pb-32">
            {/* PANEL DE MODO CHOFER */}
            <div className="bg-indigo-600 p-6 rounded-[2.5rem] text-white shadow-xl shadow-indigo-200">
                <div className="flex items-center gap-4 mb-4">
                    <div className="w-12 h-12 bg-white/20 rounded-2xl flex items-center justify-center text-2xl">
                        <i className="fas fa-satellite-dish"></i>
                    </div>
                    <div>
                        <h3 className="font-black text-lg">Modo Chofer</h3>
                        <p className="text-[10px] opacity-70 font-bold uppercase tracking-wide">Transmisión GPS</p>
                    </div>
                </div>

                {activeVehicleId ? (
                    <div className="bg-white/10 p-4 rounded-2xl border border-white/20">
                        <p className="text-xs font-bold mb-2">Conduciendo: <span className="text-amber-300 uppercase">{vehicles.find(v => v.id === activeVehicleId)?.plate}</span></p>
                        <button onClick={stopTracking} className="w-full py-3 bg-red-500 rounded-xl font-black uppercase text-[10px] shadow-lg active:scale-95 transition-all">
                            Detener Transmisión
                        </button>
                    </div>
                ) : (
                    <div className="bg-white/10 p-4 rounded-2xl border border-white/20">
                        <p className="text-[10px] opacity-70 mb-3">Selecciona la unidad que estás conduciendo hoy para activar el rastreo en tiempo real.</p>
                        <select 
                            className="w-full bg-white text-indigo-900 p-3 rounded-xl font-bold text-xs outline-none mb-3"
                            onChange={(e) => { if(e.target.value) startTracking(e.target.value); }}
                            value=""
                        >
                            <option value="" disabled>Seleccionar Unidad...</option>
                            {vehicles.map(v => (
                                <option key={v.id} value={v.id}>{v.plate} - {v.description}</option>
                            ))}
                        </select>
                    </div>
                )}
            </div>

            {vehicles.map(v => {
                const isActive = activeVehicleId === v.id;
                const hasLocation = (v as any).lat && (v as any).lng;

                return (
                    <RoundedCard key={v.id} className={`relative overflow-hidden border-none shadow-xl bg-white group p-0 ${isActive ? 'ring-2 ring-indigo-500' : ''}`}>
                        {isActive && <div className="absolute top-0 right-0 bg-indigo-500 text-white text-[8px] font-black px-3 py-1 rounded-bl-xl z-10">TRANSMITIENDO</div>}
                        <div className="p-6 pb-4">
                            <div className="flex justify-between items-start mb-6">
                                <div className="flex gap-4">
                                <div className="w-14 h-14 bg-gradient-to-br from-sky-700 to-slate-800 text-white rounded-[1.5rem] flex items-center justify-center text-2xl shadow-lg shadow-slate-300">
                                    <i className="fas fa-truck-pickup"></i>
                                </div>
                                <div>
                                    <span className="text-[10px] font-black text-sky-400 uppercase tracking-widest leading-none block mb-1">{v.plate}</span>
                                    <h3 className="text-xl font-black text-sky-900 leading-tight">{v.description}</h3>
                                    {hasLocation && <span className="text-[8px] text-emerald-500 font-bold flex items-center gap-1 mt-1"><i className="fas fa-signal"></i> GPS Activo</span>}
                                </div>
                                </div>
                                <div className="flex gap-2">
                                <button onClick={() => setFuelVehicleId(v.id)} className="w-10 h-10 bg-amber-50 text-amber-500 rounded-full flex items-center justify-center hover:bg-amber-100 transition-colors shadow-sm"><i className="fas fa-gas-pump"></i></button>
                                <button onClick={() => setEditingVehicle(v)} className="w-10 h-10 bg-sky-50 text-sky-400 rounded-full flex items-center justify-center hover:bg-sky-100 transition-colors"><i className="fas fa-pen"></i></button>
                                </div>
                            </div>

                            <div className="flex items-end justify-between mb-4">
                                <div>
                                <p className="text-[10px] font-black text-sky-400 uppercase tracking-tighter mb-1">Carga Actual</p>
                                <p className="text-4xl font-black text-sky-600 tracking-tighter">{v.currentLoad} <span className="text-xs font-bold text-sky-300 ml-1">/{v.loadCapacity}</span></p>
                                </div>
                                <button onClick={() => setLoadingVehicleId(v.id)} className="px-6 py-3 bg-sky-600 text-white rounded-2xl font-black text-[10px] uppercase shadow-lg shadow-sky-200 active:scale-95 transition-all flex items-center gap-2">
                                <i className="fas fa-boxes-packing"></i> Cargar
                                </button>
                            </div>

                            {/* Inventory Tags */}
                            <div className="flex flex-wrap gap-2 mb-5">
                                {(!v.inventory || v.inventory.length === 0) ? (
                                <span className="text-[9px] font-bold text-slate-300 italic px-2">Unidad vacía</span>
                                ) : (
                                v.inventory.map(item => (
                                    <span key={item.id} className="bg-sky-50 text-sky-700 text-[8px] font-bold px-2 py-1 rounded-lg border border-sky-100 uppercase tracking-tight">
                                    {item.quantity}x {item.name.split(' ')[0]}
                                    </span>
                                ))
                                )}
                            </div>

                            {/* Gradient Progress Bar */}
                            <div className="w-full bg-slate-100 h-2.5 rounded-full overflow-hidden">
                                <div className="h-full bg-gradient-to-r from-sky-400 to-indigo-500 transition-all duration-700 ease-out shadow-[0_0_10px_rgba(99,102,241,0.5)]" style={{ width: `${Math.min((v.currentLoad/v.loadCapacity)*100, 100)}%` }}></div>
                            </div>
                        </div>
                    </RoundedCard>
                );
            })}

            <button onClick={() => setEditingVehicle({})} className="w-full py-7 border-2 border-dashed border-sky-200 rounded-[2.5rem] text-sky-400 font-black text-sm uppercase hover:bg-white hover:text-sky-600 transition-all flex items-center justify-center gap-2">
            <i className="fas fa-plus"></i> Nueva Unidad
            </button>
          </div>
      ) : (
          <div className="flex-1 px-4 pb-6 animate-fadeIn relative h-full">
             <div className="absolute top-0 left-4 z-10 bg-white/90 backdrop-blur px-3 py-1 rounded-full text-[9px] font-bold text-slate-500 shadow-sm border border-white/50">
                Mostrando solo unidades con GPS activo
             </div>
             <LogisticsMap customers={customers} vehicles={vehicles} orders={orders} activeVehicleId={activeVehicleId} />
          </div>
      )}

      {loadingVehicleId && <LoadingModal vehicleId={loadingVehicleId} onClose={() => setLoadingVehicleId(null)} />}
      {fuelVehicleId && <FuelModal vehicleId={fuelVehicleId} onClose={() => setFuelVehicleId(null)} />}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader } from './ui/Cards';

const TRANSITION_TIME = 15; 
const STORAGE_KEY = 'aqua_production_state_v4'; 

// --- SVG COMPONENTS FOR VISUALIZATION ---
const TankVisual = ({ type, isActive, level, label }: { type: 'multi' | 'carbon' | 'softener', isActive: boolean, level: number, label: string }) => {
    const color = type === 'multi' ? 'text-sky-400' : type === 'carbon' ? 'text-slate-400' : 'text-indigo-400';
    const activeGlow = isActive ? 'drop-shadow-[0_0_15px_rgba(255,255,255,0.6)]' : '';

    return (
        <div className={`flex flex-col items-center gap-2 transition-all duration-500 ${isActive ? 'scale-110 opacity-100' : 'scale-95 opacity-50'}`}>
            <div className={`relative w-20 h-32 border-2 rounded-2xl bg-slate-800 overflow-hidden ${isActive ? 'border-white' : 'border-slate-600'} ${activeGlow}`}>
                {/* Media Level */}
                <div className={`absolute bottom-0 w-full transition-all duration-1000 ${type === 'multi' ? 'bg-amber-900/40' : type === 'carbon' ? 'bg-black/60' : 'bg-orange-300/40'}`} style={{ height: '70%' }}></div>

                {/* Water Flow Animation (Only if active) */}
                {isActive && (
                    <div className="absolute inset-0 bg-blue-500/20 animate-pulse">
                        <div className="w-full h-full flex justify-center space-x-4">
                            <div className="w-1 h-full bg-white/20 animate-[slideUp_2s_infinite_linear]"></div>
                            <div className="w-1 h-full bg-white/20 animate-[slideUp_1.5s_infinite_linear]"></div>
                        </div>
                    </div>
                )}

                {/* Valve Head */}
                <div className="absolute top-0 left-1/2 -translate-x-1/2 w-12 h-6 bg-slate-500 rounded-b-lg border-b border-white/20"></div>

                {/* Status Indicator */}
                <div className={`absolute bottom-2 right-2 w-3 h-3 rounded-full ${isActive ? 'bg-green-500 animate-ping' : 'bg-slate-700'}`}></div>
            </div>
            <span className={`text-[9px] font-black uppercase tracking-widest ${isActive ? 'text-white' : 'text-slate-500'}`}>{label}</span>
        </div>
    );
};

export const ProductionModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const { productionConfig, setProductionConfig } = useERPData();

  const [mode, setMode] = useState<'backwash' | 'regen'>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved).mode : 'backwash';
  });

  const [currentStepIdx, setCurrentStepIdx] = useState(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved).currentStepIdx : 0;
  });

  const [isRunning, setIsRunning] = useState(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved).isRunning : false;
  });

  const [isTransitioning, setIsTransitioning] = useState(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved).isTransitioning : false;
  });

  const [endTime, setEndTime] = useState<number | null>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved).endTime : null;
  });

  const [timeLeft, setTimeLeft] = useState(0);

  // Logic for Hardness Planner
  const [hardnessGPG, setHardnessGPG] = useState(10); 
  const [resinFt3, setResinFt3] = useState(productionConfig.softenerVolumeFt3 || 1.5);
  const [batchInput, setBatchInput] = useState(0);

  const wakeLock = useRef<WakeLockSentinel | null>(null);

  const currentSequence = mode === 'backwash' ? productionConfig.backwashSequence : productionConfig.regenerationSequence;

  // Identify active tank based on stage name
  const currentStageName = currentSequence[currentStepIdx]?.stage || '';
  const activeTank = currentStageName.includes('Multicama') ? 'multi' 
                   : currentStageName.includes('Carbón') ? 'carbon' 
                   : currentStageName.includes('Suavizador') ? 'softener' 
                   : 'none';

  // Capacity Calcs
  const totalCapacityLiters = (resinFt3 * 30000 / (hardnessGPG || 1)) * 3.785;
  const currentUsage = productionConfig.currentUsageLiters || 0;
  const percentageUsed = Math.min((currentUsage / totalCapacityLiters) * 100, 100);
  const remainingLiters = Math.max(0, totalCapacityLiters - currentUsage);

  // Persistence & Timer Logic (Same as before but refined)
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      if (parsed.isRunning && parsed.endTime) {
        const now = Date.now();
        const diff = Math.ceil((parsed.endTime - now) / 1000);
        if (diff > 0) {
          setTimeLeft(diff);
          requestWakeLock();
        } else {
          setTimeLeft(0);
        }
      } else {
        const defaultTime = parsed.isTransitioning ? TRANSITION_TIME : currentSequence[parsed.currentStepIdx]?.time || 0;
        setTimeLeft(parsed.savedTimeLeft || defaultTime);
      }
    } else {
      setTimeLeft(currentSequence[0]?.time || 0);
    }
  }, []); // Run once on mount

  // Sync Resin Config
  useEffect(() => {
    if (Math.abs(resinFt3 - (productionConfig.softenerVolumeFt3 || 0)) > 0.1) {
        setProductionConfig({ ...productionConfig, softenerVolumeFt3: resinFt3 });
    }
  }, [resinFt3]);

  // Save State
  useEffect(() => {
    const stateToSave = { mode, currentStepIdx, endTime, isRunning, isTransitioning, savedTimeLeft: timeLeft };
    localStorage.setItem(STORAGE_KEY, JSON.stringify(stateToSave));
  }, [mode, currentStepIdx, endTime, isRunning, timeLeft, isTransitioning]);

  const requestWakeLock = async () => {
    try { if ('wakeLock' in navigator && !wakeLock.current) wakeLock.current = await navigator.wakeLock.request('screen'); } 
    catch (err) { console.warn(err); }
  };

  const releaseWakeLock = async () => {
    if (wakeLock.current) { await wakeLock.current.release(); wakeLock.current = null; }
  };

  // Timer Tick
  useEffect(() => {
    let interval: any;
    if (isRunning && endTime) {
      requestWakeLock(); 
      interval = setInterval(() => {
        const now = Date.now();
        const remaining = Math.ceil((endTime - now) / 1000);

        if (remaining <= 0) {
          if (isTransitioning) {
            setIsTransitioning(false);
            const nextIdx = currentStepIdx + 1;
            setCurrentStepIdx(nextIdx);
            const nextStepTime = currentSequence[nextIdx]?.time || 0;
            const newEndTime = Date.now() + nextStepTime * 1000;
            setEndTime(newEndTime);
            setTimeLeft(nextStepTime);
          } else {
            if (navigator.vibrate) navigator.vibrate([1000, 500, 1000]); 
            if (currentStepIdx < currentSequence.length - 1) {
              setIsTransitioning(true);
              const newEndTime = Date.now() + TRANSITION_TIME * 1000;
              setEndTime(newEndTime);
              setTimeLeft(TRANSITION_TIME);
            } else {
              // FINISH
              setIsRunning(false);
              setEndTime(null);
              releaseWakeLock();
              localStorage.removeItem(STORAGE_KEY);
              if (mode === 'regen') {
                  setProductionConfig({ ...productionConfig, currentUsageLiters: 0, lastRegenDate: Date.now() });
                  alert("REGENERACIÓN COMPLETADA.\nContador de uso reiniciado.");
              } else {
                  alert("RETROLAVADO FINALIZADO");
              }
            }
          }
        } else {
          setTimeLeft(remaining);
        }
      }, 1000);
    } else {
      releaseWakeLock();
    }
    return () => clearInterval(interval);
  }, [isRunning, endTime, currentStepIdx, currentSequence, mode, isTransitioning]);

  const startSequence = () => {
    const duration = timeLeft > 0 ? timeLeft : (isTransitioning ? TRANSITION_TIME : currentSequence[currentStepIdx].time);
    setEndTime(Date.now() + duration * 1000);
    setIsRunning(true);
  };

  const handleAddBatch = () => {
    if (batchInput <= 0) return;
    setProductionConfig({ ...productionConfig, currentUsageLiters: (productionConfig.currentUsageLiters || 0) + (batchInput * 20) });
    setBatchInput(0);
  };

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s.toString().padStart(2, '0')}`;
  };

  return (
    <div className="px-6 py-8 animate-fadeIn h-full bg-slate-900 overflow-y-auto pb-24 no-scrollbar text-white">
      <div className="flex items-center gap-4 mb-6">
        <button onClick={onBack} className="w-12 h-12 bg-white/10 rounded-2xl flex items-center justify-center active:scale-90 transition-transform text-white">
          <i className="fas fa-arrow-left"></i>
        </button>
        <div>
            <h2 className="text-2xl font-black tracking-tight leading-none">Control Planta</h2>
            <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Panel de Operaciones</p>
        </div>
      </div>

      <div className="space-y-8">

        {/* --- SCHEMATIC VIEW --- */}
        <div className="bg-slate-950 p-6 rounded-[2.5rem] shadow-2xl border border-slate-800 relative overflow-hidden">
            {/* Piping Background (Static Lines) */}
            <div className="absolute top-16 left-0 w-full h-2 bg-slate-800 z-0"></div>

            <div className="flex justify-between items-end relative z-10">
                <TankVisual type="multi" isActive={isRunning && activeTank === 'multi'} level={80} label="Multicama" />
                <TankVisual type="carbon" isActive={isRunning && activeTank === 'carbon'} level={80} label="C. Activado" />
                <TankVisual type="softener" isActive={isRunning && activeTank === 'softener'} level={80} label="Suavizador" />
            </div>

            {/* Active Flow Status */}
            <div className="mt-6 flex items-center justify-between bg-white/5 p-3 rounded-2xl border border-white/5">
                <div className="flex items-center gap-3">
                    <div className={`w-3 h-3 rounded-full ${isRunning ? 'bg-green-500 animate-pulse' : 'bg-red-500'}`}></div>
                    <span className="text-[9px] font-bold uppercase tracking-widest text-slate-400">
                        {isRunning ? (isTransitioning ? 'CAMBIO DE VALVULA...' : `PROCESO: ${currentStageName.toUpperCase()}`) : 'SISTEMA EN ESPERA'}
                    </span>
                </div>
                {isRunning && <i className="fas fa-gear animate-spin text-slate-500"></i>}
            </div>
        </div>

        {/* --- MAIN CONTROLS --- */}
        {!isRunning ? (
            <div className="space-y-6">
                {/* Mode Selector */}
                <div className="flex bg-slate-800 p-1.5 rounded-[2rem] shadow-inner border border-slate-700">
                    <button onClick={() => { setMode('backwash'); setCurrentStepIdx(0); setTimeLeft(productionConfig.backwashSequence[0].time); }} className={`flex-1 py-4 rounded-[1.8rem] text-[10px] font-black uppercase tracking-widest transition-all ${mode === 'backwash' ? 'bg-sky-600 text-white shadow-lg' : 'text-slate-400'}`}>
                        Retrolavado
                    </button>
                    <button onClick={() => { setMode('regen'); setCurrentStepIdx(0); setTimeLeft(productionConfig.regenerationSequence[0].time); }} className={`flex-1 py-4 rounded-[1.8rem] text-[10px] font-black uppercase tracking-widest transition-all ${mode === 'regen' ? 'bg-amber-600 text-white shadow-lg' : 'text-slate-400'}`}>
                        Regeneración
                    </button>
                </div>

                {/* Hardness & Capacity Dashboard */}
                <div className="bg-gradient-to-br from-indigo-900 to-slate-900 p-6 rounded-[2.5rem] border border-indigo-500/30 relative overflow-hidden">
                    <div className="flex justify-between items-start mb-6">
                        <div>
                            <h3 className="text-sm font-black text-indigo-300 uppercase tracking-widest">Vida Útil Resina</h3>
                            <p className="text-[9px] text-white/50 mt-1">Basado en volumen procesado</p>
                        </div>
                        <div className="text-right">
                            <p className="text-2xl font-black text-white">{Math.round(remainingLiters).toLocaleString()}</p>
                            <p className="text-[8px] font-bold uppercase text-indigo-400">Litros Restantes</p>
                        </div>
                    </div>

                    {/* Progress Bar */}
                    <div className="w-full bg-black/40 h-4 rounded-full overflow-hidden mb-6 border border-white/5">
                        <div 
                            className={`h-full transition-all duration-700 ${percentageUsed > 90 ? 'bg-red-500' : percentageUsed > 75 ? 'bg-amber-500' : 'bg-emerald-500'}`} 
                            style={{ width: `${percentageUsed}%` }}
                        ></div>
                    </div>

                    {/* Inputs */}
                    <div className="grid grid-cols-2 gap-4 mb-4">
                        <div className="bg-white/5 p-3 rounded-2xl">
                            <label className="text-[8px] font-bold text-slate-400 uppercase block mb-1">Dureza (GPG)</label>
                            <div className="flex items-center justify-between">
                                <button onClick={() => setHardnessGPG(Math.max(1, hardnessGPG - 1))} className="w-6 h-6 bg-white/10 rounded text-xs font-bold">-</button>
                                <span className="font-black">{hardnessGPG}</span>
                                <button onClick={() => setHardnessGPG(hardnessGPG + 1)} className="w-6 h-6 bg-white/10 rounded text-xs font-bold">+</button>
                            </div>
                        </div>
                        <div className="bg-white/5 p-3 rounded-2xl">
                            <label className="text-[8px] font-bold text-slate-400 uppercase block mb-1">Prod. Lote</label>
                            <div className="flex items-center gap-2">
                                <input 
                                    type="number" 
                                    className="w-full bg-transparent text-right font-black outline-none border-b border-white/20"
                                    placeholder="Garrafones"
                                    value={batchInput || ''}
                                    onChange={e => setBatchInput(parseInt(e.target.value) || 0)}
                                />
                                <button onClick={handleAddBatch} className="text-indigo-400"><i className="fas fa-check"></i></button>
                            </div>
                        </div>
                    </div>

                    <button onClick={startSequence} className={`w-full py-5 rounded-[2rem] font-black text-sm uppercase tracking-widest shadow-xl active:scale-95 transition-all ${mode === 'regen' ? 'bg-amber-500 text-black shadow-amber-500/20' : 'bg-sky-500 text-white shadow-sky-500/20'}`}>
                        INICIAR {mode === 'backwash' ? 'RETROLAVADO' : 'REGENERACIÓN'}
                    </button>
                </div>
            </div>
        ) : (
            // --- RUNNING VIEW ---
            <div className="relative overflow-hidden rounded-[2.5rem] bg-slate-800 shadow-2xl border border-slate-700">
                <div className={`absolute top-0 left-0 h-1 bg-gradient-to-r from-transparent via-white to-transparent opacity-50 w-full animate-[shimmer_2s_infinite]`}></div>

                <div className="p-8 text-center relative z-10">
                    <div className={`inline-block px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest mb-6 border ${isTransitioning ? 'bg-violet-500/20 border-violet-500 text-violet-300 animate-pulse' : 'bg-emerald-500/20 border-emerald-500 text-emerald-400'}`}>
                        {isTransitioning ? 'AJUSTANDO VÁLVULAS' : `PASO ${currentStepIdx + 1} DE ${currentSequence.length}`}
                    </div>

                    <h3 className="text-2xl font-black text-white mb-2 leading-none">
                        {isTransitioning ? 'ESPERA...' : currentSequence[currentStepIdx]?.process}
                    </h3>

                    <div className="text-[80px] font-mono font-black mb-8 tracking-tighter text-white drop-shadow-2xl leading-none">
                        {formatTime(timeLeft)}
                    </div>

                    <button onClick={() => setIsRunning(false)} className="w-full bg-red-500/20 border border-red-500/50 text-red-400 py-4 rounded-[2rem] font-black text-xs uppercase tracking-widest active:scale-95 transition-all hover:bg-red-500/30">
                        DETENER EMERGENCIA
                    </button>
                </div>

                {/* Progress Bar Bottom */}
                <div className="absolute bottom-0 left-0 h-3 bg-black/50 w-full">
                    <div 
                        className={`h-full transition-all duration-1000 ease-linear ${isTransitioning ? 'bg-violet-500' : 'bg-emerald-500'}`} 
                        style={{ width: `${isTransitioning ? ((TRANSITION_TIME - timeLeft)/TRANSITION_TIME)*100 : ((currentSequence[currentStepIdx].time - timeLeft)/currentSequence[currentStepIdx].time)*100}%` }}
                    ></div>
                </div>
            </div>
        )}
      </div>

      <style>{`
        @keyframes slideUp {
            from { transform: translateY(100%); }
            to { transform: translateY(-100%); }
        }
      `}</style>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';
import { QualityRecord } from '../types';

const SENSORY_OPTIONS = {
  color: ['Incoloro', 'Cristalino', 'Amarillento', 'Turbio'],
  sabor: ['Insípido', 'Clorado', 'Metálico', 'Dulce'],
  turbiedad: ['Nula', 'Ligera', 'Media', 'Alta']
};

// NORMATIVA (Based roughly on NOM-201-SSA1-2015 & NOM-127)
const NORMS = {
    ph: { min: 6.5, max: 8.5, ideal: 7.0 },
    tds: { min: 0, max: 500, ideal: 50 }, // Purified often <100
    cloro: { min: 0.2, max: 1.5, ideal: 0.5 }, // Residual free chlorine
    dureza: { min: 0, max: 200, ideal: 0 } // Ideally soft
};

export const QualityModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const { qualityRecords, addQualityRecord } = useERPData();
  const [activeTab, setActiveTab] = useState<'new' | 'history'>('new');
  const [newRecord, setNewRecord] = useState<Partial<QualityRecord>>({
    type: 'Producto', // Default to finished product
    ph: 7.0,
    cloro: 0.5,
    tds: 40,
    dureza: 0,
    color: 'Cristalino',
    sabor: 'Insípido',
    turbiedad: 'Nula'
  });

  // --- VALIDATION LOGIC ---
  const getStatus = (val: number, type: 'ph' | 'tds' | 'cloro' | 'dureza') => {
      const norm = NORMS[type];
      if (val >= norm.min && val <= norm.max) return 'good';
      // Warning buffer (10%)
      const buffer = (norm.max - norm.min) * 0.1;
      if (val >= norm.min - buffer && val <= norm.max + buffer) return 'warning';
      return 'danger';
  };

  const isBatchCertified = useMemo(() => {
      if (newRecord.type === 'Cruda') return true; // Raw water standards allow more variance usually, but keep simple

      const phStatus = getStatus(newRecord.ph || 0, 'ph');
      const tdsStatus = getStatus(newRecord.tds || 0, 'tds');
      const cloroStatus = getStatus(newRecord.cloro || 0, 'cloro');

      // Sensory Check
      const sensoryOK = newRecord.color === 'Cristalino' || newRecord.color === 'Incoloro';
      const flavorOK = newRecord.sabor === 'Insípido';

      return phStatus === 'good' && tdsStatus === 'good' && cloroStatus === 'good' && sensoryOK && flavorOK;
  }, [newRecord]);

  const handleSave = () => {
    if (!isBatchCertified && !confirm("⚠️ ADVERTENCIA: Los parámetros están fuera de norma. ¿Guardar de todos modos?")) return;

    addQualityRecord(newRecord as any);
    alert(isBatchCertified ? "✅ Lote Certificado y Registrado." : "⚠️ Bitácora guardada con observaciones.");
    setActiveTab('history');
  };

  // --- UI COMPONENTS ---
  const SmartGauge = ({ label, value, onChange, type, unit, step }: any) => {
      const status = getStatus(value, type);
      const norm = NORMS[type as keyof typeof NORMS];

      // Colors
      const colorClass = status === 'good' ? 'text-emerald-500' : status === 'warning' ? 'text-amber-500' : 'text-rose-500';
      const bgClass = status === 'good' ? 'bg-emerald-50 border-emerald-100' : status === 'warning' ? 'bg-amber-50 border-amber-100' : 'bg-rose-50 border-rose-100';
      const barColor = status === 'good' ? 'bg-emerald-400' : status === 'warning' ? 'bg-amber-400' : 'bg-rose-400';

      // Percentage for bar (Clamped 0-100 relative to max norm * 1.5)
      const maxDisplay = norm.max * 1.5;
      const percent = Math.min((value / maxDisplay) * 100, 100);

      return (
        <div className={`p-5 rounded-[2rem] border transition-all ${bgClass}`}>
            <div className="flex justify-between items-end mb-2">
                <div>
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">{label}</label>
                    <div className="flex items-center gap-2">
                        <input 
                            type="number" 
                            step={step}
                            className={`text-3xl font-black bg-transparent outline-none w-24 ${colorClass}`}
                            value={value}
                            onChange={(e) => onChange(parseFloat(e.target.value) || 0)}
                        />
                        <span className="text-[10px] font-bold text-slate-400 uppercase">{unit}</span>
                    </div>
                </div>
                <div className="text-right">
                    <span className={`text-[9px] font-bold uppercase px-2 py-1 rounded-lg ${status === 'good' ? 'bg-white text-emerald-500' : 'bg-white text-rose-500'}`}>
                        {status === 'good' ? 'EN NORMA' : 'REVISAR'}
                    </span>
                </div>
            </div>

            {/* Visual Gauge Bar */}
            <div className="relative h-3 bg-white rounded-full overflow-hidden shadow-inner">
                <div className={`absolute top-0 left-0 h-full ${barColor} transition-all duration-500 rounded-full`} style={{ width: `${percent}%` }}></div>
                {/* Norm Markers */}
                <div className="absolute top-0 bottom-0 w-0.5 bg-slate-300 opacity-50" style={{ left: `${(norm.min / maxDisplay)*100}%` }}></div>
                <div className="absolute top-0 bottom-0 w-0.5 bg-slate-300 opacity-50" style={{ left: `${(norm.max / maxDisplay)*100}%` }}></div>
            </div>
            <div className="flex justify-between text-[8px] text-slate-400 font-bold mt-1 px-1">
                <span>0</span>
                <span>Rango: {norm.min}-{norm.max}</span>
                <span>{maxDisplay}</span>
            </div>
        </div>
      );
  };

  const SensoryButton = ({ label, options, current, onSelect }: any) => (
    <div>
        <label className="text-[9px] font-black text-slate-400 uppercase ml-2 mb-2 block">{label}</label>
        <div className="flex flex-wrap gap-2">
            {options.map((opt: string) => {
                const isSelected = current === opt;
                // Highlight logic for "Bad" sensory values
                const isBad = (label === 'Color' && opt !== 'Cristalino' && opt !== 'Incoloro') || 
                              (label === 'Sabor' && opt !== 'Insípido') ||
                              (label === 'Turbiedad' && opt !== 'Nula');

                return (
                    <button
                        key={opt}
                        onClick={() => onSelect(opt)}
                        className={`px-3 py-2 rounded-xl text-[9px] font-black uppercase transition-all border ${
                            isSelected 
                                ? (isBad ? 'bg-rose-500 text-white border-rose-500 shadow-md' : 'bg-teal-500 text-white border-teal-500 shadow-md')
                                : 'bg-white text-slate-400 border-slate-100 hover:border-teal-200'
                        }`}
                    >
                        {opt}
                    </button>
                );
            })}
        </div>
    </div>
  );

  return (
    <div className="h-full bg-slate-50 flex flex-col animate-fadeIn overflow-hidden pb-24">
      <ModuleHeader title="Laboratorio de Calidad" onBack={onBack} />

      <div className="px-6 flex gap-2 mb-4 shrink-0">
        <button onClick={() => setActiveTab('new')} className={`flex-1 py-3.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'new' ? 'bg-teal-600 text-white shadow-lg' : 'bg-white text-slate-400'}`}>Nueva Muestra</button>
        <button onClick={() => setActiveTab('history')} className={`flex-1 py-3.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'history' ? 'bg-teal-600 text-white shadow-lg' : 'bg-white text-slate-400'}`}>Bitácora</button>
      </div>

      <div className="flex-1 overflow-y-auto px-6 space-y-6 no-scrollbar pb-10">
        {activeTab === 'new' ? (
          <div className="space-y-6 animate-fadeIn">

            {/* Certification Status Header */}
            <div className={`p-5 rounded-[2.5rem] shadow-sm flex items-center justify-between transition-colors duration-500 ${isBatchCertified ? 'bg-emerald-500 text-white shadow-emerald-200' : 'bg-white text-slate-500 border border-slate-100'}`}>
                <div>
                    <p className="text-[10px] font-black uppercase opacity-80 tracking-widest mb-1">Estado del Lote</p>
                    <h3 className="text-xl font-black">{isBatchCertified ? 'CALIDAD CERTIFICADA' : 'REVISIÓN REQUERIDA'}</h3>
                </div>
                <div className={`w-12 h-12 rounded-full flex items-center justify-center text-2xl ${isBatchCertified ? 'bg-white/20 text-white' : 'bg-slate-100 text-slate-300'}`}>
                    <i className={`fas ${isBatchCertified ? 'fa-certificate' : 'fa-triangle-exclamation'}`}></i>
                </div>
            </div>

            {/* Type Selector */}
            <div className="flex p-1.5 bg-white rounded-[2rem] shadow-sm gap-1">
              {['Cruda', 'Producto'].map(type => (
                <button 
                  key={type} 
                  onClick={() => setNewRecord({...newRecord, type: type as any})}
                  className={`flex-1 py-3 rounded-[1.5rem] text-[10px] font-black uppercase tracking-widest transition-all ${newRecord.type === type ? 'bg-slate-700 text-white shadow-md' : 'text-slate-400 hover:bg-slate-50'}`}
                >
                  Agua {type}
                </button>
              ))}
            </div>

            {/* Gauges Grid */}
            <div className="grid grid-cols-1 gap-4">
                <SmartGauge label="pH (Potencial H)" value={newRecord.ph} type="ph" unit="pH" step={0.1} onChange={(v:any) => setNewRecord({...newRecord, ph: v})} />
                <SmartGauge label="Cloro Residual" value={newRecord.cloro} type="cloro" unit="mg/L" step={0.1} onChange={(v:any) => setNewRecord({...newRecord, cloro: v})} />
                <SmartGauge label="Sólidos (TDS)" value={newRecord.tds} type="tds" unit="PPM" step={1} onChange={(v:any) => setNewRecord({...newRecord, tds: v})} />
            </div>

            {/* Sensory Section */}
            <div className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-50 space-y-5">
                <h4 className="text-xs font-black text-slate-800 uppercase border-b border-slate-50 pb-2">Análisis Organoléptico</h4>
                <SensoryButton label="Apariencia / Color" options={SENSORY_OPTIONS.color} current={newRecord.color} onSelect={(v:string) => setNewRecord({...newRecord, color: v})} />
                <SensoryButton label="Sabor" options={SENSORY_OPTIONS.sabor} current={newRecord.sabor} onSelect={(v:string) => setNewRecord({...newRecord, sabor: v})} />
                <SensoryButton label="Turbiedad" options={SENSORY_OPTIONS.turbiedad} current={newRecord.turbiedad} onSelect={(v:string) => setNewRecord({...newRecord, turbiedad: v})} />
            </div>

            <ActionButton onClick={handleSave} variant={isBatchCertified ? 'primary' : 'secondary'}>
                {isBatchCertified ? 'Registrar Lote Correcto' : 'Registrar Incidencia'}
            </ActionButton>
          </div>
        ) : (
          <div className="space-y-4 animate-fadeIn">
            {qualityRecords.length === 0 ? (
              <div className="text-center py-20 text-slate-300 italic flex flex-col items-center gap-4">
                <i className="fas fa-microscope text-5xl opacity-20"></i>
                Sin registros en bitácora.
              </div>
            ) : (
              qualityRecords.slice().reverse().map(r => {
                  // Quick check for status
                  const isOK = r.ph >= NORMS.ph.min && r.ph <= NORMS.ph.max && r.cloro >= NORMS.cloro.min && r.cloro <= NORMS.cloro.max;

                  return (
                    <RoundedCard key={r.id} className="p-0 border-none shadow-sm relative overflow-hidden group">
                      <div className={`h-2 w-full ${isOK ? 'bg-emerald-500' : 'bg-amber-500'}`}></div>
                      <div className="p-5">
                          <div className="flex justify-between items-start mb-4">
                            <div>
                              <div className="flex items-center gap-2">
                                  <h4 className="font-black text-slate-800 text-sm">Agua {r.type}</h4>
                                  {!isOK && <i className="fas fa-triangle-exclamation text-amber-500 text-xs"></i>}
                              </div>
                              <p className="text-[10px] text-slate-400 font-bold uppercase">{new Date(r.timestamp).toLocaleString()}</p>
                            </div>
                            <span className="text-[9px] font-black text-slate-300 uppercase tracking-widest">{r.id}</span>
                          </div>

                          <div className="flex justify-between text-center divide-x divide-slate-100">
                             <div className="px-2 flex-1">
                                <p className="text-[8px] font-black uppercase text-slate-400">pH</p>
                                <p className={`text-sm font-black ${r.ph < 6.5 || r.ph > 8.5 ? 'text-rose-500' : 'text-slate-700'}`}>{r.ph}</p>
                             </div>
                             <div className="px-2 flex-1">
                                <p className="text-[8px] font-black uppercase text-slate-400">Cloro</p>
                                <p className={`text-sm font-black ${r.cloro < 0.2 || r.cloro > 1.5 ? 'text-rose-500' : 'text-slate-700'}`}>{r.cloro}</p>
                             </div>
                             <div className="px-2 flex-1">
                                <p className="text-[8px] font-black uppercase text-slate-400">TDS</p>
                                <p className="text-sm font-black text-slate-700">{r.tds}</p>
                             </div>
                          </div>
                      </div>
                    </RoundedCard>
                  );
              })
            )}
          </div>
        )}
      </div>
    </div>
  );
};

