// --- SAT CATALOGS (Simplified for common use cases) ---
const REGIMENES_FISCALES = [
  { code: '601', desc: 'General de Ley Personas Morales' },
  { code: '603', desc: 'Personas Morales con Fines no Lucrativos' },
  { code: '605', desc: 'Sueldos y Salarios e Ingresos Asimilados a Salarios' },
  { code: '606', desc: 'Arrendamiento' },
  { code: '612', desc: 'Personas Físicas con Actividades Empresariales y Profesionales' },
  { code: '621', desc: 'Incorporación Fiscal' },
  { code: '626', desc: 'Régimen Simplificado de Confianza (RESICO)' },
];

const USOS_CFDI = [
  { code: 'G01', desc: 'Adquisición de mercancías' },
  { code: 'G03', desc: 'Gastos en general' },
  { code: 'S01', desc: 'Sin efectos fiscales' },
  { code: 'D01', desc: 'Honorarios médicos, dentales y gastos hospitalarios' },
];

const METODOS_PAGO = [
  { code: 'PUE', desc: 'Pago en una sola exhibición' },
  { code: 'PPD', desc: 'Pago en parcialidades o diferido' },
];

const FORMAS_PAGO = [
  { code: '01', desc: 'Efectivo' },
  { code: '03', desc: 'Transferencia electrónica de fondos' },
  { code: '04', desc: 'Tarjeta de crédito' },
  { code: '28', desc: 'Tarjeta de débito' },
  { code: '99', desc: 'Por definir' },
];

// --- HELPER: Validar RFC ---
const validateRFC = (rfc: string): boolean => {
  const rfcPattern = /^([A-ZÑ&]{3,4}) ?(?:- ?)?(\d{2}(?:0[1-9]|1[0-2])(?:0[1-9]|[12]\d|3[01])) ?(?:- ?)?([A-Z\d]{2})([A\d])$/;
  return rfcPattern.test(rfc.toUpperCase());
};

// --- SUB-COMPONENTS ---

const TaxDataForm = ({ customer, onSave, onCancel }: { customer: Customer, onSave: (profile: TaxProfile) => void, onCancel: () => void }) => {
  const [form, setForm] = useState<TaxProfile>(customer.taxInfo || {
    rfc: '',
    razonSocial: customer.name.toUpperCase(),
    regimenFiscal: '626',
    codigoPostal: '',
    usoCFDI: 'G03',
    email: ''
  });

  const handleSubmit = () => {
    if (!validateRFC(form.rfc)) return alert("El RFC no tiene un formato válido.");
    if (form.codigoPostal.length !== 5) return alert("El Código Postal debe ser de 5 dígitos.");
    if (!form.razonSocial) return alert("La Razón Social es obligatoria.");
    onSave(form);
  };

  return (
    <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-md z-[200] flex items-center justify-center p-4 animate-fadeIn">
      <div className="bg-white w-full max-w-md rounded-[2.5rem] p-6 shadow-2xl max-h-[90vh] overflow-y-auto no-scrollbar">
        <h3 className="text-xl font-black text-sky-900 mb-2">Datos Fiscales (SAT 4.0)</h3>
        <p className="text-xs text-slate-400 mb-6 font-medium">Información requerida para timbrado.</p>

        <div className="space-y-4">
          <div>
            <label className="text-[10px] font-black uppercase text-slate-400 ml-2">RFC (Sin Guiones)</label>
            <input className="w-full bg-slate-50 p-4 rounded-2xl outline-none font-bold text-sky-900 uppercase tracking-widest" value={form.rfc} onChange={e => setForm({...form, rfc: e.target.value.toUpperCase()})} placeholder="XAXX010101000" maxLength={13} />
          </div>

          <div>
            <label className="text-[10px] font-black uppercase text-slate-400 ml-2">Razón Social (Sin SA de CV)</label>
            <input className="w-full bg-slate-50 p-4 rounded-2xl outline-none font-bold text-sky-900 uppercase" value={form.razonSocial} onChange={e => setForm({...form, razonSocial: e.target.value.toUpperCase()})} placeholder="Nombre exacto Constancia" />
          </div>

          <div className="grid grid-cols-2 gap-4">
             <div>
                <label className="text-[10px] font-black uppercase text-slate-400 ml-2">C.P. Fiscal</label>
                <input type="number" className="w-full bg-slate-50 p-4 rounded-2xl outline-none font-bold text-sky-900" value={form.codigoPostal} onChange={e => setForm({...form, codigoPostal: e.target.value})} placeholder="00000" maxLength={5} />
             </div>
             <div>
                <label className="text-[10px] font-black uppercase text-slate-400 ml-2">Régimen</label>
                <select className="w-full bg-slate-50 p-4 rounded-2xl outline-none font-bold text-sky-900 text-xs appearance-none" value={form.regimenFiscal} onChange={e => setForm({...form, regimenFiscal: e.target.value})}>
                   {REGIMENES_FISCALES.map(r => <option key={r.code} value={r.code}>{r.code} - {r.desc.substring(0, 15)}...</option>)}
                </select>
             </div>
          </div>

          <div>
            <label className="text-[10px] font-black uppercase text-slate-400 ml-2">Uso CFDI</label>
            <select className="w-full bg-slate-50 p-4 rounded-2xl outline-none font-bold text-sky-900 text-xs appearance-none" value={form.usoCFDI} onChange={e => setForm({...form, usoCFDI: e.target.value})}>
                {USOS_CFDI.map(u => <option key={u.code} value={u.code}>{u.code} - {u.desc}</option>)}
            </select>
          </div>

          <div>
            <label className="text-[10px] font-black uppercase text-slate-400 ml-2">Email para envío</label>
            <input type="email" className="w-full bg-slate-50 p-4 rounded-2xl outline-none font-bold text-sky-900 lowercase" value={form.email} onChange={e => setForm({...form, email: e.target.value})} placeholder="cliente@email.com" />
          </div>
        </div>

        <div className="flex gap-3 mt-6">
           <button onClick={onCancel} className="flex-1 py-4 bg-slate-100 text-slate-400 rounded-2xl font-black uppercase text-xs">Cancelar</button>
           <button onClick={handleSubmit} className="flex-[2] py-4 bg-indigo-600 text-white rounded-2xl font-black uppercase text-xs shadow-xl shadow-indigo-200">Guardar Datos</button>
        </div>
      </div>
    </div>
  );
};

export const BillingModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const { sales, customers, saveCustomer, addInvoice, invoices, ticketConfig } = useERPData();
  const [activeTab, setActiveTab] = useState<'pending' | 'history'>('pending');
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);
  const [selectedSaleIds, setSelectedSaleIds] = useState<Set<string>>(new Set());
  const [editingTaxInfo, setEditingTaxInfo] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);

  // Group pending sales by Customer
  const pendingSales = useMemo(() => {
    return sales.filter(s => !s.invoiced && s.status !== 'cancelado');
  }, [sales]);

  const customersWithPending = useMemo(() => {
    const map = new Map<string, Customer>();
    pendingSales.forEach(s => {
        const c = customers.find(cust => cust.id === s.customerId);
        if (c) map.set(c.id, c);
    });
    return Array.from(map.values());
  }, [pendingSales, customers]);

  const salesForSelectedCustomer = useMemo(() => {
    if (!selectedCustomer) return [];
    return pendingSales.filter(s => s.customerId === selectedCustomer.id);
  }, [selectedCustomer, pendingSales]);

  const toggleSaleSelection = (id: string) => {
    const newSet = new Set(selectedSaleIds);
    if (newSet.has(id)) newSet.delete(id);
    else newSet.add(id);
    setSelectedSaleIds(newSet);
  };

  const handleGenerateInvoice = async () => {
    if (!selectedCustomer) return;
    if (selectedSaleIds.size === 0) return alert("Selecciona al menos una venta.");
    if (!selectedCustomer.taxInfo || !validateRFC(selectedCustomer.taxInfo.rfc)) {
        alert("Faltan datos fiscales válidos del cliente.");
        setEditingTaxInfo(true);
        return;
    }

    setIsProcessing(true);

    // 1. CONSTRUCT REAL CFDI 4.0 PAYLOAD
    const selectedSalesList = salesForSelectedCustomer.filter(s => selectedSaleIds.has(s.id));

    // Calculate totals
    const subtotal = selectedSalesList.reduce((acc, s) => acc + (s.total / 1.16), 0); // Assuming 16% included
    const total = selectedSalesList.reduce((acc, s) => acc + s.total, 0);
    const tax = total - subtotal;

    // Line Items (Consolidated)
    const concepts = selectedSalesList.flatMap(s => s.items.map(item => ({
        ClaveProdServ: item.satCode || '50202301', // Default Water
        Cantidad: item.quantity,
        ClaveUnidad: item.unitCode || 'H87', // Default Piece
        Unidad: 'Pieza',
        Descripcion: item.name,
        ValorUnitario: (item.price / 1.16).toFixed(2),
        Importe: ((item.quantity * item.price) / 1.16).toFixed(2),
        ObjetoImp: '02', // Si objeto de impuesto
        Impuestos: {
            Traslados: [
                { Base: ((item.quantity * item.price) / 1.16).toFixed(2), Impuesto: '002', TipoFactor: 'Tasa', TasaOCuota: '0.160000', Importe: ((item.quantity * item.price) - ((item.quantity * item.price) / 1.16)).toFixed(2) }
            ]
        }
    })));

    const cfdiPayload = {
        Version: "4.0",
        Serie: "F",
        Folio: Date.now().toString().slice(-6),
        Fecha: new Date().toISOString(),
        Sello: "", // Filled by PAC
        FormaPago: "01", // Default Cash, logic should deduce from sales paymentSplits
        NoCertificado: "", // Filled by Issuer
        Certificado: "", // Filled by Issuer
        SubTotal: subtotal.toFixed(2),
        Moneda: "MXN",
        Total: total.toFixed(2),
        TipoDeComprobante: "I",
        Exportacion: "01",
        MetodoPago: "PUE",
        LugarExpedicion: "44100", // Should come from Config
        Emisor: {
            Rfc: ticketConfig.rfc || "XAXX010101000",
            Nombre: ticketConfig.businessName,
            RegimenFiscal: "626" // Should come from Config
        },
        Receptor: {
            Rfc: selectedCustomer.taxInfo.rfc,
            Nombre: selectedCustomer.taxInfo.razonSocial,
            DomicilioFiscalReceptor: selectedCustomer.taxInfo.codigoPostal,
            RegimenFiscalReceptor: selectedCustomer.taxInfo.regimenFiscal,
            UsoCFDI: selectedCustomer.taxInfo.usoCFDI
        },
        Conceptos: concepts,
        Impuestos: {
            TotalImpuestosTrasladados: tax.toFixed(2),
            Traslados: [
                { Impuesto: "002", TipoFactor: "Tasa", TasaOCuota: "0.160000", Importe: tax.toFixed(2) }
            ]
        }
    };

    // 2. SIMULATE API CALL TO PAC (In real app, fetch(PAC_URL, body: cfdiPayload))
    // We delay to simulate network latency
    setTimeout(() => {
        // Create Local Invoice Record
        const newInvoice: Invoice = {
            uuid: `UUID-${Math.random().toString(36).substr(2, 9).toUpperCase()}-${Date.now()}`,
            internalId: cfdiPayload.Folio,
            timestamp: Date.now(),
            customerId: selectedCustomer.id,
            customerName: selectedCustomer.taxInfo!.razonSocial,
            customerRfc: selectedCustomer.taxInfo!.rfc,
            total: parseFloat(cfdiPayload.Total),
            subtotal: parseFloat(cfdiPayload.SubTotal),
            tax: parseFloat(cfdiPayload.Impuestos.TotalImpuestosTrasladados),
            status: 'Timbrada',
            relatedSalesIds: Array.from(selectedSaleIds)
        };

        addInvoice(newInvoice);

        // Export JSON for user (Proof of real data structure)
        exportJSON(cfdiPayload, `CFDI_${newInvoice.internalId}.json`);

        setIsProcessing(false);
        setSelectedCustomer(null);
        setSelectedSaleIds(new Set());
        setActiveTab('history');
        alert("✅ Factura generada y 'timbrada' exitosamente.");
    }, 2000);
  };

  const exportJSON = async (data: any, filename: string) => {
      try {
          await Filesystem.writeFile({
              path: filename,
              data: JSON.stringify(data, null, 2),
              directory: Directory.Documents,
              encoding: Encoding.UTF8
          });
          console.log("JSON exportado");
      } catch (e) {
          console.warn("No se pudo guardar archivo localmente (Web mode?)");
      }
  };

  return (
    <div className="h-full bg-slate-50 flex flex-col animate-fadeIn overflow-hidden pb-24 relative">
      <ModuleHeader title="Facturación 4.0" onBack={onBack} />

      <div className="px-6 flex gap-2 mb-4 shrink-0">
        <button onClick={() => setActiveTab('pending')} className={`flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'pending' ? 'bg-indigo-600 text-white shadow-lg' : 'bg-white text-slate-400'}`}>Por Facturar</button>
        <button onClick={() => setActiveTab('history')} className={`flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'history' ? 'bg-indigo-600 text-white shadow-lg' : 'bg-white text-slate-400'}`}>Historial</button>
      </div>

      <div className="flex-1 overflow-y-auto px-6 space-y-4 no-scrollbar pb-10">

        {/* VIEW: PENDING */}
        {activeTab === 'pending' && (
            <>
                {!selectedCustomer ? (
                    // STEP 1: SELECT CUSTOMER
                    <div className="space-y-3">
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Clientes con Ventas Pendientes</p>
                        {customersWithPending.length === 0 ? (
                            <div className="text-center py-20 opacity-40">
                                <i className="fas fa-file-invoice text-6xl mb-4 text-slate-300"></i>
                                <p className="text-xs font-black uppercase text-slate-400">Todo Facturado</p>
                            </div>
                        ) : (
                            customersWithPending.map(c => (
                                <RoundedCard key={c.id} onClick={() => setSelectedCustomer(c)} className="cursor-pointer hover:shadow-md transition-all active:scale-[0.98] border border-transparent hover:border-indigo-100">
                                    <div className="flex items-center justify-between">
                                        <div className="flex items-center gap-3">
                                            <div className="w-12 h-12 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center text-xl">
                                                <i className="fas fa-user-tie"></i>
                                            </div>
                                            <div>
                                                <h4 className="font-black text-sky-900 text-sm">{c.alias}</h4>
                                                {c.taxInfo ? (
                                                    <span className="bg-emerald-100 text-emerald-600 text-[8px] font-black px-2 py-0.5 rounded uppercase">RFC: {c.taxInfo.rfc}</span>
                                                ) : (
                                                    <span className="bg-amber-100 text-amber-600 text-[8px] font-black px-2 py-0.5 rounded uppercase">Sin Datos Fiscales</span>
                                                )}
                                            </div>
                                        </div>
                                        <i className="fas fa-chevron-right text-slate-300"></i>
                                    </div>
                                </RoundedCard>
                            ))
                        )}
                    </div>
                ) : (
                    // STEP 2: SELECT SALES
                    <div className="space-y-4 animate-slideUp">
                        {/* Customer Header */}
                        <div className="bg-white p-4 rounded-3xl shadow-sm border border-indigo-50 flex justify-between items-center">
                            <div>
                                <h3 className="font-black text-sky-900">{selectedCustomer.alias}</h3>
                                <p className="text-[9px] font-bold text-slate-400 uppercase">Selección de Tickets</p>
                            </div>
                            <button onClick={() => { setSelectedCustomer(null); setSelectedSaleIds(new Set()); }} className="w-8 h-8 bg-slate-100 text-slate-400 rounded-full flex items-center justify-center"><i className="fas fa-times"></i></button>
                        </div>

                        {/* Tax Info Check */}
                        <div onClick={() => setEditingTaxInfo(true)} className={`p-4 rounded-3xl border-2 cursor-pointer transition-all flex items-center justify-between ${selectedCustomer.taxInfo ? 'bg-emerald-50 border-emerald-100' : 'bg-amber-50 border-amber-200 animate-pulse'}`}>
                            <div className="flex items-center gap-3">
                                <i className={`fas ${selectedCustomer.taxInfo ? 'fa-check-circle text-emerald-500' : 'fa-triangle-exclamation text-amber-500'} text-xl`}></i>
                                <div>
                                    <p className={`text-[10px] font-black uppercase ${selectedCustomer.taxInfo ? 'text-emerald-700' : 'text-amber-700'}`}>Datos Fiscales</p>
                                    <p className="text-xs font-bold text-slate-600">{selectedCustomer.taxInfo?.razonSocial || 'Requerido para facturar'}</p>
                                </div>
                            </div>
                            <i className="fas fa-pen text-slate-400"></i>
                        </div>

                        {/* Sales List */}
                        <div className="space-y-2">
                            {salesForSelectedCustomer.map(s => {
                                const isSelected = selectedSaleIds.has(s.id);
                                return (
                                    <div key={s.id} onClick={() => toggleSaleSelection(s.id)} className={`p-4 rounded-2xl border-2 transition-all cursor-pointer flex items-center justify-between ${isSelected ? 'border-indigo-500 bg-indigo-50' : 'border-white bg-white shadow-sm'}`}>
                                        <div className="flex items-center gap-3">
                                            <div className={`w-5 h-5 rounded flex items-center justify-center border ${isSelected ? 'bg-indigo-500 border-indigo-500' : 'bg-white border-slate-300'}`}>
                                                {isSelected && <i className="fas fa-check text-white text-[10px]"></i>}
                                            </div>
                                            <div>
                                                <p className="text-[10px] font-black text-slate-400 uppercase">{new Date(s.timestamp).toLocaleDateString()}</p>
                                                <p className="text-xs font-bold text-slate-700">Folio: {s.id.split('-')[1]}</p>
                                            </div>
                                        </div>
                                        <span className="font-black text-sky-900">${s.total.toFixed(2)}</span>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                )}
            </>
        )}

        {/* VIEW: HISTORY */}
        {activeTab === 'history' && (
            <div className="space-y-3">
                {invoices.length === 0 ? (
                    <div className="text-center py-20 opacity-40">
                       <i className="fas fa-clock-rotate-left text-6xl mb-4 text-slate-300"></i>
                       <p className="text-xs font-black uppercase text-slate-400">Sin historial</p>
                    </div>
                ) : (
                    invoices.sort((a,b) => b.timestamp - a.timestamp).map(inv => (
                        <RoundedCard key={inv.uuid} className="border-l-4 border-l-emerald-500 py-4">
                            <div className="flex justify-between items-start mb-2">
                                <div>
                                    <p className="text-[9px] font-black text-slate-400 uppercase">Folio: {inv.internalId}</p>
                                    <h4 className="font-black text-sky-900 text-sm truncate max-w-[150px]">{inv.customerName}</h4>
                                </div>
                                <span className="bg-emerald-100 text-emerald-600 px-2 py-1 rounded text-[8px] font-black uppercase">Timbrada</span>
                            </div>
                            <div className="flex justify-between items-end">
                                <p className="text-[8px] text-slate-400 font-mono">{inv.uuid.substring(0, 15)}...</p>
                                <p className="text-lg font-black text-slate-800">${inv.total.toFixed(2)}</p>
                            </div>
                            <div className="mt-3 flex gap-2">
                                <button className="flex-1 bg-slate-100 py-2 rounded-xl text-[9px] font-bold text-slate-500 uppercase flex items-center justify-center gap-1">
                                    <i className="fas fa-file-pdf"></i> PDF
                                </button>
                                <button className="flex-1 bg-slate-100 py-2 rounded-xl text-[9px] font-bold text-slate-500 uppercase flex items-center justify-center gap-1">
                                    <i className="fas fa-code"></i> XML
                                </button>
                                <button className="flex-1 bg-slate-100 py-2 rounded-xl text-[9px] font-bold text-slate-500 uppercase flex items-center justify-center gap-1">
                                    <i className="fas fa-envelope"></i> Email
                                </button>
                            </div>
                        </RoundedCard>
                    ))
                )}
            </div>
        )}
      </div>

      {/* FOOTER ACTIONS */}
      {activeTab === 'pending' && selectedCustomer && (
          <div className="fixed bottom-0 left-0 right-0 p-6 bg-white border-t border-slate-100 shadow-[0_-10px_40px_rgba(0,0,0,0.1)] z-50 animate-slideUp">
              <div className="flex justify-between items-center mb-4 px-2">
                  <span className="text-xs font-bold text-slate-400 uppercase">{selectedSaleIds.size} Tickets</span>
                  <div className="text-right">
                      <p className="text-[9px] font-bold text-slate-400 uppercase">Total Factura</p>
                      <p className="text-2xl font-black text-sky-900">
                          ${salesForSelectedCustomer.filter(s => selectedSaleIds.has(s.id)).reduce((acc, s) => acc + s.total, 0).toFixed(2)}
                      </p>
                  </div>
              </div>
              <ActionButton onClick={handleGenerateInvoice} disabled={isProcessing}>
                  {isProcessing ? 'Timbrando...' : 'Generar CFDI 4.0'}
              </ActionButton>
          </div>
      )}

      {/* TAX INFO MODAL */}
      {editingTaxInfo && selectedCustomer && (
          <TaxDataForm 
            customer={selectedCustomer}
            onCancel={() => setEditingTaxInfo(false)}
            onSave={(profile) => {
                saveCustomer({ ...selectedCustomer, taxInfo: profile });
                setEditingTaxInfo(false);
            }}
          />
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { useNavigation } from './hooks/useNavigation';
import { Employee, Order } from './types';
import { Dashboard } from './components/Dashboard';
import { POSModule } from './components/POSModule';
import { ProductionModule } from './components/ProductionModule';
import { LogisticsModule } from './components/LogisticsModule';
import { InventoryModule } from './components/InventoryModule';
import { SuppliesModule } from './components/SuppliesModule';
import { WhatsAppModule } from './components/WhatsAppModule';
import { CustomersModule } from './components/CustomersModule';
import { EmployeesModule } from './components/EmployeesModule';
import { ReportsModule } from './components/ReportsModule';
import { SettingsModule } from './components/SettingsModule';
import { SyncModule } from './components/SyncModule';
import { OrdersModule } from './components/OrdersModule';
import { QualityModule } from './components/QualityModule';
import { ScannerModule } from './components/ScannerModule';
import { TicketModule } from './components/TicketModule';
import { MessagingModule } from './components/MessagingModule';
import { BillingModule } from './components/BillingModule';

// Auth & UI Components
import { PermissionShield } from './components/auth/PermissionShield';
import { LoginScreen } from './components/auth/LoginScreen';
import { SplashScreen } from './components/ui/SplashScreen';

// State Provider
import { ERPProvider, useERPDataHook } from './hooks/ERPContext'; // Fixed import

const AppContent: React.FC = () => {
  const { currentView, navigateTo, goBack } = useNavigation();
  const { messages, syncData, cloudConfig, addNotification, employees } = useERPDataHook();

  const [showSplash, setShowSplash] = useState(true);
  const [needsPermissions, setNeedsPermissions] = useState(() => !localStorage.getItem('aqua_permissions_granted'));
  const [user, setUser] = useState<Employee | null>(null);

  // State for passing Order to POS
  const [pendingOrderForPOS, setPendingOrderForPOS] = useState<Order | null>(null);

  // --- GLOBAL MESSAGE MONITORING ---
  const prevMsgCount = useRef(messages.length);

  // 1. Background Polling (Every 10s)
  useEffect(() => {
    if (!user || !cloudConfig.url) return;

    const pollMessages = async () => {
       try {
         const endpoint = `${cloudConfig.url}messages.json${cloudConfig.apiKey ? `?auth=${cloudConfig.apiKey}` : ''}`;
         const res = await fetch(endpoint);
         if(res.ok) {
            const data = await res.json();
            if(data) syncData({ messages: data });
         }
       } catch(e) {
         // Silent fail on background poll
       }
    };

    const interval = setInterval(pollMessages, 10000); 
    return () => clearInterval(interval);
  }, [user, cloudConfig, syncData]);

  // 2. New Message Detection & Notification
  useEffect(() => {
    if (!user) return;

    if (messages.length > prevMsgCount.current) {
        // Get only the new messages added
        const newMsgs = messages.slice(prevMsgCount.current);

        newMsgs.forEach(msg => {
            const isFromMe = msg.senderId === user.id;
            const isForMe = msg.receiverId === user.id || msg.receiverId === 'general';

            // If message is for me (or general) AND not from me
            if (!isFromMe && isForMe) {
                // Only notify if NOT currently in the messaging module
                if (currentView !== 'messages') {
                    const senderName = employees.find(e => e.id === msg.senderId)?.name.split(' ')[0] || 'Alguien';
                    const title = msg.receiverId === 'general' ? `Canal General (${senderName})` : `Mensaje de ${senderName}`;

                    addNotification({
                        title: title,
                        message: msg.text,
                        type: 'info',
                        actionLink: 'messages'
                    });
                }
            }
        });
    }
    prevMsgCount.current = messages.length;
  }, [messages, user, currentView, employees, addNotification]);

  const handleProcessOrder = (order: Order) => {
    setPendingOrderForPOS(order);
    navigateTo('pos');
  };

  if (needsPermissions) return <PermissionShield onGranted={() => setNeedsPermissions(false)} />;
  if (showSplash) return <SplashScreen onComplete={() => setShowSplash(false)} />;
  if (!user) return <LoginScreen onLogin={setUser} />;

  return (
    <div className="max-w-md mx-auto h-screen bg-sky-50 relative overflow-hidden shadow-2xl flex flex-col">
      <main className="flex-1 overflow-hidden relative">
        {currentView === 'dashboard' && <Dashboard setView={navigateTo} user={user} onLogout={() => setUser(null)} />}

        {currentView === 'pos' && (
          <POSModule 
            key="pos-module-static"
            user={user} 
            onBack={goBack} 
            initialOrder={pendingOrderForPOS} 
            onClearInitialOrder={() => setPendingOrderForPOS(null)} 
          />
        )}

        {currentView === 'settings' && <SettingsModule currentUser={user} onBack={goBack} />}
        {currentView === 'whatsapp' && <WhatsAppModule onBack={goBack} />}
        {currentView === 'customers' && <CustomersModule onBack={goBack} />}
        {currentView === 'logistics' && <LogisticsModule onBack={goBack} />}
        {currentView === 'production' && <ProductionModule onBack={goBack} />}
        {currentView === 'sync' && <SyncModule onBack={goBack} onScanRequest={() => navigateTo('scanner')} />}
        {currentView === 'inventory' && <InventoryModule onBack={goBack} />}
        {currentView === 'supplies' && <SuppliesModule onBack={goBack} />}
        {currentView === 'employees' && <EmployeesModule onBack={goBack} currentUser={user} />}
        {currentView === 'reports' && <ReportsModule onBack={goBack} />}
        {currentView === 'quality' && <QualityModule onBack={goBack} />}
        {currentView === 'scanner' && <ScannerModule onBack={goBack} />}
        {currentView === 'messages' && <MessagingModule onBack={goBack} currentUser={user} />}
        {currentView === 'billing' && <BillingModule onBack={goBack} />}

        {currentView === 'orders' && (
          <OrdersModule 
            onBack={goBack} 
            onProcessOrder={handleProcessOrder} 
          />
        )}

        {currentView === 'tickets' && <TicketModule onBack={goBack} />}
      </main>
    </div>
  );
};

const App: React.FC = () => (
  <ERPProvider>
    <AppContent />
  </ERPProvider>
);

export default App;

import React, { useState, useMemo } from 'react';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';
import { Sale, TaxProfile, Invoice, Customer } from '../types';
import { Filesystem, Directory, Encoding } from '@capacitor/filesystem';

// --- SAT CATALOGS (Simplified for common use cases) ---
const REGIMENES_FISCALES = [
  { code: '601', desc: 'General de Ley Personas Morales' },
  { code: '603', desc: 'Personas Morales con Fines no Lucrativos' },
  { code: '605', desc: 'Sueldos y Salarios e Ingresos Asimilados a Salarios' },
  { code: '606', desc: 'Arrendamiento' },
  { code: '612', desc: 'Personas Físicas con Actividades Empresariales y Profesionales' },
  { code: '621', desc: 'Incorporación Fiscal' },
  { code: '626', desc: 'Régimen Simplificado de Confianza (RESICO)' },
];

const USOS_CFDI = [
  { code: 'G01', desc: 'Adquisición de mercancías' },
  { code: 'G03', desc: 'Gastos en general' },
  { code: 'S01', desc: 'Sin efectos fiscales' },
  { code: 'D01', desc: 'Honorarios médicos, dentales y gastos hospitalarios' },
];

// --- HELPER: Validar RFC ---
const validateRFC = (rfc: string): boolean => {
  if (!rfc) return false;
  const rfcPattern = /^([A-ZÑ&]{3,4}) ?(?:- ?)?(\d{2}(?:0[1-9]|1[0-2])(?:0[1-9]|[12]\d|3[01])) ?(?:- ?)?([A-Z\d]{2})([A\d])$/;
  return rfcPattern.test(rfc.toUpperCase());
};

// --- SUB-COMPONENTS ---

const TaxDataForm = ({ customer, onSave, onCancel }: { customer: Customer, onSave: (profile: TaxProfile) => void, onCancel: () => void }) => {
  const [form, setForm] = useState<TaxProfile>(customer.taxInfo || {
    rfc: '',
    razonSocial: customer.name.toUpperCase(),
    regimenFiscal: '626',
    codigoPostal: '',
    usoCFDI: 'G03',
    email: ''
  });

  const handleSubmit = () => {
    if (!validateRFC(form.rfc)) return alert("El RFC no tiene un formato válido.");
    if (form.codigoPostal.length !== 5) return alert("El Código Postal debe ser de 5 dígitos.");
    if (!form.razonSocial) return alert("La Razón Social es obligatoria.");
    onSave(form);
  };

  return (
    <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-md z-[200] flex items-center justify-center p-4 animate-fadeIn">
      <div className="bg-white w-full max-w-md rounded-[2.5rem] p-6 shadow-2xl max-h-[90vh] overflow-y-auto no-scrollbar">
        <h3 className="text-xl font-black text-sky-900 mb-2">Datos Fiscales (SAT 4.0)</h3>
        <p className="text-xs text-slate-400 mb-6 font-medium">Información requerida para timbrado.</p>

        <div className="space-y-4">
          <div>
            <label className="text-[10px] font-black uppercase text-slate-400 ml-2">RFC (Sin Guiones)</label>
            <input className="w-full bg-slate-50 p-4 rounded-2xl outline-none font-bold text-sky-900 uppercase tracking-widest" value={form.rfc} onChange={e => setForm({...form, rfc: e.target.value.toUpperCase()})} placeholder="XAXX010101000" maxLength={13} />
          </div>

          <div>
            <label className="text-[10px] font-black uppercase text-slate-400 ml-2">Razón Social (Sin SA de CV)</label>
            <input className="w-full bg-slate-50 p-4 rounded-2xl outline-none font-bold text-sky-900 uppercase" value={form.razonSocial} onChange={e => setForm({...form, razonSocial: e.target.value.toUpperCase()})} placeholder="Nombre exacto Constancia" />
          </div>

          <div className="grid grid-cols-2 gap-4">
             <div>
                <label className="text-[10px] font-black uppercase text-slate-400 ml-2">C.P. Fiscal</label>
                <input type="number" className="w-full bg-slate-50 p-4 rounded-2xl outline-none font-bold text-sky-900" value={form.codigoPostal} onChange={e => setForm({...form, codigoPostal: e.target.value})} placeholder="00000" maxLength={5} />
             </div>
             <div>
                <label className="text-[10px] font-black uppercase text-slate-400 ml-2">Régimen</label>
                <select className="w-full bg-slate-50 p-4 rounded-2xl outline-none font-bold text-sky-900 text-xs appearance-none" value={form.regimenFiscal} onChange={e => setForm({...form, regimenFiscal: e.target.value})}>
                   {REGIMENES_FISCALES.map(r => <option key={r.code} value={r.code}>{r.code} - {r.desc.substring(0, 15)}...</option>)}
                </select>
             </div>
          </div>

          <div>
            <label className="text-[10px] font-black uppercase text-slate-400 ml-2">Uso CFDI</label>
            <select className="w-full bg-slate-50 p-4 rounded-2xl outline-none font-bold text-sky-900 text-xs appearance-none" value={form.usoCFDI} onChange={e => setForm({...form, usoCFDI: e.target.value})}>
                {USOS_CFDI.map(u => <option key={u.code} value={u.code}>{u.code} - {u.desc}</option>)}
            </select>
          </div>

          <div>
            <label className="text-[10px] font-black uppercase text-slate-400 ml-2">Email para envío</label>
            <input type="email" className="w-full bg-slate-50 p-4 rounded-2xl outline-none font-bold text-sky-900 lowercase" value={form.email} onChange={e => setForm({...form, email: e.target.value})} placeholder="cliente@email.com" />
          </div>
        </div>

        <div className="flex gap-3 mt-6">
           <button onClick={onCancel} className="flex-1 py-4 bg-slate-100 text-slate-400 rounded-2xl font-black uppercase text-xs">Cancelar</button>
           <button onClick={handleSubmit} className="flex-[2] py-4 bg-indigo-600 text-white rounded-2xl font-black uppercase text-xs shadow-xl shadow-indigo-200">Guardar Datos</button>
        </div>
      </div>
    </div>
  );
};

export const BillingModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const { sales, customers, saveCustomer, addInvoice, invoices, ticketConfig } = useERPData();
  const [activeTab, setActiveTab] = useState<'pending' | 'history'>('pending');

  // FIX: Store ID instead of Object to ensure updates propagate
  const [selectedCustomerId, setSelectedCustomerId] = useState<string | null>(null);
  const [selectedSaleIds, setSelectedSaleIds] = useState<Set<string>>(new Set());
  const [editingTaxInfo, setEditingTaxInfo] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);

  // Derived state for current customer object (Reactive)
  const selectedCustomer = useMemo(() => {
    return customers.find(c => c.id === selectedCustomerId) || null;
  }, [customers, selectedCustomerId]);

  // Group pending sales by Customer
  const pendingSales = useMemo(() => {
    return sales.filter(s => !s.invoiced && s.status !== 'cancelado');
  }, [sales]);

  const customersWithPending = useMemo(() => {
    const map = new Map<string, Customer>();
    pendingSales.forEach(s => {
        const c = customers.find(cust => cust.id === s.customerId);
        if (c) map.set(c.id, c);
    });
    return Array.from(map.values());
  }, [pendingSales, customers]);

  const salesForSelectedCustomer = useMemo(() => {
    if (!selectedCustomerId) return [];
    return pendingSales.filter(s => s.customerId === selectedCustomerId);
  }, [selectedCustomerId, pendingSales]);

  const toggleSaleSelection = (id: string) => {
    const newSet = new Set(selectedSaleIds);
    if (newSet.has(id)) newSet.delete(id);
    else newSet.add(id);
    setSelectedSaleIds(newSet);
  };

  const handleGenerateInvoice = async () => {
    if (!selectedCustomer) return;
    if (selectedSaleIds.size === 0) return alert("Selecciona al menos una venta.");
    if (!selectedCustomer.taxInfo || !validateRFC(selectedCustomer.taxInfo.rfc)) {
        alert("Faltan datos fiscales válidos del cliente.");
        setEditingTaxInfo(true);
        return;
    }

    setIsProcessing(true);

    // 1. CONSTRUCT REAL CFDI 4.0 PAYLOAD
    const selectedSalesList = salesForSelectedCustomer.filter(s => selectedSaleIds.has(s.id));

    // Calculate totals
    const subtotal = selectedSalesList.reduce((acc, s) => acc + (s.total / 1.16), 0); // Assuming 16% included
    const total = selectedSalesList.reduce((acc, s) => acc + s.total, 0);
    const tax = total - subtotal;

    // Line Items (Consolidated)
    const concepts = selectedSalesList.flatMap(s => s.items.map(item => ({
        ClaveProdServ: item.satCode || '50202301', // Default Water
        Cantidad: item.quantity,
        ClaveUnidad: item.unitCode || 'H87', // Default Piece
        Unidad: 'Pieza',
        Descripcion: item.name,
        ValorUnitario: (item.price / 1.16).toFixed(2),
        Importe: ((item.quantity * item.price) / 1.16).toFixed(2),
        ObjetoImp: '02', // Si objeto de impuesto
        Impuestos: {
            Traslados: [
                { Base: ((item.quantity * item.price) / 1.16).toFixed(2), Impuesto: '002', TipoFactor: 'Tasa', TasaOCuota: '0.160000', Importe: ((item.quantity * item.price) - ((item.quantity * item.price) / 1.16)).toFixed(2) }
            ]
        }
    })));

    const cfdiPayload = {
        Version: "4.0",
        Serie: "F",
        Folio: Date.now().toString().slice(-6),
        Fecha: new Date().toISOString(),
        Sello: "", // Filled by PAC
        FormaPago: "01", // Default Cash, logic should deduce from sales paymentSplits
        NoCertificado: "", // Filled by Issuer
        Certificado: "", // Filled by Issuer
        SubTotal: subtotal.toFixed(2),
        Moneda: "MXN",
        Total: total.toFixed(2),
        TipoDeComprobante: "I",
        Exportacion: "01",
        MetodoPago: "PUE",
        LugarExpedicion: "44100", // Should come from Config
        Emisor: {
            Rfc: ticketConfig.rfc || "XAXX010101000",
            Nombre: ticketConfig.businessName,
            RegimenFiscal: "626" // Should come from Config
        },
        Receptor: {
            Rfc: selectedCustomer.taxInfo.rfc,
            Nombre: selectedCustomer.taxInfo.razonSocial,
            DomicilioFiscalReceptor: selectedCustomer.taxInfo.codigoPostal,
            RegimenFiscalReceptor: selectedCustomer.taxInfo.regimenFiscal,
            UsoCFDI: selectedCustomer.taxInfo.usoCFDI
        },
        Conceptos: concepts,
        Impuestos: {
            TotalImpuestosTrasladados: tax.toFixed(2),
            Traslados: [
                { Impuesto: "002", TipoFactor: "Tasa", TasaOCuota: "0.160000", Importe: tax.toFixed(2) }
            ]
        }
    };

    // 2. SIMULATE API CALL TO PAC (In real app, fetch(PAC_URL, body: cfdiPayload))
    // We delay to simulate network latency
    setTimeout(() => {
        // Create Local Invoice Record
        const newInvoice: Invoice = {
            uuid: `UUID-${Math.random().toString(36).substr(2, 9).toUpperCase()}-${Date.now()}`,
            internalId: cfdiPayload.Folio,
            timestamp: Date.now(),
            customerId: selectedCustomer.id,
            customerName: selectedCustomer.taxInfo!.razonSocial,
            customerRfc: selectedCustomer.taxInfo!.rfc,
            total: parseFloat(cfdiPayload.Total),
            subtotal: parseFloat(cfdiPayload.SubTotal),
            tax: parseFloat(cfdiPayload.Impuestos.TotalImpuestosTrasladados),
            status: 'Timbrada',
            relatedSalesIds: Array.from(selectedSaleIds)
        };

        addInvoice(newInvoice);

        // Export JSON for user (Proof of real data structure)
        exportJSON(cfdiPayload, `CFDI_${newInvoice.internalId}.json`);

        setIsProcessing(false);
        setSelectedCustomerId(null); // Reset selection
        setSelectedSaleIds(new Set());
        setActiveTab('history');
        alert("✅ Factura generada y 'timbrada' exitosamente.");
    }, 2000);
  };

  const exportJSON = async (data: any, filename: string) => {
      try {
          await Filesystem.writeFile({
              path: filename,
              data: JSON.stringify(data, null, 2),
              directory: Directory.Documents,
              encoding: Encoding.UTF8
          });
          console.log("JSON exportado");
      } catch (e) {
          console.warn("No se pudo guardar archivo localmente (Web mode?)");
      }
  };

  return (
    <div className="h-full bg-slate-50 flex flex-col animate-fadeIn overflow-hidden pb-24 relative">
      <ModuleHeader title="Facturación 4.0" onBack={onBack} />

      <div className="px-6 flex gap-2 mb-4 shrink-0">
        <button onClick={() => setActiveTab('pending')} className={`flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'pending' ? 'bg-indigo-600 text-white shadow-lg' : 'bg-white text-slate-400'}`}>Por Facturar</button>
        <button onClick={() => setActiveTab('history')} className={`flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'history' ? 'bg-indigo-600 text-white shadow-lg' : 'bg-white text-slate-400'}`}>Historial</button>
      </div>

      <div className="flex-1 overflow-y-auto px-6 space-y-4 no-scrollbar pb-10">

        {/* VIEW: PENDING */}
        {activeTab === 'pending' && (
            <>
                {!selectedCustomerId ? (
                    // STEP 1: SELECT CUSTOMER
                    <div className="space-y-3">
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Clientes con Ventas Pendientes</p>
                        {customersWithPending.length === 0 ? (
                            <div className="text-center py-20 opacity-40">
                                <i className="fas fa-file-invoice text-6xl mb-4 text-slate-300"></i>
                                <p className="text-xs font-black uppercase text-slate-400">Todo Facturado</p>
                            </div>
                        ) : (
                            customersWithPending.map(c => (
                                <RoundedCard key={c.id} onClick={() => setSelectedCustomerId(c.id)} className="cursor-pointer hover:shadow-md transition-all active:scale-[0.98] border border-transparent hover:border-indigo-100">
                                    <div className="flex items-center justify-between">
                                        <div className="flex items-center gap-3">
                                            <div className="w-12 h-12 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center text-xl">
                                                <i className="fas fa-user-tie"></i>
                                            </div>
                                            <div>
                                                <h4 className="font-black text-sky-900 text-sm">{c.alias}</h4>
                                                {c.taxInfo ? (
                                                    <span className="bg-emerald-100 text-emerald-600 text-[8px] font-black px-2 py-0.5 rounded uppercase">RFC: {c.taxInfo.rfc}</span>
                                                ) : (
                                                    <span className="bg-amber-100 text-amber-600 text-[8px] font-black px-2 py-0.5 rounded uppercase">Sin Datos Fiscales</span>
                                                )}
                                            </div>
                                        </div>
                                        <i className="fas fa-chevron-right text-slate-300"></i>
                                    </div>
                                </RoundedCard>
                            ))
                        )}
                    </div>
                ) : (
                    // STEP 2: SELECT SALES
                    <div className="space-y-4 animate-slideUp">
                        {/* Customer Header */}
                        {selectedCustomer && (
                            <div className="bg-white p-4 rounded-3xl shadow-sm border border-indigo-50 flex justify-between items-center">
                                <div>
                                    <h3 className="font-black text-sky-900">{selectedCustomer.alias}</h3>
                                    <p className="text-[9px] font-bold text-slate-400 uppercase">Selección de Tickets</p>
                                </div>
                                <button onClick={() => { setSelectedCustomerId(null); setSelectedSaleIds(new Set()); }} className="w-8 h-8 bg-slate-100 text-slate-400 rounded-full flex items-center justify-center"><i className="fas fa-times"></i></button>
                            </div>
                        )}

                        {/* Tax Info Check */}
                        <div onClick={() => setEditingTaxInfo(true)} className={`p-4 rounded-3xl border-2 cursor-pointer transition-all flex items-center justify-between ${selectedCustomer?.taxInfo ? 'bg-emerald-50 border-emerald-100' : 'bg-amber-50 border-amber-200 animate-pulse'}`}>
                            <div className="flex items-center gap-3">
                                <i className={`fas ${selectedCustomer?.taxInfo ? 'fa-check-circle text-emerald-500' : 'fa-triangle-exclamation text-amber-500'} text-xl`}></i>
                                <div>
                                    <p className={`text-[10px] font-black uppercase ${selectedCustomer?.taxInfo ? 'text-emerald-700' : 'text-amber-700'}`}>Datos Fiscales</p>
                                    <p className="text-xs font-bold text-slate-600">{selectedCustomer?.taxInfo?.razonSocial || 'Requerido para facturar'}</p>
                                </div>
                            </div>
                            <i className="fas fa-pen text-slate-400"></i>
                        </div>

                        {/* Sales List */}
                        <div className="space-y-2">
                            {salesForSelectedCustomer.map(s => {
                                const isSelected = selectedSaleIds.has(s.id);
                                return (
                                    <div key={s.id} onClick={() => toggleSaleSelection(s.id)} className={`p-4 rounded-2xl border-2 transition-all cursor-pointer flex items-center justify-between ${isSelected ? 'border-indigo-500 bg-indigo-50' : 'border-white bg-white shadow-sm'}`}>
                                        <div className="flex items-center gap-3">
                                            <div className={`w-5 h-5 rounded flex items-center justify-center border ${isSelected ? 'bg-indigo-500 border-indigo-500' : 'bg-white border-slate-300'}`}>
                                                {isSelected && <i className="fas fa-check text-white text-[10px]"></i>}
                                            </div>
                                            <div>
                                                <p className="text-[10px] font-black text-slate-400 uppercase">{new Date(s.timestamp).toLocaleDateString()}</p>
                                                <p className="text-xs font-bold text-slate-700">Folio: {s.id.split('-')[1]}</p>
                                            </div>
                                        </div>
                                        <span className="font-black text-sky-900">${s.total.toFixed(2)}</span>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                )}
            </>
        )}

        {/* VIEW: HISTORY */}
        {activeTab === 'history' && (
            <div className="space-y-3">
                {invoices.length === 0 ? (
                    <div className="text-center py-20 opacity-40">
                       <i className="fas fa-clock-rotate-left text-6xl mb-4 text-slate-300"></i>
                       <p className="text-xs font-black uppercase text-slate-400">Sin historial</p>
                    </div>
                ) : (
                    invoices.sort((a,b) => b.timestamp - a.timestamp).map(inv => (
                        <RoundedCard key={inv.uuid} className="border-l-4 border-l-emerald-500 py-4">
                            <div className="flex justify-between items-start mb-2">
                                <div>
                                    <p className="text-[9px] font-black text-slate-400 uppercase">Folio: {inv.internalId}</p>
                                    <h4 className="font-black text-sky-900 text-sm truncate max-w-[150px]">{inv.customerName}</h4>
                                </div>
                                <span className="bg-emerald-100 text-emerald-600 px-2 py-1 rounded text-[8px] font-black uppercase">Timbrada</span>
                            </div>
                            <div className="flex justify-between items-end">
                                <p className="text-[8px] text-slate-400 font-mono">{inv.uuid.substring(0, 15)}...</p>
                                <p className="text-lg font-black text-slate-800">${inv.total.toFixed(2)}</p>
                            </div>
                            <div className="mt-3 flex gap-2">
                                <button className="flex-1 bg-slate-100 py-2 rounded-xl text-[9px] font-bold text-slate-500 uppercase flex items-center justify-center gap-1">
                                    <i className="fas fa-file-pdf"></i> PDF
                                </button>
                                <button className="flex-1 bg-slate-100 py-2 rounded-xl text-[9px] font-bold text-slate-500 uppercase flex items-center justify-center gap-1">
                                    <i className="fas fa-code"></i> XML
                                </button>
                                <button className="flex-1 bg-slate-100 py-2 rounded-xl text-[9px] font-bold text-slate-500 uppercase flex items-center justify-center gap-1">
                                    <i className="fas fa-envelope"></i> Email
                                </button>
                            </div>
                        </RoundedCard>
                    ))
                )}
            </div>
        )}
      </div>

      {/* FOOTER ACTIONS */}
      {activeTab === 'pending' && selectedCustomer && (
          <div className="fixed bottom-0 left-0 right-0 p-6 bg-white border-t border-slate-100 shadow-[0_-10px_40px_rgba(0,0,0,0.1)] z-50 animate-slideUp">
              <div className="flex justify-between items-center mb-4 px-2">
                  <span className="text-xs font-bold text-slate-400 uppercase">{selectedSaleIds.size} Tickets</span>
                  <div className="text-right">
                      <p className="text-[9px] font-bold text-slate-400 uppercase">Total Factura</p>
                      <p className="text-2xl font-black text-sky-900">
                          ${salesForSelectedCustomer.filter(s => selectedSaleIds.has(s.id)).reduce((acc, s) => acc + s.total, 0).toFixed(2)}
                      </p>
                  </div>
              </div>
              <ActionButton onClick={handleGenerateInvoice} disabled={isProcessing}>
                  {isProcessing ? 'Timbrando...' : 'Generar CFDI 4.0'}
              </ActionButton>
          </div>
      )}

      {/* TAX INFO MODAL */}
      {editingTaxInfo && selectedCustomer && (
          <TaxDataForm 
            customer={selectedCustomer}
            onCancel={() => setEditingTaxInfo(false)}
            onSave={(profile) => {
                saveCustomer({ ...selectedCustomer, taxInfo: profile });
                setEditingTaxInfo(false);
            }}
          />
      )}
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';
import { Sale, TaxProfile, Invoice, Customer } from '../types';
import { Filesystem, Directory, Encoding } from '@capacitor/filesystem';

// --- SAT CATALOGS (Simplified for common use cases) ---
const REGIMENES_FISCALES = [
  { code: '601', desc: 'General de Ley Personas Morales' },
  { code: '603', desc: 'Personas Morales con Fines no Lucrativos' },
  { code: '605', desc: 'Sueldos y Salarios e Ingresos Asimilados a Salarios' },
  { code: '606', desc: 'Arrendamiento' },
  { code: '612', desc: 'Personas Físicas con Actividades Empresariales y Profesionales' },
  { code: '621', desc: 'Incorporación Fiscal' },
  { code: '626', desc: 'Régimen Simplificado de Confianza (RESICO)' },
];

const USOS_CFDI = [
  { code: 'G01', desc: 'Adquisición de mercancías' },
  { code: 'G03', desc: 'Gastos en general' },
  { code: 'S01', desc: 'Sin efectos fiscales' },
  { code: 'D01', desc: 'Honorarios médicos, dentales y gastos hospitalarios' },
  { code: 'I01', desc: 'Construcciones' }
];

// --- HELPER: Validar RFC ---
const validateRFC = (rfc: string): boolean => {
  if (!rfc) return false;
  // Eliminar espacios y guiones para validar solo caracteres
  const cleanStr = rfc.replace(/[\s-]/g, '').toUpperCase();
  // Regex ajustado para aceptar formato limpio
  const rfcPattern = /^([A-ZÑ&]{3,4})(\d{6})([A-Z\d]{3})$/;
  return rfcPattern.test(cleanStr);
};

// --- SUB-COMPONENTS ---

const TaxDataForm = ({ customer, onSave, onCancel }: { customer: Customer, onSave: (profile: TaxProfile) => void, onCancel: () => void }) => {
  const [form, setForm] = useState<TaxProfile>(customer.taxInfo || {
    rfc: '',
    razonSocial: customer.name.toUpperCase(),
    regimenFiscal: '626',
    codigoPostal: '',
    usoCFDI: 'G03',
    email: ''
  });

  const handleSubmit = () => {
    // 1. Limpieza de datos antes de validar
    const cleanRFC = form.rfc.trim().toUpperCase().replace(/\s/g, ''); // Sin espacios
    const cleanZip = form.codigoPostal.trim();
    const cleanName = form.razonSocial.trim().toUpperCase();

    // 2. Validaciones con mensajes claros
    if (!validateRFC(cleanRFC)) {
        return alert(`El RFC "${cleanRFC}" no es válido.\n\nDebe tener:\n- 3 o 4 letras iniciales\n- 6 números (fecha)\n- 3 caracteres de homoclave`);
    }
    if (cleanZip.length !== 5 || isNaN(Number(cleanZip))) {
        return alert("El Código Postal debe ser numérico y tener exactamente 5 dígitos.");
    }
    if (!cleanName || cleanName.length < 3) {
        return alert("La Razón Social es obligatoria y debe ser válida.");
    }

    // 3. Guardar datos limpios
    onSave({
        ...form,
        rfc: cleanRFC,
        codigoPostal: cleanZip,
        razonSocial: cleanName
    });
  };

  return (
    <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-md z-[200] flex items-center justify-center p-4 animate-fadeIn">
      <div className="bg-white w-full max-w-md rounded-[2.5rem] p-6 shadow-2xl max-h-[90vh] overflow-y-auto no-scrollbar">
        <h3 className="text-xl font-black text-sky-900 mb-2">Datos Fiscales (SAT 4.0)</h3>
        <p className="text-xs text-slate-400 mb-6 font-medium">Información requerida para timbrado.</p>

        <div className="space-y-4">
          <div>
            <label className="text-[10px] font-black uppercase text-slate-400 ml-2">RFC (Sin Guiones ni Espacios)</label>
            <input 
                className="w-full bg-slate-50 p-4 rounded-2xl outline-none font-bold text-sky-900 uppercase tracking-widest placeholder-slate-300 focus:ring-2 ring-sky-300 transition-all" 
                value={form.rfc} 
                onChange={e => setForm({...form, rfc: e.target.value.toUpperCase().replace(/[^A-Z0-9Ñ&]/g, '')})} 
                placeholder="XAXX010101000" 
                maxLength={13} 
            />
          </div>

          <div>
            <label className="text-[10px] font-black uppercase text-slate-400 ml-2">Razón Social (Sin SA de CV)</label>
            <input 
                className="w-full bg-slate-50 p-4 rounded-2xl outline-none font-bold text-sky-900 uppercase focus:ring-2 ring-sky-300 transition-all" 
                value={form.razonSocial} 
                onChange={e => setForm({...form, razonSocial: e.target.value.toUpperCase()})} 
                placeholder="Nombre exacto Constancia" 
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
             <div>
                <label className="text-[10px] font-black uppercase text-slate-400 ml-2">C.P. Fiscal</label>
                <input 
                    type="text" 
                    inputMode="numeric" 
                    pattern="\d*" 
                    maxLength={5}
                    className="w-full bg-slate-50 p-4 rounded-2xl outline-none font-bold text-sky-900 focus:ring-2 ring-sky-300 transition-all" 
                    value={form.codigoPostal} 
                    onChange={e => setForm({...form, codigoPostal: e.target.value.replace(/\D/g, '')})} 
                    placeholder="00000" 
                />
             </div>
             <div>
                <label className="text-[10px] font-black uppercase text-slate-400 ml-2">Régimen</label>
                <select className="w-full bg-slate-50 p-4 rounded-2xl outline-none font-bold text-sky-900 text-xs appearance-none focus:ring-2 ring-sky-300 transition-all" value={form.regimenFiscal} onChange={e => setForm({...form, regimenFiscal: e.target.value})}>
                   {REGIMENES_FISCALES.map(r => <option key={r.code} value={r.code}>{r.code} - {r.desc.substring(0, 15)}...</option>)}
                </select>
             </div>
          </div>

          <div>
            <label className="text-[10px] font-black uppercase text-slate-400 ml-2">Uso CFDI</label>
            <select className="w-full bg-slate-50 p-4 rounded-2xl outline-none font-bold text-sky-900 text-xs appearance-none focus:ring-2 ring-sky-300 transition-all" value={form.usoCFDI} onChange={e => setForm({...form, usoCFDI: e.target.value})}>
                {USOS_CFDI.map(u => <option key={u.code} value={u.code}>{u.code} - {u.desc}</option>)}
            </select>
          </div>

          <div>
            <label className="text-[10px] font-black uppercase text-slate-400 ml-2">Email para envío</label>
            <input type="email" className="w-full bg-slate-50 p-4 rounded-2xl outline-none font-bold text-sky-900 lowercase focus:ring-2 ring-sky-300 transition-all" value={form.email} onChange={e => setForm({...form, email: e.target.value})} placeholder="cliente@email.com" />
          </div>
        </div>

        <div className="flex gap-3 mt-6">
           <button onClick={onCancel} className="flex-1 py-4 bg-slate-100 text-slate-400 rounded-2xl font-black uppercase text-xs hover:bg-slate-200 transition-colors">Cancelar</button>
           <button onClick={handleSubmit} className="flex-[2] py-4 bg-indigo-600 text-white rounded-2xl font-black uppercase text-xs shadow-xl shadow-indigo-200 active:scale-95 transition-transform">Guardar Datos</button>
        </div>
      </div>
    </div>
  );
};

export const BillingModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const { sales, customers, saveCustomer, addInvoice, invoices, ticketConfig } = useERPData();
  const [activeTab, setActiveTab] = useState<'pending' | 'history'>('pending');

  // FIX: Store ID instead of Object to ensure updates propagate
  const [selectedCustomerId, setSelectedCustomerId] = useState<string | null>(null);
  const [selectedSaleIds, setSelectedSaleIds] = useState<Set<string>>(new Set());
  const [editingTaxInfo, setEditingTaxInfo] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);

  // Derived state for current customer object (Reactive)
  const selectedCustomer = useMemo(() => {
    return customers.find(c => c.id === selectedCustomerId) || null;
  }, [customers, selectedCustomerId]);

  // Group pending sales by Customer
  const pendingSales = useMemo(() => {
    return sales.filter(s => !s.invoiced && s.status !== 'cancelado');
  }, [sales]);

  const customersWithPending = useMemo(() => {
    const map = new Map<string, Customer>();
    pendingSales.forEach(s => {
        const c = customers.find(cust => cust.id === s.customerId);
        if (c) map.set(c.id, c);
    });
    return Array.from(map.values());
  }, [pendingSales, customers]);

  const salesForSelectedCustomer = useMemo(() => {
    if (!selectedCustomerId) return [];
    return pendingSales.filter(s => s.customerId === selectedCustomerId);
  }, [selectedCustomerId, pendingSales]);

  const toggleSaleSelection = (id: string) => {
    const newSet = new Set(selectedSaleIds);
    if (newSet.has(id)) newSet.delete(id);
    else newSet.add(id);
    setSelectedSaleIds(newSet);
  };

  const handleGenerateInvoice = async () => {
    if (!selectedCustomer) return;
    if (selectedSaleIds.size === 0) return alert("Selecciona al menos una venta.");
    if (!selectedCustomer.taxInfo || !validateRFC(selectedCustomer.taxInfo.rfc)) {
        alert("Faltan datos fiscales válidos del cliente. Por favor verifica el RFC.");
        setEditingTaxInfo(true);
        return;
    }

    setIsProcessing(true);

    // 1. CONSTRUCT REAL CFDI 4.0 PAYLOAD
    const selectedSalesList = salesForSelectedCustomer.filter(s => selectedSaleIds.has(s.id));

    // Calculate totals
    const subtotal = selectedSalesList.reduce((acc, s) => acc + (s.total / 1.16), 0); // Assuming 16% included
    const total = selectedSalesList.reduce((acc, s) => acc + s.total, 0);
    const tax = total - subtotal;

    // Line Items (Consolidated)
    const concepts = selectedSalesList.flatMap(s => s.items.map(item => ({
        ClaveProdServ: item.satCode || '50202301', // Default Water
        Cantidad: item.quantity,
        ClaveUnidad: item.unitCode || 'H87', // Default Piece
        Unidad: 'Pieza',
        Descripcion: item.name,
        ValorUnitario: (item.price / 1.16).toFixed(2),
        Importe: ((item.quantity * item.price) / 1.16).toFixed(2),
        ObjetoImp: '02', // Si objeto de impuesto
        Impuestos: {
            Traslados: [
                { Base: ((item.quantity * item.price) / 1.16).toFixed(2), Impuesto: '002', TipoFactor: 'Tasa', TasaOCuota: '0.160000', Importe: ((item.quantity * item.price) - ((item.quantity * item.price) / 1.16)).toFixed(2) }
            ]
        }
    })));

    const cfdiPayload = {
        Version: "4.0",
        Serie: "F",
        Folio: Date.now().toString().slice(-6),
        Fecha: new Date().toISOString(),
        Sello: "", // Filled by PAC
        FormaPago: "01", // Default Cash, logic should deduce from sales paymentSplits
        NoCertificado: "", // Filled by Issuer
        Certificado: "", // Filled by Issuer
        SubTotal: subtotal.toFixed(2),
        Moneda: "MXN",
        Total: total.toFixed(2),
        TipoDeComprobante: "I",
        Exportacion: "01",
        MetodoPago: "PUE",
        LugarExpedicion: "44100", // Should come from Config
        Emisor: {
            Rfc: ticketConfig.rfc || "XAXX010101000",
            Nombre: ticketConfig.businessName,
            RegimenFiscal: "626" // Should come from Config
        },
        Receptor: {
            Rfc: selectedCustomer.taxInfo.rfc,
            Nombre: selectedCustomer.taxInfo.razonSocial,
            DomicilioFiscalReceptor: selectedCustomer.taxInfo.codigoPostal,
            RegimenFiscalReceptor: selectedCustomer.taxInfo.regimenFiscal,
            UsoCFDI: selectedCustomer.taxInfo.usoCFDI
        },
        Conceptos: concepts,
        Impuestos: {
            TotalImpuestosTrasladados: tax.toFixed(2),
            Traslados: [
                { Impuesto: "002", TipoFactor: "Tasa", TasaOCuota: "0.160000", Importe: tax.toFixed(2) }
            ]
        }
    };

    // 2. SIMULATE API CALL TO PAC (In real app, fetch(PAC_URL, body: cfdiPayload))
    // We delay to simulate network latency
    setTimeout(() => {
        // Create Local Invoice Record
        const newInvoice: Invoice = {
            uuid: `UUID-${Math.random().toString(36).substr(2, 9).toUpperCase()}-${Date.now()}`,
            internalId: cfdiPayload.Folio,
            timestamp: Date.now(),
            customerId: selectedCustomer.id,
            customerName: selectedCustomer.taxInfo!.razonSocial,
            customerRfc: selectedCustomer.taxInfo!.rfc,
            total: parseFloat(cfdiPayload.Total),
            subtotal: parseFloat(cfdiPayload.SubTotal),
            tax: parseFloat(cfdiPayload.Impuestos.TotalImpuestosTrasladados),
            status: 'Timbrada',
            relatedSalesIds: Array.from(selectedSaleIds)
        };

        addInvoice(newInvoice);

        // Export JSON for user (Proof of real data structure)
        exportJSON(cfdiPayload, `CFDI_${newInvoice.internalId}.json`);

        setIsProcessing(false);
        setSelectedCustomerId(null); // Reset selection
        setSelectedSaleIds(new Set());
        setActiveTab('history');
        alert("✅ Factura generada y 'timbrada' exitosamente.");
    }, 2000);
  };

  const exportJSON = async (data: any, filename: string) => {
      try {
          await Filesystem.writeFile({
              path: filename,
              data: JSON.stringify(data, null, 2),
              directory: Directory.Documents,
              encoding: Encoding.UTF8
          });
          console.log("JSON exportado");
      } catch (e) {
          console.warn("No se pudo guardar archivo localmente (Web mode?)");
      }
  };

  return (
    <div className="h-full bg-slate-50 flex flex-col animate-fadeIn overflow-hidden pb-24 relative">
      <ModuleHeader title="Facturación 4.0" onBack={onBack} />

      <div className="px-6 flex gap-2 mb-4 shrink-0">
        <button onClick={() => setActiveTab('pending')} className={`flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'pending' ? 'bg-indigo-600 text-white shadow-lg' : 'bg-white text-slate-400'}`}>Por Facturar</button>
        <button onClick={() => setActiveTab('history')} className={`flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'history' ? 'bg-indigo-600 text-white shadow-lg' : 'bg-white text-slate-400'}`}>Historial</button>
      </div>

      <div className="flex-1 overflow-y-auto px-6 space-y-4 no-scrollbar pb-10">

        {/* VIEW: PENDING */}
        {activeTab === 'pending' && (
            <>
                {!selectedCustomerId ? (
                    // STEP 1: SELECT CUSTOMER
                    <div className="space-y-3">
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Clientes con Ventas Pendientes</p>
                        {customersWithPending.length === 0 ? (
                            <div className="text-center py-20 opacity-40">
                                <i className="fas fa-file-invoice text-6xl mb-4 text-slate-300"></i>
                                <p className="text-xs font-black uppercase text-slate-400">Todo Facturado</p>
                            </div>
                        ) : (
                            customersWithPending.map(c => (
                                <RoundedCard key={c.id} onClick={() => setSelectedCustomerId(c.id)} className="cursor-pointer hover:shadow-md transition-all active:scale-[0.98] border border-transparent hover:border-indigo-100">
                                    <div className="flex items-center justify-between">
                                        <div className="flex items-center gap-3">
                                            <div className="w-12 h-12 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center text-xl">
                                                <i className="fas fa-user-tie"></i>
                                            </div>
                                            <div>
                                                <h4 className="font-black text-sky-900 text-sm">{c.alias}</h4>
                                                {c.taxInfo ? (
                                                    <span className="bg-emerald-100 text-emerald-600 text-[8px] font-black px-2 py-0.5 rounded uppercase">RFC: {c.taxInfo.rfc}</span>
                                                ) : (
                                                    <span className="bg-amber-100 text-amber-600 text-[8px] font-black px-2 py-0.5 rounded uppercase">Sin Datos Fiscales</span>
                                                )}
                                            </div>
                                        </div>
                                        <i className="fas fa-chevron-right text-slate-300"></i>
                                    </div>
                                </RoundedCard>
                            ))
                        )}
                    </div>
                ) : (
                    // STEP 2: SELECT SALES
                    <div className="space-y-4 animate-slideUp">
                        {/* Customer Header */}
                        {selectedCustomer && (
                            <div className="bg-white p-4 rounded-3xl shadow-sm border border-indigo-50 flex justify-between items-center">
                                <div>
                                    <h3 className="font-black text-sky-900">{selectedCustomer.alias}</h3>
                                    <p className="text-[9px] font-bold text-slate-400 uppercase">Selección de Tickets</p>
                                </div>
                                <button onClick={() => { setSelectedCustomerId(null); setSelectedSaleIds(new Set()); }} className="w-8 h-8 bg-slate-100 text-slate-400 rounded-full flex items-center justify-center"><i className="fas fa-times"></i></button>
                            </div>
                        )}

                        {/* Tax Info Check */}
                        <div onClick={() => setEditingTaxInfo(true)} className={`p-4 rounded-3xl border-2 cursor-pointer transition-all flex items-center justify-between ${selectedCustomer?.taxInfo ? 'bg-emerald-50 border-emerald-100' : 'bg-amber-50 border-amber-200 animate-pulse'}`}>
                            <div className="flex items-center gap-3">
                                <i className={`fas ${selectedCustomer?.taxInfo ? 'fa-check-circle text-emerald-500' : 'fa-triangle-exclamation text-amber-500'} text-xl`}></i>
                                <div>
                                    <p className={`text-[10px] font-black uppercase ${selectedCustomer?.taxInfo ? 'text-emerald-700' : 'text-amber-700'}`}>Datos Fiscales</p>
                                    <p className="text-xs font-bold text-slate-600">{selectedCustomer?.taxInfo?.razonSocial || 'Requerido para facturar'}</p>
                                </div>
                            </div>
                            <i className="fas fa-pen text-slate-400"></i>
                        </div>

                        {/* Sales List */}
                        <div className="space-y-2">
                            {salesForSelectedCustomer.map(s => {
                                const isSelected = selectedSaleIds.has(s.id);
                                return (
                                    <div key={s.id} onClick={() => toggleSaleSelection(s.id)} className={`p-4 rounded-2xl border-2 transition-all cursor-pointer flex items-center justify-between ${isSelected ? 'border-indigo-500 bg-indigo-50' : 'border-white bg-white shadow-sm'}`}>
                                        <div className="flex items-center gap-3">
                                            <div className={`w-5 h-5 rounded flex items-center justify-center border ${isSelected ? 'bg-indigo-500 border-indigo-500' : 'bg-white border-slate-300'}`}>
                                                {isSelected && <i className="fas fa-check text-white text-[10px]"></i>}
                                            </div>
                                            <div>
                                                <p className="text-[10px] font-black text-slate-400 uppercase">{new Date(s.timestamp).toLocaleDateString()}</p>
                                                <p className="text-xs font-bold text-slate-700">Folio: {s.id.split('-')[1]}</p>
                                            </div>
                                        </div>
                                        <span className="font-black text-sky-900">${s.total.toFixed(2)}</span>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                )}
            </>
        )}

        {/* VIEW: HISTORY */}
        {activeTab === 'history' && (
            <div className="space-y-3">
                {invoices.length === 0 ? (
                    <div className="text-center py-20 opacity-40">
                       <i className="fas fa-clock-rotate-left text-6xl mb-4 text-slate-300"></i>
                       <p className="text-xs font-black uppercase text-slate-400">Sin historial</p>
                    </div>
                ) : (
                    invoices.sort((a,b) => b.timestamp - a.timestamp).map(inv => (
                        <RoundedCard key={inv.uuid} className="border-l-4 border-l-emerald-500 py-4">
                            <div className="flex justify-between items-start mb-2">
                                <div>
                                    <p className="text-[9px] font-black text-slate-400 uppercase">Folio: {inv.internalId}</p>
                                    <h4 className="font-black text-sky-900 text-sm truncate max-w-[150px]">{inv.customerName}</h4>
                                </div>
                                <span className="bg-emerald-100 text-emerald-600 px-2 py-1 rounded text-[8px] font-black uppercase">Timbrada</span>
                            </div>
                            <div className="flex justify-between items-end">
                                <p className="text-[8px] text-slate-400 font-mono">{inv.uuid.substring(0, 15)}...</p>
                                <p className="text-lg font-black text-slate-800">${inv.total.toFixed(2)}</p>
                            </div>
                            <div className="mt-3 flex gap-2">
                                <button className="flex-1 bg-slate-100 py-2 rounded-xl text-[9px] font-bold text-slate-500 uppercase flex items-center justify-center gap-1">
                                    <i className="fas fa-file-pdf"></i> PDF
                                </button>
                                <button className="flex-1 bg-slate-100 py-2 rounded-xl text-[9px] font-bold text-slate-500 uppercase flex items-center justify-center gap-1">
                                    <i className="fas fa-code"></i> XML
                                </button>
                                <button className="flex-1 bg-slate-100 py-2 rounded-xl text-[9px] font-bold text-slate-500 uppercase flex items-center justify-center gap-1">
                                    <i className="fas fa-envelope"></i> Email
                                </button>
                            </div>
                        </RoundedCard>
                    ))
                )}
            </div>
        )}
      </div>

      {/* FOOTER ACTIONS */}
      {activeTab === 'pending' && selectedCustomer && (
          <div className="fixed bottom-0 left-0 right-0 p-6 bg-white border-t border-slate-100 shadow-[0_-10px_40px_rgba(0,0,0,0.1)] z-50 animate-slideUp">
              <div className="flex justify-between items-center mb-4 px-2">
                  <span className="text-xs font-bold text-slate-400 uppercase">{selectedSaleIds.size} Tickets</span>
                  <div className="text-right">
                      <p className="text-[9px] font-bold text-slate-400 uppercase">Total Factura</p>
                      <p className="text-2xl font-black text-sky-900">
                          ${salesForSelectedCustomer.filter(s => selectedSaleIds.has(s.id)).reduce((acc, s) => acc + s.total, 0).toFixed(2)}
                      </p>
                  </div>
              </div>
              <ActionButton onClick={handleGenerateInvoice} disabled={isProcessing}>
                  {isProcessing ? 'Timbrando...' : 'Generar CFDI 4.0'}
              </ActionButton>
          </div>
      )}

      {/* TAX INFO MODAL */}
      {editingTaxInfo && selectedCustomer && (
          <TaxDataForm 
            customer={selectedCustomer}
            onCancel={() => setEditingTaxInfo(false)}
            onSave={(profile) => {
                // Ensure we use the object from the list to avoid any stale closures
                saveCustomer({ ...selectedCustomer, taxInfo: profile });
                setEditingTaxInfo(false);
            }}
          />
      )}
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';
import { Sale, TaxProfile, Invoice, Customer } from '../types';
import { Filesystem, Directory, Encoding } from '@capacitor/filesystem';
import { generateTicketPDF } from '../services/pdfGenerator';

// --- SAT CATALOGS (Simplified for common use cases) ---
const REGIMENES_FISCALES = [
  { code: '601', desc: 'General de Ley Personas Morales' },
  { code: '603', desc: 'Personas Morales con Fines no Lucrativos' },
  { code: '605', desc: 'Sueldos y Salarios e Ingresos Asimilados a Salarios' },
  { code: '606', desc: 'Arrendamiento' },
  { code: '612', desc: 'Personas Físicas con Actividades Empresariales y Profesionales' },
  { code: '621', desc: 'Incorporación Fiscal' },
  { code: '626', desc: 'Régimen Simplificado de Confianza (RESICO)' },
];

const USOS_CFDI = [
  { code: 'G01', desc: 'Adquisición de mercancías' },
  { code: 'G03', desc: 'Gastos en general' },
  { code: 'S01', desc: 'Sin efectos fiscales' },
  { code: 'D01', desc: 'Honorarios médicos, dentales y gastos hospitalarios' },
  { code: 'I01', desc: 'Construcciones' }
];

// --- HELPER: Validar RFC ---
const validateRFC = (rfc: string): boolean => {
  if (!rfc) return false;
  // Eliminar espacios y guiones para validar solo caracteres
  const cleanStr = rfc.replace(/[\s-]/g, '').toUpperCase();
  // Regex ajustado para aceptar formato limpio
  const rfcPattern = /^([A-ZÑ&]{3,4})(\d{6})([A-Z\d]{3})$/;
  return rfcPattern.test(cleanStr);
};

// --- HELPER: Descargar Archivo (Web & Native) ---
const downloadFile = async (data: string | Uint8Array, filename: string, mimeType: string) => {
    try {
        // 1. Intento Nativo (Android/iOS)
        await Filesystem.writeFile({
            path: filename,
            data: typeof data === 'string' ? data : await blobToBase64(new Blob([data])),
            directory: Directory.Documents,
            encoding: typeof data === 'string' ? Encoding.UTF8 : undefined
        });
        alert(`✅ Archivo guardado en Documentos:\n${filename}`);
    } catch (e) {
        console.warn("Filesystem falló (Probablemente Web), usando descarga navegador.", e);

        // 2. Fallback Web
        const blob = typeof data === 'string' ? new Blob([data], { type: mimeType }) : new Blob([data], { type: mimeType });
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = filename;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        setTimeout(() => URL.revokeObjectURL(url), 1000);
    }
};

const blobToBase64 = (blob: Blob): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
        const base64 = reader.result as string;
        resolve(base64.split(',')[1]); // Remover prefijo data:
    };
    reader.onerror = reject;
    reader.readAsDataURL(blob);
  });
};

