                  <span className="text-xs font-bold text-slate-400 uppercase">{selectedSaleIds.size} Tickets</span>
                  <div className="text-right">
                      <p className="text-[9px] font-bold text-slate-400 uppercase">Total Factura</p>
                      <p className="text-2xl font-black text-sky-900">
                          ${salesForSelectedCustomer.filter(s => selectedSaleIds.has(s.id)).reduce((acc, s) => acc + s.total, 0).toFixed(2)}
                      </p>
                  </div>
              </div>
              <ActionButton onClick={handleGenerateInvoice} disabled={isProcessing}>
                  {isProcessing ? 'Timbrando...' : 'Generar CFDI 4.0'}
              </ActionButton>
          </div>
      )}

      {/* TAX INFO MODAL */}
      {editingTaxInfo && selectedCustomer && (
          <TaxDataForm 
            customer={selectedCustomer}
            onCancel={() => setEditingTaxInfo(false)}
            onSave={(profile) => {
                // Ensure we use the object from the list to avoid any stale closures
                saveCustomer({ ...selectedCustomer, taxInfo: profile });
                setEditingTaxInfo(false);
            }}
          />
      )}
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';
