import { Share } from '@capacitor/share';
import { generateTicketPDF } from '../services/pdfGenerator';

// --- HELPER: Uint8Array to Base64 ---
const uint8ArrayToBase64 = (bytes: Uint8Array) => {
    let binary = '';
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) {
        binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
}

// --- SAT CATALOGS (Simplified for common use cases) ---
const REGIMENES_FISCALES = [
  { code: '601', desc: 'General de Ley Personas Morales' },
  { code: '603', desc: 'Personas Morales con Fines no Lucrativos' },
  { code: '605', desc: 'Sueldos y Salarios e Ingresos Asimilados a Salarios' },
  { code: '606', desc: 'Arrendamiento' },
  { code: '612', desc: 'Personas Físicas con Actividades Empresariales y Profesionales' },
  { code: '621', desc: 'Incorporación Fiscal' },
  { code: '626', desc: 'Régimen Simplificado de Confianza (RESICO)' },
];

const USOS_CFDI = [
  { code: 'G01', desc: 'Adquisición de mercancías' },
  { code: 'G03', desc: 'Gastos en general' },
  { code: 'S01', desc: 'Sin efectos fiscales' },
  { code: 'D01', desc: 'Honorarios médicos, dentales y gastos hospitalarios' },
  { code: 'I01', desc: 'Construcciones' }
];

// --- HELPER: Validar RFC ---
const validateRFC = (rfc: string): boolean => {
  if (!rfc) return false;
  // Eliminar espacios y guiones para validar solo caracteres
  const cleanStr = rfc.replace(/[\s-]/g, '').toUpperCase();
  // Regex ajustado para aceptar formato limpio
  const rfcPattern = /^([A-ZÑ&]{3,4})(\d{6})([A-Z\d]{3})$/;
  return rfcPattern.test(cleanStr);
};

// --- HELPER: Descargar Archivo (Web & Native) ---
const downloadFile = async (data: string | Uint8Array, filename: string, mimeType: string) => {
    try {
        // 1. Intento Nativo (Android/iOS)
        await Filesystem.writeFile({
            path: filename,
            data: typeof data === 'string' ? data : await blobToBase64(new Blob([data])),
            directory: Directory.Documents,
            encoding: typeof data === 'string' ? Encoding.UTF8 : undefined
        });
        alert(`✅ Archivo guardado en Documentos:\n${filename}`);
    } catch (e) {
        console.warn("Filesystem falló (Probablemente Web), usando descarga navegador.", e);

        // 2. Fallback Web
        const blob = typeof data === 'string' ? new Blob([data], { type: mimeType }) : new Blob([data], { type: mimeType });
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = filename;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        setTimeout(() => URL.revokeObjectURL(url), 1000);
    }
};

const blobToBase64 = (blob: Blob): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
        const base64 = reader.result as string;
        resolve(base64.split(',')[1]); // Remover prefijo data:
    };
    reader.onerror = reject;
    reader.readAsDataURL(blob);
  });
};

// --- SUB-COMPONENTS ---

const TaxDataForm = ({ customer, onSave, onCancel }: { customer: Customer, onSave: (profile: TaxProfile) => void, onCancel: () => void }) => {
  const [form, setForm] = useState<TaxProfile>(customer.taxInfo || {
    rfc: '',
    razonSocial: customer.name.toUpperCase(),
    regimenFiscal: '626',
    codigoPostal: '',
    usoCFDI: 'G03',
    email: ''
  });

  const handleSubmit = () => {
    // 1. Limpieza de datos antes de validar
    const cleanRFC = form.rfc.trim().toUpperCase().replace(/\s/g, ''); // Sin espacios
    const cleanZip = form.codigoPostal.trim();
    const cleanName = form.razonSocial.trim().toUpperCase();

    // 2. Validaciones con mensajes claros
    if (!validateRFC(cleanRFC)) {
        return alert(`El RFC "${cleanRFC}" no es válido.\n\nDebe tener:\n- 3 o 4 letras iniciales\n- 6 números (fecha)\n- 3 caracteres de homoclave`);
    }
    if (cleanZip.length !== 5 || isNaN(Number(cleanZip))) {
        return alert("El Código Postal debe ser numérico y tener exactamente 5 dígitos.");
    }
    if (!cleanName || cleanName.length < 3) {
        return alert("La Razón Social es obligatoria y debe ser válida.");
    }

    // 3. Guardar datos limpios
    onSave({
        ...form,
        rfc: cleanRFC,
        codigoPostal: cleanZip,
        razonSocial: cleanName
    });
  };

  return (
    <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-md z-[200] flex items-center justify-center p-4 animate-fadeIn">
      <div className="bg-white w-full max-w-md rounded-[2.5rem] p-6 shadow-2xl max-h-[90vh] overflow-y-auto no-scrollbar">
        <h3 className="text-xl font-black text-sky-900 mb-2">Datos Fiscales (SAT 4.0)</h3>
        <p className="text-xs text-slate-400 mb-6 font-medium">Información requerida para timbrado.</p>

        <div className="space-y-4">
          <div>
            <label className="text-[10px] font-black uppercase text-slate-400 ml-2">RFC (Sin Guiones ni Espacios)</label>
            <input 
                className="w-full bg-slate-50 p-4 rounded-2xl outline-none font-bold text-sky-900 uppercase tracking-widest placeholder-slate-300 focus:ring-2 ring-sky-300 transition-all" 
                value={form.rfc} 
                onChange={e => setForm({...form, rfc: e.target.value.toUpperCase().replace(/[^A-Z0-9Ñ&]/g, '')})} 
                placeholder="XAXX010101000" 
                maxLength={13} 
            />
          </div>

          <div>
            <label className="text-[10px] font-black uppercase text-slate-400 ml-2">Razón Social (Sin SA de CV)</label>
            <input 
                className="w-full bg-slate-50 p-4 rounded-2xl outline-none font-bold text-sky-900 uppercase focus:ring-2 ring-sky-300 transition-all" 
                value={form.razonSocial} 
                onChange={e => setForm({...form, razonSocial: e.target.value.toUpperCase()})} 
                placeholder="Nombre exacto Constancia" 
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
             <div>
                <label className="text-[10px] font-black uppercase text-slate-400 ml-2">C.P. Fiscal</label>
                <input 
                    type="text" 
                    inputMode="numeric" 
                    pattern="\d*" 
                    maxLength={5}
                    className="w-full bg-slate-50 p-4 rounded-2xl outline-none font-bold text-sky-900 focus:ring-2 ring-sky-300 transition-all" 
                    value={form.codigoPostal} 
                    onChange={e => setForm({...form, codigoPostal: e.target.value.replace(/\D/g, '')})} 
                    placeholder="00000" 
                />
             </div>
             <div>
                <label className="text-[10px] font-black uppercase text-slate-400 ml-2">Régimen</label>
                <select className="w-full bg-slate-50 p-4 rounded-2xl outline-none font-bold text-sky-900 text-xs appearance-none focus:ring-2 ring-sky-300 transition-all" value={form.regimenFiscal} onChange={e => setForm({...form, regimenFiscal: e.target.value})}>
                   {REGIMENES_FISCALES.map(r => <option key={r.code} value={r.code}>{r.code} - {r.desc.substring(0, 15)}...</option>)}
                </select>
             </div>
          </div>

          <div>
            <label className="text-[10px] font-black uppercase text-slate-400 ml-2">Uso CFDI</label>
            <select className="w-full bg-slate-50 p-4 rounded-2xl outline-none font-bold text-sky-900 text-xs appearance-none focus:ring-2 ring-sky-300 transition-all" value={form.usoCFDI} onChange={e => setForm({...form, usoCFDI: e.target.value})}>
                {USOS_CFDI.map(u => <option key={u.code} value={u.code}>{u.code} - {u.desc}</option>)}
            </select>
