                                    onClick={() => handleDownloadInvoiceXML(inv)}
                                    className="bg-slate-100 py-2 rounded-xl text-[9px] font-bold text-slate-500 uppercase flex items-center justify-center gap-1 active:scale-95 transition-transform"
                                >
                                    <i className="fas fa-code"></i> Guardar XML
