  const handleSubmit = () => {
    const cleanRFC = form.rfc.trim().toUpperCase().replace(/\s/g, ''); 
    const cleanZip = form.codigoPostal.trim();
    const cleanName = form.razonSocial.trim().toUpperCase();

    if (!validateRFC(cleanRFC)) {
        return alert(`El RFC "${cleanRFC}" no es válido.`);
    }
