export const BillingModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const { sales, customers, saveCustomer, addInvoice, invoices, ticketConfig } = useERPData();
  const [activeTab, setActiveTab] = useState<'pending' | 'history'>('pending');

  const [selectedCustomerId, setSelectedCustomerId] = useState<string | null>(null);
  const [selectedSaleIds, setSelectedSaleIds] = useState<Set<string>>(new Set());
  const [editingTaxInfo, setEditingTaxInfo] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);

  // Preview State
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);

  const selectedCustomer = useMemo(() => {
    return customers.find(c => c.id === selectedCustomerId) || null;
  }, [customers, selectedCustomerId]);

  const pendingSales = useMemo(() => {
    return sales.filter(s => !s.invoiced && s.status !== 'cancelado');
  }, [sales]);

  const customersWithPending = useMemo(() => {
    const map = new Map<string, Customer>();
    pendingSales.forEach(s => {
        const c = customers.find(cust => cust.id === s.customerId);
        if (c) map.set(c.id, c);
    });
    return Array.from(map.values());
  }, [pendingSales, customers]);

  const salesForSelectedCustomer = useMemo(() => {
    if (!selectedCustomerId) return [];
    return pendingSales.filter(s => s.customerId === selectedCustomerId);
  }, [selectedCustomerId, pendingSales]);

  const toggleSaleSelection = (id: string) => {
    const newSet = new Set(selectedSaleIds);
    if (newSet.has(id)) newSet.delete(id);
    else newSet.add(id);
    setSelectedSaleIds(newSet);
  };

  // Helper to calculate invoice numbers without generating final object
  const calculateInvoiceData = () => {
    if (!selectedCustomer) return null;
    const selectedSalesList = salesForSelectedCustomer.filter(s => selectedSaleIds.has(s.id));
    if (selectedSalesList.length === 0) return null;

    const subtotal = selectedSalesList.reduce((acc, s) => acc + (s.total / 1.16), 0);
    const total = selectedSalesList.reduce((acc, s) => acc + s.total, 0);
    const tax = total - subtotal;

    return {
        selectedSalesList,
        subtotal,
        total,
        tax
    };
  };

  const handlePreviewInvoice = async () => {
    if (!selectedCustomer) return;
    if (selectedSaleIds.size === 0) return alert("Selecciona ventas.");
    if (!selectedCustomer.taxInfo || !validateRFC(selectedCustomer.taxInfo.rfc)) {
        return alert("Faltan datos fiscales del cliente.");
    }

    const data = calculateInvoiceData();
    if (!data) return;

    // Create a mock invoice for the PDF generator
    const mockInvoice: Invoice = {
        uuid: "PREVISUALIZACION-SIN-VALIDEZ-FISCAL",
        internalId: "BORRADOR",
        timestamp: Date.now(),
        customerId: selectedCustomer.id,
        customerName: selectedCustomer.taxInfo.razonSocial,
        customerRfc: selectedCustomer.taxInfo.rfc,
        total: data.total,
        subtotal: data.subtotal,
        tax: data.tax,
        status: 'Pendiente',
        relatedSalesIds: []
    };

    try {
        const pdfBytes = await generatePDFBytes(mockInvoice);
        const blob = new Blob([pdfBytes], { type: 'application/pdf' });
        const url = URL.createObjectURL(blob);
        setPreviewUrl(url);
    } catch (e) {
        console.error(e);
        alert("Error generando vista previa.");
    }
  };

  const handleGenerateInvoice = async () => {
    if (!selectedCustomer) return;
    if (selectedSaleIds.size === 0) return alert("Selecciona al menos una venta.");

    // Close preview if open
    if (previewUrl) {
        URL.revokeObjectURL(previewUrl);
        setPreviewUrl(null);
    }

    if (!selectedCustomer.taxInfo || !validateRFC(selectedCustomer.taxInfo.rfc)) {
        alert("Faltan datos fiscales válidos. Verifica el RFC.");
        setEditingTaxInfo(true);
        return;
    }

    setIsProcessing(true);

    const data = calculateInvoiceData();
    if (!data) { setIsProcessing(false); return; }

    // Line Items (Consolidated)
    const concepts = data.selectedSalesList.flatMap(s => s.items.map(item => ({
        ClaveProdServ: item.satCode || '50202301', 
        Cantidad: item.quantity,
        ClaveUnidad: item.unitCode || 'H87', 
        Descripcion: item.name,
        ValorUnitario: (item.price / 1.16).toFixed(2),
        Importe: ((item.quantity * item.price) / 1.16).toFixed(2),
    })));

    const cfdiPayload = {
        Version: "4.0",
        Folio: Date.now().toString().slice(-6),
        Fecha: new Date().toISOString(),
        SubTotal: data.subtotal.toFixed(2),
        Total: data.total.toFixed(2),
        Receptor: { Rfc: selectedCustomer.taxInfo.rfc, Nombre: selectedCustomer.taxInfo.razonSocial },
        Conceptos: concepts,
    };

    setTimeout(() => {
        const newInvoice: Invoice = {
            uuid: `UUID-${Math.random().toString(36).substr(2, 9).toUpperCase()}-${Date.now()}`,
            internalId: cfdiPayload.Folio,
            timestamp: Date.now(),
            customerId: selectedCustomer.id,
            customerName: selectedCustomer.taxInfo!.razonSocial,
            customerRfc: selectedCustomer.taxInfo!.rfc,
            total: data.total,
            subtotal: data.subtotal,
            tax: data.tax,
            status: 'Timbrada',
            relatedSalesIds: Array.from(selectedSaleIds)
        };

        addInvoice(newInvoice);
        downloadFile(JSON.stringify(cfdiPayload, null, 2), `CFDI_${newInvoice.internalId}.json`, 'application/json');

        setIsProcessing(false);
        setSelectedCustomerId(null);
        setSelectedSaleIds(new Set());
        setActiveTab('history');
        alert("✅ Factura generada y 'timbrada' exitosamente.");
    }, 2000);
  };

  // --- CONTENT GENERATORS ---
  const generateXMLContent = (inv: Invoice) => {
      return `<?xml version="1.0" encoding="UTF-8"?>
<cfdi:Comprobante Version="4.0" Folio="${inv.internalId}" Fecha="${new Date(inv.timestamp).toISOString()}" Total="${inv.total.toFixed(2)}" SubTotal="${inv.subtotal.toFixed(2)}" Moneda="MXN" TipoDeComprobante="I" MetodoPago="PUE" LugarExpedicion="44100">
  <cfdi:Emisor Rfc="${ticketConfig.rfc}" Nombre="${ticketConfig.businessName}" RegimenFiscal="626"/>
  <cfdi:Receptor Rfc="${inv.customerRfc}" Nombre="${inv.customerName}" UsoCFDI="G03"/>
  <cfdi:Conceptos>
    <cfdi:Concepto Importe="${inv.subtotal.toFixed(2)}" ValorUnitario="${inv.subtotal.toFixed(2)}" Description="Venta Global Facturada" Cantidad="1" ClaveUnidad="E48" ClaveProdServ="01010101"/>
  </cfdi:Conceptos>
  <cfdi:Impuestos TotalImpuestosTrasladados="${inv.tax.toFixed(2)}">
    <cfdi:Traslados>
        <cfdi:Traslado Base="${inv.subtotal.toFixed(2)}" Impuesto="002" TipoFactor="Tasa" TasaOCuota="0.160000" Importe="${inv.tax.toFixed(2)}"/>
    </cfdi:Traslados>
  </cfdi:Impuestos>
</cfdi:Comprobante>`;
  };

  const generatePDFBytes = async (inv: Invoice) => {
      const mockSale: Sale = {
          id: `F-${inv.internalId}`,
          timestamp: inv.timestamp,
          customerId: inv.customerId,
          customerAlias: inv.customerName,
          items: [{ id: 'ref', name: 'CONSUMO GENERAL (FACTURA)', price: inv.subtotal, quantity: 1, stock: 0, category: 'Agua' }],
          total: inv.total,
          paidAmount: inv.total,
          change: 0,
          paymentSplits: [],
          emptyGarrafonsReturned: 0,
          synced: true,
          invoiced: true
      };

      const invoiceConfig = {
          ...ticketConfig,
          footerMessage: `UUID: ${inv.uuid}`,
          extraNote: 'Este documento es una representación impresa de un CFDI.'
      };

      return await generateTicketPDF(mockSale, invoiceConfig);
  };

  // --- DOWNLOAD HANDLERS ---
  const handleDownloadInvoiceXML = (inv: Invoice) => {
      const xml = generateXMLContent(inv);
      downloadFile(xml, `Factura_${inv.internalId}.xml`, 'text/xml');
  };

  const handleDownloadInvoicePDF = async (inv: Invoice) => {
      try {
          const pdfBytes = await generatePDFBytes(inv);
          await downloadFile(pdfBytes, `Factura_${inv.internalId}.pdf`, 'application/pdf');
      } catch (e) {
          console.error(e);
          alert("Error generando representación PDF");
      }
  };

  // --- SHARE HANDLERS (WHATSAPP) ---
  const handleShareInvoiceXML = async (inv: Invoice) => {
      const xml = generateXMLContent(inv);
      try {
          const fileName = `Factura_${inv.internalId}.xml`;
          const savedFile = await Filesystem.writeFile({
              path: fileName,
              data: xml,
              directory: Directory.Cache,
              encoding: Encoding.UTF8
          });

          await Share.share({ title: `XML Factura`, url: savedFile.uri });
      } catch (e) { console.error(e); alert("Error al compartir XML."); }
  };

  const handleShareInvoicePDF = async (inv: Invoice) => {
      try {
          const pdfBytes = await generatePDFBytes(inv);
          const base64 = uint8ArrayToBase64(pdfBytes);
          const fileName = `Factura_${inv.internalId}.pdf`;
          const savedFile = await Filesystem.writeFile({
              path: fileName,
              data: base64,
              directory: Directory.Cache
          });
          await Share.share({ title: `PDF Factura`, url: savedFile.uri });
      } catch (e) { console.error(e); alert("Error al compartir PDF."); }
  };

  return (
    <div className="h-full bg-slate-50 flex flex-col animate-fadeIn overflow-hidden pb-24 relative">
      <ModuleHeader title="Facturación 4.0" onBack={onBack} />

      <div className="px-6 flex gap-2 mb-4 shrink-0">
