                                </button>
                                <button 
                                    onClick={() => handleShareInvoicePDF(inv)}
                                    className="bg-emerald-500 text-white py-2 rounded-xl text-[9px] font-bold uppercase flex items-center justify-center gap-1 active:scale-95 transition-transform shadow-lg shadow-emerald-200"
                                >
                                    <i className="fab fa-whatsapp"></i> Enviar PDF
                                </button>
                                <button 
                                    onClick={() => handleShareInvoiceXML(inv)}
