      </div>

      {/* FOOTER ACTIONS */}
      {activeTab === 'pending' && selectedCustomer && (
          <div className="fixed bottom-0 left-0 right-0 p-6 bg-white border-t border-slate-100 shadow-[0_-10px_40px_rgba(0,0,0,0.1)] z-50 animate-slideUp">
              <div className="flex justify-between items-center mb-4 px-2">
                  <span className="text-xs font-bold text-slate-400 uppercase">{selectedSaleIds.size} Tickets</span>
                  <div className="text-right">
                      <p className="text-[9px] font-bold text-slate-400 uppercase">Total Factura</p>
                      <p className="text-2xl font-black text-sky-900">
                          ${salesForSelectedCustomer.filter(s => selectedSaleIds.has(s.id)).reduce((acc, s) => acc + s.total, 0).toFixed(2)}
                      </p>
                  </div>
              </div>

              <div className="flex gap-3">
                  <button 
                    onClick={handlePreviewInvoice}
                    disabled={isProcessing || selectedSaleIds.size === 0}
                    className="flex-1 bg-white text-indigo-600 border-2 border-indigo-100 py-4 rounded-[1.5rem] font-black text-xs uppercase tracking-widest active:scale-95 transition-all shadow-sm"
                  >
                    Vista Previa
                  </button>
                  <button 
                    onClick={handleGenerateInvoice} 
                    disabled={isProcessing || selectedSaleIds.size === 0}
                    className="flex-[2] bg-gradient-to-r from-sky-500 to-indigo-600 text-white py-4 rounded-[1.5rem] font-black text-xs uppercase tracking-widest shadow-lg shadow-sky-500/30 active:scale-95 transition-all"
                  >
                    {isProcessing ? 'Timbrando...' : 'Generar CFDI 4.0'}
                  </button>
              </div>
          </div>
      )}

      {/* MODALS */}
      {editingTaxInfo && selectedCustomer && (
          <TaxDataForm 
            customer={selectedCustomer}
            onCancel={() => setEditingTaxInfo(false)}
            onSave={(profile) => {
                saveCustomer({ ...selectedCustomer, taxInfo: profile });
                setEditingTaxInfo(false);
            }}
          />
      )}

      {previewUrl && (
          <InvoicePreviewModal 
            url={previewUrl}
            onClose={() => { URL.revokeObjectURL(previewUrl); setPreviewUrl(null); }}
            onConfirm={() => {
                URL.revokeObjectURL(previewUrl);
                setPreviewUrl(null);
                handleGenerateInvoice();
            }}
            isProcessing={isProcessing}
          />
      )}
    </div>
  );
};

