import React, { useState, useMemo } from 'react';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';
import { Vehicle, FuelRecord } from '../types';

export const FuelModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const { vehicles, addFuelRecord } = useERPData();
  const [activeTab, setActiveTab] = useState<'register' | 'history'>('register');

  // Form State
  const [selectedVehicleId, setSelectedVehicleId] = useState<string>('');
  const [mileage, setMileage] = useState<string>('');
  const [liters, setLiters] = useState<string>('');
  const [cost, setCost] = useState<string>('');
  const [notes, setNotes] = useState('');

  const selectedVehicle = useMemo(() => 
    vehicles.find(v => v.id === selectedVehicleId), 
  [vehicles, selectedVehicleId]);

  // Determine last mileage to calculate efficiency
  const lastRecord = useMemo(() => {
    if (!selectedVehicle || !selectedVehicle.fuelHistory || selectedVehicle.fuelHistory.length === 0) return null;
    return selectedVehicle.fuelHistory[0]; // Assuming 0 is newest based on unshift in hook
  }, [selectedVehicle]);

  const efficiency = useMemo(() => {
    if (!lastRecord || !mileage || !liters) return null;
    const currentKm = parseFloat(mileage);
    const l = parseFloat(liters);
    const diff = currentKm - lastRecord.mileage;
    if (diff <= 0 || l <= 0) return 0;
    return diff / l;
  }, [mileage, liters, lastRecord]);

  const handleSave = () => {
    if (!selectedVehicleId || !mileage || !liters || !cost) {
      alert("Por favor completa todos los campos numéricos.");
      return;
    }

    const currentKm = parseFloat(mileage);

    if (lastRecord && currentKm <= lastRecord.mileage) {
      alert(`Error: El kilometraje (${currentKm}) no puede ser menor o igual al anterior (${lastRecord.mileage}).`);
      return;
    }

    const newRecord: FuelRecord = {
      id: Date.now().toString(),
      date: Date.now(),
      mileage: currentKm,
      liters: parseFloat(liters),
      cost: parseFloat(cost),
      notes: notes
    };

    addFuelRecord(selectedVehicleId, newRecord);

    // Reset Form
    setMileage('');
    setLiters('');
    setCost('');
    setNotes('');
    alert("✅ Carga registrada correctamente.");
    setActiveTab('history');
  };

  return (
    <div className="h-full bg-slate-50 flex flex-col animate-fadeIn overflow-hidden pb-24 relative">
      <ModuleHeader title="Control Combustible" onBack={onBack} />

      <div className="px-6 flex gap-2 mb-4 shrink-0">
        <button onClick={() => setActiveTab('register')} className={`flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'register' ? 'bg-amber-500 text-white shadow-lg' : 'bg-white text-slate-400'}`}>Registrar Carga</button>
        <button onClick={() => setActiveTab('history')} className={`flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'history' ? 'bg-amber-500 text-white shadow-lg' : 'bg-white text-slate-400'}`}>Historial</button>
      </div>

      <div className="flex-1 overflow-y-auto px-6 space-y-4 no-scrollbar pb-10">

        {activeTab === 'register' && (
          <div className="space-y-6">

            {/* Vehicle Selector */}
            <div className="bg-white p-4 rounded-[2rem] shadow-sm border border-slate-50">
               <label className="text-[10px] font-black text-slate-400 uppercase ml-2 mb-2 block">Seleccionar Unidad</label>
               <div className="grid grid-cols-2 gap-3">
                  {vehicles.map(v => (
                    <button 
                      key={v.id} 
                      onClick={() => setSelectedVehicleId(v.id)}
                      className={`p-3 rounded-2xl border-2 transition-all flex items-center gap-3 ${selectedVehicleId === v.id ? 'border-amber-500 bg-amber-50' : 'border-slate-100 bg-slate-50'}`}
                    >
                       <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-lg ${selectedVehicleId === v.id ? 'bg-amber-500 text-white' : 'bg-white text-slate-300'}`}>
                          <i className="fas fa-truck-pickup"></i>
                       </div>
                       <div className="text-left">
                          <p className={`text-xs font-black uppercase ${selectedVehicleId === v.id ? 'text-amber-900' : 'text-slate-500'}`}>{v.plate}</p>
                          <p className="text-[8px] font-bold text-slate-400 truncate max-w-[80px]">{v.description}</p>
                       </div>
                    </button>
                  ))}
               </div>
            </div>

            {selectedVehicle && (
              <div className="animate-slideUp space-y-4">
                 {/* Odometer Input */}
                 <RoundedCard className="bg-slate-800 text-white border-none relative overflow-hidden">
                    <div className="flex justify-between items-start mb-4 relative z-10">
                       <div>
                          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Odómetro Actual</p>
                          {lastRecord && <p className="text-[8px] text-amber-400">Anterior: {lastRecord.mileage.toLocaleString()} km</p>}
                       </div>
                       <i className="fas fa-gauge-high text-2xl text-slate-600"></i>
                    </div>
                    <div className="flex items-center gap-2 relative z-10">
                       <input 
                         type="number" 
                         inputMode="numeric"
                         value={mileage}
                         onChange={e => setMileage(e.target.value)}
                         placeholder={lastRecord ? `${lastRecord.mileage + 100}` : '0'}
                         className="w-full bg-transparent text-4xl font-black text-white outline-none placeholder-slate-600"
                       />
                       <span className="text-sm font-bold text-slate-500">KM</span>
                    </div>
                 </RoundedCard>

                 {/* Fuel Details */}
                 <div className="grid grid-cols-2 gap-3">
                    <div className="bg-white p-5 rounded-[2rem] shadow-sm">
                       <label className="text-[9px] font-black text-slate-400 uppercase block mb-1">Litros</label>
                       <input 
                         type="number" 
                         inputMode="decimal"
                         className="w-full text-2xl font-black text-slate-800 outline-none placeholder-slate-200" 
                         placeholder="0.0"
                         value={liters}
                         onChange={e => setLiters(e.target.value)}
                       />
                    </div>
                    <div className="bg-white p-5 rounded-[2rem] shadow-sm">
                       <label className="text-[9px] font-black text-slate-400 uppercase block mb-1">Costo Total</label>
                       <div className="flex items-center">
                         <span className="text-lg font-black text-slate-300 mr-1">$</span>
                         <input 
                           type="number" 
                           inputMode="decimal"
                           className="w-full text-2xl font-black text-emerald-600 outline-none placeholder-slate-200" 
                           placeholder="0.00"
                           value={cost}
                           onChange={e => setCost(e.target.value)}
                         />
                       </div>
                    </div>
                 </div>

                 {/* Calculated Stats Preview */}
                 {efficiency && efficiency > 0 && (
                    <div className="flex items-center justify-between bg-indigo-50 p-4 rounded-2xl border border-indigo-100">
                       <div className="flex items-center gap-3">
                          <div className="w-10 h-10 bg-indigo-100 text-indigo-600 rounded-full flex items-center justify-center text-lg"><i className="fas fa-chart-line"></i></div>
                          <div>
                             <p className="text-[10px] font-bold text-indigo-400 uppercase">Rendimiento Est.</p>
                             <p className="text-xl font-black text-indigo-900">{efficiency.toFixed(2)} <span className="text-xs">Km/L</span></p>
                          </div>
                       </div>
                       <div className="text-right">
                          <p className="text-[10px] font-bold text-indigo-400 uppercase">Precio / L</p>
                          <p className="text-sm font-black text-indigo-900">${(parseFloat(cost)/parseFloat(liters)).toFixed(2)}</p>
                       </div>
                    </div>
                 )}

                 <textarea 
                    className="w-full bg-white p-4 rounded-2xl outline-none font-bold text-slate-600 text-sm resize-none shadow-sm focus:ring-2 ring-amber-200 transition-all"
                    rows={2}
                    placeholder="Notas opcionales (Gasolinera, Ticket #...)"
                    value={notes}
                    onChange={e => setNotes(e.target.value)}
                 ></textarea>

                 <ActionButton onClick={handleSave} variant="primary">
                    Registrar Carga <i className="fas fa-gas-pump ml-2"></i>
                 </ActionButton>
              </div>
            )}
          </div>
        )}

        {activeTab === 'history' && (
          <div className="space-y-4">
             <div className="flex gap-2 overflow-x-auto no-scrollbar pb-2">
                <button 
                  onClick={() => setSelectedVehicleId('')}
                  className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase whitespace-nowrap transition-all ${!selectedVehicleId ? 'bg-slate-800 text-white' : 'bg-white text-slate-400'}`}
                >
                  Todos
                </button>
                {vehicles.map(v => (
                   <button 
                     key={v.id} 
                     onClick={() => setSelectedVehicleId(v.id)}
                     className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase whitespace-nowrap transition-all ${selectedVehicleId === v.id ? 'bg-amber-500 text-white' : 'bg-white text-slate-400'}`}
                   >
                     {v.plate}
                   </button>
                ))}
             </div>

             {vehicles.filter(v => !selectedVehicleId || v.id === selectedVehicleId).map(v => (
               <div key={v.id}>
                  {(!v.fuelHistory || v.fuelHistory.length === 0) ? (
                     selectedVehicleId === v.id && <p className="text-center text-slate-400 text-xs italic mt-10">Sin registros para esta unidad.</p>
                  ) : (
                     <div className="space-y-3">
                        {!selectedVehicleId && <h4 className="text-xs font-black text-slate-600 uppercase ml-2 mt-4 mb-2">{v.plate} - {v.description}</h4>}
                        {v.fuelHistory.map((rec, idx, arr) => {
                           // Calculate efficiency relative to the NEXT record in the array (which is chronologically previous)
                           const prevRecord = arr[idx + 1];
                           const effic = prevRecord ? (rec.mileage - prevRecord.mileage) / rec.liters : 0;

                           return (
                             <RoundedCard key={rec.id} className="p-4 border-l-4 border-l-amber-400 flex justify-between items-center shadow-sm">
                                <div>
                                   <p className="text-[10px] font-bold text-slate-400 uppercase">{new Date(rec.date).toLocaleDateString()} {new Date(rec.date).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}</p>
                                   <div className="flex items-center gap-2">
                                      <span className="text-lg font-black text-slate-800">{rec.liters} L</span>
                                      <span className="text-xs font-bold text-slate-400">x ${rec.cost.toLocaleString()}</span>
                                   </div>
                                   <p className="text-xs font-bold text-slate-600">Odo: {rec.mileage.toLocaleString()} km</p>
                                </div>
                                <div className="text-right">
                                   {effic > 0 ? (
                                     <div className={`px-3 py-1 rounded-lg text-xs font-black mb-1 ${effic > 8 ? 'bg-emerald-100 text-emerald-600' : effic > 5 ? 'bg-amber-100 text-amber-600' : 'bg-rose-100 text-rose-600'}`}>
                                        {effic.toFixed(1)} km/L
                                     </div>
                                   ) : (
                                     <div className="px-3 py-1 rounded-lg text-[9px] font-bold bg-slate-100 text-slate-400 mb-1">Base</div>
                                   )}
                                   <p className="text-[9px] text-slate-400 italic max-w-[80px] truncate">{rec.notes}</p>
                                </div>
                             </RoundedCard>
                           );
                        })}
                     </div>
                  )}
               </div>
             ))}
          </div>
        )}
      </div>
    </div>
  );
};

