  });

  const [customers, setCustomers] = useState<Customer[]>(() => {
    const saved = localStorage.getItem('aqua_customers');
    return saved ? JSON.parse(saved).map((c: any) => ({ ...c, balance: c.balance || 0 })) : INITIAL_CUSTOMERS;
  });

  const [ticketConfig, setTicketConfig] = useState<TicketConfig>(() => {
    const saved = localStorage.getItem('aqua_ticket_config');
    const parsed = saved ? JSON.parse(saved) : INITIAL_TICKET_CONFIG;
    return { ...INITIAL_TICKET_CONFIG, ...parsed };
  });

  const [productionConfig, setProductionConfig] = useState<ProductionConfig>(() => {
    const saved = localStorage.getItem('aqua_production_config');
    return saved ? JSON.parse(saved) : { 
      backwashSequence: BACKWASH_SEQUENCE, 
      regenerationSequence: REGENERATION_SEQUENCE 
    };
  });

  const [cloudConfig, setCloudConfig] = useState<CloudConfig>(() => {
    const saved = localStorage.getItem('aqua_cloud_config');
    return saved ? JSON.parse(saved) : INITIAL_CLOUD_CONFIG;
  });

  const [sales, setSales] = useState<Sale[]>(() => {
    const saved = localStorage.getItem('aqua_sales');
    return saved ? JSON.parse(saved) : [];
  });

  const [invoices, setInvoices] = useState<Invoice[]>(() => {
    const saved = localStorage.getItem('aqua_invoices');
    return saved ? JSON.parse(saved) : [];
  });

  const [orders, setOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('aqua_orders');
    return saved ? JSON.parse(saved) : [];
  });

  const [employees, setEmployees] = useState<Employee[]>(() => {
    const saved = localStorage.getItem('aqua_employees');
    let initial = saved ? JSON.parse(saved) : [{ id: 'admin', name: 'Gerente General', roles: ['Administrador'], phone: '', pin: '1234', permissions: [...DEFAULT_PERMISSIONS] }];
    return initial.map((e: any) => ({ ...e, roles: e.roles || [e.role] }));
  });

  const [vehicles, setVehicles] = useState<Vehicle[]>(() => {
    const saved = localStorage.getItem('aqua_vehicles');
    const parsed = saved ? JSON.parse(saved) : [{ id: 'v1', plate: 'GEN-001', description: 'Unidad General', loadCapacity: 100, currentLoad: 0, inventory: [], fuelHistory: [] }];
    return parsed.map((v: any) => ({ ...v, inventory: v.inventory || [], fuelHistory: v.fuelHistory || [] }));
  });

  const [qualityRecords, setQualityRecords] = useState<QualityRecord[]>(() => {
    const saved = localStorage.getItem('aqua_quality');
    return saved ? JSON.parse(saved) : [];
  });

  const [tasks, setTasks] = useState<Task[]>(() => {
    const saved = localStorage.getItem('aqua_tasks');
    return saved ? JSON.parse(saved) : [];
  });

  const [attendance, setAttendance] = useState<Attendance[]>(() => {
    const saved = localStorage.getItem('aqua_attendance');
    return saved ? JSON.parse(saved) : [];
  });

  const [savedReports, setSavedReports] = useState<SavedReport[]>(() => {
    const saved = localStorage.getItem('aqua_saved_reports');
    return saved ? JSON.parse(saved) : [];
  });

  const [messages, setMessages] = useState<Message[]>(() => {
    const saved = localStorage.getItem('aqua_messages');
    return saved ? JSON.parse(saved) : [];
  });

  const [notifications, setNotifications] = useState<AppNotification[]>(() => {
    const saved = localStorage.getItem('aqua_notifications');
    return saved ? JSON.parse(saved) : [];
  });

  // --- PERSISTENCE ---
  useEffect(() => { localStorage.setItem('aqua_products', JSON.stringify(products)); }, [products]);
  useEffect(() => { localStorage.setItem('aqua_customers', JSON.stringify(customers)); }, [customers]);
  useEffect(() => { localStorage.setItem('aqua_sales', JSON.stringify(sales)); }, [sales]);
  useEffect(() => { localStorage.setItem('aqua_invoices', JSON.stringify(invoices)); }, [invoices]);
  useEffect(() => { localStorage.setItem('aqua_orders', JSON.stringify(orders)); }, [orders]);
  useEffect(() => { localStorage.setItem('aqua_employees', JSON.stringify(employees)); }, [employees]);
  useEffect(() => { localStorage.setItem('aqua_vehicles', JSON.stringify(vehicles)); }, [vehicles]);
  useEffect(() => { localStorage.setItem('aqua_ticket_config', JSON.stringify(ticketConfig)); }, [ticketConfig]);
  useEffect(() => { localStorage.setItem('aqua_production_config', JSON.stringify(productionConfig)); }, [productionConfig]);
  useEffect(() => { localStorage.setItem('aqua_quality', JSON.stringify(qualityRecords)); }, [qualityRecords]);
  useEffect(() => { localStorage.setItem('aqua_tasks', JSON.stringify(tasks)); }, [tasks]);
  useEffect(() => { localStorage.setItem('aqua_attendance', JSON.stringify(attendance)); }, [attendance]);
  useEffect(() => { localStorage.setItem('aqua_cloud_config', JSON.stringify(cloudConfig)); }, [cloudConfig]);
  useEffect(() => { localStorage.setItem('aqua_saved_reports', JSON.stringify(savedReports)); }, [savedReports]);
  useEffect(() => { localStorage.setItem('aqua_messages', JSON.stringify(messages)); }, [messages]);
  useEffect(() => { localStorage.setItem('aqua_notifications', JSON.stringify(notifications)); }, [notifications]);

  // --- SYNC ENGINE ---
  const performSync = useCallback(async (mode: 'push' | 'merge' = 'merge') => {
    if (!cloudConfig.url || !navigator.onLine) return;

    setIsSyncing(true);
    const endpoint = `${cloudConfig.url}aqua_data.json${cloudConfig.apiKey ? `?auth=${cloudConfig.apiKey}` : ''}`;

    try {
        let finalData: any = {
            products, customers, sales, orders, employees, vehicles, qualityRecords, tasks, attendance, savedReports, messages, invoices,
            ticketConfig, productionConfig,
            lastUpdated: Date.now(),
            deviceUser: deviceId
        };

        if (mode === 'merge') {
            // 1. Fetch Cloud Data
            const res = await fetch(endpoint);
            if (!res.ok) throw new Error("Fetch failed");
            const cloudData = await res.json() || {};

            // 2. Smart Merge All Collections
            finalData.products = smartMerge(products, cloudData.products);
            finalData.customers = smartMerge(customers, cloudData.customers);
            finalData.sales = smartMerge(sales, cloudData.sales);
            finalData.orders = smartMerge(orders, cloudData.orders);
            finalData.employees = smartMerge(employees, cloudData.employees);
            finalData.vehicles = smartMerge(vehicles, cloudData.vehicles);
            finalData.qualityRecords = smartMerge(qualityRecords, cloudData.qualityRecords);
            finalData.tasks = smartMerge(tasks, cloudData.tasks);
            finalData.attendance = smartMerge(attendance, cloudData.attendance);
            finalData.savedReports = smartMerge(savedReports, cloudData.savedReports);
            finalData.messages = smartMerge(messages, cloudData.messages);
            finalData.invoices = smartMerge(invoices, cloudData.invoices);

            // Configs (Last Write Wins Logic simplified)
            // If local config changed recently, keep it. Otherwise assume cloud might be newer.
            // For simplicity in this engine, we prefer local if we are active, but let's merge loosely.
            if(cloudData.ticketConfig) finalData.ticketConfig = { ...ticketConfig, ...cloudData.ticketConfig }; // Cloud overrides local partials?

            // 3. Update Local State with Merged Data
            setProducts(finalData.products);
            setCustomers(finalData.customers);
            setSales(finalData.sales);
            setOrders(finalData.orders);
            setEmployees(finalData.employees);
            setVehicles(finalData.vehicles);
            setQualityRecords(finalData.qualityRecords);
            setTasks(finalData.tasks);
            setAttendance(finalData.attendance);
            setSavedReports(finalData.savedReports);
            setMessages(finalData.messages);
            setInvoices(finalData.invoices);
        }

        // 4. Push Merged Data back to Cloud (Overwrite/PUT)
        await fetch(endpoint, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(finalData)
        });

        setSyncStatus('success');
        setLastSyncTime(Date.now());

    } catch (e) {
        console.error("Sync Error:", e);
        setSyncStatus('error');
    } finally {
        setIsSyncing(false);
    }
  }, [cloudConfig, deviceId, products, customers, sales, orders, employees, vehicles, qualityRecords, tasks, attendance, savedReports, messages, invoices, ticketConfig, productionConfig]);

  // --- AUTO SYNC INTERVAL ---
  useEffect(() => {
    if (cloudConfig.autoSync && cloudConfig.url) {
        // Initial Sync on Load
        performSync('merge');

        // Aggressive Interval (15s)
        const interval = setInterval(() => {
            if (!isSyncing) performSync('merge');
        }, 15000);
        return () => clearInterval(interval);
    }
  }, [cloudConfig.autoSync, cloudConfig.url]); // Depend only on config, internal state handled by refs/closures in functional updates if needed, but here simple interval works

  // --- ACTIONS WITH INSTANT SYNC TRIGGER ---
  // Wraps state updates and triggers a sync shortly after to propagate changes
  const triggerInstantSync = () => {
      if (cloudConfig.autoSync) {
          setTimeout(() => performSync('merge'), 500);
      }
  };

  const addSale = (customerId: string, items: CartItem[], total: number, paidAmount: number, splits: PaymentSplit[], returnedVacios: number, manualTimestamp?: number, vehicleId?: string) => {
    const timestamp = manualTimestamp || Date.now();
    const newSale: Sale = {
      id: `TKT-${timestamp.toString().slice(-6)}-${deviceId}`,
      timestamp, customerId, customerAlias: customers.find(c => c.id === customerId)?.alias || 'Anonimo',
      items, total, paidAmount, change: Math.max(0, paidAmount - total), paymentSplits: splits,
      emptyGarrafonsReturned: returnedVacios, synced: false, deviceId, invoiced: false
    };

    setSales(prev => [newSale, ...prev]);

    // Update Customer & Inventory logic...
    setCustomers(prev => prev.map(c => c.id === customerId ? { ...c, balance: (c.balance || 0) + (total - paidAmount), jugsOnLoan: Math.max(0, (c.jugsOnLoan || 0) + (items.filter(i => i.category==='Agua').reduce((a,b)=>a+b.quantity,0) - returnedVacios)), lastUpdated: Date.now() } : c));

    if (vehicleId && vehicleId !== 'plant') {
        setVehicles(prev => prev.map(v => v.id === vehicleId ? { ...v, inventory: v.inventory.map(i => { const sold = items.find(x => x.id === i.id); return sold ? { ...i, quantity: Math.max(0, i.quantity - sold.quantity) } : i }).filter(i => i.quantity > 0), currentLoad: v.inventory.reduce((a,b)=>a+b.quantity,0), lastUpdated: Date.now() } : v));
    } else {
        setProducts(prev => prev.map(p => { const sold = items.find(i => i.id === p.id); return sold ? { ...p, stock: p.stock - sold.quantity, lastUpdated: Date.now() } : p; }));
    }

    triggerInstantSync();
    return newSale;
  };

  const saveProduct = (p: Product) => {
      setProducts(prev => {
          const exists = prev.find(x => x.id === p.id);
          return exists ? prev.map(x => x.id === p.id ? { ...p, lastUpdated: Date.now() } : x) : [...prev, { ...p, lastUpdated: Date.now() }];
      });
      triggerInstantSync();
  };

  const saveCustomer = (c: Customer) => {
      setCustomers(prev => {
          const exists = prev.find(x => x.id === c.id);
          return exists ? prev.map(x => x.id === c.id ? { ...c, lastUpdated: Date.now() } : x) : [...prev, { ...c, lastUpdated: Date.now() }];
      });
      triggerInstantSync();
  };

  const addOrder = (o: Partial<Order>) => {
      const newOrder: Order = {
          id: `ORD-${Date.now().toString().slice(-6)}-${deviceId}`,
          timestamp: Date.now(), status: 'pendiente', priority: 1, items: [], total: 0, customerId: '', customerAlias: '', deviceId, lastUpdated: Date.now(), ...o
      } as Order;
      setOrders(prev => [newOrder, ...prev]);
      triggerInstantSync();
  };

  const updateOrder = (o: Order) => {
      setOrders(prev => prev.map(x => x.id === o.id ? { ...o, lastUpdated: Date.now() } : x));
      triggerInstantSync();
  };

  const saveEmployee = (e: Employee) => {
      setEmployees(prev => {
          const exists = prev.find(x => x.id === e.id);
          return exists ? prev.map(x => x.id === e.id ? { ...e, lastUpdated: Date.now() } : x) : [...prev, { ...e, lastUpdated: Date.now() }];
      });
      triggerInstantSync();
  };

  // ... (Other functions follow same pattern)

  // Explicit helper for sync module to use
  const syncData = (data: any) => {
      // Manual merge if called from elsewhere
      if(data) {
          // Apply manual data
          setMessages(prev => smartMerge(prev, data.messages || []));
          // ... apply others if needed
      }
      return true;
  };

  // Re-export full context
  return {
    deviceId, isSyncing, syncStatus, lastSyncTime, performSync,
    products, saveProduct, deleteProduct: (id) => { setProducts(prev => prev.filter(p => p.id !== id)); triggerInstantSync(); },
    customers, saveCustomer, deleteCustomer: (id) => { setCustomers(prev => prev.filter(c => c.id !== id)); triggerInstantSync(); }, importCustomers: (newC) => { setCustomers(prev => [...prev, ...newC.map(c => ({...c, lastUpdated: Date.now()}))]); triggerInstantSync(); },
    sales, addSale, resetSales: () => { setSales([]); setInvoices([]); triggerInstantSync(); },
    invoices, addInvoice: (inv) => { setInvoices(prev => [inv, ...prev]); triggerInstantSync(); },
    orders, setOrders, addOrder, updateOrder,
    employees, saveEmployee, deleteEmployee: (id) => { setEmployees(prev => prev.filter(e => e.id !== id)); triggerInstantSync(); },
    vehicles, setVehicles: (fn) => { setVehicles(fn); triggerInstantSync(); },
    loadVehicle: (vid, prod, delta) => { /* logic inside loadVehicle also needs to trigger sync, simplified here */ triggerInstantSync(); }, // Needs full implementation inside hook to work with trigger
    addFuelRecord: (vid, rec) => { setVehicles(prev => prev.map(v => v.id === vid ? { ...v, fuelHistory: [rec, ...v.fuelHistory], lastUpdated: Date.now() } : v)); triggerInstantSync(); },
    tasks, addTask: (t) => { setTasks(prev => [...prev, { ...t, id: t.id || `TSK-${Date.now()}`, lastUpdated: Date.now() } as Task]); triggerInstantSync(); },
    addTasks: (ts) => { setTasks(prev => [...ts.map(t => ({...t, lastUpdated: Date.now()} as Task)), ...prev]); triggerInstantSync(); },
    updateTask: (t) => { setTasks(prev => prev.map(x => x.id === t.id ? { ...t, lastUpdated: Date.now() } : x)); triggerInstantSync(); },
    updateTaskStatus: (id, s) => { setTasks(prev => prev.map(x => x.id === id ? { ...x, status: s, lastUpdated: Date.now() } : x)); triggerInstantSync(); },
    deleteTask: (id) => { setTasks(prev => prev.filter(t => t.id !== id)); triggerInstantSync(); },
    clearTasksByDate: (d) => { setTasks(prev => prev.filter(t => t.date !== d)); triggerInstantSync(); },
    attendance, recordAttendance: (eid, s) => { setAttendance(prev => [{ id: `ATT-${Date.now()}`, employeeId: eid, status: s, date: new Date().toISOString().split('T')[0], timestamp: Date.now() }, ...prev]); triggerInstantSync(); },
    qualityRecords, addQualityRecord: (r) => { setQualityRecords(prev => [{ ...r, id: `QUAL-${Date.now()}`, timestamp: Date.now() } as QualityRecord, ...prev]); triggerInstantSync(); },
    ticketConfig, setTicketConfig: (c) => { setTicketConfig(c); triggerInstantSync(); },
    productionConfig, setProductionConfig: (c) => { setProductionConfig(c); triggerInstantSync(); },
    cloudConfig, setCloudConfig,
    syncData,
    savedReports, addSavedReport: (r) => { setSavedReports(prev => [r, ...prev]); triggerInstantSync(); }, deleteSavedReport: (id) => { setSavedReports(prev => prev.filter(r => r.id !== id)); triggerInstantSync(); },
    messages, sendMessage: (txt, sid, rid) => { setMessages(prev => [...prev, { id: `MSG-${Date.now()}`, text: txt, senderId: sid, receiverId: rid, timestamp: Date.now(), read: false }]); triggerInstantSync(); },
    notifications, addNotification: (n) => { setNotifications(prev => [{ ...n, id: `NOT-${Date.now()}`, timestamp: Date.now(), read: false }, ...prev]); }, // Notifications are local mostly
    markNotificationRead: (id) => setNotifications(prev => prev.map(n => n.id === id ? { ...n, read: true } : n)),
    deleteNotification: (id) => setNotifications(prev => prev.filter(n => n.id !== id)),
    clearAllNotifications: () => setNotifications([])
  };
};

const ERPContext = createContext<ReturnType<typeof useERPFactory> | null>(null);

export const ERPProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const data = useERPFactory();
  return <ERPContext.Provider value={data}>{children}</ERPContext.Provider>;
};

export const useERPDataHook = () => {
  const context = useContext(ERPContext);
  if (!context) throw new Error("useERPData must be used within ERPProvider");
  return context;
};

import React, { useState } from 'react';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, ActionButton } from './ui/Cards';

interface SyncModuleProps {
  onBack: () => void;
  onScanRequest: () => void;
  scannedId?: string;
}

export const SyncModule: React.FC<SyncModuleProps> = ({ onBack }) => {
  const { 
    cloudConfig, setCloudConfig, performSync, isSyncing, syncStatus, lastSyncTime
  } = useERPData();

