             <div className="flex items-center gap-3 mb-4">
                <div className="w-12 h-12 bg-amber-100 rounded-2xl flex items-center justify-center text-amber-500 text-2xl">
                    <i className="fas fa-fire"></i>
                </div>
                <div>
                    <h3 className="font-black text-sky-900 leading-none">Firebase</h3>
                    <p className="text-[10px] font-bold text-sky-300 uppercase">Realtime Database</p>
                </div>
             </div>

             <div className="space-y-4">
               <div>
                 <label className="text-[10px] font-black uppercase text-sky-400 ml-2">URL del Proyecto</label>
                 <input 
                   type="url" 
                   placeholder="https://..." 
                   className="w-full bg-slate-50 p-4 rounded-2xl outline-none font-bold text-sky-900 text-xs focus:ring-2 ring-indigo-300 transition-all"
                   value={tempConfig.url}
                   onChange={e => setTempConfig({...tempConfig, url: e.target.value})}
                 />
               </div>

               <div>
                 <label className="text-[10px] font-black uppercase text-sky-400 ml-2">Auth Secret (Opcional)</label>
                 <input 
                   type="password" 
                   placeholder="Token..." 
                   className="w-full bg-slate-50 p-4 rounded-2xl outline-none font-bold text-sky-900 text-xs focus:ring-2 ring-indigo-300 transition-all"
                   value={tempConfig.apiKey}
                   onChange={e => setTempConfig({...tempConfig, apiKey: e.target.value})}
                 />
               </div>

               <div className="flex items-center gap-3 bg-indigo-50 p-4 rounded-2xl cursor-pointer" onClick={() => setTempConfig({...tempConfig, autoSync: !tempConfig.autoSync})}>
                 <div className={`w-10 h-6 rounded-full p-1 transition-colors ${tempConfig.autoSync ? 'bg-indigo-500' : 'bg-slate-300'}`}>
                   <div className={`w-4 h-4 bg-white rounded-full shadow-sm transition-transform ${tempConfig.autoSync ? 'translate-x-4' : ''}`}></div>
                 </div>
                 <span className="text-[10px] font-black text-indigo-900 uppercase">Sincronización Automática (15s)</span>
               </div>
             </div>
          </div>
          <ActionButton onClick={handleSaveConfig}>Guardar Conexión</ActionButton>
        </div>
