          <button onClick={onBack} className="w-12 h-12 bg-white/10 rounded-2xl flex items-center justify-center active:scale-90 transition-transform">
            <i className="fas fa-arrow-left"></i>
          </button>
          <div>
            <h2 className="text-xl font-black tracking-tight">Aqua Cloud</h2>
            <div className="flex items-center gap-2">
               <div className={`w-2 h-2 rounded-full ${cloudConfig.url ? 'bg-emerald-400' : 'bg-red-500'}`}></div>
               <span className="text-[10px] font-bold uppercase opacity-70">
                 {cloudConfig.url ? (cloudConfig.autoSync ? 'Auto-Sync Activo' : 'Manual') : 'Desconectado'}
               </span>
            </div>
          </div>
        </div>
        <button onClick={() => setEditingConfig(true)} className="w-10 h-10 bg-white/10 rounded-xl flex items-center justify-center text-sm active:bg-white/20">
          <i className="fas fa-gear"></i>
        </button>
      </div>

      <div className="flex-1 flex flex-col items-center justify-center px-6 pb-20">

        {/* BIG STATUS INDICATOR */}
        <div className="relative mb-10">
           <div className={`absolute inset-0 bg-indigo-500 rounded-full blur-[60px] opacity-20 transition-all ${isSyncing ? 'scale-150 opacity-40' : ''}`}></div>

           <div className={`w-40 h-40 rounded-full flex items-center justify-center text-6xl shadow-2xl relative z-10 border-4 border-slate-800 transition-all duration-500 ${isSyncing ? 'bg-indigo-600 animate-pulse border-indigo-400' : syncStatus === 'error' ? 'bg-rose-600 border-rose-400' : 'bg-emerald-500 border-emerald-400'}`}>
              <i className={`fas ${isSyncing ? 'fa-arrows-rotate animate-spin' : syncStatus === 'error' ? 'fa-triangle-exclamation' : 'fa-check'}`}></i>
           </div>
        </div>

        <h3 className="text-2xl font-black mb-2 text-center">
            {isSyncing ? 'Sincronizando...' : syncStatus === 'error' ? 'Error de Conexión' : 'Todo Actualizado'}
        </h3>
        <p className="text-xs text-slate-400 font-bold mb-8 text-center uppercase tracking-widest">
            {lastSyncTime ? `Última sincronización: ${new Date(lastSyncTime).toLocaleTimeString()}` : 'Esperando primera conexión...'}
        </p>

        <div className="w-full space-y-3">
           <button 
             onClick={() => performSync('merge')}
             disabled={isSyncing}
             className="w-full bg-indigo-600 text-white py-5 rounded-[2rem] font-black uppercase text-xs tracking-widest shadow-xl shadow-indigo-500/20 active:scale-[0.98] transition-all disabled:opacity-50 disabled:grayscale flex items-center justify-center gap-3"
           >
             <i className="fas fa-cloud-arrow-up"></i> Forzar Sincronización
           </button>

           <div className="bg-white/5 p-4 rounded-2xl text-[9px] text-slate-400 text-center leading-relaxed">
              El sistema se sincroniza automáticamente cada 15 segundos y después de cada cambio importante (ventas, clientes, inventario).
           </div>
        </div>

      </div>
    </div>
  );
};

export type ViewType = 'dashboard' | 'pos' | 'orders' | 'logistics' | 'production' | 'sync' | 'whatsapp' | 'customers' | 'employees' | 'reports' | 'settings' | 'quality' | 'scanner' | 'inventory' | 'tickets' | 'supplies' | 'messages' | 'notifications' | 'billing' | 'fuel';

export type Role = 'Administrador' | 'Repartidor' | 'Planta';

export type GarrafonType = 'Aqua' | 'Bonafont' | 'Ciel' | 'E-Pura' | 'Generico';

export interface Product {
  id: string;
  name: string;
  price: number;
  stock: number;
  category: 'Agua' | 'Accesorios' | 'Insumos';
  lastUpdated?: number;
  satCode?: string;
  unitCode?: string;
}

export interface CartItem extends Product {
  quantity: number;
}

export interface TaxProfile {
  rfc: string;
  razonSocial: string;
  regimenFiscal: string;
  codigoPostal: string;
  usoCFDI: string;
  email: string;
}

export interface Customer {
  id: string;
  name: string;
  alias: string;
  phone: string;
  address: string;
  balance: number;
  specialPrice?: number;
  garrafonType?: GarrafonType;
  jugsOnLoan?: number;
  lat?: number;
  lng?: number;
  lastUpdated?: number;
  taxInfo?: TaxProfile;
}

export interface PaymentSplit {
  method: 'Efectivo' | 'Transferencia' | 'Tarjeta';
  amount: number;
}

export interface Sale {
  id: string;
  timestamp: number;
  customerId: string;
  customerAlias: string;
  items: CartItem[];
  total: number;
  paidAmount: number;
