          paymentSplits: [],
          emptyGarrafonsReturned: 0,
          synced: true,
          invoiced: true
      };

      const invoiceConfig = {
          ...ticketConfig,
          footerMessage: `UUID: ${inv.uuid}`,
          extraNote: 'Este documento es una representación impresa de un CFDI.'
      };

      return await generateTicketPDF(mockSale, invoiceConfig);
  };

  // --- DOWNLOAD HANDLERS ---
  const handleDownloadInvoiceXML = (inv: Invoice) => {
      const xml = generateXMLContent(inv);
      downloadFile(xml, `Factura_${inv.internalId}.xml`, 'text/xml');
  };

  const handleDownloadInvoicePDF = async (inv: Invoice) => {
      try {
          const pdfBytes = await generatePDFBytes(inv);
          await downloadFile(pdfBytes, `Factura_${inv.internalId}.pdf`, 'application/pdf');
      } catch (e) {
          console.error(e);
          alert("Error generando representación PDF");
      }
